<template>
  <div
    class="sr-page page"
    :class="[
      { 'theme-light-blue': uiTheme === 'light', 'mode-craft': srDataMode === 'craft', 'is-mobile-shell': isMobileShell },
      isMobileShell ? 'm-tab-' + mobileActiveTab : ''
    ]"
  >
    <!-- Minimal Page Identity Header (chuẩn reportFIREBASE.vue) -->
    <header class="bg-topbar">
      <div class="bg-topbar-left">
        <div class="bg-brand-icon">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
            <path d="M3 3v18h18"/>
            <path d="M18 17V9"/>
            <path d="M13 17V5"/>
            <path d="M8 17v-3"/>
          </svg>
        </div>
        <div class="bg-title-wrap">
          <div class="bg-title-row">
            <h1 class="bg-title">Quản Lý Sale Report</h1>
            <span v-if="!isMobileShell" class="bg-count-pill" :class="{ 'is-craft-pill': srDataMode === 'craft' }">
              {{ filteredRows.length }} / {{ rows.length }} {{ srDataMode === 'craft' ? 'Phương án tạm' : 'PO' }}
            </span>
          </div>
          <p v-if="false" class="bg-subtitle">Theo dõi doanh số bán, lợi nhuận COM / Margin, chứng từ PO &amp; tiến độ thu hồi công nợ</p>
        </div>
      </div>
      <div v-if="false" class="bg-topbar-right">
        <!-- Segmented Mode Switcher đã chuyển xuống thanh công cụ chính để tránh trùng lặp -->
      </div>
    </header>

    <!-- Thanh chuyển chế độ Segmented Capsule 50/50 dành riêng cho Mobile (Phương án A - Không Emoji) -->
    <div v-if="isMobileShell" class="sr-mob-mode-switcher-bar">
      <div class="sr-ctt-mode-switcher is-mobile-full" role="tablist" aria-label="Chế độ dữ liệu Sale Report">
        <button
          type="button"
          class="sr-ctt-mode-btn is-official"
          :class="{ active: srDataMode === 'official' }"
          @click.stop="switchSrDataMode('official')"
          title="Chế độ Bản Chính Thức (Đã chốt deal)"
        >
          <svg class="sr-ctt-mode-icon" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/><polyline points="9 12 11 14 15 10"/></svg>
          <span class="sr-ctt-mode-label">Bản Chính Thức</span>
          <span class="sr-ctt-mode-count">{{ officialRows.length }}</span>
        </button>
        <button
          type="button"
          class="sr-ctt-mode-btn is-craft"
          :class="{ active: srDataMode === 'craft' }"
          @click.stop="switchSrDataMode('craft')"
          title="Chế độ Phương Án Tạm (So sánh trước khi chốt deal)"
        >
          <svg class="sr-ctt-mode-icon" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><polygon points="12 2 2 7 12 12 22 7 12 2"/><polyline points="2 17 12 22 22 17"/><polyline points="2 12 12 17 22 12"/></svg>
          <span class="sr-ctt-mode-label">Phương Án Tạm</span>
          <span class="sr-ctt-mode-count">{{ craftRows.length }}</span>
        </button>
      </div>
    </div>

    <input type="file" ref="reportUploadInput" accept=".xlsx, .xls" multiple style="display: none" @change="onReportFilesSelected" />

    <!-- Modal Chọn Phương Thức Thêm Mới (Đồng bộ chuẩn Bento của trang) -->
    <Teleport to="body">
      <div
        v-if="showAddChoiceModal"
        class="sr-modal-overlay"
        :class="{ 'theme-light-blue': uiTheme === 'light' }"
        @click.self="showAddChoiceModal = false"
        style="z-index: 10050;"
      >
        <div class="sr-add-choice-modal" :class="{ 'is-light': uiTheme === 'light' }">
          <!-- Bento Header đồng bộ .bg-filter-head / .sr-action-deck-header -->
          <div class="sr-add-choice-header">
            <div class="sr-add-choice-header-left">
              <span class="sr-add-choice-header-icon">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
              </span>
              <div class="sr-add-choice-title-wrap">
                <div class="sr-add-choice-title-row">
                  <h3 class="sr-add-choice-title">Thêm mới dữ liệu Sale Report</h3>
                  <span class="sr-add-choice-badge">4 PHƯƠNG THỨC</span>
                </div>
                <p class="sr-add-choice-sub">Chọn phương thức khởi tạo đơn hàng PO mới hoặc trích xuất tự động từ chứng từ</p>
              </div>
            </div>
            <button type="button" class="sr-add-choice-close" @click="showAddChoiceModal = false" title="Đóng cửa sổ">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
            </button>
          </div>

          <!-- 4 Bento Option Cards -->
          <div class="sr-add-choice-grid">
            <button type="button" class="sr-choice-card is-primary" @click="handleCreateBlankPO()">
              <span class="sr-choice-icon is-emerald">
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
              </span>
              <div class="sr-choice-body">
                <div class="sr-choice-head">
                  <strong class="sr-choice-title">Thêm mới hoàn toàn</strong>
                  <span class="sr-choice-tag is-emerald">Nhập trực tiếp</span>
                </div>
                <p class="sr-choice-desc">Mở form PO trống để tự nhập thông tin khách hàng, chỉ số tài chính, bảng hàng hóa và đính kèm file</p>
              </div>
              <span class="sr-choice-arrow">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"/></svg>
              </span>
            </button>

            <button type="button" class="sr-choice-card is-blue" @click="handleChoiceImportBaoGia()">
              <span class="sr-choice-icon is-blue">
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg>
              </span>
              <div class="sr-choice-body">
                <div class="sr-choice-head">
                  <strong class="sr-choice-title">Import Báo giá</strong>
                  <span class="sr-choice-tag is-blue">Excel / PDF</span>
                </div>
                <p class="sr-choice-desc">Chọn 1 hoặc nhiều file Báo giá để tự động bóc tách doanh số, khách hàng và bảng hàng hóa</p>
              </div>
              <span class="sr-choice-arrow">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"/></svg>
              </span>
            </button>

            <button type="button" class="sr-choice-card is-amber" @click="handleChoiceImportDxmh()">
              <span class="sr-choice-icon is-amber">
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M16 4h2a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2h2"/><rect x="8" y="2" width="8" height="4" rx="1" ry="1"/></svg>
              </span>
              <div class="sr-choice-body">
                <div class="sr-choice-head">
                  <strong class="sr-choice-title">Import DXMH</strong>
                  <span class="sr-choice-tag is-amber">File Đề xuất MH</span>
                </div>
                <p class="sr-choice-desc">Chọn file Đề xuất mua hàng để trích xuất tự động số PO, công ty, người nhận và MST</p>
              </div>
              <span class="sr-choice-arrow">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"/></svg>
              </span>
            </button>

            <button type="button" class="sr-choice-card is-purple" @click="handleChoiceImportReport()">
              <span class="sr-choice-icon is-purple">
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>
              </span>
              <div class="sr-choice-body">
                <div class="sr-choice-head">
                  <strong class="sr-choice-title">Import Report</strong>
                  <span class="sr-choice-tag is-purple">Hàng loạt theo năm</span>
                </div>
                <p class="sr-choice-desc">Nạp danh sách nhiều PO cùng lúc từ file Excel Sale Report tổng hợp theo năm báo cáo</p>
              </div>
              <span class="sr-choice-arrow">
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"/></svg>
              </span>
            </button>
          </div>

          <div class="sr-add-choice-footer">
            <span class="sr-add-choice-hint">Mẹo: Bạn có thể đính kèm thêm Báo giá, Mua hàng, DXMH và Ảnh chứng từ ngay bên trong form PO.</span>
            <button type="button" class="sr-add-choice-cancel" @click="showAddChoiceModal = false">Đóng</button>
          </div>
        </div>
      </div>
    </Teleport>

    <!-- Top Summary Dashboard: Phương án A — 4 Card Phẳng (Chỉ hiện ở Bản Chính Thức, ẩn ở Bản Tạm) -->
    <div class="sr-top-summary" v-if="srDataMode !== 'craft' && !loading && filteredRows.length > 0 && (isMobileShell ? (mobileActiveTab === 'overview' && !isKpiCollapsed) : !isKpiCollapsed)">
      <div class="sr-super-bento-grid">
        <!-- CARD 1: Doanh số bán | Net PO | Tổng tiền sau VAT -->
        <article class="sr-sb-card sb-card-revenue">
          <div class="sr-sb-head">
            <div class="sr-sb-title-cluster">
              <span class="sr-sb-icon is-blue">
                <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/></svg>
              </span>
              <h3 class="sr-sb-title">Doanh số bán</h3>
            </div>
            <div class="sr-sb-quick-acts">
              <button type="button" class="sr-sb-act-pill" @click.stop="openChart('doanhSoBan')" title="Mở bảng phân tích Doanh số bán">
                <svg class="sr-sb-act-svg" width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><path d="M3 3v18h18"/><path d="M18 17V9"/><path d="M13 17V5"/><path d="M8 17v-3"/></svg><span class="sr-sb-act-text">Xem phân tích</span>
              </button>
            </div>
          </div>

          <div class="sr-sb-main" @click="openChart('doanhSoBan')" title="Click xem biểu đồ Doanh số bán">
            <div class="sr-sb-hero-val money-white">
              {{ fmt(sumCol('doanhSoBan')) }}
              <span class="sr-sb-unit">VND</span>
            </div>
            <span v-if="getTrendData(sumCol('doanhSoBan'), sumColPrev('doanhSoBan'))" class="sr-sb-trend" :class="getTrendData(sumCol('doanhSoBan'), sumColPrev('doanhSoBan'))?.state">
              {{ getTrendData(sumCol('doanhSoBan'), sumColPrev('doanhSoBan'))?.text }}
            </span>
          </div>

          <div class="sr-sb-foot">
            <div class="sr-sb-foot-row" @click="openChart('netPO')" title="Click xem biểu đồ Net PO">
              <span class="sr-sb-foot-label">Net PO</span>
              <strong class="sr-sb-foot-val money-blue">{{ fmt(sumCol('netPO')) }} <small>đ</small></strong>
            </div>
            <div class="sr-sb-foot-row" @click="openChart('tongSauVat')" title="Click xem biểu đồ Tổng tiền sau VAT">
              <span class="sr-sb-foot-label">Tổng tiền sau VAT</span>
              <strong class="sr-sb-foot-val money-blue">{{ fmt(sumCol('tongSauVat')) }} <small>đ</small></strong>
            </div>
          </div>
        </article>

        <!-- CARD 2: Net COM | Gross COM | Net Com / Net PO | Net Com / DSB -->
        <article class="sr-sb-card sb-card-com">
          <div class="sr-sb-head">
            <div class="sr-sb-title-cluster">
              <span class="sr-sb-icon is-emerald">
                <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>
              </span>
              <h3 class="sr-sb-title">Net COM</h3>
            </div>
            <div class="sr-sb-quick-acts">
              <button type="button" class="sr-sb-act-pill" @click.stop="openChart('netCom')" title="Mở bảng phân tích Net COM">
                <svg class="sr-sb-act-svg" width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><path d="M3 3v18h18"/><path d="M18 17V9"/><path d="M13 17V5"/><path d="M8 17v-3"/></svg><span class="sr-sb-act-text">Xem phân tích</span>
              </button>
            </div>
          </div>

          <div class="sr-sb-main" @click="openChart('netCom')" title="Click xem biểu đồ Net COM">
            <div class="sr-sb-hero-val money-green">
              {{ fmt(sumCol('netCom')) }}
              <span class="sr-sb-unit">VND</span>
            </div>
            <span v-if="getTrendData(sumCol('netCom'), sumColPrev('netCom'))" class="sr-sb-trend" :class="getTrendData(sumCol('netCom'), sumColPrev('netCom'))?.state">
              {{ getTrendData(sumCol('netCom'), sumColPrev('netCom'))?.text }}
            </span>
          </div>

          <div class="sr-sb-foot">
            <div class="sr-sb-foot-row" @click="openChart('grossCom')" title="Click xem biểu đồ Gross COM">
              <span class="sr-sb-foot-label">Gross COM</span>
              <strong class="sr-sb-foot-val money-blue">{{ fmt(sumCol('grossCom')) }} <small>đ</small></strong>
            </div>
            <div class="sr-sb-foot-row" @click="openChart('totalNetComPct', true)" title="Click xem biểu đồ Net Com / Net PO">
              <span class="sr-sb-foot-label">Net Com / Net PO</span>
              <strong class="sr-sb-foot-val money-green">{{ pctFmt(totalNetComPct) }}</strong>
            </div>
            <div class="sr-sb-foot-row" @click="openChart('totalNetComDsbPct', true)" title="Click xem biểu đồ Net Com / DSB">
              <span class="sr-sb-foot-label">Net Com / DSB</span>
              <strong class="sr-sb-foot-val money-green">{{ pctFmt(totalNetComDsbPct) }}</strong>
            </div>
          </div>
        </article>

        <!-- CARD 3: Net Margin | Net Margin / Net PO | Net Margin / DSB -->
        <article class="sr-sb-card sb-card-margin">
          <div class="sr-sb-head">
            <div class="sr-sb-title-cluster">
              <span class="sr-sb-icon" :class="sumCol('netMargin') >= 0 ? 'is-emerald' : 'is-red'">
                <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 3v18h18"/><path d="M18.7 8l-5.1 5.2-2.8-2.7L7 14.3"/></svg>
              </span>
              <h3 class="sr-sb-title">Net Margin</h3>
            </div>
            <div class="sr-sb-quick-acts">
              <button type="button" class="sr-sb-act-pill" @click.stop="openChart('netMargin')" title="Mở bảng phân tích Net Margin">
                <svg class="sr-sb-act-svg" width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><path d="M3 3v18h18"/><path d="M18 17V9"/><path d="M13 17V5"/><path d="M8 17v-3"/></svg><span class="sr-sb-act-text">Xem phân tích</span>
              </button>
            </div>
          </div>

          <div class="sr-sb-main" @click="openChart('netMargin')" title="Click xem biểu đồ Net Margin">
            <div class="sr-sb-hero-val" :class="sumCol('netMargin') >= 0 ? 'money-green' : 'money-red'">
              {{ fmt(sumCol('netMargin')) }}
              <span class="sr-sb-unit">VND</span>
            </div>
            <span v-if="getTrendData(sumCol('netMargin'), sumColPrev('netMargin'))" class="sr-sb-trend" :class="getTrendData(sumCol('netMargin'), sumColPrev('netMargin'))?.state">
              {{ getTrendData(sumCol('netMargin'), sumColPrev('netMargin'))?.text }}
            </span>
          </div>

          <div class="sr-sb-foot">
            <div class="sr-sb-foot-row" @click="openChart('totalNetMarginPct', true)" title="Click xem biểu đồ Net Margin / Net PO">
              <span class="sr-sb-foot-label">Net Margin / Net PO</span>
              <strong class="sr-sb-foot-val" :class="totalNetMarginPct >= 0 ? 'money-green' : 'money-red'">{{ pctFmt(totalNetMarginPct) }}</strong>
            </div>
            <div class="sr-sb-foot-row" @click="openChart('totalNetMarginDsbPct', true)" title="Click xem biểu đồ Net Margin / DSB">
              <span class="sr-sb-foot-label">Net Margin / DSB</span>
              <strong class="sr-sb-foot-val" :class="totalNetMarginDsbPct >= 0 ? 'money-blue' : 'money-red'">{{ pctFmt(totalNetMarginDsbPct) }}</strong>
            </div>
          </div>
        </article>

        <!-- CARD 4: Công nợ còn lại | Khách đã thanh toán -->
        <article class="sr-sb-card sb-card-debt">
          <div class="sr-sb-head">
            <div class="sr-sb-title-cluster">
              <span class="sr-sb-icon" :class="sumCol('congNo') > 0 ? 'is-red' : 'is-emerald'">
                <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>
              </span>
              <h3 class="sr-sb-title">Công nợ còn lại</h3>
            </div>
            <div class="sr-sb-quick-acts">
              <button type="button" class="sr-sb-act-pill" @click.stop="openChart('congNo')" title="Mở bảng phân tích Công nợ còn lại">
                <svg class="sr-sb-act-svg" width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><path d="M3 3v18h18"/><path d="M18 17V9"/><path d="M13 17V5"/><path d="M8 17v-3"/></svg><span class="sr-sb-act-text">Xem phân tích</span>
              </button>
            </div>
          </div>

          <div class="sr-sb-main" @click="openChart('congNo')" title="Click xem biểu đồ Công nợ còn lại">
            <div class="sr-sb-hero-val" :class="sumCol('congNo') > 0 ? 'money-red' : 'money-green'">
              {{ fmt(sumCol('congNo')) }}
              <span class="sr-sb-unit">VND</span>
            </div>
            <button
              type="button"
              class="sr-sb-po-badge"
              :class="unpaidPoCount > 0 ? 'is-red' : 'is-emerald'"
              @click.stop="filterDebtStatus = filterDebtStatus === 'Còn công nợ' ? 'Tất cả' : 'Còn công nợ'"
              title="Click để lọc nhanh các PO đang nợ"
            >
              {{ unpaidPoCount }}/{{ filteredRows.length }} PO nợ
            </button>
          </div>

          <div class="sr-sb-foot">
            <div class="sr-sb-foot-row" @click="openChart('daThanhToan')" title="Click xem biểu đồ Khách đã thanh toán">
              <span class="sr-sb-foot-label">Khách đã thanh toán</span>
              <strong class="sr-sb-foot-val money-green">{{ fmt(sumCol('daThanhToan')) }} <small>đ</small></strong>
            </div>
            <div
              class="sr-sb-foot-row"
              @click="filterDebtStatus = overduePoCount > 0 ? (filterDebtStatus === 'Quá hạn thanh toán' ? 'Tất cả' : 'Quá hạn thanh toán') : (filterDebtStatus === 'Còn công nợ' ? 'Tất cả' : 'Còn công nợ')"
              title="Click để lọc đơn quá hạn / còn nợ"
            >
              <span class="sr-sb-foot-label">
                Khách đã thanh toán / Tổng tiền sau VAT
                <span v-if="overduePoCount > 0" class="sr-sb-overdue-inline">({{ overduePoCount }} quá hạn)</span>
              </span>
              <strong class="sr-sb-foot-val money-blue">{{ sumCol('tongSauVat') > 0 ? pctFmt((sumCol('daThanhToan') / sumCol('tongSauVat')) * 100) : '0%' }}</strong>
            </div>
          </div>

          <div class="sr-sb-bottom-progress" aria-hidden="true">
            <div
              class="sr-sb-bottom-progress-fill"
              :style="{ width: (sumCol('tongSauVat') > 0 ? Math.min(100, Math.max(0, (sumCol('daThanhToan') / sumCol('tongSauVat')) * 100)) : 0) + '%' }"
            ></div>
          </div>
        </article>
      </div>
    </div>

    <!-- Không gian Quản lý Đơn hàng (Tỉ lệ 3:7 — Cột trái Danh sách công ty & Bộ lọc | Cột phải Header File Folder + Tác vụ/Thiết lập + Card PO) -->
    <div class="sr-groups-container" v-if="!loading">
      <!-- Khung Bố Cục Chính (Master-Detail Tỉ lệ 3:7 hoặc Danh Sách Dọc) -->
      <div class="sr-workspace-layout" :class="{ 'is-master-detail': layoutViewMode === 'master-detail' }">
        <!-- CỘT TRÁI (30%): DANH SÁCH CÔNG TY + TÌM KIẾM & BỘ LỌC TÍCH HỢP -->
        <aside
          v-show="!isMobileShell || mobileActiveTab === 'overview'"
          class="sr-md-sidebar"
          :class="{ 'is-stacked-filter-bar': isMobileShell || layoutViewMode === 'stacked-groups' }"
        >
          <div class="sr-md-sidebar-head">
            <!-- Dòng 1: Tiêu đề Danh sách công ty + Cụm nút Đặt lại / Bộ lọc / Làm mới -->
            <div class="sr-md-sh-top">
              <div class="sr-md-sh-title-group">
                <span class="sr-md-sh-title">Danh sách công ty</span>
                <span class="sr-md-sh-plain-count">({{ filteredSidebarGroups.length }}/{{ allGroupedFilteredRows.length }} Cty • {{ filteredRows.length }} PO)</span>
              </div>

              <div class="sr-md-sh-actions">
                <button
                  v-if="activeSaleFilterCount > 0"
                  type="button"
                  class="sr-sb-head-btn is-reset"
                  @click="resetAllSaleFilters"
                  title="Xoá toàn bộ điều kiện lọc"
                >
                  <span>Đặt lại ({{ activeSaleFilterCount }})</span>
                </button>

                <button
                  type="button"
                  class="sr-sb-head-btn is-filter-toggle"
                  :class="{ active: isSidebarFilterExpanded || activeSaleFilterCount > 0 }"
                  @click="isSidebarFilterExpanded = !isSidebarFilterExpanded"
                  title="Đóng/Mở bộ lọc chi tiết"
                >
                  <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polygon points="22 3 2 3 10 12.46 10 19 14 21 14 12.46 22 3"/></svg>
                  <span>Bộ lọc</span>
                  <span v-if="activeSaleFilterCount > 0" class="sr-sb-filter-count">{{ activeSaleFilterCount }}</span>
                </button>

                <button
                  type="button"
                  class="sr-sb-head-btn"
                  @click="loadData"
                  :disabled="loading"
                  title="Tải lại dữ liệu từ hệ thống"
                >
                  <svg :class="{ spin: loading }" width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="23 4 23 10 17 10"/><polyline points="1 20 1 14 7 14"/><path d="M3.51 9a9 9 0 0 1 14.85-3.36L23 10M1 14l4.64 4.36A9 9 0 0 0 20.49 15"/></svg>
                </button>
              </div>
            </div>

            <!-- Dòng 2: Thanh tìm kiếm hợp nhất (Tìm công ty, mã KH, MST, số PO, nội dung HĐ) -->
            <div class="bg-search-shell sr-sidebar-search-shell">
              <svg class="bg-search-icon" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
              <input
                v-model="searchStr"
                type="text"
                @focus="onSearchInputFocus"
                @blur="onSearchInputBlur"
                @keydown.enter="onSearchEnter"
                placeholder="Tìm tên công ty, mã KH, MST, số PO, nội dung HĐ..."
              />
              <button v-if="searchStr" type="button" class="bg-search-clear" @click="searchStr = ''" title="Xoá từ khoá">&times;</button>

              <!-- Dropdown Lịch sử tìm kiếm gần đây -->
              <transition name="sr-fade">
                <div v-if="isSearchFocused && !searchStr && recentSaleSearches.length > 0" class="bg-recent-dropdown" @mousedown.prevent>
                  <div class="bg-recent-head">
                    <span class="bg-recent-title">
                      <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
                      Tìm kiếm gần đây
                    </span>
                    <button type="button" class="bg-recent-clear-all" @click.stop="clearAllRecentSaleSearches">Xoá lịch sử</button>
                  </div>
                  <div class="bg-recent-chips">
                    <div
                      v-for="item in recentSaleSearches"
                      :key="item"
                      class="bg-recent-chip"
                      @click="selectRecentSaleSearch(item)"
                    >
                      <span class="bg-recent-chip-text">{{ item }}</span>
                      <button type="button" class="bg-recent-chip-del" @click.stop="removeRecentSaleSearch(item)" title="Xoá mục này">&times;</button>
                    </div>
                  </div>
                </div>
              </transition>
            </div>

            <!-- Dòng 3: Khối Bộ lọc tích hợp ngay trong phần Danh sách công ty -->
            <div v-show="isSidebarFilterExpanded" class="sr-sidebar-filter-panel">
              <!-- Lọc Thời gian -->
              <div class="sr-sb-time-block">
                <div class="sr-sb-time-top">
                  <div class="bg-seg-group sr-sb-seg-group is-full-width">
                    <button type="button" class="bg-seg-btn" :class="{ active: timeFilterMode === 'all' }" @click="timeFilterMode = 'all'">Tất cả</button>
                    <button type="button" class="bg-seg-btn" :class="{ active: timeFilterMode === 'day' }" @click="timeFilterMode = 'day'">Ngày</button>
                    <button type="button" class="bg-seg-btn" :class="{ active: timeFilterMode === 'month' }" @click="timeFilterMode = 'month'">Tháng</button>
                    <button type="button" class="bg-seg-btn" :class="{ active: timeFilterMode === 'year' }" @click="timeFilterMode = 'year'">Năm</button>
                  </div>
                </div>

                <div v-if="timeFilterMode !== 'all'" class="sr-sb-time-range-row">
                  <button type="button" class="bg-period-step-btn" @click="shiftSalePeriod(-1)" title="Kỳ trước">
                    <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="15 18 9 12 15 6"/></svg>
                  </button>

                  <div v-if="timeFilterMode === 'day'" class="bg-date-capsule sr-sb-date-capsule">
                    <span class="sr-date-cap-lbl">Từ</span>
                    <input type="date" v-model="dateFrom" :max="dateTo" @click="e => (e.target as any).showPicker && (e.target as any).showPicker()" />
                    <span class="bg-date-sep">&rarr;</span>
                    <span class="sr-date-cap-lbl">Đến</span>
                    <input type="date" v-model="dateTo" :min="dateFrom" @click="e => (e.target as any).showPicker && (e.target as any).showPicker()" />
                  </div>

                  <div v-else-if="timeFilterMode === 'month'" class="bg-date-capsule sr-sb-date-capsule">
                    <span class="sr-date-cap-lbl">Từ</span>
                    <input type="month" v-model="monthFrom" :max="monthTo" @click="e => (e.target as any).showPicker && (e.target as any).showPicker()" />
                    <span class="bg-date-sep">&rarr;</span>
                    <span class="sr-date-cap-lbl">Đến</span>
                    <input type="month" v-model="monthTo" :min="monthFrom" @click="e => (e.target as any).showPicker && (e.target as any).showPicker()" />
                  </div>

                  <div v-else-if="timeFilterMode === 'year'" class="bg-date-capsule sr-sb-date-capsule">
                    <span class="sr-date-cap-lbl">Từ</span>
                    <select v-model="yearFrom">
                      <option value="">Tất cả</option>
                      <option v-for="y in availableYearsList" :key="'yf-' + y" :value="y">{{ y }}</option>
                    </select>
                    <span class="bg-date-sep">&rarr;</span>
                    <span class="sr-date-cap-lbl">Đến</span>
                    <select v-model="yearTo">
                      <option value="">Tất cả</option>
                      <option v-for="y in availableYearsList" :key="'yt-' + y" :value="y">{{ y }}</option>
                    </select>
                  </div>

                  <button type="button" class="bg-period-step-btn" @click="shiftSalePeriod(1)" title="Kỳ tiếp theo">
                    <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><polyline points="9 18 15 12 9 6"/></svg>
                  </button>
                </div>
              </div>

              <!-- 5 Bộ lọc Pill Pickers gọn trong Sidebar (KH & NCC mở Modal chọn) -->
              <div class="sr-sidebar-pickers-grid">
                <!-- 1. Khách hàng (Mở Modal chọn) -->
                <div class="pl-picker-wrap is-full-span" :class="{ 'is-open': showFilterCustomerModal }">
                  <div
                    class="pl-picker-trigger"
                    :class="{ 'has-value': filterCustomer && filterCustomer !== 'Tất cả', 'is-open': showFilterCustomerModal }"
                    @click.stop="openFilterCustomerModal()"
                    title="Nhấn để mở danh sách chọn Khách hàng / Công ty"
                  >
                    <span class="pl-picker-tag">KH:</span>
                    <span class="pl-picker-val">{{ !filterCustomer || filterCustomer === 'Tất cả' ? 'Tất cả khách hàng' : filterCustomer }}</span>
                    <button
                      v-if="filterCustomer && filterCustomer !== 'Tất cả'"
                      type="button"
                      class="pl-picker-clear"
                      @click.stop="filterCustomer = 'Tất cả'"
                      title="Bỏ lọc Khách hàng"
                    >&times;</button>
                    <svg v-else class="pl-picker-caret" width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><polyline points="6 9 12 15 18 9"/></svg>
                  </div>
                </div>

                <!-- 2. Nhà cung cấp / Product Type (Mở Modal chọn) -->
                <div class="pl-picker-wrap" :class="{ 'is-open': showFilterNccModal }">
                  <div
                    class="pl-picker-trigger"
                    :class="{ 'has-value': filterProductType !== 'Tất cả', 'is-open': showFilterNccModal }"
                    @click.stop="openFilterNccModal()"
                    title="Nhấn để mở danh sách chọn Nhà cung cấp (NCC / Product Type)"
                  >
                    <span class="pl-picker-tag">NCC:</span>
                    <span class="pl-picker-val">{{ filterProductType === 'Tất cả' ? 'Tất cả' : filterProductType }}</span>
                    <button
                      v-if="filterProductType !== 'Tất cả'"
                      type="button"
                      class="pl-picker-clear"
                      @click.stop="filterProductType = 'Tất cả'"
                      title="Bỏ lọc Nhà cung cấp"
                    >&times;</button>
                    <svg v-else class="pl-picker-caret" width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><polyline points="6 9 12 15 18 9"/></svg>
                  </div>
                </div>

                <!-- 3. Công nợ (Chỉ hiện ở Bản Chính Thức) -->
                <div v-if="srDataMode !== 'craft'" class="pl-picker-wrap is-right-col" :class="{ 'is-open': openSalePickerKey === 'debt' }">
                  <div
                    class="pl-picker-trigger"
                    :class="{ 'has-value': filterDebtStatus !== 'Tất cả', 'is-open': openSalePickerKey === 'debt' }"
                    @click.stop="toggleSalePicker('debt')"
                  >
                    <span class="pl-picker-tag">Nợ:</span>
                    <span class="pl-picker-val">{{ filterDebtStatus }}</span>
                    <button
                      v-if="filterDebtStatus !== 'Tất cả'"
                      type="button"
                      class="pl-picker-clear"
                      @click.stop="filterDebtStatus = 'Tất cả'; closeSalePicker()"
                    >&times;</button>
                    <svg v-else class="pl-picker-caret" width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><polyline points="6 9 12 15 18 9"/></svg>
                  </div>

                  <div v-if="openSalePickerKey === 'debt'" class="pl-popover" @click.stop>
                    <div class="pl-popover-list custom-scrollbar">
                      <button type="button" class="pl-popover-item" :class="{ active: filterDebtStatus === 'Tất cả' }" @click="filterDebtStatus = 'Tất cả'; closeSalePicker()">
                        <span>Tất cả công nợ</span>
                        <span class="pl-item-count">{{ rows.length }}</span>
                      </button>
                      <button type="button" class="pl-popover-item" :class="{ active: filterDebtStatus === 'Còn công nợ' }" @click="filterDebtStatus = 'Còn công nợ'; closeSalePicker()">
                        <span class="pl-dot-label"><i class="pl-dot is-amber"></i>Còn công nợ</span>
                        <span class="pl-item-count">{{ allUnpaidPoCount }}</span>
                      </button>
                      <button type="button" class="pl-popover-item" :class="{ active: filterDebtStatus === 'Quá hạn thanh toán' }" @click="filterDebtStatus = 'Quá hạn thanh toán'; closeSalePicker()">
                        <span class="pl-dot-label"><i class="pl-dot is-rose"></i>Quá hạn thanh toán</span>
                        <span class="pl-item-count">{{ overduePoCount }}</span>
                      </button>
                      <button type="button" class="pl-popover-item" :class="{ active: filterDebtStatus === 'Sắp đến hạn' }" @click="filterDebtStatus = 'Sắp đến hạn'; closeSalePicker()">
                        <span class="pl-dot-label"><i class="pl-dot is-orange"></i>Sắp đến hạn &le; 7 ngày</span>
                        <span class="pl-item-count">{{ dueSoonPoCount }}</span>
                      </button>
                      <button type="button" class="pl-popover-item" :class="{ active: filterDebtStatus === 'Thanh toán 1 phần' }" @click="filterDebtStatus = 'Thanh toán 1 phần'; closeSalePicker()">
                        <span class="pl-dot-label"><i class="pl-dot is-sky"></i>Thanh toán 1 phần</span>
                        <span class="pl-item-count">{{ partialPaidPoCount }}</span>
                      </button>
                      <button type="button" class="pl-popover-item" :class="{ active: filterDebtStatus === 'Chưa thanh toán' }" @click="filterDebtStatus = 'Chưa thanh toán'; closeSalePicker()">
                        <span class="pl-dot-label"><i class="pl-dot is-red"></i>Chưa thanh toán</span>
                        <span class="pl-item-count">{{ unpaidZeroPoCount }}</span>
                      </button>
                      <button type="button" class="pl-popover-item" :class="{ active: filterDebtStatus === 'Đã tất toán' }" @click="filterDebtStatus = 'Đã tất toán'; closeSalePicker()">
                        <span class="pl-dot-label"><i class="pl-dot is-emerald"></i>Đã tất toán (Hết nợ)</span>
                        <span class="pl-item-count">{{ settledPoCount }}</span>
                      </button>
                    </div>
                  </div>
                </div>

                <!-- 4. Sắp xếp ngày tạo -->
                <div class="pl-picker-wrap" :class="{ 'is-open': openSalePickerKey === 'sortDate' }">
                  <div
                    class="pl-picker-trigger"
                    :class="{ 'has-value': sortOrder !== 'Mới nhất', 'is-open': openSalePickerKey === 'sortDate' }"
                    @click.stop="toggleSalePicker('sortDate')"
                  >
                    <span class="pl-picker-tag">Ngày:</span>
                    <span class="pl-picker-val">{{ sortOrder === 'Mới nhất' ? 'Mới → Cũ' : 'Cũ → Mới' }}</span>
                    <svg class="pl-picker-caret" width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><polyline points="6 9 12 15 18 9"/></svg>
                  </div>

                  <div v-if="openSalePickerKey === 'sortDate'" class="pl-popover" @click.stop>
                    <div class="pl-popover-list">
                      <button type="button" class="pl-popover-item" :class="{ active: sortOrder === 'Mới nhất' }" @click="sortOrder = 'Mới nhất'; closeSalePicker()">
                        <span>Mới nhất &rarr; Cũ nhất</span>
                        <svg v-if="sortOrder === 'Mới nhất'" class="pl-check" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6"><polyline points="20 6 9 17 4 12"/></svg>
                      </button>
                      <button type="button" class="pl-popover-item" :class="{ active: sortOrder === 'Cũ nhất' }" @click="sortOrder = 'Cũ nhất'; closeSalePicker()">
                        <span>Cũ nhất &rarr; Mới nhất</span>
                        <svg v-if="sortOrder === 'Cũ nhất'" class="pl-check" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6"><polyline points="20 6 9 17 4 12"/></svg>
                      </button>
                    </div>
                  </div>
                </div>

                <!-- 5. Sắp xếp số PO -->
                <div class="pl-picker-wrap is-right-col" :class="{ 'is-open': openSalePickerKey === 'sortPo' }">
                  <div
                    class="pl-picker-trigger"
                    :class="{ 'has-value': !!sortPoOrder, 'is-open': openSalePickerKey === 'sortPo' }"
                    @click.stop="toggleSalePicker('sortPo')"
                  >
                    <span class="pl-picker-tag">PO:</span>
                    <span class="pl-picker-val">{{ !sortPoOrder ? 'Mặc định' : (sortPoOrder === 'PO giảm' ? 'Lớn → Nhỏ' : 'Nhỏ → Lớn') }}</span>
                    <button
                      v-if="sortPoOrder"
                      type="button"
                      class="pl-picker-clear"
                      @click.stop="sortPoOrder = ''; closeSalePicker()"
                    >&times;</button>
                    <svg v-else class="pl-picker-caret" width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><polyline points="6 9 12 15 18 9"/></svg>
                  </div>

                  <div v-if="openSalePickerKey === 'sortPo'" class="pl-popover" @click.stop>
                    <div class="pl-popover-list">
                      <button type="button" class="pl-popover-item" :class="{ active: !sortPoOrder }" @click="sortPoOrder = ''; closeSalePicker()">
                        <span>Mặc định (Theo ngày tạo)</span>
                        <svg v-if="!sortPoOrder" class="pl-check" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6"><polyline points="20 6 9 17 4 12"/></svg>
                      </button>
                      <button type="button" class="pl-popover-item" :class="{ active: sortPoOrder === 'PO giảm' }" @click="sortPoOrder = 'PO giảm'; closeSalePicker()">
                        <span>Số PO lớn &rarr; nhỏ</span>
                        <svg v-if="sortPoOrder === 'PO giảm'" class="pl-check" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6"><polyline points="20 6 9 17 4 12"/></svg>
                      </button>
                      <button type="button" class="pl-popover-item" :class="{ active: sortPoOrder === 'PO tăng' }" @click="sortPoOrder = 'PO tăng'; closeSalePicker()">
                        <span>Số PO nhỏ &rarr; lớn</span>
                        <svg v-if="sortPoOrder === 'PO tăng'" class="pl-check" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6"><polyline points="20 6 9 17 4 12"/></svg>
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>

          <div v-if="!isMobileShell && layoutViewMode === 'master-detail'" class="sr-md-company-list">
            <div v-if="filteredSidebarGroups.length === 0" class="sr-md-empty-sidebar">
              Không tìm thấy công ty phù hợp với điều kiện lọc hiện tại.
            </div>

            <div
              v-for="(cGroup, cIdx) in filteredSidebarGroups"
              :key="cGroup.ma_cong_ty + cIdx"
              class="sr-md-company-card"
              :class="{
                active: activeMasterGroup && getGroupCollapseKey(activeMasterGroup) === getGroupCollapseKey(cGroup),
                'is-promoted-company-card': highlightedPoKey && Array.isArray(cGroup.items) && cGroup.items.some((it: any) => getPoRowKey(it) === highlightedPoKey || String(it.So_PO || '') === highlightedPoKey)
              }"
              @click="selectMasterGroup(cGroup)"
            >
              <!-- Dòng 1: Ô chọn + Tên công ty - Tên KH - MST -->
              <div class="sr-md-cc-header-line">
                <button
                  type="button"
                  class="sr-md-cc-check"
                  :class="{ selected: isGroupFullySelected(cGroup) }"
                  @click.stop="toggleSelectGroup(cGroup)"
                  :title="isGroupFullySelected(cGroup) ? 'Bỏ chọn toàn bộ PO của công ty này' : 'Chọn toàn bộ PO của công ty này để xuất Excel'"
                >
                  <svg v-if="isGroupFullySelected(cGroup)" xmlns="http://www.w3.org/2000/svg" width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
                </button>
                <div class="sr-md-cc-title-block">
                  <div class="sr-md-cc-name" :title="`${cGroup.ten_cong_ty}${getGroupTenKhachHang(cGroup) ? ' - ' + getGroupTenKhachHang(cGroup) : ''}${cGroup.mst && cGroup.mst !== 'N/A' ? ' - ' + cGroup.mst : ''}`">
                    <span class="sr-md-cc-code-plain" v-html="highlightSaleText(cGroup.ten_cong_ty, searchStr)"></span>
                    <template v-if="getGroupTenKhachHang(cGroup)">
                      <span class="sr-po1-sep">-</span>
                      <span v-html="highlightSaleText(getGroupTenKhachHang(cGroup), searchStr)"></span>
                    </template>
                    <template v-if="cGroup.mst && cGroup.mst !== 'N/A'">
                      <span class="sr-po1-sep">-</span>
                      <span class="sr-md-cc-mst-inline" v-html="highlightSaleText(cGroup.mst, searchStr)"></span>
                    </template>
                  </div>
                </div>
              </div>

              <!-- Dòng 2: Bản Chính Thức hiện DSB/Đã TT/Công nợ/PO; Bản Tạm hiện Số PA / DSB cao nhất / Margin tốt nhất -->
              <div v-if="srDataMode === 'craft'" class="sr-md-cc-metrics-4col is-craft-sidebar-metrics" style="grid-template-columns: repeat(3, minmax(0, 1fr));">
                <div class="sr-md-ccm-item">
                  <span class="sr-md-ccm-lbl">Phương án</span>
                  <strong class="sr-md-ccm-val">{{ cGroup.items.length }} PA</strong>
                </div>
                <div class="sr-md-ccm-item">
                  <span class="sr-md-ccm-lbl">DSB cao nhất</span>
                  <strong class="sr-md-ccm-val is-com-text">{{ fmt(getGroupMaxDoanhSoBan(cGroup)) }}</strong>
                </div>
                <div class="sr-md-ccm-item">
                  <span class="sr-md-ccm-lbl">Margin tốt nhất</span>
                  <strong class="sr-md-ccm-val" :class="getGroupMaxNetMargin(cGroup) >= 0 ? 'is-com-text' : 'is-debt-text'">{{ fmt(getGroupMaxNetMargin(cGroup)) }}</strong>
                </div>
              </div>
              <div v-else class="sr-md-cc-metrics-4col">
                <div class="sr-md-ccm-item">
                  <span class="sr-md-ccm-lbl">DSB</span>
                  <strong class="sr-md-ccm-val is-com-text">{{ fmt(getGroupDoanhSoBan(cGroup)) }}</strong>
                </div>
                <div class="sr-md-ccm-item">
                  <span class="sr-md-ccm-lbl">Đã TT</span>
                  <strong class="sr-md-ccm-val is-com-text">{{ fmt(getGroupDaThanhToan(cGroup)) }}</strong>
                </div>
                <div class="sr-md-ccm-item">
                  <span class="sr-md-ccm-lbl">Công nợ</span>
                  <strong class="sr-md-ccm-val" :class="getGroupCongNo(cGroup) > 0 ? 'is-debt-text' : 'is-com-text'">{{ fmt(getGroupCongNo(cGroup)) }}</strong>
                </div>
                <div class="sr-md-ccm-item">
                  <span class="sr-md-ccm-lbl">Tổng số PO</span>
                  <strong class="sr-md-ccm-val">{{ cGroup.items.length }} PO</strong>
                </div>
              </div>
            </div>
          </div>
        </aside>

        <!-- CỘT PHẢI (70%): THANH TÁC VỤ PHÍA TRÊN + HEADER CÔNG TY + 4 CARD KPI RIÊNG KHÁCH HÀNG & DANH SÁCH CARD PO -->
        <div
          v-show="!isMobileShell || mobileActiveTab === 'overview' || mobileActiveTab === 'company_detail'"
          class="sr-md-main-area"
        >
          <!-- Thanh tác vụ nằm phía trên Header của tên công ty -->
          <div class="sr-company-top-toolbar" @click.stop>
            <!-- Thanh ngữ cảnh Mobile (Tab Chi tiết Cty: Quay lại Tổng quan & Chuyển nhanh Cty Trước/Sau) -->
            <div v-if="isMobileShell && mobileActiveTab === 'company_detail'" class="sr-mob-toolbar-left">
              <button
                type="button"
                class="sr-mob-ctx-btn is-back-list"
                @click.stop="switchMobileTab('overview')"
                title="Quay lại màn hình Tổng quan"
              >
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="15 18 9 12 15 6"/></svg>
                <span>Tổng quan</span>
              </button>

              <div v-if="filteredRows.length > 1" class="sr-mob-company-stepper">
                <button
                  type="button"
                  class="sr-mob-step-btn"
                  @click.stop="prevMobilePo()"
                  title="Công ty trước"
                >
                  <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="15 18 9 12 15 6"/></svg>
                </button>
                <span class="sr-mob-step-pos">PO {{ activeMobilePoIndex + 1 }}/{{ filteredRows.length }}</span>
                <button
                  type="button"
                  class="sr-mob-step-btn"
                  @click.stop="nextMobilePo()"
                  title="PO tiếp theo"
                >
                  <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"/></svg>
                </button>
              </div>
              <button v-if="activeMobilePoRow" type="button" class="sr-mob-ctx-btn is-edit-po" @click.stop="openMultiEditModal(activeMobilePoRow)">
                <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/></svg>
                <span>Sửa PO</span>
              </button>
            </div>

            <div v-if="!isMobileShell" class="sr-ctt-left">
              <div class="sr-ctt-mode-switcher" role="tablist" aria-label="Chế độ dữ liệu Sale Report">
                <button
                  type="button"
                  class="sr-ctt-mode-btn is-official"
                  :class="{ active: srDataMode === 'official' }"
                  @click.stop="switchSrDataMode('official')"
                  title="Chế độ Bản Chính Thức (Đã chốt deal)"
                >
                  <svg class="sr-ctt-mode-icon" width="13.5" height="13.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/><polyline points="9 12 11 14 15 10"/></svg>
                  <span class="sr-ctt-mode-label">Bản Chính Thức</span>
                  <span class="sr-ctt-mode-count">{{ officialRows.length }}</span>
                </button>
                <button
                  type="button"
                  class="sr-ctt-mode-btn is-craft"
                  :class="{ active: srDataMode === 'craft' }"
                  @click.stop="switchSrDataMode('craft')"
                  title="Chế độ Phương Án Tạm (So sánh trước khi chốt deal)"
                >
                  <svg class="sr-ctt-mode-icon" width="13.5" height="13.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><polygon points="12 2 2 7 12 12 22 7 12 2"/><polyline points="2 17 12 22 22 17"/><polyline points="2 12 12 17 22 12"/></svg>
                  <span class="sr-ctt-mode-label">Phương Án Tạm</span>
                  <span class="sr-ctt-mode-count">{{ craftRows.length }}</span>
                </button>
              </div>
            </div>

            <div class="sr-ctt-right">
              <button
                type="button"
                class="sr-hdr-action-btn is-review-mindmap"
                @click.stop="openReviewMindmapModal(isMobileShell && mobileActiveTab === 'company_detail' && activeMobilePoGroup ? activeMobilePoGroup : (layoutViewMode === 'master-detail' && activeMasterGroup ? null : null))"
                title="Mở Mindmap Review Kinh Doanh (Tổng quan → Công ty → PO → Chi tiết)"
              >
                <svg width="13.5" height="13.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><circle cx="6" cy="12" r="3"/><circle cx="18" cy="6" r="3"/><circle cx="18" cy="18" r="3"/><path d="M8.7 10.7l6.6-3.4"/><path d="M8.7 13.3l6.6 3.4"/></svg>
                <span>Review tổng</span>
              </button>

              <button
                type="button"
                class="sr-hdr-action-btn is-add"
                @click.stop="openAddChoiceModal()"
                :title="srDataMode === 'craft' ? 'Tạo Phương án tạm mới hoặc Import Báo giá / DXMH / Report' : 'Tạo PO mới hoặc Import Báo giá / DXMH / Report'"
              >
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
                <span>{{ srDataMode === 'craft' ? 'Thêm phương án' : 'Thêm mới' }}</span>
              </button>

              <button
                type="button"
                class="sr-hdr-action-btn is-export"
                @click.stop="openExportFromToolbar()"
                title="Xuất danh sách Sale Report ra Excel"
              >
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>
                <span>Xuất Excel</span>
                <span v-if="selectedPoRows.length > 0" class="sr-hdr-export-count">{{ selectedPoRows.length }}</span>
              </button>

              <!-- Nút & Popover Thiết lập hiển thị (chuẩn baogiaFirebase.vue) -->
              <div class="sr-display-setting-wrap">
                <button
                  type="button"
                  class="sr-hdr-action-btn is-setting"
                  :class="{ active: showDisplaySettingPopover }"
                  @click.stop="showDisplaySettingPopover = !showDisplaySettingPopover"
                  title="Thiết lập hiển thị cột PO, bố cục nhóm & giao diện"
                >
                  <svg width="13.5" height="13.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round">
                    <circle cx="12" cy="12" r="3"></circle>
                    <path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1 0 2.83 2 2 0 0 1-2.83 0l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-2 2 2 2 0 0 1-2-2v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83 0 2 2 0 0 1 0-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1-2-2 2 2 0 0 1 2-2h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 0-2.83 2 2 0 0 1 2.83 0l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 2-2 2 2 0 0 1 2 2v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 0 2 2 0 0 1 0 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 2 2 2 2 0 0 1-2 2h-.09a1.65 1.65 0 0 0-1.51 1z"></path>
                  </svg>
                  <span>Thiết lập hiển thị</span>
                </button>

                <!-- Dropdown Thiết lập hiển thị chuẩn baogiaFirebase.vue -->
                <div v-if="showDisplaySettingPopover" class="sr-display-setting-dropdown" @click.stop>
                  <div class="sr-ds-head">
                    <span class="sr-ds-title">Thiết lập hiển thị</span>
                    <button type="button" class="sr-ds-close" @click="showDisplaySettingPopover = false">✕</button>
                  </div>

                  <!-- 1. Giao diện (Theme) -->
                  <div class="sr-ds-section">
                    <div class="sr-ds-label">Giao diện (Theme)</div>
                    <div class="sr-ds-grid-2">
                      <button
                        type="button"
                        class="sr-ds-opt-btn"
                        :class="{ active: uiTheme === 'dark' }"
                        @click="uiTheme !== 'dark' && toggleUiTheme()"
                      >
                        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"></path></svg>
                        <span>Tối (Mặc định)</span>
                      </button>
                      <button
                        type="button"
                        class="sr-ds-opt-btn"
                        :class="{ active: uiTheme === 'light' }"
                        @click="uiTheme !== 'light' && toggleUiTheme()"
                      >
                        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="5"></circle><line x1="12" y1="1" x2="12" y2="3"></line><line x1="12" y1="21" x2="12" y2="23"></line><line x1="4.22" y1="4.22" x2="5.64" y2="5.64"></line><line x1="18.36" y1="18.36" x2="19.78" y2="19.78"></line><line x1="1" y1="12" x2="3" y2="12"></line><line x1="21" y1="12" x2="23" y2="12"></line></svg>
                        <span>Sáng (Xanh-Trắng)</span>
                      </button>
                    </div>
                  </div>

                  <!-- 2. Số cột hiển thị Card PO -->
                  <div class="sr-ds-section">
                    <div class="sr-ds-label">Hiển thị cột Card PO</div>
                    <div class="sr-ds-grid-2">
                      <button
                        type="button"
                        class="sr-ds-opt-btn"
                        :class="{ active: poCardCols === 1 }"
                        @click="poCardCols = 1"
                      >
                        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><rect x="3" y="4" width="18" height="6" rx="1"/><rect x="3" y="14" width="18" height="6" rx="1"/></svg>
                        <span>1 Cột PO</span>
                      </button>
                      <button
                        type="button"
                        class="sr-ds-opt-btn"
                        :class="{ active: poCardCols === 2 }"
                        @click="poCardCols = 2"
                      >
                        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/></svg>
                        <span>2 Cột PO</span>
                      </button>
                    </div>
                  </div>

                  <!-- 3. Bố cục hiển thị Nhóm công ty -->
                  <div class="sr-ds-section">
                    <div class="sr-ds-label">Bố cục nhóm công ty</div>
                    <div class="sr-ds-grid-2">
                      <button
                        type="button"
                        class="sr-ds-opt-btn"
                        :class="{ active: layoutViewMode === 'master-detail' }"
                        @click="layoutViewMode = 'master-detail'"
                      >
                        <span>Chia 2 Cột (3:7)</span>
                      </button>
                      <button
                        type="button"
                        class="sr-ds-opt-btn"
                        :class="{ active: layoutViewMode === 'stacked-groups' }"
                        @click="layoutViewMode = 'stacked-groups'"
                      >
                        <span>Tất cả nhóm dọc</span>
                      </button>
                    </div>
                  </div>

                  <!-- 4. Thu gọn / Mở rộng khu vực hiển thị -->
                  <div class="sr-ds-section is-last">
                    <div class="sr-ds-label">Chế độ chi tiết</div>
                    <div class="sr-ds-stack-btns">
                      <button
                        type="button"
                        class="sr-ds-toggle-row"
                        :class="{ active: !isAllCardsCollapsed }"
                        @click="toggleAllPoCardsCollapse()"
                      >
                        <span>{{ isAllCardsCollapsed ? 'Đang thu gọn Card PO (1 dòng)' : 'Đang mở rộng chi tiết Card PO' }}</span>
                        <strong>{{ isAllCardsCollapsed ? 'Mở rộng' : 'Thu gọn' }}</strong>
                      </button>

                      <button
                        v-if="srDataMode !== 'craft'"
                        type="button"
                        class="sr-ds-toggle-row"
                        :class="{ active: !isKpiCollapsed }"
                        @click="isKpiCollapsed = !isKpiCollapsed"
                      >
                        <span>{{ isKpiCollapsed ? 'Đang ẩn 4 thẻ KPI tổng hợp' : 'Đang hiện 4 thẻ KPI tổng hợp' }}</span>
                        <strong>{{ isKpiCollapsed ? 'Hiện KPI' : 'Ẩn KPI' }}</strong>
                      </button>

                      <button
                        v-if="!isMobileShell && layoutViewMode === 'stacked-groups'"
                        type="button"
                        class="sr-ds-toggle-row"
                        :class="{ active: !areAllGroupsCollapsed }"
                        @click="toggleAllGroupsCollapse()"
                      >
                        <span>{{ areAllGroupsCollapsed ? 'Đang thu gọn các nhóm công ty' : 'Đang mở tất cả nhóm công ty' }}</span>
                        <strong>{{ areAllGroupsCollapsed ? 'Mở tất cả' : 'Thu gọn' }}</strong>
                      </button>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>

          <!-- Khi bộ lọc không khớp công ty nào -->
          <div v-if="renderedMainGroups.length === 0" class="sr-report-group is-md-active-group">
            <div class="sr-company-folder-header">
              <div class="sr-folder-top-bar">
                <div class="sr-folder-ear-tab">
                  <svg class="sr-folder-icon" width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">
                    <path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"></path>
                  </svg>
                  <span class="sr-cpb-name">Không có đơn hàng PO phù hợp</span>
                </div>
              </div>
              <div class="sr-cpb-kpi-strip sr-folder-body-sheet sr-empty-folder-sheet">
                <span>Không tìm thấy đơn hàng PO nào khớp với điều kiện lọc hiện tại.</span>
                <button v-if="activeSaleFilterCount > 0" type="button" class="sr-plain-text-btn" @click="resetAllSaleFilters">
                  Đặt lại toàn bộ bộ lọc ({{ activeSaleFilterCount }})
                </button>
              </div>
            </div>
          </div>

          <div
            v-for="(group, gIdx) in renderedMainGroups"
            :key="group.ma_cong_ty + gIdx"
            class="sr-report-group"
            :class="{
              'is-group-collapsed': !isMobileShell && layoutViewMode === 'stacked-groups' && isGroupCollapsed(group),
              'is-md-active-group': isMobileShell ? mobileActiveTab === 'company_detail' : layoutViewMode === 'master-detail'
            }"
          >
            <!-- Header Công Ty Dạng Hình File / Bìa Hồ Sơ (Folder Tab Shape) Phía Trên Card PO -->
            <div
              class="sr-company-folder-header"
              @click="(!isMobileShell && layoutViewMode === 'stacked-groups') ? toggleGroupCollapse(group) : undefined"
              :style="{ cursor: (!isMobileShell && layoutViewMode === 'stacked-groups') ? 'pointer' : 'default' }"
            >
              <!-- Hàng trên: Tai File (Folder Ear Tab) bên trái + Cụm Tác vụ, Dữ liệu & Thiết lập hiển thị ở góc phải (chuẩn baogiaFirebase) -->
              <div class="sr-folder-top-bar">
                <div class="sr-folder-ear-tab">
                  <svg class="sr-folder-icon" width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">
                    <path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"></path>
                  </svg>
                  <h3 class="sr-cpb-name" :title="group.ten_cong_ty" v-html="highlightSaleText(group.ten_cong_ty, searchStr)"></h3>
                  <template v-if="getGroupTenKhachHang(group)">
                    <span class="sr-folder-sep">-</span>
                    <strong class="sr-cpb-code" v-html="highlightSaleText(getGroupTenKhachHang(group), searchStr)"></strong>
                  </template>
                  <template v-if="group.mst && group.mst !== 'N/A'">
                    <span class="sr-folder-sep">-</span>
                    <span class="sr-folder-mst">MST: <span v-html="highlightSaleText(group.mst, searchStr)"></span></span>
                  </template>
                  <span class="sr-folder-sep">•</span>
                  <span class="sr-folder-pocount" :class="{ 'is-craft-count': srDataMode === 'craft' }">
                    {{ group.items.length }} {{ srDataMode === 'craft' ? 'Phương án' : 'PO' }}
                  </span>
                  <button
                    type="button"
                    class="sr-plain-text-btn is-folder-review-btn"
                    @click.stop="openReviewMindmapModal(group)"
                    title="Review Sơ đồ nhánh Kinh doanh của riêng công ty này"
                  >
                    <svg width="12.5" height="12.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><circle cx="6" cy="12" r="3"/><circle cx="18" cy="6" r="3"/><circle cx="18" cy="18" r="3"/><path d="M8.7 10.7l6.6-3.4"/><path d="M8.7 13.3l6.6 3.4"/></svg>
                    <span>Review công ty</span>
                  </button>
                </div>

                <div
                  v-if="!isMobileShell && layoutViewMode === 'stacked-groups'"
                  class="sr-cpb-right"
                  @click.stop
                >
                  <button
                    type="button"
                    class="sr-plain-text-btn"
                    @click.stop="toggleGroupCollapse(group)"
                  >
                    <span class="sr-hide-mob">{{ isGroupCollapsed(group) ? 'Mở rộng' : 'Thu gọn' }}</span>
                  </button>
                </div>
              </div>

              <div v-if="false" class="sr-mob-folder-subbar"><div class="sr-mob-fs-left"><strong v-if="getGroupTenKhachHang(group)" class="sr-mob-fs-code" v-html="highlightSaleText(getGroupTenKhachHang(group), searchStr)"></strong><span v-if="getGroupTenKhachHang(group) && group.mst && group.mst !== 'N/A'" class="sr-mob-fs-sep">•</span><span v-if="group.mst && group.mst !== 'N/A'" class="sr-mob-fs-mst">MST: <span v-html="highlightSaleText(group.mst, searchStr)"></span></span></div><div class="sr-mob-fs-right"><span class="sr-mob-fs-metric">DSB: <strong>{{ fmt(getGroupDoanhSoBan(group)) }}</strong></span><span class="sr-mob-fs-sep">•</span><span class="sr-mob-fs-metric" :class="getGroupCongNo(group) > 0 ? 'is-debt' : 'is-settled'">Nợ: <strong>{{ fmt(getGroupCongNo(group)) }}</strong></span></div></div>
              <!-- Bên dưới Header Tên Công Ty: 4 Card KPI Dành Riêng Cho Khách Hàng Này (Chỉ hiện ở Bản Chính Thức, ẩn ở Bản Tạm) -->
              <div
                v-if="srDataMode !== 'craft'"
                v-show="isMobileShell ? mobileActiveTab === 'overview' : (layoutViewMode === 'master-detail' || !isGroupCollapsed(group))"
                class="sr-customer-kpi-sheet sr-folder-body-sheet"
                @click.stop
              >
                <div class="sr-super-bento-grid is-customer-bento">
                  <!-- CARD 1 (KH): Doanh số bán | Net PO | Tổng tiền sau VAT -->
                  <article
                    class="sr-sb-card sb-card-revenue"
                    style="cursor: pointer;"
                    @click="openCompanyChart(group, 'doanhSoBan')"
                    title="Click xem biểu đồ Doanh số bán của công ty này"
                  >
                    <div class="sr-sb-head">
                      <div class="sr-sb-title-cluster">
                        <span class="sr-sb-icon is-blue">
                          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><line x1="12" y1="1" x2="12" y2="23"/><path d="M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6"/></svg>
                        </span>
                        <h3 class="sr-sb-title">Doanh số bán</h3>
                      </div>
                      <div class="sr-sb-quick-acts">
                        <button
                          type="button"
                          class="sr-sb-act-pill"
                          @click.stop="openCompanyChart(group, 'doanhSoBan')"
                          title="Mở bảng phân tích Doanh số bán của công ty này"
                        >
                          <svg class="sr-sb-act-svg" width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><path d="M3 3v18h18"/><path d="M18 17V9"/><path d="M13 17V5"/><path d="M8 17v-3"/></svg><span class="sr-sb-act-text">Xem phân tích</span>
                        </button>
                      </div>
                    </div>

                    <div
                      class="sr-sb-main"
                      style="cursor: pointer;"
                      @click.stop="openCompanyChart(group, 'doanhSoBan')"
                      title="Click xem biểu đồ Doanh số bán của công ty này"
                    >
                      <div class="sr-sb-hero-val money-white">
                        {{ fmt(getGroupDoanhSoBan(group)) }}
                        <span class="sr-sb-unit">VND</span>
                      </div>
                    </div>

                    <div class="sr-sb-foot">
                      <div
                        class="sr-sb-foot-row"
                        style="cursor: pointer;"
                        @click.stop="openCompanyChart(group, 'netPO')"
                        title="Click xem biểu đồ Net PO của công ty này"
                      >
                        <span class="sr-sb-foot-label">Net PO</span>
                        <strong class="sr-sb-foot-val money-blue">{{ fmt(getGroupNetPO(group)) }} <small>đ</small></strong>
                      </div>
                      <div
                        class="sr-sb-foot-row"
                        style="cursor: pointer;"
                        @click.stop="openCompanyChart(group, 'tongSauVat')"
                        title="Click xem biểu đồ Tổng tiền sau VAT của công ty này"
                      >
                        <span class="sr-sb-foot-label">Tổng tiền sau VAT</span>
                        <strong class="sr-sb-foot-val money-blue">{{ fmt(getGroupTongSauVat(group)) }} <small>đ</small></strong>
                      </div>
                    </div>
                  </article>

                  <!-- CARD 2 (KH): Net COM | Gross COM | Net Com / Net PO | Net Com / DSB -->
                  <article
                    class="sr-sb-card sb-card-com"
                    style="cursor: pointer;"
                    @click="openCompanyChart(group, 'netCom')"
                    title="Click xem biểu đồ Net COM của công ty này"
                  >
                    <div class="sr-sb-head">
                      <div class="sr-sb-title-cluster">
                        <span class="sr-sb-icon is-emerald">
                          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>
                        </span>
                        <h3 class="sr-sb-title">Net COM</h3>
                      </div>
                      <div class="sr-sb-quick-acts">
                        <button
                          type="button"
                          class="sr-sb-act-pill"
                          @click.stop="openCompanyChart(group, 'netCom')"
                          title="Mở bảng phân tích Net COM của công ty này"
                        >
                          <svg class="sr-sb-act-svg" width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><path d="M3 3v18h18"/><path d="M18 17V9"/><path d="M13 17V5"/><path d="M8 17v-3"/></svg><span class="sr-sb-act-text">Xem phân tích</span>
                        </button>
                      </div>
                    </div>

                    <div
                      class="sr-sb-main"
                      style="cursor: pointer;"
                      @click.stop="openCompanyChart(group, 'netCom')"
                      title="Click xem biểu đồ Net COM của công ty này"
                    >
                      <div class="sr-sb-hero-val money-green">
                        {{ fmt(getGroupNetCom(group)) }}
                        <span class="sr-sb-unit">VND</span>
                      </div>
                    </div>

                    <div class="sr-sb-foot">
                      <div
                        class="sr-sb-foot-row"
                        style="cursor: pointer;"
                        @click.stop="openCompanyChart(group, 'grossCom')"
                        title="Click xem biểu đồ Gross COM của công ty này"
                      >
                        <span class="sr-sb-foot-label">Gross COM</span>
                        <strong class="sr-sb-foot-val money-blue">{{ fmt(getGroupGrossCom(group)) }} <small>đ</small></strong>
                      </div>
                      <div
                        class="sr-sb-foot-row"
                        style="cursor: pointer;"
                        @click.stop="openCompanyChart(group, 'totalNetComPct', true)"
                        title="Click xem biểu đồ Net Com / Net PO của công ty này"
                      >
                        <span class="sr-sb-foot-label">Net Com / Net PO</span>
                        <strong class="sr-sb-foot-val money-green">{{ pctFmt(getGroupNetComPct(group)) }}</strong>
                      </div>
                      <div
                        class="sr-sb-foot-row"
                        style="cursor: pointer;"
                        @click.stop="openCompanyChart(group, 'totalNetComDsbPct', true)"
                        title="Click xem biểu đồ Net Com / DSB của công ty này"
                      >
                        <span class="sr-sb-foot-label">Net Com / DSB</span>
                        <strong class="sr-sb-foot-val money-green">{{ pctFmt(getGroupNetComDsbPct(group)) }}</strong>
                      </div>
                    </div>
                  </article>

                  <!-- CARD 3 (KH): Net Margin | Net Margin / Net PO | Net Margin / DSB -->
                  <article
                    class="sr-sb-card sb-card-margin"
                    style="cursor: pointer;"
                    @click="openCompanyChart(group, 'netMargin')"
                    title="Click xem biểu đồ Net Margin của công ty này"
                  >
                    <div class="sr-sb-head">
                      <div class="sr-sb-title-cluster">
                        <span class="sr-sb-icon" :class="getGroupNetMargin(group) >= 0 ? 'is-emerald' : 'is-red'">
                          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 3v18h18"/><path d="M18.7 8l-5.1 5.2-2.8-2.7L7 14.3"/></svg>
                        </span>
                        <h3 class="sr-sb-title">Net Margin</h3>
                      </div>
                      <div class="sr-sb-quick-acts">
                        <button
                          type="button"
                          class="sr-sb-act-pill"
                          @click.stop="openCompanyChart(group, 'netMargin')"
                          title="Mở bảng phân tích Net Margin của công ty này"
                        >
                          <svg class="sr-sb-act-svg" width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><path d="M3 3v18h18"/><path d="M18 17V9"/><path d="M13 17V5"/><path d="M8 17v-3"/></svg><span class="sr-sb-act-text">Xem phân tích</span>
                        </button>
                      </div>
                    </div>

                    <div
                      class="sr-sb-main"
                      style="cursor: pointer;"
                      @click.stop="openCompanyChart(group, 'netMargin')"
                      title="Click xem biểu đồ Net Margin của công ty này"
                    >
                      <div class="sr-sb-hero-val" :class="getGroupNetMargin(group) >= 0 ? 'money-green' : 'money-red'">
                        {{ fmt(getGroupNetMargin(group)) }}
                        <span class="sr-sb-unit">VND</span>
                      </div>
                    </div>

                    <div class="sr-sb-foot">
                      <div
                        class="sr-sb-foot-row"
                        style="cursor: pointer;"
                        @click.stop="openCompanyChart(group, 'totalNetMarginPct', true)"
                        title="Click xem biểu đồ Net Margin / Net PO của công ty này"
                      >
                        <span class="sr-sb-foot-label">Net Margin / Net PO</span>
                        <strong class="sr-sb-foot-val" :class="getGroupNetMarginPct(group) >= 0 ? 'money-green' : 'money-red'">{{ pctFmt(getGroupNetMarginPct(group)) }}</strong>
                      </div>
                      <div
                        class="sr-sb-foot-row"
                        style="cursor: pointer;"
                        @click.stop="openCompanyChart(group, 'totalNetMarginDsbPct', true)"
                        title="Click xem biểu đồ Net Margin / DSB của công ty này"
                      >
                        <span class="sr-sb-foot-label">Net Margin / DSB</span>
                        <strong class="sr-sb-foot-val" :class="getGroupNetMarginDsbPct(group) >= 0 ? 'money-blue' : 'money-red'">{{ pctFmt(getGroupNetMarginDsbPct(group)) }}</strong>
                      </div>
                    </div>
                  </article>

                  <!-- CARD 4 (KH): Công nợ còn lại | Khách đã thanh toán -->
                  <article
                    class="sr-sb-card sb-card-debt"
                    style="cursor: pointer;"
                    @click="openCompanyChart(group, 'congNo', false, 'debt')"
                    title="Click xem biểu đồ Công nợ & Tiến độ thanh toán của công ty này"
                  >
                    <div class="sr-sb-head">
                      <div class="sr-sb-title-cluster">
                        <span class="sr-sb-icon" :class="getGroupCongNo(group) > 0 ? 'is-red' : 'is-emerald'">
                          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>
                        </span>
                        <h3 class="sr-sb-title">Công nợ còn lại</h3>
                      </div>
                      <div class="sr-sb-quick-acts">
                        <button
                          type="button"
                          class="sr-sb-act-pill"
                          @click.stop="openCompanyChart(group, 'congNo', false, 'debt')"
                          title="Mở bảng phân tích Công nợ của công ty này"
                        >
                          <svg class="sr-sb-act-svg" width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><path d="M3 3v18h18"/><path d="M18 17V9"/><path d="M13 17V5"/><path d="M8 17v-3"/></svg><span class="sr-sb-act-text">Xem phân tích</span>
                        </button>
                      </div>
                    </div>

                    <div
                      class="sr-sb-main"
                      style="cursor: pointer;"
                      @click.stop="openCompanyChart(group, 'congNo', false, 'debt')"
                      title="Click xem biểu đồ Công nợ còn lại của công ty này"
                    >
                      <div class="sr-sb-hero-val" :class="getGroupCongNo(group) > 0 ? 'money-red' : 'money-green'">
                        {{ fmt(getGroupCongNo(group)) }}
                        <span class="sr-sb-unit">VND</span>
                      </div>
                      <span
                        class="sr-sb-po-badge"
                        :class="getGroupUnpaidPoCount(group) > 0 ? 'is-red' : 'is-emerald'"
                      >
                        {{ getGroupUnpaidPoCount(group) }}/{{ group.items.length }} PO nợ
                      </span>
                    </div>

                    <div class="sr-sb-foot">
                      <div
                        class="sr-sb-foot-row"
                        style="cursor: pointer;"
                        @click.stop="openCompanyChart(group, 'daThanhToan', false, 'debt')"
                        title="Click xem biểu đồ Khách đã thanh toán của công ty này"
                      >
                        <span class="sr-sb-foot-label">Khách đã thanh toán</span>
                        <strong class="sr-sb-foot-val money-green">{{ fmt(getGroupDaThanhToan(group)) }} <small>đ</small></strong>
                      </div>
                      <div
                        class="sr-sb-foot-row"
                        style="cursor: pointer;"
                        @click.stop="openCompanyChart(group, 'daThanhToan', false, 'debt')"
                        title="Click xem biểu đồ Tiến độ thanh toán của công ty này"
                      >
                        <span class="sr-sb-foot-label">
                          Khách đã thanh toán / Tổng tiền sau VAT
                          <span v-if="getGroupOverduePoCount(group) > 0" class="sr-sb-overdue-inline">({{ getGroupOverduePoCount(group) }} quá hạn)</span>
                        </span>
                        <strong class="sr-sb-foot-val money-blue">{{ getGroupTongSauVat(group) > 0 ? pctFmt(getGroupPaidPct(group)) : '0%' }}</strong>
                      </div>
                    </div>

                    <div class="sr-sb-bottom-progress" aria-hidden="true">
                      <div
                        class="sr-sb-bottom-progress-fill"
                        :style="{ width: Math.min(100, Math.max(0, getGroupPaidPct(group))) + '%' }"
                      ></div>
                    </div>
                  </article>
                </div>
              </div>
            </div>

            <!-- Danh sách Card PO (Hỗ trợ 1 Cột hoặc 2 Cột + Lazy Loading tự động) -->
            <div
              v-show="isMobileShell || layoutViewMode === 'master-detail' || !isGroupCollapsed(group)"
              class="sr-card-list"
              :class="poCardCols === 2 ? 'is-cols-2' : 'is-cols-1'"
            >
              <div v-for="(r, idx) in getVisibleGroupPoItems(group)" :key="getPoRowKey(r) || idx" class="sr-card-outer-item">
                <div
                  :id="'sr-po-card-' + (getPoRowKey(r) || r.So_PO || idx)"
                  class="sr-record-card sr-po1-card"
                  :class="{
                    'is-selected-card': isPoRowSelected(r),
                    'is-craft-card': srDataMode === 'craft',
                    'is-collapsed-card': isEffectivePoCollapsed(r),
                    'is-mob-po-summary': isMobileShell && mobileActiveTab === 'overview',
                    'is-promoted-highlight-card': highlightedPoKey && (highlightedPoKey === getPoRowKey(r) || highlightedPoKey === String(r.So_PO || ''))
                  }"
                  @click="openMultiEditModal(r)"
                  style="cursor: pointer;"
                >
                  <!-- 1. HEADER CARD PO (MÀU NỀN NỔI BẬT, SẮP XẾP 2 TẦNG RÕ RÀNG) -->
                  <div class="sr-po1-header">
                    <!-- Dòng 1: Thông tin định danh PO bên trái | Trạng thái & Thao tác bên phải -->
                    <div class="sr-po1-hbar">
                      <div class="sr-po1-meta-left">
                        <button
                          type="button"
                          class="sr-md-cc-check"
                          :class="{ selected: isPoRowSelected(r) }"
                          @click.stop="toggleSelectPoRow(r)"
                          :title="isPoRowSelected(r) ? 'Bỏ chọn PO này' : 'Chọn PO này'"
                        >
                          <svg v-if="isPoRowSelected(r)" xmlns="http://www.w3.org/2000/svg" width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
                        </button>
                        <span v-if="srDataMode === 'craft'" class="sr-craft-option-pill">BẢN TẠM #{{ idx + 1 }}</span>
                        <strong class="sr-po1-po-num">{{ srDataMode === 'craft' ? 'Phương án' : 'PO' }} <span v-html="highlightSaleText(r.So_PO, searchStr)"></span></strong>
                        <span class="sr-po1-sep">•</span>
                        <span class="sr-po1-plain-meta"><span class="sr-hide-mob">Ngày </span>{{ fmtDate(r.created_time) }}<span class="sr-hide-mob"> (Tháng {{ getMonth(r.created_time) }})</span></span>
                        <template v-if="r.Ten_nha_cung_cap">
                          <span class="sr-po1-sep">•</span>
                          <span class="sr-po1-plain-meta">NCC: <strong v-html="highlightSaleText(r.Ten_nha_cung_cap, searchStr)"></strong></span>
                        </template>
                      </div>

                      <div class="sr-po1-meta-right">
                        <template v-if="srDataMode === 'craft'">
                          <button
                            type="button"
                            class="sr-craft-card-btn is-clone"
                            @click.stop="cloneCraftRow(r)"
                            title="Nhân bản phương án này thành 1 phương án tạm mới để thử kịch bản giá khác"
                          >
                            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>
                            <span>Nhân bản</span>
                          </button>
                          <button
                            type="button"
                            class="sr-craft-card-btn is-chotdeal"
                            @click.stop="promoteCraftToOfficial(r)"
                            title="Chốt Deal phương án này và chuyển sang Bản Chính Thức"
                          >
                            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
                            <span>Chốt Deal</span>
                          </button>
                        </template>
                        <template v-else>
                          <span
                            class="sr-po1-plain-status"
                            :class="congNo(r) <= 0 && tongSauVat(r) > 0 ? 'is-com-text' : 'is-debt-text'"
                          >
                            {{ congNo(r) <= 0 && tongSauVat(r) > 0 ? 'Đã tất toán' : (daThanhToan(r) > 0 && congNo(r) > 0 ? 'Thanh toán 1 phần' : 'Chưa thanh toán') }}
                          </span>
                          <template v-if="congNo(r) > 0 && getPoDueInfo(r).dueBadgeText">
                            <span class="sr-po1-sep">•</span>
                            <span
                              class="sr-po1-plain-due"
                              :class="{ 'is-debt-text': getPoDueInfo(r).dueStatus === 'qua_han' }"
                              @click.stop="openPaymentModal(r)"
                            >
                              {{ getPoDueInfo(r).dueBadgeText }}
                            </span>
                          </template>
                          <span class="sr-po1-sep">|</span>
                          <button
                            type="button"
                            class="sr-po-pay-extend-btn"
                            @click.stop="openPaymentModal(r)"
                          >
                            Thanh toán<span class="sr-hide-mob"> / Gia hạn</span><template v-if="getPaymentHistoryForPO(r).length > 0"> ({{ getPaymentHistoryForPO(r).length }})</template>
                          </button>
                        </template>
                        <button
                          type="button"
                          class="sr-po-collapse-arrow-btn"
                          :class="{ 'is-collapsed': isPoCardCollapsed(r) }"
                          @click.stop="togglePoCardCollapse(r)"
                          :title="isPoCardCollapsed(r) ? 'Mở rộng chi tiết PO' : 'Thu gọn chi tiết PO'"
                        >
                          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">
                            <polyline points="18 15 12 9 6 15" />
                          </svg>
                        </button>
                      </div>
                    </div>

                    <!-- Dòng 2: Nội dung Hợp đồng / PO nằm riêng 1 dòng độc lập nổi bật -->
                    <div class="sr-po1-contract-row">
                      <div class="sr-po1-contract-title" :title="r.content_of_contract_PO || 'Chưa có nội dung hợp đồng'">
                        <span class="sr-po1-contract-prefix">Nội dung HĐ:</span>
                        <span v-html="highlightSaleText(r.content_of_contract_PO || 'Chưa có nội dung hợp đồng', searchStr)"></span>
                      </div>

                      <!-- Khi thu gọn PO 1 dòng: hiện tóm tắt chữ thường ngay bên phải -->
                      <div v-if="isEffectivePoCollapsed(r)" class="sr-po1-collapsed-summary">
                        <span>DSB: <strong class="is-com-text">{{ fmt(doanhSoBan(r)) }}</strong></span>
                        <span class="sr-po1-sep">•</span>
                        <span>Net COM: <strong class="is-com-text">{{ fmt(netCom(r)) }}</strong></span>
                        <span class="sr-po1-sep">•</span>
                        <span>Margin: <strong :class="netMargin(r) >= 0 ? 'is-com-text' : 'is-debt-text'">{{ fmt(netMargin(r)) }}</strong></span>
                        <template v-if="srDataMode !== 'craft'">
                          <span class="sr-po1-sep">•</span>
                          <span>Nợ: <strong :class="congNo(r) > 0 ? 'is-debt-text' : 'is-com-text'">{{ fmt(congNo(r)) }}</strong></span>
                        </template>
                      </div>
                    </div>

                    <!-- Dòng 3 (Ngay dưới Nội dung hợp đồng): 4 Ô Tệp đính kèm cố định (BÁO GIÁ, MUA HÀNG, DXMH, KHÁC) gọn gàng, ngăn nắp -->
                    <div
                      v-if="!isEffectivePoCollapsed(r)"
                      class="sr-po1-contract-files is-4box-grid"
                      @click.stop
                    >
                      <!-- Ô 1: BÁO GIÁ -->
                      <div
                        class="sr-po1-file-box is-emerald"
                        :class="{ 'has-file': Boolean(r.link_excel_bao_gia) }"
                        @click.stop="openMultiEditModalWithDocTab(r, 'bg')"
                        :title="r.link_excel_bao_gia ? (r.ten_file_bao_gia || 'File Báo giá') : 'Nhấp để mở tab Báo giá trong Modal PO'"
                      >
                        <div class="sr-po1-fb-left">
                          <svg v-if="r.link_excel_bao_gia" class="sr-doc-tick-circle" width="14" height="14" viewBox="0 0 24 24" fill="none">
                            <circle cx="12" cy="12" r="10" fill="#10b981"/>
                            <polyline points="16.5 9 10.5 15 7.5 12" stroke="#ffffff" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/>
                          </svg>
                          <span v-else class="sr-po1-fb-dot"></span>
                          <span class="sr-po1-fb-tag">BÁO GIÁ</span>
                          <span class="sr-po1-fb-name">
                            {{ r.link_excel_bao_gia ? (r.ten_file_bao_gia || 'Đã đính kèm') : 'Chưa có file' }}
                          </span>
                        </div>
                        <div v-if="r.link_excel_bao_gia" class="sr-po1-fe-actions">
                          <button type="button" class="sr-po1-fe-btn is-view" @click.stop="openPoFileOfficeView(r.link_excel_bao_gia, r.ten_file_bao_gia)" title="Xem file Báo giá">
                            <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
                            <span>Xem</span>
                          </button>
                          <button type="button" class="sr-po1-fe-btn is-dl" @click.stop="downloadPoFile(r.link_excel_bao_gia, r.ten_file_bao_gia || `Bao_gia_PO_${r.So_PO || ''}`, $event)" title="Tải xuống file Báo giá">
                            <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>
                          </button>
                        </div>
                      </div>

                      <!-- Ô 2: MUA HÀNG -->
                      <div
                        class="sr-po1-file-box is-rose"
                        :class="{ 'has-file': Boolean(r.link_excel_mua_hang) }"
                        @click.stop="openMultiEditModalWithDocTab(r, 'mh')"
                        :title="r.link_excel_mua_hang ? (r.ten_file_mua_hang || 'File Mua hàng') : 'Nhấp để mở tab Mua hàng trong Modal PO'"
                      >
                        <div class="sr-po1-fb-left">
                          <svg v-if="r.link_excel_mua_hang" class="sr-doc-tick-circle" width="14" height="14" viewBox="0 0 24 24" fill="none">
                            <circle cx="12" cy="12" r="10" fill="#10b981"/>
                            <polyline points="16.5 9 10.5 15 7.5 12" stroke="#ffffff" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/>
                          </svg>
                          <span v-else class="sr-po1-fb-dot"></span>
                          <span class="sr-po1-fb-tag">MUA HÀNG</span>
                          <span class="sr-po1-fb-name">
                            {{ r.link_excel_mua_hang ? (r.ten_file_mua_hang || 'Đã đính kèm') : 'Chưa có file' }}
                          </span>
                        </div>
                        <div v-if="r.link_excel_mua_hang" class="sr-po1-fe-actions">
                          <button type="button" class="sr-po1-fe-btn is-view" @click.stop="openPoFileOfficeView(r.link_excel_mua_hang, r.ten_file_mua_hang)" title="Xem file Mua hàng">
                            <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
                            <span>Xem</span>
                          </button>
                          <button type="button" class="sr-po1-fe-btn is-dl" @click.stop="downloadPoFile(r.link_excel_mua_hang, r.ten_file_mua_hang || `Mua_hang_PO_${r.So_PO || ''}`, $event)" title="Tải xuống file Mua hàng">
                            <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>
                          </button>
                        </div>
                      </div>

                      <!-- Ô 3: DXMH -->
                      <div
                        class="sr-po1-file-box is-amber"
                        :class="{ 'has-file': Boolean(r.link_excel_dxmh) }"
                        @click.stop="openMultiEditModalWithDocTab(r, 'dxmh')"
                        :title="r.link_excel_dxmh ? (r.ten_file_dxmh || 'File DXMH') : 'Nhấp để mở tab DXMH trong Modal PO'"
                      >
                        <div class="sr-po1-fb-left">
                          <svg v-if="r.link_excel_dxmh" class="sr-doc-tick-circle" width="14" height="14" viewBox="0 0 24 24" fill="none">
                            <circle cx="12" cy="12" r="10" fill="#10b981"/>
                            <polyline points="16.5 9 10.5 15 7.5 12" stroke="#ffffff" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/>
                          </svg>
                          <span v-else class="sr-po1-fb-dot"></span>
                          <span class="sr-po1-fb-tag">DXMH</span>
                          <span class="sr-po1-fb-name">
                            {{ r.link_excel_dxmh ? (r.ten_file_dxmh || 'Đã đính kèm') : 'Chưa có file' }}
                          </span>
                        </div>
                        <div v-if="r.link_excel_dxmh" class="sr-po1-fe-actions">
                          <button type="button" class="sr-po1-fe-btn is-view" @click.stop="openPoFileOfficeView(r.link_excel_dxmh, r.ten_file_dxmh)" title="Xem file DXMH">
                            <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
                            <span>Xem</span>
                          </button>
                          <button type="button" class="sr-po1-fe-btn is-dl" @click.stop="downloadPoFile(r.link_excel_dxmh, r.ten_file_dxmh || `DXMH_PO_${r.So_PO || ''}`, $event)" title="Tải xuống file DXMH">
                            <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>
                          </button>
                        </div>
                      </div>

                      <!-- Ô 4: KHÁC (Gộp File khác & Ảnh chứng từ) -->
                      <div
                        class="sr-po1-file-box is-purple"
                        :class="{ 'has-file': getPoCardOtherFilesList(r).length > 0 }"
                        @click.stop="openMultiEditModalWithDocTab(r, (r.danh_sach_file_khac && r.danh_sach_file_khac.length > 0) ? 'other' : (r.img_save ? 'img' : 'other'))"
                        :title="getPoCardOtherFilesList(r).length > 0 ? getPoCardOtherFilesList(r).map((f: any) => f.ten_file).join(', ') : 'Nhấp để mở tab File khác trong Modal PO'"
                      >
                        <div class="sr-po1-fb-left">
                          <svg v-if="getPoCardOtherFilesList(r).length > 0" class="sr-doc-tick-circle" width="14" height="14" viewBox="0 0 24 24" fill="none">
                            <circle cx="12" cy="12" r="10" fill="#10b981"/>
                            <polyline points="16.5 9 10.5 15 7.5 12" stroke="#ffffff" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/>
                          </svg>
                          <span v-else class="sr-po1-fb-dot"></span>
                          <span class="sr-po1-fb-tag">
                            KHÁC<template v-if="getPoCardOtherFilesList(r).length > 0"> ({{ getPoCardOtherFilesList(r).length }})</template>
                          </span>
                          <span class="sr-po1-fb-name">
                            {{ getPoCardOtherFilesList(r).length > 0 ? (getPoCardOtherFilesList(r).length === 1 ? getPoCardOtherFilesList(r)[0].ten_file : `${getPoCardOtherFilesList(r).length} tệp đính kèm`) : 'Chưa có file' }}
                          </span>
                        </div>
                        <div v-if="getPoCardOtherFilesList(r).length > 0" class="sr-po1-fe-actions">
                          <button
                            type="button"
                            class="sr-po1-fe-btn is-view"
                            @click.stop="getPoCardOtherFilesList(r).length === 1 ? openPoFileOfficeView(getPoCardOtherFilesList(r)[0].link_file, getPoCardOtherFilesList(r)[0].ten_file, getPoCardOtherFilesList(r)[0].isImage) : openMultiEditModalWithDocTab(r, (r.danh_sach_file_khac && r.danh_sach_file_khac.length > 0) ? 'other' : 'img')"
                            :title="getPoCardOtherFilesList(r).length === 1 ? 'Xem tệp đính kèm' : 'Xem toàn bộ các tệp đính kèm trong Modal PO'"
                          >
                            <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/><circle cx="12" cy="12" r="3"/></svg>
                            <span>{{ getPoCardOtherFilesList(r).length === 1 ? 'Xem' : `Xem (${getPoCardOtherFilesList(r).length})` }}</span>
                          </button>
                          <button
                            type="button"
                            class="sr-po1-fe-btn is-dl"
                            @click.stop="downloadPoFile(getPoCardOtherFilesList(r)[0].link_file, getPoCardOtherFilesList(r)[0].ten_file || `File_PO_${r.So_PO || ''}`, $event)"
                            :title="`Tải xuống: ${getPoCardOtherFilesList(r)[0].ten_file}`"
                          >
                            <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>
                          </button>
                        </div>
                      </div>
                    </div>
                  </div>

                  <!-- 2. 4 KHỐI CHỈ SỐ THEO ĐÚNG NHÓM GỐC (SỐ TIỀN MÀU XANH LÁ / ĐỎ) -->
                  <div v-show="!isEffectivePoCollapsed(r)" class="sr-po1-4blocks" :class="{ 'is-craft-3blocks': srDataMode === 'craft' }">
                    <!-- KHỐI 1: Doanh số bán, Giá mua, Tổng CP đơn hàng -->
                    <div class="sr-po1-block">
                      <div class="sr-po1-block-title is-blue-head">Doanh số &amp; Chi phí</div>
                      <div class="sr-po1-b-row is-primary sr-fin-row-clickable" @click.stop="openMultiEditModal(r, 'doanhSoBan')" title="Nhấp để sửa Doanh số bán">
                        <span class="sr-po1-b-lbl">Doanh số bán</span>
                        <strong class="sr-po1-b-val is-com-text">{{ fmt(doanhSoBan(r)) }}</strong>
                      </div>
                      <div class="sr-po1-b-row sr-fin-row-clickable" @click.stop="openMultiEditModal(r, 'giaMua')" title="Nhấp để sửa Giá mua">
                        <span class="sr-po1-b-lbl">Giá mua</span>
                        <span class="sr-po1-b-val is-debt-text">{{ fmt(giaMua(r)) }}</span>
                      </div>
                      <div class="sr-po1-b-row sr-fin-row-clickable" @click.stop="openMultiEditModal(r, 'tongCP')" title="Nhấp để sửa Tổng CP đơn hàng">
                        <span class="sr-po1-b-lbl"><span class="sr-hide-mob">Tổng CP đơn hàng</span><span class="sr-show-mob-inline">Tổng chi phí</span></span>
                        <span class="sr-po1-b-val is-debt-text">{{ fmt(tongCP(r)) }}</span>
                      </div>
                      <div v-if="srDataMode === 'craft'" class="sr-po1-b-row is-sub-divider">
                        <span class="sr-po1-b-lbl"><span class="sr-hide-mob">Tổng tiền sau VAT</span><span class="sr-show-mob-inline">Tổng sau VAT</span></span>
                        <strong class="sr-po1-b-val is-com-text">{{ fmt(tongSauVat(r)) }}</strong>
                      </div>
                    </div>

                    <!-- KHỐI 2: Net COM, Gross COM, Thuế, Net PO, Net Margin -->
                    <div class="sr-po1-block">
                      <div class="sr-po1-block-title is-green-head">COM, Thuế &amp; Margin</div>
                      <div class="sr-po1-b-row is-primary sr-fin-row-clickable" @click.stop="openMultiEditModal(r, 'netCom')" title="Nhấp để sửa Net COM">
                        <span class="sr-po1-b-lbl">Net COM</span>
                        <strong class="sr-po1-b-val is-com-text">{{ fmt(netCom(r)) }}</strong>
                      </div>
                      <div class="sr-po1-b-row sr-fin-row-clickable" @click.stop="openMultiEditModal(r, 'grossCom')" title="Nhấp để sửa Gross COM">
                        <span class="sr-po1-b-lbl">Gross COM</span>
                        <span class="sr-po1-b-val is-com-text">{{ fmt(grossCom(r)) }}</span>
                      </div>
                      <div class="sr-po1-b-row sr-fin-row-clickable" @click.stop="openMultiEditModal(r, 'taxPct')" title="Nhấp để sửa Thuế">
                        <span class="sr-po1-b-lbl">Thuế {{ thuePct(r) }}%</span>
                        <span class="sr-po1-b-val is-debt-text">{{ fmt(thue(r)) }}</span>
                      </div>
                      <div class="sr-po1-b-row">
                        <span class="sr-po1-b-lbl">Net PO</span>
                        <span class="sr-po1-b-val is-com-text">{{ fmt(netPO(r)) }}</span>
                      </div>
                      <div class="sr-po1-b-row is-sub-divider">
                        <span class="sr-po1-b-lbl">Net Margin</span>
                        <strong class="sr-po1-b-val" :class="netMargin(r) >= 0 ? 'is-com-text' : 'is-debt-text'">{{ fmt(netMargin(r)) }}</strong>
                      </div>
                    </div>

                    <!-- KHỐI 3: Tỉ suất % trên Net PO & trên Doanh số bán -->
                    <div class="sr-po1-block">
                      <div class="sr-po1-block-title is-green-head">Tỉ suất (%)</div>
                      <div class="sr-po1-b-row">
                        <span class="sr-po1-b-lbl">Net COM / Net PO</span>
                        <strong class="sr-po1-b-val is-com-text">{{ pctFmt(netComPct(r)) }}</strong>
                      </div>
                      <div class="sr-po1-b-row">
                        <span class="sr-po1-b-lbl">Net Margin / Net PO</span>
                        <strong class="sr-po1-b-val" :class="netMarginPct(r) >= 0 ? 'is-com-text' : 'is-debt-text'">{{ pctFmt(netMarginPct(r)) }}</strong>
                      </div>
                      <div class="sr-po1-b-row is-sub-divider">
                        <span class="sr-po1-b-lbl">Net COM / <span class="sr-hide-mob">Doanh số bán</span><span class="sr-show-mob-inline">DSB</span></span>
                        <strong class="sr-po1-b-val is-com-text">{{ pctFmt(netComDsbPct(r)) }}</strong>
                      </div>
                      <div class="sr-po1-b-row">
                        <span class="sr-po1-b-lbl">Net Margin / <span class="sr-hide-mob">Doanh số bán</span><span class="sr-show-mob-inline">DSB</span></span>
                        <strong class="sr-po1-b-val" :class="netMarginDsbPct(r) >= 0 ? 'is-com-text' : 'is-debt-text'">{{ pctFmt(netMarginDsbPct(r)) }}</strong>
                      </div>
                    </div>

                    <!-- KHỐI 4: Tổng tiền sau VAT, Đã thanh toán, Công nợ còn lại, Thời gian TT, Hạn thanh toán (Chỉ hiện ở Bản Chính Thức) -->
                    <div v-if="srDataMode !== 'craft'" class="sr-po1-block">
                      <div class="sr-po1-block-title is-red-head">Thanh toán &amp; Công nợ</div>
                      <div class="sr-po1-b-row is-primary">
                        <span class="sr-po1-b-lbl"><span class="sr-hide-mob">Tổng tiền sau VAT</span><span class="sr-show-mob-inline">Tổng sau VAT</span></span>
                        <strong class="sr-po1-b-val is-com-text">{{ fmt(tongSauVat(r)) }}</strong>
                      </div>
                      <div class="sr-po1-b-row sr-fin-row-clickable" @click.stop="openPaymentModal(r)" title="Nhấp để ghi nhận/xem lịch sử thanh toán">
                        <span class="sr-po1-b-lbl">Đã thanh toán</span>
                        <span class="sr-po1-b-val is-com-text">{{ fmt(daThanhToan(r)) }}</span>
                      </div>
                      <div class="sr-po1-b-row sr-fin-row-clickable" @click.stop="openPaymentModal(r)" title="Nhấp để ghi nhận/xem lịch sử thanh toán">
                        <span class="sr-po1-b-lbl"><span class="sr-hide-mob">Công nợ còn lại</span><span class="sr-show-mob-inline">Công nợ</span></span>
                        <strong class="sr-po1-b-val" :class="congNo(r) > 0 ? 'is-debt-text' : 'is-com-text'">{{ fmt(congNo(r)) }}</strong>
                      </div>
                      <div class="sr-po1-b-row is-sub-divider">
                        <span class="sr-po1-b-lbl">Thời gian TT</span>
                        <span class="sr-po1-b-val">{{ r.thoi_gian_thanh_toan ? fmtDate(r.thoi_gian_thanh_toan) : 'Chưa TT' }}</span>
                      </div>
                      <div class="sr-po1-b-row sr-fin-row-clickable" @click.stop="openPaymentModal(r)" title="Nhấp để thiết lập mốc thời gian / đợt thanh toán">
                        <span class="sr-po1-b-lbl">
                          <span class="sr-hide-mob">Hạn thanh toán</span><span class="sr-show-mob-inline">Hạn TT</span><template v-if="getPoDueInfo(r).loaiThanhToan === 'nhieu_dot'"> (Đợt {{ getPoDueInfo(r).currentDot }}/{{ getPoDueInfo(r).totalDots }})</template>
                        </span>
                        <span class="sr-po1-b-val" :class="congNo(r) <= 0 ? 'is-com-text' : (getPoDueInfo(r).dueStatus === 'qua_han' ? 'is-debt-text' : '')">
                          {{ getPoDueInfo(r).nextDueDate || 'Chưa đặt hạn' }}
                        </span>
                      </div>
                    </div>
                  </div>

                  <div class="sr-po1-note-line" v-if="!isEffectivePoCollapsed(r) && r.ghi_chu">
                    <span class="sr-po1-files-label">Ghi chú:</span>
                    <span v-html="highlightSaleText(r.ghi_chu, searchStr)"></span>
                  </div>
                </div>
              </div>

              <!-- Sentinel Lazy Loading tự động tải thêm Card PO trong nhóm công ty khi cuộn xuống -->
              <div
                v-if="hasMoreGroupPoItems(group)"
                v-po-lazy-observer="() => loadMoreGroupPoItems(group)"
                class="sr-po-lazy-sentinel"
              >
                <button type="button" class="sr-po-lazy-more-btn" @click.stop="loadMoreGroupPoItems(group)">
                  <span>Đang hiển thị {{ getVisibleGroupPoItems(group).length }} / {{ group.items.length }} {{ srDataMode === 'craft' ? 'phương án' : 'PO' }} • Tải thêm ({{ group.items.length - getVisibleGroupPoItems(group).length }})</span>
                </button>
              </div>
            </div>
          </div>

          <div
            v-if="(isMobileShell ? mobileActiveTab === 'overview' : layoutViewMode === 'stacked-groups') && displayLimit < filteredRows.length"
            v-po-lazy-observer="loadMore"
            class="sr-po-lazy-sentinel is-global-sentinel"
          >
            <button type="button" @click="loadMore" class="sr-po-lazy-more-btn">
              <span>Đang hiển thị {{ Math.min(displayLimit, filteredRows.length) }} / {{ filteredRows.length }} {{ srDataMode === 'craft' ? 'phương án' : 'bản ghi PO' }} • Xem thêm ({{ filteredRows.length - displayLimit }})</span>
            </button>
          </div>
        </div>
      </div>
    </div>

    <!-- ================== MODAL BỘ LỌC KHÁCH HÀNG (KH) ================== -->
    <Teleport to="body">
      <div
        v-if="showFilterCustomerModal"
        class="sr-modal-overlay"
        :class="{ 'theme-light-blue': uiTheme === 'light' }"
        @click.self="showFilterCustomerModal = false"
        style="z-index: 100080;"
      >
        <div class="sr-filter-picker-modal" :class="{ 'is-light': uiTheme === 'light' }">
          <!-- Header -->
          <div class="sr-fpm-header">
            <div class="sr-fpm-header-left">
              <span class="sr-fpm-icon is-sky">
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M23 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>
              </span>
              <div class="sr-fpm-title-wrap">
                <div class="sr-fpm-title-row">
                  <h3 class="sr-fpm-title">Lọc Theo Khách Hàng / Công Ty</h3>
                  <span class="sr-fpm-badge">{{ uniqueCustomers.length }} CÔNG TY</span>
                </div>
                <p class="sr-fpm-sub">Chọn một công ty để lọc danh sách đơn hàng PO hoặc chọn Tất cả khách hàng</p>
              </div>
            </div>
            <button type="button" class="sr-add-choice-close" @click="showFilterCustomerModal = false" title="Đóng cửa sổ">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
            </button>
          </div>

          <!-- Search & Quick All Toolbar -->
          <div class="sr-fpm-toolbar">
            <div class="sr-fpm-search-box">
              <svg class="sr-fpm-search-icon" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
              <input
                v-model="customerPickerSearch"
                type="text"
                class="sr-fpm-search-input"
                placeholder="Tìm nhanh theo Tên công ty, Người nhận (Tên KH), Mã KH, MST..."
              />
              <button v-if="customerPickerSearch" type="button" class="sr-fpm-search-clear" @click="customerPickerSearch = ''" title="Xóa từ khóa">&times;</button>
            </div>
            <button
              type="button"
              class="sr-fpm-all-btn"
              :class="{ active: !filterCustomer || filterCustomer === 'Tất cả' }"
              @click="filterCustomer = 'Tất cả'; showFilterCustomerModal = false"
            >
              <span>Tất cả khách hàng ({{ uniqueCustomers.length }})</span>
              <svg v-if="!filterCustomer || filterCustomer === 'Tất cả'" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
            </button>
            <span class="sr-fpm-count-tag">{{ filteredPickerCustomers.length }} kết quả</span>
          </div>

          <!-- Body List -->
          <div class="sr-fpm-body custom-scrollbar">
            <div v-if="filteredPickerCustomers.length === 0" class="sr-fpm-empty">
              Không tìm thấy công ty / khách hàng nào phù hợp với từ khóa "{{ customerPickerSearch }}".
            </div>
            <div v-else class="sr-fpm-list">
              <button
                v-for="c in filteredPickerCustomers"
                :key="c.companyName + c.companyCode"
                type="button"
                class="sr-fpm-item"
                :class="{ active: filterCustomer === c.companyName }"
                @click="filterCustomer = c.companyName; showFilterCustomerModal = false"
              >
                <div class="sr-fpm-item-main">
                  <div class="sr-fpm-item-title-row">
                    <strong class="sr-fpm-item-name" v-html="highlightSaleText(c.companyName, customerPickerSearch)"></strong>
                    <span v-if="filterCustomer === c.companyName" class="sr-fpm-selected-pill">Đang chọn</span>
                  </div>
                  <div class="sr-fpm-item-meta">
                    <span v-if="c.customerName" class="sr-fpm-meta-chip">
                      Người nhận: <strong v-html="highlightSaleText(c.customerName, customerPickerSearch)"></strong>
                    </span>
                    <span v-if="c.companyCode" class="sr-fpm-meta-chip is-code">
                      Mã: <strong v-html="highlightSaleText(c.companyCode, customerPickerSearch)"></strong>
                    </span>
                    <span v-if="c.mst" class="sr-fpm-meta-chip is-mono">
                      MST: <strong v-html="highlightSaleText(c.mst, customerPickerSearch)"></strong>
                    </span>
                  </div>
                </div>

                <div class="sr-fpm-item-right">
                  <div class="sr-fpm-metrics">
                    <span class="sr-fpm-metric-pill is-po">{{ c.poCount || 0 }} PO</span>
                    <span class="sr-fpm-metric-pill is-dsb">DSB: {{ fmt(c.totalDsb || 0) }}</span>
                    <span v-if="c.totalCongNo > 0" class="sr-fpm-metric-pill is-debt">Nợ: {{ fmt(c.totalCongNo) }}</span>
                    <span v-else class="sr-fpm-metric-pill is-settled">Hết nợ</span>
                  </div>
                  <span class="sr-fpm-choose-btn" :class="{ active: filterCustomer === c.companyName }">
                    {{ filterCustomer === c.companyName ? 'Đang chọn' : 'Chọn' }}
                  </span>
                </div>
              </button>
            </div>
          </div>

          <!-- Footer -->
          <div class="sr-fpm-footer">
            <div class="sr-fpm-footer-info">
              Đang lọc:
              <strong>{{ !filterCustomer || filterCustomer === 'Tất cả' ? 'Tất cả khách hàng' : filterCustomer }}</strong>
            </div>
            <div class="sr-fpm-footer-actions">
              <button
                v-if="filterCustomer && filterCustomer !== 'Tất cả'"
                type="button"
                class="sr-fpm-reset-btn"
                @click="filterCustomer = 'Tất cả'; showFilterCustomerModal = false"
              >
                Bỏ lọc (Chọn Tất cả)
              </button>
              <button type="button" class="sr-add-choice-cancel" @click="showFilterCustomerModal = false">Đóng</button>
            </div>
          </div>
        </div>
      </div>
    </Teleport>

    <!-- ================== MODAL BỘ LỌC NHÀ CUNG CẤP (NCC / PRODUCT TYPE) ================== -->
    <Teleport to="body">
      <div
        v-if="showFilterNccModal"
        class="sr-modal-overlay"
        :class="{ 'theme-light-blue': uiTheme === 'light' }"
        @click.self="showFilterNccModal = false"
        style="z-index: 100080;"
      >
        <div class="sr-filter-picker-modal is-ncc-modal" :class="{ 'is-light': uiTheme === 'light' }">
          <!-- Header -->
          <div class="sr-fpm-header">
            <div class="sr-fpm-header-left">
              <span class="sr-fpm-icon is-emerald">
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/><polyline points="3.27 6.96 12 12.01 20.73 6.96"/><line x1="12" y1="22.08" x2="12" y2="12"/></svg>
              </span>
              <div class="sr-fpm-title-wrap">
                <div class="sr-fpm-title-row">
                  <h3 class="sr-fpm-title">Lọc Theo Nhà Cung Cấp (NCC / Product Type)</h3>
                  <span class="sr-fpm-badge is-emerald">{{ uniqueProductTypes.length }} NCC</span>
                </div>
                <p class="sr-fpm-sub">Chọn Nhà cung cấp / Product Type để lọc danh sách đơn hàng PO</p>
              </div>
            </div>
            <button type="button" class="sr-add-choice-close" @click="showFilterNccModal = false" title="Đóng cửa sổ">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
            </button>
          </div>

          <!-- Search & Quick All Toolbar -->
          <div class="sr-fpm-toolbar">
            <div class="sr-fpm-search-box">
              <svg class="sr-fpm-search-icon" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg>
              <input
                v-model="productPickerSearch"
                type="text"
                class="sr-fpm-search-input"
                placeholder="Tìm nhanh Nhà cung cấp / Product Type..."
              />
              <button v-if="productPickerSearch" type="button" class="sr-fpm-search-clear" @click="productPickerSearch = ''" title="Xóa từ khóa">&times;</button>
            </div>
            <button
              type="button"
              class="sr-fpm-all-btn"
              :class="{ active: filterProductType === 'Tất cả' }"
              @click="filterProductType = 'Tất cả'; showFilterNccModal = false"
            >
              <span>Tất cả Nhà cung cấp ({{ uniqueProductTypes.length }})</span>
              <svg v-if="filterProductType === 'Tất cả'" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
            </button>
            <span class="sr-fpm-count-tag">{{ filteredPickerProductTypes.length }} kết quả</span>
          </div>

          <!-- Body Grid -->
          <div class="sr-fpm-body custom-scrollbar">
            <div v-if="filteredPickerProductTypes.length === 0" class="sr-fpm-empty">
              Không tìm thấy Nhà cung cấp nào phù hợp với từ khóa "{{ productPickerSearch }}".
            </div>
            <div v-else class="sr-fpm-ncc-grid">
              <button
                v-for="pt in filteredPickerProductTypes"
                :key="pt"
                type="button"
                class="sr-fpm-ncc-card"
                :class="{ active: filterProductType === pt }"
                @click="filterProductType = pt; showFilterNccModal = false"
              >
                <div class="sr-fpm-ncc-top">
                  <strong class="sr-fpm-ncc-name" v-html="highlightSaleText(pt, productPickerSearch)"></strong>
                  <span class="sr-fpm-choose-btn" :class="{ active: filterProductType === pt }">
                    {{ filterProductType === pt ? 'Đang chọn' : 'Chọn' }}
                  </span>
                </div>
                <div class="sr-fpm-ncc-foot">
                  <span class="sr-fpm-metric-pill is-po">{{ getPoCountByProductType(pt) }} PO</span>
                  <span class="sr-fpm-metric-pill is-dsb">DSB: {{ fmt(getDsbByProductType(pt)) }}</span>
                </div>
              </button>
            </div>
          </div>

          <!-- Footer -->
          <div class="sr-fpm-footer">
            <div class="sr-fpm-footer-info">
              Đang lọc:
              <strong>{{ filterProductType === 'Tất cả' ? 'Tất cả Nhà cung cấp' : filterProductType }}</strong>
            </div>
            <div class="sr-fpm-footer-actions">
              <button
                v-if="filterProductType !== 'Tất cả'"
                type="button"
                class="sr-fpm-reset-btn"
                @click="filterProductType = 'Tất cả'; showFilterNccModal = false"
              >
                Bỏ lọc (Chọn Tất cả)
              </button>
              <button type="button" class="sr-add-choice-cancel" @click="showFilterNccModal = false">Đóng</button>
            </div>
          </div>
        </div>
      </div>
    </Teleport>

    <!-- Thanh nổi thao tác nhanh khi chọn Card PO hoặc Card Công ty -->
    <Teleport to="body">
      <div
        v-if="selectedPoRows.length > 0 && !multiEditModal.show && !showExportModal && !paymentModal.show && !showCraftCompareModal && !reviewMindmapModal.show"
        class="sr-selection-floating-bar"
      >
        <div class="sr-sel-bar-info">
          <span class="sr-sel-count-badge">
            <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
            Đã chọn: {{ selectedPoRows.length }}
          </span>
        </div>
        <div class="sr-sel-bar-actions">
          <button
            type="button"
            class="sr-sel-btn sr-sel-btn-mindmap"
            @click="openCompareMindmapReview()"
            title="Mở Sơ đồ Tư duy (Mindmap) & Thuyết minh giọng đọc cho các PO đang chọn"
          >
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="6" cy="12" r="3"/><circle cx="18" cy="6" r="3"/><circle cx="18" cy="18" r="3"/><path d="M8.7 10.7l6.6-3.4"/><path d="M8.7 13.3l6.6 3.4"/></svg>
            <span>Review PO</span>
          </button>
          <button
            type="button"
            class="sr-sel-btn sr-sel-btn-compare"
            @click="openCraftCompareModal()"
            title="Mở bảng Phân tích & So sánh chỉ số giữa các PO đang chọn"
          >
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="20" x2="18" y2="10"/><line x1="12" y1="20" x2="12" y2="4"/><line x1="6" y1="20" x2="6" y2="14"/></svg>
            <span>So sánh</span>
          </button>
          <button
            type="button"
            class="sr-sel-btn sr-sel-btn-export"
            :disabled="exporting"
            @click="exportSelectedPoRowsDirectly()"
          >
            <svg v-if="exporting" class="spin" xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 12a9 9 0 1 1-6.219-8.56"/></svg>
            <span>{{ exporting ? 'Đang xuất...' : 'Xuất Excel' }}</span>
          </button>
          <button
            type="button"
            class="sr-sel-btn sr-sel-btn-preview"
            @click="viewSelectedPoRows()"
          >
            Xem tất cả
          </button>
          <button
            type="button"
            class="sr-sel-btn sr-sel-btn-clear"
            @click="clearSelectedPoRows()"
          >
            Bỏ chọn
          </button>
          <button
            type="button"
            class="sr-sel-btn sr-sel-btn-delete-all"
            @click="deleteSelectedPoRows()"
          >
            Xóa tất cả PO
          </button>
        </div>
      </div>
    </Teleport>

    <div v-if="loading" class="sr-loading">
      <div class="sr-spinner"></div>
      <p>Đang tải dữ liệu Sale Report...</p>
    </div>

    <!-- Multi Edit Modal (Fullscreen 100% — Đồng bộ Bento Style Dark Emerald / Light Blue) -->
    <Teleport to="body">
      <div
        v-if="multiEditModal.show"
        class="sr-modal-overlay sr-po-modal-overlay"
        :class="{ 'theme-light-blue': uiTheme === 'light', 'is-craft-overlay': srDataMode === 'craft', 'no-anim': isSwitchingTab }"
        @click.self="requestCloseMultiEditModal()"
        style="z-index: 10000;"
      >
        <div
          class="sr-modal sr-modal-large sr-po-modal is-fullscreen-100"
          :class="{ 'is-light': uiTheme === 'light', 'is-craft-modal': srDataMode === 'craft', 'no-anim': isSwitchingTab }"
        >
          <!-- 1. STICKY TOP HEADER -->
          <div class="sr-import-card-header sr-po-modal-header" v-if="activeModalItem">
            <div class="sr-po-header-left">
              <span class="sr-po-header-icon">
                <svg v-if="multiEditModal.mode === 'create'" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="12" y1="18" x2="12" y2="12"/><line x1="9" y1="15" x2="15" y2="15"/></svg>
                <svg v-else width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/></svg>
              </span>
              <div class="sr-po-header-titles">
                <div class="sr-po-header-title-row">
                  <h4 class="sr-po-header-title">
                    {{ (activeModalItem as any)._clonedFromRow ? 'Nhân bản phương án PO' : (multiEditModal.mode === 'create' ? (srDataMode === 'craft' ? 'Tạo mới phương án PO' : 'Tạo mới đơn hàng PO') : (srDataMode === 'craft' ? 'Chỉnh sửa phương án PO' : 'Chỉnh sửa đơn hàng PO')) }}
                  </h4>
                  <span class="sr-po-mode-badge">
                    {{ (activeModalItem as any)._clonedFromRow ? 'NHÂN BẢN PHƯƠNG ÁN' : (multiEditModal.mode === 'create' ? (srDataMode === 'craft' ? 'KHỞI TẠO PHƯƠNG ÁN' : 'KHỞI TẠO PO MỚI') : 'CHỈNH SỬA PO') }}
                  </span>
                  <span v-if="false && activeModalItem.soPO" class="sr-po-index-badge">
                    PO #{{ activeModalItem.soPO }}
                  </span>
                  <span v-if="multiEditModal.items.length > 1" class="sr-po-index-badge">
                    Đơn {{ activeItemIdx + 1 }} / {{ multiEditModal.items.length }}
                  </span>
                </div>
                <p class="sr-po-header-sub">
                  {{ activeModalItem.customer ? `Khách hàng: ${activeModalItem.customer}` : (multiEditModal.mode === 'create' ? 'Điền thông tin tổng quan, chỉ số tài chính, bảng hàng hóa và đính kèm chứng từ cho đơn hàng' : 'Cập nhật hồ sơ đơn hàng PO, bảng hàng hóa, thanh toán và chứng từ đính kèm') }}
                </p>
              </div>
            </div>

            <div class="sr-po-header-actions">
              <button
                v-if="multiEditModal.mode === 'create'"
                type="button"
                class="sr-po-header-add-btn"
                @click="addAnotherBlankPOInModal()"
                title="Thêm 1 đơn hàng PO trống nữa vào phiên tạo mới"
              >
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
                <span>Thêm PO trống</span>
              </button>

              <div class="sr-po-pane-layout-btns">
                <button
                  type="button"
                  class="sr-po-layout-btn"
                  :class="{ active: !isPoLeftPaneCollapsed && !isPoLeftPaneWide }"
                  @click="isPoLeftPaneCollapsed = false; isPoLeftPaneWide = false"
                  title="Chế độ chuẩn (Cột chứng từ 450px)"
                >
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="18" height="18" rx="2"/><line x1="9" y1="3" x2="9" y2="21"/></svg>
                  <span>Chuẩn</span>
                </button>
                <button
                  type="button"
                  class="sr-po-layout-btn"
                  :class="{ active: !isPoLeftPaneCollapsed && isPoLeftPaneWide }"
                  @click="isPoLeftPaneCollapsed = false; isPoLeftPaneWide = true"
                  title="Mở rộng khung xem trước chứng từ 50:50"
                >
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="18" height="18" rx="2"/><line x1="12" y1="3" x2="12" y2="21"/></svg>
                  <span>50 : 50</span>
                </button>
                <button
                  type="button"
                  class="sr-po-layout-btn"
                  :class="{ active: isPoLeftPaneCollapsed }"
                  @click="isPoLeftPaneCollapsed = !isPoLeftPaneCollapsed"
                  title="Thu gọn cột chứng từ để mở rộng tối đa phần dữ liệu"
                >
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="3" width="18" height="18" rx="2"/><path d="M15 12H9m0 0 3-3m-3 3 3 3"/></svg>
                  <span>{{ isPoLeftPaneCollapsed ? 'Hiện File' : 'Ẩn File' }}</span>
                </button>
              </div>

              <button
                type="button"
                class="sr-po-header-close"
                @click="requestCloseMultiEditModal()"
                title="Đóng cửa sổ"
              >
                <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>
              </button>
            </div>
          </div>

          <!-- 2. MULTI-PO SESSION STRIP (Khi có nhiều PO trong phiên) -->
          <div
            v-if="multiEditModal.items.length > 1"
            class="sr-po-session-bar"
          >
            <div class="sr-po-session-tabs sr-scroll">
              <button
                v-for="(it, sIdx) in multiEditModal.items"
                :key="it.id"
                type="button"
                class="sr-po-session-tab"
                :class="{ active: sIdx === activeItemIdx }"
                @click="activeItemIdx = sIdx"
              >
                <span class="sr-po-session-num">#{{ sIdx + 1 }}</span>
                <span class="sr-po-session-po">PO {{ it.soPO || 'Mới' }}</span>
                <span class="sr-po-session-cust">{{ it.customer || it.content || 'Chưa đặt tên' }}</span>
                <span v-if="getAttachedDocCount(it) > 0" class="sr-po-session-doc-pill">{{ getAttachedDocCount(it) }} file</span>
              </button>
              <button
                v-if="multiEditModal.mode === 'create'"
                type="button"
                class="sr-po-session-add-btn"
                @click="addAnotherBlankPOInModal()"
                title="Thêm 1 đơn hàng PO trống nữa vào phiên tạo mới"
              >
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>
                <span>Thêm PO trống</span>
              </button>
            </div>
            <div v-if="multiEditModal.items.length > 1" class="sr-po-session-nav">
              <button
                type="button"
                class="sr-po-nav-btn"
                :disabled="activeItemIdx <= 0"
                @click="activeItemIdx = Math.max(0, activeItemIdx - 1)"
              >
                ‹ Trước
              </button>
              <span class="sr-po-nav-counter">{{ activeItemIdx + 1 }} / {{ multiEditModal.items.length }}</span>
              <button
                type="button"
                class="sr-po-nav-btn"
                :disabled="activeItemIdx >= multiEditModal.items.length - 1"
                @click="activeItemIdx = Math.min(multiEditModal.items.length - 1, activeItemIdx + 1)"
              >
                Sau ›
              </button>
            </div>
          </div>

          <!-- 3. MOBILE PANE SWITCHER (<= 1080px) -->
          <div v-if="activeModalItem" class="sr-po-mobile-switch">
            <button
              type="button"
              class="sr-po-mob-switch-btn"
              :class="{ active: mobilePoPane === 'form' }"
              @click="mobilePoPane = 'form'"
            >
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><rect x="3" y="3" width="18" height="18" rx="2"/><line x1="3" y1="9" x2="21" y2="9"/><line x1="9" y1="21" x2="9" y2="9"/></svg>
              <span>Thông tin &amp; Tài chính</span>
            </button>
            <button
              type="button"
              class="sr-po-mob-switch-btn"
              :class="{ active: mobilePoPane === 'docs' }"
              @click="mobilePoPane = 'docs'"
            >
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>
              <span>Chứng từ &amp; Xem trước ({{ getAttachedDocCount(activeModalItem) }})</span>
            </button>
          </div>

          <!-- 4. MAIN FULL-HEIGHT WORKSPACE BODY -->
          <div class="sr-modal-body sr-po-modal-scroll">
            <div v-if="multiEditModal.items.length === 0" class="sr-po-empty">
              Không có dữ liệu
            </div>
            <template
              v-for="(item, idx) in multiEditModal.items"
              :key="item.id || idx"
            >
            <div
              v-if="idx === activeItemIdx || (multiEditModal.items.length === 1 && idx === 0)"
              class="sr-po-card-shell"
            >
              <div class="sr-import-card-body sr-po-card-body" @input="isModalDirty = true" @change="isModalDirty = true">
                <div
                  class="sr-po-workspace"
                  :class="{
                    'is-left-collapsed': isPoLeftPaneCollapsed,
                    'is-left-wide': !isPoLeftPaneCollapsed && isPoLeftPaneWide,
                    'mob-show-docs': mobilePoPane === 'docs'
                  }"
                >
                  <!-- COLLAPSED LEFT RAIL (When Left Pane is Collapsed on PC) -->
                  <div v-if="isPoLeftPaneCollapsed" class="sr-po-left-rail">
                    <button
                      type="button"
                      class="sr-po-rail-expand-btn"
                      @click="isPoLeftPaneCollapsed = false"
                      title="Mở cột Chứng từ & Xem trước"
                    >
                      <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><path d="M9 12h6m0 0-3-3m3 3-3 3"/><rect x="3" y="3" width="18" height="18" rx="2"/></svg>
                    </button>
                    <button type="button" class="sr-po-rail-doc-btn is-emerald" :class="{ 'has-file': hasItemBgPreview(item) }" @click="setActivePreviewTab(item, 'bg')" title="File Báo giá">
                      <span>BG</span>
                      <svg v-if="hasItemBgPreview(item)" class="sr-rail-tick-circle" width="12" height="12" viewBox="0 0 24 24" fill="none" aria-hidden="true"><circle cx="12" cy="12" r="10" fill="#10b981"/><polyline points="16.5 9 10.5 15 7.5 12" stroke="#ffffff" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"/></svg>
                    </button>
                    <button type="button" class="sr-po-rail-doc-btn is-rose" :class="{ 'has-file': hasItemMhPreview(item) }" @click="setActivePreviewTab(item, 'mh')" title="File Mua hàng">
                      <span>MH</span>
                      <svg v-if="hasItemMhPreview(item)" class="sr-rail-tick-circle" width="12" height="12" viewBox="0 0 24 24" fill="none" aria-hidden="true"><circle cx="12" cy="12" r="10" fill="#10b981"/><polyline points="16.5 9 10.5 15 7.5 12" stroke="#ffffff" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"/></svg>
                    </button>
                    <button type="button" class="sr-po-rail-doc-btn is-amber" :class="{ 'has-file': hasItemDxmhPreview(item) }" @click="setActivePreviewTab(item, 'dxmh')" title="File DXMH">
                      <span>DX</span>
