                                  { 'is-expanded': isMindmapPoExpanded(r) },
                                  getTourPoNodeClass(r, g)
                                ]"
                                @click.stop="onMindmapPoCardClick(r, g)"
                              >
                                <div class="sr-mm-node-head">
                                  <div class="sr-mm-head-left">
                                    <strong class="sr-mm-po-code">PO #{{ r.So_PO || 'Mới' }}</strong>
                                    <span class="sr-mm-po-date">{{ fmtDate(r.created_time) }}</span>
                                    <span v-if="r.Ten_nha_cung_cap" class="sr-mm-ncc-tag">{{ r.Ten_nha_cung_cap }}</span>
                                  </div>
                                  <span
                                    class="sr-mm-status-tag"
                                    :class="congNo(r) <= 0 && tongSauVat(r) > 0 ? 'is-settled' : (getPoDueInfo(r).dueStatus === 'qua_han' ? 'is-overdue' : 'is-debt')"
                                  >
                                    {{ congNo(r) <= 0 && tongSauVat(r) > 0 ? 'Đã tất toán' : (getPoDueInfo(r).dueBadgeText || 'Còn nợ') }}
                                  </span>
                                </div>

                                <div class="sr-mm-po-contract" :title="r.content_of_contract_PO">
                                  {{ r.content_of_contract_PO || 'Chưa có nội dung hợp đồng' }}
