                                  <div class="sr-mm-kv">
                                    <span>Net COM ({{ pctFmt(netComPct(r)) }})</span>
                                    <strong class="is-emerald-val">{{ fmt(netCom(r)) }} đ</strong>
                                  </div>
                                  <div class="sr-mm-kv">
                                    <span>Đã thanh toán</span>
                                    <strong class="is-emerald-val">{{ fmt(daThanhToan(r)) }} đ</strong>
                                  </div>
                                  <div class="sr-mm-kv">
                                    <span>Công nợ còn lại</span>
                                    <strong :class="congNo(r) > 0 ? 'is-rose-val' : 'is-emerald-val'">{{ fmt(congNo(r)) }} đ</strong>
