                                      <div class="sr-mm-leaf-row"><span>Người phụ trách (AM)</span><strong>{{ r.account_manager_name || '—' }}</strong></div>
                                      <div class="sr-mm-leaf-row">
                                        <span>Chứng từ đính kèm</span>
                                        <strong>
                                          {{ [r.link_excel_bao_gia ? 'BG' : '', r.link_excel_mua_hang ? 'MH' : '', r.link_excel_dxmh ? 'DXMH' : '', getPoCardOtherFilesList(r).length > 0 ? ('Khác(' + getPoCardOtherFilesList(r).length + ')') : ''].filter(Boolean).join(' • ') || 'Chưa đính kèm' }}
                                        </strong>
                                      </div>
                                      <div v-if="r.ghi_chu" class="sr-mm-leaf-row"><span>Ghi chú</span><strong>{{ r.ghi_chu }}</strong></div>
                                    </div>
                                    <button type="button" class="sr-mm-leaf-cta is-blue" @click.stop="openMultiEditModal(r)">Mở Chi tiết &amp; Chứng từ PO</button>
                                  </div>
                                </div>
                              </div>
                            </div>
