                @click="dbCustomerPickerModal.searchQuery = ''"
                style="position: absolute; right: 10px; background: none; border: none; color: #94a3b8; cursor: pointer; font-size: 14px;"
              >
                ✕
              </button>
            </div>
            <span
              v-if="getMatchedDbCustomerForItem(dbCustomerPickerModal.targetItem)"
              style="display: inline-flex; align-items: center; gap: 6px; padding: 5px 11px; border-radius: 999px; background: rgba(16, 185, 129, 0.14); border: 1px solid rgba(16, 185, 129, 0.4); color: #34d399; font-size: 11.5px; font-weight: 800;"
            >
              <svg class="sr-doc-tick-circle" width="13" height="13" viewBox="0 0 24 24" fill="none">
                <circle cx="12" cy="12" r="10" fill="#10b981"/>
                <polyline points="16.5 9 10.5 15 7.5 12" stroke="#ffffff" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/>
              </svg>
              <span>Đang chọn: {{ getMatchedDbCustomerForItem(dbCustomerPickerModal.targetItem).ten_cong_ty || getMatchedDbCustomerForItem(dbCustomerPickerModal.targetItem).ten_khach_hang }}</span>
            </span>
            <span style="font-size: 12px; font-weight: 700; color: #38bdf8; white-space: nowrap;">
              {{ filteredDbCustomerModalList.length }} kết quả
            </span>
          </div>

          <div class="custom-scrollbar" style="flex: 1; min-height: 0; overflow-y: auto; padding: 14px 20px;">
            <table v-if="filteredDbCustomerModalList.length > 0" style="width: 100%; border-collapse: collapse; font-size: 12.5px; color: #e2e8f0;">
              <thead>
                <tr style="background: rgba(30, 41, 59, 0.75); border-bottom: 1px solid #334155; text-align: left; color: #94a3b8; font-size: 11px; text-transform: uppercase;">
                  <th style="padding: 9px 12px;">Tên Công ty / Đơn vị</th>
                  <th style="padding: 9px 12px; width: 175px;">Người nhận (Tên KH)</th>
                  <th style="padding: 9px 12px; width: 125px;">Mã số thuế</th>
                  <th style="padding: 9px 12px; width: 150px;">Ngành hàng</th>
                  <th style="padding: 9px 12px; width: 225px; text-align: center;">Thao tác</th>
                </tr>
              </thead>
              <tbody>
                <tr
                  v-for="c in filteredDbCustomerModalList"
                  :key="c.id || c.ma_khach_hang"
