            <div v-if="false && paymentModal.row" style="display: flex; align-items: center; gap: 8px; flex-wrap: wrap;">
              <button
                type="button"
                @click="openScheduleSubModal"
                style="display: inline-flex; align-items: center; gap: 6px; background: #0284c7; color: #ffffff; border: none; border-radius: 7px; padding: 8px 14px; font-size: 11.5px; font-weight: 800; text-transform: uppercase; cursor: pointer; width: fit-content; margin: 0; box-shadow: 0 2px 6px rgba(2, 132, 199, 0.28);"
              >
                <span>Thiết lập Kế hoạch / Hạn thanh toán</span>
              </button>

              <button
                type="button"
                @click="openRecordPaymentSubModal()"
                style="display: inline-flex; align-items: center; gap: 6px; background: linear-gradient(135deg, #10b981, #059669); color: #ffffff; border: none; border-radius: 7px; padding: 8px 15px; font-size: 11.5px; font-weight: 800; text-transform: uppercase; cursor: pointer; box-shadow: 0 2px 8px rgba(16, 185, 129, 0.28); width: fit-content; margin: 0;"
              >
                <span>+ Ghi nhận đợt thanh toán mới</span>
              </button>
            </div>
          </div>

          <!-- MAIN FULLSCREEN WORKSPACE (DESKTOP) -->
          <div class="dt-only-debt-view" style="padding: 18px 32px; overflow: hidden; flex: 1; min-height: 0; display: flex; flex-direction: column; gap: 16px;">
            <!-- 4 KPI CARDS -->
            <div style="display: grid; grid-template-columns: repeat(4, minmax(180px, 1fr)); gap: 14px; flex-shrink: 0;">
              <div class="cust-group-box cust-group-company" style="background: rgba(56, 189, 248, 0.06); border: 1px solid rgba(56, 189, 248, 0.25); border-radius: 10px; padding: 12px 16px;">
                <div style="font-size: 11px; color: #94a3b8; font-weight: 800; text-transform: uppercase;">
                  {{ paymentModal.row ? 'Tổng tiền sau VAT (PO)' : 'Tổng phải thu toàn KH' }}
                </div>
                <div style="font-size: 19px; font-weight: 900; color: #38bdf8; margin-top: 4px;">
                  {{ fmt(paymentModal.row ? tongSauVat(paymentModal.row) : getCustomerDebtSummary(paymentModal.customer).tongSauVat) }} đ
                </div>
              </div>

              <div class="cust-group-box cust-group-main" style="background: rgba(16, 185, 129, 0.06); border: 1px solid rgba(16, 185, 129, 0.25); border-radius: 10px; padding: 12px 16px;">
                <div style="font-size: 11px; color: #94a3b8; font-weight: 800; text-transform: uppercase;">
                  {{ paymentModal.row ? 'Khách đã thanh toán (PO)' : 'Đã thanh toán toàn KH' }}
                </div>
                <div style="font-size: 19px; font-weight: 900; color: #10b981; margin-top: 4px;">
                  {{ fmt(paymentModal.row ? daThanhToan(paymentModal.row) : getCustomerDebtSummary(paymentModal.customer).daThanhToan) }} đ
                </div>
              </div>

              <div class="cust-group-box cust-group-sub" style="background: rgba(239, 68, 68, 0.05); border: 1px solid rgba(239, 68, 68, 0.28); border-radius: 10px; padding: 12px 16px;">
                <div style="font-size: 11px; color: #94a3b8; font-weight: 800; text-transform: uppercase;">Công nợ còn lại (PO)</div>
                <div
                  style="font-size: 19px; font-weight: 900; margin-top: 4px;"
                  :style="{ color: (paymentModal.row ? congNo(paymentModal.row) : getCustomerDebtSummary(paymentModal.customer).congNo) > 0 ? '#ef4444' : '#10b981' }"
                >
                  {{ fmt(paymentModal.row ? congNo(paymentModal.row) : getCustomerDebtSummary(paymentModal.customer).congNo) }} đ
                </div>
              </div>

              <div class="cust-group-box cust-group-sub" style="background: rgba(245, 158, 11, 0.06); border: 1px solid rgba(245, 158, 11, 0.3); border-radius: 10px; padding: 12px 16px;">
                <div style="font-size: 11px; color: #94a3b8; font-weight: 800; text-transform: uppercase;">Tổng nợ toàn KH ({{ paymentModal.customerPOs.length }} PO)</div>
                <div style="font-size: 19px; font-weight: 900; color: #fbbf24; margin-top: 4px;">
                  {{ fmt(getCustomerDebtSummary(paymentModal.customer).congNo) }} đ
                </div>
              </div>
            </div>

            <!-- QUICK ACTION BUTTONS BELOW TỔNG NỢ TOÀN KH CARD (PC) -->
            <div v-if="paymentModal.row" class="sr-debt-pc-actions-under-kpi" style="display: flex; justify-content: flex-end; align-items: center; gap: 10px; flex-wrap: wrap; margin-top: -6px; flex-shrink: 0;">
              <button
                type="button"
                @click="openScheduleSubModal"
                style="display: inline-flex; align-items: center; gap: 6px; background: #0284c7; color: #ffffff; border: none; border-radius: 8px; padding: 8px 15px; font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.02em; cursor: pointer; width: fit-content; margin: 0; box-shadow: 0 2px 6px rgba(2, 132, 199, 0.28);"
              >
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="18" rx="2" ry="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>
                <span>Thiết lập Kế hoạch / Hạn thanh toán</span>
              </button>

              <button
                type="button"
                @click="openRecordPaymentSubModal()"
                style="display: inline-flex; align-items: center; gap: 6px; background: linear-gradient(135deg, #10b981, #059669); color: #ffffff; border: none; border-radius: 8px; padding: 8px 16px; font-size: 12px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.02em; cursor: pointer; box-shadow: 0 2px 8px rgba(16, 185, 129, 0.28); width: fit-content; margin: 0;"
              >
                <span>+ Ghi nhận đợt thanh toán mới</span>
              </button>
            </div>

            <!-- 2-COLUMN SPLIT: LEFT PO SIDEBAR + RIGHT TABLES -->
            <div style="flex: 1; min-height: 0; display: grid; grid-template-columns: 310px 1fr; gap: 18px; overflow: hidden;">
              <!-- LEFT SIDEBAR: DANH SÁCH PO CỦA KHÁCH HÀNG -->
              <div class="cust-group-box cust-group-sub" style="background: rgba(148,163,184,0.04); border: 1px solid rgba(148,163,184,0.16); border-radius: 10px; padding: 14px 16px; display: flex; flex-direction: column; gap: 10px; min-height: 0; overflow: hidden;">
                <div class="cust-group-title-sub" style="font-size: 11.5px; text-transform: uppercase; font-weight: 800; color: #ffffff; letter-spacing: 0.6px; flex-shrink: 0;">
                  DANH SÁCH ĐƠN HÀNG PO ({{ paymentModal.customerPOs.length }})
                </div>

                <div v-if="paymentModal.customerPOs.length > 0" class="custom-scrollbar" style="flex: 1; min-height: 0; overflow-y: auto; display: flex; flex-direction: column; gap: 8px; padding-right: 4px;">
                  <div
                    v-for="po in paymentModal.customerPOs"
                    :key="po._firebaseKey || po.ID"
                    class="sr-debt-po-side-item"
                    :class="{ 'is-active': paymentModal.row && ((paymentModal.row._firebaseKey && paymentModal.row._firebaseKey === po._firebaseKey) || (paymentModal.row.ID && paymentModal.row.ID === po.ID)) }"
                    @click="selectPoInPaymentModal(po)"
                    style="padding: 11px 12px; border-radius: 9px; cursor: pointer; display: flex; flex-direction: column; gap: 6px; transition: all 0.2s;"
                    :style="{
                      background: paymentModal.row && ((paymentModal.row._firebaseKey && paymentModal.row._firebaseKey === po._firebaseKey) || (paymentModal.row.ID && paymentModal.row.ID === po.ID))
                        ? 'rgba(2, 132, 199, 0.14)'
                        : 'rgba(148, 163, 184, 0.08)',
                      border: paymentModal.row && ((paymentModal.row._firebaseKey && paymentModal.row._firebaseKey === po._firebaseKey) || (paymentModal.row.ID && paymentModal.row.ID === po.ID))
                        ? '2px solid #0284c7'
                        : '1px solid rgba(148, 163, 184, 0.25)'
                    }"
                  >
                    <div style="display: flex; justify-content: space-between; align-items: flex-start; gap: 8px;">
                      <div style="flex: 1; min-width: 0; display: flex; flex-direction: column; gap: 3px;">
                        <span
                          :title="getPoContractContent(po)"
                          style="font-size: 12.5px; font-weight: 800; color: #38bdf8; line-height: 1.35; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; word-break: break-word;"
                        >
                          {{ getPoContractContent(po) }}
                        </span>
                        <span v-if="getPoCreatedDateShort(po)" style="font-size: 10.5px; color: #94a3b8; font-weight: 600;">
                          Ngày tạo: {{ getPoCreatedDateShort(po) }}
                        </span>
                      </div>
                      <span
                        style="padding: 2px 8px; border-radius: 999px; font-size: 10.5px; font-weight: 800; flex-shrink: 0; white-space: nowrap;"
                        :style="{
                          background: congNo(po) > 0 ? 'rgba(239, 68, 68, 0.15)' : 'rgba(16, 185, 129, 0.16)',
                          color: congNo(po) > 0 ? '#ef4444' : '#10b981'
                        }"
                      >
                        {{ congNo(po) > 0 ? 'Còn nợ' : 'Đã tất toán' }}
                      </span>
                    </div>
                    <div class="sr-debt-po-side-row" style="display: flex; justify-content: space-between; align-items: center; font-size: 11.5px; color: #cbd5e1;">
                      <span>Tổng sau VAT:</span>
                      <strong class="sr-debt-po-vat-val" style="color: #10b981;">{{ fmt(tongSauVat(po)) }} đ</strong>
                    </div>
                    <div style="display: flex; justify-content: space-between; align-items: center; font-size: 11.5px; color: #cbd5e1;">
                      <span>Còn nợ:</span>
                      <strong :style="{ color: congNo(po) > 0 ? '#ef4444' : '#10b981' }">{{ fmt(congNo(po)) }} đ</strong>
                    </div>
                  </div>
                </div>
                <div v-else style="flex: 1; display: flex; align-items: center; justify-content: center; border: 1px dashed rgba(148,163,184,0.3); border-radius: 8px; padding: 18px; text-align: center; color: #64748b; font-size: 12.5px;">
                  Khách hàng này hiện chưa có đơn hàng (PO) nào trong <code>sale_report</code>.
                </div>
              </div>

              <!-- RIGHT MAIN AREA: 2 TABLES STACKED & FLEX-EXPANDED -->
              <div style="display: flex; flex-direction: column; gap: 14px; min-height: 0; overflow: hidden;">
                <!-- BẢNG 1: TIẾN ĐỘ KẾ HOẠCH & MỐC HẠN THANH TOÁN -->
                <div
                  v-if="paymentModal.row"
                  class="cust-group-box cust-group-company"
                  style="background: rgba(56,189,248,0.04); border: 1px solid rgba(56,189,248,0.16); border-radius: 10px; padding: 14px 18px; display: flex; flex-direction: column; gap: 10px; max-height: 45%; min-height: 175px; overflow: hidden;"
                >
                  <div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 8px; flex-shrink: 0;">
                    <span style="font-size: 12px; font-weight: 800; color: #38bdf8; text-transform: uppercase; letter-spacing: 0.5px;">
                      Tiến độ Kế hoạch &amp; Mốc hạn thanh toán ({{ modalEvaluatedInstallments.length }} đợt)
                    </span>
                    <button
                      type="button"
                      @click="openScheduleSubModal"
                      style="background: rgba(2, 132, 199, 0.12); color: #38bdf8; border: 1px solid rgba(56, 189, 248, 0.35); border-radius: 6px; padding: 4px 10px; font-size: 11px; font-weight: 800; cursor: pointer; width: fit-content; margin: 0;"
                    >
                      Chỉnh sửa mốc hạn / Chia đợt
                    </button>
                  </div>

                  <div class="quote-table-wrap custom-scrollbar" style="flex: 1; min-height: 0; overflow: auto;">
                    <table style="width: 100%; min-width: 720px; border-collapse: collapse; font-size: 12px; color: #e2e8f0;">
                      <thead>
                        <tr style="background: rgba(15, 23, 42, 0.85); border-bottom: 1px solid rgba(148, 163, 184, 0.22); color: #94a3b8; font-size: 11px; text-transform: uppercase;">
                          <th style="padding: 9px 12px; width: 55px; text-align: left;">Đợt</th>
                          <th style="padding: 9px 12px; text-align: left;">Nội dung đợt</th>
                          <th style="padding: 9px 12px; text-align: right; width: 80px;">Tỷ lệ</th>
                          <th style="padding: 9px 12px; text-align: right;">Phải thu</th>
                          <th style="padding: 9px 12px; text-align: right;">Đã thu</th>
                          <th style="padding: 9px 12px; text-align: right;">Còn thiếu</th>
                          <th style="padding: 9px 12px; text-align: left;">Mốc hạn TT</th>
                          <th style="padding: 9px 12px; text-align: left;">Trạng thái hạn</th>
                          <th style="padding: 9px 12px; text-align: center; width: 110px;">Thu nhanh</th>
                        </tr>
                      </thead>
                      <tbody>
                        <tr v-for="(inst, idx) in modalEvaluatedInstallments" :key="idx" style="border-bottom: 1px dashed rgba(148, 163, 184, 0.16);">
                          <td style="padding: 9px 12px; font-weight: 800; color: #c084fc;">#{{ inst.dot }}</td>
                          <td style="padding: 9px 12px; font-weight: 600; color: #f8fafc;">{{ inst.noi_dung }}</td>
                          <td style="padding: 9px 12px; text-align: right; font-weight: 700; color: #38bdf8;">{{ inst.ty_le_pct }}%</td>
                          <td style="padding: 9px 12px; text-align: right; font-weight: 700; color: #e2e8f0;">{{ fmt(inst.so_tien_phai_thu) }} đ</td>
                          <td style="padding: 9px 12px; text-align: right; font-weight: 700; color: #10b981;">{{ fmt(inst.da_thu) }} đ</td>
                          <td style="padding: 9px 12px; text-align: right; font-weight: 700;" :style="{ color: inst.con_thieu > 0 ? '#ef4444' : '#64748b' }">
                            {{ fmt(inst.con_thieu) }} đ
                          </td>
                          <td style="padding: 9px 12px; font-family: monospace; font-weight: 700; color: #cbd5e1;">
                            {{ inst.han_thanh_toan || 'Chưa đặt hạn' }}
                          </td>
                          <td style="padding: 9px 12px;">
                            <span
                              :style="{
                                display: 'inline-flex',
                                alignItems: 'center',
                                gap: '4px',
                                padding: '3px 8px',
                                borderRadius: '999px',
                                fontSize: '11px',
                                fontWeight: '700',
                                color: inst.statusColor,
                                background: 'rgba(148, 163, 184, 0.12)',
                                border: `1px solid ${inst.statusColor}`
                              }"
                            >
                              <span>{{ inst.statusLabel }}</span>
                            </span>
                          </td>
                          <td style="padding: 9px 12px; text-align: center;">
                            <button
                              v-if="inst.con_thieu > 0"
                              type="button"
                              @click="openRecordPaymentSubModal(inst)"
                              style="background: #10b981; color: #ffffff; border: none; border-radius: 6px; padding: 5px 10px; font-size: 11px; font-weight: 800; cursor: pointer; white-space: nowrap; width: fit-content; margin: 0;"
                            >
                              Thu đợt này
                            </button>
                            <span v-else style="font-size: 11px; color: #10b981; font-weight: 800;">Hoàn tất</span>
                          </td>
                        </tr>
                      </tbody>
                    </table>
                  </div>
                </div>

                <!-- BẢNG 2: LỊCH SỬ THANH TOÁN THỰC TẾ -->
                <div
                  class="cust-group-box cust-group-main"
                  style="background: rgba(16,185,129,0.04); border: 1px solid rgba(16,185,129,0.16); border-radius: 10px; padding: 14px 18px; display: flex; flex-direction: column; gap: 10px; flex: 1; min-height: 0; overflow: hidden;"
                >
                  <div style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 8px; flex-shrink: 0;">
                    <span
                      :title="paymentModal.row ? getPoContractContent(paymentModal.row) : ''"
                      style="font-size: 12px; font-weight: 800; color: #10b981; text-transform: uppercase; letter-spacing: 0.5px;"
                    >
                      Lịch sử thanh toán thực tế {{ paymentModal.row ? ('— ' + getPoContractContent(paymentModal.row, 56)) : 'của Khách hàng' }}
                      ({{ currentModalPaymentHistory.length }} lần)
                    </span>
                  </div>

                  <div class="quote-table-wrap custom-scrollbar" style="flex: 1; min-height: 0; overflow: auto;">
                    <table style="width: 100%; min-width: 780px; border-collapse: collapse; font-size: 12px; color: #e2e8f0;">
                      <thead>
                        <tr style="background: rgba(15, 23, 42, 0.85); border-bottom: 1px solid rgba(148, 163, 184, 0.22); color: #94a3b8; font-size: 11px; text-transform: uppercase;">
                          <th style="padding: 10px 12px; width: 56px; text-align: left;">Lần</th>
                          <th style="padding: 10px 12px; text-align: left; white-space: nowrap;">Thời gian TT</th>
                          <th style="padding: 10px 12px; text-align: left;">Tên KH</th>
                          <th style="padding: 10px 12px; text-align: left;">Tên Công ty</th>
                          <th style="padding: 10px 12px; text-align: right; white-space: nowrap;">Số tiền thanh toán</th>
                          <th style="padding: 10px 12px; text-align: right; white-space: nowrap;">Công nợ còn lại</th>
                          <th style="padding: 10px 12px; text-align: left;">Ghi chú</th>
                          <th style="padding: 10px 12px; text-align: center; width: 65px;">Xóa</th>
                        </tr>
                      </thead>
                      <tbody>
                        <tr v-for="(h, idx) in currentModalPaymentHistory" :key="h.id || idx" style="border-bottom: 1px dashed rgba(148, 163, 184, 0.16);">
                          <td
                            :title="h.id ? ('Mã GD: ' + h.id) : ''"
                            style="padding: 10px 12px; font-weight: 800; color: #38bdf8;"
                          >
                            #{{ currentModalPaymentHistory.length - idx }}
                          </td>
                          <td style="padding: 10px 12px; font-weight: 600; color: #f8fafc; white-space: nowrap;">{{ h.thoi_gian_thanh_toan || '—' }}</td>
                          <td style="padding: 10px 12px; font-weight: 600; color: #e2e8f0;">{{ getPaymentHistoryCustomerInfo(h).tenKH }}</td>
                          <td style="padding: 10px 12px; font-weight: 600; color: #cbd5e1; max-width: 220px; word-break: break-word;">{{ getPaymentHistoryCustomerInfo(h).tenCongTy }}</td>
                          <td style="padding: 10px 12px; text-align: right; font-weight: 800; color: #10b981; white-space: nowrap;">+{{ fmt(toNum(h.so_tien_thanh_toan)) }} đ</td>
                          <td style="padding: 10px 12px; text-align: right; font-weight: 800; white-space: nowrap;" :style="{ color: toNum(h.cong_no_con_lai) > 0 ? '#ef4444' : '#10b981' }">
                            {{ fmt(toNum(h.cong_no_con_lai)) }} đ
                          </td>
                          <td style="padding: 10px 12px; color: #94a3b8;">{{ h.ghi_chu || '—' }}</td>
                          <td style="padding: 10px 12px; text-align: center;">
                            <button
                              v-if="paymentModal.row"
                              type="button"
                              @click="deletePaymentHistoryItem(h)"
                              title="Xóa đợt thanh toán này và hoàn lại công nợ"
                              style="background: rgba(239, 68, 68, 0.14); color: #ef4444; border: 1px solid rgba(239, 68, 68, 0.35); border-radius: 6px; padding: 5px 9px; font-weight: 700; cursor: pointer; width: fit-content; margin: 0;"
                            >
                              Xóa
                            </button>
                          </td>
                        </tr>
                        <tr v-if="currentModalPaymentHistory.length === 0">
                          <td colspan="8" style="padding: 28px; text-align: center; color: #64748b; font-style: italic;">
                            Chưa có lịch sử thanh toán nào.
                          </td>
                        </tr>
                      </tbody>
                    </table>
                  </div>
                </div>
              </div>
            </div>
          </div>

          <!-- MOBILE FINTECH WORKSPACE (<= 1100px) -->
          <div class="m-debt-body">
            <!-- 1. COMPACT CUSTOMER IDENTITY & PLAN CARD -->
            <div class="m-debt-cust-card">
              <div class="m-debt-cust-top">
                <div class="m-debt-cust-name">
                  {{ paymentModal.customer?.Ten_cong_ty || paymentModal.customer?.Ten_khach_hang || paymentModal.row?.Ten_cong_ty || paymentModal.row?.Ten_khach_hang || 'Khách hàng' }}
                </div>
                <span class="m-debt-cust-code">{{ paymentModal.customer?.Ma_khach_hang || paymentModal.row?.Ma_khach_hang || 'N/A' }}</span>
              </div>

              <div v-if="paymentModal.row" class="m-debt-plan-row">
                <span class="m-debt-plan-badge" :class="paymentModal.scheduleMode === 'nhieu_dot' ? 'is-multi' : 'is-single'">
                  <svg class="m-debt-plan-ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="4" width="18" height="18" rx="2" ry="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>
                  <span v-if="paymentModal.scheduleMode === 'nhieu_dot'">Chia {{ modalEvaluatedInstallments.length }} đợt thanh toán</span>
                  <span v-else>Thanh toán 1 lần • Hạn: {{ paymentModal.singleDueDate || 'Chưa đặt' }}</span>
                </span>

                <button type="button" class="m-debt-plan-edit-btn" @click="openScheduleSubModal">
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/></svg>
                  <span>Sửa hạn</span>
                </button>
              </div>
            </div>

            <!-- 2. BENTO 2x2 KPI GRID + PROGRESS BAR -->
            <div class="m-debt-kpi-section">
              <div class="m-debt-bento-grid">
                <div class="m-debt-kpi-tile is-sky">
                  <div class="m-debt-kpi-lbl">{{ paymentModal.row ? 'Tổng sau VAT (PO)' : 'Tổng phải thu KH' }}</div>
                  <div class="m-debt-kpi-val">
                    {{ fmt(paymentModal.row ? tongSauVat(paymentModal.row) : getCustomerDebtSummary(paymentModal.customer).tongSauVat) }} đ
                  </div>
                </div>

                <div class="m-debt-kpi-tile is-emerald">
                  <div class="m-debt-kpi-lbl">{{ paymentModal.row ? 'Đã thanh toán' : 'Đã thu toàn KH' }}</div>
                  <div class="m-debt-kpi-val">
                    {{ fmt(paymentModal.row ? daThanhToan(paymentModal.row) : getCustomerDebtSummary(paymentModal.customer).daThanhToan) }} đ
                  </div>
                </div>

                <div
                  class="m-debt-kpi-tile"
                  :class="(paymentModal.row ? congNo(paymentModal.row) : getCustomerDebtSummary(paymentModal.customer).congNo) > 0 ? 'is-rose' : 'is-emerald'"
                >
                  <div class="m-debt-kpi-lbl">Công nợ còn lại</div>
                  <div class="m-debt-kpi-val">
                    {{ fmt(paymentModal.row ? congNo(paymentModal.row) : getCustomerDebtSummary(paymentModal.customer).congNo) }} đ
                  </div>
                </div>

                <div class="m-debt-kpi-tile is-amber">
                  <div class="m-debt-kpi-lbl">Tổng nợ KH ({{ paymentModal.customerPOs.length }} PO)</div>
                  <div class="m-debt-kpi-val">
                    {{ fmt(getCustomerDebtSummary(paymentModal.customer).congNo) }} đ
                  </div>
                </div>
              </div>

              <div class="m-debt-progress-card">
                <div class="m-debt-progress-head">
                  <span class="m-debt-progress-lbl" :title="paymentModal.row ? getPoContractContent(paymentModal.row) : ''">
                    Tiến độ thanh toán{{ paymentModal.row ? (' • ' + getPoContractContent(paymentModal.row, 28)) : '' }}
                  </span>
                  <span class="m-debt-progress-pct" :class="{ 'is-done': modalDebtProgressPct >= 100 }">{{ modalDebtProgressPct }}%</span>
                </div>
                <div class="m-debt-progress-track">
                  <div class="m-debt-progress-fill" :style="{ width: modalDebtProgressPct + '%' }"></div>
                </div>
              </div>
            </div>

            <!-- 3. HORIZONTAL SCROLLABLE PO PILLS -->
            <div class="m-debt-po-strip">
              <div class="m-debt-sec-head">
                <span class="m-debt-sec-title">Đơn hàng PO ({{ paymentModal.customerPOs.length }})</span>
                <span v-if="paymentModal.customerPOs.length > 1" class="m-debt-sec-hint">Vuốt ngang để chọn PO</span>
              </div>

              <div v-if="paymentModal.customerPOs.length > 0" class="m-debt-po-scroll">
                <button
                  v-for="po in paymentModal.customerPOs"
                  :key="'m-po-' + (po._firebaseKey || po.ID)"
                  type="button"
                  class="m-debt-po-pill"
                  :title="getPoContractContent(po)"
                  :class="{
                    'is-active': paymentModal.row && ((paymentModal.row._firebaseKey && paymentModal.row._firebaseKey === po._firebaseKey) || (paymentModal.row.ID && paymentModal.row.ID === po.ID)),
                    'is-paid': congNo(po) <= 0
                  }"
                  @click="selectPoInPaymentModal(po)"
                >
                  <span class="m-debt-po-code">{{ getPoContractContent(po) }}</span>
                  <span class="m-debt-po-sep">•</span>
                  <span class="m-debt-po-state">{{ congNo(po) > 0 ? ('Nợ ' + fmt(congNo(po)) + ' đ') : 'Đã tất toán' }}</span>
                </button>
              </div>
              <div v-else class="m-debt-po-empty">
                Khách hàng hiện chưa có đơn hàng PO nào trên hệ thống.
              </div>
            </div>

            <!-- 4. SEGMENTED TABS & FINTECH CARDS -->
            <div class="m-debt-tabs-wrap">
              <div v-if="paymentModal.row" class="m-debt-tabs">
                <button
                  type="button"
                  class="m-debt-tab-btn"
                  :class="{ active: mobileDebtActiveTab === 'schedule' }"
                  @click="mobileDebtActiveTab = 'schedule'"
                >
                  <span>Kế hoạch &amp; Mốc hạn</span>
                  <span class="m-debt-tab-count">{{ modalEvaluatedInstallments.length }}</span>
                </button>
                <button
                  type="button"
                  class="m-debt-tab-btn"
                  :class="{ active: mobileDebtActiveTab === 'history' }"
                  @click="mobileDebtActiveTab = 'history'"
                >
                  <span>Lịch sử đã thu</span>
                  <span class="m-debt-tab-count">{{ currentModalPaymentHistory.length }}</span>
                </button>
              </div>
              <div v-else class="m-debt-sec-head">
                <span class="m-debt-sec-title">Lịch sử thanh toán ({{ currentModalPaymentHistory.length }})</span>
              </div>

              <!-- TAB 1: KE HOACH & MOC HAN THANH TOAN -->
              <div v-if="paymentModal.row && mobileDebtActiveTab === 'schedule'" class="m-debt-card-list">
                <div v-for="(inst, idx) in modalEvaluatedInstallments" :key="'m-inst-' + idx" class="m-debt-inst-card">
                  <div class="m-debt-inst-head">
                    <div class="m-debt-inst-title-group">
                      <span class="m-debt-inst-dot">#{{ inst.dot }}</span>
                      <span class="m-debt-inst-pct">{{ inst.ty_le_pct }}%</span>
                      <span class="m-debt-inst-name">{{ inst.noi_dung }}</span>
                    </div>
                    <span class="m-debt-inst-status" :class="'status-' + inst.status">{{ inst.statusLabel }}</span>
                  </div>

                  <div class="m-debt-inst-metrics">
                    <div class="m-debt-metric-col">
                      <span class="m-debt-metric-lbl">Phải thu</span>
                      <strong class="m-debt-metric-val">{{ fmt(inst.so_tien_phai_thu) }} đ</strong>
                    </div>
                    <div class="m-debt-metric-col">
                      <span class="m-debt-metric-lbl">Đã thu</span>
                      <strong class="m-debt-metric-val is-emerald">{{ fmt(inst.da_thu) }} đ</strong>
                    </div>
                    <div class="m-debt-metric-col">
                      <span class="m-debt-metric-lbl">Còn thiếu</span>
                      <strong class="m-debt-metric-val" :class="inst.con_thieu > 0 ? 'is-rose' : 'is-muted'">{{ fmt(inst.con_thieu) }} đ</strong>
                    </div>
                  </div>

                  <div class="m-debt-inst-foot">
                    <div class="m-debt-inst-due">
                      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>
                      <span>Hạn TT: <strong>{{ inst.han_thanh_toan || 'Chưa đặt hạn' }}</strong></span>
                    </div>
                    <button
                      v-if="inst.con_thieu > 0"
                      type="button"
                      class="m-debt-inst-pay-btn"
                      @click="openRecordPaymentSubModal(inst)"
                    >
                      Thu đợt này
                    </button>
                    <span v-else class="m-debt-inst-done-tag">Hoàn tất</span>
                  </div>
                </div>
              </div>

              <!-- TAB 2: LICH SU DA THU -->
              <div v-if="!paymentModal.row || mobileDebtActiveTab === 'history'" class="m-debt-card-list">
                <template v-if="currentModalPaymentHistory.length > 0">
                  <div v-for="(h, idx) in currentModalPaymentHistory" :key="'m-hist-' + (h.id || idx)" class="m-debt-hist-card">
                    <div class="m-debt-hist-top">
                      <div class="m-debt-hist-meta">
                        <span class="m-debt-hist-idx" :title="h.id ? ('Mã GD: ' + h.id) : ''">Lần #{{ currentModalPaymentHistory.length - idx }}</span>
                        <span class="m-debt-hist-time">{{ h.thoi_gian_thanh_toan || '—' }}</span>
                      </div>
                      <span class="m-debt-hist-amt">+{{ fmt(toNum(h.so_tien_thanh_toan)) }} đ</span>
                    </div>

                    <div class="m-debt-hist-cust-info">
                      <span v-if="getPaymentHistoryCustomerInfo(h).tenKH !== '—'" class="m-debt-hist-kh">
                        KH: <strong>{{ getPaymentHistoryCustomerInfo(h).tenKH }}</strong>
                      </span>
                      <span v-if="getPaymentHistoryCustomerInfo(h).tenCongTy !== '—'" class="m-debt-hist-cty">
                        Cty: <strong>{{ getPaymentHistoryCustomerInfo(h).tenCongTy }}</strong>
                      </span>
                    </div>

                    <div class="m-debt-hist-mid">
                      <span class="m-debt-hist-rem">
                        Dư nợ sau GD:
                        <strong :class="toNum(h.cong_no_con_lai) > 0 ? 'is-rose' : 'is-emerald'">
                          {{ fmt(toNum(h.cong_no_con_lai)) }} đ
                        </strong>
                      </span>
                      <button
                        v-if="paymentModal.row"
                        type="button"
                        class="m-debt-hist-del-btn"
                        title="Xóa đợt thanh toán này và hoàn lại công nợ"
                        @click="deletePaymentHistoryItem(h)"
                      >
                        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>
                        <span>Xóa</span>
                      </button>
                    </div>

                    <div v-if="h.ghi_chu" class="m-debt-hist-note">{{ h.ghi_chu }}</div>
                  </div>
                </template>

                <div v-else class="m-debt-empty-box">
                  <svg class="m-debt-empty-ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="2" y="5" width="20" height="14" rx="2"/><line x1="2" y1="10" x2="22" y2="10"/></svg>
                  <div class="m-debt-empty-title">Chưa có lịch sử thanh toán</div>
                  <div class="m-debt-empty-sub">Các đợt khách hàng thanh toán thực tế sẽ được lưu tại đây.</div>
                  <button
                    v-if="paymentModal.row"
                    type="button"
                    class="m-debt-empty-cta"
                    @click="openRecordPaymentSubModal()"
                  >
                    + Ghi nhận đợt thanh toán đầu tiên
                  </button>
                </div>
              </div>
            </div>
          </div>

          <!-- FOOTER -->
          <div class="cust-modal-footer fullscreen-modal-footer debt-modal-footer" style="padding: 14px 32px; background: rgba(15, 23, 42, 0.95); border-top: 1px solid rgba(255,255,255,0.08); display: flex; justify-content: flex-end; flex-shrink: 0; border-radius: 0 !important;">
            <button type="button" class="modal-btn-secondary btn-debt-close" @click="paymentModal.show = false" style="padding: 10px 24px; border-radius: 8px; background: rgba(255,255,255,0.1); color: #f8fafc; border: 1px solid rgba(255,255,255,0.2); font-weight: 700; cursor: pointer; width: fit-content; margin: 0;">Đóng</button>
            <button v-if="paymentModal.row" type="button" class="m-only-debt-btn btn-debt-schedule" @click="openScheduleSubModal">Kế hoạch hạn</button>
            <button v-if="paymentModal.row" type="button" class="m-only-debt-btn btn-debt-record" @click="openRecordPaymentSubModal()">+ Ghi nhận TT</button>
          </div>
        </div>
      </div>

      <!-- SUB-MODAL 1: Thiết lập Kế hoạch & Mốc thời gian phải thanh toán -->
      <div v-if="paymentModal.show && paymentModal.row && paymentModal.showScheduleSubModal" class="sr-modal-overlay" :class="{ 'is-light': uiTheme === 'light', 'theme-light-blue': uiTheme === 'light' }" @click.self="paymentModal.showScheduleSubModal = false" style="z-index: 100065; padding: 20px; background: rgba(2, 6, 23, 0.78);">
        <div class="sr-modal debt-schedule-submodal" :class="{ 'is-light': uiTheme === 'light' }" style="max-width: 920px; width: 95vw; background: #0f172a; border: 1px solid rgba(56, 189, 248, 0.4); border-radius: 16px; overflow: hidden; display: flex; flex-direction: column; max-height: 90vh; box-shadow: 0 20px 50px rgba(0, 0, 0, 0.65);">
          <div class="sr-debt-head" style="padding: 14px 22px; margin-bottom: 0; border-radius: 0; display: flex; justify-content: space-between; align-items: center;">
            <div style="min-width: 0; padding-right: 12px;">
              <h4 :title="getPoContractContent(paymentModal.row)" style="margin: 0; color: #ffffff !important; font-size: 15px; font-weight: 800; text-transform: uppercase;">
                Thiết lập Kế hoạch &amp; Mốc hạn thanh toán — {{ getPoContractContent(paymentModal.row, 52) }}
              </h4>
              <div style="font-size: 12px; color: #ffffff; opacity: 0.9; margin-top: 2px;">
                Tổng giá trị PO sau VAT: <strong>{{ fmt(tongSauVat(paymentModal.row)) }} đ</strong>
                • Đã thu: <strong>{{ fmt(daThanhToan(paymentModal.row)) }} đ</strong>
              </div>
            </div>
            <button @click="paymentModal.showScheduleSubModal = false" style="color: #fff; background: rgba(0,0,0,0.18); border-radius: 50%; width: 28px; height: 28px; display: flex; align-items: center; justify-content: center; border: none; cursor: pointer;">✕</button>
          </div>

          <div class="debt-sub-body custom-scrollbar" style="padding: 18px 22px; overflow-y: auto; flex: 1; display: flex; flex-direction: column; gap: 16px;">
            <div class="debt-sub-seg" style="display: inline-flex; background: rgba(148, 163, 184, 0.12); border: 1px solid rgba(148, 163, 184, 0.3); border-radius: 8px; padding: 3px; gap: 4px; align-self: flex-start;">
              <button
                type="button"
                @click="setScheduleMode('mot_lan')"
                :style="{
                  background: paymentModal.scheduleMode === 'mot_lan' ? '#0284c7' : 'transparent',
                  color: paymentModal.scheduleMode === 'mot_lan' ? '#ffffff' : '#94a3b8',
                  border: 'none',
                  borderRadius: '6px',
                  padding: '6px 14px',
                  fontSize: '12px',
                  fontWeight: '700',
                  cursor: 'pointer'
                }"
              >
                Thanh toán 1 lần (100%)
              </button>
              <button
                type="button"
                @click="setScheduleMode('nhieu_dot')"
                :style="{
                  background: paymentModal.scheduleMode === 'nhieu_dot' ? '#7c3aed' : 'transparent',
                  color: paymentModal.scheduleMode === 'nhieu_dot' ? '#ffffff' : '#94a3b8',
                  border: 'none',
                  borderRadius: '6px',
                  padding: '6px 14px',
                  fontSize: '12px',
                  fontWeight: '700',
                  cursor: 'pointer'
                }"
              >
                Chia theo đợt (% khác nhau)
              </button>
            </div>

            <!-- Chế độ 1: Thanh toán 1 lần (100%) -->
            <div v-if="paymentModal.scheduleMode === 'mot_lan'" style="display: flex; align-items: center; justify-content: space-between; gap: 14px; flex-wrap: wrap; background: rgba(30, 41, 59, 0.45); border: 1px solid #1e293b; border-radius: 10px; padding: 16px;">
              <div style="display: flex; align-items: center; gap: 14px; flex-wrap: wrap; width: 100%;">
                <div class="debt-due-field-wrap">
                  <label style="font-size: 11.5px; color: #cbd5e1; font-weight: 600; display: block; margin-bottom: 6px;">Mốc hạn thanh toán (DD/MM/YYYY)</label>
                  <div class="debt-due-inputs-row" style="display: flex; align-items: center; gap: 8px;">
                    <input
                      type="text"
                      v-model="paymentModal.singleDueDate"
                      placeholder="DD/MM/YYYY"
                      class="sr-modal-input"
                      style="width: 140px; padding: 8px 10px; font-size: 13px; font-weight: 700; color: #f8fafc; font-family: 'JetBrains Mono', monospace;"
                    />
                    <input
                      type="date"
                      :value="ddmmyyyyToIso(paymentModal.singleDueDate)"
                      @change="onSingleDueDatePickerChange"
                      class="sr-modal-input"
                      style="padding: 7px 10px; font-size: 12.5px; color: #cbd5e1; width: 155px;"
                    />
                  </div>
                </div>

                <div>
                  <label style="font-size: 11.5px; color: #cbd5e1; font-weight: 600; display: block; margin-bottom: 6px;">Chọn nhanh hạn TT (từ ngày tạo PO)</label>
                  <div class="debt-sub-chips" style="display: flex; gap: 6px; flex-wrap: wrap;">
                    <button type="button" @click="setSingleDueDateDays(7, true)" style="background: rgba(51, 65, 85, 0.55); color: #cbd5e1; border: 1px solid #475569; border-radius: 6px; padding: 6px 10px; font-size: 11.5px; font-weight: 600; cursor: pointer;">+7 ngày</button>
                    <button type="button" @click="setSingleDueDateDays(15, true)" style="background: rgba(51, 65, 85, 0.55); color: #cbd5e1; border: 1px solid #475569; border-radius: 6px; padding: 6px 10px; font-size: 11.5px; font-weight: 600; cursor: pointer;">+15 ngày</button>
                    <button type="button" @click="setSingleDueDateDays(30, true)" style="background: rgba(51, 65, 85, 0.55); color: #cbd5e1; border: 1px solid #475569; border-radius: 6px; padding: 6px 10px; font-size: 11.5px; font-weight: 600; cursor: pointer;">+30 ngày</button>
                    <button type="button" @click="setSingleDueDateDays(45, true)" style="background: rgba(51, 65, 85, 0.55); color: #cbd5e1; border: 1px solid #475569; border-radius: 6px; padding: 6px 10px; font-size: 11.5px; font-weight: 600; cursor: pointer;">+45 ngày</button>
                    <button type="button" @click="setSingleDueDateDays(60, true)" style="background: rgba(51, 65, 85, 0.55); color: #cbd5e1; border: 1px solid #475569; border-radius: 6px; padding: 6px 10px; font-size: 11.5px; font-weight: 600; cursor: pointer;">+60 ngày</button>
                  </div>
                </div>
              </div>
            </div>

            <!-- Chế độ 2: Chia theo nhiều đợt (% khác nhau) -->
            <div v-else style="display: flex; flex-direction: column; gap: 12px;">
              <div class="debt-sub-chips" style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 8px;">
                <div style="display: flex; align-items: center; gap: 6px; flex-wrap: wrap;">
                  <span style="font-size: 11.5px; color: #94a3b8; font-weight: 600;">Mẫu chia đợt nhanh:</span>
                  <button type="button" @click="applySchedulePreset([30, 70], ['Đợt 1 - Tạm ứng 30%', 'Đợt 2 - Tất toán 70%'])" style="background: rgba(2, 132, 199, 0.14); color: #38bdf8; border: 1px solid rgba(56, 189, 248, 0.35); border-radius: 6px; padding: 4px 10px; font-size: 11px; font-weight: 700; cursor: pointer;">2 đợt (30% - 70%)</button>
                  <button type="button" @click="applySchedulePreset([50, 50], ['Đợt 1 - Tạm ứng 50%', 'Đợt 2 - Tất toán 50%'])" style="background: rgba(2, 132, 199, 0.14); color: #38bdf8; border: 1px solid rgba(56, 189, 248, 0.35); border-radius: 6px; padding: 4px 10px; font-size: 11px; font-weight: 700; cursor: pointer;">2 đợt (50% - 50%)</button>
                  <button type="button" @click="applySchedulePreset([30, 50, 20], ['Đợt 1 - Tạm ứng 30%', 'Đợt 2 - Giao hàng 50%', 'Đợt 3 - Nghiệm thu 20%'])" style="background: rgba(124, 58, 237, 0.14); color: #c084fc; border: 1px solid rgba(168, 85, 247, 0.35); border-radius: 6px; padding: 4px 10px; font-size: 11px; font-weight: 700; cursor: pointer;">3 đợt (30% - 50% - 20%)</button>
                </div>
                <button type="button" @click="addScheduleInstallment" style="background: #10b981; color: #ffffff; border: none; border-radius: 6px; padding: 5px 11px; font-size: 11.5px; font-weight: 700; cursor: pointer;">+ Thêm đợt TT</button>
              </div>

              <div class="debt-sub-table-wrap" style="overflow-x: auto; border: 1px solid rgba(148,163,184,0.3); border-radius: 10px;">
                <table style="width: 100%; min-width: 680px; border-collapse: collapse; font-size: 12px; color: #e2e8f0;">
                  <thead>
                    <tr style="background: rgba(30, 41, 59, 0.75); border-bottom: 1px solid #334155; text-align: left; color: #94a3b8; font-size: 11px; text-transform: uppercase;">
                      <th style="padding: 8px 10px; width: 46px;">Đợt</th>
                      <th style="padding: 8px 10px; text-align: left;">Nội dung đợt</th>
                      <th style="padding: 8px 10px; width: 90px; text-align: right;">Tỷ lệ (%)</th>
                      <th style="padding: 8px 10px; width: 150px; text-align: right;">Số tiền phải thu</th>
                      <th style="padding: 8px 10px; width: 155px; text-align: left;">Hạn thanh toán</th>
                      <th style="padding: 8px 10px; text-align: center; width: 55px;">Xóa</th>
                    </tr>
                  </thead>
                  <tbody>
                    <tr v-for="(inst, idx) in paymentModal.scheduleItems" :key="idx" style="border-bottom: 1px dashed #1e293b;">
                      <td style="padding: 8px 10px; font-weight: 800; color: #c084fc;">#{{ idx + 1 }}</td>
                      <td style="padding: 8px 10px;">
                        <input type="text" v-model="inst.noi_dung" class="sr-modal-input" style="width: 100%; padding: 6px 8px; font-size: 12px; color: #f8fafc;" />
                      </td>
                      <td style="padding: 8px 10px;">
                        <FormattedInput
                          :modelValue="inst.ty_le_pct"
                          @update:modelValue="val => onInstallmentPctValueChange(idx, val)"
                          :decimals="2"
                          placeholder="0"
                          class="sr-modal-input text-right"
                          style="width: 78px; padding: 6px 6px; font-size: 12px; font-weight: 700; color: #38bdf8;"
                        />
                      </td>
                      <td style="padding: 8px 10px;">
                        <FormattedInput
                          :modelValue="inst.so_tien_phai_thu"
                          @update:modelValue="val => onInstallmentAmountValueChange(idx, val)"
                          :decimals="0"
                          placeholder="0"
                          class="sr-modal-input text-right"
                          style="width: 140px; padding: 6px 8px; font-size: 12px; font-weight: 700; color: #f8fafc;"
                        />
                      </td>
                      <td style="padding: 8px 10px;">
                        <input
                          type="date"
                          :value="ddmmyyyyToIso(inst.han_thanh_toan)"
                          @change="onInstallmentDatePickerChange(idx, $event)"
                          class="sr-modal-input"
                          style="width: 145px; padding: 5px 8px; font-size: 12px; color: #f8fafc;"
                        />
                      </td>
                      <td style="padding: 8px 10px; text-align: center;">
                        <button v-if="paymentModal.scheduleItems.length > 1" type="button" class="debt-sub-row-del" @click="removeScheduleInstallment(idx)" style="background: rgba(239, 68, 68, 0.14); color: #ef4444; border: 1px solid rgba(239, 68, 68, 0.35); border-radius: 6px; padding: 4px 8px; cursor: pointer;">✕</button>
                      </td>
                    </tr>
                  </tbody>
                </table>
              </div>

              <div class="debt-sub-balance-row" style="display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 8px; font-size: 12px; color: #94a3b8;">
                <div>
                  Tổng tỷ lệ: <strong :style="{ color: Math.abs(modalScheduleTotalPct - 100) < 0.1 ? '#10b981' : '#fbbf24' }">{{ modalScheduleTotalPct }}%</strong>
                  • Tổng tiền kế hoạch: <strong>{{ fmt(modalScheduleTotalAmount) }} / {{ fmt(tongSauVat(paymentModal.row)) }} đ</strong>
                </div>
                <button v-if="Math.abs(modalScheduleTotalAmount - tongSauVat(paymentModal.row)) > 1" type="button" class="debt-sub-balance-btn" @click="balanceLastInstallment" style="background: rgba(245, 158, 11, 0.15); color: #fbbf24; border: 1px solid rgba(245, 158, 11, 0.4); border-radius: 6px; padding: 4px 10px; font-size: 11px; font-weight: 700; cursor: pointer;">
                  Tự động cân bằng đợt cuối cho khớp 100%
                </button>
              </div>
            </div>
          </div>

          <div class="cust-modal-footer debt-sub-footer" style="padding: 14px 22px; background: rgba(15, 23, 42, 0.95); border-top: 1px solid rgba(255,255,255,0.08); display: flex; justify-content: flex-end; gap: 10px;">
            <button type="button" class="sr-btn sr-btn-cancel debt-sub-cancel" @click="paymentModal.showScheduleSubModal = false" style="padding: 8px 18px;">Hủy</button>
            <button type="button" class="debt-sub-save" @click="savePaymentScheduleOnly" :disabled="paymentModal.savingSchedule" style="padding: 8px 18px; border-radius: 8px; background: linear-gradient(135deg, #10b981, #059669); color: #fff; border: none; font-weight: 700; cursor: pointer;">
              {{ paymentModal.savingSchedule ? 'Đang lưu...' : 'Lưu Kế hoạch & Hạn TT' }}
            </button>
          </div>
        </div>
      </div>

      <!-- SUB-MODAL 2: Ghi nhận đợt thanh toán mới -->
      <div v-if="paymentModal.show && paymentModal.row && paymentModal.showRecordSubModal" class="sr-modal-overlay" :class="{ 'is-light': uiTheme === 'light', 'theme-light-blue': uiTheme === 'light' }" @click.self="paymentModal.showRecordSubModal = false" style="z-index: 100065; padding: 20px; background: rgba(2, 6, 23, 0.78);">
        <div class="sr-modal debt-record-submodal" :class="{ 'is-light': uiTheme === 'light' }" style="max-width: 640px; width: 95vw; background: #0f172a; border: 1px solid rgba(16, 185, 129, 0.45); border-radius: 16px; overflow: hidden; display: flex; flex-direction: column; box-shadow: 0 20px 50px rgba(0, 0, 0, 0.65);">
          <div class="sr-debt-head" style="padding: 14px 22px; margin-bottom: 0; border-radius: 0; display: flex; justify-content: space-between; align-items: center;">
            <div style="min-width: 0; padding-right: 12px;">
              <h4 :title="getPoContractContent(paymentModal.row)" style="margin: 0; color: #ffffff !important; font-size: 15px; font-weight: 800; text-transform: uppercase;">
                Ghi nhận đợt thanh toán mới — {{ getPoContractContent(paymentModal.row, 44) }}
              </h4>
              <div style="font-size: 12px; color: #ffffff; opacity: 0.9; margin-top: 2px;">
                Công nợ hiện tại của đơn hàng: <strong>{{ fmt(congNo(paymentModal.row)) }} đ</strong>
              </div>
            </div>
            <button @click="paymentModal.showRecordSubModal = false" style="color: #fff; background: rgba(0,0,0,0.18); border-radius: 50%; width: 28px; height: 28px; display: flex; align-items: center; justify-content: center; border: none; cursor: pointer;">✕</button>
          </div>

          <div class="debt-sub-body" style="padding: 18px 22px; display: flex; flex-direction: column; gap: 14px;">
            <div>
              <label style="font-size: 11.5px; color: #cbd5e1; font-weight: 700; display: block; margin-bottom: 6px;">Số tiền khách thanh toán (VNĐ)</label>
              <FormattedInput
                :modelValue="paymentModal.amount"
                @update:modelValue="val => onPaymentAmountValueChange(val)"
                :decimals="0"
                placeholder="0"
                class="sr-modal-input text-right"
                style="width: 100%; padding: 10px 14px; font-size: 17px; font-weight: 800; color: #34d399; border-color: rgba(16, 185, 129, 0.45); background: rgba(16, 185, 129, 0.06);"
              />

              <div class="debt-quick-amount-below" style="margin-top: 8px;">
                <div class="debt-sub-chips" style="display: flex; align-items: center; gap: 6px; flex-wrap: wrap;">
                  <span style="font-size: 11px; color: #94a3b8; font-weight: 600; margin-right: 2px;">Chọn nhanh:</span>
                  <template v-if="paymentModal.scheduleMode === 'nhieu_dot'">
                    <button
                      v-for="(inst, idx) in modalEvaluatedInstallments.filter(x => x.con_thieu > 0)"
                      :key="'quick-inst-' + idx"
                      type="button"
                      @click="applyQuickInstallmentAmount(inst)"
                      style="background: rgba(168, 85, 247, 0.16); color: #c084fc; border: 1px solid rgba(168, 85, 247, 0.4); border-radius: 6px; padding: 5px 10px; font-size: 11px; font-weight: 700; cursor: pointer;"
                    >
                      Đợt {{ inst.dot }} ({{ fmt(inst.con_thieu) }} đ)
                    </button>
                  </template>
                  <button type="button" @click="setPaymentQuickPct(100)" style="background: rgba(16, 185, 129, 0.15); color: #34d399; border: 1px solid rgba(16, 185, 129, 0.35); border-radius: 6px; padding: 5px 10px; font-size: 11px; font-weight: 700; cursor: pointer;">
                    Tất toán 100% nợ ({{ fmt(congNo(paymentModal.row)) }})
                  </button>
                  <button type="button" @click="setPaymentQuickPct(50)" style="background: rgba(56, 189, 248, 0.12); color: #38bdf8; border: 1px solid rgba(56, 189, 248, 0.3); border-radius: 6px; padding: 5px 10px; font-size: 11px; font-weight: 700; cursor: pointer;">
                    50% công nợ
                  </button>
                  <button type="button" @click="setPaymentQuickPct(30)" style="background: rgba(245, 158, 11, 0.12); color: #fbbf24; border: 1px solid rgba(245, 158, 11, 0.3); border-radius: 6px; padding: 5px 10px; font-size: 11px; font-weight: 700; cursor: pointer;">
                    30% công nợ
                  </button>
                  <button
                    v-if="paymentModal.amount > 0"
                    type="button"
                    @click="resetPaymentAmountToZero"
                    style="background: rgba(148, 163, 184, 0.14); color: #cbd5e1; border: 1px solid rgba(148, 163, 184, 0.32); border-radius: 6px; padding: 5px 10px; font-size: 11px; font-weight: 700; cursor: pointer;"
                  >
                    Đặt về 0
                  </button>
                </div>
              </div>

              <div
                v-if="congNo(paymentModal.row) > 0 && paymentModal.amount > congNo(paymentModal.row)"
                style="margin-top: 8px; padding: 8px 11px; border-radius: 7px; background: rgba(245, 158, 11, 0.12); border: 1px solid rgba(245, 158, 11, 0.38); color: #fbbf24; font-size: 11.5px; font-weight: 600;"
              >
                Lưu ý: Số tiền đang nhập vượt quá công nợ còn lại của đơn hàng ({{ fmt(congNo(paymentModal.row)) }} đ).
              </div>
            </div>

            <div class="debt-record-2col" style="display: grid; grid-template-columns: 1fr 1.25fr; gap: 12px;">
              <div>
                <label style="font-size: 11.5px; color: #cbd5e1; font-weight: 600; display: block; margin-bottom: 5px;">Thời gian thanh toán</label>
                <input type="text" v-model="paymentModal.paymentTime" placeholder="DD/MM/YYYY HH:mm:ss" class="sr-modal-input" style="width: 100%; padding: 9px 10px; font-size: 12.5px; color: #f8fafc;" />
              </div>
              <div>
                <label style="font-size: 11.5px; color: #cbd5e1; font-weight: 600; display: block; margin-bottom: 5px;">Ghi chú đợt thanh toán (Tùy chọn)</label>
                <input type="text" v-model="paymentModal.note" placeholder="VD: Thanh toán đợt 1 chuyển khoản..." class="sr-modal-input" style="width: 100%; padding: 9px 12px; font-size: 12.5px; color: #f8fafc;" />
              </div>
            </div>

            <!-- Live preview công nợ còn lại sau đợt thanh toán -->
            <div style="padding: 10px 12px; background: rgba(30, 41, 59, 0.5); border: 1px dashed #334155; border-radius: 8px; display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 8px; font-size: 12px; color: #94a3b8;">
              <span>
                Dự kiến Đã TT mới:
                <strong style="color: #34d399;">{{ fmt(daThanhToan(paymentModal.row) + (paymentModal.amount || 0)) }} đ</strong>
              </span>
              <span>
                Công nợ còn lại:
                <strong :style="{ color: Math.max(0, congNo(paymentModal.row) - (paymentModal.amount || 0)) > 0 ? '#f87171' : '#34d399', fontSize: '13px' }">
                  {{ fmt(Math.max(0, congNo(paymentModal.row) - (paymentModal.amount || 0))) }} đ
                </strong>
              </span>
            </div>
          </div>

          <div class="cust-modal-footer debt-sub-footer" style="padding: 14px 22px; background: rgba(15, 23, 42, 0.95); border-top: 1px solid rgba(255,255,255,0.08); display: flex; justify-content: flex-end; gap: 10px;">
            <button type="button" class="sr-btn sr-btn-cancel debt-sub-cancel" @click="paymentModal.showRecordSubModal = false" style="padding: 8px 18px;">Hủy</button>
            <button
              type="button"
              class="debt-sub-save"
              @click="submitPayment"
              :disabled="paymentModal.saving || paymentModal.amount <= 0"
              style="background: linear-gradient(135deg, #10b981, #059669); color: #ffffff; border: none; border-radius: 8px; padding: 8px 18px; font-size: 13px; font-weight: 700; cursor: pointer; display: inline-flex; align-items: center; gap: 6px; box-shadow: 0 4px 12px rgba(16, 185, 129, 0.3);"
            >
              <span>{{ paymentModal.saving ? 'Đang lưu...' : 'Xác nhận Ghi nhận TT' }}</span>
            </button>
          </div>
        </div>
      </div>
    </Teleport>

    <!-- MODAL PROGRESS TẢI & ĐỒNG BỘ CACHE HÀNG HÓA (HANG_HOA) -->
    <Teleport to="body">
      <div
        v-if="goodsDbLoadingModal.show"
        class="sr-goods-db-loading-overlay"
        :class="{ 'is-light': uiTheme === 'light' }"
      >
        <div class="sr-goods-db-loading-card">
          <div class="sr-gdl-head">
            <div class="sr-gdl-icon-ring">
              <svg class="sr-gdl-spin" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">
                <ellipse cx="12" cy="5" rx="9" ry="3" />
                <path d="M21 12c0 1.66-4 3-9 3s-9-1.34-9-3" />
                <path d="M3 5v14c0 1.66 4 3 9 3s9-1.34 9-3V5" />
              </svg>
            </div>
            <div class="sr-gdl-title-wrap">
              <span class="sr-gdl-eyebrow">ĐỒNG BỘ DATABASE &amp; BỘ NHỚ ĐỆM CACHE</span>
              <h4 class="sr-gdl-title">{{ goodsDbLoadingModal.stepTitle || 'Đang tải & đồng bộ danh mục Hàng hóa...' }}</h4>
            </div>
            <span class="sr-gdl-pct-badge">{{ Math.min(100, Math.max(0, Math.round(goodsDbLoadingModal.percent))) }}%</span>
          </div>

          <div class="sr-gdl-progress-track">
            <div
              class="sr-gdl-progress-fill"
              :style="{ width: `${Math.min(100, Math.max(4, Math.round(goodsDbLoadingModal.percent)))}%` }"
            ></div>
          </div>

          <div class="sr-gdl-meta-row">
            <span class="sr-gdl-detail">{{ goodsDbLoadingModal.stepDetail }}</span>
            <span v-if="goodsDbLoadingModal.totalCount > 0" class="sr-gdl-counter">
              <strong>{{ goodsDbLoadingModal.processedCount.toLocaleString('vi-VN') }}</strong> / {{ goodsDbLoadingModal.totalCount.toLocaleString('vi-VN') }} SP
            </span>
          </div>

          <div class="sr-gdl-cache-note">
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>
            <span v-if="goodsDbLoadingModal.fromCacheFallback">Đang sử dụng dữ liệu từ Bộ nhớ đệm (IndexedDB Cache) do kết nối mạng chậm</span>
            <span v-else>Tự động cập nhật dữ liệu mới nhất từ Cloud &amp; lưu vào Bộ nhớ đệm (IndexedDB Cache)</span>
          </div>
        </div>
      </div>
    </Teleport>

    <!-- MODAL KIỂM TRA & ĐỒNG BỘ HÀNG HÓA PO VÀO DATABASE (HANG_HOA) — FULL SCREEN 100% -->
    <Teleport to="body">
      <div
        v-if="poGoodsDbSyncModal.show"
        class="sr-dbsync-overlay"
        :class="{ 'is-light': uiTheme === 'light' }"
      >
        <div class="sr-dbsync-modal">
          <!-- 1. Header -->
          <div class="sr-dbsync-header">
            <div class="sr-dbsync-header-left">
              <div class="sr-dbsync-icon">
                <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><ellipse cx="12" cy="5" rx="9" ry="3"/><path d="M21 12c0 1.66-4 3-9 3s-9-1.34-9-3"/><path d="M3 5v14c0 1.66 4 3 9 3s9-1.34 9-3V5"/></svg>
              </div>
              <div class="sr-dbsync-title-block">
                <div class="sr-dbsync-title-row">
                  <h3 class="sr-dbsync-title">KIỂM TRA &amp; ĐỒNG BỘ HÀNG HÓA VÀO DATABASE (HANG_HOA)</h3>
                  <span class="sr-dbsync-meta-pill">
                    PO: <strong>{{ poGoodsDbSyncModal.targetItem?.soPO || poGoodsDbSyncModal.targetItem?.contractCode || 'Mới' }}</strong>
                  </span>
                  <span class="sr-dbsync-meta-pill">
                    NCC / Ngành hàng: <strong>{{ poGoodsDbSyncModal.targetItem?.productType || 'Chưa chọn' }}</strong>
                  </span>
                </div>
              </div>
            </div>
            <button type="button" class="sr-dbsync-close-btn" @click="poGoodsDbSyncModal.show = false" title="Đóng cửa sổ">
              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
              <span>Đóng</span>
            </button>
          </div>

          <!-- 2. Filter Bar -->
          <div class="sr-dbsync-toolbar">
            <div class="sr-dbsync-tabs">
              <button
                type="button"
                class="sr-dbsync-tab"
                :class="{ active: poGoodsDbSyncModal.filterTab === 'all' }"
                @click="poGoodsDbSyncModal.filterTab = 'all'"
              >
                Tất cả ({{ poGoodsDbSyncStats.total }})
              </button>
              <button
                type="button"
                class="sr-dbsync-tab is-new"
                :class="{ active: poGoodsDbSyncModal.filterTab === 'new' }"
                @click="poGoodsDbSyncModal.filterTab = 'new'"
              >
                Chưa có trong DB ({{ poGoodsDbSyncStats.newCount }})
              </button>
              <button
                type="button"
                class="sr-dbsync-tab is-diff"
                :class="{ active: poGoodsDbSyncModal.filterTab === 'diff' }"
                @click="poGoodsDbSyncModal.filterTab = 'diff'"
              >
                Đã có - Khác giá ({{ poGoodsDbSyncStats.diffCount }})
              </button>
              <button
                type="button"
                class="sr-dbsync-tab is-matched"
                :class="{ active: poGoodsDbSyncModal.filterTab === 'matched' }"
                @click="poGoodsDbSyncModal.filterTab = 'matched'"
              >
                Đã khớp DB ({{ poGoodsDbSyncStats.matchedCount }})
              </button>
              <button
                type="button"
                class="sr-dbsync-quick-btn"
                @click="selectPoGoodsDbSyncByStatus('need_action')"
                title="Chọn tất cả mặt hàng Chưa có DB hoặc Khác giá DB"
              >
                Chọn mục cần lưu ({{ poGoodsDbSyncStats.newCount + poGoodsDbSyncStats.diffCount }})
              </button>
            </div>
          </div>

          <!-- 3. Main 5-Column-Group Spacious Table -->
          <div class="sr-dbsync-body custom-scrollbar">
            <table class="sr-dbsync-table">
              <colgroup>
                <col style="width: 56px;" />
                <col style="width: 32%;" />
                <col style="width: 24%;" />
                <col style="width: 22%;" />
                <col style="width: 18%;" />
              </colgroup>
              <thead>
                <tr>
                  <th class="text-center">
                    <input
                      type="checkbox"
                      class="sr-dbsync-checkbox"
                      :checked="filteredPoGoodsDbSyncRows.length > 0 && filteredPoGoodsDbSyncRows.every(r => r.selected)"
                      @change="e => toggleAllPoGoodsDbSyncSelect((e.target as HTMLInputElement).checked)"
                    />
                  </th>
                  <th class="text-left">1. ĐỊNH DANH HÀNG HÓA &amp; ĐỐI CHIẾU DATABASE</th>
                  <th class="text-left">2. CÁC CHỈ SỐ TÍNH GIÁ (NHẬP VND)</th>
                  <th class="text-left">3. CHẾ ĐỘ ĐƠN GIÁ &amp; TIỀN TỆ LƯU DB</th>
                  <th class="text-left">4. KẾT QUẢ CHỐT LƯU VÀO HANG_HOA</th>
                </tr>
              </thead>
              <tbody>
                <tr v-if="filteredPoGoodsDbSyncRows.length === 0">
                  <td colspan="5" class="sr-dbsync-empty">
                    Không có mặt hàng nào trong bộ lọc hiện tại.
                  </td>
                </tr>
                <tr
                  v-for="r in filteredPoGoodsDbSyncRows"
                  :key="r.goodsIdx"
                  class="sr-dbsync-row"
                  :class="{ 'is-selected': r.selected }"
                >
                  <!-- CỘT 1: CHECKBOX & STT -->
                  <td class="text-center is-idx-col">
                    <div class="sr-dbsync-idx-wrap">
                      <input type="checkbox" v-model="r.selected" class="sr-dbsync-checkbox" />
                      <span class="sr-dbsync-stt-pill">#{{ r.goodsIdx + 1 }}</span>
                    </div>
                  </td>

                  <!-- CỘT 2: ĐỊNH DANH HÀNG HÓA & ĐỐI CHIẾU DB -->
                  <td>
                    <div class="sr-dbsync-identity-card">
                      <div class="sr-dbsync-sec-banner">
                        <span>ĐỊNH DANH HÀNG HÓA</span>
                        <div class="sr-dbsync-link-actions">
                          <button
                            type="button"
                            class="sr-dbsync-link-btn"
                            @click="openSyncRowDbProductPicker(r.goodsIdx)"
                          >
                            {{ r.dbItem ? 'Đổi SP DB' : 'Gắn SP DB có sẵn' }}
                          </button>
                          <button
                            v-if="r.dbItem"
                            type="button"
                            class="sr-dbsync-link-btn is-unlink"
                            @click="linkSyncRowToDbProduct(r, null)"
                          >
                            Tách thành SP mới
                          </button>
                        </div>
                      </div>

                      <div class="sr-dbsync-status-strip">
                        <div class="sr-dbsync-status-left">
                          <span v-if="!r.dbItem" class="sr-dbsync-status-badge is-new">
                            CHƯA CÓ TRONG DB (THÊM MỚI)
                          </span>
                          <span v-else-if="r.status === 'diff'" class="sr-dbsync-status-badge is-diff">
                            ĐÃ CÓ TRONG DB — KHÁC GIÁ
                          </span>
                          <span v-else class="sr-dbsync-status-badge is-matched">
                            ĐÃ KHỚP DB
                          </span>

                          <span v-if="r.dbItem" class="sr-dbsync-db-compare-pill">
                            Đang lưu DB:
                            <strong v-if="String(r.dbItem.don_vi_tien_te || 'VND').toUpperCase() === 'USD'">
                              {{ formatUsdPrice(r.dbItem.don_gia) }} USD
                            </strong>
                            <strong v-else>
                              {{ fmtInput(r.dbItem.don_gia) || '0' }} đ
                            </strong>
                            <template v-if="r.dbItem.gia_nhap">
                              • Giá nhập DB:
                              <strong v-if="String(r.dbItem.don_vi_tien_te || 'VND').toUpperCase() === 'USD'">
                                {{ formatUsdPrice(r.dbItem.gia_nhap) }} USD
                              </strong>
                              <strong v-else>
                                {{ fmtInput(r.dbItem.gia_nhap) || '0' }} đ
                              </strong>
                            </template>
                          </span>
                        </div>
                      </div>

                      <textarea
                        v-model="r.tenHang"
                        @input="onSyncRowNameOrCatInput(r)"
                        rows="2"
                        class="sr-dbsync-name-textarea custom-scrollbar"
                        placeholder="Nhập tên hàng hóa / dịch vụ..."
                      ></textarea>

                      <div class="sr-dbsync-meta-inputs">
                        <div class="sr-dbsync-labeled-field">
                          <label>Mã hàng lưu DB</label>
                          <input
                            type="text"
                            v-model="r.maHang"
                            @input="r.maHangEdited = true"
                            class="sr-dbsync-input is-code"
                            placeholder="Mã hàng..."
                          />
                        </div>
                        <div class="sr-dbsync-labeled-field">
                          <label>Danh mục (hang_hoa)</label>
                          <div class="sr-dbsync-input-with-btn">
                            <input
                              type="text"
                              v-model="r.danhMuc"
                              @input="onSyncRowNameOrCatInput(r)"
                              class="sr-dbsync-input is-cat"
                              placeholder="DANH MỤC"
                            />
                            <button
                              type="button"
                              class="sr-dbsync-pick-inline-btn"
                              @click="openSyncAttrPicker(r.goodsIdx, 'danh_muc')"
                              title="Chọn Danh mục từ bảng hang_hoa"
                            >
                              Chọn
                            </button>
                          </div>
                        </div>
                        <div class="sr-dbsync-labeled-field is-dvt-box">
                          <label>ĐVT (hang_hoa)</label>
                          <div class="sr-dbsync-input-with-btn">
                            <input
                              type="text"
                              v-model="r.dvt"
                              class="sr-dbsync-input text-center"
                              placeholder="Cái"
                            />
                            <button
                              type="button"
                              class="sr-dbsync-pick-inline-btn"
                              @click="openSyncAttrPicker(r.goodsIdx, 'dvt')"
                              title="Chọn ĐVT từ bảng hang_hoa"
                            >
                              Chọn
                            </button>
                          </div>
                        </div>
                      </div>
                    </div>
                  </td>

                  <!-- CỘT 3: LƯỚI 2x2 CHỈ SỐ TÍNH GIÁ (VND) -->
                  <td>
                    <div class="sr-dbsync-col-wrap">
                      <div class="sr-dbsync-sec-banner">
                        <span>CÁC CHỈ SỐ TÍNH GIÁ</span>
                      </div>
                      <div class="sr-dbsync-calc-grid">
                        <div class="sr-dbsync-calc-field">
                          <label>Đơn giá trên File (VND)</label>
                          <FormattedInput
                            :modelValue="r.donGiaFileVnd"
                            @update:modelValue="val => onSyncRowValueChange(r, 'donGiaFileVnd', val)"
                            :decimals="0"
                            class="sr-dbsync-input text-right is-file-price"
                            placeholder="0"
                          />
                        </div>

                        <div class="sr-dbsync-calc-field">
                          <label>Chênh lệch (VND)</label>
                          <FormattedInput
                            :modelValue="r.chenhLechVnd"
                            @update:modelValue="val => onSyncRowValueChange(r, 'chenhLechVnd', val)"
                            :decimals="0"
                            :allowNegative="true"
                            class="sr-dbsync-input text-right"
                            placeholder="0"
                          />
                        </div>

                        <div class="sr-dbsync-calc-field">
                          <label>Giá nhập (VND)</label>
                          <FormattedInput
                            :modelValue="r.giaNhapVnd"
                            @update:modelValue="val => onSyncRowValueChange(r, 'giaNhapVnd', val)"
                            :decimals="0"
                            class="sr-dbsync-input text-right is-cost-price"
                            placeholder="0"
                          />
                        </div>

                        <div class="sr-dbsync-calc-field">
                          <div class="sr-dbsync-off-label-row">
                            <label>Off khách</label>
                            <div class="sr-dbsync-off-mode-switch">
                              <button
                                type="button"
                                :class="{ active: r.offType === 'pct' }"
                                @click="onSyncRowOffTypeChange(r, 'pct')"
                              >
                                %
                              </button>
                              <button
                                type="button"
                                :class="{ active: r.offType === 'amount' }"
                                @click="onSyncRowOffTypeChange(r, 'amount')"
                              >
                                VNĐ
                              </button>
                            </div>
                          </div>
                          <div v-if="r.offType === 'pct'" class="sr-dbsync-pct-input-wrap">
                            <FormattedInput
                              :modelValue="r.offPct"
                              @update:modelValue="val => onSyncRowOffPctChange(r, val)"
                              :decimals="2"
                              class="sr-dbsync-input text-right"
                              placeholder="0"
                            />
                            <span class="sr-dbsync-pct-unit">%</span>
                          </div>
                          <div v-else class="sr-dbsync-pct-input-wrap">
                            <FormattedInput
                              :modelValue="r.offAmountVnd"
                              @update:modelValue="val => onSyncRowValueChange(r, 'offAmountVnd', val)"
                              :decimals="0"
                              class="sr-dbsync-input text-right"
                              placeholder="0"
                            />
                            <span class="sr-dbsync-pct-unit">đ</span>
                          </div>
                        </div>
                      </div>
                    </div>
                  </td>

                  <!-- CỘT 4: LỰA CHỌN ĐƠN GIÁ & TIỀN TỆ / TỈ GIÁ -->
                  <td>
                    <div class="sr-dbsync-choice-stack">
                      <div class="sr-dbsync-sec-banner">
                        <span>CHẾ ĐỘ &amp; TIỀN TỆ</span>
                      </div>
                      <div class="sr-dbsync-radio-list">
                        <button
                          type="button"
                          class="sr-dbsync-radio-card"
                          :class="{ active: r.priceMode === 'file' }"
                          @click="r.priceMode = 'file'"
                        >
                          <span class="sr-dbsync-radio-dot"></span>
                          <span class="sr-dbsync-radio-text">Lưu đúng giá trên File</span>
                          <strong class="sr-dbsync-radio-val">{{ fmtInput(r.donGiaFileVnd) || '0' }} đ</strong>
                        </button>

                        <button
                          type="button"
                          class="sr-dbsync-radio-card is-calc"
                          :class="{ active: r.priceMode === 'calc' }"
                          @click="r.priceMode = 'calc'"
                        >
                          <span class="sr-dbsync-radio-dot"></span>
                          <span class="sr-dbsync-radio-text">Lưu giá sau tính toán</span>
                          <strong class="sr-dbsync-radio-val">{{ fmtInput(calcSyncRowStandardPriceVnd(r)) || '0' }} đ</strong>
                        </button>
                      </div>

                      <div class="sr-dbsync-currency-row" :class="{ 'is-usd': r.currency === 'USD' }">
                        <div class="sr-dbsync-cur-left">
                          <span class="sr-dbsync-cur-lbl">Tiền tệ lưu DB:</span>
                          <div class="sr-dbsync-cur-switch">
                            <button
                              type="button"
                              :class="{ active: r.currency === 'VND' }"
                              @click="onSyncRowCurrencyChange(r, 'VND')"
                            >
                              VND
                            </button>
                            <button
                              type="button"
                              :class="{ active: r.currency === 'USD' }"
                              @click="onSyncRowCurrencyChange(r, 'USD')"
                            >
                              USD
                            </button>
                          </div>
                        </div>

                        <div v-if="r.currency === 'USD'" class="sr-dbsync-rate-inline">
                          <label>Tỉ giá (Ti_gia):</label>
                          <div class="sr-dbsync-input-with-btn is-rate-wrap">
                            <FormattedInput
                              :modelValue="r.tiGia"
                              @update:modelValue="val => onSyncRowValueChange(r, 'tiGia', val)"
                              :decimals="0"
                              class="sr-dbsync-input text-right is-rate"
                              placeholder="25.500"
                            />
                            <button
                              type="button"
                              class="sr-dbsync-pick-inline-btn"
                              @click="openSyncAttrPicker(r.goodsIdx, 'ti_gia')"
                              title="Chọn Tỉ giá (Ti_gia) từ bảng hang_hoa"
                            >
                              Chọn
                            </button>
                          </div>
                        </div>
                      </div>
                    </div>
                  </td>

                  <!-- CỘT 5: THẺ KẾT QUẢ CHỐT LƯU VÀO DATABASE -->
                  <td>
                    <div class="sr-dbsync-col-wrap">
                      <div class="sr-dbsync-sec-banner">
                        <span>KẾT QUẢ LƯU DB</span>
                      </div>
                      <div class="sr-dbsync-result-card" :class="{ 'is-usd': r.currency === 'USD' }">
                        <div class="sr-dbsync-result-head">
                          <span class="sr-dbsync-result-action">
                            {{ r.dbItem ? 'CẬP NHẬT DB' : 'THÊM MỚI DB' }}
                          </span>
                          <span class="sr-dbsync-result-cur-tag">
                            LƯU {{ r.currency }}
                          </span>
                        </div>

                        <div class="sr-dbsync-result-metric">
                          <span class="sr-dbsync-result-lbl">Đơn giá (Don_gia):</span>
                          <strong v-if="r.currency === 'USD'" class="sr-dbsync-result-val is-usd">
                            {{ formatUsdPrice(getSyncRowFinalDonGiaToSave(r)) }} USD
                          </strong>
                          <strong v-else class="sr-dbsync-result-val is-vnd">
                            {{ fmtInput(getSyncRowFinalDonGiaToSave(r)) || '0' }} đ
                          </strong>
                        </div>

                        <div class="sr-dbsync-result-metric">
                          <span class="sr-dbsync-result-lbl">Giá nhập (gia_nhap):</span>
                          <strong v-if="r.currency === 'USD'" class="sr-dbsync-result-sub is-usd">
                            {{ formatUsdPrice(getSyncRowFinalGiaNhapToSave(r)) }} USD
                          </strong>
                          <strong v-else class="sr-dbsync-result-sub is-vnd">
                            {{ fmtInput(getSyncRowFinalGiaNhapToSave(r)) || '0' }} đ
                          </strong>
                        </div>

                        <div v-if="r.currency === 'USD'" class="sr-dbsync-result-footnote">
                          Quy đổi theo Ti_gia {{ fmtInput(r.tiGia) || '0' }} (Lưu USD vào hang_hoa)
                        </div>
                      </div>
                    </div>
                  </td>
                </tr>
              </tbody>
            </table>
          </div>

          <!-- Sub-Modal Chọn Danh mục / ĐVT / Tỉ giá từ bảng hang_hoa -->
          <div
            v-if="poGoodsDbSyncModal.attrPickerType !== null"
            class="sr-dbsync-picker-backdrop"
            @click.self="closeSyncAttrPicker"
          >
            <div class="sr-dbsync-picker-card is-attr-picker">
              <div class="sr-dbsync-picker-head">
                <h4>
                  {{
                    poGoodsDbSyncModal.attrPickerType === 'danh_muc'
                      ? 'Chọn Danh mục (Danh_muc) từ bảng hang_hoa'
                      : poGoodsDbSyncModal.attrPickerType === 'dvt'
                        ? 'Chọn Đơn vị tính (DVT) từ bảng hang_hoa'
                        : 'Chọn Tỉ giá (Ti_gia) từ bảng hang_hoa'
                  }}
                </h4>
                <button type="button" class="sr-dbsync-close-btn is-icon-only" @click="closeSyncAttrPicker">
                  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
                </button>
              </div>
              <div class="sr-dbsync-picker-search">
                <input
                  type="text"
                  v-model="poGoodsDbSyncModal.attrPickerSearch"
                  class="sr-dbsync-input"
                  placeholder="Nhập từ khóa để lọc nhanh..."
                />
              </div>
              <div class="sr-dbsync-attr-grid custom-scrollbar">
                <button
                  v-for="opt in filteredSyncAttrPickerOptions"
                  :key="String(opt.value)"
                  type="button"
                  class="sr-dbsync-attr-chip"
                  @click="selectSyncAttrPickerOption(opt.value)"
                >
                  <strong class="sr-dbsync-attr-val">{{ opt.label }}</strong>
                  <span class="sr-dbsync-attr-cnt">{{ opt.count }} SP</span>
                </button>
                <div v-if="filteredSyncAttrPickerOptions.length === 0" class="sr-dbsync-empty" style="grid-column: 1 / -1;">
                  Không tìm thấy giá trị phù hợp trong bảng hang_hoa.
                </div>
              </div>
            </div>
          </div>

          <!-- Sub-Modal Chọn mặt hàng có sẵn trong DB (Khi bấm Đổi SP DB / Gắn SP DB) -->
          <div
            v-if="poGoodsDbSyncModal.pickerRowIdx !== null"
            class="sr-dbsync-picker-backdrop"
            @click.self="poGoodsDbSyncModal.pickerRowIdx = null"
          >
            <div class="sr-dbsync-picker-card">
              <div class="sr-dbsync-picker-head">
                <h4>Chọn mặt hàng trong Database (hang_hoa) để liên kết</h4>
                <button type="button" class="sr-dbsync-close-btn is-icon-only" @click="poGoodsDbSyncModal.pickerRowIdx = null">
                  <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
                </button>
              </div>
              <div class="sr-dbsync-picker-search">
                <input
                  type="text"
                  v-model="poGoodsDbSyncModal.pickerSearch"
                  class="sr-dbsync-input"
                  placeholder="Tìm theo Mã hàng, Tên hàng, Danh mục, Nhà cung cấp..."
                />
                <button
                  type="button"
                  class="sr-dbsync-mini-btn"
                  @click="() => {
                    const targetRow = poGoodsDbSyncModal.rows.find(x => x.goodsIdx === poGoodsDbSyncModal.pickerRowIdx);
                    if (targetRow) linkSyncRowToDbProduct(targetRow, null);
                  }"
                >
                  Tách thành mặt hàng mới hoàn toàn
                </button>
              </div>
              <div class="sr-dbsync-picker-list custom-scrollbar">
                <div
                  v-for="hh in filteredSyncDbPickerCatalog"
                  :key="hh._firebaseKey || hh.ma_hang"
                  class="sr-dbsync-picker-item"
                  @click="() => {
                    const targetRow = poGoodsDbSyncModal.rows.find(x => x.goodsIdx === poGoodsDbSyncModal.pickerRowIdx);
                    if (targetRow) linkSyncRowToDbProduct(targetRow, hh);
                  }"
                >
                  <div class="sr-dbsync-picker-item-left">
                    <span class="sr-dbsync-picker-code">{{ hh.ma_hang }}</span>
                    <strong class="sr-dbsync-picker-name">{{ hh.ten_hang }}</strong>
                    <span v-if="hh.danh_muc" class="sr-dbsync-picker-cat">{{ hh.danh_muc }}</span>
                  </div>
                  <div class="sr-dbsync-picker-item-right">
                    <span v-if="String(hh.don_vi_tien_te || 'VND').toUpperCase() === 'USD'">
                      Đơn giá: <strong>{{ formatUsdPrice(hh.don_gia) }} USD</strong> (Tỉ giá {{ fmtInput(hh.ti_gia) }})
                    </span>
                    <span v-else>
                      Đơn giá: <strong>{{ fmtInput(hh.don_gia) || '0' }} đ</strong>
                    </span>
                  </div>
                </div>
                <div v-if="filteredSyncDbPickerCatalog.length === 0" class="sr-dbsync-empty">
                  Không tìm thấy mặt hàng phù hợp trong Database.
                </div>
              </div>
            </div>
          </div>

          <!-- 4. Footer -->
          <div class="sr-dbsync-footer">
            <div class="sr-dbsync-footer-info">
              Đang tích chọn <strong>{{ poGoodsDbSyncStats.selectedCount }}</strong> / {{ poGoodsDbSyncStats.total }} mặt hàng
              <span class="sr-dbsync-sep">•</span>
              Thêm mới: <strong class="text-sky">{{ poGoodsDbSyncStats.selectedNewCount }}</strong>
              <span class="sr-dbsync-sep">•</span>
              Cập nhật DB: <strong class="text-amber">{{ poGoodsDbSyncStats.selectedUpdateCount }}</strong>
            </div>
            <div class="sr-dbsync-footer-actions">
              <button
                type="button"
                class="sr-dbsync-cancel-btn"
                @click="poGoodsDbSyncModal.show = false"
              >
                Đóng cửa sổ
              </button>
              <button
                type="button"
                class="sr-dbsync-save-btn"
                :disabled="poGoodsDbSyncModal.saving || poGoodsDbSyncStats.selectedCount === 0"
                @click="confirmSavePoGoodsToDatabase"
              >
                <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
                <span>
                  {{ poGoodsDbSyncModal.saving ? 'Đang lưu vào Database...' : `Xác nhận Lưu / Cập nhật vào Database (${poGoodsDbSyncStats.selectedCount})` }}
                </span>
              </button>
            </div>
          </div>
        </div>
      </div>
    </Teleport>

    <!-- ================== MODAL HỘP THOẠI THÔNG BÁO & XÁC NHẬN ĐỒNG BỘ TEMPLATE CHÍNH (ALERT / CONFIRM) ================== -->
    <Teleport to="body">
      <div
        v-if="srDialog.show"
        class="sr-modal-overlay sr-dialog-overlay"
        :class="{ 'theme-light-blue': uiTheme === 'light', 'is-light': uiTheme === 'light' }"
        style="z-index: 1000200;"
        @click.self="resolveSrDialog(false)"
      >
        <div
          class="sr-dialog-card"
          :class="['is-variant-' + srDialog.variant, 'is-mode-' + srDialog.mode, { 'is-light': uiTheme === 'light' }]"
          role="dialog"
          aria-modal="true"
          :aria-label="srDialog.title"
        >
          <!-- Header -->
          <div class="sr-dialog-head">
            <div class="sr-dialog-dt-head">
              <span class="sr-dialog-head-ico">
                <svg v-if="srDialog.variant === 'danger'" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/><line x1="10" y1="11" x2="10" y2="17"/><line x1="14" y1="11" x2="14" y2="17"/></svg>
                <svg v-else-if="srDialog.variant === 'error'" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/></svg>
                <svg v-else-if="srDialog.variant === 'success'" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>
                <svg v-else-if="srDialog.variant === 'warning'" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>
                <svg v-else width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>
              </span>
              <span class="sr-dialog-head-title">{{ srDialog.title }}</span>
            </div>

            <div class="sr-dialog-m-head">
              <span class="sr-dialog-m-eyebrow">{{ srDialog.eyebrow }}</span>
              <span class="sr-dialog-m-title">{{ srDialog.title }}</span>
            </div>

            <button
              type="button"
              class="sr-dialog-close-x"
              @click="resolveSrDialog(false)"
              aria-label="Đóng hộp thoại"
            >
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round">
                <line x1="18" y1="6" x2="6" y2="18"></line>
                <line x1="6" y1="6" x2="18" y2="18"></line>
              </svg>
            </button>
          </div>

          <!-- Body -->
          <div class="sr-dialog-body custom-scrollbar">
            <div v-if="srDialog.highlightValue" class="sr-dialog-target-card">
              <div class="sr-dialog-target-icon">
                <svg v-if="srDialog.variant === 'danger'" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>
                <svg v-else-if="srDialog.variant === 'error'" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/></svg>
                <svg v-else-if="srDialog.variant === 'success'" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
                <svg v-else width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>
              </div>
              <div class="sr-dialog-target-info">
                <div class="sr-dialog-target-tag">{{ srDialog.highlightLabel || srDialog.eyebrow }}</div>
                <div class="sr-dialog-target-val" :title="srDialog.highlightValue">
                  {{ srDialog.highlightValue }}
                </div>
              </div>
            </div>

            <div class="sr-dialog-msg-box">
              <div class="sr-dialog-msg-icon">
                <svg v-if="srDialog.variant === 'danger'" width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>
                <svg v-else-if="srDialog.variant === 'error'" width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="15" y1="9" x2="9" y2="15"/><line x1="9" y1="9" x2="15" y2="15"/></svg>
                <svg v-else-if="srDialog.variant === 'success'" width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>
                <svg v-else-if="srDialog.variant === 'warning'" width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>
                <svg v-else width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>
              </div>
              <div class="sr-dialog-msg-text">{{ srDialog.message }}</div>
            </div>

            <div v-if="srDialog.subNote" class="sr-dialog-subnote">
              <svg class="sr-dialog-subnote-ico" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>
              <span>{{ srDialog.subNote }}</span>
            </div>
          </div>

          <!-- Footer -->
          <div
            class="sr-dialog-foot"
            :class="{ 'is-single-action': srDialog.mode === 'alert' }"
          >
            <button
              v-if="srDialog.mode === 'confirm'"
              ref="srDialogCancelBtnRef"
              type="button"
              class="sr-dlg-btn sr-dlg-cancel"
              @click="resolveSrDialog(false)"
            >
              <span>{{ srDialog.cancelText }}</span>
            </button>

            <button
              ref="srDialogConfirmBtnRef"
              type="button"
              class="sr-dlg-btn sr-dlg-confirm"
              :class="'is-btn-' + srDialog.variant"
              @click="resolveSrDialog(true)"
            >
              <svg v-if="srDialog.mode === 'confirm' && srDialog.variant === 'danger'" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg>
              <svg v-else width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
              <span>{{ srDialog.confirmText }}</span>
            </button>
          </div>
        </div>
      </div>
    </Teleport>

    <!-- ================== MODAL NHẮC NHỞ DỮ LIỆU CHƯA LƯU KHI ĐÓNG MODAL PO (PHƯƠNG ÁN A - 3 NÚT) ================== -->
    <Teleport to="body">
      <div
        v-if="showUnsavedPoCloseModal"
        class="sr-modal-overlay sr-dialog-overlay"
        :class="{ 'theme-light-blue': uiTheme === 'light', 'is-light': uiTheme === 'light' }"
        style="z-index: 1000250;"
        @click.self="showUnsavedPoCloseModal = false"
      >
        <div
          class="sr-dialog-card is-variant-warning is-mode-confirm sr-unsaved-po-dialog"
          :class="{ 'is-light': uiTheme === 'light' }"
          role="dialog"
          aria-modal="true"
          aria-label="Thay đổi chưa được lưu"
        >
          <!-- Header -->
          <div class="sr-dialog-head">
            <div class="sr-dialog-dt-head">
              <span class="sr-dialog-head-ico">
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>
              </span>
              <span class="sr-dialog-head-title">Thay đổi chưa được lưu</span>
            </div>

            <div class="sr-dialog-m-head">
              <span class="sr-dialog-m-eyebrow">{{ srDataMode === 'craft' ? 'Cảnh báo Phương án tạm chưa lưu' : 'Cảnh báo đơn hàng PO chưa lưu' }}</span>
              <span class="sr-dialog-m-title">Thay đổi chưa được lưu</span>
            </div>

            <button
              type="button"
              class="sr-dialog-close-x"
              @click="showUnsavedPoCloseModal = false"
              aria-label="Đóng hộp thoại"
            >
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round">
                <line x1="18" y1="6" x2="6" y2="18"></line>
                <line x1="6" y1="6" x2="18" y2="18"></line>
              </svg>
            </button>
          </div>

          <!-- Body -->
          <div class="sr-dialog-body custom-scrollbar">
            <div class="sr-dialog-target-card">
              <div class="sr-dialog-target-icon">
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/></svg>
              </div>
              <div class="sr-dialog-target-info">
                <div class="sr-dialog-target-tag">{{ srDataMode === 'craft' ? 'PHƯƠNG ÁN TẠM ĐANG NHẬP' : 'ĐƠN HÀNG PO ĐANG NHẬP' }}</div>
                <div class="sr-dialog-target-val" :title="unsavedPoModalTargetLabel">
                  {{ unsavedPoModalTargetLabel }}
                </div>
              </div>
            </div>

            <div class="sr-dialog-msg-box">
              <div class="sr-dialog-msg-icon">
                <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>
              </div>
              <div class="sr-dialog-msg-text">Bạn có dữ liệu vừa chỉnh sửa nhưng chưa lưu. Nếu đóng ngay bây giờ, các thay đổi vừa nhập sẽ bị mất.</div>
            </div>

            <div class="sr-dialog-subnote">
              <svg class="sr-dialog-subnote-ico" width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="16" x2="12" y2="12"/><line x1="12" y1="8" x2="12.01" y2="8"/></svg>
              <span>Chọn "Lưu &amp; Đóng" để ghi nhận thay đổi trước khi thoát, hoặc "Thoát không lưu" để hủy bỏ các chỉnh sửa.</span>
            </div>
          </div>

          <!-- Footer (3 Nút: Tiếp tục sửa | Thoát không lưu | Lưu & Đóng) -->
          <div class="sr-dialog-foot is-three-actions">
            <button
              type="button"
              class="sr-dlg-btn sr-dlg-cancel"
              @click="showUnsavedPoCloseModal = false"
            >
              <span>Tiếp tục sửa</span>
            </button>

            <button
              type="button"
              class="sr-dlg-btn sr-dlg-discard"
              @click="confirmDiscardAndCloseMultiEditModal()"
            >
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
              <span>Thoát không lưu</span>
            </button>

            <button
              type="button"
              class="sr-dlg-btn sr-dlg-confirm is-btn-save-close"
              :disabled="savingModal"
              @click="confirmSaveAndCloseMultiEditModal()"
            >
              <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z"/><polyline points="17 21 17 13 7 13 7 21"/><polyline points="7 3 7 8 15 8"/></svg>
              <span>{{ savingModal ? 'Đang lưu...' : 'Lưu & Đóng' }}</span>
            </button>
          </div>
        </div>
      </div>
    </Teleport>

    <!-- MOBILE FLOATING GLASS BOTTOM DOCK (Phương án A: 1. Tổng quan & DS Công ty | 2. Thêm mới (Giữa) | 3. Chi tiết Công ty) -->
    <nav
      v-if="isMobileShell"
      class="sr-mobile-dock"
      :class="{ 'is-modal-hidden': isAnySaleModalOpen }"
      aria-label="Điều hướng nhanh Sale Report Mobile"
    >
      <!-- 1. Tổng quan (4 Card KPI tổng + Tìm kiếm/Bộ lọc + Tất cả nhóm Công ty & PO) -->
      <button
        type="button"
        class="sr-dock-btn"
        :class="{ active: mobileActiveTab === 'overview' }"
        @click="switchMobileTab('overview')"
      >
        <div class="sr-dock-icon-wrap">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round">
            <rect x="3" y="3" width="7" height="7" rx="1.5" />
            <rect x="14" y="3" width="7" height="7" rx="1.5" />
            <rect x="14" y="14" width="7" height="7" rx="1.5" />
            <rect x="3" y="14" width="7" height="7" rx="1.5" />
          </svg>
          <span v-if="activeSaleFilterCount > 0" class="sr-dock-badge is-amber" :title="`Đang bật ${activeSaleFilterCount} bộ lọc`">{{ activeSaleFilterCount }}</span>
          <span v-else-if="filteredRows.length > 0" class="sr-dock-badge">{{ filteredRows.length > 999 ? '999+' : filteredRows.length }}</span>
        </div>
        <span>Tổng quan</span>
      </button>

      <!-- 2. Nút Thêm mới (Primary CTA chính giữa) -->
      <button
        type="button"
        class="sr-dock-btn is-primary is-center-cta"
        @click="openAddChoiceModal()"
      >
        <div class="sr-dock-icon-wrap">
          <svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round">
            <line x1="12" y1="5" x2="12" y2="19" />
            <line x1="5" y1="12" x2="19" y2="12" />
          </svg>
        </div>
        <span>Thêm mới</span>
      </button>

      <!-- 3. Tên công ty (Xem chi tiết KPI & PO của công ty đang chọn) -->
      <button
        type="button"
        class="sr-dock-btn is-company-slot"
        :class="{
          active: mobileActiveTab === 'company_detail',
          'is-disabled': !activeMobilePoRow
        }"
        @click="activeMobilePoRow ? openMultiEditModal(activeMobilePoRow) : switchMobileTab('overview')"
        :title="activeMobilePoRow ? `Đang chọn PO ${activeMobilePoRow.So_PO || ''} - ${activeMobilePoRow.Ten_cong_ty || ''}` : 'Chọn một PO từ Tổng quan'"
      >
        <div class="sr-dock-icon-wrap">
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round">
            <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" /><polyline points="14 2 14 8 20 8" /><line x1="16" y1="13" x2="8" y2="13" /><line x1="16" y1="17" x2="8" y2="17" />
          </svg>
          <span v-if="false && activeMasterGroup && activeMasterGroup.items?.length" class="sr-dock-badge is-emerald">
            {{ activeMasterGroup.items.length }}
          </span>
        </div>
        <span class="sr-dock-company-name">{{ getMobileDockPoLabel(activeMobilePoRow) }}</span>
      </button>

      <!-- 4. Nút Xuất Excel -->
      <button
        type="button"
        class="sr-dock-btn"
        @click.stop="openExportFromToolbar()"
        title="Xuất danh sách Sale Report ra Excel"
      >
        <div class="sr-dock-icon-wrap">
          <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round">
            <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4" />
            <polyline points="7 10 12 15 17 10" />
            <line x1="12" y1="15" x2="12" y2="3" />
          </svg>
          <span v-if="selectedPoRows.length > 0" class="sr-dock-badge is-emerald">{{ selectedPoRows.length }}</span>
        </div>
        <span>Xuất Excel</span>
      </button>

      <!-- 5. Nút Thiết lập hiển thị -->
      <button
        type="button"
        class="sr-dock-btn"
        :class="{ active: showDisplaySettingPopover }"
        @click.stop="showDisplaySettingPopover = !showDisplaySettingPopover"
        title="Thiết lập hiển thị & Giao diện"
      >
        <div class="sr-dock-icon-wrap">
          <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round">
            <circle cx="12" cy="12" r="3" />
            <path d="M19.4 15a1.65 1.65 0 0 0 .33 1.82l.06.06a2 2 0 0 1 0 2.83 2 2 0 0 1-2.83 0l-.06-.06a1.65 1.65 0 0 0-1.82-.33 1.65 1.65 0 0 0-1 1.51V21a2 2 0 0 1-2 2 2 2 0 0 1-2-2v-.09A1.65 1.65 0 0 0 9 19.4a1.65 1.65 0 0 0-1.82.33l-.06.06a2 2 0 0 1-2.83 0 2 2 0 0 1 0-2.83l.06-.06a1.65 1.65 0 0 0 .33-1.82 1.65 1.65 0 0 0-1.51-1H3a2 2 0 0 1-2-2 2 2 0 0 1 2-2h.09A1.65 1.65 0 0 0 4.6 9a1.65 1.65 0 0 0-.33-1.82l-.06-.06a2 2 0 0 1 0-2.83 2 2 0 0 1 2.83 0l.06.06a1.65 1.65 0 0 0 1.82.33H9a1.65 1.65 0 0 0 1-1.51V3a2 2 0 0 1 2-2 2 2 0 0 1 2 2v.09a1.65 1.65 0 0 0 1 1.51 1.65 1.65 0 0 0 1.82-.33l.06-.06a2 2 0 0 1 2.83 0 2 2 0 0 1 0 2.83l-.06.06a1.65 1.65 0 0 0-.33 1.82V9a1.65 1.65 0 0 0 1.51 1H21a2 2 0 0 1 2 2 2 2 0 0 1-2 2h-.09a1.65 1.65 0 0 0-1.51 1z" />
          </svg>
        </div>
        <span>Hiển thị</span>
      </button>
    </nav>

    <!-- MODAL PHÂN TÍCH & SO SÁNH ĐA PHƯƠNG ÁN (ĐỒNG BỘ GIAO DIỆN MODAL PHÂN TÍCH BẢN CHÍNH THỨC) -->
    <Teleport to="body">
      <div
        v-if="showCraftCompareModal"
        class="sr-modal-overlay"
        :class="{ 'theme-light-blue': uiTheme === 'light', 'mode-craft': srDataMode === 'craft', 'no-anim': isSwitchingTab }"
        @click.self="showCraftCompareModal = false"
        style="z-index: 100000; padding: 0;"
      >
        <div
          class="sr-modal sr-modal-large sr-analytics-modal"
          :class="{ 'is-light': uiTheme === 'light', 'mode-craft': srDataMode === 'craft', 'no-anim': isSwitchingTab }"
        >
          <!-- Header (Đồng bộ chuẩn .sr-analytics-header bên Bản Chính Thức) -->
          <div class="sr-analytics-header">
            <div class="sr-analytics-header-left">
              <button
                type="button"
                class="sr-analytics-back-btn"
                @click="isMobile && craftCompareMobileDockTab === 'chart' ? (craftCompareMobileDockTab = 'group') : (isMobile && craftCompareMobileDockTab === 'group' ? (craftCompareMobileDockTab = 'metric') : (showCraftCompareModal = false))"
                title="Quay lại"
              >
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M19 12H5"/><path d="M12 19l-7-7 7-7"/></svg>
              </button>
              <span v-if="!isMobile" class="sr-analytics-header-icon">
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><path d="M3 3v18h18"/><path d="M18 17V9"/><path d="M13 17V5"/><path d="M8 17v-3"/></svg>
              </span>
              <div class="sr-analytics-title-wrap">
                <div class="sr-analytics-title-row" style="flex-wrap: wrap; gap: 8px;">
                  <h3 class="sr-analytics-title">Phân tích &amp; So sánh Phương án</h3>
                  <span class="sr-analytics-po-badge">Đã chọn {{ effectiveCraftCompareRows.length }} / {{ rows.length }} Phương án</span>
                </div>
                <p class="sr-analytics-sub">
                  Chọn các chỉ số KPI ở cột bên trái để hiển thị Biểu đồ và Bảng ma trận đối chiếu theo Nội dung hợp đồng (content_of_contract_PO)
                </p>
              </div>
            </div>

            <div style="display: flex; align-items: center; gap: 8px;">
              <button
                v-if="!isMobile && effectiveCraftCompareRows.length > 0"
                type="button"
                class="sr-ccm-tool-btn is-clone"
                @click="cloneCraftRowFromCompare(effectiveCraftCompareRows[effectiveCraftCompareRows.length - 1])"
                title="Nhân bản thêm 1 phương án mới ngay trong modal phân tích"
              >
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>
                <span class="sr-hide-mob">+ Nhân bản PA</span>
              </button>
              <button
                v-if="!isMobile && effectiveCraftCompareRows.length > 0"
                type="button"
                class="sr-ccm-tool-btn is-mindmap"
                @click="openCompareMindmapReview()"
                title="Mở Sơ đồ Tư duy (Mindmap) & Thuyết minh giọng đọc cho các phương án đang so sánh"
              >
                <svg width="13.5" height="13.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><circle cx="6" cy="12" r="3"/><circle cx="18" cy="6" r="3"/><circle cx="18" cy="18" r="3"/><path d="M8.7 10.7l6.6-3.4"/><path d="M8.7 13.3l6.6 3.4"/></svg>
                <span class="sr-hide-mob">Review Mindmap</span>
              </button>
              <button
                type="button"
                class="sr-add-choice-close"
                @click="showCraftCompareModal = false"
                title="Đóng phân tích so sánh"
              >
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
              </button>
            </div>
          </div>

          <!-- 2-Column Split Workspace: Left Sidebar (Chọn Phương Án + 10 KPI Metrics + 4 KPI Summary Cards) | Right Main (Toolbar + Full-Height Charts & Tables) -->
          <div
            class="sr-analytics-split-shell"
            :class="[`mob-analytics-dock-${craftCompareMobileDockTab}`, { 'is-sidebar-collapsed': isAnalyticsSidebarCollapsed }]"
          >
            <!-- Thanh ngữ cảnh nhanh trên Mobile khi đang ở Tab Biểu đồ (Đã ẩn theo yêu cầu để mở rộng không gian) -->
            <div v-if="false" class="sr-analytics-mob-ctx-bar">
              <button type="button" class="sr-analytics-mob-ctx-pill is-metric" @click="craftCompareMobileDockTab = 'metric'">
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><line x1="4" y1="21" x2="4" y2="14"/><line x1="4" y1="10" x2="4" y2="3"/><line x1="12" y1="21" x2="12" y2="12"/><line x1="12" y1="8" x2="12" y2="3"/><line x1="20" y1="21" x2="20" y2="16"/><line x1="20" y1="12" x2="20" y2="3"/><line x1="1" y1="14" x2="7" y2="14"/><line x1="9" y1="8" x2="15" y2="8"/><line x1="17" y1="16" x2="23" y2="16"/></svg>
                <span>Phương án ({{ effectiveCraftCompareRows.length }}) &amp; Chỉ số: <strong>{{ craftCompareChartMetric === 'triple_kpi' ? 'Gộp 3 KPI chính' : activeCraftChartMetricDef.label }}</strong></span>
              </button>
              <button type="button" class="sr-analytics-mob-ctx-pill is-group" @click="craftCompareMobileDockTab = 'group'">
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/></svg>
                <span>{{ craftCompareViewSection === 'table' ? 'Ma trận 10 KPI' : 'So sánh Phương án PO' }}</span>
              </button>
            </div>

            <!-- Thanh Bottom Dock 3 nút trên Mobile: 1. Chỉ số | 2. Nhóm biểu đồ | 3. Biểu đồ -->
            <nav class="sr-analytics-mobile-dock" aria-label="Điều hướng phân tích phương án">
              <button
                type="button"
                class="sr-analytics-dock-btn"
                :class="{ active: craftCompareMobileDockTab === 'metric' }"
                @click="craftCompareMobileDockTab = 'metric'"
              >
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><line x1="4" y1="21" x2="4" y2="14"/><line x1="4" y1="10" x2="4" y2="3"/><line x1="12" y1="21" x2="12" y2="12"/><line x1="12" y1="8" x2="12" y2="3"/><line x1="20" y1="21" x2="20" y2="16"/><line x1="20" y1="12" x2="20" y2="3"/><line x1="1" y1="14" x2="7" y2="14"/><line x1="9" y1="8" x2="15" y2="8"/><line x1="17" y1="16" x2="23" y2="16"/></svg>
                <span>Phương án &amp; Chỉ số</span>
              </button>
              <button
                type="button"
                class="sr-analytics-dock-btn"
                :class="{ active: craftCompareMobileDockTab === 'group' }"
                @click="craftCompareMobileDockTab = 'group'"
              >
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/></svg>
                <span>Góc nhìn</span>
              </button>
              <button
                type="button"
                class="sr-analytics-dock-btn"
                :class="{ active: craftCompareMobileDockTab === 'chart' }"
                @click="craftCompareMobileDockTab = 'chart'"
              >
                <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.1" stroke-linecap="round" stroke-linejoin="round"><path d="M3 3v18h18"/><path d="M18 17V9"/><path d="M13 17V5"/><path d="M8 17v-3"/></svg>
                <span>Biểu đồ</span>
              </button>
            </nav>

            <!-- CỘT TRÁI: Chọn 10 Chỉ Số KPI + 4 Thẻ KPI Tóm Tắt -->
            <aside class="sr-analytics-sidebar custom-scrollbar">
              <!-- MỤC 1: CHỌN 10 CHỈ SỐ PHÂN TÍCH KPI -->
              <div class="sr-analytics-side-section">
                <div class="sr-analytics-side-heading is-with-toggle">
                  <span>Chỉ số biểu đồ (3 Nhóm Card PO)</span>
                  <button
                    type="button"
                    class="sr-analytics-side-collapse-btn"
                    @click="isAnalyticsSidebarCollapsed = true"
                    title="Thu gọn cột chỉ số bên trái"
                  >
                    <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><polyline points="11 17 6 12 11 7"/><polyline points="18 17 13 12 18 7"/></svg>
                    <span>Ẩn</span>
                  </button>
                </div>
                <div class="sr-analytics-metric-strip">
                  <button
                    v-for="mDef in craftCompareMetricDefs"
                    :key="mDef.key"
                    type="button"
                    class="sr-analytics-metric-chip"
                    :class="[
                      mDef.group === 'profit' || mDef.group === 'ratio' ? 'is-margin' : (mDef.group === 'cost' ? 'is-com' : `is-${mDef.group}`),
                      { active: craftCompareChartMetric === mDef.key }
                    ]"
                    @click="craftCompareChartMetric = mDef.key; craftCompareMobileDockTab = 'group'"
                    :title="mDef.formula ? `${mDef.label} (${mDef.formula})` : mDef.label"
                  >
                    {{ mDef.shortLabel || mDef.label }}
                  </button>
                  <button
                    type="button"
                    class="sr-analytics-metric-chip is-margin"
                    :class="{ active: craftCompareChartMetric === 'triple_kpi' }"
                    @click="craftCompareChartMetric = 'triple_kpi'; craftCompareMobileDockTab = 'group'"
                    title="Vẽ gộp 3 cột KPI chính (Doanh số bán • Net COM • Net Margin) cho từng phương án trên cùng 1 biểu đồ"
                  >
                    Gộp 3 KPI chính
                  </button>
                </div>
              </div>

              <div class="sr-analytics-side-section">
                <div class="sr-analytics-side-heading">
                  Tóm tắt — {{ craftCompareChartMetric === 'triple_kpi' ? '3 Cụm KPI' : activeCraftChartMetricDef.label }}
                </div>
                <div class="sr-analytics-kpi-grid">
                  <div
                    v-for="(kpi, kIdx) in craftCompareSummaryKpis"
                    :key="kIdx"
                    class="sr-analytics-kpi-card"
                    :class="`is-${kpi.tone}`"
                  >
                    <span class="sr-analytics-kpi-label">{{ kpi.label }}</span>
                    <strong class="sr-analytics-kpi-val">{{ kpi.value }}</strong>
                    <span class="sr-analytics-kpi-sub" :title="kpi.sub">{{ kpi.sub }}</span>
                  </div>
                </div>
              </div>
            </aside>

            <!-- CỘT PHẢI: Thanh Tab Góc Nhìn + Vùng Biểu Đồ & Bảng Full Chiều Cao (Giống hệt Bản Chính Thức) -->
            <div class="sr-analytics-main">
              <!-- Toolbar: View Tabs (Left) + Context Controls (Right) -->
              <div class="sr-analytics-toolbar">
                <div class="sr-analytics-tabs">
                  <button
                    type="button"
                    class="sr-analytics-sidebar-toggle-btn"
                    :class="{ 'is-collapsed': isAnalyticsSidebarCollapsed }"
                    @click="isAnalyticsSidebarCollapsed = !isAnalyticsSidebarCollapsed"
                    :title="isAnalyticsSidebarCollapsed ? 'Mở lại cột chỉ số KPI bên trái' : 'Thu gọn cột chỉ số bên trái để mở rộng không gian'"
                  >
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">
                      <rect x="3" y="3" width="18" height="18" rx="2" />
                      <line x1="9" y1="3" x2="9" y2="21" />
                      <polyline v-if="isAnalyticsSidebarCollapsed" points="13 9 16 12 13 15" />
                      <polyline v-else points="15 9 12 12 15 15" />
                    </svg>
                    <span>{{ isAnalyticsSidebarCollapsed ? 'Mở cột chỉ số' : 'Ẩn cột trái' }}</span>
                  </button>
                  <button
                    type="button"
                    class="sr-analytics-tab-btn"
                    :class="{ active: craftCompareViewSection === 'both' }"
                    @click="craftCompareViewSection = 'both'; craftCompareMobileDockTab = 'chart'"
                  >
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 3v18h18"/><path d="M18 17V9"/><path d="M13 17V5"/><path d="M8 17v-3"/></svg>
                    <span>So sánh Phương án PO ({{ effectiveCraftCompareRows.length }})</span>
                  </button>
                  <button
                    type="button"
                    class="sr-analytics-tab-btn"
                    :class="{ active: craftCompareViewSection === 'table' }"
                    @click="craftCompareViewSection = 'table'; craftCompareMobileDockTab = 'chart'"
                  >
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2"/><line x1="3" y1="9" x2="21" y2="9"/><line x1="9" y1="21" x2="9" y2="9"/></svg>
                    <span>Bảng Ma trận So sánh (3 Nhóm)</span>
                  </button>
                </div>

                <!-- Controls cho Tab Biểu đồ So sánh PO -->
                <div v-if="craftCompareViewSection !== 'table'" class="sr-analytics-controls">
                  <div class="sr-analytics-ctrl-group">
                    <span class="sr-analytics-ctrl-label">Sắp xếp:</span>
                    <button
                      type="button"
                      class="sr-analytics-seg-btn"
                      :class="{ active: craftCompareChartSort === 'original' }"
                      @click="craftCompareChartSort = 'original'"
                    >
                      Thứ tự gốc
                    </button>
                    <button
                      type="button"
                      class="sr-analytics-seg-btn"
                      :class="{ active: craftCompareChartSort === 'desc' }"
                      @click="craftCompareChartSort = 'desc'"
                    >
                      Cao nhất
                    </button>
                    <button
                      type="button"
                      class="sr-analytics-seg-btn"
                      :class="{ active: craftCompareChartSort === 'asc' }"
                      @click="craftCompareChartSort = 'asc'"
                    >
                      Thấp nhất
                    </button>
                  </div>
                </div>

                <!-- Controls cho Tab Bảng Ma trận 10 KPI -->
                <div v-else class="sr-analytics-controls">
                  <div class="sr-analytics-ctrl-group">
                    <span class="sr-analytics-ctrl-label">Bố cục:</span>
                    <button
                      type="button"
                      class="sr-analytics-seg-btn"
                      :class="{ active: craftCompareLayout === 'columns' }"
                      @click="craftCompareLayout = 'columns'"
                    >
                      Dạng Cột
                    </button>
                    <button
                      type="button"
                      class="sr-analytics-seg-btn"
                      :class="{ active: craftCompareLayout === 'rows' }"
                      @click="craftCompareLayout = 'rows'"
                    >
                      Dạng Dòng
                    </button>
                  </div>
                  <div v-if="effectiveCraftCompareRows.length > 1" class="sr-analytics-ctrl-group">
                    <span class="sr-analytics-ctrl-label">Bản gốc:</span>
                    <button
                      v-for="(r, bIdx) in effectiveCraftCompareRows"
                      :key="'base-pick-' + (getPoRowKey(r) || bIdx)"
                      type="button"
                      class="sr-analytics-seg-btn"
                      :class="{ active: isCraftBaselineRow(r) }"
                      @click="setCraftBaselineRow(r)"
                      :title="'Chọn làm Bản gốc: ' + getCraftCompareColTitle(r, bIdx)"
                    >
                      {{ isCraftBaselineRow(r) ? '★ ' : '' }}PA {{ bIdx + 1 }}
                    </button>
                  </div>
                  <div class="sr-analytics-ctrl-group">
                    <button
                      type="button"
                      class="sr-analytics-seg-btn"
                      :class="{ active: craftCompareOnlyDiff }"
                      @click="craftCompareOnlyDiff = !craftCompareOnlyDiff"
                    >
                      {{ craftCompareOnlyDiff ? 'Đang lọc: Có chênh lệch' : 'Tất cả 10 chỉ số KPI' }}
                    </button>
                  </div>
                </div>
              </div>

              <!-- Body: Biểu đồ + Bảng xếp hạng / Ma trận KPI -->
              <div
                class="sr-analytics-body custom-scrollbar"
                :class="{ 'is-matrix-body': craftCompareViewSection === 'table' && effectiveCraftCompareRows.length > 0 }"
              >
                <div v-if="effectiveCraftCompareRows.length === 0" class="sr-ccm-empty">
                  <p>Chưa có phương án nào được chọn. Hãy tích chọn các phương án ở danh sách bên ngoài rồi mở bảng so sánh.</p>
                </div>

                <div v-else class="sr-analytics-ranking-workspace">
                  <!-- HÀNG 1: BIỂU ĐỒ TRÒN DOUGHNUT + BIỂU ĐỒ CỘT BAR CHART (Mỗi cột là content_of_contract_PO) -->
                  <div v-if="craftCompareViewSection !== 'table'" class="sr-analytics-charts-row">
                    <!-- Doughnut Chart (Ẩn khi xem chỉ số tỷ lệ % hoặc Gộp 3 KPI) -->
                    <div
                      v-if="craftCompareChartMetric !== 'triple_kpi' && !activeCraftChartMetricDef.isRatio"
                      class="sr-analytics-doughnut-card"
                    >
                      <div class="sr-analytics-panel-head">
                        <h4 class="sr-analytics-panel-title">Cơ cấu tỷ trọng phương án</h4>
                        <span class="sr-analytics-panel-sub">{{ activeCraftChartMetricDef.label }}</span>
                      </div>
                      <div class="sr-analytics-doughnut-wrap">
                        <Doughnut
                          :key="'ccm-dn-' + craftCompareChartMetric + '-' + craftCompareChartSort + '-' + effectiveCraftCompareRows.length + '-' + uiTheme"
                          :data="craftComparePieData"
                          :options="craftComparePieOptions"
                        />
                      </div>
                    </div>

                    <!-- Standard Ranking Bar Chart: Cột là từng content_of_contract_PO -->
                    <div class="sr-analytics-bar-card">
                      <div class="sr-analytics-panel-head">
                        <h4 class="sr-analytics-panel-title">
                          Biểu đồ xếp hạng Phương án PO —
                          {{ craftCompareChartMetric === 'triple_kpi' ? 'Doanh số bán • Net COM • Net Margin' : activeCraftChartMetricDef.label }}
                        </h4>
                        <span class="sr-analytics-panel-sub">
                          Tên mỗi cột là Nội dung hợp đồng (content_of_contract_PO) • Chọn nhanh 10 chỉ số KPI ở cột bên trái
                        </span>
                      </div>
                      <div class="sr-analytics-bar-scroll custom-scrollbar">
                        <div
                          class="chart-wrapper-mobile"
                          :style="isMobile ? {
                            '--mob-bar-h': Math.max(240, craftCompareSortedChartRows.length * (craftCompareChartMetric === 'triple_kpi' ? 88 : 68) + 64) + 'px',
                            height: Math.max(240, craftCompareSortedChartRows.length * (craftCompareChartMetric === 'triple_kpi' ? 88 : 68) + 64) + 'px',
                            width: '100%',
                            minWidth: '100%'
                          } : {
                            height: '420px',
                            width: Math.max(100, craftCompareSortedChartRows.length * (craftCompareChartMetric === 'triple_kpi' ? 165 : 125)) + 'px',
                            minWidth: '100%'
                          }"
                        >
                          <Bar
                            :key="'ccm-bar-' + (isMobile ? 'mob-h' : 'pc-v') + '-' + craftCompareChartMetric + '-' + craftCompareChartSort + '-' + effectiveCraftCompareRows.length + '-' + uiTheme"
                            :data="craftCompareBarData"
                            :options="craftCompareBarOptions"
                          />
                        </div>
                      </div>
                    </div>
                  </div>

                  <!-- HÀNG 2A: BẢNG CHI TIẾT XẾP HẠNG PHƯƠNG ÁN PO (Chuẩn giao diện Modal Phân tích Bản Chính Thức) -->
                  <div v-if="craftCompareViewSection !== 'table'" class="sr-analytics-table-card">
                    <div class="sr-analytics-panel-head">
                      <h4 class="sr-analytics-panel-title">
                        Bảng chi tiết xếp hạng Phương án PO ({{ craftCompareSortedChartRows.length }} phương án)
                      </h4>
                      <span class="sr-analytics-panel-sub">
                        So sánh trực tiếp Doanh số bán, Net COM, Net Margin và thao tác Sửa / Nhân bản / Chốt Deal từng phương án
                      </span>
                    </div>
                    <div class="sr-analytics-table-scroll custom-scrollbar">
                      <table class="sr-analytics-table">
                        <thead>
                          <tr>
                            <th style="width: 56px;">Hạng</th>
                            <th>Nội dung hợp đồng (content of contract)</th>
                            <th style="width: 150px; text-align: right;">Doanh số bán</th>
                            <th style="width: 145px; text-align: right;">Net COM</th>
                            <th style="width: 145px; text-align: right;">Net Margin</th>
                            <th v-if="craftCompareChartMetric !== 'triple_kpi'" style="width: 160px; text-align: right;">
                              {{ activeCraftChartMetricDef.label }}
                            </th>
                            <th v-if="craftCompareChartMetric !== 'triple_kpi' && !activeCraftChartMetricDef.isRatio" style="width: 185px;">
                              Tỷ trọng
                            </th>
                            <th style="width: 215px; text-align: right;">Thao tác</th>
                          </tr>
                        </thead>
                        <tbody>
                          <tr
                            v-for="(item, rIdx) in craftCompareSortedChartRows"
                            :key="(getPoRowKey(item.row) || rIdx)"
                          >
                            <td>
                              <span class="sr-rank-badge" :class="{ 'is-top1': rIdx === 0, 'is-top2': rIdx === 1, 'is-top3': rIdx === 2 }">
                                {{ rIdx + 1 }}
                              </span>
                            </td>
                            <td class="sr-rank-name" :title="item.label">
                              <div>{{ item.label }}</div>
                              <div style="font-size: 11px; font-weight: 500; opacity: 0.72; margin-top: 2px; white-space: normal;">
                                {{ item.row.Ten_cong_ty || item.row.Ten_khach_hang || 'Khách lẻ' }}
                                <template v-if="item.row.So_PO"> • PO: {{ item.row.So_PO }}</template>
                                <template v-if="item.row.Ten_nha_cung_cap"> • NCC: {{ item.row.Ten_nha_cung_cap }}</template>
                              </div>
                            </td>
                            <td style="text-align: right; font-weight: 700; font-variant-numeric: tabular-nums;">{{ fmt(doanhSoBan(item.row)) }} đ</td>
                            <td style="text-align: right; font-weight: 700; font-variant-numeric: tabular-nums;">
                              {{ fmt(netCom(item.row)) }} đ
                              <small style="display: block; font-size: 10px; opacity: 0.72;">({{ pct(netCom(item.row), doanhSoBan(item.row)) }}% DSB)</small>
                            </td>
                            <td style="text-align: right; font-variant-numeric: tabular-nums;" class="sr-rank-val" :class="netMargin(item.row) < 0 ? 'text-red' : 'text-green'">
                              {{ fmt(netMargin(item.row)) }} đ
                              <small style="display: block; font-size: 10px; opacity: 0.72;">({{ pct(netMargin(item.row), doanhSoBan(item.row)) }}% DSB)</small>
                            </td>
                            <td
                              v-if="craftCompareChartMetric !== 'triple_kpi'"
                              style="text-align: right; font-variant-numeric: tabular-nums;"
                              class="sr-rank-val"
                              :class="item.val < 0 ? 'text-red' : 'text-green'"
                            >
                              {{ activeCraftChartMetricDef.format(item.row) }}
                            </td>
                            <td v-if="craftCompareChartMetric !== 'triple_kpi' && !activeCraftChartMetricDef.isRatio">
                              <div class="sr-rank-share-cell">
                                <div class="sr-rank-share-bar">
                                  <div
                                    class="sr-rank-share-fill"
                                    :style="{
                                      width: (craftCompareChartTotal > 0 ? Math.min(100, Math.max(0, (Math.max(0, item.val) / craftCompareChartTotal) * 100)) : 0) + '%'
                                    }"
                                  ></div>
                                </div>
                                <span class="sr-rank-share-text">
                                  {{ craftCompareChartTotal > 0 ? ((Math.max(0, item.val) / craftCompareChartTotal) * 100).toFixed(1) : '0.0' }}%
                                </span>
                              </div>
                            </td>
                            <td style="text-align: right;">
                              <div class="sr-ccm-opt-actions is-right-aligned">
                                <button
                                  type="button"
                                  class="sr-ccm-act-btn is-edit is-icon-only"
                                  title="Sửa phương án"
                                  @click="openMultiEditModalFromCompare(item.row)"
                                >
                                  <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z"/></svg>
                                </button>
                                <button
                                  type="button"
                                  class="sr-ccm-act-btn is-clone is-icon-only"
                                  title="Nhân bản phương án"
                                  @click="cloneCraftRowFromCompare(item.row)"
                                >
                                  <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.3" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>
                                </button>
                                <button
                                  v-if="srDataMode === 'craft'"
                                  type="button"
                                  class="sr-ccm-act-btn is-chot"
                                  title="Chốt Deal phương án này"
                                  @click="promoteCraftToOfficial(item.row)"
                                >
                                  <svg width="12.5" height="12.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>
                                  <span>Chốt</span>
                                </button>
                              </div>
                            </td>
                          </tr>
                        </tbody>
                      </table>
                    </div>
                  </div>

                  <!-- HÀNG 2B: BẢNG MA TRẬN ĐỐI CHIẾU 10 CHỈ SỐ KPI (SO SÁNH TĂNG/GIẢM THEO BẢN GỐC ĐƯỢC CHỌN Ở CẢ DẠNG CỘT VÀ DẠNG DÒNG) -->
                  <div v-else class="sr-analytics-table-card is-matrix-full-card">
                    <div class="sr-analytics-table-scroll is-matrix-full-scroll custom-scrollbar">
                      <!-- DẠNG CỘT (COLUMNS): Cột đầu là Tên Chỉ Số (3 Cụm KPI), các cột tiếp theo là từng Nội dung hợp đồng (content_of_contract_PO) -->
                      <table
                        v-if="craftCompareLayout === 'columns'"
                        class="sr-ccm-table is-columns-layout is-clean-sheet"
                        :style="{ '--ccm-opt-count': Math.max(1, effectiveCraftCompareRows.length) }"
                      >
                        <colgroup>
                          <col class="sr-ccm-col-sticky" />
                          <col
                            v-for="(r, colIdx) in effectiveCraftCompareRows"
                            :key="'col-' + (getPoRowKey(r) || colIdx)"
                            class="sr-ccm-col-option"
                          />
                        </colgroup>
                        <thead>
                          <tr>
                            <th class="sr-ccm-sticky-col sr-ccm-metric-th">
                              <div class="sr-ccm-corner-head">
                                <span>CHỈ SỐ KPI ({{ filteredCraftCompareMetricDefs.length }})</span>
                              </div>
                            </th>
                            <th
                              v-for="(r, colIdx) in effectiveCraftCompareRows"
                              :key="getPoRowKey(r) || colIdx"
                              class="sr-ccm-option-th"
                              :class="{ 'is-baseline-col': isCraftBaselineRow(r) }"
                            >
                              <div class="sr-ccm-opt-head">
                                <div class="sr-ccm-opt-top">
                                  <div class="sr-ccm-opt-top-left">
                                    <button
                                      v-if="effectiveCraftCompareRows.length > 1"
                                      type="button"
                                      class="sr-ccm-base-btn"
                                      :class="{ 'is-active': isCraftBaselineRow(r) }"
                                      @click.stop="setCraftBaselineRow(r)"
                                      :title="isCraftBaselineRow(r) ? 'Phương án này đang được chọn làm Bản gốc' : 'Chọn phương án này làm Bản gốc để so sánh tăng/giảm'"
                                    >
                                      {{ isCraftBaselineRow(r) ? '★ Bản gốc' : 'Chọn làm gốc' }}
                                    </button>
                                  </div>
                                  <button
                                    v-if="effectiveCraftCompareRows.length > 1"
                                    type="button"
                                    class="sr-ccm-opt-rm"
                                    @click="removeCraftRowFromCompare(r)"
                                    title="Ẩn phương án này khỏi bảng so sánh"
                                  >
                                    ×
                                  </button>
                                </div>
                                <div class="sr-ccm-opt-po" :title="getCraftCompareColTitle(r, colIdx)">
                                  {{ getCraftCompareColTitle(r, colIdx) }}
                                </div>
                                <div class="sr-ccm-opt-cust" :title="r.Ten_cong_ty || r.Ten_khach_hang">
                                  {{ r.Ten_cong_ty || r.Ten_khach_hang || 'Chưa chọn công ty' }}
                                  <template v-if="r.So_PO"> • {{ r.So_PO }}</template>
                                  <template v-if="r.Ten_nha_cung_cap"> • {{ r.Ten_nha_cung_cap }}</template>
                                </div>
                              </div>
                            </th>
                          </tr>
                        </thead>
                        <tbody>
                          <template v-for="mDef in filteredCraftCompareMetricDefs" :key="mDef.key">
                            <tr
                              v-if="mDef.sectionTitle"
                              class="sr-ccm-section-banner"
                              :class="'is-sec-' + (mDef.sectionGroup === 'rev_cost' ? 'rev' : mDef.sectionGroup === 'com_tax_margin' ? 'com' : 'profit')"
                            >
                              <td :colspan="effectiveCraftCompareRows.length + 1" class="sr-ccm-section-td">
                                <span
                                  class="sr-ccm-sec-dot"
                                  :class="'is-' + (mDef.sectionGroup === 'rev_cost' ? 'rev' : mDef.sectionGroup === 'com_tax_margin' ? 'com' : 'profit')"
                                ></span>
                                <span>{{ mDef.sectionTitle }}</span>
                              </td>
                            </tr>
                            <tr
                              :class="'sr-ccm-row-' + mDef.group"
                              :title="mDef.formula ? `${mDef.label}: ${mDef.formula}` : mDef.label"
                            >
                              <td
                                class="sr-ccm-sticky-col sr-ccm-metric-td"
                                style="cursor: pointer;"
                                @click="craftCompareChartMetric = mDef.key"
                              >
                                <div class="sr-ccm-m-label">
                                  <span class="sr-ccm-m-dot" :class="'is-' + mDef.group"></span>
                                  <strong>{{ mDef.label }}</strong>
                                </div>
                              </td>
                              <td
                                v-for="(r, colIdx) in effectiveCraftCompareRows"
                                :key="(getPoRowKey(r) || colIdx) + '_' + mDef.key"
                                class="sr-ccm-val-td is-editable-cell"
                                :class="{
                                  'is-baseline-col': isCraftBaselineRow(r),
                                  'is-editing-cell': isEditingMatrixCell(r, mDef)
                                }"
                                :title="mDef.key === 'thue_com' ? 'Click để sửa % Thuế COM' : 'Click để sửa nhanh chỉ số này'"
                                @click.stop="startEditMatrixCell(r, mDef)"
                              >
                                <div class="sr-ccm-cell-main is-right-aligned">
                                  <input
                                    v-if="isEditingMatrixCell(r, mDef) && editingMatrixCell"
                                    id="sr-ccm-inline-input-main"
                                    type="text"
                                    class="sr-ccm-inline-input"
                                    :value="editingMatrixCell.rawVal"
                                    :placeholder="mDef.key === 'thue_com' ? '% Thuế' : (mDef.isRatio ? '% Tỉ suất' : 'Giá trị')"
                                    @input="onMatrixInlineInput($event, mDef)"
                                    @keydown.enter.prevent="commitEditMatrixCell(r, mDef)"
                                    @keydown.esc.prevent="cancelEditMatrixCell()"
                                    @click.stop
                                  />
                                  <span
                                    v-else
                                    class="sr-ccm-cell-val"
                                    :class="{
                                      'is-neg-val': mDef.isNumeric && mDef.getNumeric(r) < 0
                                    }"
                                    @click.stop="startEditMatrixCell(r, mDef, 'main')"
                                  >
