pdfjsLib.GlobalWorkerOptions.workerSrc = pdfWorkerUrl

// ─── Firebase Setup ───
import { initializeApp, getApps, getApp } from "firebase/app"
import { getDatabase, ref as dbRef, get, set, push, update, remove, child } from "firebase/database"

const firebaseConfig = {
  apiKey: "AIzaSyB3fHD_sOqyqVygCxP2gZtvaipr-35a1s8",
  authDomain: "chusonproject.firebaseapp.com",
  databaseURL: "https://chusonproject-default-rtdb.asia-southeast1.firebasedatabase.app",
  projectId: "chusonproject",
  storageBucket: "chusonproject.firebasestorage.app",
  messagingSenderId: "929199941311",
  appId: "1:929199941311:web:ca8d86f9fd7f8dff61480a",
  measurementId: "G-48VVPGFSFK"
}
const firebaseApp = !getApps().length ? initializeApp(firebaseConfig) : getApp()
const database = getDatabase(firebaseApp)

// BASE_URL removed - all CRUD operations now use Firebase Realtime Database

const loading = ref(false)
const srDataMode = ref<'official' | 'craft'>('official')
const officialRows = ref<any[]>([])
const craftRows = ref<any[]>([])
const rows = computed<any[]>({
  get: () => (srDataMode.value === 'craft' ? craftRows.value : officialRows.value),
  set: (val) => {
    if (srDataMode.value === 'craft') {
      craftRows.value = val
    } else {
      officialRows.value = val
    }
  }
})
const hdChiTietData = ref<any[]>([])
const searchStr = ref('')
const showSearchSuggestions = ref(false)

// ─── Unified Queued Promise Dialog (Alert & Confirm chuẩn Template chính) ───
type SrDialogVariant = 'info' | 'success' | 'warning' | 'danger' | 'error'

interface SrDialogOptions {
  variant?: SrDialogVariant
  eyebrow?: string
  title: string
  message: string
  highlightLabel?: string
  highlightValue?: string
  subNote?: string
  confirmText?: string
  cancelText?: string
}

interface SrDialogQueueItem {
  mode: 'alert' | 'confirm'
  variant: SrDialogVariant
  eyebrow: string
  title: string
  message: string
  highlightLabel: string
  highlightValue: string
  subNote: string
  confirmText: string
  cancelText: string
  resolve: (confirmed: boolean) => void
}

const srDialog = reactive({
  show: false,
  mode: 'alert' as 'alert' | 'confirm',
  variant: 'info' as SrDialogVariant,
  eyebrow: 'Thông báo hệ thống',
  title: '',
  message: '',
  highlightLabel: '',
  highlightValue: '',
  subNote: '',
  confirmText: 'Đã hiểu',
  cancelText: 'Hủy bỏ'
})

const srDialogQueue: SrDialogQueueItem[] = []
let activeSrDialogResolver: ((confirmed: boolean) => void) | null = null
const srDialogCancelBtnRef = ref<HTMLButtonElement | null>(null)
const srDialogConfirmBtnRef = ref<HTMLButtonElement | null>(null)
let isSrDialogKeyListenerAttached = false

function onSrDialogKeydown(ev: KeyboardEvent) {
  if (!srDialog.show) return
  if (ev.key === 'Escape') {
    ev.preventDefault()
    ev.stopPropagation()
    resolveSrDialog(false)
    return
  }
  if (ev.key === 'Enter') {
    const activeEl = typeof document !== 'undefined' ? document.activeElement : null
    if (
      activeEl &&
      (activeEl === srDialogCancelBtnRef.value || activeEl === srDialogConfirmBtnRef.value)
    ) {
      return
    }
    if (srDialog.mode === 'alert' || srDialog.variant !== 'danger') {
      ev.preventDefault()
      ev.stopPropagation()
      resolveSrDialog(true)
    }
  }
}

function attachSrDialogKeyListener() {
  if (typeof window === 'undefined' || isSrDialogKeyListenerAttached) return
  window.addEventListener('keydown', onSrDialogKeydown, true)
  isSrDialogKeyListenerAttached = true
}

function detachSrDialogKeyListener() {
  if (typeof window === 'undefined' || !isSrDialogKeyListenerAttached) return
  window.removeEventListener('keydown', onSrDialogKeydown, true)
  isSrDialogKeyListenerAttached = false
}

function presentNextSrDialog() {
  const nextItem = srDialogQueue.shift()
  if (!nextItem) {
    srDialog.show = false
    activeSrDialogResolver = null
    detachSrDialogKeyListener()
    return
  }
  activeSrDialogResolver = nextItem.resolve
  srDialog.mode = nextItem.mode
  srDialog.variant = nextItem.variant
  srDialog.eyebrow = nextItem.eyebrow
  srDialog.title = nextItem.title
  srDialog.message = nextItem.message
  srDialog.highlightLabel = nextItem.highlightLabel
  srDialog.highlightValue = nextItem.highlightValue
  srDialog.subNote = nextItem.subNote
  srDialog.confirmText = nextItem.confirmText
  srDialog.cancelText = nextItem.cancelText
  srDialog.show = true

  nextTick(() => {
    attachSrDialogKeyListener()
    if (srDialog.mode === 'confirm' && srDialog.variant === 'danger') {
      srDialogCancelBtnRef.value?.focus()
    } else {
      srDialogConfirmBtnRef.value?.focus()
    }
  })
}

function enqueueSrDialog(mode: 'alert' | 'confirm', opts: SrDialogOptions): Promise<boolean> {
  const variant: SrDialogVariant = opts.variant || (mode === 'confirm' ? 'danger' : 'info')
  const defaultEyebrow =
    variant === 'danger'
      ? 'Xác nhận thao tác'
      : variant === 'error'
        ? 'Cảnh báo lỗi hệ thống'
        : variant === 'success'
          ? 'Thao tác hoàn tất'
          : variant === 'warning'
            ? 'Kiểm tra thông tin'
            : 'Thông báo hệ thống'

  return new Promise<boolean>((resolve) => {
    srDialogQueue.push({
      mode,
      variant,
      eyebrow: opts.eyebrow || defaultEyebrow,
      title: opts.title,
      message: opts.message,
      highlightLabel: opts.highlightLabel || '',
      highlightValue: opts.highlightValue || '',
      subNote: opts.subNote || '',
      confirmText: opts.confirmText || (mode === 'confirm' ? 'Xác nhận' : 'Đã hiểu'),
      cancelText: opts.cancelText || 'Hủy bỏ',
      resolve
    })
    if (!srDialog.show) {
      presentNextSrDialog()
    }
  })
}

function openSrAlert(opts: SrDialogOptions): Promise<boolean> {
  return enqueueSrDialog('alert', opts)
}

function openSrConfirm(opts: SrDialogOptions): Promise<boolean> {
  return enqueueSrDialog('confirm', opts)
}

function resolveSrDialog(confirmed: boolean) {
  const resolver = activeSrDialogResolver
  activeSrDialogResolver = null
  if (srDialogQueue.length > 0) {
    presentNextSrDialog()
  } else {
    srDialog.show = false
    detachSrDialogKeyListener()
  }
  if (resolver) {
    resolver(confirmed)
  }
}

