function escapeHtmlForHighlight(str: string): string {
  return str
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;')
}

function highlightSaleText(rawText: any, customQuery?: string): string {
  const text = String(rawText ?? '')
  if (!text) return ''
  const query = typeof customQuery === 'string' ? customQuery : (searchStr.value || '')
  const trimmed = query.trim()
  const safeHtmlText = escapeHtmlForHighlight(text)
  if (!trimmed) return safeHtmlText
  const words = trimmed.toLowerCase().split(/\s+/).filter(Boolean)
  if (!words.length) return safeHtmlText
  const safeWords = words.map(w => escapeHtmlForHighlight(w).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'))
  const regex = new RegExp(`(${safeWords.join('|')})`, 'gi')
  return safeHtmlText.replace(
    regex,
    '<span class="sr-search-hl" style="background-color: #eab308; color: #0f172a; font-weight: bold; padding: 0 2px; border-radius: 2px;">$1</span>'
  )
}

