const shiftSalePeriod = (dir: number) => {
  const pad = (n: number) => String(n).padStart(2, '0')
  if (timeFilterMode.value === 'day') {
    const todayIso = `${currentDate.getFullYear()}-${pad(currentDate.getMonth() + 1)}-${pad(currentDate.getDate())}`
    const shiftIsoDay = (iso: string) => {
      const base = iso ? new Date(iso + 'T00:00:00') : new Date()
      base.setDate(base.getDate() + dir)
      return `${base.getFullYear()}-${pad(base.getMonth() + 1)}-${pad(base.getDate())}`
    }
    dateFrom.value = shiftIsoDay(dateFrom.value || dateTo.value || todayIso)
    dateTo.value = shiftIsoDay(dateTo.value || dateFrom.value || todayIso)
  } else if (timeFilterMode.value === 'month') {
    const shiftIsoMonth = (ym: string) => {
      const [yStr, mStr] = (ym || currentMonthStr).split('-')
      const d = new Date(Number(yStr) || currentDate.getFullYear(), (Number(mStr) || 1) - 1 + dir, 1)
      return `${d.getFullYear()}-${pad(d.getMonth() + 1)}`
    }
    const baseFrom = monthFrom.value || monthTo.value || currentMonthStr
    const baseTo = monthTo.value || monthFrom.value || currentMonthStr
    monthFrom.value = shiftIsoMonth(baseFrom)
    monthTo.value = shiftIsoMonth(baseTo)
  } else if (timeFilterMode.value === 'year') {
    const curY = currentDate.getFullYear()
    const yf = Number(yearFrom.value || yearTo.value || curY) + dir
    const yt = Number(yearTo.value || yearFrom.value || curY) + dir
    yearFrom.value = String(yf)
    yearTo.value = String(yt)
  }
}

