const hangHoaNccList = ref<string[]>([])

function isInHangHoaNccList(val: string | undefined | null): boolean {
  if (!val) return false
  return hangHoaNccList.value.includes(String(val))
}

function matchHangHoaNcc(rawHint: string | undefined | null, fallbackText?: string): string {
  if (hangHoaNccList.value.length === 0) return ''
  const hint = String(rawHint || '').trim()
  if (hint) {
    const exact = hangHoaNccList.value.find(n => n.toLowerCase() === hint.toLowerCase())
    if (exact) return exact
    const sortedByLen = [...hangHoaNccList.value].sort((a, b) => b.length - a.length)
    const partial = sortedByLen.find(
      n => n.length >= 2 && (hint.toLowerCase().includes(n.toLowerCase()) || n.toLowerCase().includes(hint.toLowerCase()))
    )
    if (partial) return partial
  }
  if (fallbackText) {
    const hay = String(fallbackText).toLowerCase()
    const sortedNccs = [...hangHoaNccList.value].sort((a, b) => b.length - a.length)
    for (const ncc of sortedNccs) {
      if (ncc.length < 2) continue
      const escaped = ncc.toLowerCase().replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
      const re = new RegExp(`(^|[_\\-\\s.,()\\[\\]])${escaped}($|[_\\-\\s.,()\\[\\]])`, 'i')
      if (re.test(hay)) return ncc
    }
  }
  return ''
}

const uniqueProductTypes = computed(() => {
  const map = new Map<string, string>()
  hangHoaNccList.value.forEach(ncc => {
    const original = String(ncc || '').trim()
    const lower = original.toLowerCase()
    if (lower && !map.has(lower)) {
      map.set(lower, original)
    }
  })
  rows.value.forEach(r => {
    if (r.Ten_nha_cung_cap) {
      const original = String(r.Ten_nha_cung_cap).trim()
      const lower = original.toLowerCase()
      if (lower && !map.has(lower)) {
        map.set(lower, original)
      }
    }
  })
  return Array.from(map.values()).sort((a, b) => a.localeCompare(b, 'vi'))
})

watch([dateFrom, dateTo], ([newFrom, newTo], [oldFrom, oldTo]) => {
  if (newFrom && newTo && newFrom > newTo) {
    if (newFrom !== oldFrom) dateTo.value = newFrom
    else dateFrom.value = newTo
  }
})

watch([monthFrom, monthTo], ([newFrom, newTo], [oldFrom, oldTo]) => {
  if (newFrom && newTo && newFrom > newTo) {
    if (newFrom !== oldFrom) monthTo.value = newFrom
    else monthFrom.value = newTo
  }
})

watch([yearFrom, yearTo], ([newFrom, newTo], [oldFrom, oldTo]) => {
  if (newFrom && newTo && Number(newFrom) > Number(newTo)) {
    if (newFrom !== oldFrom) yearTo.value = newFrom
    else yearFrom.value = newTo
  }
})
const modalInput = ref<HTMLInputElement | null>(null)
const editModal = ref<{ show: boolean; row: any; field: string; label: string; value: number }>({
  show: false, row: null, field: '', label: '', value: 0
})
const savingModal = ref(false)

// ─── Core Helpers & Financial Formulas (Hoisted before computed/watchers) ───
const toNum = (v: any): number => {
  if (v === null || v === undefined || v === '') return 0
  if (typeof v === 'number') return isFinite(v) ? v : 0
  const n = Number(v)
  if (!isNaN(n) && isFinite(n)) return n
  const s = String(v).trim().replace(/\s+/g, '').replace(/[^\d.,-]/g, '')
  if (!s || s === '-') return 0
  const parsed = Number(s.replace(/\./g, '').replace(/,/g, '.'))
  return !isNaN(parsed) && isFinite(parsed) ? parsed : 0
}

const getMonth = (t: string) => {
  if (!t) return ''
  const parts = String(t).match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/)
  if (parts) return Number(parts[2])
  const iso = String(t).match(/(\d{4})-(\d{2})/)
  if (iso) return Number(iso[2])
  return ''
}

const fmtDate = (v: any): string => {
  if (!v) return ''
  const s = String(v)
  const m1 = s.match(/^(\d{2})\/(\d{2})\/(\d{4})\s+(\d{2}):(\d{2}):(\d{2})$/)
  if (m1) return s
  const m1b = s.match(/^(\d{2})\/(\d{2})\/(\d{4})\s+(\d{2}):(\d{2})$/)
  if (m1b) return `${m1b[1]}/${m1b[2]}/${m1b[3]} ${m1b[4]}:${m1b[5]}:00`
  const d = new Date(v)
  if (!isNaN(d.getTime())) {
    const p = (n: number) => String(n).padStart(2, '0')
    return `${p(d.getDate())}/${p(d.getMonth()+1)}/${d.getFullYear()} ${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`
  }
  return s
}

const parseDateStr = (s: string) => {
  if (!s) return null;
  s = String(s);
  const m1 = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})\s+(\d{1,2}):(\d{1,2})(?::(\d{1,2}))?/);
  if (m1) {
    return new Date(`${m1[3]}-${m1[2].padStart(2,'0')}-${m1[1].padStart(2,'0')}T${m1[4].padStart(2,'0')}:${m1[5].padStart(2,'0')}:${(m1[6]||'00').padStart(2,'0')}`);
  }
  const m2 = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m2) {
    return new Date(`${m2[3]}-${m2[2].padStart(2,'0')}-${m2[1].padStart(2,'0')}T00:00:00`);
  }
  const iso = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (iso) {
    return new Date(s);
  }
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
};

const doanhSoBan = (r: any) => toNum(r?.Tong_tien_truoc_thueVAT)
const tongSauVat = (r: any) => {
  const s = toNum(r?.Tong_tien_sau_thueVAT)
  return s > 0 ? s : (toNum(r?.Tong_tien_truoc_thueVAT) + toNum(r?.Tong_thueVAT))
}
const daThanhToan = (r: any) => toNum(r?.so_tien_da_thanh_toan)
const congNo = (r: any) => {
  if (!r) return 0
  if (r.cong_no !== undefined && r.cong_no !== null && r.cong_no !== '') {
    return Math.max(0, toNum(r.cong_no))
  }
  return Math.max(0, tongSauVat(r) - daThanhToan(r))
}

// ─── Payment Due Date & Multi-Installment Helpers ───
const ddmmyyyyToIso = (s: string): string => {
  if (!s) return ''
  const str = String(s).trim()
  const m = str.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/)
  if (m) {
    return `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}`
  }
  const iso = str.match(/^(\d{4})-(\d{2})-(\d{2})/)
  if (iso) return `${iso[1]}-${iso[2]}-${iso[3]}`
  return ''
}

const isoToDdmmyyyy = (iso: string): string => {
  if (!iso) return ''
  const str = String(iso).trim()
  const m = str.match(/^(\d{4})-(\d{2})-(\d{2})/)
  if (m) return `${m[3]}/${m[2]}/${m[1]}`
  const dmy = str.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/)
  if (dmy) return `${dmy[1].padStart(2, '0')}/${dmy[2].padStart(2, '0')}/${dmy[3]}`
  return str
}

const formatDateObjToDdmmyyyy = (d: Date): string => {
  const p = (n: number) => String(n).padStart(2, '0')
  return `${p(d.getDate())}/${p(d.getMonth() + 1)}/${d.getFullYear()}`
}

const addDaysToDateStr = (baseStr: string, days: number): string => {
  const baseDate = parseDateStr(baseStr) || new Date()
  const target = new Date(baseDate.getFullYear(), baseDate.getMonth(), baseDate.getDate())
  target.setDate(target.getDate() + days)
  return formatDateObjToDdmmyyyy(target)
}

const getDaysUntilDue = (dueDateStr: string): number | null => {
  if (!dueDateStr) return null
  const d = parseDateStr(String(dueDateStr).trim())
  if (!d || isNaN(d.getTime())) return null
  const now = new Date()
  const todayMidnight = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime()
  const dueMidnight = new Date(d.getFullYear(), d.getMonth(), d.getDate()).getTime()
  return Math.round((dueMidnight - todayMidnight) / 86400000)
}

const evaluateInstallmentSchedule = (
  totalSau: number,
  paidTotal: number,
  mode: 'mot_lan' | 'nhieu_dot',
  singleDue: string,
  items: PaymentScheduleItem[]
) => {
  const rawList: PaymentScheduleItem[] =
    mode === 'nhieu_dot' && Array.isArray(items) && items.length > 0
      ? items
      : [
          {
            dot: 1,
            noi_dung: 'Thanh toán 100% đơn hàng',
            ty_le_pct: 100,
            so_tien_phai_thu: totalSau,
            han_thanh_toan: singleDue || (Array.isArray(items) && items[0]?.han_thanh_toan) || ''
          }
        ]

  let remainingPaid = Math.max(0, toNum(paidTotal))

  return rawList.map((inst, idx) => {
    const phaiThu = Math.max(0, toNum(inst.so_tien_phai_thu))
    const daThu = Math.min(phaiThu, remainingPaid)
    remainingPaid = Math.max(0, remainingPaid - daThu)
    const conThieu = Math.max(0, phaiThu - daThu)
    const hanTT = String(inst.han_thanh_toan || '').trim()
    const daysDiff = getDaysUntilDue(hanTT)

    let status: 'da_thu_du' | 'qua_han' | 'den_han_hom_nay' | 'sap_den_han' | 'thu_mot_phan' | 'trong_han' | 'chua_co_han' = 'chua_co_han'
    let statusLabel = 'Chưa đặt hạn'
    let statusColor = '#64748b'

    if (conThieu <= 0 && phaiThu > 0) {
      status = 'da_thu_du'
      statusLabel = 'Đã thu đủ'
      statusColor = '#34d399'
    } else if (daysDiff !== null && daysDiff < 0) {
      status = 'qua_han'
      statusLabel = `Quá hạn ${Math.abs(daysDiff)} ngày`
      statusColor = '#f87171'
    } else if (daysDiff !== null && daysDiff === 0) {
      status = 'den_han_hom_nay'
      statusLabel = 'Hôm nay đến hạn'
      statusColor = '#fbbf24'
    } else if (daysDiff !== null && daysDiff > 0 && daysDiff <= 7) {
      status = 'sap_den_han'
      statusLabel = `Sắp đến hạn (còn ${daysDiff} ngày)`
      statusColor = '#fbbf24'
    } else if (daThu > 0) {
      status = 'thu_mot_phan'
      statusLabel = daysDiff !== null ? `Thu 1 phần (còn ${daysDiff} ngày)` : 'Đã thu 1 phần'
      statusColor = '#38bdf8'
    } else if (daysDiff !== null && daysDiff > 7) {
      status = 'trong_han'
      statusLabel = `Trong hạn (còn ${daysDiff} ngày)`
      statusColor = '#94a3b8'
    }

    return {
      dot: inst.dot || idx + 1,
      noi_dung: inst.noi_dung || `Đợt ${idx + 1}`,
      ty_le_pct: toNum(inst.ty_le_pct),
      so_tien_phai_thu: phaiThu,
      han_thanh_toan: hanTT,
      da_thu: daThu,
      con_thieu: conThieu,
      daysDiff,
      status,
      statusLabel,
      statusColor
    }
  })
}

const getPoDueInfo = (r: any) => {
  if (!r) {
    return {
      loaiThanhToan: 'mot_lan' as const,
      totalDots: 1,
      paidDots: 0,
      currentDot: 1,
      nextDueDate: '',
      nextDueAmount: 0,
      daysDiff: null as number | null,
      dueStatus: 'chua_co_han' as const,
      dueBadgeText: ''
    }
  }
  const totalSau = tongSauVat(r)
  const paid = daThanhToan(r)
  const cn = congNo(r)
  const mode: 'mot_lan' | 'nhieu_dot' =
    r.loai_thanh_toan === 'nhieu_dot' || (Array.isArray(r.ke_hoach_thanh_toan) && r.ke_hoach_thanh_toan.length > 1)
      ? 'nhieu_dot'
      : 'mot_lan'
  const schedule: PaymentScheduleItem[] = Array.isArray(r.ke_hoach_thanh_toan) ? r.ke_hoach_thanh_toan : []
  const singleDue = String(r.han_thanh_toan || (schedule[0]?.han_thanh_toan || '')).trim()

  const evalList = evaluateInstallmentSchedule(totalSau, paid, mode, singleDue, schedule)
  const totalDots = evalList.length
  const paidDots = evalList.filter(x => x.con_thieu <= 0 && x.so_tien_phai_thu > 0).length

  if (cn <= 0 && totalSau > 0) {
    const lastDue = evalList[evalList.length - 1]?.han_thanh_toan || singleDue
    return {
      loaiThanhToan: mode,
      totalDots,
      paidDots: totalDots,
      currentDot: totalDots,
      nextDueDate: lastDue,
      nextDueAmount: 0,
      daysDiff: null as number | null,
      dueStatus: 'da_thu_du' as const,
      dueBadgeText: 'Đã tất toán đủ'
    }
  }

  // Tìm đợt chưa thu đủ tiếp theo (ưu tiên đợt quá hạn trước, hoặc đợt chưa thu đầu tiên)
  const unpaidList = evalList.filter(x => x.con_thieu > 0)
  const overdueInst = unpaidList.find(x => x.status === 'qua_han')
  const activeInst = overdueInst || unpaidList[0] || evalList[evalList.length - 1]

  const nextDueDate = activeInst?.han_thanh_toan || singleDue || ''
  const daysDiff = getDaysUntilDue(nextDueDate)
  const currentDot = activeInst?.dot || 1
  const nextDueAmount = activeInst ? activeInst.con_thieu : cn

  let dueStatus: 'qua_han' | 'den_han_hom_nay' | 'sap_den_han' | 'trong_han' | 'chua_co_han' = 'chua_co_han'
  let dueBadgeText = ''

  if (daysDiff !== null && daysDiff < 0) {
    dueStatus = 'qua_han'
    dueBadgeText = mode === 'nhieu_dot'
      ? `Đợt ${currentDot}/${totalDots}: Quá hạn ${Math.abs(daysDiff)} ngày (${nextDueDate})`
      : `Quá hạn ${Math.abs(daysDiff)} ngày (Hạn: ${nextDueDate})`
  } else if (daysDiff !== null && daysDiff === 0) {
    dueStatus = 'den_han_hom_nay'
    dueBadgeText = mode === 'nhieu_dot'
      ? `Đợt ${currentDot}/${totalDots}: Hôm nay đến hạn (${nextDueDate})`
      : `Hôm nay đến hạn (${nextDueDate})`
  } else if (daysDiff !== null && daysDiff > 0 && daysDiff <= 7) {
    dueStatus = 'sap_den_han'
    dueBadgeText = mode === 'nhieu_dot'
      ? `Đợt ${currentDot}/${totalDots}: Còn ${daysDiff} ngày (${nextDueDate})`
      : `Sắp đến hạn: Còn ${daysDiff} ngày (${nextDueDate})`
  } else if (nextDueDate) {
    dueStatus = 'trong_han'
    dueBadgeText = mode === 'nhieu_dot'
      ? `Đợt ${currentDot}/${totalDots} • Hạn TT: ${nextDueDate}`
      : `Hạn TT: ${nextDueDate}`
  } else if (mode === 'nhieu_dot') {
    dueStatus = 'chua_co_han'
    dueBadgeText = `Chia ${totalDots} đợt (Đã thu ${paidDots}/${totalDots} đợt)`
  }

  return {
    loaiThanhToan: mode,
    totalDots,
    paidDots,
    currentDot,
    nextDueDate,
    nextDueAmount,
    daysDiff,
    dueStatus,
    dueBadgeText
  }
}

async function syncAllCustomersCongNo(currentRows?: any[]) {
  try {
    const activeRows = currentRows || officialRows.value || []
    const khSnapshot = await get(dbRef(database, 'khach_hang'))
    const khData = khSnapshot.val() || {}
    khachHangMap.value = khData

    // Tính tổng công nợ theo Ma_khach_hang và Ma_cong_ty từ sale_report
    const debtByMaKH = new Map<string, number>()
    const debtByMaCty = new Map<string, number>()

    activeRows.forEach((r: any) => {
      if (!r || typeof r !== 'object') return
      const d = congNo(r)
      const mkh = String(r.Ma_khach_hang || '').trim()
      const mct = String(r.Ma_cong_ty || '').trim()
      if (mkh) debtByMaKH.set(mkh, (debtByMaKH.get(mkh) || 0) + d)
      if (mct) debtByMaCty.set(mct, (debtByMaCty.get(mct) || 0) + d)
    })

    const updates: Record<string, any> = {}
    Object.entries(khData).forEach(([khKey, khObj]: [string, any]) => {
      if (!khObj || typeof khObj !== 'object') return
      const mkh = String(khObj.ma_khach_hang || khObj.Ma_khach_hang || khKey || '').trim()
      const mct = String(khObj.ma_cong_ty || khObj.Ma_cong_ty || '').trim()
      let totalDebt = 0
      if (mkh && debtByMaKH.has(mkh)) {
        totalDebt = debtByMaKH.get(mkh) || 0
      } else if (mct && debtByMaCty.has(mct)) {
        totalDebt = debtByMaCty.get(mct) || 0
      } else if (mkh && debtByMaCty.has(mkh)) {
        totalDebt = debtByMaCty.get(mkh) || 0
      }
      if (Number(khObj.cong_no) !== totalDebt) {
        updates[`khach_hang/${khKey}/cong_no`] = totalDebt
        khObj.cong_no = totalDebt
      }
    })

    if (Object.keys(updates).length > 0) {
      const cleanUpdates = JSON.parse(JSON.stringify(updates))
    await update(dbRef(database), cleanUpdates)
    }
  } catch (e) {
    console.warn('Lỗi đồng bộ cong_no vào khach_hang:', e)
  }
}

function normalizeLookupKey(s: any): string {
  return String(s || '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, ' ')
}

function findCatalogStandardPrice(maHang: any, tenHang: any): { stdPriceVnd: number; ncc: string } {
  const codeKey = normalizeLookupKey(maHang)
  const nameKey = normalizeLookupKey(tenHang)
  if (!codeKey && !nameKey) return { stdPriceVnd: 0, ncc: '' }

  for (const hh of hangHoaCatalogList.value) {
    const hhCode = normalizeLookupKey(hh.ma_hang)
    const hhName = normalizeLookupKey(hh.ten_hang)
    const isCodeMatch = codeKey && hhCode && (hhCode === codeKey || hhName === codeKey)
    const isNameMatch =
      nameKey &&
      ((hhName && (hhName === nameKey || (nameKey.length >= 4 && hhName.includes(nameKey)) || (hhName.length >= 4 && nameKey.includes(hhName)))) ||
        (hhCode && hhCode.length >= 3 && nameKey.includes(hhCode)))

    if (isCodeMatch || isNameMatch) {
      const basePrice = toNum(hh.gia_tieu_chuan) || toNum(hh.don_gia)
      const rate = toNum(hh.ti_gia) > 0 ? toNum(hh.ti_gia) : 1
      const currency = String(hh.don_vi_tien_te || 'VND').trim().toUpperCase()
      const stdPriceVnd = currency !== 'VND' && rate > 1 ? basePrice * rate : basePrice
      return {
        stdPriceVnd,
        ncc: String(hh.ten_ncc || '').trim()
      }
    }
  }
  return { stdPriceVnd: 0, ncc: '' }
}

const hdChiTietRawMap = ref<Record<string, any>>({})

function chiTietObjToRowArr(item: any): any[] | null {
  if (Array.isArray(item)) return item
  if (item && typeof item === 'object') {
    return [
      item.ma_hop_dong ?? item.Ma_hop_dong ?? '',
      item.so_hop_dong ?? item.So_hop_dong ?? '',
      item.ma_hang ?? item.Ma_hang_hoa ?? item.ma_hang_hoa ?? '',
      item.ten_hang ?? item.Ten_hang_hoa ?? item.ten_hang_hoa ?? '',
      item.main_img ?? '',
      item.ma_ncc ?? item.Ma_nha_cung_cap ?? item.ma_nha_cung_cap ?? '',
      item.ten_ncc ?? item.Ten_nha_cung_cap ?? item.ten_nha_cung_cap ?? '',
      item.mo_ta_chung ?? item.Mo_ta_chung ?? '',
      item.mo_ta_chi_tiet ?? item.Mo_ta_chi_tiet ?? '',
      item.dien_giai ?? item.Dien_giai ?? '',
      item.danh_muc ?? item.Danh_muc ?? '',
      item.ghi_chu ?? item.Ghi_chu ?? '',
      item.dvt ?? item.DVT ?? '',
      item.don_gia ?? item.Don_gia ?? 0,
      item.gia_tieu_chuan ?? item.Gia_tieu_chuan ?? 0,
      item.don_vi_tien_te ?? item.Don_vi_tien_te ?? 'VND',
      item.ti_gia ?? item.Ti_gia ?? 1,
      item.thue_vat ?? item.Thue_VAT ?? 0,
      item.so_luong ?? item.So_luong ?? 1,
      item.features ?? item.Features ?? '',
      item.gia_hardware ?? item.Gia_hardware ?? 0,
      item.gia_nhap ?? item.Gia_nhap ?? 0,
      item.muc_phan_tram_off ?? item.Muc_phan_tram_off ?? 0
    ]
  }
  return null
}

function rebuildHdChiTietDataArray() {
  const chiTietArr: any[] = []
  Object.values(hdChiTietRawMap.value || {}).forEach((item: any) => {
    const arr = chiTietObjToRowArr(item)
    if (arr) chiTietArr.push(arr)
  })
  hdChiTietData.value = chiTietArr
}

function computeCatalogMarkupForChiTietRows(matchedItems: any[]): number {
  let sumMarkup = 0
  let hasValidPriceDiff = false
  for (const arr of matchedItems) {
    const maHang = arr[2]
    const tenHang = arr[3]
    const donGia = toNum(arr[13])
    let giaTieuChuan = toNum(arr[14])
    const tiGia = toNum(arr[16]) > 0 ? toNum(arr[16]) : 1
    const soLuong = toNum(arr[18]) > 0 ? toNum(arr[18]) : 1

    if (giaTieuChuan <= 0 || giaTieuChuan === donGia) {
      const cat = findCatalogStandardPrice(maHang, tenHang)
      if (cat.stdPriceVnd > 0) {
        giaTieuChuan = tiGia > 1 ? cat.stdPriceVnd / tiGia : cat.stdPriceVnd
      }
    }

    if (donGia > 0 && giaTieuChuan > 0 && donGia !== giaTieuChuan) {
      sumMarkup += (donGia - giaTieuChuan) * tiGia * soLuong
      hasValidPriceDiff = true
    }
  }
  return hasValidPriceDiff ? Math.round(sumMarkup) : 0
}

function cleanupDuplicatedChiTietAndAutoInjectedCom() {
  const rawMap = hdChiTietRawMap.value || {}
  const byMaHD = new Map<string, Array<{ key: string; arr: any[] }>>()

  Object.entries(rawMap).forEach(([fbKey, item]) => {
    const arr = chiTietObjToRowArr(item)
    if (!arr) return
    const maHD = String(arr[0] || '').trim()
    if (!maHD) return
    if (!byMaHD.has(maHD)) byMaHD.set(maHD, [])
    byMaHD.get(maHD)!.push({ key: fbKey, arr })
  })

  const fbCleanupUpdates: Record<string, any> = {}
  const rawMarkupByMaHD = new Map<string, number>()
  const dedupMarkupByMaHD = new Map<string, number>()

  byMaHD.forEach((entries, maHD) => {
    const allArrs = entries.map(e => e.arr)
    const rawMarkup = computeCatalogMarkupForChiTietRows(allArrs)
    if (rawMarkup !== 0) rawMarkupByMaHD.set(maHD, rawMarkup)

    const n = entries.length
    if (n >= 2) {
      let dedupBlockLen = n
      for (let m = 1; m <= Math.floor(n / 2); m++) {
        if (n % m !== 0) continue
        let isExactRepeat = true
        for (let i = m; i < n; i++) {
          const a = entries[i % m].arr
          const b = entries[i].arr
          const sigA = `${String(a[2] || '').trim()}|${String(a[3] || '').trim()}|${String(a[9] || '').trim()}|${toNum(a[13])}|${toNum(a[18])}`
          const sigB = `${String(b[2] || '').trim()}|${String(b[3] || '').trim()}|${String(b[9] || '').trim()}|${toNum(b[13])}|${toNum(b[18])}`
          if (sigA !== sigB) {
            isExactRepeat = false
            break
          }
        }
        if (isExactRepeat) {
          const singleBlockSum = entries.slice(0, m).reduce((s, e) => s + toNum(e.arr[13]) * (toNum(e.arr[18]) || 1), 0)
          const matchedPo = officialRows.value.find((r: any) => String(r?.ma_hop_dong || '').trim() === maHD)
          const poDsb = matchedPo ? doanhSoBan(matchedPo) : 0
          const isDefaultRow = m === 1 && String(entries[0].arr[3] || '').trim() === 'Hàng hóa mặc định'
          if (isDefaultRow || (poDsb > 0 && Math.abs(singleBlockSum - poDsb) <= 10)) {
            dedupBlockLen = m
            break
          }
        }
      }

      if (dedupBlockLen < n) {
        const toRemove = entries.slice(0, n - dedupBlockLen)
        toRemove.forEach(rem => {
          delete rawMap[rem.key]
          fbCleanupUpdates[`hop_dong_chi_tiet/${rem.key}`] = null
        })
        const keptArrs = entries.slice(n - dedupBlockLen).map(e => e.arr)
        const dedupMarkup = computeCatalogMarkupForChiTietRows(keptArrs)
        if (dedupMarkup !== 0) dedupMarkupByMaHD.set(maHD, dedupMarkup)
      } else if (rawMarkup !== 0) {
        dedupMarkupByMaHD.set(maHD, rawMarkup)
      }
    } else if (rawMarkup !== 0) {
      dedupMarkupByMaHD.set(maHD, rawMarkup)
    }
  })

  // Làm sạch các PO không có ảnh COM nhưng bị hàm auto-cross-reference cũ tự điền / nhân đôi COM từ chênh lệch giá hang_hoa
  officialRows.value.forEach((r: any) => {
    if (!r || typeof r !== 'object') return
    const hasComImg = Boolean(String(r.img_save || '').trim())
    if (hasComImg) return

    const rMaHD = String(r.ma_hop_dong || '').trim()
    if (!rMaHD) return

    const curGross =
      toNum(r.chiet_khau_tong_truoc_thue) ||
      toNum(r.chenh_lech_gia) ||
      toNum(r.gross_com) ||
      toNum(r.grossCom)
    if (curGross === 0) return

    const rawM = rawMarkupByMaHD.get(rMaHD) || 0
    const dedupM = dedupMarkupByMaHD.get(rMaHD) || 0
    const isAutoMarkupMatch =
      (rawM !== 0 && Math.abs(curGross - rawM) <= 5) ||
      (dedupM !== 0 && (Math.abs(curGross - dedupM) <= 5 || (curGross % dedupM === 0 && curGross / dedupM >= 1 && curGross / dedupM <= 10)))

    if (isAutoMarkupMatch) {
      r.chiet_khau_tong_truoc_thue = 0
      r.chenh_lech_gia = 0
      r.gross_com = 0
      r.grossCom = 0
      r.thue_chenh_lech_gia = 0
      r.con_lai = 0
      r.tong_chiet_khau = 0
      r.net_com = 0
      r.netCom = 0

      const fbKey = r._firebaseKey
      if (fbKey) {
        fbCleanupUpdates[`sale_report/${fbKey}/chiet_khau_tong_truoc_thue`] = 0
        fbCleanupUpdates[`sale_report/${fbKey}/chenh_lech_gia`] = 0
        fbCleanupUpdates[`sale_report/${fbKey}/gross_com`] = 0
        fbCleanupUpdates[`sale_report/${fbKey}/thue_chenh_lech_gia`] = 0
        fbCleanupUpdates[`sale_report/${fbKey}/con_lai`] = 0
        fbCleanupUpdates[`sale_report/${fbKey}/tong_chiet_khau`] = 0
        fbCleanupUpdates[`sale_report/${fbKey}/net_com`] = 0
      }
      if (hopDongTongQuatMap.value && hopDongTongQuatMap.value[rMaHD]) {
        fbCleanupUpdates[`hop_dong_tong_quat/${rMaHD}/gross_com`] = 0
        fbCleanupUpdates[`hop_dong_tong_quat/${rMaHD}/chenh_lech_gia`] = 0
        fbCleanupUpdates[`hop_dong_tong_quat/${rMaHD}/chiet_khau_tong_truoc_thue`] = 0
        fbCleanupUpdates[`hop_dong_tong_quat/${rMaHD}/thue_chenh_lech_gia`] = 0
        fbCleanupUpdates[`hop_dong_tong_quat/${rMaHD}/tong_chiet_khau`] = 0
        fbCleanupUpdates[`hop_dong_tong_quat/${rMaHD}/con_lai`] = 0
      }
    }
  })

  rebuildHdChiTietDataArray()

  if (Object.keys(fbCleanupUpdates).length > 0) {
    update(dbRef(database), fbCleanupUpdates).catch(err =>
      console.warn('Cleanup duplicated hop_dong_chi_tiet / auto-injected COM error:', err)
    )
  }
}

function crossReferenceFinancialsForImportedQuote(itemObj: any) {
  if (!itemObj) return

  // Chỉ tự động nhận diện Nhà cung cấp (NCC) từ bảng hang_hoa nếu chưa có, KHÔNG tự động điền Gross COM / Net COM
  if (!itemObj.productType && Array.isArray(itemObj.goodsList) && itemObj.goodsList.length > 0 && hangHoaCatalogList.value.length > 0) {
    for (const g of itemObj.goodsList) {
      const cat = findCatalogStandardPrice(g.ten, g.dienGiai || g.ten)
      if (cat.ncc) {
        itemObj.productType = matchHangHoaNcc(cat.ncc) || cat.ncc
        break
      }
    }
  }
}

async function loadData() {
  loading.value = true
  try {
    // Khởi tạo trước danh sách NCC từ cache nhẹ để bộ lọc NCC hoạt động tức thì mà KHÔNG cần tải bảng hang_hoa nặng khi vào trang
    if (hangHoaNccList.value.length === 0) {
      const cachedNccs = loadNccListFromLocalCache()
      if (cachedNccs.length > 0) {
        hangHoaNccList.value = cachedNccs
      }
    }

    // ─── Read sale_report, hop_dong_tong_quat, sale_report_craft from Firebase in parallel (KHÔNG gọi hang_hoa lúc mới vào trang) ───
    const [saleReportRes, hdTongQuatRes, srCraftRes] = await Promise.allSettled([
      get(dbRef(database, 'sale_report')),
      get(dbRef(database, 'hop_dong_tong_quat')),
      get(dbRef(database, 'sale_report_craft'))
    ])

    if (hdTongQuatRes.status === 'fulfilled') {
      hopDongTongQuatMap.value = hdTongQuatRes.value.val() || {}
    }
    if (srCraftRes.status === 'fulfilled') {
      saleReportCraftMap.value = srCraftRes.value.val() || {}
    }

    if (saleReportRes.status === 'rejected') {
      throw saleReportRes.reason
    }
    const saleReportData = saleReportRes.value.val() || {}
    
    const mappedRows: any[] = []
    const backfillUpdates: Record<string, any> = {}

    Object.entries(saleReportData).forEach(([firebaseKey, item]: [string, any]) => {
      if (!item || typeof item !== 'object') return
      const tSau = Number(item.Tong_tien_sau_thueVAT) > 0
        ? Number(item.Tong_tien_sau_thueVAT)
        : (Number(item.Tong_tien_truoc_thueVAT) || 0) + (Number(item.Tong_thueVAT) || 0)
      const daTT = Number(item.so_tien_da_thanh_toan) || 0
      const cn = (item.cong_no !== undefined && item.cong_no !== null && item.cong_no !== '')
        ? Math.max(0, Number(item.cong_no) || 0)
        : Math.max(0, tSau - daTT)
      const tgTT = item.thoi_gian_thanh_toan !== undefined ? String(item.thoi_gian_thanh_toan || '') : ''
      const loaiTT: 'mot_lan' | 'nhieu_dot' =
        item.loai_thanh_toan === 'nhieu_dot' || (Array.isArray(item.ke_hoach_thanh_toan) && item.ke_hoach_thanh_toan.length > 1)
          ? 'nhieu_dot'
          : 'mot_lan'
      const hanTT = item.han_thanh_toan !== undefined ? String(item.han_thanh_toan || '') : ''
      const keHoachTT = Array.isArray(item.ke_hoach_thanh_toan) ? item.ke_hoach_thanh_toan : []
      const danhSachFileKhac = Array.isArray(item.danh_sach_file_khac)
        ? item.danh_sach_file_khac.filter(Boolean)
        : (item.danh_sach_file_khac && typeof item.danh_sach_file_khac === 'object'
            ? Object.values(item.danh_sach_file_khac).filter(Boolean)
            : [])

      if (item.so_tien_da_thanh_toan === undefined || item.cong_no === undefined || item.thoi_gian_thanh_toan === undefined) {
        backfillUpdates[`sale_report/${firebaseKey}/so_tien_da_thanh_toan`] = daTT
        backfillUpdates[`sale_report/${firebaseKey}/cong_no`] = cn
        backfillUpdates[`sale_report/${firebaseKey}/thoi_gian_thanh_toan`] = tgTT
      }

      mappedRows.push({
        ...item,
        so_tien_da_thanh_toan: daTT,
        cong_no: cn,
        thoi_gian_thanh_toan: tgTT,
        loai_thanh_toan: loaiTT,
        han_thanh_toan: hanTT,
        ke_hoach_thanh_toan: keHoachTT,
        danh_sach_file_khac: danhSachFileKhac,
        _firebaseKey: firebaseKey, // lưu key Firebase để update/delete
        ID: item.ID || firebaseKey
      })
    })
    officialRows.value = mappedRows

    // ─── Map sale_report_craft (Bản tạm chưa chốt deal) sang cấu trúc chuẩn của SaleReportFirebase.vue ───
    const closedCraftKeys = new Set<string>()
    mappedRows.forEach((offRow: any) => {
      const fc = String(offRow?.from_craft || '').trim()
      if (fc) closedCraftKeys.add(fc)
    })
    const mappedCrafts: any[] = []
    let runningMaxPo = 0
    mappedRows.forEach((offRow: any) => {
      const n = parseInt(String(offRow?.So_PO || ''), 10)
      if (!isNaN(n) && n > runningMaxPo) runningMaxPo = n
    })
    Object.values(saleReportCraftMap.value || {}).forEach((c: any) => {
      const raw = String(c?.So_PO || c?.soPO || '').trim()
      if (/^\d+$/.test(raw)) {
        const n = parseInt(raw, 10)
        if (!isNaN(n) && n > runningMaxPo) runningMaxPo = n
      }
    })
    Object.entries(saleReportCraftMap.value || {}).forEach(([craftKey, c]: [string, any]) => {
      if (!c || typeof c !== 'object') return
      if (c.chotDeal === true || closedCraftKeys.has(craftKey)) return
      const dsb = toNum(c.Tong_tien_truoc_thueVAT ?? c.doanhSoBan ?? c.goodsTotal?.ttTruoc ?? 0)
      const vat = toNum(c.Tong_thueVAT ?? c.goodsTotal?.vat ?? 0)
      const tSauCraft = toNum(c.Tong_tien_sau_thueVAT) > 0 ? toNum(c.Tong_tien_sau_thueVAT) : dsb + vat
      const gm = toNum(c.Tong_thanh_tien_chua_VAT_mua_hang ?? c.giaMua ?? 0)
      const tcp = toNum(c.Tong_CP_don_hang ?? c.tongCP ?? gm)
      const gCom = toNum(c.chiet_khau_tong_truoc_thue ?? c.chenh_lech_gia ?? c.gross_com ?? c.grossCom ?? 0)
      const tPct =
        c.phan_tram_thue_chenh_lech_gia !== undefined && c.phan_tram_thue_chenh_lech_gia !== ''
          ? toNum(c.phan_tram_thue_chenh_lech_gia)
          : c.taxPct !== undefined && c.taxPct !== ''
            ? toNum(c.taxPct)
            : 25
      const tCom =
        c.thue_chenh_lech_gia !== undefined && c.thue_chenh_lech_gia !== ''
          ? toNum(c.thue_chenh_lech_gia)
          : Math.round(gCom * (tPct / 100))
      const nCom =
        c.con_lai !== undefined && c.con_lai !== ''
          ? toNum(c.con_lai)
          : c.netCom !== undefined && c.netCom !== ''
            ? toNum(c.netCom)
            : Math.round(gCom - tCom)
      const tenCongTy = String(c.Ten_cong_ty || c.customer || c.Ten_khach_hang || c.recipient || 'Khách hàng (Bản tạm)').trim()
      const tenKhachHang = String(c.Ten_khach_hang || c.recipient || tenCongTy).trim()
      const maCongTy = String(c.Ma_cong_ty || c.linkedMaCongTy || genMaCongTy(tenCongTy) || 'CTY_CRAFT').trim()
      const maKhachHang = String(c.Ma_khach_hang || c.linkedMaKH || genMaKhachHang(tenKhachHang, tenCongTy) || maCongTy).trim()
      const rawSoPo = String(c.So_PO || c.soPO || '').trim()
      const isCleanPo = Boolean(rawSoPo && !/^(PA[-_\s]?\d+|.*-PA\d+)$/i.test(rawSoPo))
      const finalCraftSoPo = isCleanPo ? rawSoPo : String(++runningMaxPo)
      if (!isCleanPo) {
        backfillUpdates[`sale_report_craft/${craftKey}/So_PO`] = finalCraftSoPo
      }
      const danhSachFileKhacCraft = Array.isArray(c.danh_sach_file_khac)
        ? c.danh_sach_file_khac.filter(Boolean)
        : c.danh_sach_file_khac && typeof c.danh_sach_file_khac === 'object'
          ? Object.values(c.danh_sach_file_khac).filter(Boolean)
          : []
      const rawGoodsList = Array.isArray(c.goodsList)
        ? c.goodsList.filter(Boolean)
        : c.goodsList && typeof c.goodsList === 'object'
          ? Object.values(c.goodsList).filter(Boolean)
          : []

      mappedCrafts.push({
        ...c,
        So_PO: finalCraftSoPo,
        Ten_nha_cung_cap: String(c.Ten_nha_cung_cap || c.productType || '').trim(),
        Ma_cong_ty: maCongTy,
        Ten_cong_ty: tenCongTy,
        Ma_khach_hang: maKhachHang,
        Ten_khach_hang: tenKhachHang,
        MST: String(c.MST || c.mst || '').trim(),
        created_time: String(c.created_time || c.createdTime || '').trim() || getFormattedNow(),
        content_of_contract_PO: String(c.content_of_contract_PO || c.content || '').trim(),
        ghi_chu: String(c.ghi_chu || c.ghiChu || '').trim(),
        Tong_tien_truoc_thueVAT: dsb,
        Tong_thueVAT: vat,
        Tong_tien_sau_thueVAT: tSauCraft,
        Tong_thanh_tien_chua_VAT_mua_hang: gm,
        Tong_CP_don_hang: tcp,
        chiet_khau_tong_truoc_thue: gCom,
        chenh_lech_gia: gCom,
        gross_com: gCom,
        phan_tram_thue_chenh_lech_gia: tPct,
        thue_chenh_lech_gia: tCom,
        con_lai: nCom,
        tong_chiet_khau: nCom,
        net_com: nCom,
        account_manager_name: String(c.account_manager_name || c.am || '').trim(),
        img_save: String(c.img_save || c.existingImgUrl || '').trim(),
        link_excel_bao_gia: String(c.link_excel_bao_gia || c.linkBaoGia || '').trim(),
        link_excel_mua_hang: String(c.link_excel_mua_hang || c.linkMuaHang || '').trim(),
        link_excel_dxmh: String(c.link_excel_dxmh || c.linkDxmh || '').trim(),
        ten_file_bao_gia: String(c.ten_file_bao_gia || c.tenFileBG || '').trim(),
        ten_file_mua_hang: String(c.ten_file_mua_hang || c.tenFileMH || '').trim(),
        ten_file_dxmh: String(c.ten_file_dxmh || c.tenFileDxmh || '').trim(),
        so_tien_da_thanh_toan: toNum(c.so_tien_da_thanh_toan),
        cong_no: Math.max(0, tSauCraft - toNum(c.so_tien_da_thanh_toan)),
        thoi_gian_thanh_toan: String(c.thoi_gian_thanh_toan || ''),
        loai_thanh_toan: 'mot_lan',
        han_thanh_toan: String(c.han_thanh_toan || ''),
        ke_hoach_thanh_toan: [],
        danh_sach_file_khac: danhSachFileKhacCraft,
        goodsList: rawGoodsList,
        goodsTotal: c.goodsTotal || (dsb > 0 ? { ttTruoc: dsb, vat, ttSau: tSauCraft } : null),
        _isCraft: true,
        _firebaseKey: craftKey,
        ID: c.ID || craftKey
      })
    })
    craftRows.value = mappedCrafts

    if (Object.keys(backfillUpdates).length > 0) {
      update(dbRef(database), backfillUpdates).catch(err => console.warn('Backfill sale_report debt fields error:', err))
    }

    // ─── Read lich_su_thanh_toan from Firebase ───
    try {
      const lsttSnapshot = await get(dbRef(database, 'lich_su_thanh_toan'))
      const lsttData = lsttSnapshot.val() || {}
      const list: any[] = []
      Object.entries(lsttData).forEach(([key, val]: [string, any]) => {
        if (val && typeof val === 'object') {
          list.push({
            ...val,
            id: val.id || key,
            _firebaseKey: key
          })
        }
      })
      list.sort((a, b) => {
        const da = parseDateStr(a.thoi_gian_thanh_toan)?.getTime() || 0
        const db = parseDateStr(b.thoi_gian_thanh_toan)?.getTime() || 0
        if (db !== da) return db - da
        return String(b.id || '').localeCompare(String(a.id || ''))
      })
      lichSuThanhToanList.value = list
    } catch (e) {
      console.warn('Lỗi load lich_su_thanh_toan từ Firebase:', e)
    }

    // ─── Sync cong_no to khach_hang (non-blocking) ───
    syncAllCustomersCongNo(mappedRows)
    
    // ─── Read hop_dong_chi_tiet from Firebase ───
    try {
      const chiTietSnapshot = await get(dbRef(database, 'hop_dong_chi_tiet'))
      const chiTietData = chiTietSnapshot.val() || {}
      hdChiTietRawMap.value = { ...chiTietData }
      rebuildHdChiTietDataArray()
    } catch(e) {
      console.warn('Lỗi load hd_chi_tiet từ Firebase:', e)
    }

    // ─── Làm sạch các dòng hop_dong_chi_tiet bị nhân bản & số COM tự nhảy do lỗi cũ ───
    cleanupDuplicatedChiTietAndAutoInjectedCom()
  } catch (e) {
    console.error('Lỗi load sale_report từ Firebase:', e)
    officialRows.value = []
    craftRows.value = []
  } finally {
    loading.value = false
  }
}

onMounted(() => {
  loadData()
  if (typeof document !== 'undefined') {
    document.addEventListener('click', handleOutsideSalePickerClick)
  }
})

onUnmounted(() => {
  if (typeof document !== 'undefined') {
    document.removeEventListener('click', handleOutsideSalePickerClick)
  }
})

const uniqueAMs = computed(() => {
  const set = new Set<string>()
  rows.value.forEach(r => {
    if (r.account_manager_name) set.add(r.account_manager_name)
  })
  return [...set].sort()
})

const filteredCustomerOptions = computed(() => {
  const search = (filterCustomer.value || '').toLowerCase().trim();
  const allOptions = uniqueCustomers.value;
  if (!search || search === 'tất cả') return [{ companyName: 'Tất cả' }, ...allOptions];
  
  return allOptions.filter(c => 
    c.companyName.toLowerCase().includes(search) || 
    c.customerName.toLowerCase().includes(search) ||
    c.companyCode.toLowerCase().includes(search)
  );
});

const selectCustomerOption = (c: any) => {
  filterCustomer.value = c.companyName === 'Tất cả' ? 'Tất cả' : c.companyName;
  showCustomerDropdown.value = false;
};

const onCustomerInputBlur = () => {
  setTimeout(() => {
    showCustomerDropdown.value = false;
    if (!filterCustomer.value) {
      filterCustomer.value = 'Tất cả';
    }
  }, 200); // delay to allow click event on dropdown items
};

const uniqueCustomers = computed(() => {
  const map = new Map();
  rows.value.forEach(r => {
    const maCty = String(r.Ma_cong_ty || '').trim();
    const cn = congNo(r);
    const dsb = doanhSoBan(r);
    const mst = String(r.MST || '').trim();
    if (maCty) {
      if (!map.has(maCty)) {
        map.set(maCty, {
          companyName: String(r.Ten_cong_ty || '').trim() || maCty,
          customerName: String(r.Ten_khach_hang || '').trim(),
          companyCode: maCty,
          mst: mst && mst !== 'N/A' ? mst : '',
          poCount: 0,
          totalDsb: 0,
          totalCongNo: 0
        });
      }
      const item = map.get(maCty);
      item.poCount += 1;
      item.totalDsb += dsb;
      item.totalCongNo += cn;
      if (!item.mst && mst && mst !== 'N/A') item.mst = mst;
      if (!item.customerName && r.Ten_khach_hang) item.customerName = String(r.Ten_khach_hang).trim();
    } else {
      const cty = String(r.Ten_cong_ty || '').trim();
      if (cty) {
        if (!map.has(cty)) {
          map.set(cty, {
            companyName: cty,
            customerName: String(r.Ten_khach_hang || '').trim(),
            companyCode: '',
            mst: mst && mst !== 'N/A' ? mst : '',
            poCount: 0,
            totalDsb: 0,
            totalCongNo: 0
          });
        }
        const item = map.get(cty);
        item.poCount += 1;
        item.totalDsb += dsb;
        item.totalCongNo += cn;
        if (!item.mst && mst && mst !== 'N/A') item.mst = mst;
        if (!item.customerName && r.Ten_khach_hang) item.customerName = String(r.Ten_khach_hang).trim();
      }
    }
  });
  return Array.from(map.values()).sort((a, b) => a.companyName.localeCompare(b.companyName));
});

function matchesSaleSearchRow(r: any, rawQuery: string): boolean {
  const trimmed = String(rawQuery || '').trim().toLowerCase()
  if (!trimmed) return true
  const words = trimmed.split(/\s+/).filter(Boolean)
  if (!words.length) return true
  const rowText = Object.values(r).map(v => String(v ?? '')).join(' ').toLowerCase()
  return words.every(w => rowText.includes(w))
}

const filteredRows = computed(() => {
  let list = rows.value
  if (searchStr.value && searchStr.value.trim()) {
    list = list.filter(r => matchesSaleSearchRow(r, searchStr.value))
  }
  
  list = list.filter(r => {
    if (!r.created_time) return true
    const d = parseDateStr(r.created_time)
    if (!d) return true
    
    if (timeFilterMode.value === 'day') {
      if (dateFrom.value && new Date(dateFrom.value) > d) return false
      if (dateTo.value) {
        const to = new Date(dateTo.value)
        to.setHours(23, 59, 59, 999)
        if (to < d) return false
      }
    } else if (timeFilterMode.value === 'month') {
      const rowMonthStr = `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`
      if (monthFrom.value && monthFrom.value > rowMonthStr) return false
      if (monthTo.value && monthTo.value < rowMonthStr) return false
    } else if (timeFilterMode.value === 'year') {
      const y = d.getFullYear()
      if (yearFrom.value && parseInt(yearFrom.value) > y) return false
      if (yearTo.value && parseInt(yearTo.value) < y) return false
    }
    return true
  })

  if (filterAM.value) {
    list = list.filter(r => r.account_manager_name === filterAM.value)
  }

  if (filterCustomer.value && filterCustomer.value !== 'Tất cả') {
    const target = filterCustomer.value.toLowerCase().trim();
    const exactMatch = uniqueCustomers.value.find(c => c.companyName.toLowerCase() === target);
    const targetCode = exactMatch ? exactMatch.companyCode.toLowerCase() : '';

    list = list.filter(r => {
      const ten = String(r.Ten_cong_ty || '').toLowerCase();
      const tenKh = String(r.Ten_khach_hang || '').toLowerCase();
      const macty = String(r.Ma_cong_ty || '').toLowerCase();
      
      if (targetCode && macty === targetCode) return true;
      return ten.includes(target) || tenKh.includes(target) || macty.includes(target);
    });
  }

  if (filterProductType.value !== 'Tất cả') {
    const targetLower = filterProductType.value.toLowerCase()
    list = list.filter(r => r.Ten_nha_cung_cap && String(r.Ten_nha_cung_cap).toLowerCase().trim() === targetLower)
  }

  if (filterDebtStatus.value && filterDebtStatus.value !== 'Tất cả') {
    list = list.filter(r => {
      const cn = congNo(r)
      const dtt = daThanhToan(r)
      const dueInfo = getPoDueInfo(r)
      if (filterDebtStatus.value === 'Còn công nợ') return cn > 0
      if (filterDebtStatus.value === 'Quá hạn thanh toán') return cn > 0 && dueInfo.dueStatus === 'qua_han'
      if (filterDebtStatus.value === 'Sắp đến hạn') return cn > 0 && (dueInfo.dueStatus === 'sap_den_han' || dueInfo.dueStatus === 'den_han_hom_nay')
      if (filterDebtStatus.value === 'Chưa thanh toán') return cn > 0 && dtt <= 0
      if (filterDebtStatus.value === 'Thanh toán 1 phần') return cn > 0 && dtt > 0
      if (filterDebtStatus.value === 'Đã tất toán') return cn <= 0
      return true
    })
  }

  list.sort((a, b) => {
    if (sortPoOrder.value === 'PO giảm') {
      const pa = parseInt(String(a.So_PO).replace(/\D/g, '')) || 0
      const pb = parseInt(String(b.So_PO).replace(/\D/g, '')) || 0
      if (pa !== pb) return pb - pa
    } else if (sortPoOrder.value === 'PO tăng') {
      const pa = parseInt(String(a.So_PO).replace(/\D/g, '')) || 0
      const pb = parseInt(String(b.So_PO).replace(/\D/g, '')) || 0
      if (pa !== pb) return pa - pb
    }
    const da = parseDateStr(a.created_time)?.getTime() || 0
    const db = parseDateStr(b.created_time)?.getTime() || 0
    return sortOrder.value === 'Mới nhất' ? db - da : da - db
  })

  return list
})

const displayLimit = ref(15)
const PO_LAZY_BATCH_SIZE = 8
const groupPoVisibleLimitMap = ref<Record<string, number>>({})

watch(filteredRows, () => {
  displayLimit.value = 15
  groupPoVisibleLimitMap.value = {}
})

function getGroupPoLimit(group: any): number {
  const key = getGroupCollapseKey(group)
  return groupPoVisibleLimitMap.value[key] || PO_LAZY_BATCH_SIZE
}

function getVisibleGroupPoItems(group: any): any[] {
  if (!Array.isArray(group?.items)) return []
  return group.items.slice(0, getGroupPoLimit(group))
}

function hasMoreGroupPoItems(group: any): boolean {
  return Array.isArray(group?.items) && group.items.length > getGroupPoLimit(group)
}

function loadMoreGroupPoItems(group: any) {
  if (!group) return
  const key = getGroupCollapseKey(group)
  const current = groupPoVisibleLimitMap.value[key] || PO_LAZY_BATCH_SIZE
  const total = Array.isArray(group.items) ? group.items.length : current
  if (current >= total) return
  groupPoVisibleLimitMap.value = {
    ...groupPoVisibleLimitMap.value,
    [key]: Math.min(total, current + PO_LAZY_BATCH_SIZE)
  }
}

const vPoLazyObserver = {
  mounted(el: HTMLElement, binding: { value: () => void }) {
    ;(el as any)._poLazyCallback = binding.value
    if (typeof IntersectionObserver === 'undefined') return
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          const cb = (el as any)._poLazyCallback
          if (entry.isIntersecting && typeof cb === 'function') {
            cb()
          }
        })
      },
      { root: null, rootMargin: '320px 0px', threshold: 0.01 }
    )
    observer.observe(el)
    ;(el as any)._poLazyObserver = observer
  },
  updated(el: HTMLElement, binding: { value: () => void }) {
    ;(el as any)._poLazyCallback = binding.value
  },
  unmounted(el: HTMLElement) {
    const observer = (el as any)._poLazyObserver as IntersectionObserver | undefined
    if (observer) {
      observer.disconnect()
      delete (el as any)._poLazyObserver
    }
    delete (el as any)._poLazyCallback
  }
}

const displayedRows = computed(() => {
  return filteredRows.value.slice(0, displayLimit.value)
})

const groupedDisplayedRows = computed(() => {
  const map = new Map();
  displayedRows.value.forEach(r => {
    const maCty = r.Ma_cong_ty || 'Khác';
    const mstVal = String(r.MST || '').trim();
    if (!map.has(maCty)) {
      map.set(maCty, {
        ma_cong_ty: maCty,
        ten_cong_ty: r.Ten_cong_ty || 'N/A',
        mst: mstVal,
        items: []
      });
    } else if (mstVal && !map.get(maCty).mst) {
      map.get(maCty).mst = mstVal;
    }
    map.get(maCty).items.push(r);
  });
  return Array.from(map.values());
});

const collapsedGroupMap = ref<Record<string, boolean>>({})
const collapsedPoCardMap = ref<Record<string, boolean>>({})
const isAllCardsCollapsed = ref(false)

function getGroupCollapseKey(group: any): string {
  return String(group?.ma_cong_ty || group?.ten_cong_ty || 'Khác')
}

function isGroupCollapsed(group: any): boolean {
  return !!collapsedGroupMap.value[getGroupCollapseKey(group)]
}

function toggleGroupCollapse(group: any) {
  const key = getGroupCollapseKey(group)
  collapsedGroupMap.value = {
    ...collapsedGroupMap.value,
    [key]: !collapsedGroupMap.value[key]
  }
}

const areAllGroupsCollapsed = computed(() => {
  if (groupedDisplayedRows.value.length === 0) return false
  return groupedDisplayedRows.value.every(g => isGroupCollapsed(g))
})

function toggleAllGroupsCollapse() {
  const nextState = !areAllGroupsCollapsed.value
  const nextMap: Record<string, boolean> = { ...collapsedGroupMap.value }
  groupedDisplayedRows.value.forEach(g => {
    nextMap[getGroupCollapseKey(g)] = nextState
  })
  collapsedGroupMap.value = nextMap
}

function isPoCardCollapsed(r: any): boolean {
  const key = String(getPoRowKey(r) || r?.So_PO || '')
  if (key && key in collapsedPoCardMap.value) {
    return !!collapsedPoCardMap.value[key]
  }
  return isAllCardsCollapsed.value
}

function togglePoCardCollapse(r: any) {
  const key = String(getPoRowKey(r) || r?.So_PO || '')
  if (!key) return
  const current = isPoCardCollapsed(r)
  collapsedPoCardMap.value = {
    ...collapsedPoCardMap.value,
    [key]: !current
  }
}

function toggleAllPoCardsCollapse() {
  isAllCardsCollapsed.value = !isAllCardsCollapsed.value
  collapsedPoCardMap.value = {}
}

