const getGroupItemsArray = (groupOrItems: any): any[] => {
  return Array.isArray(groupOrItems)
    ? groupOrItems
    : (Array.isArray(groupOrItems?.items) ? groupOrItems.items : [])
}

const getGroupDoanhSoBan = (groupOrItems: any) => {
  return getGroupItemsArray(groupOrItems).reduce((s: number, r: any) => s + doanhSoBan(r), 0)
}
const getGroupNetPO = (groupOrItems: any) => {
  return getGroupItemsArray(groupOrItems).reduce((s: number, r: any) => s + netPO(r), 0)
}
const getGroupTongSauVat = (groupOrItems: any) => {
  return getGroupItemsArray(groupOrItems).reduce((s: number, r: any) => s + tongSauVat(r), 0)
}
const getGroupGrossCom = (groupOrItems: any) => {
  return getGroupItemsArray(groupOrItems).reduce((s: number, r: any) => s + grossCom(r), 0)
}
const getGroupNetCom = (groupOrItems: any) => {
  return getGroupItemsArray(groupOrItems).reduce((s: number, r: any) => s + netCom(r), 0)
}
const getGroupNetComPct = (groupOrItems: any) => {
  const np = getGroupNetPO(groupOrItems)
  return np !== 0 ? (getGroupNetCom(groupOrItems) / np) * 100 : 0
}
const getGroupNetComDsbPct = (groupOrItems: any) => {
  const dsb = getGroupDoanhSoBan(groupOrItems)
  return dsb !== 0 ? (getGroupNetCom(groupOrItems) / dsb) * 100 : 0
}
const getGroupNetMargin = (groupOrItems: any) => {
  return getGroupItemsArray(groupOrItems).reduce((s: number, r: any) => s + netMargin(r), 0)
}
const getGroupNetMarginPct = (groupOrItems: any) => {
  const np = getGroupNetPO(groupOrItems)
  return np !== 0 ? (getGroupNetMargin(groupOrItems) / np) * 100 : 0
}
const getGroupNetMarginDsbPct = (groupOrItems: any) => {
  const dsb = getGroupDoanhSoBan(groupOrItems)
  return dsb !== 0 ? (getGroupNetMargin(groupOrItems) / dsb) * 100 : 0
}
const getGroupCongNo = (groupOrItems: any) => {
  return getGroupItemsArray(groupOrItems).reduce((s: number, r: any) => s + congNo(r), 0)
}
const getGroupDaThanhToan = (groupOrItems: any) => {
  return getGroupItemsArray(groupOrItems).reduce((s: number, r: any) => s + daThanhToan(r), 0)
}
const getGroupUnpaidPoCount = (groupOrItems: any) => {
