function getMobileDockCompanyShortName(group: any): string {
  if (!group) return 'Chưa chọn Cty'
  const tenKh = getGroupTenKhachHang(group)
  if (tenKh && tenKh.length <= 15) return tenKh
  const rawName = String(group.ten_cong_ty || group.ma_cong_ty || 'Công ty').trim()
  const cleaned = rawName
    .replace(/^(CÔNG TY TNHH MTV|CÔNG TY TNHH MỘT THÀNH VIÊN|CÔNG TY TNHH|CÔNG TY CỔ PHẦN|CÔNG TY CP|CHI NHÁNH CÔNG TY|TẬP ĐOÀN|CÔNG TY)\s+/i, '')
    .trim()
  const finalLabel = cleaned || rawName
  return finalLabel.length > 14 ? finalLabel.slice(0, 13).trim() + '…' : finalLabel
}

function getGroupTenKhachHang(group: any): string {
  if (!group) return ''
  const items: any[] = Array.isArray(group.items) ? group.items : []
  const tenCtyNorm = String(group.ten_cong_ty || '').trim().toLowerCase()
  let firstNonEmpty = ''
  for (const r of items) {
    const kh = String(r?.Ten_khach_hang || '').trim()
    if (kh && kh !== 'N/A') {
      if (!firstNonEmpty) firstNonEmpty = kh
      if (kh.toLowerCase() !== tenCtyNorm) return kh
    }
  }
  const maCty = String(group.ma_cong_ty || '').trim().toUpperCase()
  const mst = String(group.mst || '').trim().toUpperCase()
  const khEntries = Object.entries(khachHangMap.value || {})
  for (const [, khObj] of khEntries) {
    if (!khObj || typeof khObj !== 'object') continue
    const cMct = String(khObj.ma_cong_ty || khObj.Ma_cong_ty || '').trim().toUpperCase()
    const cMst = String(khObj.mst || khObj.MST || '').trim().toUpperCase()
    if ((maCty && maCty !== 'KHÁC' && cMct === maCty) || (mst && mst !== 'N/A' && cMst === mst)) {
      const dbKh = String(khObj.ten_khach_hang || khObj.Ten_khach_hang || '').trim()
      if (dbKh) return dbKh
    }
  }
  return firstNonEmpty
}

function getPoCardOtherFilesList(r: any): Array<{ id: string; ten_file: string; link_file: string; isImage?: boolean }> {
  const out: Array<{ id: string; ten_file: string; link_file: string; isImage?: boolean }> = []
  if (Array.isArray(r?.danh_sach_file_khac)) {
    r.danh_sach_file_khac.forEach((f: any, idx: number) => {
      if (!f) return
      out.push({
        id: String(f.id || `other_${idx}`),
        ten_file: String(f.ten_file || `Tệp đính kèm #${idx + 1}`),
        link_file: String(f.link_file || ''),
        isImage: false
      })
    })
  }
  if (r?.img_save) {
    out.push({
      id: 'img_save',
      ten_file: 'Ảnh đính kèm (IMG)',
      link_file: String(r.img_save),
      isImage: true
    })
  }
  return out
}

