const filteredSidebarGroups = computed(() => {
  const q = (companySidebarSearch.value || '').toLowerCase().trim()
  let list = allGroupedFilteredRows.value
  if (q) {
    list = list.filter(g => {
      const matchCompany =
        String(g.ma_cong_ty || '').toLowerCase().includes(q) ||
        String(g.ten_cong_ty || '').toLowerCase().includes(q) ||
        String(getGroupTenKhachHang(g) || '').toLowerCase().includes(q) ||
        String(g.mst || '').toLowerCase().includes(q)
      if (matchCompany) return true
      return Array.isArray(g.items) && g.items.some((r: any) =>
        String(r.So_PO || '').toLowerCase().includes(q) ||
        String(r.Ten_khach_hang || '').toLowerCase().includes(q)
      )
    })
  }
  if (companySidebarSort.value === 'dsb_desc') {
    return [...list].sort((a, b) => getGroupDoanhSoBan(b) - getGroupDoanhSoBan(a))
  }
  if (companySidebarSort.value === 'debt_desc') {
    return [...list].sort((a, b) => getGroupCongNo(b) - getGroupCongNo(a))
  }
  if (companySidebarSort.value === 'po_desc') {
    return [...list].sort((a, b) => b.items.length - a.items.length)
  }
  return list
})

