const sumScopeCol = (rowsList: any[], metric: string): number => {
  return rowsList.reduce((acc, r) => {
    const { num } = getRowMetricNumDen(r, metric)
    return acc + (Number(num) || 0)
  }, 0)
}

const calcScopeMetricTotal = (rowsList: any[], metric: string): number => {
  if (!rowsList || rowsList.length === 0) return 0
  if (metric === 'totalNetComPct') {
    const np = sumScopeCol(rowsList, 'netPO')
    return np !== 0 ? (sumScopeCol(rowsList, 'netCom') / np) * 100 : 0
  }
  if (metric === 'totalNetMarginPct') {
    const np = sumScopeCol(rowsList, 'netPO')
    return np !== 0 ? (sumScopeCol(rowsList, 'netMargin') / np) * 100 : 0
  }
  if (metric === 'totalNetComDsbPct') {
    const dsb = sumScopeCol(rowsList, 'doanhSoBan')
    return dsb !== 0 ? (sumScopeCol(rowsList, 'netCom') / dsb) * 100 : 0
  }
  if (metric === 'totalNetMarginDsbPct') {
    const dsb = sumScopeCol(rowsList, 'doanhSoBan')
    return dsb !== 0 ? (sumScopeCol(rowsList, 'netMargin') / dsb) * 100 : 0
  }
  return sumScopeCol(rowsList, metric)
}

