const resolvedGranularity = computed<'day' | 'month' | 'quarter' | 'year'>(() => {
  if (chartGranularity.value !== 'auto') return chartGranularity.value
  if (timeFilterMode.value === 'day') return 'day'
  if (timeFilterMode.value === 'year') return 'year'
  return 'month'
})

const getRowMetricNumDen = (r: any, metric: string): { num: number; den: number } => {
  switch (metric) {
    case 'doanhSoBan': return { num: doanhSoBan(r), den: 1 }
    case 'tongSauVat': return { num: tongSauVat(r), den: 1 }
    case 'daThanhToan': return { num: daThanhToan(r), den: 1 }
    case 'congNo': return { num: congNo(r), den: 1 }
    case 'grossCom': return { num: grossCom(r), den: 1 }
    case 'netCom': return { num: netCom(r), den: 1 }
    case 'netPO': return { num: netPO(r), den: 1 }
    case 'netMargin': return { num: netMargin(r), den: 1 }
    case 'totalNetComPct': return { num: netCom(r), den: netPO(r) }
    case 'totalNetMarginPct': return { num: netMargin(r), den: netPO(r) }
    case 'totalNetComDsbPct': return { num: netCom(r), den: doanhSoBan(r) }
    case 'totalNetMarginDsbPct': return { num: netMargin(r), den: doanhSoBan(r) }
    default: return { num: 0, den: 1 }
  }
}

const timelineBuckets = computed(() => {
  const metric = activeChartMetric.value
  const gran = resolvedGranularity.value
  const grouped = new Map<string, { sum: number; np: number; dsb: number; nm: number; count: number }>()

  const sorted = [...activeChartScopeRows.value].sort((a, b) => {
    const da = parseDateStr(a.created_time)?.getTime() || 0
    const db = parseDateStr(b.created_time)?.getTime() || 0
    return da - db
  })

  sorted.forEach(r => {
    const dObj = parseDateStr(r.created_time)
    let bucketKey = 'Chưa rõ ngày'
    if (dObj) {
      const dd = dObj.getDate().toString().padStart(2, '0')
      const mm = (dObj.getMonth() + 1).toString().padStart(2, '0')
      const yyyy = dObj.getFullYear()
      if (gran === 'day') {
        bucketKey = `${dd}/${mm}/${yyyy}`
      } else if (gran === 'month') {
        bucketKey = `${mm}/${yyyy}`
      } else if (gran === 'quarter') {
        const q = Math.floor(dObj.getMonth() / 3) + 1
        bucketKey = `Quý ${q}/${yyyy}`
      } else {
        bucketKey = `${yyyy}`
      }
    }

    if (!grouped.has(bucketKey)) {
      grouped.set(bucketKey, { sum: 0, np: 0, dsb: 0, nm: 0, count: 0 })
    }
    const g = grouped.get(bucketKey)!
    const { num } = getRowMetricNumDen(r, metric)
    g.sum += num
    g.np += netPO(r) || 0
    g.dsb += doanhSoBan(r) || 0
    g.nm += netMargin(r) || 0
    g.count += 1
  })

  const labels = Array.from(grouped.keys())
  const values: number[] = []
  const marginPcts: number[] = []
  const counts: number[] = []

  for (const g of grouped.values()) {
    let val = g.sum
    if (metric === 'totalNetComPct' || metric === 'totalNetMarginPct') {
      val = g.np !== 0 ? (g.sum / g.np) * 100 : 0
    } else if (metric === 'totalNetComDsbPct' || metric === 'totalNetMarginDsbPct') {
      val = g.dsb !== 0 ? (g.sum / g.dsb) * 100 : 0
    }
    values.push(val)
    marginPcts.push(g.dsb !== 0 ? (g.nm / g.dsb) * 100 : 0)
    counts.push(g.count)
  }

  return { labels, values, marginPcts, counts }
})

const chartOptions = computed(() => {
  const isLight = uiTheme.value === 'light'
  const gridColor = isLight ? 'rgba(148, 163, 184, 0.25)' : 'rgba(51, 65, 85, 0.45)'
  const tickColor = isLight ? '#475569' : '#94a3b8'
  const legendColor = isLight ? '#0f172a' : '#e2e8f0'
  const ratio = chartModal.value.isRatio
  const needRightAxis = !ratio && (chartLineMode.value === 'cumulative' || chartLineMode.value === 'marginPct')

  const scales: Record<string, any> = {
    y: {
      beginAtZero: true,
      grace: '16%',
      grid: { color: gridColor },
      ticks: {
        color: tickColor,
        maxTicksLimit: 6,
        font: { weight: '600', size: 10.5 },
        callback: (value: any) => (ratio ? pctFmt(value) : fmt(value))
      }
    },
    x: {
      grid: { display: false },
      ticks: { color: tickColor, font: { weight: '600', size: 10.5 } }
    }
  }

  if (needRightAxis) {
    scales.y1 = {
      position: 'right',
      beginAtZero: true,
      grace: '16%',
      grid: { drawOnChartArea: false },
      ticks: {
        color: chartLineMode.value === 'marginPct' ? '#f59e0b' : (isLight ? '#0284c7' : '#34d399'),
        maxTicksLimit: 6,
        font: { weight: '700', size: 10.5 },
        callback: (value: any) =>
          chartLineMode.value === 'marginPct' ? pctFmt(value) : fmt(value)
      }
    }
  }

  return {
    responsive: true,
    maintainAspectRatio: false,
    layout: { padding: { top: 14, right: 10, bottom: 4, left: 4 } },
    interaction: { mode: 'index' as const, intersect: false },
    scales,
    plugins: {
      legend: {
        position: 'top' as const,
        labels: { color: legendColor, font: { weight: '700', size: 11.5 }, usePointStyle: true, boxWidth: 9, padding: 10 }
      },
      tooltip: {
        callbacks: {
          label: (context: any) => {
            const dsLabel = context.dataset.label || ''
            const raw = Number(context.raw) || 0
            if (context.dataset.yAxisID === 'y1' && chartLineMode.value === 'marginPct') {
              return `${dsLabel}: ${pctFmt(raw)}`
            }
            return `${dsLabel}: ${ratio ? pctFmt(raw) : fmt(raw)}`
          }
        }
      },
      datalabels: {
        display: false
      }
    }
  }
})

const chartData = computed(() => {
  const metric = activeChartMetric.value
  const { labels, values, marginPcts } = timelineBuckets.value
  if (labels.length === 0) return { labels: [], datasets: [] }

  const isLight = uiTheme.value === 'light'
  const ratio = chartModal.value.isRatio
  const avgVal = values.length > 0 ? values.reduce((s, v) => s + v, 0) / values.length : 0

  let lineDataset: any = null
  if (chartLineMode.value === 'avg') {
    lineDataset = {
      type: 'line',
      label: `Trung bình kỳ (${ratio ? pctFmt(avgVal) : fmt(avgVal)})`,
      data: values.map(() => avgVal),
      borderColor: '#f59e0b',
      backgroundColor: 'rgba(245, 158, 11, 0.08)',
      borderWidth: 2.5,
      borderDash: [6, 6],
      pointRadius: 3,
      tension: 0,
      fill: false,
      yAxisID: 'y',
      order: 1
    }
  } else if (chartLineMode.value === 'cumulative' && !ratio) {
    let running = 0
    const cumData = values.map(v => {
      running += v
      return running
    })
    lineDataset = {
      type: 'line',
      label: 'Lũy kế qua các kỳ',
      data: cumData,
      borderColor: isLight ? '#0284c7' : '#34d399',
      backgroundColor: isLight ? 'rgba(2, 132, 199, 0.1)' : 'rgba(52, 211, 153, 0.12)',
      borderWidth: 3,
      tension: 0.35,
      fill: true,
      yAxisID: 'y1',
      order: 1
    }
  } else if (chartLineMode.value === 'marginPct' && !ratio) {
    lineDataset = {
      type: 'line',
      label: 'Net Margin / DSB (%)',
      data: marginPcts,
      borderColor: '#f59e0b',
      backgroundColor: 'rgba(245, 158, 11, 0.12)',
      borderWidth: 3,
      tension: 0.35,
      fill: false,
      yAxisID: 'y1',
      order: 1
    }
  } else {
    lineDataset = {
      type: 'line',
      label: 'Đường xu hướng',
      data: values,
      borderColor: isLight ? '#0284c7' : '#34d399',
      backgroundColor: isLight ? 'rgba(2, 132, 199, 0.1)' : 'rgba(52, 211, 153, 0.1)',
      borderWidth: 3,
      tension: 0.38,
      fill: true,
      yAxisID: 'y',
      order: 1
    }
  }

  const barPositiveColor = isLight
    ? (metric === 'congNo' ? '#dc2626' : '#0284c7')
    : (metric === 'congNo' ? '#ef4444' : '#10b981')

  return {
    labels,
    datasets: [
      lineDataset,
      {
        type: 'bar',
        label: labelMap[metric] || metric,
        data: values,
        backgroundColor: (ctx: any) => (ctx.raw < 0 ? '#ef4444' : barPositiveColor),
        borderRadius: 5,
        maxBarThickness: 34,
        categoryPercentage: 0.66,
        barPercentage: 0.76,
        yAxisID: 'y',
        order: 2,
        datalabels: {
          display: true,
          color: isLight ? '#0f172a' : '#ffffff',
          anchor: 'end',
          align: 'top',
          offset: 2,
          formatter: (value: any) => {
            if (!value || value === 0) return ''
            if (ratio) return pctFmt(value)
            if (Math.abs(value) >= 1e9) return (value / 1e9).toFixed(2) + ' Tỷ'
            if (Math.abs(value) >= 1e6) return (value / 1e6).toFixed(1) + ' Tr'
            return fmt(value)
          },
          font: { weight: 'bold', size: 10.5 },
          textShadowBlur: isLight ? 0 : 4,
          textShadowColor: 'rgba(0,0,0,0.5)'
        }
      }
    ]
  }
})

// ─── Tra cứu Ngành hàng của Khách hàng từ khachHangMap / PO (Chỉ lấy Ngành hàng, KHÔNG lấy tagKH) ───
const getCustomerIndustryForRow = (r: any): string => {
  if (!r) return 'Chưa phân loại ngành'
  const direct = String(
    r.nganh_nghe_cong_ty ||
    r.Nganh_nghe_cong_ty ||
    r.nganh_hang ||
    r.Nganh_hang ||
    ''
  ).trim()
  if (direct) return direct

  const maKH = String(r.Ma_khach_hang || r.ma_khach_hang || '').trim().toUpperCase()
  const maCT = String(r.Ma_cong_ty || r.ma_cong_ty || '').trim().toUpperCase()
  const mst = String(r.MST || r.mst || '').trim().toUpperCase()
  const tenCty = String(r.Ten_cong_ty || r.ten_cong_ty || '').trim().toLowerCase()

  const khEntries = Object.entries(khachHangMap.value || {})
  for (const [khKey, khObj] of khEntries) {
    if (!khObj || typeof khObj !== 'object') continue
    const cMkh = String(khObj.ma_khach_hang || khObj.Ma_khach_hang || khKey || '').trim().toUpperCase()
    const cMct = String(khObj.ma_cong_ty || khObj.Ma_cong_ty || '').trim().toUpperCase()
    const cMst = String(khObj.mst || khObj.MST || '').trim().toUpperCase()
    const cTenCty = String(khObj.ten_cong_ty || khObj.Ten_cong_ty || '').trim().toLowerCase()

    const matched =
      (maKH && (cMkh === maKH || cMct === maKH)) ||
      (maCT && (cMct === maCT || cMkh === maCT)) ||
      (mst && mst !== 'N/A' && cMst === mst) ||
      (tenCty && tenCty !== 'n/a' && cTenCty === tenCty)

    if (matched) {
      const nganh = String(
        khObj.nganh_nghe_cong_ty ||
        khObj.Nganh_nghe_cong_ty ||
        khObj.nganh_hang ||
        khObj.Nganh_hang ||
        ''
      ).trim()
      if (nganh) return nganh
      break
    }
  }
  return 'Chưa phân loại ngành'
}

// ─── Tra cứu Nhóm khách hàng (tagKH) của Khách hàng từ khachHangMap / PO ───
const getCustomerTagsForRow = (r: any): string[] => {
  if (!r) return ['Chưa phân nhóm KH']

  const extractTags = (rawTag: any): string[] => {
    if (Array.isArray(rawTag)) {
      return rawTag.map(t => String(t || '').trim()).filter(Boolean)
    }
    if (typeof rawTag === 'string' && rawTag.trim()) {
      return rawTag.split(',').map(t => t.trim()).filter(Boolean)
    }
    return []
  }

  const directTags = extractTags(r.tagKH || r.nhom_khach_hang || r.Nhom_khach_hang)
  if (directTags.length > 0) return directTags

  const maKH = String(r.Ma_khach_hang || r.ma_khach_hang || '').trim().toUpperCase()
  const maCT = String(r.Ma_cong_ty || r.ma_cong_ty || '').trim().toUpperCase()
  const mst = String(r.MST || r.mst || '').trim().toUpperCase()
  const tenCty = String(r.Ten_cong_ty || r.ten_cong_ty || '').trim().toLowerCase()

  const khEntries = Object.entries(khachHangMap.value || {})
  for (const [khKey, khObj] of khEntries) {
    if (!khObj || typeof khObj !== 'object') continue
    const cMkh = String(khObj.ma_khach_hang || khObj.Ma_khach_hang || khKey || '').trim().toUpperCase()
    const cMct = String(khObj.ma_cong_ty || khObj.Ma_cong_ty || '').trim().toUpperCase()
    const cMst = String(khObj.mst || khObj.MST || '').trim().toUpperCase()
    const cTenCty = String(khObj.ten_cong_ty || khObj.Ten_cong_ty || '').trim().toLowerCase()

    const matched =
      (maKH && (cMkh === maKH || cMct === maKH)) ||
      (maCT && (cMct === maCT || cMkh === maCT)) ||
      (mst && mst !== 'N/A' && cMst === mst) ||
      (tenCty && tenCty !== 'n/a' && cTenCty === tenCty)

    if (matched) {
      const dbTags = extractTags(khObj.tagKH || khObj.nhom_khach_hang || khObj.Nhom_khach_hang)
      if (dbTags.length > 0) return dbTags
      break
    }
  }
  return ['Chưa phân nhóm KH']
}

// ─── Dữ liệu Mặt hàng chi tiết (hd_chi_tiet) của phạm vi công ty đang xem ───
const companyGoodsList = computed(() => {
  const rowsList = activeChartScopeRows.value
  if (!rowsList || rowsList.length === 0) return []

  const maHdToPoMap = new Map<string, any>()
  rowsList.forEach(r => {
    const mhd = String(r.ma_hop_dong || '').trim()
    if (mhd) maHdToPoMap.set(mhd, r)
  })

  const goodsMap = new Map<
    string,
    {
      ten: string
      danhMuc: string
      dvt: string
      totalSl: number
      lastDonGia: number
      totalTruocVat: number
      buyCount: number
      poSet: Set<string>
    }
  >()

  if (maHdToPoMap.size > 0 && Array.isArray(hdChiTietData.value)) {
    hdChiTietData.value.forEach(rowArr => {
      const mhd = String(rowArr[0] || '').trim()
      if (!mhd || !maHdToPoMap.has(mhd)) return
      const poRow = maHdToPoMap.get(mhd)
      const soPo = String(poRow?.So_PO || mhd).trim()
      const ten = String(rowArr[3] || rowArr[9] || 'Mặt hàng').trim()
      const danhMuc = String(rowArr[10] || poRow?.Ten_nha_cung_cap || '').trim()
      const dvt = String(rowArr[12] || 'Cái').trim()
      const donGia = Number(rowArr[13]) || 0
      const sl = Number(rowArr[18]) || 1
      const ttTruoc = donGia * sl
      const key = `${ten.toLowerCase()}__${dvt.toLowerCase()}`
      if (!goodsMap.has(key)) {
        goodsMap.set(key, {
          ten,
          danhMuc,
          dvt,
          totalSl: 0,
          lastDonGia: donGia,
          totalTruocVat: 0,
          buyCount: 0,
          poSet: new Set()
        })
      }
      const g = goodsMap.get(key)!
      g.totalSl += sl
      if (donGia > 0) g.lastDonGia = donGia
      g.totalTruocVat += ttTruoc
      g.buyCount += 1
      if (soPo) g.poSet.add(soPo)
    })
  }

  // Hỗ trợ đọc trực tiếp từ r.goodsList (dành cho Bản Tạm sale_report_craft hoặc PO có lưu trực tiếp goodsList)
  rowsList.forEach(r => {
    if (!Array.isArray(r?.goodsList) || r.goodsList.length === 0) return
    const mhd = String(r?.ma_hop_dong || '').trim()
    if (mhd && Array.isArray(hdChiTietData.value) && hdChiTietData.value.some(arr => String(arr[0] || '').trim() === mhd)) {
      return
    }
    const soPo = String(r?.So_PO || 'PA').trim()
    r.goodsList.forEach((gi: any) => {
      if (!gi || typeof gi !== 'object') return
      const ten = String(gi.ten || gi.dienGiai || 'Mặt hàng').trim()
      const danhMuc = String(gi.danhMuc || r?.Ten_nha_cung_cap || '').trim()
      const dvt = String(gi.dvt || 'Cái').trim()
      const donGia = toNum(gi.donGia)
      const sl = toNum(gi.sl) || 1
      const ttTruoc = toNum(gi.ttTruoc) || donGia * sl
      const key = `${ten.toLowerCase()}__${dvt.toLowerCase()}`
      if (!goodsMap.has(key)) {
        goodsMap.set(key, {
          ten,
          danhMuc,
          dvt,
          totalSl: 0,
          lastDonGia: donGia,
          totalTruocVat: 0,
          buyCount: 0,
          poSet: new Set()
        })
      }
      const g = goodsMap.get(key)!
      g.totalSl += sl
      if (donGia > 0) g.lastDonGia = donGia
      g.totalTruocVat += ttTruoc
      g.buyCount += 1
      if (soPo) g.poSet.add(soPo)
    })
  })

  // Nếu chưa có dòng chi tiết trong hdChiTietData, gom theo nội dung hợp đồng / sản phẩm trên PO
  if (goodsMap.size === 0) {
    rowsList.forEach((r, idx) => {
      const contentName = getPoContractContent(r, 80) || String(r.Ten_nha_cung_cap || `Đơn hàng PO #${idx + 1}`).trim()
      const ncc = String(r.Ten_nha_cung_cap || '').trim()
      const soPo = String(r.So_PO || `PO-${idx + 1}`).trim()
      const dsb = doanhSoBan(r)
      const key = contentName.toLowerCase()
      if (!goodsMap.has(key)) {
        goodsMap.set(key, {
          ten: contentName,
          danhMuc: ncc,
          dvt: 'Đơn',
          totalSl: 1,
          lastDonGia: dsb,
          totalTruocVat: dsb,
          buyCount: 1,
          poSet: new Set([soPo])
        })
      } else {
        const g = goodsMap.get(key)!
        g.totalSl += 1
        g.lastDonGia = dsb
        g.totalTruocVat += dsb
        g.buyCount += 1
        g.poSet.add(soPo)
      }
    })
  }

  const totalAll = Array.from(goodsMap.values()).reduce((s, x) => s + x.totalTruocVat, 0)
  const dir = analyticsSortDir.value === 'asc' ? 1 : -1

  return Array.from(goodsMap.values())
    .map(g => ({
      ...g,
      poCount: g.poSet.size,
      poListStr: Array.from(g.poSet).join(', '),
      sharePct: totalAll > 0 ? (g.totalTruocVat / totalAll) * 100 : 0
    }))
    .sort((a, b) => (a.totalTruocVat - b.totalTruocVat) * dir)
})

const companyGoodsRankingRawData = computed(() => {
  const list = companyGoodsList.value
  const sorted: [string, number][] = []
  const counts = new Map<string, number>()
  const subMap = new Map<string, string>()
  let total = 0

  list.forEach(g => {
    sorted.push([g.ten, g.totalTruocVat])
    counts.set(g.ten, g.poCount || g.buyCount)
    const parts = [
      `SL: ${fmt(g.totalSl)} ${g.dvt}`,
      g.lastDonGia > 0 ? `Đơn giá gần nhất: ${fmt(g.lastDonGia)} đ` : '',
      g.danhMuc ? `NCC/Nhóm: ${g.danhMuc}` : ''
    ].filter(Boolean)
    subMap.set(g.ten, parts.join(' • '))
    total += g.totalTruocVat
  })

  return { sorted, counts, subMap, total }
})

// ─── Unified Ranking Data Builder (Customer / Industry / Customer Group / Product / PO / Debt Status) ───
const buildRankingData = (dimension: 'customer' | 'industry' | 'customerGroup' | 'product' | 'po' | 'debt', metric: string) => {
  if (!metric) {
    return {
      sorted: [] as [string, number][],
      counts: new Map<string, number>(),
      subMap: new Map<string, string>(),
      total: 0
    }
  }

  const isCompanyScoped = Boolean(chartModal.value.companyScope)
  const map = new Map<string, { num: number; den: number; names: Set<string>; poCount: number; subText: string; companies: Set<string> }>()
  let total = 0

  activeChartScopeRows.value.forEach((r, idx) => {
    const tenCty = r.Ten_cong_ty ? String(r.Ten_cong_ty).trim() : ''
    const { num, den } = getRowMetricNumDen(r, metric)

    if (dimension === 'customerGroup') {
      const tags = getCustomerTagsForRow(r)
      const uniqueRowTags = new Map<string, string>()
      tags.forEach(t => {
        const clean = String(t || '').trim() || 'Chưa phân nhóm KH'
        const k = clean.toLowerCase()
        if (!uniqueRowTags.has(k)) uniqueRowTags.set(k, clean)
      })
      for (const [tKey, tDisplay] of uniqueRowTags.entries()) {
        if (!map.has(tKey)) {
          map.set(tKey, { num: 0, den: 0, names: new Set(), poCount: 0, subText: '', companies: new Set() })
        }
        const item = map.get(tKey)!
        item.num += num
        item.den += den
        item.poCount += 1
        item.names.add(tDisplay)
        if (tenCty) item.companies.add(tenCty)
      }
      return
    }

    let key = ''
    let displaySeed = ''
    let subText = ''

    if (dimension === 'customer') {
      const maKH = r.Ma_khach_hang ? String(r.Ma_khach_hang).trim() : ''
      const maCT = r.Ma_cong_ty ? String(r.Ma_cong_ty).trim() : ''
      key = (maKH || maCT) ? `${maKH}_${maCT}` : (tenCty || 'Khác')
      displaySeed = tenCty || 'Khác'
    } else if (dimension === 'industry') {
      const ind = getCustomerIndustryForRow(r)
      key = ind.toLowerCase()
      displaySeed = ind
    } else if (dimension === 'product') {
      const ncc = r.Ten_nha_cung_cap ? String(r.Ten_nha_cung_cap).trim() : 'Chưa gán NCC'
      key = ncc.toLowerCase()
      displaySeed = ncc
    } else if (dimension === 'po') {
      const soPo = r.So_PO ? String(r.So_PO).trim() : `PO-#${idx + 1}`
      const ctyLabel = tenCty || 'Khách lẻ'
      const ncc = r.Ten_nha_cung_cap ? String(r.Ten_nha_cung_cap).trim() : ''
      const contentStr = getPoContractContent(r, 70)
      const dateStr = r.created_time ? String(r.created_time).split(' ')[0] : ''
      key = String(r.ID || r._firebaseKey || `${soPo}_${idx}`)
      const craftTitle = String(r?.content_of_contract_PO || r?.content || '').trim() || soPo
      displaySeed = srDataMode.value === 'craft'
        ? craftTitle
        : (isCompanyScoped ? soPo : `${soPo} — ${ctyLabel}`)
      subText = [dateStr ? `Ngày: ${dateStr}` : '', contentStr, ncc ? `NCC: ${ncc}` : ''].filter(Boolean).join(' • ')
    } else {
      const cn = congNo(r)
      const dtt = daThanhToan(r)
      const dueInfo = getPoDueInfo(r)
      let debtGroup = 'Đã tất toán'
      if (cn <= 0) {
        debtGroup = 'Đã tất toán'
      } else if (dueInfo.dueStatus === 'qua_han') {
        debtGroup = 'Quá hạn thanh toán'
      } else if (dueInfo.dueStatus === 'sap_den_han' || dueInfo.dueStatus === 'den_han_hom_nay') {
        debtGroup = 'Sắp đến hạn'
      } else if (dtt > 0) {
        debtGroup = 'Thanh toán 1 phần'
      } else {
        debtGroup = 'Chưa thanh toán'
      }
      key = debtGroup
      displaySeed = debtGroup
    }

    if (!map.has(key)) {
      map.set(key, { num: 0, den: 0, names: new Set(), poCount: 0, subText, companies: new Set() })
    }
    const item = map.get(key)!
    item.num += num
    item.den += den
    item.poCount += 1
    if (displaySeed) item.names.add(displaySeed)
    if (tenCty) item.companies.add(tenCty)
    if (subText && !item.subText) item.subText = subText
  })

  const finalMap = new Map<string, number>()
  const countsMap = new Map<string, number>()
  const subMap = new Map<string, string>()
  const ratio = isRatioMetric(metric)

  for (const val of map.values()) {
    let finalVal = 0
    if (ratio) {
      finalVal = val.den !== 0 ? (val.num / val.den) * 100 : 0
    } else {
      finalVal = val.num
      total += finalVal
    }
    const displayName = val.names.size > 0 ? Array.from(val.names)[0] : 'Khác'
    if (ratio) {
      finalMap.set(displayName, finalVal)
    } else {
      finalMap.set(displayName, (finalMap.get(displayName) || 0) + finalVal)
    }
    countsMap.set(displayName, (countsMap.get(displayName) || 0) + val.poCount)
    if ((dimension === 'industry' || dimension === 'customerGroup') && val.companies.size > 0) {
      const cList = Array.from(val.companies)
      subMap.set(
        displayName,
        `${cList.length} KH: ${cList.slice(0, 3).join(', ')}${cList.length > 3 ? ` (+${cList.length - 3} KH)` : ''}`
      )
    } else if (val.subText) {
      subMap.set(displayName, val.subText)
    }
  }

  const dir = analyticsSortDir.value === 'asc' ? 1 : -1
  const sorted = Array.from(finalMap.entries()).sort((a, b) => (a[1] - b[1]) * dir)
  return { sorted, counts: countsMap, subMap, total }
}

