function applyAnalyticsDrilldown(entityName: string) {
  if (!entityName || entityName === 'Khác' || entityName === 'Chưa gán NCC' || entityName === 'Chưa phân loại ngành' || entityName === 'Chưa phân nhóm KH') return
  if (chartModal.value.companyScope && chartModal.value.companyScope.tenCongTy) {
    filterCustomer.value = chartModal.value.companyScope.tenCongTy
  }
  if (analyticsActiveTab.value === 'customer') {
    const cleanName = entityName.split(' / ')[0].trim()
    filterCustomer.value = cleanName
  } else if (analyticsActiveTab.value === 'industry') {
    const matchedRow = activeChartScopeRows.value.find(r => getCustomerIndustryForRow(r).toLowerCase() === entityName.toLowerCase())
    if (matchedRow && matchedRow.Ten_cong_ty) {
      filterCustomer.value = String(matchedRow.Ten_cong_ty).trim()
    }
  } else if (analyticsActiveTab.value === 'customerGroup') {
    const matchedRow = activeChartScopeRows.value.find(r =>
      getCustomerTagsForRow(r).some(t => t.toLowerCase() === entityName.toLowerCase())
    )
    if (matchedRow && matchedRow.Ten_cong_ty) {
      filterCustomer.value = String(matchedRow.Ten_cong_ty).trim()
    }
  } else if (analyticsActiveTab.value === 'product') {
    if (chartModal.value.companyScope && companyProductSubMode.value === 'goods') {
      searchStr.value = entityName
    } else {
      const cleanName = entityName.split(' / ')[0].trim()
      filterProductType.value = cleanName
    }
  } else if (analyticsActiveTab.value === 'po') {
    const soPo = entityName.split(' — ')[0].trim()
    if (soPo) searchStr.value = soPo
  } else if (analyticsActiveTab.value === 'debt') {
    filterDebtStatus.value = entityName
  }
  chartModal.value.show = false
}

const wrapText = (text: string, maxLen: number = 20, maxLines: number = 0) => {
  if (!text) return ''
  const normalized = String(text).replace(/_/g, '_ ')
  if (normalized.length <= maxLen) return String(text)
  const rawWords = normalized.split(/\s+/).filter(Boolean)
  const words: string[] = []
  for (const w of rawWords) {
    if (w.length <= maxLen) {
      words.push(w)
    } else {
      for (let i = 0; i < w.length; i += maxLen) {
        words.push(w.slice(i, i + maxLen))
      }
    }
  }
  const lines: string[] = []
  let line = ''
  for (const word of words) {
    const candidate = line ? (line.endsWith('_') ? line + word : line + ' ' + word) : word
    if (candidate.length <= maxLen) {
      line = candidate
    } else {
      if (line) lines.push(line)
      line = word
    }
  }
  if (line) lines.push(line)
  if (maxLines > 0 && lines.length > maxLines) {
    const kept = lines.slice(0, maxLines)
    const last = kept[maxLines - 1]
    kept[maxLines - 1] = (last.length > maxLen - 2 ? last.slice(0, maxLen - 2).trimEnd() : last) + '…'
    return kept
  }
  return lines
}

const rankingPalette = [
  '#10b981', '#0284c7', '#f59e0b', '#8b5cf6', '#ec4899',
  '#14b8a6', '#f97316', '#3b82f6', '#84cc16', '#06b6d4', '#64748b'
]

const activeRankingPieData = computed(() => {
  const data = activeRankingRawData.value.sorted.filter(d => d[1] > 0)
  const limit = Number(analyticsTopLimit.value) || 10
  const topN = data.slice(0, limit)
  const others = data.slice(limit).reduce((sum, item) => sum + Math.max(0, item[1]), 0)

  const labels = topN.map(d => {
    const text = d[0]
    if (isMobile.value && text.length > 16) return text.substring(0, 16) + '...'
    if (!isMobile.value && text.length > 26) return text.substring(0, 26) + '...'
    return text
  })
  const values = topN.map(d => d[1])

  if (others > 0) {
    labels.push('Nhóm còn lại')
    values.push(others)
  }

  return {
    labels,
    datasets: [
      {
        data: values,
        backgroundColor: rankingPalette,
        borderWidth: 2,
        borderColor: uiTheme.value === 'light' ? '#ffffff' : '#091411'
      }
    ]
  }
})

const activeRankingPieOptions = computed(() => {
  const isLight = uiTheme.value === 'light'
  const total = activeRankingRawData.value.total
  return {
    responsive: true,
    maintainAspectRatio: false,
    cutout: '58%',
    onClick: (_e: any, activeEls: any[]) => {
      if (activeEls.length > 0) {
        const index = activeEls[0].index
        const entry = activeRankingRawData.value.sorted[index]
        if (entry && entry[0]) {
          applyAnalyticsDrilldown(entry[0])
        }
      }
    },
    plugins: {
      legend: {
        position: 'bottom' as const,
        labels: {
          color: isLight ? '#334155' : '#cbd5e1',
          font: { size: 11, weight: '600' },
          boxWidth: 10
        }
      },
      tooltip: {
        callbacks: {
          label: (ctx: any) => {
            const pct = total > 0 ? ((ctx.raw / total) * 100).toFixed(1) : '0.0'
            return ` ${ctx.label}: ${fmt(ctx.raw)} (${pct}%)`
          }
        }
      },
      datalabels: {
        color: '#ffffff',
        formatter: (val: number) => {
          if (!total) return ''
          const pct = (val / total) * 100
          return pct >= 6 ? `${pct.toFixed(0)}%` : ''
        },
        font: { weight: 'bold', size: 11 },
        textShadowBlur: 4,
        textShadowColor: 'rgba(0,0,0,0.75)'
      }
    }
  }
})

const activeRankingBarData = computed(() => {
  const allData = activeRankingRawData.value.sorted
  const limit = Number(analyticsTopLimit.value) || 10
  const sliced = allData.slice(0, limit)
  const isLight = uiTheme.value === 'light'
  const ratio = chartModal.value.isRatio
  const positiveBarColor =
    analyticsActiveTab.value === 'industry'
      ? '#06b6d4'
      : analyticsActiveTab.value === 'customerGroup'
        ? '#ec4899'
        : analyticsActiveTab.value === 'product'
          ? (isLight ? '#059669' : '#10b981')
          : analyticsActiveTab.value === 'po'
            ? '#f59e0b'
            : analyticsActiveTab.value === 'debt'
              ? '#8b5cf6'
              : '#0284c7'

  const datasets: any[] = []
  if (chartModal.value.companyScope && analyticsActiveTab.value === 'po' && sliced.length > 1) {
    const avgPoVal = sliced.reduce((s, d) => s + d[1], 0) / sliced.length
    datasets.push({
      type: 'line',
      label: `Trung bình PO khách hàng (${ratio ? pctFmt(avgPoVal) : fmt(avgPoVal)})`,
      data: sliced.map(() => avgPoVal),
      borderColor: isLight ? '#0284c7' : '#34d399',
      borderWidth: 2,
      borderDash: [6, 5],
      pointRadius: 2.5,
      fill: false,
      order: 1,
      datalabels: { display: false }
    })
  }

  datasets.push({
    type: 'bar',
    label: activeChartMetricLabel.value,
    data: sliced.map(d => d[1]),
    backgroundColor: (ctx: any) => (ctx.raw < 0 ? '#ef4444' : positiveBarColor),
    borderRadius: 6,
    maxBarThickness: isMobile.value ? 28 : 54,
    order: 2
  })

  return {
    labels: sliced.map(d => isMobile.value ? wrapText(d[0], 18, 3) : wrapText(d[0], 20)),
    datasets
  }
})

const activeRankingBarOptions = computed(() => {
  const isLight = uiTheme.value === 'light'
  const ratio = chartModal.value.isRatio
  const total = activeRankingRawData.value.total
  const horiz = isMobile.value
  const showLegend = Boolean(chartModal.value.companyScope && analyticsActiveTab.value === 'po' && activeRankingRawData.value.sorted.length > 1)

  const formatAxisValue = (v: any) => {
    const num = Number(v)
    if (ratio) return pctFmt(num)
    if (horiz) {
      if (Math.abs(num) >= 1e9) return (num / 1e9).toFixed(1).replace(/\.0$/, '') + ' Tỷ'
      if (Math.abs(num) >= 1e6) return (num / 1e6).toFixed(0) + ' Tr'
      if (Math.abs(num) >= 1e3) return (num / 1e3).toFixed(0) + 'k'
    }
    return fmt(num)
  }

  return {
    indexAxis: horiz ? ('y' as const) : ('x' as const),
    responsive: true,
    maintainAspectRatio: false,
    onClick: (_e: any, activeEls: any[]) => {
      if (activeEls.length > 0) {
        const index = activeEls[0].index
        const entry = activeRankingRawData.value.sorted[index]
        if (entry && entry[0]) {
          applyAnalyticsDrilldown(entry[0])
        }
      }
    },
    layout: horiz
      ? { padding: { top: 8, right: ratio ? 42 : 58, bottom: 8, left: 2 } }
      : { padding: { top: 40, bottom: 16 } },
    scales: horiz
      ? {
          x: {
            beginAtZero: true,
            grace: '22%',
            grid: { color: isLight ? 'rgba(148, 163, 184, 0.25)' : 'rgba(51, 65, 85, 0.45)' },
            ticks: {
              color: isLight ? '#475569' : '#94a3b8',
              maxTicksLimit: 5,
              font: { weight: '600', size: 10 },
              callback: formatAxisValue
            }
          },
          y: {
            grid: { display: false },
            ticks: {
              color: isLight ? '#0f172a' : '#e2e8f0',
              autoSkip: false,
              font: { size: 10.5, weight: '700' }
            }
          }
        }
      : {
          y: {
            beginAtZero: true,
            grace: '24%',
            grid: { color: isLight ? 'rgba(148, 163, 184, 0.25)' : 'rgba(51, 65, 85, 0.45)' },
            ticks: {
              color: isLight ? '#475569' : '#94a3b8',
              font: { weight: '600', size: 11 },
              callback: (v: any) => (ratio ? pctFmt(v) : fmt(v))
            }
          },
          x: {
            grid: { display: false },
            ticks: {
              color: isLight ? '#0f172a' : '#e2e8f0',
              minRotation: 0,
              maxRotation: 0,
              autoSkip: false,
              font: { size: 11, weight: '600' }
            }
          }
        },
    plugins: {
      legend: {
        display: showLegend,
        position: 'top' as const,
        labels: {
          color: isLight ? '#0f172a' : '#e2e8f0',
          font: { size: 11, weight: '600' },
          usePointStyle: true,
          boxWidth: 9
        }
      },
      tooltip: {
        callbacks: {
          title: (items: any[]) => {
            if (!items || !items.length) return ''
            const idx = items[0].dataIndex
            return activeRankingRawData.value.sorted[idx]?.[0] || ''
          },
          label: (ctx: any) => (ratio ? pctFmt(ctx.raw) : fmt(ctx.raw))
        }
      },
      datalabels: {
        labels: {
          value: {
            color: isLight ? '#0f172a' : '#ffffff',
            anchor: 'end',
            align: horiz ? 'end' : 'top',
            offset: horiz ? 6 : (ratio ? 4 : 18),
            textAlign: horiz ? ('left' as const) : ('center' as const),
            font: { weight: 'bold', size: horiz ? 10 : 11 },
            formatter: (val: number, ctx: any) => {
              if (ctx?.dataset?.type === 'line') return ''
              if (ratio) return pctFmt(val)
              let shortVal = fmt(val)
              if (Math.abs(val) >= 1e9) shortVal = (val / 1e9).toFixed(2) + ' Tỷ'
              else if (Math.abs(val) >= 1e6) shortVal = (val / 1e6).toFixed(1) + ' Tr'
              if (horiz && total) {
                const pct = (val / total) * 100
                return [shortVal, `(${pct.toFixed(1)}%)`]
              }
              return shortVal
            },
            textShadowBlur: isLight ? 0 : 4,
            textShadowColor: 'rgba(0,0,0,0.5)'
          },
          percent: {
            display: !horiz,
            color: isLight ? '#059669' : '#34d399',
            anchor: 'end',
            align: 'top',
            offset: 3,
            font: { weight: 'bold', size: 10.5 },
            formatter: (val: number, ctx: any) => {
              if (ctx?.dataset?.type === 'line') return ''
              if (ratio || !total) return ''
              const pct = (val / total) * 100
              return `${pct.toFixed(1)}%`
            },
            textShadowBlur: isLight ? 0 : 4,
            textShadowColor: 'rgba(0,0,0,0.5)'
          }
        }
      }
    }
  }
})

