// ─── 4 Mini-KPI Summary Cards cho Bento Analytics Hub ───
const analyticsSummaryKpis = computed(() => {
  const metric = activeChartMetric.value
  const ratio = chartModal.value.isRatio
  const isCompanyScoped = Boolean(chartModal.value.companyScope)
  const scopeRows = activeChartScopeRows.value
  const formatVal = (v: number) => (ratio ? pctFmt(v) : `${fmt(v)} đ`)

  if (analyticsActiveTab.value === 'timeline') {
    const { labels, values } = timelineBuckets.value
    const count = values.length
    const totalVal = calcScopeMetricTotal(scopeRows, metric)
    const systemTotalVal = calcScopeMetricTotal(filteredRows.value, metric)
    const avgVal = count > 0 ? values.reduce((s, v) => s + v, 0) / count : 0
    const avgPerPoVal = scopeRows.length > 0 && !ratio ? totalVal / scopeRows.length : avgVal

    let maxIdx = 0
    let minIdx = 0
    for (let i = 1; i < count; i++) {
      if (values[i] > values[maxIdx]) maxIdx = i
      if (values[i] < values[minIdx]) minIdx = i
    }

    let firstSub = `${scopeRows.length} đơn hàng PO trong bộ lọc`
    if (isCompanyScoped) {
      if (ratio) {
        const diff = totalVal - systemTotalVal
        firstSub = `Toàn hệ thống: ${pctFmt(systemTotalVal)} (${diff >= 0 ? '+' : ''}${diff.toFixed(1)}%)`
      } else {
        const sharePct = systemTotalVal > 0 ? ((totalVal / systemTotalVal) * 100).toFixed(1) : '0.0'
        firstSub = `Chiếm ${sharePct}% toàn hệ thống (${scopeRows.length} PO)`
      }
    }

    return [
      {
        label: ratio
          ? (isCompanyScoped ? 'Tỷ suất của khách hàng' : 'Tỷ suất trung bình kỳ')
          : `Tổng ${activeChartMetricLabel.value}`,
        value: formatVal(totalVal),
        sub: firstSub,
        tone: 'emerald'
      },
      {
        label: isCompanyScoped && !ratio ? 'Trung bình mỗi đơn PO' : 'Trung bình mỗi mốc thời gian',
        value: formatVal(isCompanyScoped && !ratio ? avgPerPoVal : avgVal),
        sub: isCompanyScoped && !ratio
          ? `TB mỗi kỳ: ${formatVal(avgVal)} (${count} kỳ)`
          : `Chia đều trên ${count} mốc phát sinh`,
        tone: 'blue'
      },
      {
        label: 'Mốc đạt đỉnh (Peak)',
        value: count > 0 ? formatVal(values[maxIdx]) : '0',
        sub: count > 0 ? `Cao nhất tại: ${labels[maxIdx]}` : 'Chưa có dữ liệu',
        tone: 'amber'
      },
      {
        label: 'Mốc thấp nhất',
        value: count > 0 ? formatVal(values[minIdx]) : '0',
        sub: count > 0 ? `Thấp nhất tại: ${labels[minIdx]}` : 'Chưa có dữ liệu',
        tone: 'purple'
      }
    ]
  } else {
    const { sorted, total } = activeRankingRawData.value
    const entityCount = sorted.length
    const top1 = sorted[0]
    const top1Share = !ratio && total > 0 && top1 ? ((top1[1] / total) * 100).toFixed(1) + '%' : ''
    const top3Sum = sorted.slice(0, 3).reduce((s, item) => s + item[1], 0)
    const top3Share = !ratio && total > 0 ? ((top3Sum / total) * 100).toFixed(1) + '%' : '—'
    const avgPerEntity = entityCount > 0
      ? (ratio ? sorted.reduce((s, x) => s + x[1], 0) / entityCount : total / entityCount)
      : 0

    return [
      {
        label: `Tổng ${activeEntityLabel.value}`,
        value: `${entityCount}`,
        sub: ratio ? `Đang xếp hạng theo ${activeChartMetricLabel.value}` : `Tổng cộng: ${formatVal(total)}`,
        tone: 'blue'
      },
      {
        label: `Dẫn đầu (Top 1)`,
        value: top1 ? formatVal(top1[1]) : '0',
        sub: top1 ? `${top1[0]}${top1Share ? ` (${top1Share})` : ''}` : 'Chưa có dữ liệu',
        tone: 'emerald'
      },
      {
        label: 'Tỷ trọng Top 3 (Pareto)',
        value: ratio ? (top1 ? formatVal(top3Sum / Math.min(3, Math.max(1, entityCount))) : '0%') : top3Share,
        sub: ratio ? 'Trung bình nhóm Top 3 dẫn đầu' : `Tổng Top 3: ${formatVal(top3Sum)}`,
        tone: 'amber'
      },
      {
        label: `Trung bình / ${activeEntityLabel.value}`,
        value: formatVal(avgPerEntity),
        sub: `Trên ${entityCount} ${activeEntityLabel.value.toLowerCase()}`,
        tone: 'purple'
      }
    ]
  }
})


