  if (hasItemBgPreview(item)) return 'bg'
  if (hasItemMhPreview(item)) return 'mh'
  if (hasItemDxmhPreview(item)) return 'dxmh'
  if (hasItemImgPreview(item)) return 'img'
  if (item.otherFiles && item.otherFiles.length > 0) return 'other'
  return 'bg'
}

