function setFullInitialPayment(item: ImportItem | null | undefined) {
  if (!item) return
  const totalSauVat = Number(item.goodsTotal?.ttSau || item.doanhSoBan || 0)
  item.soTienDaThanhToan = Math.max(0, Math.round(totalSauVat))
  isModalDirty.value = true
}

function applyPredictPreset(item: ImportItem | null | undefined, pct: number | null) {
  if (!item) return
  if (pct === null) {
    item.predictPct = ''
    if (item._origGross !== undefined) item.grossCom = item._origGross
    if (item._origNet !== undefined) item.netCom = item._origNet
    isModalDirty.value = true
    return
  }
  if (item._origGross === undefined) {
    item._origGross = item.grossCom
    item._origNet = item.netCom
  }
  item.predictPct = String(pct)
  const ratio = pct / 100
  const tax = (Number(item.taxPct) || 0) / 100
  const dsb = item.doanhSoBan || 0
  const tcp = item.tongCP || 0
  const targetNetMargin = dsb * ratio
  const requiredGrossCom = dsb - tcp - targetNetMargin
  const requiredNetCom = requiredGrossCom * (1 - tax)
  item.grossCom = Math.round(requiredGrossCom)
  item.netCom = Math.round(requiredNetCom)
  isModalDirty.value = true
}

function applyTaxPreset(item: ImportItem | null | undefined, pct: number) {
  if (!item) return
  item.taxPct = pct
  onFinancialInput(item, 'taxPct' as any)
  isModalDirty.value = true
}

function syncGiaMuaToTongCP(item: ImportItem | null | undefined) {
