function normalizeCustomerCompareStr(s: any): string {
  return String(s || '').trim().replace(/\s+/g, ' ').toLowerCase()
}

function hasDxmhOnItem(item: ImportItem | null | undefined): boolean {
  if (!item) return false
  return Boolean(
    item.rawFileDxmh ||
    item.previewUrlDXMH ||
    item.linkDxmh ||
    item.tenFileDxmh ||
    item.row?.link_excel_dxmh ||
    item.row?.ten_file_dxmh
  )
}

function getIndustryFromDbCustomer(cus: any): string {
  if (!cus || typeof cus !== 'object') return ''
  const direct = String(
    cus.nganh_nghe_cong_ty ||
    cus.Nganh_nghe_cong_ty ||
    cus.nganh_hang ||
    cus.Nganh_hang ||
    ''
  ).trim()
  if (direct) return direct
  return ''
}

function getCustomerGroupArrayFromDbCustomer(cus: any): string[] {
  if (!cus || typeof cus !== 'object') return []
  const raw = cus.tagKH ?? cus.TagKH ?? cus.nhom_khach_hang ?? cus.Nhom_khach_hang
  if (Array.isArray(raw)) {
    return raw.map((t: any) => String(t || '').trim()).filter(Boolean)
  }
  if (typeof raw === 'string' && raw.trim()) {
    return raw.split(/[,;]/).map(s => s.trim()).filter(Boolean)
  }
  return []
}

function getCustomerGroupFromDbCustomer(cus: any): string {
  return getCustomerGroupArrayFromDbCustomer(cus).join(', ')
}

function parseCustomerGroupStringToArray(val: string): string[] {
  if (!val) return []
  const seen = new Set<string>()
  const out: string[] = []
  val.split(/[,;]/).forEach(part => {
    const clean = part.trim()
    if (!clean) return
    const key = clean.toLowerCase()
    if (!seen.has(key)) {
      seen.add(key)
      out.push(clean)
    }
  })
  return out
}

const khachHangList = computed(() => {
  const map = khachHangMap.value || {}
  return Object.entries(map)
    .filter(([, v]) => v && typeof v === 'object')
    .map(([k, v]: [string, any]) => {
      const ma_khach_hang = String(v.ma_khach_hang || v.Ma_khach_hang || k || '').trim()
      const ma_cong_ty = String(v.ma_cong_ty || v.Ma_cong_ty || '').trim()
      const ten_cong_ty = String(v.ten_cong_ty || v.Ten_cong_ty || '').trim()
      const ten_khach_hang = String(v.ten_khach_hang || v.Ten_khach_hang || '').trim()
      const mst = String(v.mst || v.MST || '').trim()
      return {
        ...v,
        id: k,
        ma_khach_hang,
        ma_cong_ty,
        ten_cong_ty,
        ten_khach_hang,
        mst,
        nganh_nghe_cong_ty: getIndustryFromDbCustomer(v),
        tagKH: getCustomerGroupArrayFromDbCustomer(v),
        _mstClean: mst.replace(/[^0-9A-Za-z-]/g, '').trim(),
        _normComp: normalizeCustomerCompareStr(ten_cong_ty),
        _normKH: normalizeCustomerCompareStr(ten_khach_hang)
      }
    })
})

const khachHangLookupIndex = computed(() => {
  const byMaKH = new Map<string, any>()
  const byMaCT = new Map<string, any>()
  const byMst = new Map<string, any>()
  const byNormName = new Map<string, any>()

  for (const c of khachHangList.value) {
    if (c.ma_khach_hang && !byMaKH.has(c.ma_khach_hang)) byMaKH.set(c.ma_khach_hang, c)
    if (c.ma_cong_ty && !byMaCT.has(c.ma_cong_ty)) byMaCT.set(c.ma_cong_ty, c)
    if (c._mstClean && c._mstClean.length >= 8 && !byMst.has(c._mstClean)) byMst.set(c._mstClean, c)
    if (c._normComp && !byNormName.has(c._normComp)) byNormName.set(c._normComp, c)
    if (c._normKH && !byNormName.has(c._normKH)) byNormName.set(c._normKH, c)
  }

  return { byMaKH, byMaCT, byMst, byNormName, count: khachHangList.value.length }
})

const custMatchedWeakCache = new WeakMap<object, { key: string; val: any | null }>()
const custStateWeakCache = new WeakMap<object, { key: string; val: any }>()

function getMatchedDbCustomerForItem(item: ImportItem | null | undefined): any | null {
  if (!item) return null
  const idx = khachHangLookupIndex.value
  if (!idx.count) return null

  const rawItem = toRaw(item) as object
  const targetMaKH = String(item.linkedMaKH || item.row?.Ma_khach_hang || '').trim()
  const mstClean = String(item.mst || '').replace(/[^0-9A-Za-z-]/g, '').trim()
  const comp = String(item.customer || '').trim()
  const rec = String(item.recipient || '').trim()
  const cacheKey = `${idx.count}|${targetMaKH}|${mstClean}|${comp}|${rec}`
  const cached = custMatchedWeakCache.get(rawItem)
  if (cached && cached.key === cacheKey) {
    return cached.val
  }

  let found: any | null = null

  // 1. Ưu tiên mã KH đã gắn trên item hoặc từ bản ghi gốc
  if (targetMaKH) {
    found = idx.byMaKH.get(targetMaKH) || null
  }

  // 2. Tra cứu theo MST
  if (!found && mstClean && mstClean.length >= 8) {
    found = idx.byMst.get(mstClean) || null
  }

  // 3. Tra cứu theo Mã KH / Mã công ty sinh tự động hoặc tên chính xác
  if (!found) {
    const genKH = genMaKhachHang(rec, comp)
    if (genKH) {
      found = idx.byMaKH.get(genKH) || null
    }
  }
  if (!found) {
    const genCT = genMaCongTy(comp || rec)
    if (genCT) {
      found = idx.byMaCT.get(genCT) || idx.byMaKH.get(genCT) || null
    }
  }
  if (!found && comp) {
    const normComp = normalizeCustomerCompareStr(comp)
    if (normComp) {
      found = idx.byNormName.get(normComp) || null
    }
  }

  custMatchedWeakCache.set(rawItem, { key: cacheKey, val: found })
  return found
}

function getDisplayIndustryForModalItem(item: ImportItem | null | undefined): string {
  if (!item) return ''
  if (item._industryEdited) return String(item.industry || '')
  if (item.industry && String(item.industry).trim()) return String(item.industry).trim()
  const dbCus = getMatchedDbCustomerForItem(item)
