const availableCustomerTags = computed(() => {
  const tagSet = new Set<string>()
  khachHangList.value.forEach(c => {
    if (Array.isArray(c.tagKH)) {
      c.tagKH.forEach((t: any) => {
        const clean = String(t || '').trim()
        if (clean) tagSet.add(clean)
      })
    } else if (typeof c.tagKH === 'string' && c.tagKH.trim()) {
      tagSet.add(c.tagKH.trim())
    }
  })
  dbCustomerDetailModal.value.form.tagKH.forEach(t => {
    const clean = String(t || '').trim()
    if (clean) tagSet.add(clean)
  })
  return Array.from(tagSet).sort((a, b) => a.localeCompare(b, 'vi'))
})

function addNewTagToCustomerDetailForm() {
  const val = String(dbCustomerDetailModal.value.newTagInput || '').trim()
  if (!val) return
  if (!dbCustomerDetailModal.value.form.tagKH.includes(val)) {
    dbCustomerDetailModal.value.form.tagKH.push(val)
  }
  dbCustomerDetailModal.value.newTagInput = ''
}

function toggleTagOnCustomerDetailForm(tag: string) {
  const arr = dbCustomerDetailModal.value.form.tagKH
  const idx = arr.indexOf(tag)
  if (idx > -1) {
    arr.splice(idx, 1)
  } else {
    arr.push(tag)
  }
}

function getDbCustomerLiveDebtSummary(cus: any) {
  if (!cus) {
    return { poCount: 0, tongSauVat: 0, daThanhToan: 0, congNo: 0, progressPct: 0, firstPoRow: null as any }
  }
  const pos = getCustomerPOsForDebtModal(cus)
  if (pos.length > 0) {
    const tongSau = pos.reduce((s, r) => s + tongSauVat(r), 0)
    const daTT = pos.reduce((s, r) => s + daThanhToan(r), 0)
    const cn = pos.reduce((s, r) => s + congNo(r), 0)
    const progressPct = tongSau > 0 ? Math.min(100, Math.round((daTT / tongSau) * 100)) : (cn <= 0 ? 100 : 0)
    return { poCount: pos.length, tongSauVat: tongSau, daThanhToan: daTT, congNo: cn, progressPct, firstPoRow: pos[0] }
  }
  return { poCount: 0, tongSauVat: 0, daThanhToan: 0, congNo: Number(cus.cong_no) || 0, progressPct: 0, firstPoRow: null as any }
}

