async function saveDbCustomerDetailModal() {
  const modal = dbCustomerDetailModal.value
  const cus = modal.customer
  if (!cus || !cus.id) return
  const f = modal.form
  if (!String(f.ten_cong_ty || '').trim() && !String(f.ten_khach_hang || '').trim()) {
    await openSrAlert({
      variant: 'warning',
      title: 'Thiếu thông tin định danh khách hàng',
      message: 'Vui lòng nhập ít nhất Tên công ty hoặc Tên khách hàng trước khi lưu hồ sơ.',
      confirmText: 'Đã hiểu'
    })
    return
  }
  modal.saving = true
  try {
    const updates: Record<string, any> = {
      ten_cong_ty: String(f.ten_cong_ty || '').trim(),
      ten_khach_hang: String(f.ten_khach_hang || '').trim(),
      ten_khach_hang_phu: String(f.ten_khach_hang_phu || '').trim(),
      mst: String(f.mst || '').trim(),
      nganh_nghe_cong_ty: String(f.nganh_nghe_cong_ty || '').trim(),
      ngay_thanh_lap: String(f.ngay_thanh_lap || '').trim(),
      so_dien_thoai_ca_nhan: String(f.so_dien_thoai_ca_nhan || '').trim(),
      email_ca_nhan: String(f.email_ca_nhan || '').trim(),
      so_dien_thoai_ca_nhan_phu: String(f.so_dien_thoai_ca_nhan_phu || '').trim(),
      email_ca_nhan_phu: String(f.email_ca_nhan_phu || '').trim(),
      so_dien_thoai_cong_ty: String(f.so_dien_thoai_cong_ty || '').trim(),
      so_fax_cong_ty: String(f.so_fax_cong_ty || '').trim(),
      email_cong_ty: String(f.email_cong_ty || '').trim(),
      dia_chi_cong_ty: String(f.dia_chi_cong_ty || '').trim(),
      website_cong_ty: String(f.website_cong_ty || '').trim(),
      company: String(f.company || '').trim(),
      tel: String(f.tel || '').trim(),
      address: String(f.address || '').trim(),
      ghi_chu: String(f.ghi_chu || '').trim(),
      tagKH: Array.isArray(f.tagKH) ? [...f.tagKH] : [],
      sdt: String(f.so_dien_thoai_ca_nhan || f.so_dien_thoai_cong_ty || f.tel || '').trim(),
      email: String(f.email_ca_nhan || f.email_cong_ty || '').trim(),
      dia_chi: String(f.dia_chi_cong_ty || f.address || '').trim(),
      last_updated: new Date().toISOString()
    }
    await update(dbRef(database, `khach_hang/${cus.id}`), updates)
    if (khachHangMap.value[cus.id]) {
      Object.assign(khachHangMap.value[cus.id], updates)
    }
    Object.assign(cus, updates)

    // Đồng bộ ngay vào PO đang mở nếu PO đang gắn với khách hàng này
    const tItem = modal.targetItem || activeModalItem.value
    if (tItem) {
      const matched = getMatchedDbCustomerForItem(tItem)
      if (matched && (matched.id === cus.id || matched.ma_khach_hang === cus.ma_khach_hang)) {
        if (updates.ten_cong_ty) tItem.customer = updates.ten_cong_ty
        if (!hasDxmhOnItem(tItem) && updates.ten_khach_hang) tItem.recipient = updates.ten_khach_hang
        if (updates.mst) tItem.mst = updates.mst
        tItem.industry = updates.nganh_nghe_cong_ty
        tItem._industryEdited = false
        tItem.customerGroup = Array.isArray(updates.tagKH) ? updates.tagKH.join(', ') : ''
        tItem._customerGroupEdited = false
      }
    }
    modal.mode = 'view'
  } catch (e) {
    console.warn('Lỗi lưu thông tin khách hàng DB:', e)
    await openSrAlert({
      variant: 'error',
      title: 'Lỗi lưu hồ sơ khách hàng',
      message: 'Không thể lưu thông tin khách hàng vào Database. Vui lòng thử lại.',
      confirmText: 'Đóng'
    })
  } finally {
    modal.saving = false
  }
}

