const recipientPickerModal = ref<{
  show: boolean
  targetItem: ImportItem | null
  searchQuery: string
}>({
  show: false,
  targetItem: null,
  searchQuery: ''
})

function openRecipientPickerModal(item: ImportItem) {
  if (!item) return
  recipientPickerModal.value = {
    show: true,
    targetItem: item,
    searchQuery: ''
  }
}

const companySpecificRecipients = computed(() => {
  const item = recipientPickerModal.value.targetItem
  if (!item) return [] as Array<{ name: string; source: string }>
  const out: Array<{ name: string; source: string }> = []
  const seen = new Set<string>()
  const addRec = (nameRaw: any, source: string) => {
    const clean = String(nameRaw || '').trim()
    if (!clean || clean === 'N/A') return
    const key = normalizeCustomerCompareStr(clean)
    if (seen.has(key)) return
    seen.add(key)
    out.push({ name: clean, source })
  }

  const dbCus = getMatchedDbCustomerForItem(item)
  if (dbCus) {
    addRec(dbCus.ten_khach_hang, `Tên KH chính trong DB (${dbCus.ten_cong_ty || dbCus.ma_khach_hang})`)
    addRec(dbCus.ten_khach_hang_phu, `Tên KH phụ trong DB (${dbCus.ten_cong_ty || dbCus.ma_khach_hang})`)
  }
  if (item.dxmhRecipient) {
    addRec(item.dxmhRecipient, 'Trích xuất từ File DXMH của PO này')
  }
  if (item.extractedRecipient) {
    addRec(item.extractedRecipient, `Trích xuất từ File ${item.extractedSourceLabel || 'Báo giá'}`)
  }

  // Quét thêm các người nhận từng xuất hiện trong lịch sử PO của cùng công ty
  const targetCompNorm = normalizeCustomerCompareStr(item.customer || dbCus?.ten_cong_ty)
  const targetMaCty = String(item.linkedMaCongTy || dbCus?.ma_cong_ty || '').trim().toUpperCase()
  if (targetCompNorm || targetMaCty) {
    rows.value.forEach(r => {
      const rMaCty = String(r.Ma_cong_ty || '').trim().toUpperCase()
      const rCompNorm = normalizeCustomerCompareStr(r.Ten_cong_ty)
      if ((targetMaCty && rMaCty === targetMaCty) || (targetCompNorm && rCompNorm === targetCompNorm)) {
        addRec(r.Ten_khach_hang, `Lịch sử PO #${r.So_PO || ''}`)
      }
    })
  }
  return out
})

const filteredRecipientDbList = computed(() => {
  const q = String(recipientPickerModal.value.searchQuery || '').trim().toLowerCase()
  const list = khachHangList.value.filter(c => c.ten_khach_hang || c.ten_khach_hang_phu)
  if (!q) return list.slice(0, 80)
  return list
    .filter(c => {
      const s = [c.ten_khach_hang, c.ten_khach_hang_phu, c.ten_cong_ty, c.so_dien_thoai_ca_nhan, c.sdt]
        .filter(Boolean)
        .join(' ')
        .toLowerCase()
      return s.includes(q)
    })
    .slice(0, 80)
})

