const industryPickerModal = ref<{
  show: boolean
  mode: 'po_item' | 'customer_detail'
  targetItem: ImportItem | null
  searchQuery: string
  newIndustryName: string
}>({
  show: false,
  mode: 'po_item',
  targetItem: null,
  searchQuery: '',
  newIndustryName: ''
})

const customAddedIndustries = ref<string[]>([])

const industryDirectoryList = computed(() => {
  const counts = new Map<string, { name: string; count: number }>()
  const addInd = (raw: string, inc = 1) => {
    const clean = String(raw || '').trim()
    if (!clean || clean === 'Chưa phân loại ngành') return
    const key = clean.toLowerCase()
    if (!counts.has(key)) {
      counts.set(key, { name: clean, count: 0 })
    }
    counts.get(key)!.count += inc
  }

  khachHangList.value.forEach(c => {
    const ind = getIndustryFromDbCustomer(c)
    if (ind) addInd(ind, 1)
  })
  customAddedIndustries.value.forEach(ind => addInd(ind, 0))

  return Array.from(counts.values()).sort((a, b) => b.count - a.count || a.name.localeCompare(b.name, 'vi'))
})

const filteredIndustryDirectoryList = computed(() => {
  const q = String(industryPickerModal.value.searchQuery || '').trim().toLowerCase()
  if (!q) return industryDirectoryList.value
  return industryDirectoryList.value.filter(it => it.name.toLowerCase().includes(q))
})

function openIndustryPickerModal(item: ImportItem | null, mode: 'po_item' | 'customer_detail' = 'po_item') {
  industryPickerModal.value = {
    show: true,
    mode,
    targetItem: item || activeModalItem.value,
    searchQuery: '',
    newIndustryName: ''
  }
}

function isIndustryCurrentlySelected(name: string): boolean {
  const norm = normalizeCustomerCompareStr(name)
  if (!norm) return false
  if (industryPickerModal.value.mode === 'customer_detail') {
    return normalizeCustomerCompareStr(dbCustomerDetailModal.value.form.nganh_nghe_cong_ty) === norm
  }
  const item = industryPickerModal.value.targetItem
  if (!item) return false
  return normalizeCustomerCompareStr(getDisplayIndustryForModalItem(item)) === norm
}

function selectIndustryFromModal(name: string) {
  const clean = String(name || '').trim()
  if (!clean) return
  if (industryPickerModal.value.mode === 'customer_detail') {
    dbCustomerDetailModal.value.form.nganh_nghe_cong_ty = clean
  } else if (industryPickerModal.value.targetItem) {
    onItemIndustryInput(industryPickerModal.value.targetItem, clean)
  }
  industryPickerModal.value.show = false
}

function createAndSelectNewIndustry() {
  const clean = String(industryPickerModal.value.newIndustryName || industryPickerModal.value.searchQuery || '').trim()
  if (!clean) return
  if (!customAddedIndustries.value.includes(clean)) {
    customAddedIndustries.value.push(clean)
  }
  selectIndustryFromModal(clean)
}

// ─── Modal Chọn / Thêm Nhóm Khách Hàng (tagKH) ───
const customerGroupPickerModal = ref<{
  show: boolean
  mode: 'po_item' | 'customer_detail'
  targetItem: ImportItem | null
  searchQuery: string
  newGroupName: string
}>({
  show: false,
  mode: 'po_item',
  targetItem: null,
  searchQuery: '',
  newGroupName: ''
})

const customAddedCustomerGroups = ref<string[]>([])

const customerGroupDirectoryList = computed(() => {
  const counts = new Map<string, { name: string; count: number }>()
  const addGrp = (raw: string, inc = 1) => {
    const clean = String(raw || '').trim()
    if (!clean || clean === 'Chưa gắn nhóm KH') return
    const key = clean.toLowerCase()
    if (!counts.has(key)) {
      counts.set(key, { name: clean, count: 0 })
    }
    counts.get(key)!.count += inc
  }

  khachHangList.value.forEach(c => {
    const grps = getCustomerGroupArrayFromDbCustomer(c)
    grps.forEach(g => addGrp(g, 1))
  })
  customAddedCustomerGroups.value.forEach(g => addGrp(g, 0))

  return Array.from(counts.values()).sort((a, b) => b.count - a.count || a.name.localeCompare(b.name, 'vi'))
})

const filteredCustomerGroupDirectoryList = computed(() => {
  const q = String(customerGroupPickerModal.value.searchQuery || '').trim().toLowerCase()
  if (!q) return customerGroupDirectoryList.value
  return customerGroupDirectoryList.value.filter(it => it.name.toLowerCase().includes(q))
})

function openCustomerGroupPickerModal(item: ImportItem | null, mode: 'po_item' | 'customer_detail' = 'po_item') {
  customerGroupPickerModal.value = {
    show: true,
    mode,
    targetItem: item || activeModalItem.value,
    searchQuery: '',
    newGroupName: ''
  }
}

function getCurrentSelectedCustomerGroupsInModal(): string[] {
  if (customerGroupPickerModal.value.mode === 'customer_detail') {
    return Array.isArray(dbCustomerDetailModal.value.form.tagKH)
      ? [...dbCustomerDetailModal.value.form.tagKH]
      : []
  }
  const item = customerGroupPickerModal.value.targetItem
  if (!item) return []
  return parseCustomerGroupStringToArray(getDisplayCustomerGroupForModalItem(item))
}

function isCustomerGroupCurrentlySelected(name: string): boolean {
  const norm = normalizeCustomerCompareStr(name)
  if (!norm) return false
  return getCurrentSelectedCustomerGroupsInModal().some(g => normalizeCustomerCompareStr(g) === norm)
}

function toggleCustomerGroupFromModal(name: string) {
  const clean = String(name || '').trim()
  if (!clean) return
  const norm = normalizeCustomerCompareStr(clean)
  const current = getCurrentSelectedCustomerGroupsInModal()
  const idx = current.findIndex(g => normalizeCustomerCompareStr(g) === norm)
  if (idx >= 0) {
    current.splice(idx, 1)
  } else {
    current.push(clean)
  }

  if (customerGroupPickerModal.value.mode === 'customer_detail') {
    dbCustomerDetailModal.value.form.tagKH = current
  } else if (customerGroupPickerModal.value.targetItem) {
    onItemCustomerGroupInput(customerGroupPickerModal.value.targetItem, current.join(', '))
  }
}

function createAndSelectNewCustomerGroup() {
  const clean = String(customerGroupPickerModal.value.newGroupName || customerGroupPickerModal.value.searchQuery || '').trim()
  if (!clean) return
  if (!customAddedCustomerGroups.value.includes(clean)) {
    customAddedCustomerGroups.value.push(clean)
  }
  if (!isCustomerGroupCurrentlySelected(clean)) {
    toggleCustomerGroupFromModal(clean)
  }
  customerGroupPickerModal.value.newGroupName = ''
}

function fmtDateShort(raw: any): string {
  if (!raw) return '—'
  const d = parseDateStr(String(raw))
  if (d && !isNaN(d.getTime())) {
    const p = (n: number) => String(n).padStart(2, '0')
    return `${p(d.getDate())}/${p(d.getMonth() + 1)}/${d.getFullYear()}`
  }
  return String(raw).split(' ')[0] || '—'
}

function toggleItemCustomerPicker(item: ImportItem) {
  if (!item) return
  openDbCustomerModal(item)
}

function getFilteredDbCustomersForItem(item: ImportItem) {
  const list = khachHangList.value
  const q = String(item?.customerSearchQuery || '').trim().toLowerCase()
  if (!q) return list.slice(0, 60)
  return list.filter(c => {
    const s = [c.ten_cong_ty, c.ten_khach_hang, c.ma_khach_hang, c.ma_cong_ty, c.mst, c.nganh_nghe_cong_ty, c.sdt, c.email]
      .filter(Boolean)
      .join(' ')
      .toLowerCase()
    return s.includes(q)
  }).slice(0, 60)
}

async function selectDbCustomerForModalItem(item: ImportItem, cus: any): Promise<boolean> {
  if (!item || !cus) return false
  const newMaKH = String(cus.ma_khach_hang || '').trim()
  const currentMaKH = String(item.linkedMaKH || item.row?.Ma_khach_hang || '').trim()

  if (currentMaKH && currentMaKH !== newMaKH) {
    const ok = await openSrConfirm({
      variant: 'info',
      eyebrow: 'Thay đổi liên kết khách hàng',
      title: 'Đổi khách hàng liên kết cho PO',
      highlightLabel: `MÃ KH HIỆN TẠI: ${currentMaKH}`,
      highlightValue: `${cus.ten_cong_ty || cus.ten_khach_hang} (Mã KH: ${newMaKH})`,
      message: `PO này đang gắn với Mã KH "${currentMaKH}". Bạn có chắc chắn muốn đổi sang khách hàng "${cus.ten_cong_ty || cus.ten_khach_hang}" (Mã KH: ${newMaKH}) không?`,
      confirmText: 'Đổi khách hàng',
      cancelText: 'Giữ nguyên'
    })
    if (!ok) return false
  }

  item.mst = cus.mst || item.mst || ''
  item.customer = cus.ten_cong_ty || cus.ten_khach_hang || ''
  item.recipient = (hasDxmhOnItem(item) && item.dxmhRecipient)
    ? item.dxmhRecipient
    : (cus.ten_khach_hang || '')
  item.industry = getIndustryFromDbCustomer(cus)
  item._industryEdited = false
  item.customerGroup = getCustomerGroupFromDbCustomer(cus)
  item._customerGroupEdited = false
  item.linkedMaKH = newMaKH
  item.linkedMaCongTy = cus.ma_cong_ty || genMaCongTy(cus.ten_cong_ty || cus.ten_khach_hang)
  item._approvedDbNameUpdate = false
  item.customerPickerOpen = false
  isModalDirty.value = true
  return true
}

async function applyExtractedQuoteCustomerToModalItem(
  item: ImportItem,
  extractedCompany: string,
  extractedRecipient: string,
  extractedMST: string,
  sourceLabel: string = 'Báo giá'
) {
  if (!item) return
  const isDxmhSource = sourceLabel === 'DXMH'
  const itemHasDxmh = isDxmhSource || hasDxmhOnItem(item)
  if (isDxmhSource && extractedRecipient) {
    item.dxmhRecipient = extractedRecipient
  }

  item.extractedCompany = extractedCompany || ''
  item.extractedRecipient = extractedRecipient || ''
  item.extractedMST = extractedMST || ''
  item.extractedSourceLabel = sourceLabel

  let dbCus = getMatchedDbCustomerForItem(item)
  if (!dbCus) {
    // Thử điền tạm để dò trong DB theo MST / Tên trích xuất
    const tempItem: any = {
      ...item,
      customer: extractedCompany || item.customer || '',
      recipient: extractedRecipient || item.recipient || extractedCompany || '',
      mst: extractedMST || item.mst || ''
    }
    dbCus = getMatchedDbCustomerForItem(tempItem)
  }

  if (dbCus) {
    // Giữ cố định 100% Mã KH và Mã công ty từ DB
    item.linkedMaKH = dbCus.ma_khach_hang
    item.linkedMaCongTy = dbCus.ma_cong_ty || genMaCongTy(dbCus.ten_cong_ty || dbCus.ten_khach_hang)

    const dbComp = String(dbCus.ten_cong_ty || '').trim()
    const dbRec = String(dbCus.ten_khach_hang || '').trim()
    const dbMst = String(dbCus.mst || '').trim()

    // Tên công ty & MST: ưu tiên DB nếu DB đã có, tự động bù nếu DB đang trống
    item.mst = dbMst || extractedMST || item.mst || ''
    item.customer = dbComp || extractedCompany || item.customer || ''

    // Người nhận (Tên KH): nếu PO có File DXMH thì luôn lấy theo đúng File DXMH; chưa có File DXMH thì lấy Tên KH từ DB như cũ
    if (isDxmhSource) {
      item.recipient = extractedRecipient || dbRec || item.recipient || ''
    } else if (itemHasDxmh) {
      item.recipient = item.dxmhRecipient || item.recipient || dbRec || extractedRecipient || ''
    } else {
      item.recipient = dbRec || extractedRecipient || item.recipient || ''
    }

    // Nếu tên trong file lệch với tên trong DB -> hỏi xác nhận + bật nút chuyển đổi nhanh 1-click (bỏ qua recDiff khi PO lấy người nhận theo DXMH)
    const compDiff = extractedCompany && dbComp && normalizeCustomerCompareStr(extractedCompany) !== normalizeCustomerCompareStr(dbComp)
    const recDiff = !itemHasDxmh && extractedRecipient && dbRec && normalizeCustomerCompareStr(extractedRecipient) !== normalizeCustomerCompareStr(dbRec)
    if (compDiff || recDiff) {
      let diffMsg = `Khách hàng đã có trong DB (Mã KH giữ nguyên: ${dbCus.ma_khach_hang}) nhưng tên trong File ${sourceLabel} có sự khác biệt:\n\n`
      if (compDiff) diffMsg += `• Tên công ty:\n  - Trong DB: "${dbComp}"\n  - Trong ${sourceLabel}: "${extractedCompany}"\n`
      if (recDiff) diffMsg += `• Người nhận (Tên KH):\n  - Trong DB: "${dbRec}"\n  - Trong ${sourceLabel}: "${extractedRecipient}"\n`
      diffMsg += `\nBạn có muốn áp dụng tên theo File ${sourceLabel} và cập nhật lại tên hiển thị vào DB không?`

      const applyFileNames = await openSrConfirm({
        variant: 'info',
        eyebrow: `Đối chiếu dữ liệu File ${sourceLabel} & Database`,
        title: `Khác biệt thông tin khách hàng (${sourceLabel})`,
        highlightLabel: `MÃ KH GIỮ CỐ ĐỊNH: ${dbCus.ma_khach_hang}`,
        highlightValue: extractedCompany || extractedRecipient || dbComp,
        message: diffMsg,
        subNote: `Mã KH "${dbCus.ma_khach_hang}" và Mã công ty vẫn giữ nguyên 100% để không ảnh hưởng Công nợ. Nếu bấm giữ tên DB, bạn vẫn có thể chuyển đổi nhanh phía trên ô nhập.`,
        confirmText: `Áp dụng theo File ${sourceLabel}`,
        cancelText: 'Giữ tên theo DB'
      })
      if (applyFileNames) {
        if (extractedCompany) item.customer = extractedCompany
        if (!itemHasDxmh && extractedRecipient) item.recipient = extractedRecipient
        item._approvedDbNameUpdate = true
      }
    }
  } else {
    // Khách mới hoàn toàn
    item.customer = extractedCompany || item.customer || ''
    if (isDxmhSource) {
      item.recipient = extractedRecipient || item.recipient || item.customer || ''
    } else if (itemHasDxmh) {
      item.recipient = item.dxmhRecipient || item.recipient || extractedRecipient || item.customer || ''
    } else {
      item.recipient = extractedRecipient || item.recipient || item.customer || ''
    }
    if (extractedMST) item.mst = extractedMST
    if (!item.mst) {
      const existingRow = rows.value.find(r => r.Ten_cong_ty?.trim().toLowerCase() === item.customer.toLowerCase() && r.MST)
      if (existingRow) item.mst = existingRow.MST
    }
  }
}

async function upsertCustomerFromModalItem(item: ImportItem) {
  const rawComp = String(item.customer || '').trim()
  const rawRec = String(item.recipient || '').trim()
  const rawMst = String(item.mst || '').trim()
  const rawInd = String(getDisplayIndustryForModalItem(item) || '').trim()
  const rawGrpStr = String(getDisplayCustomerGroupForModalItem(item) || '').trim()
  const rawGrpArr = parseCustomerGroupStringToArray(rawGrpStr)
  const dxmhInfo = item.dxmhCustomerDetails || null
  const itemHasDxmh = hasDxmhOnItem(item)

  const existingCus = getMatchedDbCustomerForItem(item)
  if (existingCus) {
    // QUY TẮC BẤT BIẾN: Không bao giờ thay đổi ma_khach_hang và ma_cong_ty của khách hàng đã tồn tại trong DB
    const maKHGen = String(existingCus.ma_khach_hang || '').trim() || genMaKhachHang(rawRec, rawComp)
    const maCongTyGen = String(existingCus.ma_cong_ty || '').trim() || genMaCongTy(existingCus.ten_cong_ty || existingCus.ten_khach_hang || rawComp || rawRec)

    const dbComp = String(existingCus.ten_cong_ty || '').trim()
    const dbRec = String(existingCus.ten_khach_hang || '').trim()
    const dbMst = String(existingCus.mst || '').trim()
    const dbInd = getIndustryFromDbCustomer(existingCus)
    const dbGrpArr = getCustomerGroupArrayFromDbCustomer(existingCus)

    const khUpdates: Record<string, any> = {}
    if (!dbMst && rawMst) khUpdates.mst = rawMst
    if (!dbComp && rawComp) khUpdates.ten_cong_ty = rawComp
    if (!dbRec) {
      const fallbackDbRec = itemHasDxmh
        ? (String(dxmhInfo?.ten_khach_hang || '').trim() || rawRec)
        : rawRec
      if (fallbackDbRec) khUpdates.ten_khach_hang = fallbackDbRec
    }
    if (rawInd && (!dbInd || item._industryEdited || item._approvedDbNameUpdate)) {
      khUpdates.nganh_nghe_cong_ty = rawInd
    }
    if ((rawGrpArr.length > 0 && dbGrpArr.length === 0) || item._customerGroupEdited || item._approvedDbNameUpdate) {
      if (rawGrpArr.length > 0 || item._customerGroupEdited) {
        khUpdates.tagKH = rawGrpArr
      }
    }

    // Bổ sung thông tin chi tiết khách hàng trích xuất từ File DXMH (giống CustomerFirebase) cho các trường đang trống
    if (dxmhInfo) {
      const extraFields = [
        'email_ca_nhan',
        'so_dien_thoai_ca_nhan',
        'so_dien_thoai_cong_ty',
        'so_fax_cong_ty',
        'dia_chi_cong_ty',
        'email_cong_ty',
        'website_cong_ty',
        'ten_khach_hang_phu',
        'so_dien_thoai_ca_nhan_phu',
        'company',
        'address',
        'tel'
      ]
      extraFields.forEach(field => {
        const incomingVal = String(dxmhInfo[field] || '').trim()
        const currentVal = String(existingCus[field] || '').trim()
        if (incomingVal && (!currentVal || item._approvedDbNameUpdate)) {
          khUpdates[field] = incomingVal
        }
      })
      if (!existingCus.sdt && (dxmhInfo.so_dien_thoai_ca_nhan || dxmhInfo.so_dien_thoai_cong_ty)) {
        khUpdates.sdt = String(dxmhInfo.so_dien_thoai_ca_nhan || dxmhInfo.so_dien_thoai_cong_ty).trim()
      }
      if (!existingCus.email && (dxmhInfo.email_ca_nhan || dxmhInfo.email_cong_ty)) {
        khUpdates.email = String(dxmhInfo.email_ca_nhan || dxmhInfo.email_cong_ty).trim()
      }
      if (!existingCus.dia_chi && (dxmhInfo.dia_chi_cong_ty || dxmhInfo.address)) {
        khUpdates.dia_chi = String(dxmhInfo.dia_chi_cong_ty || dxmhInfo.address).trim()
      }
    }

    const compChanged = dbComp && rawComp && normalizeCustomerCompareStr(dbComp) !== normalizeCustomerCompareStr(rawComp)
    const recChanged = !itemHasDxmh && dbRec && rawRec && normalizeCustomerCompareStr(dbRec) !== normalizeCustomerCompareStr(rawRec)
    const mstChanged = dbMst && rawMst && dbMst !== rawMst

    if (compChanged || recChanged || mstChanged) {
      let allowUpdate = Boolean(item._approvedDbNameUpdate)
      if (!allowUpdate) {
        let msg = `Thông tin khách hàng trên PO #${item.soPO || ''} khác với dữ liệu gốc trong DB (Mã KH giữ nguyên: ${maKHGen}):\n\n`
        if (compChanged) msg += `• Tên công ty: "${dbComp}" -> "${rawComp}"\n`
        if (recChanged) msg += `• Người nhận: "${dbRec}" -> "${rawRec}"\n`
        if (mstChanged) msg += `• MST: "${dbMst}" -> "${rawMst}"\n`
        msg += `\nBạn có muốn cập nhật lại tên hiển thị / MST mới này vào bảng Khách Hàng (khach_hang) không?`
        allowUpdate = await openSrConfirm({
          variant: 'info',
          eyebrow: 'Đồng bộ thông tin khách hàng',
          title: `Cập nhật thông tin khách hàng PO #${item.soPO || ''}`,
          highlightLabel: `MÃ KH GIỮ NGUYÊN: ${maKHGen}`,
          highlightValue: rawComp || rawRec || dbComp,
          message: msg,
          subNote: `Mã KH "${maKHGen}" và Mã công ty "${maCongTyGen}" vẫn giữ nguyên 100% để bảo toàn Công nợ.`,
          confirmText: 'Cập nhật vào DB',
          cancelText: 'Không cập nhật'
        })
      }
      if (allowUpdate) {
        if (compChanged) khUpdates.ten_cong_ty = rawComp
        if (recChanged) khUpdates.ten_khach_hang = rawRec
        if (mstChanged) khUpdates.mst = rawMst
        item._approvedDbNameUpdate = true
      }
    }

    if (Object.keys(khUpdates).length > 0 && existingCus.id) {
      try {
        khUpdates.last_updated = new Date().toISOString()
        await update(dbRef(database, `khach_hang/${existingCus.id}`), khUpdates)
        if (khachHangMap.value[existingCus.id]) {
          Object.assign(khachHangMap.value[existingCus.id], khUpdates)
        }
      } catch (e) {
        console.warn('Lỗi cập nhật khach_hang:', e)
      }
    }

    item.linkedMaKH = maKHGen
    item.linkedMaCongTy = maCongTyGen
    return {
      maKHGen,
      maCongTyGen,
      tenCongTy: rawComp || dbComp || rawRec || dbRec,
      tenKhachHang: rawRec || dbRec || rawComp || dbComp,
      mstVal: rawMst || dbMst
    }
  }

  // Khách hàng mới hoàn toàn -> Tạo bản ghi mới vào khach_hang (Tương thích đầy đủ schema CustomerFirebase)
  const tenCongTy = rawComp || rawRec
  const tenKhachHang = rawRec || rawComp
  const masterTenKH = (itemHasDxmh && String(dxmhInfo?.ten_khach_hang || '').trim())
    ? String(dxmhInfo?.ten_khach_hang || '').trim()
    : (tenKhachHang || tenCongTy)
  const maKHGen = item.row?.Ma_khach_hang || genMaKhachHang(masterTenKH, tenCongTy) || ('KH_UNKNOWN_' + Date.now())
  const maCongTyGen = item.row?.Ma_cong_ty || genMaCongTy(tenCongTy || masterTenKH) || ('CTY_UNKNOWN_' + Date.now())
  const mstVal = rawMst

  if (tenCongTy || tenKhachHang) {
    try {
      const newKhRef = push(dbRef(database, 'khach_hang'))
      const newKey = newKhRef.key
      const sdtCaNhan = String(dxmhInfo?.so_dien_thoai_ca_nhan || '').trim()
      const sdtCongTy = String(dxmhInfo?.so_dien_thoai_cong_ty || '').trim()
      const emailCaNhan = String(dxmhInfo?.email_ca_nhan || '').trim()
      const emailCongTy = String(dxmhInfo?.email_cong_ty || '').trim()
      const diaChiCongTy = String(dxmhInfo?.dia_chi_cong_ty || dxmhInfo?.address || '').trim()

      const newKhPayload = {
        mst: mstVal,
        ma_cong_ty: maCongTyGen,
        ten_cong_ty: tenCongTy || masterTenKH,
        ma_khach_hang: maKHGen,
        ten_khach_hang: masterTenKH,
        nganh_nghe_cong_ty: rawInd,
        email_ca_nhan: emailCaNhan,
        so_dien_thoai_ca_nhan: sdtCaNhan,
        so_dien_thoai_cong_ty: sdtCongTy,
        so_fax_cong_ty: String(dxmhInfo?.so_fax_cong_ty || '').trim(),
        dia_chi_cong_ty: diaChiCongTy,
        email_cong_ty: emailCongTy,
        website_cong_ty: String(dxmhInfo?.website_cong_ty || '').trim(),
        ten_khach_hang_phu: String(dxmhInfo?.ten_khach_hang_phu || '').trim(),
        so_dien_thoai_ca_nhan_phu: String(dxmhInfo?.so_dien_thoai_ca_nhan_phu || '').trim(),
        company: String(dxmhInfo?.company || '').trim(),
        address: String(dxmhInfo?.address || '').trim(),
        tel: String(dxmhInfo?.tel || '').trim(),
        sdt: sdtCaNhan || sdtCongTy,
        email: emailCaNhan || emailCongTy,
        dia_chi: diaChiCongTy,
        ngay_thanh_lap: '',
        tagKH: rawGrpArr,
        doanh_so: 0,
        cong_no: 0,
        ghi_chu: dxmhInfo ? 'Tạo tự động từ Sale Report / File DXMH' : 'Tạo tự động từ Sale Report / Báo giá',
        created_time: new Date().toISOString(), createdAt: Date.now(),
        last_updated: new Date().toISOString()
      }
      await set(newKhRef, newKhPayload)
      if (newKey) {
        khachHangMap.value = {
          ...khachHangMap.value,
          [newKey]: newKhPayload
        }
      }
      item.linkedMaKH = maKHGen
      item.linkedMaCongTy = maCongTyGen
    } catch (e) {
      console.warn('Lỗi tạo mới khach_hang từ SaleReport:', e)
    }
  }

  return {
    maKHGen,
    maCongTyGen,
    tenCongTy: tenCongTy || tenKhachHang,
    tenKhachHang: tenKhachHang || tenCongTy,
    mstVal
  }
}

function onFinancialInput(item: ImportItem, fieldChanged?: keyof ImportItem | 'taxPct') {
  if (fieldChanged === 'doanhSoBan' && item.goodsTotal) {
    const dsbVal = Number(item.doanhSoBan) || 0;
    const vatVal = Number(item.goodsTotal.vat) || 0;
    item.goodsTotal = {
      ...item.goodsTotal,
      ttTruoc: dsbVal,
      vat: vatVal,
      ttSau: dsbVal + vatVal
    };
  }
  const pct = (Number(item.taxPct) || 0) / 100;

  if (fieldChanged === 'netCom') {
    if (pct < 1) {
      item.grossCom = item.netCom / (1 - pct);
    }
  } else if (fieldChanged === 'grossCom' || fieldChanged === 'taxPct') {
    item.netCom = item.grossCom * (1 - pct);
  } else {
    // Mặc định tự tính netCom từ grossCom khi thay đổi trường khác
    item.netCom = item.grossCom * (1 - pct);
  }

  // Cập nhật lại số liệu gốc sau khi chỉnh sửa tay, và reset dự đoán
  item._origGross = item.grossCom;
  item._origNet = item.netCom;
  item.predictPct = '';
}

function onGoodsValueChange(
  item: ImportItem,
  g: any,
  field: 'sl' | 'donGia' | 'vatPct' | 'vat',
  val: number
) {
  if (!g) return
  const numVal = Number(val) || 0

  if (field === 'sl') {
    const nextSl = Math.max(0, numVal)
    if (Math.abs((Number(g.sl) || 0) - nextSl) < 1e-6) return
    g.sl = nextSl
    g.slStr = String(nextSl)
  } else if (field === 'donGia') {
    const nextDonGia = Math.round(numVal)
    if (Math.round(Number(g.donGia) || 0) === nextDonGia) return
    g.donGia = nextDonGia
    g.donGiaStr = nextDonGia !== 0 ? nextDonGia.toLocaleString('vi-VN') : ''
  } else if (field === 'vatPct') {
    const nextPct = Math.max(0, numVal)
    const prevPct = parseFloat(String(g.vatPct || '').replace(/[^0-9.-]/g, '')) || 0
    if (Math.abs(prevPct - nextPct) < 1e-6) return
    g.vatPct = nextPct === 0 ? '' : String(nextPct)
    g.vat = Math.round((g.ttTruoc || 0) * (nextPct / 100))
    g.vatStr = g.vat !== 0 ? g.vat.toLocaleString('vi-VN') : ''
  } else if (field === 'vat') {
    const nextVat = Math.round(numVal)
    if (Math.round(Number(g.vat) || 0) === nextVat) return
    g.vat = nextVat
    g.vatStr = nextVat !== 0 ? nextVat.toLocaleString('vi-VN') : ''
    if (g.ttTruoc > 0) {
      const pct = (nextVat / g.ttTruoc) * 100
      g.vatPct = pct === 0 ? '' : (pct % 1 === 0 ? String(pct) : pct.toFixed(2))
    } else {
      g.vatPct = ''
    }
  }

  g.ttTruoc = Math.round((g.sl || 0) * (g.donGia || 0))
  if (field !== 'vat' && g.vatPct) {
    const pct = parseFloat(String(g.vatPct).replace(/[^0-9.-]/g, '')) || 0
    g.vat = Math.round(g.ttTruoc * (pct / 100))
    g.vatStr = g.vat !== 0 ? g.vat.toLocaleString('vi-VN') : ''
  }
  g.ttSau = g.ttTruoc + (g.vat || 0)

  onGoodsInput(null, item, null, 'recalc')
}

function onGoodsInput(e: Event | null, item: ImportItem, g: any, field: string) {
  if (e && g) {
    const target = e.target as HTMLInputElement;
    const raw = target?.value ?? '';
    
    if (field === 'sl') {
       g.slStr = raw;
       g.sl = parseFloat(raw.replace(/[^0-9.-]/g, '')) || 0;
    } else if (field === 'vatPct') {
       g.vatPct = raw;
       let pct = parseFloat(raw.replace(/[^0-9.-]/g, '')) || 0;
       g.vat = (g.ttTruoc || 0) * (pct / 100);
       g.vatStr = g.vat === 0 ? '' : g.vat.toLocaleString('vi-VN');
    } else if (field === 'vat') {
       const val = parseInt(raw.replace(/[^0-9-]/g, '')) || 0;
       target.value = val === 0 && raw.replace(/[^0-9-]/g, '') === '' ? '' : val.toLocaleString('vi-VN');
       g.vatStr = target.value;
       g.vat = val;
       if (g.ttTruoc > 0) {
          let pct = (val / g.ttTruoc) * 100;
          g.vatPct = pct % 1 === 0 ? String(pct) : pct.toFixed(2);
       } else {
          g.vatPct = '';
       }
    } else if (field === 'donGia') {
       const val = parseInt(raw.replace(/[^0-9-]/g, '')) || 0;
       target.value = val === 0 && raw.replace(/[^0-9-]/g, '') === '' ? '' : val.toLocaleString('vi-VN');
       g.donGiaStr = target.value;
       g.donGia = val;
    }
    
    g.ttTruoc = (g.sl || 0) * (g.donGia || 0);
    
    // Re-eval vat based on vatPct if available
    if (field !== 'vat' && g.vatPct) {
       let pct = parseFloat(String(g.vatPct).replace(/[^0-9.-]/g, '')) || 0;
       g.vat = g.ttTruoc * (pct / 100);
       g.vatStr = g.vat === 0 ? '' : g.vat.toLocaleString('vi-VN');
    }
    
    g.ttSau = g.ttTruoc + (g.vat || 0);
  }
  
  // Calc Total
  if (item.goodsList && item.goodsList.length > 0) {
    let tTruoc = 0, tVat = 0, tSau = 0;
    item.goodsList.forEach((row, idx) => {
       if (!row.stt || /^\d+$/.test(String(row.stt))) row.stt = idx + 1;
       tTruoc += (row.ttTruoc || 0);
       tVat += (row.vat || 0);
       tSau += (row.ttSau || 0);
    });
    item.goodsTotal = { ttTruoc: tTruoc, vat: tVat, ttSau: tSau };
    
    // Update Doanh số bán when goods list is edited
    item.doanhSoBan = tTruoc;
    
    // Recompute Gross Com / Net Com if prediction is active
    if (item.predictPct) {
       const pct = parseFloat(item.predictPct.replace(/[^0-9.-]/g, ''));
       if (!isNaN(pct)) {
         item.netCom = item.doanhSoBan * (pct / 100);
         const taxPctNum = (Number(item.taxPct) || 0) / 100;
         item.grossCom = taxPctNum < 1 ? item.netCom / (1 - taxPctNum) : item.netCom;
       }
    }
  } else {
    item.goodsTotal = null;
  }
  isModalDirty.value = true;
}

function addGoodsRow(item: ImportItem) {
  if (!Array.isArray(item.goodsList)) {
    item.goodsList = [];
  }
  const nextStt = item.goodsList.length + 1;
  item.goodsList.push({
    stt: nextStt,
    danhMuc: '',
    ten: '',
    dienGiai: '',
    dvt: 'Cái',
    sl: 1,
    slStr: '1',
    donGia: 0,
    donGiaStr: '',
    ttTruoc: 0,
    vat: 0,
    vatPct: '10',
    vatStr: '',
    ttSau: 0
  });
  isModalDirty.value = true;
}

function updateCategory(item: any, startIdx: number, newCategory: string, oldCategory: string) {
  if (!item.goodsList) return;
  for (let i = startIdx; i < item.goodsList.length; i++) {
    if (item.goodsList[i].danhMuc === oldCategory) {
      item.goodsList[i].danhMuc = newCategory;
    } else {
      break;
    }
  }
  isModalDirty.value = true;
}

function removeGoodsRow(item: any, idx: number) {
  if (item.goodsList && item.goodsList.length > 1) {
    item.goodsList.splice(idx, 1);
    onGoodsInput(null, item, null, 'delete');
  } else if (multiEditModal.value.mode === 'create' && item.goodsList && item.goodsList.length === 1) {
    item.goodsList.splice(idx, 1);
    item.goodsTotal = null;
    isModalDirty.value = true;
  } else {
    openSrAlert({
      variant: 'warning',
      title: 'Không thể xóa dòng hàng hóa cuối cùng',
      message: 'Hợp đồng bắt buộc phải có ít nhất 1 hàng hóa. Vui lòng chỉnh sửa trực tiếp trên dòng này thay vì xóa.',
      confirmText: 'Đã hiểu'
    });
  }
}

// ─── Kiểm tra & Đồng bộ Bảng Hàng Hóa PO vào Database (hang_hoa) — Cách B ───
function cleanGoodsCodeSeg(val: any): string {
  return String(val || '')
    .trim()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .toUpperCase()
    .replace(/\s+/g, '-')
    .replace(/[^A-Z0-9\-]/g, '')
    .replace(/-+/g, '-')
    .replace(/^-+|-+$/g, '')
}

function genHangHoaCode(danhMuc: any, tenHang: any): string {
  const dmSeg = cleanGoodsCodeSeg(danhMuc)
  const tenSeg = cleanGoodsCodeSeg(tenHang)
  if (dmSeg && tenSeg) return `${dmSeg}-${tenSeg}`
  return tenSeg || dmSeg || ('HH-' + Date.now())
}

function normalizeGoodsMatchStr(val: any): string {
  return String(val || '')
    .trim()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
}

const hangHoaCatalogVersion = ref(0)
const hhNormWeakCache = new WeakMap<object, { ver: number; maNorm: string; tenNorm: string; tokens: string[]; nums: string[]; searchHay: string }>()
const goodsMatchWeakCache = new WeakMap<object, { key: string; val: any }>()

const hangHoaLookupIndex = computed(() => {
  const ver = hangHoaCatalogVersion.value
  const list = hangHoaCatalogList.value || []
  const byKey = new Map<string, any>()
  const byMaNorm = new Map<string, any>()
  const byTenNorm = new Map<string, any>()
  const enriched: Array<{ raw: any; maNorm: string; tenNorm: string; tokens: string[]; nums: string[]; searchHay: string }> = []

  for (const hh of list) {
    if (!hh) continue
    const rawHh = toRaw(hh) as object
    let meta = hhNormWeakCache.get(rawHh)
    if (!meta || meta.ver !== ver) {
      const maNorm = normalizeGoodsMatchStr(hh.ma_hang)
      const tenNorm = normalizeGoodsMatchStr(hh.ten_hang)
      const tokens = tenNorm ? tenNorm.split(' ').filter(Boolean) : []
      const nums = tokens.filter((t: string) => /^\d+$/.test(t))
      const searchHay = normalizeGoodsMatchStr(`${hh.ma_hang || ''} ${hh.ten_hang || ''} ${hh.danh_muc || ''} ${hh.ten_ncc || ''}`)
      meta = { ver, maNorm, tenNorm, tokens, nums, searchHay }
      hhNormWeakCache.set(rawHh, meta)
    }
    if (hh._firebaseKey) byKey.set(hh._firebaseKey, hh)
    if (hh.ma_hang && !byKey.has(hh.ma_hang)) byKey.set(hh.ma_hang, hh)
    if (meta.maNorm && !byMaNorm.has(meta.maNorm)) byMaNorm.set(meta.maNorm, hh)
    if (meta.tenNorm && !byTenNorm.has(meta.tenNorm)) byTenNorm.set(meta.tenNorm, hh)
    enriched.push({ raw: hh, ...meta })
  }

  return {
    version: `${ver}_${list.length}`,
    list,
    enriched,
    byKey,
    byMaNorm,
    byTenNorm
  }
})

function matchPoGoodsRowWithDb(g: any): {
  status: 'new' | 'diff' | 'matched' | 'empty'
  dbItem: any | null
  dbDonGiaVnd: number
  dbGiaNhapVnd: number
} {
  if (!g) return { status: 'empty', dbItem: null, dbDonGiaVnd: 0, dbGiaNhapVnd: 0 }
  const rawTen = String(g.ten || '').trim()
  const rawMa = String(g.maHang || '').trim()
  if (!rawTen && !rawMa) {
    return { status: 'empty', dbItem: null, dbDonGiaVnd: 0, dbGiaNhapVnd: 0 }
  }

  // Nếu chưa bấm "Kiểm tra & Đồng bộ DB" (hangHoaCatalogLoaded === false) và dòng chưa đồng bộ trước đó -> trả về 'empty' tức thì để không gây đơ trang
  if (!hangHoaCatalogLoaded.value && !g._syncedDbDone) {
    return { status: 'empty', dbItem: null, dbDonGiaVnd: 0, dbGiaNhapVnd: 0 }
  }

  const rawG = toRaw(g) as object
  const idx = hangHoaLookupIndex.value
  const fileDonGiaVnd = Math.round(toNum(g.donGia))
  const cacheKey = `${idx.version}|${g._linkedDbKey || ''}|${rawMa}|${rawTen}|${fileDonGiaVnd}|${g._syncedDbDone ? 1 : 0}|${g._syncedFilePrice || 0}`
  const cached = goodsMatchWeakCache.get(rawG)
  if (cached && cached.key === cacheKey) {
    return cached.val
  }

  if (g._linkedDbKey === '__NEW__') {
    const res = { status: 'new' as const, dbItem: null, dbDonGiaVnd: 0, dbGiaNhapVnd: 0 }
    goodsMatchWeakCache.set(rawG, { key: cacheKey, val: res })
    return res
  }

  let matchedDb: any | null = null

  if (g._linkedDbKey) {
    matchedDb = idx.byKey.get(g._linkedDbKey) || null
  }

  if (!matchedDb && idx.enriched.length > 0) {
    const tenNorm = normalizeGoodsMatchStr(rawTen)
    const maNorm = normalizeGoodsMatchStr(rawMa)

    // 1. Khớp chính xác tức thì O(1) qua Map
    if (maNorm && idx.byMaNorm.has(maNorm)) {
      matchedDb = idx.byMaNorm.get(maNorm)
    } else if (tenNorm && idx.byTenNorm.has(tenNorm)) {
      matchedDb = idx.byTenNorm.get(tenNorm)
    } else if (tenNorm && idx.byMaNorm.has(tenNorm)) {
      matchedDb = idx.byMaNorm.get(tenNorm)
    }

    // 2. Khớp theo cụm từ khóa & số hiệu đã tiền xử lý nếu chưa khớp tuyệt đối
    if (!matchedDb && tenNorm.length >= 5) {
      const impTokens = tenNorm.split(' ').filter(Boolean)
      const impNums = impTokens.filter(t => /^\d+$/.test(t))
      const impSet = new Set(impTokens)
      let bestCandidate: any | null = null
      let bestScore = 0

      for (const entry of idx.enriched) {
        const hhTenNorm = entry.tenNorm
        if (!hhTenNorm || hhTenNorm.length < 5) continue
        const hhTokens = entry.tokens
        const hhNums = entry.nums

        const numsCompatible =
          hhNums.every(n => impNums.includes(n)) &&
          impNums.every(n => hhNums.includes(n))
        if (!numsCompatible) continue

        if (
          (tenNorm.includes(hhTenNorm) && hhTenNorm.length >= 8 && hhTokens.length >= 2) ||
          (hhTenNorm.includes(tenNorm) && tenNorm.length >= 8 && impTokens.length >= 2)
        ) {
          const sc = 90 + Math.min(8, hhTokens.length)
          if (sc > bestScore) {
            bestScore = sc
            bestCandidate = entry.raw
          }
          continue
        }

        if (hhTokens.length >= 2 && impTokens.length >= 2) {
          let mHh = 0
          for (let k = 0; k < hhTokens.length; k++) {
            if (impSet.has(hhTokens[k])) mHh++
          }
          const rHh = mHh / hhTokens.length
          const rImp = mHh / impTokens.length
          if ((rHh >= 0.85 && mHh >= 2) || (rImp >= 0.85 && mHh >= 2)) {
            const sc = Math.round(85 + Math.max(rHh, rImp) * 5)
            if (sc > bestScore) {
              bestScore = sc
              bestCandidate = entry.raw
            }
          }
        }
      }

      if (bestCandidate && bestScore >= 85) {
        matchedDb = bestCandidate
      }
    }
  }

  if (!matchedDb) {
    const res = { status: 'new' as const, dbItem: null, dbDonGiaVnd: 0, dbGiaNhapVnd: 0 }
    goodsMatchWeakCache.set(rawG, { key: cacheKey, val: res })
    return res
  }

  const dbCur = String(matchedDb.don_vi_tien_te || 'VND').trim().toUpperCase()
  const dbRate = dbCur === 'USD' && toNum(matchedDb.ti_gia) > 1 ? toNum(matchedDb.ti_gia) : 1
  const rawDonGia = toNum(matchedDb.don_gia) || toNum(matchedDb.gia_tieu_chuan)
  const rawGiaNhap = toNum(matchedDb.gia_nhap)
  const dbDonGiaVnd = dbCur === 'USD' ? Math.round(rawDonGia * dbRate) : Math.round(rawDonGia)
  const dbGiaNhapVnd = dbCur === 'USD' ? Math.round(rawGiaNhap * dbRate) : Math.round(rawGiaNhap)

  let finalStatus: 'matched' | 'diff' = 'diff'
  if (g._syncedDbDone && g._syncedFilePrice === fileDonGiaVnd) {
    finalStatus = 'matched'
  } else if (dbDonGiaVnd > 0 && fileDonGiaVnd > 0 && Math.abs(fileDonGiaVnd - dbDonGiaVnd) <= 10) {
    finalStatus = 'matched'
  }

  const res = { status: finalStatus, dbItem: matchedDb, dbDonGiaVnd, dbGiaNhapVnd }
  goodsMatchWeakCache.set(rawG, { key: cacheKey, val: res })
  return res
}

function getPoGoodsDbStats(item: ImportItem | null | undefined) {
  const list = Array.isArray(item?.goodsList) ? item!.goodsList : []
  let newCount = 0
  let diffCount = 0
  let matchedCount = 0

  for (const g of list) {
    const info = matchPoGoodsRowWithDb(g)
    if (info.status === 'new') newCount++
    else if (info.status === 'diff') diffCount++
    else if (info.status === 'matched') matchedCount++
  }

  return {
    total: list.length,
    newCount,
    diffCount,
    matchedCount,
    needActionCount: newCount + diffCount
  }
}

interface PoGoodsDbSyncRow {
  goodsIdx: number
  selected: boolean
  status: 'new' | 'diff' | 'matched'
  dbItem: any | null
  maHang: string
  maHangEdited: boolean
  tenHang: string
  danhMuc: string
  dvt: string
  vatPct: number
  dienGiai: string
  donGiaFileVnd: number
  chenhLechVnd: number
  giaNhapVnd: number
  offType: 'pct' | 'amount'
  offPct: number
  offAmountVnd: number
  priceMode: 'file' | 'calc'
  currency: 'VND' | 'USD'
  tiGia: number
}

const poGoodsDbSyncModal = ref<{
  show: boolean
  saving: boolean
  targetItem: ImportItem | null
  filterTab: 'all' | 'new' | 'diff' | 'matched'
  bulkCurrency: 'VND' | 'USD'
  bulkTiGia: number
  rows: PoGoodsDbSyncRow[]
  pickerRowIdx: number | null
  pickerSearch: string
  attrPickerRowIdx: number | null
  attrPickerType: 'danh_muc' | 'dvt' | 'ti_gia' | null
  attrPickerSearch: string
}>({
  show: false,
  saving: false,
  targetItem: null,
  filterTab: 'all',
  bulkCurrency: 'VND',
  bulkTiGia: 25500,
  rows: [],
  pickerRowIdx: null,
  pickerSearch: '',
  attrPickerRowIdx: null,
  attrPickerType: null,
  attrPickerSearch: ''
})

// Tổng hợp Danh_muc, DVT và Ti_gia từ bảng hang_hoa (hangHoaCatalogList)
const hangHoaCatalogAttrStats = computed(() => {
  const _ver = hangHoaCatalogVersion.value
  void _ver
  const list = hangHoaCatalogList.value || []
  const catMap = new Map<string, number>()
  const dvtMap = new Map<string, number>()
  const tiGiaMap = new Map<number, number>()
  let mostCommonUsdRate = 0
  let maxRateCount = 0

  for (const hh of list) {
    const cat = String(hh.danh_muc || '').trim().toUpperCase()
    if (cat) catMap.set(cat, (catMap.get(cat) || 0) + 1)

    const dvt = String(hh.dvt || '').trim()
    if (dvt) dvtMap.set(dvt, (dvtMap.get(dvt) || 0) + 1)

    const rate = Math.round(toNum(hh.ti_gia))
    if (rate > 1000) {
      const nextCnt = (tiGiaMap.get(rate) || 0) + 1
      tiGiaMap.set(rate, nextCnt)
      if (nextCnt > maxRateCount) {
        maxRateCount = nextCnt
        mostCommonUsdRate = rate
      }
    }
  }

  const danhMucOptions = Array.from(catMap.entries())
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0], 'vi'))
    .map(([value, count]) => ({ value, label: value, count }))

  const dvtOptions = Array.from(dvtMap.entries())
    .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0], 'vi'))
    .map(([value, count]) => ({ value, label: value, count }))

  const tiGiaOptions = Array.from(tiGiaMap.entries())
    .sort((a, b) => b[1] - a[1] || b[0] - a[0])
    .map(([value, count]) => ({
      value,
      label: `${value.toLocaleString('vi-VN')} đ/USD`,
      count
    }))

  return {
    danhMucOptions,
    dvtOptions,
    tiGiaOptions,
    defaultUsdRate: mostCommonUsdRate > 1000 ? mostCommonUsdRate : 25500
  }
})

function calcSyncRowStandardPriceVnd(r: PoGoodsDbSyncRow): number {
  const filePrice = toNum(r.donGiaFileVnd)
  const diff = toNum(r.chenhLechVnd)
  const cost = toNum(r.giaNhapVnd)
  const baseAfterDiffAndCost = filePrice - diff - cost
  if (r.offType === 'amount') {
    const offAmt = Math.max(0, toNum(r.offAmountVnd))
    return Math.max(0, Math.round(baseAfterDiffAndCost + offAmt))
  }
  const off = Math.min(99.99, Math.max(0, toNum(r.offPct)))
  const denom = 1 - off / 100
  const raw = denom > 0.0001 ? baseAfterDiffAndCost / denom : baseAfterDiffAndCost
  return Math.max(0, Math.round(raw))
}

function getSyncRowEffectiveDonGiaVnd(r: PoGoodsDbSyncRow): number {
  if (r.priceMode === 'calc') {
    return calcSyncRowStandardPriceVnd(r)
  }
  return Math.max(0, Math.round(toNum(r.donGiaFileVnd)))
}

function getSyncRowEffectiveGiaNhapVnd(r: PoGoodsDbSyncRow): number {
  return Math.max(0, Math.round(toNum(r.giaNhapVnd)))
}

function getSyncRowFinalDonGiaToSave(r: PoGoodsDbSyncRow): number {
  const vnd = getSyncRowEffectiveDonGiaVnd(r)
  if (r.currency === 'USD') {
    const rate = toNum(r.tiGia) > 0 ? toNum(r.tiGia) : 1
    return Math.round((vnd / rate) * 100) / 100
  }
  return vnd
}

function getSyncRowFinalGiaNhapToSave(r: PoGoodsDbSyncRow): number {
  const vnd = getSyncRowEffectiveGiaNhapVnd(r)
  if (r.currency === 'USD') {
    const rate = toNum(r.tiGia) > 0 ? toNum(r.tiGia) : 1
    return Math.round((vnd / rate) * 100) / 100
  }
  return vnd
}

function formatUsdPrice(val: number): string {
  const num = Number(val) || 0
  return num.toLocaleString('en-US', {
    minimumFractionDigits: num % 1 === 0 ? 0 : 2,
    maximumFractionDigits: 2
  })
}

const goodsDbLoadingModal = ref<{
  show: boolean
  percent: number
  stepTitle: string
  stepDetail: string
  processedCount: number
  totalCount: number
  fromCacheFallback: boolean
}>({
  show: false,
  percent: 0,
  stepTitle: '',
  stepDetail: '',
  processedCount: 0,
  totalCount: 0,
  fromCacheFallback: false
})

async function fetchAndSyncHangHoaCatalogWithProgress(): Promise<void> {
  goodsDbLoadingModal.value = {
    show: true,
    percent: 8,
    stepTitle: 'Đang kết nối & tải danh mục Hàng hóa mới nhất...',
    stepDetail: 'Đang gọi bảng hang_hoa từ Cloud Database & kiểm tra bộ nhớ đệm...',
    processedCount: 0,
    totalCount: 0,
    fromCacheFallback: false
  }

  let ticker: ReturnType<typeof setInterval> | null = setInterval(() => {
    if (goodsDbLoadingModal.value.percent < 42) {
      goodsDbLoadingModal.value.percent += 3
    }
  }, 90)

  let rawHangHoaObj: Record<string, any> | null = null
  try {
    const snap = await get(dbRef(database, 'hang_hoa'))
    rawHangHoaObj = snap.val() || {}
  } catch (err) {
    console.warn('Không thể tải hang_hoa mới từ Firebase, chuyển sang đọc Cache IndexedDB:', err)
    rawHangHoaObj = null
  } finally {
    if (ticker) {
      clearInterval(ticker)
      ticker = null
    }
  }

  if (rawHangHoaObj && Object.keys(rawHangHoaObj).length > 0) {
    const entries = Object.entries(rawHangHoaObj)
    const total = entries.length
    goodsDbLoadingModal.value.percent = 45
    goodsDbLoadingModal.value.totalCount = total
    goodsDbLoadingModal.value.processedCount = 0
    goodsDbLoadingModal.value.stepTitle = 'Đang chuẩn hóa & cập nhật Cache Hàng hóa...'
    goodsDbLoadingModal.value.stepDetail = `Đang xử lý và lập chỉ mục ${total.toLocaleString('vi-VN')} mặt hàng...`

    const nextVer = hangHoaCatalogVersion.value + 1
    const nccMap = new Map<string, string>()
    const catList: any[] = []
    const CHUNK_SIZE = 350

    for (let start = 0; start < total; start += CHUNK_SIZE) {
      const end = Math.min(total, start + CHUNK_SIZE)
      for (let i = start; i < end; i++) {
        const [fbKey, hh] = entries[i]
        if (!hh || typeof hh !== 'object') continue
        const rawNcc = String(
          hh.Ten_nha_cung_cap || hh.ten_nha_cung_cap || hh.Ma_nha_cung_cap || hh.ma_nha_cung_cap || ''
        ).trim()
        const itemEntry = {
          _firebaseKey: fbKey,
          ma_hang: String(hh.Ma_hang ?? hh.Ma_hang_hoa ?? hh.ma_hang_hoa ?? hh.ma_hang ?? '').trim(),
          sku_code: String(hh.sku_code ?? hh.SKU ?? hh.sku ?? '').trim(),
          ten_hang: String(hh.Ten_hang ?? hh.Ten_hang_hoa ?? hh.ten_hang_hoa ?? hh.ten_hang ?? '').trim(),
          danh_muc: String(hh.Danh_muc ?? hh.danh_muc ?? '').trim().toUpperCase(),
          dvt: String(hh.DVT ?? hh.dvt ?? '').trim(),
          gia_tieu_chuan: Number(hh.Gia_tieu_chuan ?? hh.gia_tieu_chuan ?? hh.Don_gia ?? hh.don_gia ?? 0) || 0,
          don_gia: Number(hh.Don_gia ?? hh.don_gia ?? hh.Gia_tieu_chuan ?? hh.gia_tieu_chuan ?? 0) || 0,
          gia_nhap: Number(hh.gia_nhap ?? hh.Gia_nhap ?? 0) || 0,
          muc_phan_tram_off: Number(hh['muc_%_off'] ?? hh.muc_phan_tram_off ?? 0) || 0,
          don_vi_tien_te: String(hh.Don_vi_tien_te ?? hh.don_vi_tien_te ?? 'VND').trim().toUpperCase() || 'VND',
          ti_gia: Number(hh.Ti_gia ?? hh.ti_gia ?? 1) || 1,
          thue_vat: Number(hh.Thue_VAT ?? hh.thue_vat ?? 0) || 0,
          features: String(hh.Features ?? hh.features ?? '').trim(),
          description: String(hh.Description ?? hh.description ?? '').trim(),
          ten_ncc: rawNcc,
          ma_ncc: String(hh.Ma_nha_cung_cap ?? hh.ma_nha_cung_cap ?? '').trim()
        }
        // Tiền xử lý trước chỉ mục từ khóa vào WeakMap để tránh đơ luồng chính khi mở bảng đối chiếu
        const maNorm = normalizeGoodsMatchStr(itemEntry.ma_hang)
        const tenNorm = normalizeGoodsMatchStr(itemEntry.ten_hang)
        const tokens = tenNorm ? tenNorm.split(' ').filter(Boolean) : []
        const nums = tokens.filter((t: string) => /^\d+$/.test(t))
        const searchHay = normalizeGoodsMatchStr(
          `${itemEntry.ma_hang || ''} ${itemEntry.ten_hang || ''} ${itemEntry.danh_muc || ''} ${itemEntry.ten_ncc || ''}`
        )
        hhNormWeakCache.set(itemEntry, {
          ver: nextVer,
          maNorm,
          tenNorm,
          tokens,
          nums,
          searchHay
        })
        catList.push(itemEntry)

        if (rawNcc) {
          const key = rawNcc.toLowerCase()
          if (!nccMap.has(key)) {
            nccMap.set(key, rawNcc)
          } else {
            const existingVal = nccMap.get(key) || ''
            if (rawNcc === rawNcc.toUpperCase() && existingVal !== existingVal.toUpperCase()) {
              nccMap.set(key, rawNcc)
            }
          }
        }
      }

      goodsDbLoadingModal.value.processedCount = end
      goodsDbLoadingModal.value.percent = 45 + Math.round((end / total) * 38)
      await new Promise(resolve => setTimeout(resolve, 10))
    }

    const sortedNccs = Array.from(nccMap.values()).sort((a, b) => a.localeCompare(b, 'vi'))
    hangHoaCatalogList.value = catList
    hangHoaNccList.value = sortedNccs
    hangHoaCatalogVersion.value = nextVer
    hangHoaCatalogLoaded.value = true

    goodsDbLoadingModal.value.stepDetail = 'Đang lưu bộ nhớ đệm (IndexedDB Cache) để tăng tốc lần sau...'
    await writeHangHoaCacheToIdb(catList, sortedNccs)
  } else {
    // Fallback đọc từ IndexedDB Cache nếu mạng lỗi hoặc Firebase trống
    const cached = await readHangHoaCacheFromIdb()
    if (cached && cached.catalogList.length > 0) {
      goodsDbLoadingModal.value.fromCacheFallback = true
      goodsDbLoadingModal.value.totalCount = cached.catalogList.length
      goodsDbLoadingModal.value.processedCount = cached.catalogList.length
      goodsDbLoadingModal.value.percent = 82
      goodsDbLoadingModal.value.stepTitle = 'Đang nạp dữ liệu từ Bộ nhớ đệm (Cache)...'
      goodsDbLoadingModal.value.stepDetail = `Đã nạp ${cached.catalogList.length.toLocaleString('vi-VN')} mặt hàng từ Cache.`
      hangHoaCatalogList.value = cached.catalogList
      if (cached.nccList.length > 0) {
        hangHoaNccList.value = cached.nccList
      }
      hangHoaCatalogVersion.value++
      hangHoaCatalogLoaded.value = true
      hangHoaCacheTimestamp.value = cached.updatedAt
      await new Promise(resolve => setTimeout(resolve, 80))
    } else {
      hangHoaCatalogLoaded.value = true
    }
  }
}

async function openPoGoodsDbSyncModal(item: ImportItem, focusRowIdx?: number) {
  if (!item || !Array.isArray(item.goodsList) || item.goodsList.length === 0) {
    openSrAlert({
      variant: 'warning',
      title: 'Bảng hàng hóa đang trống',
      message: 'Vui lòng thêm ít nhất 1 dòng hàng hóa hoặc tải file báo giá lên trước khi kiểm tra & đồng bộ Database.',
      confirmText: 'Đã hiểu'
    })
    return
  }

  if (goodsDbLoadingModal.value.show) return

  try {
    await fetchAndSyncHangHoaCatalogWithProgress()

    goodsDbLoadingModal.value.percent = 90
    goodsDbLoadingModal.value.stepTitle = 'Đang đối chiếu hàng hóa của PO với Database...'
    goodsDbLoadingModal.value.stepDetail = `Đang kiểm tra ${item.goodsList.length} dòng hàng hóa trong PO...`
    await new Promise(resolve => setTimeout(resolve, 25))

    let detectedUsdRate = hangHoaCatalogAttrStats.value.defaultUsdRate || 25500
    const syncRows: PoGoodsDbSyncRow[] = []

    item.goodsList.forEach((g: any, idx: number) => {
      const rawTen = String(g.ten || '').trim()
      const rawMa = String(g.maHang || '').trim()
      if (!rawTen && !rawMa) return

      const match = matchPoGoodsRowWithDb(g)
      const dbItem = match.dbItem
      const isUsdDb = dbItem && String(dbItem.don_vi_tien_te || 'VND').toUpperCase() === 'USD'
      const dbRate = dbItem && toNum(dbItem.ti_gia) > 1 ? toNum(dbItem.ti_gia) : 1
      if (dbRate > 1000) {
        detectedUsdRate = dbRate
      }

      const danhMuc = String(g.danhMuc || dbItem?.danh_muc || '').trim().toUpperCase()
      const dvt = String(g.dvt || dbItem?.dvt || 'Cái').trim()
      const vatPct = toNum(g.vatPct !== undefined && g.vatPct !== '' ? g.vatPct : (dbItem?.thue_vat ?? 0))
      const maHang = dbItem?.ma_hang || rawMa || genHangHoaCode(danhMuc, rawTen)

      const savedCalc = g._lastSyncCalc || null
      const donGiaFileVnd = Math.round(toNum(g.donGia))
      const chenhLechVnd = savedCalc ? toNum(savedCalc.chenhLechVnd) : 0
      const giaNhapVnd = savedCalc
        ? toNum(savedCalc.giaNhapVnd)
        : (match.dbGiaNhapVnd > 0 ? match.dbGiaNhapVnd : 0)
      const offType: 'pct' | 'amount' = savedCalc?.offType === 'amount' ? 'amount' : 'pct'
      const offPct = savedCalc ? toNum(savedCalc.offPct) : 0
      const offAmountVnd = savedCalc ? toNum(savedCalc.offAmountVnd) : 0
      const hasCustomCalc = chenhLechVnd !== 0 || offPct !== 0 || offAmountVnd !== 0
      const priceMode: 'file' | 'calc' = savedCalc?.priceMode || (hasCustomCalc ? 'calc' : 'file')
      const currency: 'VND' | 'USD' = savedCalc?.currency || (isUsdDb ? 'USD' : 'VND')
      const tiGia = savedCalc?.tiGia
        ? toNum(savedCalc.tiGia)
        : (currency === 'USD' ? (dbRate > 1 ? dbRate : detectedUsdRate) : 1)

      const status: 'new' | 'diff' | 'matched' =
        match.status === 'new' || match.status === 'diff' || match.status === 'matched'
          ? match.status
          : 'new'

      syncRows.push({
        goodsIdx: idx,
        selected: focusRowIdx !== undefined ? idx === focusRowIdx : (status === 'new' || status === 'diff'),
        status,
        dbItem,
        maHang,
        maHangEdited: Boolean(dbItem?.ma_hang || rawMa),
        tenHang: rawTen,
        danhMuc,
        dvt,
        vatPct,
        dienGiai: String(g.dienGiai || dbItem?.features || '').trim(),
        donGiaFileVnd,
        chenhLechVnd,
        giaNhapVnd,
        offType,
        offPct,
        offAmountVnd,
        priceMode,
        currency,
        tiGia
      })
    })

    // Tự động nhận diện Nhà cung cấp nếu PO chưa có NCC
    if (!item.productType && hangHoaCatalogList.value.length > 0) {
      crossReferenceFinancialsForImportedQuote(item)
    }

    goodsDbLoadingModal.value.percent = 100
    goodsDbLoadingModal.value.stepTitle = 'Hoàn tất đồng bộ danh mục!'
    await new Promise(resolve => setTimeout(resolve, 110))
    goodsDbLoadingModal.value.show = false

    poGoodsDbSyncModal.value = {
      show: true,
      saving: false,
      targetItem: item,
      filterTab: 'all',
      bulkCurrency: syncRows.some(r => r.currency === 'USD') ? 'USD' : 'VND',
      bulkTiGia: detectedUsdRate,
      rows: syncRows,
      pickerRowIdx: null,
      pickerSearch: '',
      attrPickerRowIdx: null,
      attrPickerType: null,
      attrPickerSearch: ''
    }
  } finally {
    goodsDbLoadingModal.value.show = false
  }
}

const poGoodsDbSyncStats = computed(() => {
  const list = poGoodsDbSyncModal.value.rows || []
  let newCount = 0
  let diffCount = 0
  let matchedCount = 0
  let selectedCount = 0
  let selectedNewCount = 0
  let selectedUpdateCount = 0

  for (const r of list) {
    if (r.selected) {
      selectedCount++
      if (!r.dbItem) selectedNewCount++
      else selectedUpdateCount++
    }
    if (!r.dbItem) newCount++
    else if (r.status === 'diff') diffCount++
    else matchedCount++
  }

  return {
    total: list.length,
    newCount,
    diffCount,
    matchedCount,
    selectedCount,
    selectedNewCount,
    selectedUpdateCount
  }
})

const filteredPoGoodsDbSyncRows = computed(() => {
  const list = poGoodsDbSyncModal.value.rows || []
  const tab = poGoodsDbSyncModal.value.filterTab
  return list.filter(r => {
    if (tab === 'new') return !r.dbItem
    if (tab === 'diff') return Boolean(r.dbItem && r.status === 'diff')
    if (tab === 'matched') return Boolean(r.dbItem && r.status === 'matched')
    return true
  })
})

function toggleAllPoGoodsDbSyncSelect(val: boolean) {
  filteredPoGoodsDbSyncRows.value.forEach(r => {
    r.selected = val
  })
}

function selectPoGoodsDbSyncByStatus(mode: 'need_action' | 'new_only') {
  poGoodsDbSyncModal.value.rows.forEach(r => {
    if (mode === 'new_only') {
      r.selected = !r.dbItem
    } else {
      r.selected = !r.dbItem || r.status === 'diff'
    }
  })
}

function onSyncRowNameOrCatInput(r: PoGoodsDbSyncRow) {
  r.danhMuc = String(r.danhMuc || '').toUpperCase()
  if (!r.maHangEdited && !r.dbItem) {
    r.maHang = genHangHoaCode(r.danhMuc, r.tenHang)
  }
}

function onSyncRowValueChange(
  r: PoGoodsDbSyncRow,
  field: 'donGiaFileVnd' | 'chenhLechVnd' | 'giaNhapVnd' | 'offAmountVnd' | 'tiGia',
  val: number
) {
  const num = field === 'chenhLechVnd' ? Math.round(Number(val) || 0) : Math.max(0, Math.round(Number(val) || 0))
  if (Math.round(Number(r[field]) || 0) === num) return
  r[field] = num
  if (
    (field === 'chenhLechVnd' || field === 'giaNhapVnd' || field === 'offAmountVnd') &&
    (r.chenhLechVnd !== 0 || r.giaNhapVnd !== 0 || r.offPct !== 0 || r.offAmountVnd !== 0)
  ) {
    r.priceMode = 'calc'
  }
}

function onSyncRowOffPctChange(r: PoGoodsDbSyncRow, val: number) {
  const num = Math.min(99.99, Math.max(0, Number(val) || 0))
  if (Math.abs((Number(r.offPct) || 0) - num) < 1e-6) return
  r.offPct = num
  if (num > 0 || r.chenhLechVnd !== 0) {
    r.priceMode = 'calc'
  }
}

function onFinancialValueChange(
  item: ImportItem,
  field: 'doanhSoBan' | 'giaMua' | 'tongCP' | 'netCom' | 'grossCom' | 'taxPct' | 'soTienDaThanhToan',
  val: number,
  triggerCalc = true
) {
  const nextVal = field === 'taxPct' ? Math.max(0, Number(val) || 0) : Math.round(Number(val) || 0)
  const prevVal = Number((item as any)[field]) || 0
  if (Math.abs(prevVal - nextVal) < 1e-6) return
  ;(item as any)[field] = nextVal
  isModalDirty.value = true
  if (triggerCalc) {
    onFinancialInput(item, field as any)
  }
}

function onSyncRowMoneyInput(e: Event, r: PoGoodsDbSyncRow, field: 'donGiaFileVnd' | 'chenhLechVnd' | 'giaNhapVnd' | 'offAmountVnd' | 'tiGia') {
  const target = e.target as HTMLInputElement
  const raw = String(target.value || '').replace(/[^0-9-]/g, '')
  const isNeg = field === 'chenhLechVnd' && raw.startsWith('-')
  const digits = raw.replace(/-/g, '')
  let num = digits ? Number(digits) : 0
  if (isNeg) num = -num
  r[field] = num
  if (raw === '' || (isNeg && digits === '')) {
    target.value = raw
  } else {
    target.value = num.toLocaleString('vi-VN')
  }
  if (
    (field === 'chenhLechVnd' || field === 'giaNhapVnd' || field === 'offAmountVnd') &&
    (r.chenhLechVnd !== 0 || r.giaNhapVnd !== 0 || r.offPct !== 0 || r.offAmountVnd !== 0)
  ) {
    r.priceMode = 'calc'
  }
}

function onSyncRowOffPctInput(e: Event, r: PoGoodsDbSyncRow) {
  const target = e.target as HTMLInputElement
  const cleaned = String(target.value || '').replace(/[^0-9.,]/g, '').replace(',', '.')
  const num = Math.min(99.99, Math.max(0, parseFloat(cleaned) || 0))
  r.offPct = num
  if (num > 0 || r.chenhLechVnd !== 0) {
    r.priceMode = 'calc'
  }
}

function onSyncRowOffTypeChange(r: PoGoodsDbSyncRow, mode: 'pct' | 'amount') {
  r.offType = mode
  if ((mode === 'pct' && r.offPct > 0) || (mode === 'amount' && r.offAmountVnd > 0)) {
    r.priceMode = 'calc'
  }
}

function onSyncRowCurrencyChange(r: PoGoodsDbSyncRow, newCur: 'VND' | 'USD') {
  r.currency = newCur
  if (newCur === 'USD') {
    if (!r.tiGia || r.tiGia <= 1) {
      const dbRate = r.dbItem && toNum(r.dbItem.ti_gia) > 1
        ? toNum(r.dbItem.ti_gia)
        : (hangHoaCatalogAttrStats.value.defaultUsdRate || 25500)
      r.tiGia = dbRate
    }
  } else {
    r.tiGia = 1
  }
}

function openSyncAttrPicker(rowIdx: number, type: 'danh_muc' | 'dvt' | 'ti_gia') {
  poGoodsDbSyncModal.value.attrPickerRowIdx = rowIdx
  poGoodsDbSyncModal.value.attrPickerType = type
  poGoodsDbSyncModal.value.attrPickerSearch = ''
}

function closeSyncAttrPicker() {
  poGoodsDbSyncModal.value.attrPickerRowIdx = null
  poGoodsDbSyncModal.value.attrPickerType = null
  poGoodsDbSyncModal.value.attrPickerSearch = ''
}

const filteredSyncAttrPickerOptions = computed(() => {
  const type = poGoodsDbSyncModal.value.attrPickerType
  const q = normalizeGoodsMatchStr(poGoodsDbSyncModal.value.attrPickerSearch)
  const stats = hangHoaCatalogAttrStats.value
  const baseList =
    type === 'danh_muc'
      ? stats.danhMucOptions
      : type === 'dvt'
        ? stats.dvtOptions
        : type === 'ti_gia'
          ? stats.tiGiaOptions
          : []
  if (!q) return baseList
  return baseList.filter(item => normalizeGoodsMatchStr(item.label).includes(q))
})

function selectSyncAttrPickerOption(val: string | number) {
  const modal = poGoodsDbSyncModal.value
  const targetRow = modal.rows.find(x => x.goodsIdx === modal.attrPickerRowIdx)
  if (targetRow) {
    if (modal.attrPickerType === 'danh_muc') {
      targetRow.danhMuc = String(val || '').toUpperCase()
      onSyncRowNameOrCatInput(targetRow)
    } else if (modal.attrPickerType === 'dvt') {
      targetRow.dvt = String(val || '')
    } else if (modal.attrPickerType === 'ti_gia') {
      targetRow.tiGia = Math.max(1, toNum(val))
    }
  }
  closeSyncAttrPicker()
}

function openSyncRowDbProductPicker(rowIdx: number) {
  poGoodsDbSyncModal.value.pickerRowIdx = rowIdx
  poGoodsDbSyncModal.value.pickerSearch = ''
}

const filteredSyncDbPickerCatalog = computed(() => {
  const q = normalizeGoodsMatchStr(poGoodsDbSyncModal.value.pickerSearch)
  const enriched = hangHoaLookupIndex.value.enriched || []
  if (!q) return enriched.slice(0, 60).map(e => e.raw)
  return enriched
    .filter(e => e.searchHay.includes(q))
    .slice(0, 60)
    .map(e => e.raw)
})

function linkSyncRowToDbProduct(r: PoGoodsDbSyncRow, dbProd: any | null) {
  const targetItem = poGoodsDbSyncModal.value.targetItem
  const g = targetItem?.goodsList?.[r.goodsIdx]
  if (!dbProd) {
    r.dbItem = null
    r.status = 'new'
    r.maHangEdited = false
    r.maHang = genHangHoaCode(r.danhMuc, r.tenHang)
    r.selected = true
    if (g) g._linkedDbKey = '__NEW__'
    poGoodsDbSyncModal.value.pickerRowIdx = null
    return
  }

  r.dbItem = dbProd
  r.maHang = dbProd.ma_hang || r.maHang
  r.maHangEdited = true
  if (dbProd.danh_muc) r.danhMuc = String(dbProd.danh_muc).toUpperCase()
  if (dbProd.dvt) r.dvt = dbProd.dvt

  const isUsd = String(dbProd.don_vi_tien_te || 'VND').toUpperCase() === 'USD'
  const dbRate = toNum(dbProd.ti_gia) > 1 ? toNum(dbProd.ti_gia) : 1
  const dbDonGiaVnd = isUsd ? Math.round(toNum(dbProd.don_gia) * dbRate) : Math.round(toNum(dbProd.don_gia))
  const dbGiaNhapVnd = isUsd ? Math.round(toNum(dbProd.gia_nhap) * dbRate) : Math.round(toNum(dbProd.gia_nhap))

  if (r.giaNhapVnd === 0 && dbGiaNhapVnd > 0) {
    r.giaNhapVnd = dbGiaNhapVnd
  }
  if (isUsd) {
    r.currency = 'USD'
    r.tiGia = dbRate > 1 ? dbRate : (hangHoaCatalogAttrStats.value.defaultUsdRate || 25500)
  } else {
    r.currency = 'VND'
    r.tiGia = 1
  }

  r.status = Math.abs(r.donGiaFileVnd - dbDonGiaVnd) <= 10 ? 'matched' : 'diff'
  r.selected = true
  if (g) g._linkedDbKey = dbProd._firebaseKey || dbProd.ma_hang
  poGoodsDbSyncModal.value.pickerRowIdx = null
}

async function confirmSavePoGoodsToDatabase() {
  const modal = poGoodsDbSyncModal.value
  const targetItem = modal.targetItem
  if (!targetItem || modal.saving) return

  const selectedRows = modal.rows.filter(r => r.selected && String(r.tenHang || '').trim())
  if (selectedRows.length === 0) {
    await openSrAlert({
      variant: 'warning',
      title: 'Chưa chọn mặt hàng cần đồng bộ',
      message: 'Vui lòng tích chọn ít nhất 1 mặt hàng trong danh sách để Thêm mới hoặc Cập nhật vào Database (hang_hoa).',
      confirmText: 'Đã hiểu'
    })
    return
  }

  for (const r of selectedRows) {
    if (r.currency === 'USD' && (!r.tiGia || toNum(r.tiGia) <= 1)) {
      await openSrAlert({
        variant: 'warning',
        title: 'Tỉ giá USD chưa hợp lệ',
        highlightLabel: 'MẶT HÀNG CẦN KIỂM TRA',
        highlightValue: r.tenHang,
        message: `Vui lòng nhập Tỉ giá USD hợp lệ (lớn hơn 1) cho mặt hàng "${r.tenHang}" trước khi lưu vào Database.`,
        confirmText: 'Đã hiểu'
      })
      return
    }
  }

  modal.saving = true
  try {
    const nowIso = new Date().toISOString()
    const updates: Record<string, any> = {}
    let addedCount = 0
    let updatedCount = 0

    for (const r of selectedRows) {
      const cleanTen = String(r.tenHang || '').trim()
      const cleanDanhMuc = String(r.danhMuc || '').trim().toUpperCase()
      const cleanMa = String(r.maHang || '').trim() || genHangHoaCode(cleanDanhMuc, cleanTen)
      const cleanDvt = String(r.dvt || 'Cái').trim()
      const vatNum = Math.max(0, toNum(r.vatPct))
      const tenNcc = String(targetItem.productType || r.dbItem?.ten_ncc || '').trim()
      const maNcc = String(r.dbItem?.ma_ncc || cleanGoodsCodeSeg(tenNcc).replace(/-/g, '')).trim()

      const finalCurrency = r.currency === 'USD' ? 'USD' : 'VND'
      const finalTiGia = finalCurrency === 'USD' ? Math.max(1, toNum(r.tiGia)) : 1
      const finalDonGia = getSyncRowFinalDonGiaToSave(r)
      const finalGiaNhap = getSyncRowFinalGiaNhapToSave(r)

      let savedFbKey = ''

      if (r.dbItem && r.dbItem._firebaseKey) {
        savedFbKey = r.dbItem._firebaseKey
        const patchObj: Record<string, any> = {
          Ma_hang: cleanMa,
          Ten_hang: cleanTen,
          Danh_muc: cleanDanhMuc,
          DVT: cleanDvt,
          Don_gia: finalDonGia,
          Gia_tieu_chuan: finalDonGia,
          gia_nhap: finalGiaNhap,
          Don_vi_tien_te: finalCurrency,
          Ti_gia: finalTiGia,
          Thue_VAT: vatNum,
          muc_phan_tram_off: 0,
          'muc_%_off': 0,
          last_updated: nowIso
        }
        if (tenNcc) {
          patchObj.Ten_nha_cung_cap = tenNcc
          patchObj.Ma_nha_cung_cap = maNcc
        }
        if (r.dienGiai) {
          patchObj.Features = r.dienGiai
        }
        Object.entries(patchObj).forEach(([k, v]) => {
          updates[`hang_hoa/${savedFbKey}/${k}`] = v
        })

        // Cập nhật trực tiếp vào danh mục bộ nhớ
        r.dbItem.ma_hang = cleanMa
        r.dbItem.ten_hang = cleanTen
        r.dbItem.danh_muc = cleanDanhMuc
        r.dbItem.dvt = cleanDvt
        r.dbItem.don_gia = finalDonGia
        r.dbItem.gia_tieu_chuan = finalDonGia
        r.dbItem.gia_nhap = finalGiaNhap
        r.dbItem.don_vi_tien_te = finalCurrency
        r.dbItem.ti_gia = finalTiGia
        r.dbItem.thue_vat = vatNum
        r.dbItem.muc_phan_tram_off = 0
        if (tenNcc) {
          r.dbItem.ten_ncc = tenNcc
          r.dbItem.ma_ncc = maNcc
        }
        if (r.dienGiai) r.dbItem.features = r.dienGiai
        updatedCount++
      } else {
        const newRef = push(dbRef(database, 'hang_hoa'))
        savedFbKey = newRef.key || ('HH_' + Date.now() + '_' + Math.floor(Math.random() * 1000))
        const newItemObj = {
          Ma_hang: cleanMa,
          sku_code: '',
          Ten_hang: cleanTen,
          Main_img: '',
          Ma_nha_cung_cap: maNcc,
          Ten_nha_cung_cap: tenNcc,
          Mo_ta_chung: '',
          Mo_ta_chi_tiet: '',
          Features: String(r.dienGiai || '').trim(),
          Danh_muc: cleanDanhMuc,
          License_duration: '',
          DVT: cleanDvt,
          Gia_tieu_chuan: finalDonGia,
          Don_gia: finalDonGia,
          Trang_thai: 'Hiển thị',
          Don_vi_tien_te: finalCurrency,
          Ti_gia: finalTiGia,
          Thue_VAT: vatNum,
          Ma_hang_lien_ket: '',
          Ten_hang_lien_ket: '',
          Ghi_chu: '',
          gia_hardware: 0,
          gia_nhap: finalGiaNhap,
          'muc_%_off': 0,
          muc_phan_tram_off: 0,
          TYPE: '',
          Type: '',
          thoi_han_bao_hanh: '',
          volume: '',
          Description: '',
          danh_sach_file: [],
          last_updated: nowIso
        }
        updates[`hang_hoa/${savedFbKey}`] = newItemObj

        const newCatalogEntry = {
          _firebaseKey: savedFbKey,
          ma_hang: cleanMa,
          sku_code: '',
          ten_hang: cleanTen,
          danh_muc: cleanDanhMuc,
          dvt: cleanDvt,
          gia_tieu_chuan: finalDonGia,
          don_gia: finalDonGia,
          gia_nhap: finalGiaNhap,
          muc_phan_tram_off: 0,
          don_vi_tien_te: finalCurrency,
          ti_gia: finalTiGia,
          thue_vat: vatNum,
          features: String(r.dienGiai || '').trim(),
          description: '',
          ten_ncc: tenNcc,
          ma_ncc: maNcc
        }
        hangHoaCatalogList.value.push(newCatalogEntry)
        r.dbItem = newCatalogEntry
        addedCount++
      }

      // Đồng bộ lại thông tin định danh trên dòng hàng hóa của PO
      const g = targetItem.goodsList?.[r.goodsIdx]
      if (g) {
        g.maHang = cleanMa
        g.ten = cleanTen
        g.danhMuc = cleanDanhMuc
        g.dvt = cleanDvt
        g._linkedDbKey = savedFbKey
        g._syncedDbDone = true
        g._syncedFilePrice = Math.round(toNum(g.donGia))
        g._lastSyncCalc = {
          chenhLechVnd: r.chenhLechVnd,
          giaNhapVnd: r.giaNhapVnd,
          offType: r.offType,
          offPct: r.offPct,
          offAmountVnd: r.offAmountVnd,
          priceMode: r.priceMode,
          currency: finalCurrency,
          tiGia: finalTiGia
        }
      }
      r.status = 'matched'
      r.selected = false
    }

    if (Object.keys(updates).length > 0) {
      const cleanUpdates = JSON.parse(JSON.stringify(updates))
    await update(dbRef(database), cleanUpdates)
    }

    hangHoaCatalogVersion.value++
    hangHoaCatalogLoaded.value = true
    writeHangHoaCacheToIdb(hangHoaCatalogList.value, hangHoaNccList.value).catch(() => {})
    isModalDirty.value = true
    modal.show = false
    await openSrAlert({
      variant: 'success',
      eyebrow: 'Đồng bộ Database hoàn tất',
      title: 'Đồng bộ hàng hóa thành công',
      highlightLabel: 'KẾT QUẢ LƯU VÀO BẢNG HANG_HOA',
      highlightValue: `Thêm mới: ${addedCount} SP • Cập nhật: ${updatedCount} SP`,
      message: `Đã đồng bộ thành công dữ liệu hàng hóa của PO vào bảng hang_hoa:\n• Thêm mới: ${addedCount} mặt hàng\n• Cập nhật: ${updatedCount} mặt hàng`,
      confirmText: 'Hoàn tất'
    })
  } catch (err: any) {
    console.error('Lỗi đồng bộ hàng hóa vào Database:', err)
    await openSrAlert({
      variant: 'error',
      title: 'Lỗi đồng bộ Database (hang_hoa)',
      message: 'Không thể lưu dữ liệu vào bảng hang_hoa: ' + (err?.message || err),
      confirmText: 'Đóng'
    })
  } finally {
    modal.saving = false
  }
}

function handleInputThueTruoc() {
  return '';
}

function fmtInput(val: number) {
  if (!val) return '';
  return val.toLocaleString('vi-VN');
}

function formatNumberInput(e: Event, item: ImportItem, field: keyof ImportItem, triggerCalc = true) {
  const target = e.target as HTMLInputElement;
  const ie = e as InputEvent;
  if (ie.inputType === 'insertFromPaste' || ie.inputType === 'insertFromDrop') {
    const numericVal = parsePastedNumber(target.value, 0, true);
    (item as any)[field] = numericVal;
    target.value = numericVal !== 0 ? numericVal.toLocaleString('vi-VN') : '';
    if (triggerCalc) {
      onFinancialInput(item, field);
    }
    return;
  }
  const raw = target.value.replace(/[^0-9-]/g, '');
  const isNegative = raw.startsWith('-');
  const digits = raw.replace(/-/g, '');
  let numericVal = digits ? Number(digits) : 0;
  if (isNegative) numericVal = -numericVal;
  
  (item as any)[field] = numericVal;
  
  if (raw === '' || raw === '-') {
    target.value = raw;
  } else {
    target.value = numericVal.toLocaleString('vi-VN');
  }
  if (triggerCalc) {
    onFinancialInput(item, field);
  }
}

function onFinancialPaste(e: ClipboardEvent, item: ImportItem, field: keyof ImportItem, triggerCalc = true) {
  e.preventDefault();
  const target = e.target as HTMLInputElement;
  const pasted = e.clipboardData?.getData('text') ?? '';
  if (!pasted) return;
  const numericVal = parsePastedNumber(pasted, 0, true);
  (item as any)[field] = numericVal;
  target.value = numericVal !== 0 ? numericVal.toLocaleString('vi-VN') : '';
  if (triggerCalc) {
    onFinancialInput(item, field);
  }
}

function applyPredictPctValue(item: ImportItem, rawStr: string) {
  item.predictPct = rawStr

  if (rawStr === '') {
    if (item._origGross !== undefined) item.grossCom = item._origGross
    if (item._origNet !== undefined) item.netCom = item._origNet
    item._origGross = undefined
    item._origNet = undefined
    return
  }

  const normalized = rawStr.replace(/,/g, '.')
  if (normalized === '-' || normalized === '.' || normalized === '-.') return
  const desiredPct = Number(normalized)
  if (isNaN(desiredPct)) return

  if (item._origGross === undefined) {
    item._origGross = item.grossCom
    item._origNet = item.netCom
  }

  const pct = desiredPct / 100
  const tax = (Number(item.taxPct) || 0) / 100
  const dsb = item.doanhSoBan || 0
  const tcp = item.tongCP || 0

  const targetNetMargin = dsb * pct
  const requiredGrossCom = Math.round(dsb - tcp - targetNetMargin)
  const requiredNetCom = Math.round(requiredGrossCom * (1 - tax))

  item.grossCom = requiredGrossCom
  item.netCom = requiredNetCom
  isModalDirty.value = true
}

function resetPredictPct(item: ImportItem) {
  applyPredictPctValue(item, '')
}

function onPredictInput(e: Event, item: ImportItem) {
  const target = e.target as HTMLInputElement
  const ie = e as InputEvent
  if (ie.inputType === 'insertFromPaste' || ie.inputType === 'insertFromDrop') {
    const pastedVal = parsePastedNumber(target.value, 2, true)
    const cleanStr = target.value.trim() === '' ? '' : String(pastedVal)
    target.value = cleanStr
    applyPredictPctValue(item, cleanStr)
    return
  }
  const cleaned = target.value.replace(/[^0-9.,-]/g, '')
  if (target.value !== cleaned) {
    target.value = cleaned
  }
  applyPredictPctValue(item, cleaned)
}

function onPredictPaste(e: ClipboardEvent, item: ImportItem) {
  e.preventDefault()
  const target = e.target as HTMLInputElement
  const pasted = e.clipboardData?.getData('text') ?? ''
  if (!pasted.trim()) return
  const numericVal = parsePastedNumber(pasted, 2, true)
  const cleanStr = String(numericVal)
  target.value = cleanStr
  applyPredictPctValue(item, cleanStr)
}

