        }

        // Đồng bộ / tạo mới khách hàng vào khach_hang (Giữ cố định 100% ma_khach_hang & ma_cong_ty nếu đã có)
        const {
          maKHGen,
          maCongTyGen,
          tenCongTy,
          tenKhachHang,
          mstVal
        } = await upsertCustomerFromModalItem(item);

        const tTruoc = Number(item.doanhSoBan ?? item.goodsTotal?.ttTruoc ?? 0);
        const tVat = Number(item.goodsTotal?.vat ?? toNum(item.row?.Tong_thueVAT) ?? 0);
        const tSau = tTruoc + tVat;
        if (item.goodsTotal) {
          item.goodsTotal = { ...item.goodsTotal, ttTruoc: tTruoc, vat: tVat, ttSau: tSau };
        }

        const currentPaid = daThanhToan(item.row);
        const updatedCongNo = Math.max(0, tSau - currentPaid);
        const currentPayTime = item.row?.thoi_gian_thanh_toan || '';

        // ─── Build update payload for Firebase ───
        const updatePayload: Record<string, any> = {
            ma_hop_dong: maHD,
            so_hop_dong: soHD,
            So_PO: item.soPO,
            created_time: finalCreatedTime,
            Ma_khach_hang: maKHGen,
            Ten_khach_hang: tenKhachHang || tenCongTy,
            Ma_cong_ty: maCongTyGen,
            Ten_cong_ty: tenCongTy,
            MST: mstVal,
            account_manager_name: item.am,
            Ten_nha_cung_cap: item.productType,
            Tong_tien_truoc_thueVAT: tTruoc,
            Tong_thueVAT: tVat,
            Tong_tien_sau_thueVAT: tSau,
            so_tien_da_thanh_toan: currentPaid,
            cong_no: updatedCongNo,
            thoi_gian_thanh_toan: currentPayTime,
            Tong_thanh_tien_chua_VAT_mua_hang: item.giaMua,
            Tong_CP_don_hang: item.tongCP,
            chiet_khau_tong_truoc_thue: Number(item.grossCom) || 0,
            chenh_lech_gia: Number(item.grossCom) || 0,
            gross_com: Number(item.grossCom) || 0,
            phan_tram_thue_chenh_lech_gia: Number(item.taxPct) || 0,
            thue_chenh_lech_gia: (Number(item.grossCom) || 0) * ((Number(item.taxPct) || 0) / 100),
            con_lai: Number(item.netCom) || 0,
            tong_chiet_khau: Number(item.netCom) || 0,
            net_com: Number(item.netCom) || 0,
            content_of_contract_PO: item.content,
            ghi_chu: item.ghiChu ?? item.row?.ghi_chu ?? '',
            danh_sach_file_khac: savedOtherFiles
        };
        if (uploadedUrl) updatePayload.img_save = uploadedUrl;
        if (linkBG) { updatePayload.link_excel_bao_gia = linkBG; updatePayload.ten_file_bao_gia = tenBG; }
        if (linkMH) { updatePayload.link_excel_mua_hang = linkMH; updatePayload.ten_file_mua_hang = tenMH; }
        if (linkDXMH) { updatePayload.link_excel_dxmh = linkDXMH; updatePayload.ten_file_dxmh = tenDXMH; }

        // ─── Update sale_report in Firebase ───
        const firebaseKey = item.row._firebaseKey || item.row.ID;
        if (firebaseKey) {
          await update(dbRef(database, `sale_report/${firebaseKey}`), updatePayload);
        }

        // ─── Update hop_dong_tong_quat in Firebase ───
        const hdTongData = {
          ma_hop_dong: maHD,
          so_hop_dong: soHD,
          ma_khach_hang: maKHGen,
          ten_khach_hang: tenKhachHang || tenCongTy,
          ngay_tao: formatNgayTaoHopDong(),
          tong_truoc_vat: tTruoc,
          tong_vat: tVat,
          tong_sau_vat: tSau,
          da_thanh_toan: currentPaid,
          con_phai_thu: updatedCongNo,
          trang_thai_thanh_toan: updatedCongNo <= 0 ? 'Đã thanh toán đủ' : (currentPaid > 0 ? 'Thanh toán 1 phần' : 'Chưa thanh toán đủ'),
          loai_hop_dong: 'Chính thức',
          content: item.content || '',
          don_vi_tien_te: 'VND',
          ti_gia: 1,
          ghi_chu: '',
          tong_truoc_vat_goc: tTruoc,
          ngay_tao_date: formatCreatedTimeDateOnly(),
          so_po: item.soPO || '',
          po_content: '',
          content_po: item.content || '',
          gross_com: item.grossCom || 0,
          chenh_lech_gia: item.grossCom || 0,
          chiet_khau_tong_truoc_thue: item.grossCom || 0,
          phan_tram_chiet_khau: 0,
          thue_chenh_lech_gia: (item.grossCom * (item.taxPct / 100)) || 0,
          phan_tram_thue: item.taxPct || 0,
          phan_tram_thue_chenh_lech_gia: item.taxPct || 0,
          tong_chiet_khau: item.netCom || 0,
          con_lai: item.netCom || 0,
          tong_cp: item.tongCP || 0
        };
        await update(dbRef(database, `hop_dong_tong_quat/${maHD}`), hdTongData);

        // ─── Update hop_dong_chi_tiet in Firebase ───
        let hdChiTietRows: any[] = [];
        if (item.goodsList && item.goodsList.length > 0) {
          hdChiTietRows = item.goodsList.map(g => ({
            ma_hop_dong: maHD,
            so_hop_dong: soHD,
            ma_hang: g.maHang || '',
            ten_hang: g.ten || '',
            main_img: '',
            ma_ncc: '',
            ten_ncc: item.productType || '',
            mo_ta_chung: '',
            mo_ta_chi_tiet: '',
            dien_giai: g.dienGiai || '',
            danh_muc: g.danhMuc || '',
            ghi_chu: '',
            dvt: g.dvt || '',
            don_gia: g.donGia || 0,
            gia_tieu_chuan: g.donGia || 0,
            don_vi_tien_te: 'VND',
            ti_gia: 1,
            thue_vat: g.vatPct || 0,
            so_luong: g.sl || 1,
            features: '',
            gia_hardware: 0,
            gia_nhap: 0,
            muc_phan_tram_off: 0
          }));
        } else {
          hdChiTietRows = [{
            ma_hop_dong: maHD,
            so_hop_dong: soHD,
            ma_hang: '',
            ten_hang: 'Hàng hóa mặc định',
            main_img: '',
            ma_ncc: '',
            ten_ncc: item.productType || '',
            mo_ta_chung: '',
            mo_ta_chi_tiet: '',
            dien_giai: item.content || '',
            danh_muc: '',
            ghi_chu: '',
            dvt: 'Cái',
            don_gia: tTruoc,
            gia_tieu_chuan: tTruoc,
            don_vi_tien_te: 'VND',
            ti_gia: 1,
            thue_vat: 0,
            so_luong: 1,
            features: '',
            gia_hardware: 0,
            gia_nhap: 0,
            muc_phan_tram_off: 0
          }];
        }

        // Remove old chi tiet entries for this contract and add new ones
        const chiTietUpdates: Record<string, any> = {};
        if (maHD && hdChiTietRawMap.value && typeof hdChiTietRawMap.value === 'object') {
          Object.entries(hdChiTietRawMap.value).forEach(([ctKey, ctVal]: [string, any]) => {
            const entryMaHD = Array.isArray(ctVal)
              ? String(ctVal[0] || '').trim()
              : String(ctVal?.ma_hop_dong ?? ctVal?.Ma_hop_dong ?? '').trim();
            if (entryMaHD === maHD) {
              chiTietUpdates[`hop_dong_chi_tiet/${ctKey}`] = null;
              delete hdChiTietRawMap.value[ctKey];
            }
          });
        }
        for (const ct of hdChiTietRows) {
          const newCtKey = push(dbRef(database, 'hop_dong_chi_tiet')).key;
          if (newCtKey) {
            chiTietUpdates[`hop_dong_chi_tiet/${newCtKey}`] = ct;
            hdChiTietRawMap.value[newCtKey] = ct;
          }
        }
        if (Object.keys(chiTietUpdates).length > 0) {
          await update(dbRef(database), chiTietUpdates);
        }
        rebuildHdChiTietDataArray();

        // ─── Update local state ───
        item.row.So_PO = item.soPO
        item.row.created_time = finalCreatedTime
        item.row.content_of_contract_PO = item.content
        item.row.ghi_chu = item.ghiChu ?? item.row.ghi_chu ?? ''
        item.row.MST = mstVal
        item.row.Ma_khach_hang = maKHGen
        item.row.Ten_khach_hang = tenKhachHang || tenCongTy
        item.row.Ma_cong_ty = maCongTyGen
        item.row.Ten_cong_ty = tenCongTy
        item.row.account_manager_name = item.am
        item.row.Ten_nha_cung_cap = item.productType
        item.row.Tong_tien_truoc_thueVAT = tTruoc
        item.row.Tong_thueVAT = tVat
        item.row.Tong_tien_sau_thueVAT = tSau
        item.row.so_tien_da_thanh_toan = currentPaid
        item.row.cong_no = updatedCongNo
        item.row.thoi_gian_thanh_toan = currentPayTime
        item.row.Tong_thanh_tien_chua_VAT_mua_hang = item.giaMua
        item.row.Tong_CP_don_hang = item.tongCP
        item.row.chiet_khau_tong_truoc_thue = Number(item.grossCom) || 0
        item.row.chenh_lech_gia = Number(item.grossCom) || 0
        item.row.gross_com = Number(item.grossCom) || 0
        item.row.grossCom = Number(item.grossCom) || 0
        item.row.phan_tram_thue_chenh_lech_gia = Number(item.taxPct) || 0
        item.row.thue_chenh_lech_gia = (Number(item.grossCom) || 0) * ((Number(item.taxPct) || 0) / 100)
        item.row.con_lai = Number(item.netCom) || 0
        item.row.tong_chiet_khau = Number(item.netCom) || 0
        item.row.net_com = Number(item.netCom) || 0
        item.row.netCom = Number(item.netCom) || 0
        item.row.danh_sach_file_khac = savedOtherFiles
        if (uploadedUrl) {
          item.row.img_save = uploadedUrl
        }
        if (linkBG) {
          item.row.link_excel_bao_gia = linkBG
          item.row.ten_file_bao_gia = tenBG
        }
        if (linkMH) {
          item.row.link_excel_mua_hang = linkMH
          item.row.ten_file_mua_hang = tenMH
        }
        if (linkDXMH) {
          item.row.link_excel_dxmh = linkDXMH
          item.row.ten_file_dxmh = tenDXMH
        }
      }
      await syncAllCustomersCongNo()
    }
    const createdOrUpdatedMode = m.mode
    const poLabels = validItems
      .map(i => (i.soPO ? `PO ${i.soPO}` : i.row?.So_PO ? `PO ${i.row.So_PO}` : i.content))
      .filter(Boolean)
      .join(', ')
    isModalDirty.value = false
    wasPreDirtyOnOpen.value = false
    initialPoModalSnapshot.value = ''
    showUnsavedPoCloseModal.value = false
    m.show = false
    if (createdOrUpdatedMode === 'create') {
      await openSrAlert({
        variant: 'success',
        eyebrow: 'Khởi tạo hoàn tất',
        title: 'Khởi tạo đơn hàng PO thành công',
        highlightLabel: validItems.length > 1 ? 'DANH SÁCH ĐƠN HÀNG ĐÃ TẠO' : 'ĐƠN HÀNG PO MỚI',
        highlightValue:
          validItems.length > 1
            ? `${validItems.length} đơn hàng PO (${poLabels})`
            : poLabels || '1 đơn hàng PO',
        message: `Đã khởi tạo và lưu thành công ${validItems.length} đơn hàng PO vào hệ thống.`,
        confirmText: 'Hoàn tất'
      })
    } else {
      await openSrAlert({
        variant: 'success',
        eyebrow: 'Cập nhật hoàn tất',
        title: 'Sửa đơn hàng PO thành công',
        highlightLabel: validItems.length > 1 ? 'DANH SÁCH ĐƠN HÀNG ĐÃ SỬA' : 'ĐƠN HÀNG PO ĐÃ CẬP NHẬT',
        highlightValue:
          validItems.length > 1
            ? `${validItems.length} đơn hàng PO (${poLabels})`
            : poLabels || '1 đơn hàng PO',
        message: 'Mọi thay đổi về chỉ số tài chính, khách hàng, chứng từ và bảng hàng hóa của PO đã được lưu thành công.',
        confirmText: 'Hoàn tất'
      })
    }
  } catch (e) {
    console.error('Lỗi update:', e)
    await openSrAlert({
      variant: 'error',
      title: 'Lỗi lưu dữ liệu PO',
      message: 'Đã xảy ra lỗi khi lưu thông tin PO lên hệ thống. Vui lòng thử lại.',
      confirmText: 'Đóng'
    })
  } finally {
    savingModal.value = false
  }
}

async function deletePO(item: ImportItem, idx: number) {
  if ((multiEditModal.value.mode === 'create' || srDataMode.value === 'craft') && !item.row) {
    if (multiEditModal.value.items.length > 1) {
      multiEditModal.value.items.splice(idx, 1)
      if (activeItemIdx.value >= multiEditModal.value.items.length) {
        activeItemIdx.value = Math.max(0, multiEditModal.value.items.length - 1)
      }
      return
    }
    multiEditModal.value.show = false
    return
  }
  const isCraftItem = Boolean(srDataMode.value === 'craft' || item.row?._isCraft)
  const poName = item.row?.So_PO || item.content || 'này'
  const confirmed = await openSrConfirm({
    variant: 'danger',
    eyebrow: isCraftItem ? 'Xác nhận xóa Phương án tạm' : 'Xác nhận xóa đơn hàng',
    title: isCraftItem ? 'Xóa Phương án tạm (Bản Tạm)' : 'Xóa đơn hàng PO',
    highlightLabel: isCraftItem ? 'PHƯƠNG ÁN TẠM ĐANG CHỌN' : 'ĐƠN HÀNG PO ĐANG CHỌN',
    highlightValue: `${isCraftItem ? 'Phương án' : 'PO'} ${poName}${item.customer ? ' — ' + item.customer : ''}`,
    message: isCraftItem
      ? `Bạn có chắc chắn muốn xóa Phương án tạm ${poName} khỏi danh sách Bản Tạm?`
      : `Bạn có chắc chắn muốn xóa vĩnh viễn PO ${poName} khỏi hệ thống?`,
    subNote: isCraftItem
      ? 'Hành động này sẽ xóa phương án tạm này khỏi bảng sale_report_craft.'
      : 'Hành động này sẽ xóa PO cùng lịch sử thanh toán liên quan và không thể hoàn tác.',
    confirmText: isCraftItem ? 'Xóa phương án ngay' : 'Xóa PO ngay',
    cancelText: 'Hủy bỏ'
  })
  if (!confirmed) return
  try {
    const firebaseKey = item.row?._firebaseKey || item.row?.ID;
    const srId = item.row?.ID || firebaseKey;
    if (isCraftItem) {
      if (firebaseKey) {
        await remove(dbRef(database, `sale_report_craft/${firebaseKey}`));
      }
      selectedCraftCompareKeys.value = selectedCraftCompareKeys.value.filter(k => k !== String(firebaseKey));
      multiEditModal.value.items.splice(idx, 1)
      if (multiEditModal.value.items.length === 0) multiEditModal.value.show = false
      await loadData()
      await openSrAlert({
        variant: 'success',
        eyebrow: 'Xóa phương án tạm hoàn tất',
        title: 'Đã xóa Phương án tạm',
        highlightLabel: 'PHƯƠNG ÁN ĐÃ XÓA',
        highlightValue: `Phương án ${poName}${item.customer ? ' — ' + item.customer : ''}`,
        message: `Đã xóa Phương án tạm ${poName} khỏi danh sách Bản Tạm thành công.`,
        confirmText: 'Hoàn tất'
      })
      return
    }
    // ─── Delete from Firebase (Bản Chính Thức) ───
    if (firebaseKey) {
      await remove(dbRef(database, `sale_report/${firebaseKey}`));
    }
    // ─── Xóa lịch sử thanh toán liên quan tới PO này ───
    if (srId || firebaseKey) {
      const relatedHist = lichSuThanhToanList.value.filter(h =>
        (srId && String(h.id_salereport) === String(srId)) ||
        (firebaseKey && String(h.id_salereport) === String(firebaseKey))
      );
      for (const h of relatedHist) {
        const hk = h._firebaseKey || h.id;
        if (hk) await remove(dbRef(database, `lich_su_thanh_toan/${hk}`));
      }
    }
    // ─── Đồng bộ gỡ trạng thái Đã chốt deal bên Quản lý file & Sale Report Craft ───
    const fromCraft = item.row?.from_craft;
    if (fromCraft) {
      await update(dbRef(database, `sale_report_craft/${fromCraft}`), {
        chotDeal: false,
        id_sale_report: ''
      });
    }
    const idQuanLyFile = item.row?.id_quanlyfile || item.row?.id_quan_ly_file;
    if (idQuanLyFile) {
      const remainingSrKeys = (officialRows.value || [])
        .filter((r: any) => {
          const rKey = r?._firebaseKey || r?.ID
          if (!rKey || rKey === firebaseKey) return false
          return r?.id_quanlyfile === idQuanLyFile || r?.id_quan_ly_file === idQuanLyFile
        })
        .map((r: any) => r?._firebaseKey || r?.ID)
        .filter(Boolean)

      await update(dbRef(database, `quan_ly_file/${idQuanLyFile}`), {
        craft_chotDeal: remainingSrKeys.length > 0,
        id_sale_report: remainingSrKeys[0] || '',
        sale_report_ids: remainingSrKeys
      });
    }
    // Remove from modal
    multiEditModal.value.items.splice(idx, 1)
    if (multiEditModal.value.items.length === 0) multiEditModal.value.show = false
    // Reload data to refresh PO count, contract numbers, and sync khach_hang.cong_no
    await loadData()
    await openSrAlert({
      variant: 'success',
      eyebrow: 'Xóa đơn hàng hoàn tất',
      title: 'Xóa đơn hàng PO thành công',
      highlightLabel: 'ĐƠN HÀNG PO ĐÃ XÓA',
      highlightValue: `PO ${poName}${item.customer ? ' — ' + item.customer : ''}`,
      message: `Đã xóa vĩnh viễn PO ${poName} và đồng bộ lại dữ liệu công nợ, hợp đồng thành công.`,
      confirmText: 'Hoàn tất'
    })
  } catch (e) {
    console.error('Lỗi xóa PO:', e)
    await openSrAlert({
      variant: 'error',
      title: 'Lỗi xóa dữ liệu',
      message: 'Đã xảy ra lỗi khi xóa dữ liệu khỏi hệ thống. Vui lòng thử lại.',
      confirmText: 'Đóng'
    })
  }
}

// ════════════════════════════════════════════════════════════════════════════
// BẢN TẠM (SALE REPORT CRAFT) & BẢNG MA TRẬN SO SÁNH ĐA PHƯƠNG ÁN
// ════════════════════════════════════════════════════════════════════════════
const selectedPoKeyList = ref<string[]>([])
const selectedCraftCompareKeys = selectedPoKeyList
const showCraftCompareModal = ref(false)
const craftCompareLayout = ref<'columns' | 'rows'>('columns')
const craftCompareBaseline = ref<'first' | 'prev'>('first')
const craftCompareBaseRowKey = ref<string>('')
const craftCompareOnlyDiff = ref(false)
const craftCompareCompanyFilter = ref('')
const mindmapCompareCustomRows = ref<any[] | null>(null)

function switchSrDataMode(mode: 'official' | 'craft') {
  if (srDataMode.value === mode) return
  srDataMode.value = mode
  selectedPoKeyList.value = []
  selectedMasterGroupKey.value = ''
  if (mode === 'official') {
    showCraftCompareModal.value = false
  }
}

function thueVat(r: any): number {
  const v = toNum(r?.Tong_thueVAT)
  if (v > 0) return v
  const s = toNum(r?.Tong_tien_sau_thueVAT)
  const t = toNum(r?.Tong_tien_truoc_thueVAT)
  return s > t ? s - t : 0
}

function thueCom(r: any): number {
  return Math.round(thue(r))
}

function pct(num: number, den: number): string {
  if (!den || !Number.isFinite(den) || Math.abs(den) < 0.0001) return '0.00'
  const val = (Number(num || 0) / den) * 100
  return Number.isFinite(val) ? val.toFixed(2) : '0.00'
}

function getCraftCompareKey(r: any): string {
  return String(r?._firebaseKey || r?.ID || r?.So_PO || '').trim()
}

function isCraftSelectedForCompare(r: any): boolean {
  const k = getCraftCompareKey(r)
  return Boolean(k && selectedPoKeyList.value.includes(k))
}

function toggleCraftCompareRow(r: any) {
  const k = getCraftCompareKey(r)
  if (!k) return
  const idx = selectedPoKeyList.value.indexOf(k)
  if (idx >= 0) {
    selectedPoKeyList.value.splice(idx, 1)
  } else {
    selectedPoKeyList.value.push(k)
  }
}

function clearCraftCompareSelection() {
  selectedPoKeyList.value = []
}

function removeCraftRowFromCompare(r: any) {
  const k = getCraftCompareKey(r)
  if (!k) return
  selectedPoKeyList.value = selectedPoKeyList.value.filter(key => key !== k)
}

const selectedCraftCompareRows = computed<any[]>(() => {
  if (!selectedPoKeyList.value.length) return []
  const byKey = new Map<string, any>()
  rows.value.forEach(r => {
    const k = getCraftCompareKey(r)
    if (k) byKey.set(k, r)
  })
  return selectedPoKeyList.value.map(k => byKey.get(k)).filter(Boolean)
})

const craftCompanyGroupsForPicker = computed(() => {
  const map = new Map<string, { key: string; name: string; items: any[] }>()
  craftRows.value.forEach(r => {
    const key = String(r?.Ma_cong_ty || r?.Ten_cong_ty || 'Khác').trim()
    const name = String(r?.Ten_cong_ty || r?.Ten_khach_hang || 'Khác').trim()
    if (!map.has(key)) {
      map.set(key, { key, name, items: [] })
    }
    map.get(key)!.items.push(r)
  })
  return Array.from(map.values()).sort((a, b) => b.items.length - a.items.length)
})

function selectCraftCompareCompanyFilter(compKey: string) {
  craftCompareCompanyFilter.value = compKey
  if (!compKey) {
    selectedPoKeyList.value = []
    return
  }
  const group = craftCompanyGroupsForPicker.value.find(g => g.key === compKey)
  if (group) {
    selectedPoKeyList.value = group.items.map(r => getCraftCompareKey(r)).filter(Boolean)
  }
}

function getGroupMaxDoanhSoBan(g: any): number {
  if (!g || !Array.isArray(g.items) || !g.items.length) return 0
  return Math.max(0, ...g.items.map((r: any) => doanhSoBan(r)))
}

function getGroupMaxNetMargin(g: any): number {
  if (!g || !Array.isArray(g.items) || !g.items.length) return 0
  return Math.max(...g.items.map((r: any) => netMargin(r)))
}

const effectiveCraftCompareRows = computed<any[]>(() => {
  return [...selectedCraftCompareRows.value]
})

function openCraftCompareModal() {
  showCraftCompareModal.value = true
}

function openCraftCompareForCompany(group: any) {
  if (!group || !Array.isArray(group.items)) return
  craftCompareCompanyFilter.value = ''
  selectedPoKeyList.value = group.items.map((r: any) => getCraftCompareKey(r)).filter(Boolean)
  showCraftCompareModal.value = true
}

function openCraftCompareFromCard(r: any, _group?: any) {
  const k = getCraftCompareKey(r)
  if (k && !selectedPoKeyList.value.includes(k)) {
    selectedPoKeyList.value = [...selectedPoKeyList.value, k]
  }
  showCraftCompareModal.value = true
}

function openMultiEditModalFromCompare(r: any) {
  showCraftCompareModal.value = false
  openMultiEditModal(r)
}

function getCraftCompareColTitle(r: any, idx = 0): string {
  const content = String(r?.content_of_contract_PO || r?.content || '').trim()
  if (content) return content
  const soPo = String(r?.So_PO || '').trim()
  if (soPo) return soPo
  return `Phương án #${idx + 1}`
}

