  key: string
  label: string
  shortLabel?: string
  formula?: string
  sectionTitle?: string
  sectionGroup?: 'rev_cost' | 'com_tax_margin' | 'ratio'
  group: 'info' | 'rev' | 'cost' | 'com' | 'profit' | 'ratio'
  isNumeric: boolean
  isRatio?: boolean
  higherIsBetter?: boolean | null
  highlightRow?: boolean
  getNumeric: (r: any) => number
  format: (r: any) => string
}

