async function generateExcelOrPdfPreviewOnly(file: File): Promise<{ pUrl: string; pHtml: string }> {
  if (isImageDocFile(file) || isPdfDocFile(file)) {
    return { pUrl: URL.createObjectURL(file), pHtml: '' }
  }
  let pHtml = ''
  if (isWordDocFile(file)) {
    try {
      const wordDoc = await readUniversalWordDocument(file)
      const htmlParts: string[] = []
      if (wordDoc.paragraphs.length > 0) {
        htmlParts.push(
          '<div style="font-family: Calibri, sans-serif; font-size: 13px; color: #1e293b; padding: 12px 16px; line-height: 1.55;">' +
            wordDoc.paragraphs.slice(0, 40).map(p => `<p style="margin: 0 0 6px 0;">${escapeHtml(p)}</p>`).join('') +
            '</div>'
        )
      }
      if (wordDoc.tables.length > 0) {
        for (const tbl of wordDoc.tables) {
          const rowsHtml = tbl.rows
            .map(
              r =>
                '<tr>' +
                r
                  .map(
                    c =>
                      `<td style="border: 1px solid #cbd5e1; padding: 6px 10px; font-size: 12.5px; color: #1e293b;">${escapeHtml(
                        String(c || '')
                      )}</td>`
                  )
                  .join('') +
                '</tr>'
            )
            .join('')
          htmlParts.push(
            `<table class="preview-excel-table" style="border-collapse:collapse; font-family: 'Calibri', sans-serif; font-size: 13px; color: #1e293b; background: white; margin: 8px 12px; width: calc(100% - 24px);">${rowsHtml}</table>`
          )
        }
      }
      pHtml = htmlParts.join('')
    } catch (err) {
      console.warn('Could not build Word HTML preview:', err)
    }
  } else if (isSpreadsheetDocFile(file)) {
    try {
      const ab = await file.arrayBuffer()
      const wb = XLSX.read(ab, { type: 'array' })
      const sheetName = wb.SheetNames[0]
      if (sheetName && wb.Sheets[sheetName]) {
        pHtml = XLSX.utils.sheet_to_html(wb.Sheets[sheetName])
        pHtml = pHtml.replace(
          /<table/gi,
          '<table class="preview-excel-table" style="border-collapse:collapse; font-family: \'Calibri\', sans-serif; font-size: 13px; color: #1e293b; background: white; margin: 0;"'
        )
        pHtml = pHtml.replace(
          /<td/gi,
          '<td style="border: 1px solid #cbd5e1; padding: 6px 10px; white-space: nowrap; min-width: 60px; text-align: left; vertical-align: bottom;"'
        )
      }
    } catch (err) {
      console.warn('Could not build Excel HTML preview via XLSX, trying universal spreadsheet reader:', err)
    }
    if (!pHtml) {
      try {
        const sheets = await readUniversalSpreadsheetSheets(file)
        if (sheets.length > 0 && sheets[0].rows.length > 0) {
          const rowsHtml = sheets[0].rows
            .slice(0, 120)
            .map(
              r =>
                '<tr>' +
                r
                  .map(
                    c =>
                      `<td style="border: 1px solid #cbd5e1; padding: 6px 10px; white-space: nowrap; min-width: 60px; text-align: left; vertical-align: bottom;">${escapeHtml(
                        String(c || '')
                      )}</td>`
                  )
                  .join('') +
                '</tr>'
            )
            .join('')
          pHtml = `<table class="preview-excel-table" style="border-collapse:collapse; font-family: 'Calibri', sans-serif; font-size: 13px; color: #1e293b; background: white; margin: 0;">${rowsHtml}</table>`
        }
      } catch (err2) {
        console.warn('Could not build universal spreadsheet HTML preview:', err2)
      }
    }
  }
  const pUrl = await uploadFileToCloudinary(file)
  return { pUrl, pHtml }
}

