interface AiScanConfirmPayload {
  kind: 'bao_gia' | 'mua_hang' | 'dxmh'
  docLabel: string
  fileName: string
  doanhSoBan: number
  giaMua: number
  tongCP?: number
  soPO: string
  productType: string
  customer: string
  company?: string
  recipient: string
  mst: string
  phone?: string
  email?: string
  address?: string
  createdTime: string
  goodsList: any[]
}

const aiScanConfirmModal = ref<
  AiScanConfirmPayload & {
    show: boolean
    company: string
    tongCP: number
    phone: string
    email: string
    address: string
    resolver: ((confirmed: AiScanConfirmPayload | null) => void) | null
  }
>({
  show: false,
  kind: 'bao_gia',
  docLabel: 'File Báo Giá',
  fileName: '',
  doanhSoBan: 0,
  giaMua: 0,
  tongCP: 0,
  soPO: '',
  productType: '',
  customer: '',
  company: '',
  recipient: '',
  mst: '',
  phone: '',
  email: '',
  address: '',
  createdTime: '',
  goodsList: [],
  resolver: null
})

function openAiScanConfirmModal(payload: AiScanConfirmPayload): Promise<AiScanConfirmPayload | null> {
  return new Promise(resolve => {
    const companyVal = String(payload.company ?? payload.customer ?? '').trim()
    const giaMuaVal = Number(payload.giaMua) || 0
    aiScanConfirmModal.value = {
      ...payload,
      customer: companyVal,
      company: companyVal,
      tongCP: Number(payload.tongCP ?? giaMuaVal) || 0,
      phone: String(payload.phone || '').trim(),
      email: String(payload.email || '').trim(),
      address: String(payload.address || '').trim(),
      goodsList: Array.isArray(payload.goodsList) ? payload.goodsList.map(g => ({ ...g })) : [],
      show: true,
      resolver: resolve
    }
  })
}

function resolveAiScanConfirmModal(confirmed: boolean) {
  const m = aiScanConfirmModal.value
  const res = m.resolver
  m.show = false
  m.resolver = null
  if (!res) return
  if (!confirmed) {
    res(null)
    return
  }
  const finalCompany = String(m.company || m.customer || '').trim()
  res({
    kind: m.kind,
    docLabel: m.docLabel,
    fileName: m.fileName,
    doanhSoBan: Number(m.doanhSoBan) || 0,
    giaMua: Number(m.giaMua) || 0,
    tongCP: Number(m.tongCP || m.giaMua) || 0,
    soPO: String(m.soPO || '').trim(),
    productType: String(m.productType || '').trim(),
    customer: finalCompany,
    company: finalCompany,
    recipient: String(m.recipient || '').trim(),
    mst: String(m.mst || '').trim(),
    phone: String(m.phone || '').trim(),
    email: String(m.email || '').trim(),
    address: String(m.address || '').trim(),
    createdTime: String(m.createdTime || '').trim(),
    goodsList: Array.isArray(m.goodsList) ? m.goodsList.map(g => ({ ...g })) : []
  })
}

function onAiConfirmGoodsRowChange(g: any, field?: 'sl' | 'donGia', val?: number) {
  if (!g) return
  if (field && val !== undefined) {
    g[field] = Math.max(0, Number(val) || 0)
  }
  const sl = Number(g.sl) || 0
  const dg = Number(g.donGia) || 0
  g.ttTruoc = Math.round(sl * dg)
  const vatPctNum = parseFloat(String(g.vatPct || '0'))
  if (!isNaN(vatPctNum) && vatPctNum > 0) {
    g.vat = Math.round((g.ttTruoc * vatPctNum) / 100)
  } else {
    g.vat = Number(g.vat) || 0
  }
  g.vatStr = g.vat > 0 ? g.vat.toLocaleString('vi-VN') : ''
  g.ttSau = g.ttTruoc + (Number(g.vat) || 0)

  const list = aiScanConfirmModal.value.goodsList || []
  const sumSau = list.reduce((acc, row) => acc + (Number(row.ttSau) || Number(row.ttTruoc) || 0), 0)
  if (sumSau > 0) {
    if (aiScanConfirmModal.value.kind === 'bao_gia') {
      aiScanConfirmModal.value.doanhSoBan = sumSau
    } else if (aiScanConfirmModal.value.kind === 'mua_hang') {
      aiScanConfirmModal.value.giaMua = sumSau
      aiScanConfirmModal.value.tongCP = sumSau
    }
  }
}

async function analyzeDxmhFileWithAI(file: File, onProgress?: (msg: string) => void) {
  const prompt = `Bạn là chuyên gia phân tích chứng từ Đề Xuất Mua Hàng (DXMH) / Đơn Đặt Hàng (PO).
Hãy trích xuất thông tin khách hàng, số PO và nhà cung cấp từ tài liệu đính kèm và trả về DUY NHẤT 1 JSON object theo cấu trúc:
{
  "soPO": "Số PO hoặc Số hợp đồng nếu có (chỉ lấy mã/số)",
  "vendorHint": "Tên hãng hoặc Nhà cung cấp (NCC) nếu có",
  "tenCongTy": "Tên công ty khách hàng / đơn vị mua hàng",
  "nguoiNhan": "Tên người nhận hàng (Mục III / Người nhận) hoặc người liên hệ",
  "tenKhachHang": "Tên người liên hệ (Contact)",
  "mst": "Mã số thuế công ty khách hàng (chỉ gồm chữ số và dấu gạch ngang nếu có)",
  "diaChi": "Địa chỉ công ty khách hàng",
  "soDienThoai": "Số điện thoại người liên hệ / người nhận",
  "email": "Email liên hệ",
  "ngayTao": "Ngày tháng năm trên chứng từ định dạng DD/MM/YYYY nếu có"
}`
  const parsed = await callSmartDocumentAI(file, prompt, onProgress)
  if (!parsed || typeof parsed !== 'object') return null
  return {
    soPO: String(parsed.soPO || '').trim(),
    vendorHint: String(parsed.vendorHint || '').trim(),
    tenCongTy: String(parsed.tenCongTy || '').trim(),
    nguoiNhan: String(parsed.nguoiNhan || parsed.tenKhachHang || '').trim(),
    tenKhachHang: String(parsed.tenKhachHang || parsed.nguoiNhan || '').trim(),
    mst: String(parsed.mst || '').replace(/\s+/g, '').trim(),
    diaChi: String(parsed.diaChi || '').trim(),
    soDienThoai: String(parsed.soDienThoai || '').trim(),
    email: String(parsed.email || '').trim(),
    ngayTao: String(parsed.ngayTao || '').trim()
  }
}

async function extractUniversalDxmhFromFile(file: File) {
  const content = file.name.replace(/\.[^/.]+$/, '')
  let extractedTime = getFormattedNow()
  const dateInName = content.match(/(?:^|[_\-\s])(\d{1,2})[.\-](\d{1,2})[.\-](20\d{2})(?:$|[_\-\s])/)
  if (dateInName) {
    const dNum = Number(dateInName[1])
    const mNum = Number(dateInName[2])
    const yNum = Number(dateInName[3])
    if (dNum >= 1 && dNum <= 31 && mNum >= 1 && mNum <= 12) {
      const now = new Date()
      const p = (n: number) => String(n).padStart(2, '0')
      extractedTime = `${p(dNum)}/${p(mNum)}/${yNum} ${p(now.getHours())}:${p(now.getMinutes())}:${p(now.getSeconds())}`
    }
  }

  let soPO = ''
  const poFromName = content.match(/^(\d{1,6})(?:[_\-\s.]|$)/)
  if (poFromName) soPO = poFromName[1]

  let mst = ''
  let tenCT = ''
  let tenKH = ''
  let nguoiNhanDxmh = ''
  let productType = matchHangHoaNcc('', content)
  let previewHtml = ''
  let pUrl = ''
  let dxmhCustomerDetails: any = null
  let standardSuccess = false

  // 1. Quét chuẩn nếu không phải file ảnh
  if (!isImageDocFile(file)) {
    if (isSpreadsheetDocFile(file)) {
      try {
        const ab = await file.arrayBuffer()
        const excelParsed = parseDxmhExcelBuffer(ab, file.name)
        previewHtml = excelParsed.previewHtml
        if (excelParsed.soPO) soPO = excelParsed.soPO
        if (excelParsed.productType) productType = excelParsed.productType
        if (excelParsed.extractedTime) extractedTime = excelParsed.extractedTime
        if (excelParsed.tenCT || excelParsed.nguoiNhanDxmh || excelParsed.tenKH || excelParsed.mst) {
          mst = excelParsed.mst
          tenCT = excelParsed.tenCT
          tenKH = excelParsed.tenKH
          nguoiNhanDxmh = excelParsed.nguoiNhanDxmh
          dxmhCustomerDetails = excelParsed.dxmhCustomerDetails
          standardSuccess = true
        }
      } catch (e) {
        console.warn('parseDxmhExcelBuffer fallback:', e)
      }
    }

    if (!standardSuccess) {
      try {
        const stdCust = await parseCustomerDxmhStandardFromFile(file)
        if (stdCust && (stdCust.Ten_cong_ty || stdCust.Ten_khach_hang || stdCust.MST)) {
          tenCT = String(stdCust.Ten_cong_ty || '').trim()
          tenKH = String(stdCust.Ten_khach_hang || '').trim()
          nguoiNhanDxmh = String(stdCust.Ten_khach_hang_phu || stdCust.Ten_khach_hang || '').trim()
          mst = String(stdCust.MST || '').replace(/\s+/g, '').trim()
          dxmhCustomerDetails = {
            ten_khach_hang: tenKH,
            email_ca_nhan: stdCust.Email_ca_nhan || '',
            so_dien_thoai_ca_nhan: stdCust.So_dien_thoai_ca_nhan || '',
            ten_cong_ty: tenCT,
            so_dien_thoai_cong_ty: stdCust.So_dien_thoai_cong_ty || '',
            so_fax_cong_ty: stdCust.So_fax_cong_ty || '',
            dia_chi_cong_ty: stdCust.Dia_chi_cong_ty || '',
            email_cong_ty: stdCust.Email_cong_ty || '',
            website_cong_ty: stdCust.Website_cong_ty || '',
            mst,
            ten_khach_hang_phu: stdCust.Ten_khach_hang_phu || '',
            so_dien_thoai_ca_nhan_phu: stdCust.So_dien_thoai_ca_nhan_phu || '',
            company: stdCust.COMPANY || tenCT,
            address: stdCust.ADDRESS || stdCust.Dia_chi_cong_ty || '',
            tel: stdCust.TEL || stdCust.So_dien_thoai_cong_ty || ''
          }
          standardSuccess = true
        }
      } catch (e) {
        console.warn('parseCustomerDxmhStandardFromFile fallback:', e)
      }
    }
  }

  const prev = await generateExcelOrPdfPreviewOnly(file)
  pUrl = prev.pUrl
  if (!previewHtml && prev.pHtml) {
    previewHtml = prev.pHtml
  }

  // 2. Nếu quét thường không ra dữ liệu hoặc là file Ảnh/PDF scan -> Hỏi xác nhận người dùng trước khi chuyển sang AI
  if (!standardSuccess) {
    const allowAi = await confirmSwitchToAiScan(
      'File Đề Xuất Mua Hàng (DXMH)',
      file.name,
      `Không thể quét dữ liệu khách hàng / PO bằng chế độ chuẩn từ file "${file.name}". Bạn có muốn chuyển sang dùng AI để quét file DXMH này không?`
    )
    if (!allowAi) {
      return { cancelled: true, valid: false }
    }

    aiScanningModal.value = {
      show: true,
      title: 'AI Đang Quét File ĐXMH',
      docLabel: 'File Đề Xuất Mua Hàng (DXMH)',
      fileName: file.name,
      progressText: 'Đang dùng AI phân tích cấu trúc chứng từ ĐXMH...',
      progressMsg: 'Đang dùng AI phân tích cấu trúc chứng từ ĐXMH...'
    }
    try {
      const aiData = await analyzeDxmhFileWithAI(file, msg => {
        setAiScanningProgress(msg)
      })
      aiScanningModal.value.show = false

      if (!aiData || (!aiData.tenCongTy && !aiData.nguoiNhan && !aiData.mst && !aiData.soPO)) {
        return { cancelled: false, valid: false }
      }

      const aiSoPO = aiData.soPO || soPO
      const aiProductType = matchHangHoaNcc(aiData.vendorHint, content) || productType
      let aiTime = extractedTime
      if (aiData.ngayTao && /^\d{1,2}\/\d{1,2}\/\d{4}$/.test(aiData.ngayTao)) {
        const now = new Date()
        const p = (n: number) => String(n).padStart(2, '0')
        aiTime = `${aiData.ngayTao} ${p(now.getHours())}:${p(now.getMinutes())}:${p(now.getSeconds())}`
      }

      const confirmed = await openAiScanConfirmModal({
        kind: 'dxmh',
        docLabel: 'File Đề Xuất Mua Hàng (DXMH)',
        fileName: file.name,
        doanhSoBan: 0,
        giaMua: 0,
        soPO: aiSoPO,
        productType: aiProductType,
        customer: aiData.tenCongTy || aiData.nguoiNhan || aiData.tenKhachHang,
        company: aiData.tenCongTy || aiData.nguoiNhan || aiData.tenKhachHang,
        recipient: aiData.nguoiNhan || aiData.tenKhachHang || aiData.tenCongTy,
        mst: aiData.mst,
        phone: aiData.soDienThoai,
        email: aiData.email,
        address: aiData.diaChi,
        createdTime: aiTime,
        goodsList: []
      })

      if (!confirmed) {
        return { cancelled: true, valid: false }
      }

      soPO = confirmed.soPO
      productType = confirmed.productType
      tenCT = confirmed.customer
      nguoiNhanDxmh = confirmed.recipient
      tenKH = confirmed.recipient || confirmed.customer
      mst = confirmed.mst
      extractedTime = confirmed.createdTime || extractedTime
      dxmhCustomerDetails = {
        ten_khach_hang: tenKH,
        email_ca_nhan: confirmed.email || aiData.email || '',
        so_dien_thoai_ca_nhan: confirmed.phone || aiData.soDienThoai || '',
        ten_cong_ty: tenCT,
        so_dien_thoai_cong_ty: confirmed.phone || aiData.soDienThoai || '',
        so_fax_cong_ty: '',
        dia_chi_cong_ty: confirmed.address || aiData.diaChi || '',
        email_cong_ty: confirmed.email || aiData.email || '',
        website_cong_ty: '',
        mst,
        ten_khach_hang_phu: '',
        so_dien_thoai_ca_nhan_phu: '',
        company: tenCT,
        address: confirmed.address || aiData.diaChi || '',
        tel: confirmed.phone || aiData.soDienThoai || ''
      }
      standardSuccess = true
    } catch (aiErr) {
      aiScanningModal.value.show = false
      console.error('AI DXMH scan error:', aiErr)
      return { cancelled: false, valid: false }
    }
  }

  return {
    cancelled: false,
    valid: standardSuccess,
    soPO,
    content,
    mst,
    tenCT,
    tenKH,
    nguoiNhanDxmh,
    productType,
    extractedTime,
    previewHtml,
    pUrl,
    dxmhCustomerDetails
  }
}

async function confirmUploadModeChoice(mode: 'store_only' | 'scan_data') {
  const state = {
    kind: uploadModeChoiceModal.value.kind,
    docLabel: uploadModeChoiceModal.value.docLabel,
    files: [...uploadModeChoiceModal.value.files],
    dxmhTargetItem: uploadModeChoiceModal.value.dxmhTargetItem,
    scanTargetItem: uploadModeChoiceModal.value.scanTargetItem,
    importTargetVal: uploadModeChoiceModal.value.importTargetVal
  }
  uploadModeChoiceModal.value.show = false
  uploadModeChoiceModal.value.files = []

  if (!state.files.length) return

  if (mode === 'scan_data') {
    if (state.kind === 'dxmh') {
      await processDxmhFilesScan(state.files, state.dxmhTargetItem)
    } else if (state.kind === 'scan_img') {
      await processScanImageFile(state.files[0], state.scanTargetItem, true)
    } else if (state.kind === 'file_import' && state.importTargetVal) {
      await processImportFilesScan(state.files, state.importTargetVal)
    }
    return
  }

  // mode === 'store_only' (Up lưu trữ - không quét số liệu)
  loading.value = true
  try {
    if (state.kind === 'scan_img') {
      await processScanImageFile(state.files[0], state.scanTargetItem, false)
      await openSrAlert({
        variant: 'success',
        eyebrow: 'Import thành công',
        title: 'Import Chứng Từ COM thành công',
        highlightLabel: 'CHỨNG TỪ LƯU TRỮ',
        highlightValue: state.files[0].name,
        message: 'Đã tải và đính kèm chứng từ COM vào đơn hàng PO thành công.',
        confirmText: 'Hoàn tất'
      })
      return
    }

    if (state.kind === 'dxmh') {
      const tgtItem = state.dxmhTargetItem
      if (tgtItem) {
        const file = state.files[0]
        const { pUrl, pHtml } = await generateExcelOrPdfPreviewOnly(file)
        tgtItem.rawFileDxmh = file
        tgtItem.tenFileDxmh = file.name
        tgtItem.previewUrlDXMH = pUrl
        tgtItem.previewHtmlDXMH = pHtml
        tgtItem.activePreviewTab = 'dxmh'
        isModalDirty.value = true
        await openSrAlert({
          variant: 'success',
          eyebrow: 'Import thành công',
          title: 'Import File ĐXMH thành công',
          highlightLabel: 'CHỨNG TỪ ĐXMH LƯU TRỮ',
          highlightValue: file.name,
          message: 'Đã tải và đính kèm file Đề Xuất Mua Hàng vào PO thành công.',
          confirmText: 'Hoàn tất'
        })
        return
      }
      // Tạo PO mới từ ngoài nhưng chỉ lưu trữ file DXMH
      let currentMaxPO = Math.max(...rows.value.map(r => parseInt(String(r.So_PO))).filter(n => !isNaN(n)), 0)
      const items: ImportItem[] = []
      for (let i = 0; i < state.files.length; i++) {
        const file = state.files[i]
        const { pUrl, pHtml } = await generateExcelOrPdfPreviewOnly(file)
        currentMaxPO++
        items.push({
          id: Date.now() + i,
          row: null,
          doanhSoBan: 0,
          giaMua: 0,
          tongCP: 0,
          grossCom: 0,
          soPO: currentMaxPO > 0 ? String(currentMaxPO) : '',
          productType: '',
          customer: '',
          recipient: '',
          mst: '',
          createdTime: getFormattedNow(),
          content: file.name.replace(/\.[^/.]+$/, ''),
          netCom: 0,
          am: 'Lê Phi Sơn',
          taxPct: 25,
          scanning: false,
          rawFileDxmh: file,
          tenFileDxmh: file.name,
          previewUrlDXMH: pUrl,
          previewHtmlDXMH: pHtml,
          activePreviewTab: 'dxmh',
          otherFiles: [],
          goodsList: []
        })
      }
      isModalDirty.value = true
      multiEditModal.value = { show: true, mode: 'create', items, isReportImport: false }
      await openSrAlert({
        variant: 'success',
        eyebrow: 'Import thành công',
        title: 'Import File ĐXMH thành công',
        highlightLabel: 'SỐ FILE ĐXMH ĐÃ TẢI',
        highlightValue: `${items.length} file (${state.files.map(f => f.name).join(', ')})`,
        message: `Đã tải thành công ${items.length} file ĐXMH ở chế độ lưu trữ. Vui lòng bổ sung thông tin và nhấn Lưu trên cửa sổ PO.`,
        confirmText: 'Tiếp tục'
      })
      return
    }

    if (state.kind === 'file_import' && state.importTargetVal) {
      const tgt = state.importTargetVal
      if (tgt.type === 'update_item_bao_gia' && tgt.row) {
        const file = state.files[0]
        const { pUrl, pHtml } = await generateExcelOrPdfPreviewOnly(file)
        tgt.row.rawFileBaoGia = file
        tgt.row.previewUrlBG = pUrl
        tgt.row.previewHtmlBG = pHtml
        tgt.row.activePreviewTab = 'bg'
        isModalDirty.value = true
        await openSrAlert({
          variant: 'success',
          eyebrow: 'Import thành công',
          title: 'Import File Báo Giá thành công',
          highlightLabel: 'CHỨNG TỪ BÁO GIÁ LƯU TRỮ',
          highlightValue: file.name,
          message: 'Đã tải và đính kèm file Báo giá vào PO thành công.',
          confirmText: 'Hoàn tất'
        })
        return
      }
      if (tgt.type === 'update_item_mua_hang' && tgt.row) {
        const file = state.files[0]
        const { pUrl, pHtml } = await generateExcelOrPdfPreviewOnly(file)
        tgt.row.rawFileMuaHang = file
        tgt.row.previewUrlMH = pUrl
        tgt.row.previewHtmlMH = pHtml
        tgt.row.activePreviewTab = 'mh'
        isModalDirty.value = true
        await openSrAlert({
          variant: 'success',
          eyebrow: 'Import thành công',
          title: 'Import File Mua Hàng thành công',
          highlightLabel: 'CHỨNG TỪ MUA HÀNG LƯU TRỮ',
          highlightValue: file.name,
          message: 'Đã tải và đính kèm file Mua hàng vào PO thành công.',
          confirmText: 'Hoàn tất'
        })
        return
      }

      // Tạo PO mới từ file Báo giá / Mua hàng ở chế độ chỉ lưu trữ
      let currentMaxPO = Math.max(...rows.value.map(r => parseInt(String(r.So_PO))).filter(n => !isNaN(n)), 0)
      const items: ImportItem[] = []
      for (let i = 0; i < state.files.length; i++) {
        const file = state.files[i]
        const { pUrl, pHtml } = await generateExcelOrPdfPreviewOnly(file)
        currentMaxPO++
        const isBG = tgt.type === 'bao_gia'
        items.push({
          id: Date.now() + i,
          row: null,
          doanhSoBan: 0,
          giaMua: 0,
          tongCP: 0,
          grossCom: 0,
          soPO: currentMaxPO > 0 ? String(currentMaxPO) : '',
          productType: '',
          customer: '',
          recipient: '',
          mst: '',
          createdTime: getFormattedNow(),
          content: file.name.replace(/\.[^/.]+$/, ''),
          netCom: 0,
          am: 'Lê Phi Sơn',
          taxPct: 25,
          scanning: false,
          rawFileBaoGia: isBG ? file : undefined,
          rawFileMuaHang: !isBG ? file : undefined,
          previewUrlBG: isBG ? pUrl : undefined,
          previewHtmlBG: isBG ? pHtml : undefined,
          previewUrlMH: !isBG ? pUrl : undefined,
          previewHtmlMH: !isBG ? pHtml : undefined,
          activePreviewTab: isBG ? 'bg' : 'mh',
          otherFiles: [],
          goodsList: []
        })
      }
      isModalDirty.value = true
      multiEditModal.value = { show: true, mode: 'create', items, isReportImport: false }
      await openSrAlert({
        variant: 'success',
        eyebrow: 'Import thành công',
        title: tgt.type === 'bao_gia' ? 'Import File Báo Giá thành công' : 'Import File Mua Hàng thành công',
        highlightLabel: 'SỐ CHỨNG TỪ ĐÃ TẢI',
        highlightValue: `${items.length} file (${state.files.map(f => f.name).join(', ')})`,
        message: `Đã tải thành công ${items.length} file chứng từ ở chế độ lưu trữ. Vui lòng kiểm tra và nhấn Lưu trên cửa sổ PO.`,
        confirmText: 'Tiếp tục'
      })
    }
  } catch (err) {
    console.error('Lỗi tải file lưu trữ:', err)
    await openSrAlert({
      variant: 'error',
      title: 'Lỗi tải file lưu trữ',
      message: 'Đã xảy ra lỗi khi tải file lưu trữ lên hệ thống. Vui lòng thử lại.',
      confirmText: 'Đóng'
    })
  } finally {
    loading.value = false
  }
}

function onDxmhSelected(e: Event) {
  const target = e.target as HTMLInputElement
  if (!target.files || target.files.length === 0) return
  const files = Array.from(target.files)
  target.value = ''
  uploadModeChoiceModal.value = {
    show: true,
    kind: 'dxmh',
    docLabel: 'File Đề Xuất Mua Hàng (DXMH)',
    files,
    dxmhTargetItem: dxmhTargetItem.value,
    scanTargetItem: null,
    importTargetVal: null
  }
}

async function processDxmhFilesScan(files: File[], tgtItem: ImportItem | null) {
  loading.value = true
  try {
    // Trường hợp 1: Đính kèm / Cập nhật File DXMH trực tiếp trên 1 PO trong Modal
    if (tgtItem) {
      const file = files[0]
      const parsed = await extractUniversalDxmhFromFile(file)
      if (parsed.cancelled) {
        return
      }
      if (!parsed.valid) {
        await openSrAlert({
          variant: 'warning',
          title: 'File DXMH không hợp lệ',
          message: 'Không thể trích xuất dữ liệu hợp lệ từ file Đề Xuất Mua Hàng (DXMH) đã chọn.',
          confirmText: 'Đã hiểu'
        })
        return
      }

      tgtItem.rawFileDxmh = file
      tgtItem.tenFileDxmh = file.name
      tgtItem.previewUrlDXMH = parsed.pUrl
      tgtItem.previewHtmlDXMH = parsed.previewHtml
      tgtItem.activePreviewTab = 'dxmh'
      tgtItem.content = parsed.content
      if (parsed.soPO) tgtItem.soPO = parsed.soPO
      if (parsed.productType && (!tgtItem.productType || !isInHangHoaNccList(tgtItem.productType))) {
        tgtItem.productType = parsed.productType
      }
      tgtItem.dxmhCustomerDetails = parsed.dxmhCustomerDetails
      tgtItem.dxmhRecipient = parsed.nguoiNhanDxmh || ''

      if (parsed.tenCT || parsed.nguoiNhanDxmh || parsed.tenKH || parsed.mst) {
        await applyExtractedQuoteCustomerToModalItem(
          tgtItem,
          parsed.tenCT || '',
          parsed.nguoiNhanDxmh || '',
          parsed.mst || '',
          'DXMH'
        )
      }
      if (parsed.mst) {
        tgtItem.mst = parsed.mst
      }
      if (!tgtItem.createdTime && parsed.extractedTime) {
        tgtItem.createdTime = parsed.extractedTime
      }
      isModalDirty.value = true
      await openSrAlert({
        variant: 'success',
        eyebrow: 'Import thành công',
        title: 'Import File ĐXMH thành công',
        highlightLabel: 'CHỨNG TỪ ĐXMH ĐÃ QUÉT',
        highlightValue: file.name,
        message: 'Đã trích xuất thông tin khách hàng, số PO và đính kèm file Đề Xuất Mua Hàng vào đơn hàng thành công.',
        confirmText: 'Hoàn tất'
      })
      return
    }

    // Trường hợp 2: Import 1 hoặc nhiều File DXMH từ thanh công cụ để tạo PO mới
    const parsedItems: ImportItem[] = []
    let currentMaxPO = Math.max(...rows.value.map(r => parseInt(String(r.So_PO))).filter(n => !isNaN(n)), 0)
    let errorCount = 0
    let cancelledCount = 0

    for (let fIdx = 0; fIdx < files.length; fIdx++) {
      const file = files[fIdx]
      try {
        const parsed = await extractUniversalDxmhFromFile(file)
        if (parsed.cancelled) {
          cancelledCount++
          continue
        }
        if (!parsed.valid) {
          errorCount++
          continue
        }

        let finalSoPO = parsed.soPO || ''
        if (!finalSoPO) {
          currentMaxPO++
          finalSoPO = currentMaxPO > 0 ? String(currentMaxPO) : ''
        }

        const newItemObj: ImportItem = {
          id: Date.now() + fIdx,
          row: null,
          doanhSoBan: 0,
          giaMua: 0,
          tongCP: 0,
          grossCom: 0,
          soPO: finalSoPO,
          productType: parsed.productType || '',
          customer: parsed.tenCT || parsed.nguoiNhanDxmh || parsed.tenKH || '',
          recipient: parsed.nguoiNhanDxmh || parsed.tenCT || '',
          mst: parsed.mst || '',
          extractedCompany: parsed.tenCT || '',
          extractedRecipient: parsed.nguoiNhanDxmh || '',
          extractedMST: parsed.mst || '',
          extractedSourceLabel: 'DXMH',
          createdTime: parsed.extractedTime || getFormattedNow(),
          content: parsed.content || file.name.replace(/\.[^/.]+$/, ''),
          netCom: 0,
          am: 'Lê Phi Sơn',
          taxPct: 25,
          scanning: false,
          rawFileDxmh: file,
          tenFileDxmh: file.name,
          previewUrlDXMH: parsed.pUrl,
          previewHtmlDXMH: parsed.previewHtml,
          dxmhCustomerDetails: parsed.dxmhCustomerDetails,
          dxmhRecipient: parsed.nguoiNhanDxmh || '',
          activePreviewTab: 'dxmh',
          otherFiles: [],
          goodsList: []
        }

        await applyExtractedQuoteCustomerToModalItem(
          newItemObj,
          parsed.tenCT || '',
          parsed.nguoiNhanDxmh || '',
          parsed.mst || '',
          'DXMH'
        )
        if (parsed.mst) {
          newItemObj.mst = parsed.mst
        }
        parsedItems.push(newItemObj)
      } catch (err) {
        console.error('Lỗi đọc file DXMH:', file.name, err)
        errorCount++
      }
    }

    if (parsedItems.length === 0) {
      if (cancelledCount > 0 && errorCount === 0) return
      await openSrAlert({
        variant: 'warning',
        title: 'Không tìm thấy dữ liệu hợp lệ',
        message: 'Không tìm thấy thông tin hợp lệ trong file Đề Xuất Mua Hàng (DXMH) đã chọn.',
        confirmText: 'Đã hiểu'
      })
      return
    }

    isModalDirty.value = true
    multiEditModal.value = {
      show: true,
      mode: 'create',
      items: parsedItems,
      isReportImport: false
    }
    await openSrAlert({
      variant: 'success',
      eyebrow: 'Import thành công',
      title: 'Import File ĐXMH thành công',
      highlightLabel: 'SỐ FILE ĐXMH ĐÃ QUÉT',
      highlightValue: `${parsedItems.length} file ĐXMH`,
      message:
        errorCount > 0
          ? `Đã trích xuất thành công ${parsedItems.length} file ĐXMH (bỏ qua ${errorCount} file lỗi). Vui lòng kiểm tra thông tin và nhấn Lưu trên cửa sổ PO.`
          : `Đã trích xuất thành công ${parsedItems.length} file Đề Xuất Mua Hàng. Vui lòng kiểm tra thông tin và nhấn Lưu trên cửa sổ PO.`,
      confirmText: 'Tiếp tục'
    })
  } catch (err) {
    console.error('Lỗi khi xử lý file DXMH:', err)
    await openSrAlert({
      variant: 'error',
      title: 'Lỗi đọc file DXMH',
      message: 'Không thể đọc file Đề Xuất Mua Hàng (DXMH). Vui lòng kiểm tra lại định dạng file.',
      confirmText: 'Đóng'
    })
  } finally {
    loading.value = false
  }
}

// ─── File Khác (Other Attachments) ───
const otherFilesInput = ref<HTMLInputElement | null>(null)
const otherFilesTargetItem = ref<ImportItem | null>(null)

function getActiveOtherFile(item: ImportItem | null | undefined): OtherAttachmentItem | null {
  if (!item || !Array.isArray(item.otherFiles) || item.otherFiles.length === 0) return null
  const idx = Math.max(0, Math.min(Number(item.activeOtherFileIdx || 0), item.otherFiles.length - 1))
  return item.otherFiles[idx] || item.otherFiles[0] || null
}

function isOtherFileImage(fk: OtherAttachmentItem | null | undefined): boolean {
  if (!fk) return false
  const raw = String(fk.ten_file || fk.link_file || fk.previewUrl || '').toLowerCase()
  if (raw.startsWith('data:image/')) return true
  return /\.(png|jpe?g|webp|gif|bmp|svg)(\?|#|$)/.test(raw)
}

function isOtherFilePdf(fk: OtherAttachmentItem | null | undefined): boolean {
  if (!fk) return false
  const raw = String(fk.ten_file || fk.link_file || fk.previewUrl || '').toLowerCase()
  if (raw.startsWith('data:application/pdf')) return true
  return /\.pdf(\?|#|$)/.test(raw)
}

function isOtherFileOffice(fk: OtherAttachmentItem | null | undefined): boolean {
  if (!fk) return false
  const raw = String(fk.ten_file || fk.link_file || '').toLowerCase()
  return /\.(xlsx?|xls|docx?|pptx?)(\?|#|$)/.test(raw)
}

function triggerOtherFilesUpload(item: ImportItem) {
  otherFilesTargetItem.value = item
  if (otherFilesInput.value) {
    otherFilesInput.value.value = ''
    otherFilesInput.value.click()
  }
}

async function onOtherFilesSelected(e: Event) {
  const target = e.target as HTMLInputElement
  if (!target.files || target.files.length === 0) return
  const item = otherFilesTargetItem.value
  if (!item) return

  if (!Array.isArray(item.otherFiles)) {
    item.otherFiles = []
  }

  const nowStr = getFormattedNow()
  const filesArr = Array.from(target.files)
  for (let i = 0; i < filesArr.length; i++) {
    const file = filesArr[i]
    let previewHtml = ''
    const lowerName = file.name.toLowerCase()
    if (/\.(xlsx?|xls|csv)$/.test(lowerName)) {
      try {
        const ab = await file.arrayBuffer()
        const wb = XLSX.read(ab, { type: 'array' })
        const firstSheet = wb.SheetNames[0]
        if (firstSheet && wb.Sheets[firstSheet]) {
          previewHtml = XLSX.utils.sheet_to_html(wb.Sheets[firstSheet])
        }
      } catch (err) {
        console.warn('Could not generate Excel HTML preview for other file:', err)
      }
    }
    item.otherFiles.push({
      id: 'FK_' + Date.now() + '_' + i + '_' + Math.floor(Math.random() * 1000),
      ten_file: file.name,
      link_file: '',
      ngay_tai: nowStr,
      rawFile: file,
      previewUrl: URL.createObjectURL(file),
      previewHtml: previewHtml || undefined
    })
  }
  item.activeOtherFileIdx = Math.max(0, item.otherFiles.length - 1)
  item.activePreviewTab = 'other'
  isModalDirty.value = true
  target.value = ''
  await openSrAlert({
    variant: 'success',
    eyebrow: 'Import thành công',
    title: 'Đính kèm File Khác thành công',
    highlightLabel: 'FILE ĐÍNH KÈM MỚI',
    highlightValue: `${filesArr.length} file (${filesArr.map(f => f.name).join(', ')})`,
    message: 'Đã tải và thêm file đính kèm vào đơn hàng PO thành công.',
    confirmText: 'Hoàn tất'
  })
}

function removeOtherFile(item: ImportItem, idx: number | string) {
  const numIdx = Number(idx)
  if (!item || !Array.isArray(item.otherFiles) || numIdx < 0 || numIdx >= item.otherFiles.length) return
  const removed = item.otherFiles[numIdx]
  if (removed?.previewUrl && removed.previewUrl.startsWith('blob:')) {
    try {
      URL.revokeObjectURL(removed.previewUrl)
    } catch (_) {}
  }
  item.otherFiles.splice(numIdx, 1)
  const curIdx = Number(item.activeOtherFileIdx || 0)
  if (item.otherFiles.length === 0) {
    item.activeOtherFileIdx = 0
  } else if (curIdx >= item.otherFiles.length) {
    item.activeOtherFileIdx = item.otherFiles.length - 1
  }
  isModalDirty.value = true
}

function getOtherFileOpenUrl(fk: OtherAttachmentItem): string {
  const rawUrl = fk?.link_file || fk?.previewUrl || ''
  if (!rawUrl) return '#'
  if (rawUrl.startsWith('blob:') || rawUrl.startsWith('data:')) return rawUrl
  const nameLower = String(fk?.ten_file || rawUrl).toLowerCase()
  if (/\.(xlsx?|xls|docx?|pptx?)$/.test(nameLower)) {
    return `https://view.officeapps.live.com/op/view.aspx?src=${encodeURIComponent(rawUrl)}`
  }
  return rawUrl
}

// ─── Scan Chứng Từ COM (Ảnh / PDF / Word / Excel) ───
const scanInput = ref<HTMLInputElement | null>(null)
const scanTarget = ref<ImportItem | null>(null)

const scanConfirmModal = ref({
  show: false,
  item: null as ImportItem | null,
  nangGia: 0,
  thuePct: 25,
  conLai: 0,
  imageUrl: '',
  previewHtml: '',
  fileName: '',
  usedAi: false,
  scannedByAi: false
})

function onScanConfirmMetricChange(field?: 'nangGia' | 'thuePct' | 'conLai', val?: number) {
  const m = scanConfirmModal.value
  if (field && val !== undefined) {
    m[field] = Math.max(0, Number(val) || 0)
  }
  if (!field || field === 'nangGia' || field === 'thuePct') {
    const gross = Number(m.nangGia) || 0
    const pct = Number(m.thuePct) || 0
    if (gross > 0 && pct >= 0 && pct <= 100) {
      m.conLai = Math.round(gross * (1 - pct / 100))
    }
  }
}

async function confirmScanResult() {
  const m = scanConfirmModal.value
  const appliedGross = Number(m.nangGia) || 0
  const appliedNet = Number(m.conLai) || 0
  const fName = m.fileName || 'Chứng từ COM'
  if (m.item) {
    if (m.nangGia) m.item.grossCom = m.nangGia
    if (m.conLai) m.item.netCom = m.conLai
    m.item.taxPct = m.thuePct
    m.item.scanned = true
    isModalDirty.value = true
  }
  closeScanConfirmModal()
  await openSrAlert({
    variant: 'success',
    eyebrow: 'Import thành công',
    title: 'Import Chứng Từ COM thành công',
    highlightLabel: fName.toUpperCase(),
    highlightValue: `Gross COM: ${appliedGross.toLocaleString('vi-VN')} đ • Net COM: ${appliedNet.toLocaleString('vi-VN')} đ`,
    message: 'Đã áp dụng các chỉ số COM từ chứng từ vào đơn hàng PO thành công.',
    confirmText: 'Hoàn tất'
  })
}

function closeScanConfirmModal() {
  if (scanConfirmModal.value.imageUrl && scanConfirmModal.value.imageUrl.startsWith('blob:')) {
    try {
      URL.revokeObjectURL(scanConfirmModal.value.imageUrl)
    } catch (_) {}
