function extractComFiguresFromRawText(textData: string) {
  const lines = String(textData || '')
    .split(/\r?\n/)
    .map(l => l.trim().toLowerCase())
    .filter(Boolean)

  let nangGia = 0
  let thuePct = 25
  let conLai = 0

  const extractMoney = (text: string) => {
    const matches = text.match(/\d[\d,\.]+/g)
    if (matches) {
      for (let idx = matches.length - 1; idx >= 0; idx--) {
        const strVal = matches[idx].replace(/[,.]/g, '')
        const num = Number(strVal)
        if (!isNaN(num) && num >= 1000) return num
      }
    }
    return 0
  }

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]

    if (!nangGia && (line.includes('nâng giá') || line.includes('nang gia') || line.includes('gross com') || line.includes('hoa hồng') || line.includes('tổng com'))) {
      let val = extractMoney(line.replace(/nâng giá|nang gia|gross com|hoa hồng|tổng com/g, ''))
      if (!val && i + 1 < lines.length) val = extractMoney(lines[i + 1])
      if (val) nangGia = val
    }

    if (line.includes('thuế') || line.includes('thue') || line.includes('tax')) {
      const pctMatch = line.match(/(\d+(?:[.,]\d+)?)\s*%/)
      if (pctMatch) {
        const pct = parseFloat(pctMatch[1].replace(',', '.'))
        if (!isNaN(pct) && pct >= 0 && pct <= 100) {
          thuePct = pct
        }
      }
    }

    if (!conLai && (line.includes('còn lại') || line.includes('con lai') || line.includes('net com') || line.includes('thực nhận') || line.includes('thuc nhan'))) {
      let val = extractMoney(line.replace(/còn lại|con lai|net com|thực nhận|thuc nhan/g, ''))
      if (!val && i + 1 < lines.length) val = extractMoney(lines[i + 1])
      if (val) conLai = val
    }
  }

  if (nangGia > 0 && !conLai) {
    conLai = Math.round(nangGia * (1 - thuePct / 100))
  } else if (conLai > 0 && !nangGia && thuePct < 100) {
    nangGia = Math.round(conLai / (1 - thuePct / 100))
  }

  return { nangGia, thuePct, conLai }
}

async function processScanImageFile(file: File, item: ImportItem | null, runOcr: boolean) {
  if (!item || !file) return
  item.scanning = true

  try {
    let previewImgUrl = ''
    let previewHtml = ''

    if (isImageDocFile(file)) {
      const { base64, url } = await new Promise<{ base64: string; url: string }>((resolve, reject) => {
        const reader = new FileReader()
        reader.readAsDataURL(file)
        reader.onload = event => {
          const img = new Image()
          img.src = event.target?.result as string
          img.onload = () => {
            const canvas = document.createElement('canvas')
            const MAX_WIDTH = 1200
            let width = img.width
            let height = img.height

            if (width > MAX_WIDTH) {
              height *= MAX_WIDTH / width
              width = MAX_WIDTH
            }

            canvas.width = width
            canvas.height = height
            const ctx = canvas.getContext('2d')
            ctx?.drawImage(img, 0, 0, width, height)

            const compressedUrl = canvas.toDataURL('image/jpeg', 0.7)
            const base64Data = compressedUrl.split(',')[1]
            resolve({ base64: base64Data, url: compressedUrl })
          }
          img.onerror = reject
        }
        reader.onerror = reject
      })

      item.base64Img = base64
      item.rawFileScanCom = undefined
      item.previewUrlScanCom = url
      item.previewHtmlScanCom = ''
      previewImgUrl = url
    } else {
      const prev = await generateExcelOrPdfPreviewOnly(file)
      item.base64Img = undefined
      item.rawFileScanCom = file
      item.previewUrlScanCom = prev.pUrl
      item.previewHtmlScanCom = prev.pHtml
      previewHtml = prev.pHtml
      if (isPdfDocFile(file)) {
        try {
          const pages = await renderPdfPagesToVisionDataUrls(file, 1, 1.6)
          if (pages[0]) previewImgUrl = pages[0]
        } catch (_) {}
      }
    }

    item.activePreviewTab = 'img'

    if (!runOcr) {
      isModalDirty.value = true
      return
    }

    // 1. Quét chuẩn (OCR cho Ảnh / trích xuất văn bản cho PDF, Word, Excel)
    let rawText = ''
    if (isImageDocFile(file) && previewImgUrl) {
      const worker = await Tesseract.createWorker('vie', 1, {
        logger: m => console.log(m)
      })
      const result = await worker.recognize(previewImgUrl)
      await worker.terminate()
      rawText = result.data.text || ''
    } else {
      rawText = await extractUniversalRawText(file)
      if (!rawText.trim() && previewImgUrl) {
        const worker = await Tesseract.createWorker('vie', 1)
        const result = await worker.recognize(previewImgUrl)
        await worker.terminate()
        rawText = result.data.text || ''
      }
    }

    let { nangGia, thuePct, conLai } = extractComFiguresFromRawText(rawText)
    let usedAi = false

    // 2. Nếu quét chuẩn không tìm thấy số liệu COM -> Hỏi người dùng xác nhận chuyển sang AI
    if (!nangGia && !conLai) {
      const allowAi = await confirmSwitchToAiScan(
        'Chứng Từ COM',
        file.name,
        `Chế độ quét chuẩn không nhận diện được chỉ số Nâng giá (Gross COM) / Còn lại (Net COM) từ file "${file.name}". Bạn có muốn chuyển sang dùng AI để quét chứng từ này không?`
      )
      if (!allowAi) {
        return
      }

      aiScanningModal.value = {
        show: true,
        title: 'AI Đang Quét Chứng Từ COM',
        docLabel: 'Chứng Từ COM',
        fileName: file.name,
        progressText: 'Đang dùng AI phân tích các chỉ số COM trong chứng từ...',
        progressMsg: 'Đang dùng AI phân tích các chỉ số COM trong chứng từ...'
      }
      try {
        const comPrompt = `Bạn là chuyên gia phân tích chứng từ tính thưởng / hoa hồng / nâng giá (COM) của đơn hàng.
Hãy trích xuất các con số tài chính liên quan tới COM từ tài liệu/hình ảnh đính kèm và trả về DUY NHẤT 1 JSON object theo cấu trúc:
{
  "nangGia": 0,
  "thuePct": 25,
  "conLai": 0
}
Trong đó:
- "nangGia": Số tiền Nâng giá / Gross COM / Tổng tiền chênh lệch trước thuế (số nguyên VNĐ).
- "thuePct": Phần trăm thuế (%) áp dụng cho khoản nâng giá/COM (mặc định 25 nếu không ghi rõ).
- "conLai": Số tiền Còn lại / Net COM / Thực nhận sau khi trừ thuế (số nguyên VNĐ).`
        const aiParsed = await callSmartDocumentAI(file, comPrompt, msg => {
          setAiScanningProgress(msg)
        })
        aiScanningModal.value.show = false
        if (aiParsed && typeof aiParsed === 'object') {
          const aiGross = Math.round(Number(String(aiParsed.nangGia || 0).replace(/[^0-9.-]/g, '')) || 0)
          const aiTax = Number(String(aiParsed.thuePct ?? 25).replace(/[^0-9.]/g, ''))
          const aiNet = Math.round(Number(String(aiParsed.conLai || 0).replace(/[^0-9.-]/g, '')) || 0)
          if (aiGross > 0) nangGia = aiGross
          if (!isNaN(aiTax) && aiTax >= 0 && aiTax <= 100) thuePct = aiTax
          if (aiNet > 0) conLai = aiNet
          if (nangGia > 0 && !conLai) {
            conLai = Math.round(nangGia * (1 - thuePct / 100))
          } else if (conLai > 0 && !nangGia && thuePct < 100) {
            nangGia = Math.round(conLai / (1 - thuePct / 100))
          }
          usedAi = true
        }
      } catch (aiErr) {
        aiScanningModal.value.show = false
        console.warn('AI COM fallback error:', aiErr)
      }
    }

    scanConfirmModal.value = {
      show: true,
      item,
      nangGia,
      thuePct,
      conLai,
      imageUrl: previewImgUrl,
      previewHtml,
      fileName: file.name,
      usedAi,
      scannedByAi: usedAi
    }
  } catch (err: any) {
    aiScanningModal.value.show = false
    console.error('Lỗi quét chứng từ COM:', err)
    await openSrAlert({
      variant: 'error',
      title: 'Lỗi quét chứng từ COM',
      message: 'Không thể phân tích chứng từ: ' + (err?.message || err),
      confirmText: 'Đóng'
    })
  } finally {
    item.scanning = false
    isModalDirty.value = true
  }
}

function onFileSelected(e: Event) {
  const target = e.target as HTMLInputElement
  if (!target.files || target.files.length === 0) return
  const tgt = importTarget.value
