  }
}

interface QuotePdfToken {
  str: string
  x: number
  xRight: number
  topY: number
}

interface QuotePdfVisualLine {
  topY: number
  tokens: QuotePdfToken[]
  plainText: string
}

function joinQuotePdfLineTokens(tokens: QuotePdfToken[]): string {
  if (!tokens || tokens.length === 0) return ''
  let txt = ''
  tokens.forEach((t, idx) => {
    if (idx > 0) {
      const prev = tokens[idx - 1]
      if (t.x - prev.xRight > 1.5 && !prev.str.endsWith(' ') && !t.str.startsWith(' ')) {
        txt += ' '
      }
    }
    txt += t.str
  })
  return txt.trim()
}

function quotePdfTokensToPlainParagraphs(lines: QuotePdfToken[][]): string {
  const nonEmptyLines = lines.filter(l => l.length > 0 && l.map(t => t.str).join('').trim().length > 0)
  if (nonEmptyLines.length === 0) return ''

  const maxColRight = Math.max(...nonEmptyLines.map(l => l[l.length - 1].xRight))
  const minColLeft = Math.min(...nonEmptyLines.map(l => l[0].x))
  const colSpan = maxColRight - minColLeft

  const logicalLines: QuotePdfToken[][] = []
  for (let i = 0; i < nonEmptyLines.length; i++) {
    const curr = nonEmptyLines[i]
    if (logicalLines.length === 0) {
      logicalLines.push([...curr])
      continue
    }
    const prevLogical = logicalLines[logicalLines.length - 1]
    const prevRawLine = nonEmptyLines[i - 1]
    const prevRight = prevRawLine[prevRawLine.length - 1].xRight
    const prevFirstX = prevRawLine[0].x
    const currFirstX = curr[0].x
    const currText = joinQuotePdfLineTokens(curr)
    const prevText = joinQuotePdfLineTokens(prevRawLine)

    const startsWithBullet = /^([-+•*▪◦]|(\.\s)|(\d{1,2}[.)]\s))/i.test(currText)
    const startsWithSectionKeyword = /^(Features\s*:|Specifications\s*:|Bảo hành\s*:|Warranty\s*:|License\s+\d)/i.test(currText)
    const prevEndsWithColon = /:\s*$/.test(prevText)
    const indentChanged = Math.abs(currFirstX - prevFirstX) > 4
    const prevEndedEarly = colSpan > 90 && prevRight < maxColRight - 42

    if (startsWithBullet || startsWithSectionKeyword || prevEndsWithColon || indentChanged || prevEndedEarly) {
      logicalLines.push([...curr])
    } else {
      const offset = prevLogical[prevLogical.length - 1].xRight + 3 - curr[0].x
      const shifted = curr.map(t => ({
        ...t,
        x: t.x + offset,
        xRight: t.xRight + offset
      }))
      prevLogical.push(...shifted)
    }
  }

  return logicalLines.map(l => joinQuotePdfLineTokens(l)).filter(Boolean).join('\n').trim()
}

function quoteExcelCellText(v: any): string {
  if (v === null || v === undefined) return ''
  if (typeof v === 'string') return v
  if (typeof v === 'number') return String(v)
  if (v.richText && Array.isArray(v.richText)) return v.richText.map((r: any) => r.text || '').join('')
  if (v.text) return String(v.text)
  if (v.result !== undefined) return String(v.result)
  return String(v)
}

function stripQuoteHtmlToPlain(val?: string): string {
  if (!val) return ''
  return String(val)
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(div|p|li|tr)>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .trim()
}

function mapBaoGiaItemsToSaleReportGoodsList(rawItems: any[]): any[] {
  return (rawItems || []).map((it: any, idx: number) => {
    const sl = Math.max(1, Number(it.So_luong) || 1)
    const donGia = Number(it.Don_gia) || Number(it.Gia_tieu_chuan) || 0
    const ttTruoc = Number(it._thanhTienTruocThue) || (sl * donGia)
    const vatPct = Math.max(0, Number(it.Thue_VAT) || 0)
    const vatNum = Number(it._vatAmount) > 0
      ? Math.round(Number(it._vatAmount))
      : (vatPct > 0 ? Math.round((ttTruoc * vatPct) / 100) : 0)
    const ttSau = Number(it._thanhTienSauThue) > 0
      ? Math.round(Number(it._thanhTienSauThue))
      : (ttTruoc + vatNum)
    const dienGiaiPlain = String(
      it._dienGiaiPlain !== undefined
        ? it._dienGiaiPlain
        : stripQuoteHtmlToPlain(it.Features || it.Description || '')
    ).trim()

    return {
      stt: String(it._sttStr || it._sttIndex || idx + 1),
      maHang: String(it.Ma_hang || '').trim(),
      ten: String(it.Ten_hang || '').trim(),
      dienGiai: dienGiaiPlain,
      danhMuc: String(it.Danh_muc || '').trim(),
      dvt: String(it.DVT || '').trim(),
      sl,
      donGia,
      ttTruoc,
      vat: vatNum,
      ttSau,
      vatPct: vatPct > 0 ? String(vatPct) : '',
      vatStr: vatNum > 0 ? vatNum.toLocaleString('vi-VN') : ''
    }
  })
}

async function parsePdfQuoteGoodsLikeBaoGia(arrayBuffer: ArrayBuffer): Promise<any[]> {
  const pdf = await pdfjsLib.getDocument({ data: new Uint8Array(arrayBuffer.slice(0)) }).promise
  const allLines: QuotePdfVisualLine[] = []
  let pageOffsetY = 0

  for (let pageNum = 1; pageNum <= pdf.numPages; pageNum++) {
    const page = await pdf.getPage(pageNum)
    const viewport = page.getViewport({ scale: 1.0 })
    const textContent = await page.getTextContent()

    const pageTokens: QuotePdfToken[] = []
    for (const rawItem of (textContent.items || []) as any[]) {
      const str = String(rawItem?.str ?? '')
      if (!str.trim()) continue
      const tr = rawItem.transform || [10, 0, 0, 10, 0, 0]
      const x = Number(tr[4]) || 0
      const y = Number(tr[5]) || 0
      const topY = pageOffsetY + (viewport.height - y)
      const width = Number(rawItem.width) || (str.length * 4.5)
      pageTokens.push({
        str,
        x,
        xRight: x + width,
        topY
      })
    }

    pageTokens.sort((a, b) => a.topY - b.topY || a.x - b.x)
    for (const tok of pageTokens) {
      const existingLine = allLines.find(l => Math.abs(l.topY - tok.topY) <= 3.5)
      if (existingLine) {
        existingLine.tokens.push(tok)
      } else {
        allLines.push({
          topY: tok.topY,
          tokens: [tok],
          plainText: ''
        })
      }
    }
    pageOffsetY += viewport.height + 50
  }

  allLines.sort((a, b) => a.topY - b.topY)
  for (const line of allLines) {
    line.tokens.sort((a, b) => a.x - b.x)
    line.plainText = joinQuotePdfLineTokens(line.tokens)
  }

  let sttLineIdx = -1
  for (let i = 0; i < allLines.length; i++) {
    const hasSttToken = allLines[i].tokens.some(t => /^(STT|NO\.?|MSP|TT)$/i.test(t.str.trim()))
    if (!hasSttToken) continue
    const bandText = allLines
      .slice(Math.max(0, i - 2), Math.min(allLines.length, i + 3))
      .map(l => l.plainText)
      .join(' ')
      .toUpperCase()
    if (
      (bandText.includes('TÊN HÀNG') || bandText.includes('SẢN PHẨM') || bandText.includes('HÀNG HÓA') || bandText.includes('THIẾT BỊ') || bandText.includes('DIỄN GIẢI') || bandText.includes('MODEL') || bandText.includes('PART#') || bandText.includes('MÔ TẢ') || bandText.includes('DESCRIPTION') || bandText.includes('PS')) &&
      (bandText.includes('ĐƠN GIÁ') || bandText.includes('THÀNH TIỀN') || bandText.includes('TỔNG') || bandText.includes('S.L') || bandText.includes('SỐ LƯỢNG') || bandText.includes('UNIT PRICE') || bandText.includes('ESTIMATED VALUE') || bandText.includes('PRICES LIST') || bandText.includes('LIST PRICE'))
    ) {
      sttLineIdx = i
      break
    }
  }

  if (sttLineIdx === -1) return []

  const parseNumVal = (raw: string): number => {
    const cleaned = String(raw || '').replace(/[^\d.,-]/g, '').trim()
    if (!cleaned) return 0
    if (/^\d{1,3}(\.\d{3})+$/.test(cleaned)) {
      return parseFloat(cleaned.replace(/\./g, '')) || 0
    }
    if (/^\d{1,3}(,\d{3})+$/.test(cleaned)) {
      return parseFloat(cleaned.replace(/,/g, '')) || 0
    }
    return parseFloat(cleaned.replace(/,/g, '')) || 0
  }

  const sttTopY = allLines[sttLineIdx].topY
  const headerLines = allLines.filter(l => {
    if (Math.abs(l.topY - sttTopY) > 21) return false
    if (l.topY > sttTopY + 4 && /^(I|II|III|IV|V|1|2)\b/i.test(l.tokens[0]?.str?.trim() || '')) return false
    return true
  })
  const headerEndIdx = allLines.indexOf(headerLines[headerLines.length - 1])

  const linePhrases: Array<{ xLeft: number; xRight: number; topY: number; text: string }> = []
  for (const hl of headerLines) {
    let curr: { xLeft: number; xRight: number; topY: number; text: string } | null = null
    for (const tok of hl.tokens) {
      if (curr && tok.x - curr.xRight <= 4) {
        curr.xRight = Math.max(curr.xRight, tok.xRight)
        curr.text += ' ' + tok.str
      } else {
        if (curr) linePhrases.push(curr)
        curr = { xLeft: tok.x, xRight: tok.xRight, topY: hl.topY, text: tok.str }
      }
    }
    if (curr) linePhrases.push(curr)
  }

  linePhrases.sort((a, b) => a.topY - b.topY || a.xLeft - b.xLeft)
  const clusters: Array<{ xLeft: number; xRight: number; text: string }> = []
  for (const lp of linePhrases) {
    let bestCluster: { xLeft: number; xRight: number; text: string } | null = null
    let bestOverlap = -999
    for (const c of clusters) {
      const overlap = Math.min(c.xRight, lp.xRight) - Math.max(c.xLeft, lp.xLeft)
      if (overlap >= -4 && overlap > bestOverlap) {
        bestOverlap = overlap
        bestCluster = c
      }
    }
    if (bestCluster) {
      bestCluster.xLeft = Math.min(bestCluster.xLeft, lp.xLeft)
      bestCluster.xRight = Math.max(bestCluster.xRight, lp.xRight)
      bestCluster.text += ' ' + lp.text
    } else {
      clusters.push({ xLeft: lp.xLeft, xRight: lp.xRight, text: lp.text })
    }
  }
  clusters.sort((a, b) => a.xLeft - b.xLeft)

  const colDefs: Array<{ key: string; xLeft: number; xRight: number; xCenter: number }> = []
  for (const c of clusters) {
    const u = c.text.toUpperCase().replace(/\s+/g, ' ').trim()
    if ((u.includes('S.L') || u.includes('SỐ LƯỢNG') || u === 'SL') && (u.includes('ĐƠN VỊ') || u.includes('ĐVT') || u.includes('DVT'))) {
      const slRight = c.xLeft + 13
      colDefs.push({ key: 'sl', xLeft: c.xLeft, xRight: slRight, xCenter: (c.xLeft + slRight) / 2 })
      colDefs.push({ key: 'dvt', xLeft: slRight + 1, xRight: c.xRight, xCenter: (slRight + 1 + c.xRight) / 2 })
      continue
    }

    let key = ''
    if (u.includes('STT') || u === 'NO.' || u === 'TT' || u === 'MSP') key = 'stt'
    else if (u === 'P/N' || u === 'PN' || u.includes('MÃ HÀNG') || u.includes('PART NUMBER')) key = 'maHang'
    else if (u === 'PS' || u.startsWith('PS ') || u.includes('PART#') || u.includes('MODEL') || u.includes('SKU')) key = 'tenHang'
    else if (u.includes('TÊN HÀNG') || u.includes('HÀNG HÓA') || u.includes('SẢN PHẨM') || u.includes('THIẾT BỊ')) {
      key = colDefs.some(cd => cd.key === 'tenHang') ? 'features' : 'tenHang'
    } else if (u.startsWith('DESCRIPTION')) key = 'description'
    else if (u.includes('DIỄN GIẢI') || u.includes('MÔ TẢ') || u.includes('THÔNG SỐ') || u.includes('NỘI DUNG') || u.includes('HẠNG MỤC') || u.includes('SPEC')) key = 'features'
    else if (u.includes('ĐƠN VỊ') || u === 'ĐVT' || u === 'DVT' || u === 'UNIT') key = 'dvt'
    else if (u.includes('THỜI HẠN') || u.includes('DURATION') || u.includes('TERM')) key = 'license_duration'
    else if (u.includes('BẢO HÀNH') || u.includes('WARRANTY')) key = 'baoHanh'
    else if (u.includes('HÃNG') || u.includes('NHÀ CUNG CẤP')) key = 'hang'
    else if (u === 'S.L' || u === 'S.L.' || u.includes('SỐ LƯỢNG') || u === 'SL' || u === 'QTY') key = 'sl'
    else if (u.includes('PRICES LIST') || u.includes('LIST PRICE') || u.includes('PRICE LIST')) key = 'listPrice'
    else if (u.includes('DISCOUNT') || u.includes('OFF HÃNG')) key = 'discount'
    else if (u.includes('ĐƠN GIÁ') || u.includes('UNIT PRICE') || u.includes('GIÁ VỐN')) key = 'donGia'
    else if (u.includes('SAU THUẾ') || u.includes('SAU VAT') || u.includes('CÓ VAT') || u.includes('+ VAT') || u.includes('+ THUẾ')) key = 'sauThue'
    else if (u.includes('THÀNH TIỀN') || u.includes('TRƯỚC THUẾ') || u.includes('CHƯA VAT') || u.includes('ESTIMATED VALUE') || u === 'TỔNG' || u.includes('TỔNG TIỀN') || u === 'AMOUNT' || u === 'TOTAL') key = 'truocThue'
    else if (u.includes('VAT') || u.includes('THUẾ')) key = 'vat'

    if (key && !colDefs.some(cd => cd.key === key)) {
      colDefs.push({
        key,
        xLeft: c.xLeft,
        xRight: c.xRight,
        xCenter: (c.xLeft + c.xRight) / 2
      })
    }
  }

  colDefs.sort((a, b) => a.xCenter - b.xCenter)

  let bodyEndIdx = allLines.length
  for (let i = headerEndIdx + 1; i < allLines.length; i++) {
    const u = allLines[i].plainText.toUpperCase().trim()
    if (
      u.includes('TỔNG CỘNG') ||
      u.includes('TỔNG CHƯA VAT') ||
      u.includes('TỔNG TRƯỚC THUẾ') ||
      u.includes('TỔNG GIÁ TRỊ') ||
      u.includes('TỔNG THANH TOÁN') ||
      u.includes('CỘNG TIỀN HÀNG') ||
      u.includes('PHẦN MỀM KHÔNG CHỊU THUẾ') ||
      /^VAT\s*\d+/i.test(u) ||
      u.includes('ĐIỀU KHOẢN') ||
      u.includes('ĐIỀU KIỆN THƯƠNG MẠI') ||
      u.startsWith('TRÂN TRỌNG') ||
      u.includes('XÁC NHẬN ĐẶT HÀNG')
    ) {
      bodyEndIdx = i
      break
    }
  }

  const splitX: number[] = []
  for (let idx = 0; idx < colDefs.length - 1; idx++) {
    const curr = colDefs[idx]
    const next = colDefs[idx + 1]
    const prevSplit = idx === 0 ? Math.max(0, curr.xLeft - 4) : splitX[idx - 1]
    if (curr.key === 'stt') {
      splitX.push(curr.xRight + 4)
    } else if (next.key === 'features' || next.key === 'description') {
      const symRight = 2 * curr.xCenter - prevSplit - 2
      splitX.push(Math.min(next.xLeft - 2, Math.max(curr.xRight + 3, symRight)))
    } else if (curr.key === 'features' || curr.key === 'description' || curr.key === 'tenHang') {
      splitX.push(next.xLeft - 6)
    } else {
      splitX.push((curr.xRight + next.xLeft) / 2)
    }
  }

  const bounds: Array<{ key: string; minX: number; maxX: number }> = colDefs.map((cd, idx) => ({
    key: cd.key,
    minX: idx === 0 ? 0 : splitX[idx - 1],
    maxX: idx === colDefs.length - 1 ? 99999 : splitX[idx]
  }))

  const assignColKey = (tok: QuotePdfToken): string => {
    const tokCenter = (tok.x + tok.xRight) / 2
    for (const b of bounds) {
      const isTextCol = b.key === 'stt' || b.key === 'maHang' || b.key === 'tenHang' || b.key === 'description' || b.key === 'features'
      const refX = isTextCol ? tok.x : tokCenter
      if (refX >= b.minX && refX < b.maxX) return b.key
    }
    for (const b of bounds) {
      if (tok.x >= b.minX && tok.x < b.maxX) return b.key
    }
    return bounds[bounds.length - 1]?.key || 'features'
  }

  interface ParsedPdfBodyRow {
    topY: number
    byCol: Record<string, QuotePdfToken[]>
    isAnchor: boolean
    categoryLabel: string
  }

  const bodyRows: ParsedPdfBodyRow[] = []
  let activeCategory = ''

  for (let i = headerEndIdx + 1; i < bodyEndIdx; i++) {
    const line = allLines[i]
    if (!line.plainText) continue
    const uLine = line.plainText.toUpperCase()
    if (
      (uLine.includes('STT') || uLine.includes('NO.')) &&
      (uLine.includes('DIỄN GIẢI') || uLine.includes('TÊN HÀNG') || uLine.includes('ĐƠN GIÁ') || uLine.includes('THÀNH TIỀN'))
    ) {
      continue
    }
    const byCol: Record<string, QuotePdfToken[]> = {}
    for (const tok of line.tokens) {
      const k = assignColKey(tok)
      if (!byCol[k]) byCol[k] = []
      byCol[k].push(tok)
    }
    const getColStr = (k: string) => joinQuotePdfLineTokens(byCol[k] || [])
    const lpVal = parseNumVal(getColStr('listPrice'))
    const dgVal = parseNumVal(getColStr('donGia'))
    const ttVal = parseNumVal(getColStr('truocThue'))
    const slVal = parseNumVal(getColStr('sl'))
    const sttStr = getColStr('stt')

    const isRomanGroup = /^(I|II|III|IV|V|VI|VII|VIII|IX|X)\.?$/i.test(sttStr) && dgVal === 0 && ttVal === 0 && lpVal === 0
    const featMinX = bounds.find(b => b.key === 'features' || b.key === 'description')?.minX || 140
    const spansAcrossFeatSplit = line.tokens.some(t => t.x < featMinX - 5 && t.xRight > featMinX + 20)
    const isBannerGroup =
      !sttStr &&
      dgVal === 0 &&
      ttVal === 0 &&
      lpVal === 0 &&
      slVal === 0 &&
      (spansAcrossFeatSplit ||
        (!getColStr('tenHang') &&
          line.tokens.length === 1 &&
          /^[I1-9]*\.?\s*[A-Z0-9\s/-]{6,}$/.test(line.plainText) &&
          line.tokens[0].x < featMinX))
    if (isRomanGroup || isBannerGroup) {
      activeCategory = line.plainText.replace(/^(I|II|III|IV|V|VI|VII|VIII|IX|X)\.?\s*/i, '').trim() || line.plainText.trim()
      continue
    }

    const isAnchor =
      (dgVal > 0 && ttVal > 0) ||
      (lpVal > 0 && (dgVal > 0 || slVal > 0 || ttVal > 0)) ||
      (slVal > 0 && (dgVal > 0 || ttVal > 0 || lpVal > 0)) ||
      (/^\d+$/.test(sttStr) && (dgVal > 0 || ttVal > 0 || lpVal > 0 || Boolean(getColStr('tenHang'))))
    bodyRows.push({ topY: line.topY, byCol, isAnchor, categoryLabel: activeCategory })
  }

  const anchorIndices = bodyRows.map((r, idx) => (r.isAnchor ? idx : -1)).filter(idx => idx !== -1)
  if (anchorIndices.length === 0) return []

  const firstAnchorIdx = anchorIndices[0]
  const hasBodyAboveFirstAnchor = bodyRows
    .slice(0, firstAnchorIdx)
    .some(r => (r.byCol['features']?.length || 0) > 0 || (r.byCol['tenHang']?.length || 0) > 0)

  const itemRanges: Array<{ anchorIdx: number; startIdx: number; endIdx: number }> = []
  if (!hasBodyAboveFirstAnchor) {
    for (let m = 0; m < anchorIndices.length; m++) {
      const aIdx = anchorIndices[m]
      const nextAIdx = m < anchorIndices.length - 1 ? anchorIndices[m + 1] : bodyRows.length
      itemRanges.push({ anchorIdx: aIdx, startIdx: aIdx, endIdx: nextAIdx - 1 })
    }
  } else {
    let currentStartIdx = 0
    for (let m = 0; m < anchorIndices.length; m++) {
      const aIdx = anchorIndices[m]
      if (m === anchorIndices.length - 1) {
        itemRanges.push({ anchorIdx: aIdx, startIdx: currentStartIdx, endIdx: bodyRows.length - 1 })
      } else {
        const nextAIdx = anchorIndices[m + 1]
        const firstLineY = bodyRows[currentStartIdx].topY
        const anchorY = bodyRows[aIdx].topY
        const nextAnchorY = bodyRows[nextAIdx].topY
        const expectedBottomY = Math.min(
          nextAnchorY - 2,
          Math.max(anchorY + 2, 2 * anchorY - firstLineY)
        )
        let splitIdx = aIdx
        for (let k = aIdx; k < nextAIdx; k++) {
          if (bodyRows[k].topY <= expectedBottomY + 5) {
            splitIdx = k
          } else {
            break
          }
        }
        itemRanges.push({ anchorIdx: aIdx, startIdx: currentStartIdx, endIdx: splitIdx })
        currentStartIdx = splitIdx + 1
      }
    }
  }

  const hasSeparateFeaturesCol = colDefs.some(cd => cd.key === 'features')
  const newItems: any[] = []

  for (const range of itemRanges) {
    const anchorRow = bodyRows[range.anchorIdx]
    const getColPlainRange = (colKey: string) => {
      const parts: string[] = []
      for (let k = range.startIdx; k <= range.endIdx; k++) {
        const toks = bodyRows[k].byCol[colKey]
        if (toks && toks.length > 0) {
          parts.push(joinQuotePdfLineTokens(toks))
        }
      }
      return parts.filter(Boolean).join('\n').trim()
    }

    const featureTokenLines: QuotePdfToken[][] = []
    const tenHangTokenLines: QuotePdfToken[][] = []
    for (let k = range.startIdx; k <= range.endIdx; k++) {
      if (bodyRows[k].byCol['features']?.length) {
        featureTokenLines.push(bodyRows[k].byCol['features'])
      }
      if (bodyRows[k].byCol['tenHang']?.length) {
        tenHangTokenLines.push(bodyRows[k].byCol['tenHang'])
      }
    }

    const effectiveFeatureLines = hasSeparateFeaturesCol ? featureTokenLines : tenHangTokenLines
    const featuresPlain = quotePdfTokensToPlainParagraphs(effectiveFeatureLines)
    const rawTenHang = getColPlainRange('tenHang')
    let tenHang = ''
    if (hasSeparateFeaturesCol) {
      tenHang = rawTenHang.replace(/\r?\n/g, ' ').replace(/\s+/g, ' ').trim() || (featuresPlain ? featuresPlain.split(/\r?\n/)[0].trim() : '')
    } else {
      const rawLines = rawTenHang.split(/\r?\n/).map(s => s.trim()).filter(Boolean)
      const titleParts: string[] = []
      for (const rl of rawLines) {
        if (/^[•\-+*▪◦]/.test(rl)) break
        titleParts.push(rl)
      }
      tenHang = (titleParts.length > 0 ? titleParts.join(' ') : rawLines[0] || '').replace(/\s+/g, ' ').trim()
    }
    if (!tenHang) continue

    const getAnchorColStr = (colKey: string) => joinQuotePdfLineTokens(anchorRow.byCol[colKey] || [])
    let dvt = getColPlainRange('dvt')
      .replace(/\r?\n/g, ' ')
      .replace(/\b(BẢN|Bản)\s+(QUY)\s+(ỀN|ền)\b/g, (_, p1, p2, p3) => `${p1} ${p2}${p3}`)
      .replace(/\s+/g, ' ')
      .trim()
    let slRaw = (getAnchorColStr('sl') || getColPlainRange('sl').replace(/\r?\n/g, ' ')).trim()
    if (slRaw && !/^\d[\d.,]*$/.test(slRaw)) {
      const m = slRaw.match(/^([\d.,]+)\s+(.+)$/)
      if (m) {
        slRaw = m[1]
        if (!dvt) dvt = m[2].trim()
      }
    }
    if (!dvt) dvt = 'Bản quyền'

    const sl = parseNumVal(slRaw) || 1
    const listPrice = parseNumVal(getAnchorColStr('listPrice') || getColPlainRange('listPrice'))
    let donGia = parseNumVal(getAnchorColStr('donGia') || getColPlainRange('donGia'))
    const truocThue = parseNumVal(getAnchorColStr('truocThue') || getColPlainRange('truocThue')) || (sl * (donGia || listPrice))
    if (!donGia && truocThue > 0 && sl > 0) {
      donGia = Math.round(truocThue / sl)
    }
    const effectiveDonGia = donGia > 0 ? donGia : listPrice
    const sauThueVal = parseNumVal(getAnchorColStr('sauThue') || getColPlainRange('sauThue'))

    const vatRaw = getAnchorColStr('vat') || getColPlainRange('vat')
    const vatVal = parseNumVal(vatRaw)
    let vatPct = 0
    let vatAmount = 0
    if (vatVal > 0 && truocThue > 0 && vatVal > 100) {
      vatAmount = vatVal
      vatPct = Math.round((vatVal / truocThue) * 100)
    } else if (vatVal > 0 && vatVal <= 100) {
      vatPct = vatVal < 1 ? Math.round(vatVal * 100) : Math.round(vatVal)
      vatAmount = Math.round((truocThue * vatPct) / 100)
    }

    const sttStr = getAnchorColStr('stt') || getColPlainRange('stt').replace(/\r?\n/g, ' ').trim()

    newItems.push({
      _sttStr: sttStr || String(newItems.length + 1),
      Ten_hang: tenHang,
      Features: featuresPlain,
      _dienGiaiPlain: featuresPlain,
      Danh_muc: anchorRow.categoryLabel || '',
      DVT: dvt,
      So_luong: sl,
      Don_gia: effectiveDonGia,
      Gia_tieu_chuan: effectiveDonGia,
      Thue_VAT: vatPct,
      _vatAmount: vatAmount,
      _thanhTienTruocThue: truocThue,
      _thanhTienSauThue: sauThueVal > 0 ? sauThueVal : (truocThue + vatAmount)
    })
  }

  const summaryLines: string[] = []
  let inTerms = false
  for (let i = bodyEndIdx; i < allLines.length; i++) {
    const plain = allLines[i].plainText
    const upper = plain.toUpperCase()
    if (upper.includes('ĐIỀU KHOẢN') || upper.includes('ĐIỀU KIỆN THƯƠNG MẠI')) {
      inTerms = true
    }
    if (!inTerms && plain) {
      summaryLines.push(plain)
    }
    if (upper.startsWith('TRÂN TRỌNG') || upper.includes('XÁC NHẬN ĐẶT HÀNG') || upper.includes('ĐẠI DIỆN')) {
      break
    }
  }

  if (newItems.length > 0 && summaryLines.length > 0) {
    applySummaryVatAndComputeAfterTaxCost(newItems, summaryLines, false)
  }

  return mapBaoGiaItemsToSaleReportGoodsList(newItems)
}

async function extractGoodsListLikeBaoGiaFirebase(file: File, arrayBuffer: ArrayBuffer): Promise<any[]> {
  const lowerName = String(file.name || '').toLowerCase()
  if (lowerName.endsWith('.pdf')) {
    try {
      const pdfGoods = await parsePdfQuoteGoodsLikeBaoGia(arrayBuffer)
      if (pdfGoods.length > 0) return pdfGoods
    } catch (pdfErr) {
      console.warn('parsePdfQuoteGoodsLikeBaoGia fallback:', pdfErr)
    }
    return []
  }

  const isWordFile = isWordDocFile(file)
  const newItems: any[] = []

  // 1. Ưu tiên ExcelJS cho file .xlsx chuẩn giống baogiaFirebase.vue
  if (!isWordFile && /\.xlsx$/i.test(file.name)) {
    try {
      const excelWb = new ExcelJS.Workbook()
      await excelWb.xlsx.load(arrayBuffer.slice(0))
      for (const ws of excelWb.worksheets) {
        if (!ws || newItems.length > 0) continue
        let headerRowIndex = -1
        let readingTerms = false
        let inSummary = false
        let currentCategory = ''
        const summaryLines: string[] = []
        const colMap: Record<string, number> = {}
        const maxRow = Math.min(ws.rowCount || 500, 500)
        const isColHidden = (c: number) => Boolean(ws.getColumn(c)?.hidden)

        for (let r = 1; r <= maxRow; r++) {
          const row = ws.getRow(r)
          if (!row || row.hidden) continue

          if (headerRowIndex === -1) {
            const cellTexts: string[] = []
            for (let c = 1; c <= 25; c++) {
              if (isColHidden(c)) continue
              const rawCellVal = quoteExcelCellText(row.getCell(c).value).trim()
              cellTexts.push(rawCellVal.toUpperCase())
            }
            const rowStr = cellTexts.join('|')
            if (
              (rowStr.includes('STT') || rowStr.includes('NO.') || rowStr.includes('TT')) &&
              (rowStr.includes('TÊN HÀNG') || rowStr.includes('MODEL') || rowStr.includes('PART#') || rowStr.includes('HÀNG HÓA') || rowStr.includes('SẢN PHẨM') || rowStr.includes('DIỄN GIẢI') || rowStr.includes('DESCRIPTION'))
            ) {
              headerRowIndex = r
              let modelCol: number | undefined
              let tenHangCandidateCol: number | undefined
              for (let c = 1; c <= 25; c++) {
                if (isColHidden(c)) continue
                const cell = row.getCell(c)
                if (cell.master && cell.master.address !== cell.address) continue
                const header = quoteExcelCellText(cell.value).toUpperCase().replace(/\s+/g, ' ').trim()
                if (!header) continue
                if ((header.includes('STT') || header === 'NO.' || header === 'TT') && colMap['stt'] === undefined) colMap['stt'] = c
                else if ((header === 'P/N' || header === 'PN' || header.includes('MÃ HÀNG') || header.includes('PART NUMBER')) && colMap['maHang'] === undefined) colMap['maHang'] = c
                else if ((header.includes('MODEL') || header.includes('PART#') || header.includes('SKU')) && modelCol === undefined) {
                  modelCol = c
                  if (colMap['tenHang'] === undefined) colMap['tenHang'] = c
                } else if (header.includes('TÊN HÀNG') || header.includes('HÀNG HÓA') || header.includes('SẢN PHẨM') || header.includes('DỊCH VỤ')) {
                  if (colMap['tenHang'] === undefined) colMap['tenHang'] = c
                  else if (colMap['tenHang'] === modelCol && tenHangCandidateCol === undefined) tenHangCandidateCol = c
                } else if ((header === 'DESCRIPTION' || header === 'PRODUCT DESCRIPTION' || header.startsWith('DESCRIPTION (')) && colMap['description'] === undefined) colMap['description'] = c
                else if ((header.includes('DIỄN GIẢI') || header.includes('DIEN GIAI') || header.includes('MÔ TẢ') || header.includes('THÔNG SỐ') || header.includes('ĐẶC TÍNH') || header.includes('NỘI DUNG') || header.includes('HẠNG MỤC') || header.includes('SPEC')) && colMap['features'] === undefined) colMap['features'] = c
                else if ((header.includes('HÃNG') || header.includes('NHÀ CUNG CẤP')) && colMap['hang'] === undefined) colMap['hang'] = c
                else if ((header.includes('ĐƠN VỊ') || header.includes('DON VI') || header === 'ĐVT' || header === 'DVT' || header === 'UNIT') && colMap['dvt'] === undefined) colMap['dvt'] = c
                else if ((header.includes('THỜI HẠN') || header.includes('THOI HAN') || header.includes('DURATION')) && colMap['license_duration'] === undefined) colMap['license_duration'] = c
                else if ((header.includes('BẢO HÀNH') || header.includes('BAO HANH') || header.includes('WARRANTY')) && colMap['baoHanh'] === undefined) colMap['baoHanh'] = c
                else if ((header === 'S.L' || header === 'S.L.' || header.includes('SỐ LƯỢNG') || header.includes('S.LƯỢNG') || header === 'SL' || header === 'QTY') && colMap['sl'] === undefined) colMap['sl'] = c
                else if ((header.includes('ĐƠN GIÁ') || header.includes('DON GIA') || header.includes('UNIT PRICE')) && colMap['donGia'] === undefined) colMap['donGia'] = c
                else if (((header.includes('THÀNH TIỀN') && !header.includes('VAT') && !header.includes('SAU THUẾ') && !header.includes('SAU VAT')) || header.includes('TRƯỚC THUẾ') || header.includes('TRUOC THUE') || header.includes('ESTIMATED VALUE') || header.includes('AMOUNT')) && colMap['truocThue'] === undefined) colMap['truocThue'] = c
                else if ((header.includes('SAU THUẾ') || header.includes('SAU VAT') || (header.includes('THÀNH TIỀN') && header.includes('VAT'))) && colMap['sauThue'] === undefined) colMap['sauThue'] = c
                else if ((header === 'VAT' || header === 'THUẾ VAT' || (header.includes('THUẾ') && !header.includes('TRƯỚC') && !header.includes('SAU') && !header.includes('THÀNH TIỀN'))) && colMap['vat'] === undefined) colMap['vat'] = c
              }
              if (tenHangCandidateCol !== undefined) {
                if (colMap['features'] !== undefined || colMap['description'] !== undefined) {
                  if (modelCol !== undefined && colMap['maHang'] === undefined) colMap['maHang'] = modelCol
                  colMap['tenHang'] = tenHangCandidateCol
                } else {
                  colMap['features'] = tenHangCandidateCol
                }
              }
              if (colMap['features'] === undefined && colMap['description'] !== undefined) {
                colMap['features'] = colMap['description']
              }
            }
            continue
          }

          const getCellPlain = (colKey: string) => {
            const cIdx = colMap[colKey]
            if (cIdx === undefined) return ''
            return quoteExcelCellText(row.getCell(cIdx).value).trim()
          }

          const stt = getCellPlain('stt')
          const tenHang = getCellPlain('tenHang')
          const featuresPlain = getCellPlain('features')

          const rowPlainParts: string[] = []
          for (let c = 1; c <= 15; c++) {
            if (isColHidden(c)) continue
            const cell = row.getCell(c)
            if (cell.master && cell.master.address !== cell.address) continue
            const t = quoteExcelCellText(cell.value).trim()
            if (t) rowPlainParts.push(t)
          }
          const rowJoined = rowPlainParts.join(' ').trim()
          const rowAllUpper = `${stt.toUpperCase()}|${tenHang.toUpperCase()}|${featuresPlain.toUpperCase()}|${rowJoined.toUpperCase()}`

          if (
            !readingTerms &&
            (rowAllUpper.includes('ĐIỀU KHOẢN') || rowAllUpper.includes('ĐIỀU KIỆN THƯƠNG MẠI'))
          ) {
            readingTerms = true
          }

          if (
            !inSummary &&
            !readingTerms &&
            (rowAllUpper.includes('TỔNG CỘNG') ||
              rowAllUpper.includes('TỔNG CHƯA VAT') ||
              rowAllUpper.includes('TỔNG TRƯỚC THUẾ') ||
              rowAllUpper.includes('TỔNG GIÁ TRỊ') ||
              rowAllUpper.includes('TỔNG THANH TOÁN') ||
              rowAllUpper.includes('CỘNG TIỀN HÀNG') ||
              rowAllUpper.includes('PHẦN MỀM KHÔNG CHỊU THUẾ') ||
              /(?:^|\|)VAT\s*\d+/i.test(rowAllUpper))
          ) {
            inSummary = true
          }

          if (readingTerms) continue
          if (inSummary) {
            if (rowJoined) summaryLines.push(rowJoined)
            continue
          }

          const effectiveTenHang = tenHang || (featuresPlain ? featuresPlain.split(/\r?\n/)[0].trim() : '')
          if (!effectiveTenHang) continue

          const dvt = getCellPlain('dvt')
          const sl = Math.max(1, parseCleanNumber(getCellPlain('sl')) || 1)
          let donGia = parseCleanNumber(getCellPlain('donGia'))
          const truocThue = parseCleanNumber(getCellPlain('truocThue')) || (sl * donGia)
          if (!donGia && truocThue > 0 && sl > 0) {
            donGia = Math.round(truocThue / sl)
          }
          const sauThue = parseCleanNumber(getCellPlain('sauThue'))

          const tenCell = colMap['tenHang'] !== undefined ? row.getCell(colMap['tenHang']) : null
          const featCell = colMap['features'] !== undefined ? row.getCell(colMap['features']) : null
          const isMergedBanner = Boolean(
            tenCell &&
            featCell &&
            tenCell.isMerged &&
            featCell.isMerged &&
            tenCell.master?.address === featCell.master?.address
          )
          const isRomanSection = /^(I|II|III|IV|V|VI|VII|VIII|IX|X)\.?$/i.test(stt.trim())
          if (donGia === 0 && truocThue === 0 && (isMergedBanner || isRomanSection || !featuresPlain)) {
            currentCategory = effectiveTenHang
            continue
          }

          const vatVal = parseCleanNumber(getCellPlain('vat'))
          let vatPct = 0
          let vatAmount = 0
          if (vatVal > 0 && vatVal < 1) {
            vatPct = Math.round(vatVal * 100)
            vatAmount = Math.round((truocThue * vatPct) / 100)
          } else if (vatVal > 0 && truocThue > 0 && vatVal > 100) {
            vatAmount = vatVal
            vatPct = Math.round((vatVal / truocThue) * 100)
          } else if (vatVal > 0 && vatVal <= 100) {
            vatPct = Math.round(vatVal)
            vatAmount = Math.round((truocThue * vatPct) / 100)
          }

          newItems.push({
            _sttStr: stt || String(newItems.length + 1),
            Ten_hang: effectiveTenHang,
            Features: featuresPlain,
            _dienGiaiPlain: featuresPlain,
            Danh_muc: currentCategory,
            DVT: dvt || 'Bản quyền',
            So_luong: sl,
            Don_gia: donGia,
            Gia_tieu_chuan: donGia,
            Thue_VAT: vatPct,
            _vatAmount: vatAmount,
            _thanhTienTruocThue: truocThue,
            _thanhTienSauThue: sauThue > 0 ? sauThue : (truocThue + vatAmount)
          })
        }

        if (newItems.length > 0 && summaryLines.length > 0) {
          applySummaryVatAndComputeAfterTaxCost(newItems, summaryLines, false)
        }
      }
    } catch (excelJsErr) {
      console.warn('Chuyển sang bộ đọc đa định dạng cho bảng hàng hóa báo giá:', excelJsErr)
    }
  }

  // 2. Fallback sang bộ đọc chuẩn đa định dạng của baogiaFirebase.vue (parseSalesQuoteSheetsStandard)
  if (newItems.length === 0) {
    try {
      if (isWordFile) {
        const wordDoc = await readUniversalWordDocument(file)
        const stdWord = parseSalesQuoteSheetsStandard(wordDoc.tables, wordDoc.paragraphs, 'VND')
        if (stdWord.items.length > 0) {
          newItems.push(...stdWord.items)
        }
      } else {
        const sheets = await readUniversalSpreadsheetSheets(file)
        const stdExcel = parseSalesQuoteSheetsStandard(sheets, [], 'VND')
        if (stdExcel.items.length > 0) {
          newItems.push(...stdExcel.items)
        }
      }
    } catch (stdErr) {
      console.warn('parseSalesQuoteSheetsStandard fallback error:', stdErr)
    }
  }

  return mapBaoGiaItemsToSaleReportGoodsList(newItems)
}

// ─── HỆ THỐNG BÓC TÁCH "TỔNG CỘNG (ĐÃ BAO GỒM VAT)" CHO FILE / ẢNH MUA HÀNG (IMG_MUA_HANG) ───
function stripMuaHangDiacriticsUpper(str: string): string {
  return String(str || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[đĐ]/g, 'D')
    .toUpperCase()
}

function parseMuaHangMoneyValuesFromLine(rawLine: string): number[] {
  const cleaned = String(rawLine || '')
    // Loại bỏ tỷ lệ % như "8%", "10%"
    .replace(/\d+(?:[.,]\d+)?\s*%/g, ' ')
    // Loại bỏ thông số kỹ thuật như 1.8TB, 10K, 12Gb/s, 2.5"
    .replace(/\d+(?:[.,]\d+)?\s*(?:TB|GB|MB|KB|GB\/S|GHZ|MHZ|K|")\b/gi, ' ')
    // Loại bỏ mã hàng / part number bắt đầu bằng số 0 (VD: 005053362 trong IMG_MUA_HANG)
    .replace(/\b0\d{4,}\b/g, ' ')

  const matches = cleaned.match(/\b[1-9]\d{0,2}(?:[.,]\d{3})+\b|\b[1-9]\d{3,11}\b/g)
  if (!matches) return []
  const nums: number[] = []
  for (const tok of matches) {
    const val = Number(tok.replace(/[,.]/g, ''))
    if (Number.isFinite(val) && val >= 1000) {
      nums.push(Math.round(val))
    }
  }
  return nums
}

// Trích xuất con số TỔNG CỘNG (ĐÃ BAO GỒM VAT) từ văn bản (OCR ảnh IMG_MUA_HANG, PDF, Word)
function extractMuaHangTotalWithVatFromText(rawText: string): number {
  const lines = String(rawText || '')
    .split(/\r?\n/)
    .map(l => l.trim())
    .filter(Boolean)
  if (!lines.length) return 0

  let subTotalBeforeVat = 0
  let vatAmount = 0
  let vatRatePct = 0
  let explicitAfterVatTotal = 0

  const isHeaderLine = (u: string) => {
    let hits = 0
    if (u.includes('STT') || u.includes('SO TT')) hits++
    if (u.includes('MA HANG') || u.includes('TEN HANG')) hits++
    if (u.includes('DIEN GIAI') || u.includes('MO TA')) hits++
    if (u.includes('DON GIA')) hits++
    if (u.includes('SO LUONG')) hits++
    if (u.includes('THANH TIEN')) hits++
    return hits >= 2
  }

  for (let i = 0; i < lines.length; i++) {
    const u = stripMuaHangDiacriticsUpper(lines[i])
    if (isHeaderLine(u)) continue

    const isPreVatLabel =
      u.includes('CHUA VAT') ||
      u.includes('CHUA THUE') ||
      u.includes('TRUOC THUE') ||
      u.includes('TRUOC VAT')

    const isTotalAfterVatLine =
      !isPreVatLabel &&
      (u.includes('TONG CONG') ||
        u.includes('TONG THANH TOAN') ||
        u.includes('GRAND TOTAL') ||
        u.includes('DA BAO GOM VAT') ||
        u.includes('BAO GOM VAT') ||
        u.includes('BAO GOM THUE') ||
        u.includes('SAU VAT') ||
        u.includes('SAU THUE'))

    if (isTotalAfterVatLine) {
      const candidateNums: number[] = [...parseMuaHangMoneyValuesFromLine(lines[i])]
      // Trường hợp ô "TỔNG CỘNG / (ĐÃ BAO GỒM VAT)" gộp 2 dòng như trong IMG_MUA_HANG.jpg
      if (i + 1 < lines.length) {
        const nextU = stripMuaHangDiacriticsUpper(lines[i + 1])
        if (!nextU.includes('THUE') && !nextU.includes('THANH TIEN') && !isHeaderLine(nextU)) {
          candidateNums.push(...parseMuaHangMoneyValuesFromLine(lines[i + 1]))
        }
      }
      if (candidateNums.length === 0 && i > 0) {
        const prevU = stripMuaHangDiacriticsUpper(lines[i - 1])
        if (!prevU.includes('THUE') && !prevU.includes('THANH TIEN') && !isHeaderLine(prevU)) {
          candidateNums.push(...parseMuaHangMoneyValuesFromLine(lines[i - 1]))
        }
      }
      for (const n of candidateNums) {
        if (n > explicitAfterVatTotal) {
          explicitAfterVatTotal = n
        }
      }
      continue
    }

    const isVatLine =
      u.includes('THUE VAT') ||
      u.includes('THUE GTGT') ||
      /\bVAT\s*\d/.test(u) ||
      /^VAT\b/.test(u)

    if (isVatLine) {
      const pctMatch = lines[i].match(/(\d+(?:[.,]\d+)?)\s*%/)
      if (pctMatch) {
        const r = parseFloat(pctMatch[1].replace(',', '.'))
        if (Number.isFinite(r) && r > 0 && r <= 100) vatRatePct = r
      }
      const vNums = parseMuaHangMoneyValuesFromLine(lines[i])
      if (vNums.length > 0) {
        vatAmount = vNums[vNums.length - 1]
      } else if (i + 1 < lines.length) {
        const nextU = stripMuaHangDiacriticsUpper(lines[i + 1])
        if (!nextU.includes('TONG CONG') && !nextU.includes('DA BAO GOM')) {
          const nextNums = parseMuaHangMoneyValuesFromLine(lines[i + 1])
          if (nextNums.length > 0) vatAmount = nextNums[nextNums.length - 1]
        }
      }
      continue
    }

    const isSubTotalLine =
      u.includes('THANH TIEN') ||
      u.includes('CONG TIEN HANG') ||
      u.includes('TONG TIEN HANG') ||
      u.includes('SUBTOTAL') ||
      isPreVatLabel

    if (isSubTotalLine) {
      const sNums = parseMuaHangMoneyValuesFromLine(lines[i])
      if (sNums.length > 0) {
        subTotalBeforeVat = sNums[sNums.length - 1]
      }
    }
  }

  let computedWithVat = 0
  if (subTotalBeforeVat > 0 && vatAmount > 0) {
    computedWithVat = subTotalBeforeVat + vatAmount
  } else if (subTotalBeforeVat > 0 && vatRatePct > 0) {
    computedWithVat = Math.round(subTotalBeforeVat * (1 + vatRatePct / 100))
  }

  if (computedWithVat > 0) {
    return explicitAfterVatTotal >= computedWithVat ? explicitAfterVatTotal : computedWithVat
  }
  return explicitAfterVatTotal
}

// Trích xuất con số TỔNG CỘNG (ĐÃ BAO GỒM VAT) từ bảng dữ liệu Excel / Spreadsheet (hỗ trợ cả mẫu IMG_MUA_HANG)
function extractMuaHangTotalWithVatFromRows(rowsData: any[][]): number {
  if (!Array.isArray(rowsData) || rowsData.length === 0) return 0

  let subTotalBeforeVat = 0
  let vatAmount = 0
  let vatRatePct = 0
  let explicitAfterVatTotal = 0

  const extractRowMoneyNums = (r: any[]): number[] => {
    if (!Array.isArray(r)) return []
    const out: number[] = []
    for (let c = 0; c < r.length; c++) {
      const cell = r[c]
      if (cell === null || cell === undefined || cell === '') continue
      if (typeof cell === 'number') {
        if (Number.isFinite(cell) && cell >= 1000) out.push(Math.round(cell))
      } else {
        out.push(...parseMuaHangMoneyValuesFromLine(String(cell)))
      }
    }
    return out
  }

  for (let i = 0; i < rowsData.length; i++) {
    const r = rowsData[i]
    if (!Array.isArray(r)) continue
    const joinedText = r
      .filter(c => typeof c === 'string' && String(c).trim())
      .map(c => String(c).trim())
      .join(' ')
    if (!joinedText) continue

    const u = stripMuaHangDiacriticsUpper(joinedText)
    // Bỏ qua dòng tiêu đề bảng (VD: STT | MÃ HÀNG | DIỄN GIẢI | ĐƠN GIÁ | SỐ LƯỢNG | THÀNH TIỀN)
    if (
      (u.includes('DON GIA') && u.includes('THANH TIEN')) ||
      (u.includes('SO LUONG') && u.includes('THANH TIEN'))
    ) {
      continue
    }

    const isPreVat =
      u.includes('CHUA VAT') ||
      u.includes('CHUA THUE') ||
      u.includes('TRUOC THUE') ||
      u.includes('TRUOC VAT')

    const isAfterVatTotal =
      !isPreVat &&
      (u.includes('TONG CONG') ||
        u.includes('TONG THANH TOAN') ||
        u.includes('GRAND TOTAL') ||
        u.includes('DA BAO GOM VAT') ||
        u.includes('BAO GOM VAT') ||
        u.includes('BAO GOM THUE') ||
        u.includes('SAU VAT') ||
        u.includes('SAU THUE'))

    if (isAfterVatTotal) {
      const nums = extractRowMoneyNums(r)
      if (nums.length === 0 && i + 1 < rowsData.length) {
        nums.push(...extractRowMoneyNums(rowsData[i + 1]))
      }
      for (const n of nums) {
        if (n > explicitAfterVatTotal) explicitAfterVatTotal = n
      }
      continue
    }

    if (u.includes('THUE VAT') || u.includes('THUE GTGT') || /\bVAT\s*\d/.test(u) || /^VAT\b/.test(u)) {
      const pctMatch = joinedText.match(/(\d+(?:[.,]\d+)?)\s*%/)
      if (pctMatch) {
        const rate = parseFloat(pctMatch[1].replace(',', '.'))
        if (Number.isFinite(rate) && rate > 0 && rate <= 100) vatRatePct = rate
      }
      const nums = extractRowMoneyNums(r)
      if (nums.length > 0) vatAmount = nums[nums.length - 1]
      continue
    }

    if (
      u.includes('THANH TIEN') ||
      u.includes('CONG TIEN HANG') ||
      u.includes('TONG TIEN HANG') ||
      u.includes('SUBTOTAL') ||
      isPreVat
    ) {
      const nums = extractRowMoneyNums(r)
      if (nums.length > 0) subTotalBeforeVat = nums[nums.length - 1]
    }
  }

  let computedWithVat = 0
  if (subTotalBeforeVat > 0 && vatAmount > 0) {
    computedWithVat = subTotalBeforeVat + vatAmount
  } else if (subTotalBeforeVat > 0 && vatRatePct > 0) {
    computedWithVat = Math.round(subTotalBeforeVat * (1 + vatRatePct / 100))
  }

  if (computedWithVat > 0) {
    return explicitAfterVatTotal >= computedWithVat ? explicitAfterVatTotal : computedWithVat
  }
  return explicitAfterVatTotal
}

// Quét AI chuyên biệt cho mục Mua Hàng: CHỈ LẤY DUY NHẤT Giá mua & Tổng CP đơn hàng (theo Tổng cộng đã tính VAT), không lấy bất kỳ trường nào khác
async function analyzeMuaHangTotalOnlyWithAI(
  file: File,
  onProgress?: (msg: string) => void
): Promise<{ giaMua: number; tongCP: number }> {
  const prompt = `Bạn là chuyên gia phân tích chứng từ Mua Hàng.
Nhiệm vụ DUY NHẤT: Đọc bảng hoặc hình ảnh chứng từ Mua Hàng đính kèm và trích xuất con số TỔNG CỘNG ĐÃ BAO GỒM THUẾ VAT (Tổng thanh toán cuối cùng sau thuế) để làm Giá mua và Tổng CP đơn hàng.

QUY TẮC BẮT BUỘC:
1. Nếu chứng từ có các dòng cuối bảng như:
   - "THÀNH TIỀN" (chưa VAT, ví dụ 12,900,000)
   - "THUẾ VAT 8%" / "THUẾ VAT 10%" (ví dụ 1,032,000)
   - "TỔNG CỘNG (ĐÃ BAO GỒM VAT)" (ví dụ 13,932,000)
   => BẮT BUỘC lấy con số ở dòng "TỔNG CỘNG (ĐÃ BAO GỒM VAT)" (13932000) cho cả "giaMua" và "tongCP".
2. Nếu bảng chỉ ghi Thành tiền chưa thuế và Tiền thuế VAT riêng mà không in dòng tổng sau thuế, hãy lấy Thành tiền + Tiền thuế VAT.
3. TUYỆT ĐỐI KHÔNG lấy danh sách hàng hóa, không lấy nhà cung cấp hay bất kỳ thông tin nào khác.

Chỉ trả về DUY NHẤT 1 JSON object thuần (không giải thích thêm):
{
  "giaMua": 13932000,
  "tongCP": 13932000
}`

  const aiResult = await callSmartDocumentAI(
    file,
    prompt,
    'Chỉ trích xuất Giá mua và Tổng CP đơn hàng (Tổng cộng đã tính VAT) từ chứng từ Mua Hàng',
    onProgress,
    4
  )
  const parsedObj = aiResult?.parsed ?? aiResult
  const rawSourceText = String(aiResult?.rawSourceText || '')

  const cleanNum = (v: any): number => {
    if (typeof v === 'number') return Number.isFinite(v) ? Math.round(v) : 0
    const s = String(v ?? '').replace(/[^0-9.-]/g, '')
    const n = Number(s)
    return Number.isFinite(n) && n > 0 ? Math.round(n) : 0
  }

  let giaMua = cleanNum(parsedObj?.giaMua ?? parsedObj?.tongCongDaGomVat ?? parsedObj?.tongCong ?? parsedObj?.tongCP)
  let tongCP = cleanNum(parsedObj?.tongCP ?? giaMua)

  // Đối chiếu thêm với bộ đọc văn bản sau thuế để đảm bảo luôn lấy đúng số ĐÃ TÍNH VAT
  const textTotalAfterVat = extractMuaHangTotalWithVatFromText(rawSourceText)
  if (textTotalAfterVat > giaMua) {
    giaMua = textTotalAfterVat
  }
  if (!tongCP || tongCP < giaMua) {
    tongCP = giaMua
  }

  return { giaMua, tongCP }
}

async function processImportFilesScan(
  files: File[],
  tgt: { row: any; type: 'bao_gia' | 'mua_hang' | 'update_item_mua_hang' | 'update_item_bao_gia' }
) {
  loading.value = true

  const parsedItems: ImportItem[] = []
  let currentMaxPO = Math.max(...rows.value.map(r => parseInt(String(r.So_PO))).filter(n => !isNaN(n)), 0)
  let cancelledCount = 0

  for (let fIdx = 0; fIdx < files.length; fIdx++) {
    const file = files[fIdx]
    const isBG = tgt.type === 'bao_gia' || tgt.type === 'update_item_bao_gia'
    try {
      const arrayBuffer = await file.arrayBuffer()
      let extractedDSB = 0
      let extractedTongCP = 0
      let extractedCustomer = ''
      let extractedCompany = ''
      let extractedRecipient = ''
      let extractedMST = ''
      let extractedTime = ''
      let extractedProductType = isBG ? matchHangHoaNcc('', file.name) : ''
      let pUrl = ''
      let pHtml = ''
      let expectingCompanyPDF = false
      let expectingRecipientPDF = false
      let expectingCompanyExcel = false
      let expectingRecipientExcel = false
      let inGoodsSectionPDF = false
      let goodsList: any[] = []
      let goodsTotal: any = null
      let pendingDescLines: string[] = []
      let headerSkipCount = 0
      let currentCategory = ''

      // ─── TẦNG 1: QUÉT CHUẨN CỤC BỘ (HỖ TRỢ CẢ ẢNH IMG_MUA_HANG QUA OCR KHI IMPORT MUA HÀNG) ───
      if (!isImageDocFile(file)) {
        if (isPdfDocFile(file)) {
          pUrl = URL.createObjectURL(file)
          try {
            const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise
            const lines: string[] = []
            for (let pageNum = 1; pageNum <= pdf.numPages; pageNum++) {
              const page = await pdf.getPage(pageNum)
              const textContent = await page.getTextContent()
              const yMap = new Map<number, any[]>()
              textContent.items.forEach((item: any) => {
                const y = Math.round(item.transform[5])
                if (!yMap.has(y)) yMap.set(y, [])
                yMap.get(y)!.push(item)
              })
              const sortedYs = Array.from(yMap.keys()).sort((a, b) => b - a)
              for (const y of sortedYs) {
                const lineItems = yMap.get(y)!.sort((a, b) => a.transform[4] - b.transform[4])
                const lineText = lineItems.map(t => t.str).join(' ').replace(/\s+/g, ' ').trim()
                if (lineText) lines.push(lineText)
              }
            }

            if (!isBG) {
              extractedDSB = extractMuaHangTotalWithVatFromText(lines.join('\n'))
              extractedTongCP = extractedDSB
            }

            for (let i = 0; i < lines.length; i++) {
              const lineOriginal = lines[i]
              const line = lineOriginal.toLowerCase()

              if (!extractedDSB && (line.includes('tổng cộng') || line.includes('tổng thanh toán') || line.includes('grand total'))) {
                const parts = lines[i].toUpperCase().split(/TỔNG CỘNG|TỔNG THANH TOÁN|GRAND TOTAL/)
                if (parts[1]) {
                  const matches = parts[1].match(/[\d,.]+/g)
                  if (matches) {
                    for (const m of matches) {
                      const num = Number(m.replace(/[,.]/g, ''))
                      if (num > 1000) {
                        extractedDSB = num
                        break
                      }
                    }
                  }
                }
                if (!extractedDSB && i + 1 < lines.length) {
                  const nextLine = lines[i + 1].toUpperCase()
                  const matches = nextLine.match(/[\d,.]+/g)
                  if (matches) {
                    for (const m of matches) {
                      const num = Number(m.replace(/[,.]/g, ''))
                      if (num > 1000) {
                        extractedDSB = num
                        break
                      }
                    }
                  }
                }
              }

              if (isBG) {
                if (expectingCompanyPDF && !extractedCompany && lineOriginal.trim()) {
                  extractedCompany = lineOriginal.trim()
                  expectingCompanyPDF = false
                }
                if (expectingRecipientPDF && !extractedRecipient && lineOriginal.trim()) {
                  extractedRecipient = lineOriginal.trim()
                  expectingRecipientPDF = false
                }

                if (
                  !extractedCompany &&
                  (line.includes('kính gởi') ||
                    line.includes('kính gửi') ||
                    line.includes('bên mua') ||
                    line.includes('khách hàng') ||
                    line.includes('đơn vị') ||
                    line.includes('công ty') ||
                    line.includes('company') ||
                    line.includes('buyer') ||
                    line.includes('to:'))
                ) {
                  const match = lineOriginal.match(
                    /(kính g[ưở]i|bên mua|khách hàng|đơn vị|tên công ty|công ty|company|buyer|purchaser|to\s*:|bên a|bên b)/i
                  )
                  if (match) {
                    const colonIdx = line.indexOf(':', match.index)
                    let cLine = ''
                    if (colonIdx !== -1) {
                      cLine = lineOriginal.substring(colonIdx + 1).trim()
                    } else {
                      cLine = lineOriginal.substring((match.index || 0) + match[0].length).trim()
                    }
                    if (!cLine && i + 1 < lines.length) {
                      cLine = lines[i + 1].trim()
                    }
                    if (cLine.length > 2) {
                      extractedCompany = cLine
                    } else {
                      expectingCompanyPDF = true
                    }
                  }
                }

                if (
                  !extractedRecipient &&
                  (line.includes('người nhận') ||
                    line.includes('attn') ||
                    line.includes('attention') ||
                    line.includes('contact') ||
                    line.includes('đại diện') ||
                    line.includes('liên hệ'))
                ) {
                  const match = lineOriginal.match(/(người nhận|attn|attention|contact|đại diện|người liên hệ|người mua)/i)
                  if (match) {
                    const colonIdx = line.indexOf(':', match.index)
                    let cLine = ''
                    if (colonIdx !== -1) {
                      cLine = lineOriginal.substring(colonIdx + 1).trim()
                    } else {
                      cLine = lineOriginal.substring((match.index || 0) + match[0].length).trim()
                    }
                    if (!cLine && i + 1 < lines.length) {
                      cLine = lines[i + 1].trim()
                    }
                    if (cLine.length > 2) {
                      extractedRecipient = cLine
                    } else {
                      expectingRecipientPDF = true
                    }
                  }
                }

                if (!extractedMST && (line.includes('mã số thuế') || line.includes('mst') || line.includes('tax code'))) {
                  const mstMatch = lineOriginal.match(/[0-9]{8,14}(?:-[0-9]{1,4})?/)
                  if (mstMatch) extractedMST = mstMatch[0]
                }

                if (!extractedTime && line.includes('ngày') && line.includes('tháng') && line.includes('năm')) {
                  const m = line.match(/ngày\s+(\d{1,2})\s+tháng\s+(\d{1,2})\s+năm\s+(\d{4})/i)
                  if (m) extractedTime = `${m[1].padStart(2, '0')}/${m[2].padStart(2, '0')}/${m[3]}`
                } else if (!extractedTime && line.includes('ngày')) {
                  const m2 = line.match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/)
                  if (m2) extractedTime = m2[0]
                }

                if (!inGoodsSectionPDF) {
                  const headerKeywords = [
                    'stt',
                    'số tt',
                    'so tt',
                    'model',
                    'tên',
                    'hàng hóa',
                    'hang hoa',
                    'mô tả',
                    'mo ta',
                    'sản phẩm',
                    'san pham',
                    'chi tiết',
                    'chi tiet',
                    'hạng mục',
                    'hang muc',
                    'diễn giải',
                    'dien giai',
                    'đvt',
                    'dvt',
                    'đơn giá',
                    'don gia',
                    'unit price',
                    'số lượng',
                    'so luong',
                    's\\.l',
                    'qty',
                    'thành tiền',
                    'thanh tien',
                    'amount'
                  ]
                  let hdrCount = 0
                  for (const kw of headerKeywords) {
                    if (new RegExp('(?:^|\\s)' + kw + '(?:\\s|$)', 'i').test(line)) hdrCount++
                  }
                  if (
                    hdrCount >= 3 &&
                    !/(đơn vị\s*(thụ|thu)|tên\s*:|người\s*:|gởi\s*:|gửi\s*:|kính\s*:|địa chỉ|address|mst\s*:|mã số thuế|ngân hàng|bank)/i.test(line)
                  ) {
                    inGoodsSectionPDF = true
                    pendingDescLines = []
                    headerSkipCount = 2
                    continue
                  }
                }
                if (inGoodsSectionPDF && headerSkipCount > 0) {
                  const subHeaderWords = /(^|\s)(lượng|trước\s*thuế|sau\s*thuế|vnđ|\(vnđ\)|đơn vị|tính|hạn|thuế|vat)(\s|$)/gi
                  const matches = line.match(subHeaderWords)
                  const wordCount = line.trim().split(/\s+/).length
                  const isSubHeader = matches && matches.length >= 2 && matches.length / wordCount >= 0.3
                  if (isSubHeader) {
                    headerSkipCount--
                    continue
                  }
                  headerSkipCount = 0
                }
                if (
                  inGoodsSectionPDF &&
                  /^(tổng cộng|cộng|tổng tiền|tổng thanh toán|subtotal|grand total|các điều khoản)/i.test(line.trim())
                ) {
                  inGoodsSectionPDF = false
                }

                if (inGoodsSectionPDF) {
                  const tokens = lineOriginal.split(/\s+/)
                  const allNums: { val: number; idx: number }[] = []
                  let textTokens: string[] = []

                  for (let j = 0; j < tokens.length; j++) {
                    const tok = tokens[j]
                    if (/^-+$/.test(tok) || /^#+$/.test(tok) || /^\d+%$/.test(tok)) continue
                    if (/^[\d,.]+$/.test(tok)) {
                      const num = Number(tok.replace(/[,.]/g, ''))
                      if (!isNaN(num)) {
                        allNums.push({ val: num, idx: j })
                      }
                    }
                  }

                  let firstDataNumIdx = -1
                  let sl = 1,
                    donGia = 0,
                    ttTruoc = 0,
                    vatNum = 0,
                    ttSau = 0
                  let found = false

                  if (allNums.length >= 3) {
                    for (let a = 0; a <= allNums.length - 3; a++) {
                      const n1 = allNums[a].val,
                        n2 = allNums[a + 1].val,
                        n3 = allNums[a + 2].val
                      if (n1 > 0 && n2 > 0 && n3 >= 100000 && Math.abs(n1 * n2 - n3) <= 2) {
                        sl = n1
                        donGia = n2
                        ttTruoc = n3
                        firstDataNumIdx = allNums[a].idx
                        for (let b = a + 3; b < allNums.length; b++) {
                          if (allNums[b].val > ttTruoc * 0.5) {
                            ttSau = allNums[b].val
                            break
                          } else if (allNums[b].val > 0) {
                            vatNum = allNums[b].val
                          }
                        }
                        found = true
                        break
                      }
                    }
                  }
                  if (!found && allNums.length >= 2) {
                    for (let a = 0; a <= allNums.length - 2; a++) {
                      if (allNums[a].val >= 100000 && allNums[a].val === allNums[a + 1].val) {
                        sl = 1
                        donGia = allNums[a].val
                        ttTruoc = allNums[a + 1].val
                        firstDataNumIdx = allNums[a].idx
                        for (let b = a + 2; b < allNums.length; b++) {
                          if (allNums[b].val > ttTruoc * 0.5) {
                            ttSau = allNums[b].val
                            break
                          } else if (allNums[b].val > 0) {
                            vatNum = allNums[b].val
                          }
                        }
                        found = true
                        break
                      }
                    }
                  }
                  if (!found && allNums.length >= 2) {
                    for (let a = 0; a <= allNums.length - 2; a++) {
                      if (
                        allNums[a].val > 0 &&
                        allNums[a].val < allNums[a + 1].val &&
                        allNums[a + 1].val >= 100000 &&
                        allNums[a + 1].val % allNums[a].val === 0
                      ) {
                        sl = allNums[a].val
                        ttTruoc = allNums[a + 1].val
                        donGia = ttTruoc / sl
                        firstDataNumIdx = allNums[a].idx
                        found = true
                        break
                      }
                    }
                  }

                  if (found && sl > 0 && ttTruoc > 0) {
                    textTokens = []
                    for (let j = 0; j < firstDataNumIdx; j++) {
                      const tok = tokens[j]
                      if (/^-+$/.test(tok) || /^#+$/.test(tok) || /^\d+%$/.test(tok)) continue
                      textTokens.push(tok)
                    }

                    let stt = ''
                    if (textTokens.length > 0 && /^\d[\w.-]*$/.test(textTokens[0])) {
                      stt = textTokens.shift() || ''
                    }

                    let dvt = ''
                    const knownUnits = [
                      'cái',
                      'bộ',
                      'tháng',
                      'chiếc',
                      'gói',
                      'lô',
                      'cuộn',
                      'hộp',
                      'pcs',
                      'lic',
                      'thùng',
                      'kg',
                      'm',
                      'km',
                      'lít',
                      'bản',
                      'quyển',
                      'quyề',
                      'chai',
                      'lọ',
                      'năm'
                    ]
                    if (textTokens.length > 0) {
                      const lastWord = textTokens[textTokens.length - 1].toLowerCase()
                      if (knownUnits.includes(lastWord)) {
                        dvt = textTokens.pop() || ''
                      }
                    }

                    let ten = textTokens.join(' ').trim()
                    let dienGiai = pendingDescLines.join('\n').trim()
                    pendingDescLines = []

                    if (!ttSau && ttTruoc > 0) ttSau = ttTruoc + vatNum

                    if (ten.length <= 2 && dienGiai.length > 0) {
                      ten = dienGiai.replace(/\n/g, ' ')
                      dienGiai = ''
                    }

                    let calculatedVatPct = ''
                    if (ttTruoc > 0 && vatNum > 0) {
                      calculatedVatPct = Math.round((vatNum / ttTruoc) * 100).toString()
                    }

                    goodsList.push({
                      stt,
                      ten,
                      dvt,
                      sl,
                      donGia,
                      ttTruoc,
                      vat: vatNum,
                      ttSau,
                      dienGiai,
                      danhMuc: currentCategory,
                      vatPct: calculatedVatPct,
                      vatStr: vatNum > 0 ? vatNum.toLocaleString('vi-VN') : ''
                    })
                  } else {
                    const trimmed = lineOriginal.trim()
                    if (trimmed.length > 1 && !/^(VNĐ|vnd|\(VNĐ\)|trước thuế|sau thuế|thuế|lượng|tính|hạn|đơn vị)$/i.test(trimmed)) {
                      const isGroupLine = /^\d+[\.\s]*[A-ZÀ-Ỹ]/.test(trimmed) && allNums.length <= 1
                      if (isGroupLine) {
                        currentCategory = trimmed.replace(/^\d+[\.\s]+/, '').trim()
                        pendingDescLines = []
                      } else {
                        const startsWithLowercaseOrPunct = /^[a-zà-ỹ\(\[\{\+\,\.\/\\]/.test(trimmed)
                        if (startsWithLowercaseOrPunct && goodsList.length > 0) {
                          const lastItem = goodsList[goodsList.length - 1]
                          lastItem.dienGiai = lastItem.dienGiai ? lastItem.dienGiai + '\n' + trimmed : trimmed
                        } else {
                          pendingDescLines.push(trimmed)
                        }
                      }
                    }
                  }
                }
              }
            }

            if (extractedTime) {
              const d = new Date()
              const p = (n: number) => String(n).padStart(2, '0')
              extractedTime = `${extractedTime} ${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`
            }
          } catch (pdfErr) {
            console.warn('PDF standard scan fallback to AI:', pdfErr)
          }
        } else if (isWordDocFile(file)) {
          const prev = await generateExcelOrPdfPreviewOnly(file)
          pUrl = prev.pUrl
          pHtml = prev.pHtml
          try {
            const wordDoc = await readUniversalWordDocument(file)
            const rawLines = [
              ...wordDoc.paragraphs,
              ...wordDoc.tables.flatMap(t => t.rows.map(r => r.filter(Boolean).join(' ')))
            ]
            if (!isBG) {
              const mhWordTotalAfterVat = extractMuaHangTotalWithVatFromText(rawLines.join('\n'))
              if (mhWordTotalAfterVat > 0) {
                extractedDSB = mhWordTotalAfterVat
                extractedTongCP = mhWordTotalAfterVat
              }
            }
            for (const lineOriginal of rawLines) {
              const upper = lineOriginal.toUpperCase()
              if (!extractedDSB && (upper.includes('TỔNG CỘNG') || upper.includes('TỔNG THANH TOÁN') || upper.includes('GRAND TOTAL'))) {
                const matches = upper.match(/[\d,.]+/g)
                if (matches) {
                  for (let idx = matches.length - 1; idx >= 0; idx--) {
                    const num = Number(matches[idx].replace(/[,.]/g, ''))
                    if (num > 1000) {
                      extractedDSB = num
                      if (!isBG) extractedTongCP = num
                      break
                    }
                  }
                }
              }
            }
          } catch (wErr) {
            console.warn('Word standard scan fallback:', wErr)
          }
        } else {
          // Mọi định dạng Spreadsheet (.xlsx, .xls, .xlsm, .xlsb, .ods, .csv, .tsv, .txt, .xml, .html...)
          let data: any[][] = []
          try {
            const wb = XLSX.read(arrayBuffer, { type: 'array' })
            const ws = wb.Sheets[wb.SheetNames[0]]
            if (ws) {
              data = XLSX.utils.sheet_to_json<any[]>(ws, { header: 1 })
              pHtml = XLSX.utils.sheet_to_html(ws)
              pHtml = pHtml.replace(
                /<table/gi,
                '<table class="preview-excel-table" style="border-collapse:collapse; font-family: \'Calibri\', sans-serif; font-size: 13px; color: #1e293b; background: white; margin: 0;"'
              )
              pHtml = pHtml.replace(
                /<td/gi,
                '<td style="border: 1px solid #cbd5e1; padding: 6px 10px; white-space: nowrap; min-width: 60px; text-align: left; vertical-align: bottom;"'
              )
            }
          } catch (xlsxErr) {
            console.warn('XLSX.read fallback to universal spreadsheet reader:', xlsxErr)
          }

          if (data.length === 0) {
            try {
              const sheets = await readUniversalSpreadsheetSheets(file)
              if (sheets.length > 0) {
                data = sheets[0].rows
              }
            } catch (uErr) {
              console.warn('readUniversalSpreadsheetSheets fallback:', uErr)
            }
          }

          if (!isBG && data.length > 0) {
            const mhExcelTotalAfterVat = extractMuaHangTotalWithVatFromRows(data)
            if (mhExcelTotalAfterVat > 0) {
              extractedDSB = mhExcelTotalAfterVat
              extractedTongCP = mhExcelTotalAfterVat
            }
          }

          let headerRowIdx = -1
          let sttIdx = -1,
            tenIdx = -1,
            dienGiaiIdx = -1,
            dvtIdx = -1,
            slIdx = -1,
            dgIdx = -1,
            ttTruocIdx = -1,
            vatIdx = -1,
            ttSauIdx = -1
          let currentCat = ''

          for (let i = 0; i < data.length; i++) {
            const row = data[i]
            if (!row || !Array.isArray(row)) continue

            if (headerRowIdx === -1) {
              let foundHeaderKey = false
              for (let j = 0; j < row.length; j++) {
                const val = String(row[j] || '').toUpperCase().trim()
                if (!val) continue
                const valNoAccent = val.normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/Đ/g, 'D')

                if (sttIdx === -1 && (val === 'STT' || val === 'SỐ TT' || valNoAccent === 'SO TT' || val === 'NO' || val === 'NO.')) {
                  sttIdx = j
                  foundHeaderKey = true
                }
                if (
                  tenIdx === -1 &&
                  (val.includes('TÊN') ||
                    valNoAccent.includes('TEN HANG') ||
                    val.includes('HÀNG HÓA') ||
                    valNoAccent.includes('HANG HOA') ||
                    val.includes('VẬT TƯ') ||
                    val.includes('SẢN PHẨM') ||
                    val.includes('NỘI DUNG') ||
                    val.includes('MÔ TẢ') ||
                    val.includes('CHI TIẾT') ||
                    val.includes('HẠNG MỤC') ||
                    val.includes('ITEM') ||
                    val.includes('DESCRIPTION'))
                ) {
                  tenIdx = j
                  foundHeaderKey = true
                }
                if (dienGiaiIdx === -1 && val.includes('DIỄN GIẢI')) {
                  dienGiaiIdx = j
                }
                if (
                  dvtIdx === -1 &&
                  (val === 'DVT' || val === 'ĐVT' || val.includes('ĐƠN VỊ') || valNoAccent.includes('DON VI') || val === 'UNIT' || val === 'UOM')
                ) {
                  dvtIdx = j
                  foundHeaderKey = true
                }
                if (
                  slIdx === -1 &&
                  (val === 'S.L' || val === 'SL' || val.includes('SỐ LƯỢNG') || valNoAccent.includes('SO LUONG') || val === 'QTY')
                ) {
                  slIdx = j
                  foundHeaderKey = true
                }
                if (
                  dgIdx === -1 &&
                  (val.includes('ĐƠN GIÁ') ||
                    valNoAccent.includes('DON GIA') ||
                    val === 'GIÁ' ||
                    valNoAccent === 'GIA' ||
                    val.includes('PRICE') ||
                    val.includes('UNIT PRICE'))
                ) {
                  dgIdx = j
                  foundHeaderKey = true
                }

                if (
                  ttTruocIdx === -1 &&
                  (val.includes('THÀNH TIỀN') || valNoAccent.includes('THANH TIEN') || val.includes('AMOUNT') || val.includes('TOTAL')) &&
                  (val.includes('TRƯỚC') || valNoAccent.includes('TRUOC') || val.includes('CHƯA') || valNoAccent.includes('CHUA'))
                ) {
                  ttTruocIdx = j
                  foundHeaderKey = true
                } else if (
                  ttSauIdx === -1 &&
                  (val.includes('THÀNH TIỀN') || valNoAccent.includes('THANH TIEN') || val.includes('AMOUNT') || val.includes('TOTAL')) &&
                  (val.includes('SAU') || valNoAccent.includes('SAU') || val.includes('CÓ') || valNoAccent.includes('CO'))
                ) {
                  ttSauIdx = j
                  foundHeaderKey = true
                } else if (
                  ttSauIdx === -1 &&
                  (val.includes('THÀNH TIỀN') ||
                    valNoAccent.includes('THANH TIEN') ||
                    val === 'CỘNG' ||
                    valNoAccent === 'CONG' ||
                    val.includes('TỔNG TIỀN') ||
                    valNoAccent.includes('TONG TIEN') ||
                    val.includes('AMOUNT') ||
                    val.includes('TOTAL'))
                ) {
                  ttSauIdx = j
                  foundHeaderKey = true
                } else if (vatIdx === -1 && (val.includes('THUẾ') || valNoAccent.includes('THUE') || val.includes('VAT') || val.includes('TAX'))) {
                  vatIdx = j
                  foundHeaderKey = true
                }
              }

              const validKeysCount =
                (sttIdx !== -1 ? 1 : 0) +
                (tenIdx !== -1 ? 1 : 0) +
                (dvtIdx !== -1 ? 1 : 0) +
                (slIdx !== -1 ? 1 : 0) +
                (dgIdx !== -1 ? 1 : 0) +
                (ttTruocIdx !== -1 ? 1 : 0) +
                (ttSauIdx !== -1 ? 1 : 0)
              if (foundHeaderKey && validKeysCount >= 2) {
                headerRowIdx = i
                if (tenIdx === -1) {
                  for (let c = 0; c < row.length; c++) {
                    if (
                      c !== sttIdx &&
                      c !== dvtIdx &&
                      c !== slIdx &&
                      c !== dgIdx &&
                      c !== ttTruocIdx &&
                      c !== vatIdx &&
                      c !== ttSauIdx &&
                      String(row[c] || '').trim().length > 0
                    ) {
                      tenIdx = c
                      break
                    }
                  }
                  if (tenIdx === -1 && sttIdx !== -1) tenIdx = sttIdx + 1
                }
                continue
              } else {
                sttIdx = -1
                tenIdx = -1
                dienGiaiIdx = -1
                dvtIdx = -1
                slIdx = -1
                dgIdx = -1
                ttTruocIdx = -1
                vatIdx = -1
                ttSauIdx = -1
              }
            }

            if (headerRowIdx !== -1 && i > headerRowIdx && !extractedDSB) {
              const stt = sttIdx !== -1 ? row[sttIdx] : undefined
              let ten = tenIdx !== -1 ? row[tenIdx] : undefined

              const isTotalRow =
                String(stt || '').toUpperCase().includes('CỘNG') ||
                String(ten || '').toUpperCase().includes('CỘNG') ||
                String(stt || '').toUpperCase().includes('TỔNG') ||
                String(ten || '').toUpperCase().includes('TỔNG')

              if (isTotalRow) {
                goodsTotal = {
                  ttTruoc: ttTruocIdx !== -1 ? Number(row[ttTruocIdx]) : 0,
                  vat: vatIdx !== -1 ? Number(row[vatIdx]) : 0,
                  ttSau: ttSauIdx !== -1 ? Number(row[ttSauIdx]) : 0
                }
              } else {
                let anyText = ''
                for (let c = 0; c < row.length; c++) {
                  if (row[c] && typeof row[c] === 'string') {
                    const t = row[c].trim()
                    if (t.length > 2 && t.toUpperCase() !== 'OFF') {
                      anyText = t
                      break
                    }
                  }
                }
                const hasValidData =
                  ten ||
                  anyText ||
                  (dgIdx !== -1 && Number(row[dgIdx]) > 0) ||
                  (ttSauIdx !== -1 && Number(row[ttSauIdx]) > 0) ||
                  (slIdx !== -1 && Number(row[slIdx]) > 0)
                if (hasValidData) {
                  if (!ten) {
                    for (let c = 0; c < row.length; c++) {
                      if (
                        c !== sttIdx &&
                        c !== dvtIdx &&
                        c !== slIdx &&
                        c !== dgIdx &&
                        c !== ttTruocIdx &&
                        c !== vatIdx &&
                        c !== ttSauIdx &&
                        typeof row[c] === 'string'
                      ) {
                        const t = row[c].trim()
                        if (t.length > 2 && t.toUpperCase() !== 'OFF') {
                          ten = t
                          break
                        }
                      }
                    }
                  }
                  let ttTruoc = ttTruocIdx !== -1 ? Number(row[ttTruocIdx]) || 0 : 0
                  const donGia = dgIdx !== -1 ? Number(row[dgIdx]) || 0 : 0
                  const sl = slIdx !== -1 ? Number(row[slIdx]) || 0 : 0
                  if (ttTruoc === 0 && sl > 0 && donGia > 0) ttTruoc = sl * donGia

                  const vatVal = vatIdx !== -1 ? row[vatIdx] : 0
                  let vatNum = 0
                  if (typeof vatVal === 'string' && vatVal.includes('%')) {
                    const pct = parseFloat(vatVal) || 0
                    vatNum = ttTruoc * (pct / 100)
                  } else {
                    vatNum = Number(vatVal) || 0
                    if (vatNum > 0 && vatNum < 1) {
                      vatNum = ttTruoc * vatNum
                    }
                  }

                  let ttSau = ttSauIdx !== -1 ? Number(row[ttSauIdx]) || 0 : 0
                  if (ttSau === 0 && ttTruoc > 0) ttSau = ttTruoc + vatNum

                  let isCategoryRow = false
                  let potentialCategoryText = ''
                  for (let c = 0; c < row.length; c++) {
                    if (row[c] && typeof row[c] === 'string' && row[c].trim().length > 2) {
                      potentialCategoryText = row[c].trim()
                      break
                    }
                  }
                  if (potentialCategoryText && sl === 0 && donGia === 0 && ttTruoc === 0 && ttSau === 0) {
                    if (!potentialCategoryText.toUpperCase().includes('CỘNG') && !potentialCategoryText.toUpperCase().includes('TỔNG')) {
                      isCategoryRow = true
                      currentCat = String(potentialCategoryText).trim()
                    }
                  }

                  let calculatedVatPct = ''
                  if (ttTruoc > 0 && vatNum > 0) {
                    calculatedVatPct = Math.round((vatNum / ttTruoc) * 100).toString()
                  }

                  if (!isCategoryRow && ten) {
                    goodsList.push({
                      stt: stt || '',
                      ten: ten || '',
                      dienGiai: dienGiaiIdx !== -1 ? row[dienGiaiIdx] : '',
                      danhMuc: currentCat,
                      dvt: dvtIdx !== -1 ? row[dvtIdx] : '',
                      sl,
                      donGia,
                      ttTruoc,
                      vat: vatNum,
                      ttSau,
                      vatPct: calculatedVatPct,
                      vatStr: vatNum > 0 ? vatNum.toLocaleString('vi-VN') : ''
                    })
                  }
                }
              }
            }

            let tongCongCol = -1
            for (let j = 0; j < row.length; j++) {
              const cellUpper = String(row[j] || '').toUpperCase()
              if (cellUpper.includes('TỔNG CỘNG') || cellUpper.includes('TỔNG THANH TOÁN') || cellUpper.includes('GRAND TOTAL')) {
                tongCongCol = j
                break
              }
            }

            if (tongCongCol !== -1) {
              for (let j = tongCongCol + 1; j < row.length; j++) {
                if (!extractedDSB && row[j] !== undefined && row[j] !== null && row[j] !== '') {
                  const numVal = Number(String(row[j]).replace(/[,.]/g, ''))
                  if (!isNaN(numVal) && numVal > 0) {
                    extractedDSB = numVal
                    if (!isBG) extractedTongCP = numVal
                  }
                }
              }
            }

            if (isBG && i <= 18) {
              if (!extractedCompany || !extractedRecipient || !extractedTime || !extractedMST) {
                for (let j = 0; j < row.length; j++) {
                  const v = String(row[j] || '').trim()
                  if (!v) continue

                  if (expectingCompanyExcel && !extractedCompany) {
                    extractedCompany = v
                    expectingCompanyExcel = false
                    continue
                  }
                  if (expectingRecipientExcel && !extractedRecipient) {
                    extractedRecipient = v
                    expectingRecipientExcel = false
                    continue
                  }

                  const vLower = v.toLowerCase()

                  if (
                    !extractedCompany &&
                    (vLower.includes('kính gởi') ||
                      vLower.includes('kính gửi') ||
                      vLower.includes('bên mua') ||
                      vLower.includes('khách hàng') ||
                      vLower.includes('đơn vị'))
                  ) {
                    const match = v.match(/(kính g[ưở]i|bên mua|khách hàng|đơn vị)/i)
                    if (match) {
                      const colonIdx = v.indexOf(':', match.index)
                      if (colonIdx !== -1) {
                        extractedCompany = v.substring(colonIdx + 1).trim()
                      } else {
                        extractedCompany = v.substring((match.index || 0) + match[0].length).trim()
                      }

                      if (!extractedCompany) {
                        for (let k = j + 1; k < row.length; k++) {
                          const nextVal = String(row[k] || '').trim()
                          if (nextVal) {
                            extractedCompany = nextVal
                            break
                          }
                        }
                      }

                      if (!extractedCompany) {
                        expectingCompanyExcel = true
                      }
                    }
                  }

                  if (!extractedRecipient && vLower.includes('người nhận')) {
                    const match = v.match(/(người nhận)/i)
                    if (match) {
                      const colonIdx = v.indexOf(':', match.index)
                      if (colonIdx !== -1) {
                        extractedRecipient = v.substring(colonIdx + 1).trim()
                      } else {
                        extractedRecipient = v.substring((match.index || 0) + match[0].length).trim()
                      }

                      if (!extractedRecipient) {
                        for (let k = j + 1; k < row.length; k++) {
                          const nextVal = String(row[k] || '').trim()
                          if (nextVal) {
                            extractedRecipient = nextVal
                            break
                          }
                        }
                      }

                      if (!extractedRecipient) {
                        expectingRecipientExcel = true
                      }
                    }
                  }

                  if (!extractedMST && (vLower.includes('mã số thuế') || vLower.includes('mst') || vLower.includes('tax code'))) {
                    const colonIdx = v.indexOf(':')
                    let candidate = colonIdx !== -1 ? v.substring(colonIdx + 1).trim() : ''
                    if (!candidate && row[j + 1]) candidate = String(row[j + 1] || '').trim()
                    const mstMatch = candidate.match(/[0-9]{8,14}(?:-[0-9]{1,4})?/)
                    if (mstMatch) extractedMST = mstMatch[0]
                  }

                  if (!extractedTime && /^ngày/i.test(vLower)) {
                    let t = ''
                    if (vLower.includes(':')) {
                      t = v.split(/ngày\s*:/i)[1] || ''
                    } else {
                      t = v.replace(/^ngày\s*/i, '')
                    }
                    t = t.trim().replace(/\s*\/\s*/g, '/')
                    if (t) {
                      if (!t.includes(':')) {
                        const d = new Date()
                        const p = (n: number) => String(n).padStart(2, '0')
                        t = `${t} ${p(d.getHours())}:${p(d.getMinutes())}:${p(d.getSeconds())}`
                      }
                      extractedTime = t
                    }
                  }
                }
              }
            }
          }

          if (!isBG) {
            if (goodsTotal?.ttSau && Number(goodsTotal.ttSau) > extractedDSB) {
              extractedDSB = Number(goodsTotal.ttSau)
            }
            extractedTongCP = extractedDSB
          }

          if (!pHtml) {
            const prev = await generateExcelOrPdfPreviewOnly(file)
            pUrl = prev.pUrl
            pHtml = prev.pHtml
          } else {
            pUrl = await uploadFileToCloudinary(file)
          }
        }

        // Bổ sung quét chuẩn bảng hàng hóa & thông tin khách hàng từ bộ đọc đa định dạng baogiaFirebase.vue
        if (isBG) {
          const stdGoods = await extractGoodsListLikeBaoGiaFirebase(file, arrayBuffer)
          if (stdGoods.length > 0) {
            goodsList = stdGoods
          }
          if (!extractedCompany || !extractedRecipient || !extractedMST) {
            try {
              const stdCust = await parseCustomerQuoteStandardFromFile(file)
              if (stdCust) {
                if (!extractedCompany && stdCust.Ten_cong_ty) extractedCompany = stdCust.Ten_cong_ty
                if (!extractedRecipient && stdCust.Ten_khach_hang) extractedRecipient = stdCust.Ten_khach_hang
                if (!extractedMST && stdCust.MST) extractedMST = stdCust.MST
              }
            } catch (_) {}
          }
        } else if (!extractedDSB) {
          const stdPurchaseGoods = await extractGoodsListLikeBaoGiaFirebase(file, arrayBuffer)
          if (stdPurchaseGoods.length > 0) {
            goodsList = stdPurchaseGoods
          }
        }

        if (!extractedDSB && goodsList.length > 0) {
          extractedDSB = goodsList.reduce((acc, g) => acc + (Number(g.ttSau) || Number(g.ttTruoc) || 0), 0)
          if (!isBG) extractedTongCP = extractedDSB
        }
      } else {
        // File ảnh: tạo preview URL và nếu là Import Mua Hàng (ví dụ IMG_MUA_HANG.jpg) thì chạy OCR chuẩn lấy Tổng Cộng Đã Gồm VAT
        pUrl = URL.createObjectURL(file)
        if (!isBG) {
          try {
            const worker = await Tesseract.createWorker('vie', 1)
            const ocrRes = await worker.recognize(pUrl)
            await worker.terminate()
            const ocrText = ocrRes?.data?.text || ''
            const mhImgTotalAfterVat = extractMuaHangTotalWithVatFromText(ocrText)
            if (mhImgTotalAfterVat > 0) {
              extractedDSB = mhImgTotalAfterVat
              extractedTongCP = mhImgTotalAfterVat
            }
          } catch (ocrErr) {
            console.warn('OCR chuẩn ảnh Mua Hàng fallback sang AI:', ocrErr)
          }
        }
      }

      // ─── TẦNG 2: FALLBACK SANG AI NẾU QUÉT CHUẨN KHÔNG RA DỮ LIỆU HOẶC LÀ FILE ẢNH / PDF SCAN ───
      const needAiFallback = isBG
        ? isImageDocFile(file) || goodsList.length === 0 || !extractedDSB
        : !extractedDSB

      if (needAiFallback) {
        const docLabelStr = isBG ? 'File Báo Giá Khách Hàng' : 'File Đơn Mua Hàng (NCC)'
        const reasonStr = isImageDocFile(file)
          ? isBG
            ? 'Đây là file hình ảnh chứng từ nên bộ đọc chuẩn không thể tự trích xuất bảng hàng hóa và số tiền.'
            : 'Ảnh chứng từ Mua Hàng chưa nhận diện được dòng Tổng Cộng (đã tính VAT) qua OCR chuẩn.'
          : isBG
            ? 'Không tìm thấy bảng hàng hóa hoặc dòng Tổng Cộng doanh số bán theo mẫu chuẩn trong file này.'
            : 'Không tìm thấy dòng Tổng Cộng (đã tính VAT) của giá mua theo mẫu chuẩn trong file này.'

        const wantAi = await confirmSwitchToAiScan(docLabelStr, file.name, reasonStr)
        if (!wantAi) {
          cancelledCount++
          continue
        }

        aiScanningModal.value = {
          show: true,
          docLabel: docLabelStr,
          fileName: file.name,
          progressMsg: isImageDocFile(file)
            ? 'Đang dùng AI nhận diện hình ảnh chứng từ...'
            : 'Đang chuyển sang AI phân tích chứng từ...'
        }

        try {
          if (isBG) {
            // CHỈ quét file báo giá bằng AI để lấy danh sách hàng hóa & khách hàng (KHÔNG gửi kho sản phẩm hang_hoa cho AI)
            const aiRes = await analyzeSalesQuoteFileWithAI(file, 'VND', msg => {
              aiScanningModal.value.progressMsg = msg
            })
            aiScanningModal.value.show = false

            const aiGoods =
              aiRes.items && aiRes.items.length > 0
                ? mapBaoGiaItemsToSaleReportGoodsList(aiRes.items)
                : goodsList

            const aiDSB =
              aiGoods.reduce((acc, g) => acc + (Number(g.ttSau) || Number(g.ttTruoc) || 0), 0) || extractedDSB

            const aiCompany = String(aiRes.extractedCustomer?.Ten_cong_ty || extractedCompany || '').trim()
            const aiRecipient = String(
              aiRes.extractedCustomer?.Ten_khach_hang || extractedRecipient || aiCompany || ''
            ).trim()
            const aiMst = String(aiRes.extractedCustomer?.MST || extractedMST || '')
              .replace(/\s+/g, '')
              .trim()

            if (aiGoods.length === 0 && !aiDSB) {
              console.warn('AI không tìm thấy hàng hóa hoặc doanh số trong file báo giá:', file.name)
              continue
            }

            const confirmed = await openAiScanConfirmModal({
              kind: 'bao_gia',
              docLabel: 'File Báo Giá Khách Hàng',
              fileName: file.name,
              doanhSoBan: aiDSB,
              giaMua: 0,
              soPO: '',
              productType: extractedProductType,
              customer: aiCompany,
              recipient: aiRecipient,
              mst: aiMst,
              createdTime: extractedTime || getFormattedNow(),
              goodsList: aiGoods
            })

            if (!confirmed) {
              cancelledCount++
              continue
            }

            extractedDSB = confirmed.doanhSoBan
            extractedCompany = confirmed.customer
            extractedCustomer = confirmed.customer
            extractedRecipient = confirmed.recipient
            extractedMST = confirmed.mst
            extractedTime = confirmed.createdTime
            extractedProductType = confirmed.productType || extractedProductType
            goodsList = confirmed.goodsList
          } else {
            // File Mua Hàng -> Quét bằng AI: CHỈ LẤY DUY NHẤT Giá mua & Tổng CP đơn hàng (đã tính VAT), ngoài ra không lấy gì khác
            const aiRes = await analyzeMuaHangTotalOnlyWithAI(file, msg => {
              aiScanningModal.value.progressMsg = msg
            })
            aiScanningModal.value.show = false

            const aiGiaMua = aiRes.giaMua || extractedDSB
            const aiTongCP = aiRes.tongCP || aiGiaMua

            if (!aiGiaMua) {
              console.warn('AI không tìm thấy Tổng cộng (đã tính VAT) trong file mua hàng:', file.name)
              continue
            }

            const confirmed = await openAiScanConfirmModal({
              kind: 'mua_hang',
              docLabel: 'File Đơn Mua Hàng (NCC)',
              fileName: file.name,
              doanhSoBan: 0,
              giaMua: aiGiaMua,
              tongCP: aiTongCP,
              soPO: '',
              productType: '',
              customer: '',
              recipient: '',
              mst: '',
              createdTime: getFormattedNow(),
              goodsList: []
            })

            if (!confirmed) {
              cancelledCount++
              continue
            }

            extractedDSB = confirmed.giaMua
            extractedTongCP = confirmed.tongCP || confirmed.giaMua
            extractedProductType = ''
            goodsList = []
          }
        } catch (aiErr) {
          aiScanningModal.value.show = false
          console.error('Lỗi AI quét chứng từ:', file.name, aiErr)
          continue
        }
      }

      if (!extractedDSB) {
        console.warn('Không tìm thấy dòng TỔNG CỘNG trong file:', file.name)
        continue
      }

      const finalCompany = extractedCompany || extractedCustomer
      const finalRecipient = extractedRecipient || finalCompany
      extractedCustomer = finalCompany

      if (isBG) {
        const existingRow = rows.value.find(
          r => r.Ten_cong_ty?.trim().toLowerCase() === extractedCustomer.toLowerCase() && r.MST
        )
        currentMaxPO++

        let gTTruoc = 0,
          gVat = 0,
          gTSau = 0
        if (goodsList && goodsList.length > 0) {
          goodsList.forEach(g => {
            gTTruoc += g.ttTruoc || 0
            gVat += g.vat || 0
            gTSau += g.ttSau || 0
          })
          goodsTotal = { ttTruoc: gTTruoc, vat: gVat, ttSau: gTSau }
        }

        const newItemObj: ImportItem = {
          id: Date.now() + fIdx,
          row: null,
          doanhSoBan: extractedDSB,
          giaMua: 0,
          tongCP: 0,
          grossCom: 0,
          soPO: currentMaxPO > 0 ? String(currentMaxPO) : '',
          productType: extractedProductType,
          customer: extractedCustomer,
          recipient: finalRecipient,
          mst: extractedMST || (existingRow ? existingRow.MST : ''),
          extractedCompany: extractedCompany || '',
          extractedRecipient: extractedRecipient || '',
          extractedMST: extractedMST || '',
          extractedSourceLabel: 'Báo giá',
          createdTime: extractedTime || getFormattedNow(),
          content: file.name.replace(/\.[^/.]+$/, ''),
          netCom: 0,
          am: 'Lê Phi Sơn',
          taxPct: 25,
          scanning: false,
          rawFileBaoGia: files[fIdx],
          previewUrlBG: pUrl,
          previewHtmlBG: pHtml,
          activePreviewTab: 'bg',
          otherFiles: [],
          goodsList,
          goodsTotal
        }
        if (tgt.type === 'bao_gia') {
          await applyExtractedQuoteCustomerToModalItem(newItemObj, extractedCompany, extractedRecipient, extractedMST)
        }
        // Đối chiếu kho sản phẩm (hang_hoa) bằng hàm độc lập cục bộ — không gửi kho sản phẩm cho AI
        crossReferenceFinancialsForImportedQuote(newItemObj)
        parsedItems.push(newItemObj)
      } else {
        const finalGiaMua = extractedDSB
        const finalTongCP = extractedTongCP || extractedDSB
        parsedItems.push({
          id: Date.now() + fIdx,
          row: null,
          doanhSoBan: 0,
          giaMua: finalGiaMua,
          tongCP: finalTongCP,
          grossCom: 0,
          soPO: '',
          productType: '',
          customer: '',
          mst: '',
          createdTime: '',
          content: file.name.replace(/\.[^/.]+$/, ''),
          netCom: 0,
          am: '',
          taxPct: 25,
          scanning: false,
          rawFileMuaHang: files[fIdx],
          previewUrlMH: pUrl,
          previewHtmlMH: pHtml,
          activePreviewTab: 'mh'
        })
      }
    } catch (err) {
      aiScanningModal.value.show = false
      console.error('Lỗi khi đọc file:', file.name, err)
    }
  }

  if (parsedItems.length === 0) {
    loading.value = false
    if (cancelledCount > 0) return
    await openSrAlert({
      variant: 'warning',
      title: 'Không đọc được dữ liệu từ file',
      message: 'Không thể trích xuất dữ liệu hợp lệ từ các file đã chọn (kể cả qua quét chuẩn và AI). Vui lòng kiểm tra lại chứng từ.',
      confirmText: 'Đã hiểu'
    })
    return
  }

  if (tgt.type === 'update_item_bao_gia') {
    if (parsedItems[0] && parsedItems[0].doanhSoBan) {
      tgt.row.doanhSoBan = parsedItems[0].doanhSoBan
      tgt.row.rawFileBaoGia = files[0]
      tgt.row.previewUrlBG = parsedItems[0].previewUrlBG
      tgt.row.previewHtmlBG = parsedItems[0].previewHtmlBG
      tgt.row.activePreviewTab = 'bg'
      tgt.row.goodsList = parsedItems[0].goodsList
      tgt.row.goodsTotal = parsedItems[0].goodsTotal
      if (!tgt.row.giaMua && parsedItems[0].giaMua) {
        tgt.row.giaMua = parsedItems[0].giaMua
        tgt.row.tongCP = parsedItems[0].tongCP || parsedItems[0].giaMua
      }
      if (parsedItems[0].grossCom) {
        tgt.row.grossCom = parsedItems[0].grossCom
        tgt.row.taxPct = parsedItems[0].taxPct || tgt.row.taxPct || 25
        tgt.row.netCom = parsedItems[0].netCom
      }
      await applyExtractedQuoteCustomerToModalItem(
        tgt.row,
        parsedItems[0].extractedCompany || '',
        parsedItems[0].extractedRecipient || '',
        parsedItems[0].extractedMST || ''
      )
      onFinancialInput(tgt.row)
      isModalDirty.value = true
      loading.value = false
      await openSrAlert({
        variant: 'success',
        title: 'Import File Báo Giá thành công',
        message: `Đã trích xuất và cập nhật dữ liệu từ file Báo Giá (${files[0]?.name || ''}) vào PO #${tgt.row.soPO || 'mới'}.`,
        confirmText: 'Hoàn tất'
      })
      return
    } else {
      await openSrAlert({
        variant: 'warning',
        title: 'File báo giá thiếu dữ liệu Tổng Cộng',
        message: 'Không tìm thấy dữ liệu doanh số hoặc hàng hóa hợp lệ trong file báo giá đã chọn.',
        confirmText: 'Đã hiểu'
      })
    }
    loading.value = false
    return
  }

  if (tgt.type === 'update_item_mua_hang') {
    if (parsedItems[0] && parsedItems[0].giaMua) {
      tgt.row.giaMua = parsedItems[0].giaMua
      tgt.row.tongCP = parsedItems[0].tongCP || parsedItems[0].giaMua
      tgt.row.rawFileMuaHang = files[0]
      tgt.row.previewUrlMH = parsedItems[0].previewUrlMH
      tgt.row.previewHtmlMH = parsedItems[0].previewHtmlMH
      tgt.row.activePreviewTab = 'mh'
      onFinancialInput(tgt.row)
      isModalDirty.value = true
      loading.value = false
      await openSrAlert({
        variant: 'success',
        title: 'Import File Mua Hàng thành công',
        message: `Đã trích xuất và cập nhật Giá mua & Tổng CP đơn hàng (đã tính VAT) từ file Mua Hàng (${files[0]?.name || ''}) vào PO #${tgt.row.soPO || 'mới'}.`,
        confirmText: 'Hoàn tất'
      })
      return
    } else {
      await openSrAlert({
        variant: 'warning',
        title: 'File mua hàng thiếu dữ liệu Tổng Cộng',
        message: 'Không tìm thấy Tổng cộng (đã tính VAT) hợp lệ trong file mua hàng đã chọn.',
        confirmText: 'Đã hiểu'
      })
    }
    loading.value = false
    return
  }

  isModalDirty.value = tgt.type === 'bao_gia' || tgt.type === 'mua_hang'
  multiEditModal.value = {
    show: true,
    mode: tgt.type === 'bao_gia' || tgt.type === 'mua_hang' ? 'create' : 'update',
    items: parsedItems
  }
  loading.value = false
  await openSrAlert({
    variant: 'success',
    title: tgt.type === 'bao_gia' ? 'Import File Báo Giá thành công' : 'Import File Mua Hàng thành công',
    message: `Đã trích xuất thành công ${parsedItems.length} đơn hàng từ file ${tgt.type === 'bao_gia' ? 'Báo Giá' : 'Mua Hàng'}. Vui lòng kiểm tra thông tin trong bảng rồi nhấn Lưu dữ liệu.`,
    confirmText: 'Hoàn tất'
  })
}


// ─── Chọn Card PO / Card Công ty thống nhất (Cả Bản Chính Thức & Bản Tạm) ───
const selectedPoKeySet = computed(() => new Set(selectedPoKeyList.value))

function getPoRowKey(r: any): string {
  if (!r) return ''
  return String(r._firebaseKey || r.ID || r.So_PO || '').trim()
}

function isPoRowSelected(r: any): boolean {
  const key = getPoRowKey(r)
  return Boolean(key && selectedPoKeySet.value.has(key))
}

function toggleSelectPoRow(r: any) {
  const key = getPoRowKey(r)
  if (!key) return
  if (selectedPoKeySet.value.has(key)) {
    selectedPoKeyList.value = selectedPoKeyList.value.filter(k => k !== key)
  } else {
    selectedPoKeyList.value = [...selectedPoKeyList.value, key]
  }
}

function isGroupFullySelected(group: any): boolean {
  const items = Array.isArray(group?.items) ? group.items : []
  if (items.length === 0) return false
  return items.every((r: any) => isPoRowSelected(r))
}

function toggleSelectGroup(group: any) {
  const items = Array.isArray(group?.items) ? group.items : []
  const groupKeys = items.map((r: any) => getPoRowKey(r)).filter(Boolean)
  if (!groupKeys.length) return
  if (isGroupFullySelected(group)) {
    const removeSet = new Set(groupKeys)
    selectedPoKeyList.value = selectedPoKeyList.value.filter(k => !removeSet.has(k))
  } else {
    const next = new Set(selectedPoKeyList.value)
    groupKeys.forEach((k: string) => next.add(k))
    selectedPoKeyList.value = Array.from(next)
  }
}

function selectAllFilteredPoRows() {
  const next = new Set(selectedPoKeyList.value)
  filteredRows.value.forEach(r => {
    const k = getPoRowKey(r)
    if (k) next.add(k)
  })
  selectedPoKeyList.value = Array.from(next)
}

function clearSelectedPoRows() {
  selectedPoKeyList.value = []
}

function viewSelectedPoRows() {
  if (!selectedPoRows.value.length) return
  isModalDirty.value = false
  activeItemIdx.value = 0
  const baseId = Date.now()
  const items = selectedPoRows.value.map((r, idx) => createImportItemFromExistingRow(r, baseId + idx))
  multiEditModal.value = {
    show: true,
    mode: 'update',
    items,
    isReportImport: false
  }
}

async function deleteSelectedPoRows() {
  const list = selectedPoRows.value
  if (!list.length) return
  const count = list.length
  const isCraftMode = srDataMode.value === 'craft'
  const itemTerm = isCraftMode ? 'phương án tạm' : 'đơn hàng PO'
  const poLabels = list
    .map(r => (r.So_PO ? `PO ${r.So_PO}` : r.content_of_contract_PO || 'PO'))
    .filter(Boolean)
    .slice(0, 8)
    .join(', ') + (count > 8 ? ` (+${count - 8} khác)` : '')

  const confirmed = await openSrConfirm({
    variant: 'danger',
    eyebrow: isCraftMode ? 'Xác nhận xóa phương án tạm' : 'Xác nhận xóa đơn hàng',
    title: count > 1 ? `Xóa tất cả ${count} ${itemTerm} đã chọn` : `Xóa ${itemTerm} đã chọn`,
    highlightLabel: isCraftMode ? 'DANH SÁCH PHƯƠNG ÁN ĐANG CHỌN' : 'DANH SÁCH PO ĐANG CHỌN',
    highlightValue: `${count} ${itemTerm} (${poLabels})`,
    message: `Bạn có chắc chắn muốn xóa vĩnh viễn ${count} ${itemTerm} đã chọn khỏi hệ thống?`,
    subNote: isCraftMode
      ? 'Hành động này sẽ xóa các phương án tạm đã chọn khỏi danh sách Bản Tạm.'
      : 'Hành động này sẽ xóa các PO cùng lịch sử thanh toán liên quan và không thể hoàn tác.',
    confirmText: 'Xóa tất cả PO',
    cancelText: 'Hủy bỏ'
  })
  if (!confirmed) return

  loading.value = true
  try {
    const deletedKeySet = new Set<string>()
    for (const r of list) {
      const firebaseKey = r?._firebaseKey || r?.ID
      const srId = r?.ID || firebaseKey
      if (isCraftMode) {
        if (firebaseKey) {
          deletedKeySet.add(String(firebaseKey))
          await remove(dbRef(database, `sale_report_craft/${firebaseKey}`))
        }
        continue
      }
      if (firebaseKey) {
        deletedKeySet.add(String(firebaseKey))
        await remove(dbRef(database, `sale_report/${firebaseKey}`))
      }
      if (srId || firebaseKey) {
        const relatedHist = lichSuThanhToanList.value.filter(
          h =>
            (srId && String(h.id_salereport) === String(srId)) ||
            (firebaseKey && String(h.id_salereport) === String(firebaseKey))
        )
        for (const h of relatedHist) {
          const hk = h._firebaseKey || h.id
          if (hk) await remove(dbRef(database, `lich_su_thanh_toan/${hk}`))
        }
      }
      const fromCraft = r?.from_craft
      if (fromCraft) {
        await update(dbRef(database, `sale_report_craft/${fromCraft}`), {
          chotDeal: false,
          id_sale_report: ''
        })
      }
      const idQuanLyFile = r?.id_quanlyfile || r?.id_quan_ly_file
      if (idQuanLyFile) {
        const remainingSrKeys = (rows.value || [])
          .filter((rowItem: any) => {
            const rKey = rowItem?._firebaseKey || rowItem?.ID
            if (!rKey || deletedKeySet.has(String(rKey))) return false
            return rowItem?.id_quanlyfile === idQuanLyFile || rowItem?.id_quan_ly_file === idQuanLyFile
          })
          .map((rowItem: any) => rowItem?._firebaseKey || rowItem?.ID)
          .filter(Boolean)

        await update(dbRef(database, `quan_ly_file/${idQuanLyFile}`), {
          craft_chotDeal: remainingSrKeys.length > 0,
          id_sale_report: remainingSrKeys[0] || '',
          sale_report_ids: remainingSrKeys
        })
      }
    }

    selectedPoKeyList.value = []
    await loadData()
    await openSrAlert({
      variant: 'success',
      eyebrow: isCraftMode ? 'Xóa phương án tạm hoàn tất' : 'Xóa đơn hàng hoàn tất',
      title: isCraftMode ? 'Xóa phương án tạm thành công' : 'Xóa đơn hàng PO thành công',
      highlightLabel: isCraftMode ? 'DANH SÁCH PHƯƠNG ÁN ĐÃ XÓA' : 'DANH SÁCH PO ĐÃ XÓA',
      highlightValue: `${count} ${itemTerm} (${poLabels})`,
      message: isCraftMode
        ? `Đã xóa ${count} phương án tạm đã chọn khỏi danh sách Bản Tạm thành công.`
        : `Đã xóa vĩnh viễn ${count} đơn hàng PO đã chọn và đồng bộ lại dữ liệu công nợ, hợp đồng thành công.`,
      confirmText: 'Hoàn tất'
    })
  } catch (e) {
    console.error('Lỗi xóa hàng loạt PO:', e)
    await openSrAlert({
      variant: 'error',
      title: 'Lỗi xóa dữ liệu',
      message: 'Đã xảy ra lỗi khi xóa các mục đã chọn. Vui lòng thử lại.',
      confirmText: 'Đóng'
    })
  } finally {
    loading.value = false
  }
}

watch(rows, (newRows) => {
  if (!selectedPoKeyList.value.length) return
  const validKeys = new Set((newRows || []).map(r => getPoRowKey(r)).filter(Boolean))
  const filtered = selectedPoKeyList.value.filter(k => validKeys.has(k))
  if (filtered.length !== selectedPoKeyList.value.length) {
    selectedPoKeyList.value = filtered
  }
})

