})

const mindmapActiveFilterCount = computed(() => {
  let c = 0
  const f = mindmapFilter.value
  if (reviewMindmapModal.value.searchQuery && reviewMindmapModal.value.searchQuery.trim()) c++
  if (f.timeMode !== 'all') c++
  if (f.customer && f.customer !== 'Tất cả') c++
  if (f.ncc && f.ncc !== 'Tất cả') c++
  if (f.debtStatus && f.debtStatus !== 'Tất cả') c++
  if (f.sortBy !== 'dsb_desc') c++
  return c
})

const mindmapTimeLabel = computed(() => {
  const f = mindmapFilter.value
  const formatYMD = (s: string) => {
    if (!s) return ''
    const parts = s.split('-')
    if (parts.length === 3) return parts[2] + '/' + parts[1] + '/' + parts[0]
    return s
  }
  const formatYM = (s: string) => {
    if (!s) return ''
    const parts = s.split('-')
    if (parts.length === 2) return parts[1] + '/' + parts[0]
    return s
  }
  if (f.timeMode === 'all') return 'Tất cả thời gian'
  if (f.timeMode === 'day') {
    if (f.dateFrom && f.dateTo) {
      if (f.dateFrom === f.dateTo) return 'Ngày ' + formatYMD(f.dateFrom)
      return formatYMD(f.dateFrom) + ' → ' + formatYMD(f.dateTo)
    }
    if (f.dateFrom) return 'Từ ' + formatYMD(f.dateFrom)
    if (f.dateTo) return 'Đến ' + formatYMD(f.dateTo)
    return 'Theo ngày'
  }
  if (f.timeMode === 'month') {
    if (f.monthFrom && f.monthTo) {
      if (f.monthFrom === f.monthTo) return 'Tháng ' + formatYM(f.monthFrom)
      return formatYM(f.monthFrom) + ' → ' + formatYM(f.monthTo)
    }
    if (f.monthFrom) return 'Từ T' + formatYM(f.monthFrom)
    if (f.monthTo) return 'Đến T' + formatYM(f.monthTo)
    return 'Theo tháng'
  }
  if (f.timeMode === 'year') {
    if (f.yearFrom && f.yearTo) {
      if (f.yearFrom === f.yearTo) return 'Năm ' + f.yearFrom
      return 'Năm ' + f.yearFrom + ' → ' + f.yearTo
    }
    if (f.yearFrom) return 'Từ năm ' + f.yearFrom
    if (f.yearTo) return 'Đến năm ' + f.yearTo
    return 'Theo năm'
  }
  return 'Tất cả thời gian'
})

function setMindmapTimeMode(mode: 'all' | 'day' | 'month' | 'year') {
  mindmapFilter.value.timeMode = mode
  if (mode === 'day' && !mindmapFilter.value.dateFrom && !mindmapFilter.value.dateTo) {
    mindmapFilter.value.dateFrom = todayIsoStr
    mindmapFilter.value.dateTo = todayIsoStr
  } else if (mode === 'month' && !mindmapFilter.value.monthFrom && !mindmapFilter.value.monthTo) {
    mindmapFilter.value.monthFrom = currentMonthStr
    mindmapFilter.value.monthTo = currentMonthStr
  } else if (mode === 'year' && !mindmapFilter.value.yearFrom && !mindmapFilter.value.yearTo) {
    mindmapFilter.value.yearFrom = currentYearStr
    mindmapFilter.value.yearTo = currentYearStr
  }
}

function shiftMindmapPeriod(dir: number) {
  const f = mindmapFilter.value
  const pad = (n: number) => String(n).padStart(2, '0')
  if (f.timeMode === 'day') {
    const shiftIsoDay = (iso: string) => {
      const base = iso ? new Date(iso + 'T00:00:00') : new Date()
      base.setDate(base.getDate() + dir)
      return base.getFullYear() + '-' + pad(base.getMonth() + 1) + '-' + pad(base.getDate())
    }
    const df = f.dateFrom || f.dateTo || todayIsoStr
    const dt = f.dateTo || f.dateFrom || todayIsoStr
    f.dateFrom = shiftIsoDay(df)
    f.dateTo = shiftIsoDay(dt)
  } else if (f.timeMode === 'month') {
    const shiftIsoMonth = (ym: string) => {
      const [yStr, mStr] = (ym || currentMonthStr).split('-')
      const d = new Date(Number(yStr) || currentDate.getFullYear(), (Number(mStr) || 1) - 1 + dir, 1)
      return d.getFullYear() + '-' + pad(d.getMonth() + 1)
    }
    const mf = f.monthFrom || f.monthTo || currentMonthStr
    const mt = f.monthTo || f.monthFrom || currentMonthStr
    f.monthFrom = shiftIsoMonth(mf)
    f.monthTo = shiftIsoMonth(mt)
  } else if (f.timeMode === 'year') {
    const curY = currentDate.getFullYear()
    const yf = Number(f.yearFrom || f.yearTo || curY) + dir
    const yt = Number(f.yearTo || f.yearFrom || curY) + dir
    f.yearFrom = String(yf)
    f.yearTo = String(yt)
  }
}

function resetMindmapFilters() {
  reviewMindmapModal.value.searchQuery = ''
  reviewMindmapModal.value.companyScope = null
  mindmapFilter.value = {
