    yearTo: '',
    customer: 'Tất cả',
    ncc: 'Tất cả',
    debtStatus: 'Tất cả',
    sortBy: 'dsb_desc'
  }
}

const mindmapViewportRef = ref<HTMLElement | null>(null)
const mindmapStageRef = ref<HTMLElement | null>(null)
const mindmapChapterBarRef = ref<HTMLElement | null>(null)
const mindmapTourActive = ref(false)
const mindmapCameraAnimating = ref(false)
const mindmapSlideIdx = ref(0)
const mindmapSlideDirection = ref<'next' | 'prev'>('next')
const mindmapSlideAutoPlay = ref(false)
