// Lọc danh sách PO độc lập theo mindmapFilter bên trong Review
const mindmapFilteredRows = computed(() => {
  if (Array.isArray(mindmapCompareCustomRows.value) && mindmapCompareCustomRows.value.length > 0) {
    return mindmapCompareCustomRows.value
  }
  const f = mindmapFilter.value
  let list = rows.value

  // 1. Lọc theo Thời gian
  list = list.filter((r: any) => {
    if (f.timeMode === 'all' || !r.created_time) return true
    const d = parseDateStr(r.created_time)
    if (!d) return true
    if (f.timeMode === 'day') {
      if (f.dateFrom && new Date(f.dateFrom) > d) return false
      if (f.dateTo) {
        const to = new Date(f.dateTo)
        to.setHours(23, 59, 59, 999)
        if (to < d) return false
      }
    } else if (f.timeMode === 'month') {
      const rowMonthStr = d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0')
      if (f.monthFrom && f.monthFrom > rowMonthStr) return false
      if (f.monthTo && f.monthTo < rowMonthStr) return false
    } else if (f.timeMode === 'year') {
      const y = d.getFullYear()
      if (f.yearFrom && parseInt(f.yearFrom) > y) return false
      if (f.yearTo && parseInt(f.yearTo) < y) return false
    }
    return true
  })

  // 2. Lọc theo Công ty / Khách hàng
  if (f.customer && f.customer !== 'Tất cả') {
    const target = f.customer.toLowerCase().trim()
    const exactMatch = uniqueCustomers.value.find((c: any) => c.companyName.toLowerCase() === target)
    const targetCode = exactMatch ? String(exactMatch.companyCode || '').toLowerCase() : ''
    list = list.filter((r: any) => {
      const ten = String(r.Ten_cong_ty || '').toLowerCase()
      const tenKh = String(r.Ten_khach_hang || '').toLowerCase()
      const macty = String(r.Ma_cong_ty || '').toLowerCase()
      if (targetCode && macty === targetCode) return true
      return ten.includes(target) || tenKh.includes(target) || macty.includes(target)
    })
  }

  // 3. Lọc theo Nhà cung cấp (NCC)
  if (f.ncc && f.ncc !== 'Tất cả') {
    const targetNcc = f.ncc.toLowerCase().trim()
    list = list.filter((r: any) => String(r.Ten_nha_cung_cap || '').toLowerCase().trim() === targetNcc)
  }

  // 4. Lọc theo Trạng thái Công nợ
  if (f.debtStatus && f.debtStatus !== 'Tất cả') {
    list = list.filter((r: any) => {
      const cn = congNo(r)
      const dtt = daThanhToan(r)
      const dueInfo = getPoDueInfo(r)
      if (f.debtStatus === 'Còn công nợ') return cn > 0
      if (f.debtStatus === 'Quá hạn thanh toán') return cn > 0 && dueInfo.dueStatus === 'qua_han'
      if (f.debtStatus === 'Sắp đến hạn') return cn > 0 && (dueInfo.dueStatus === 'sap_den_han' || dueInfo.dueStatus === 'den_han_hom_nay')
      if (f.debtStatus === 'Chưa thanh toán') return cn > 0 && dtt <= 0
      if (f.debtStatus === 'Thanh toán 1 phần') return cn > 0 && dtt > 0
      if (f.debtStatus === 'Đã tất toán') return cn <= 0
      return true
    })
  }

  return list
})

const mindmapScopeGroups = computed(() => {
  const f = mindmapFilter.value
  let baseGroups: any[] = []

  if (reviewMindmapModal.value.companyScope) {
    const scoped = reviewMindmapModal.value.companyScope
    const scopedKey = getGroupCollapseKey(scoped)
    const matchingRows = mindmapFilteredRows.value.filter((r: any) => {
      const rKey = String(r.Ma_cong_ty || r.Ten_cong_ty || 'Khác')
      return rKey === scopedKey || String(r.Ten_cong_ty || '').trim() === String(scoped.ten_cong_ty || '').trim()
    })
    baseGroups = [
      {
        ...scoped,
        items: matchingRows.length > 0 ? matchingRows : (scoped.items || [])
      }
    ]
  } else {
    const map = new Map<string, any>()
    mindmapFilteredRows.value.forEach((r: any) => {
      const maCty = r.Ma_cong_ty || 'Khác'
      const mstVal = String(r.MST || '').trim()
      if (!map.has(maCty)) {
        map.set(maCty, {
          ma_cong_ty: maCty,
          ten_cong_ty: r.Ten_cong_ty || 'N/A',
          mst: mstVal,
          items: []
        })
      } else if (mstVal && !map.get(maCty).mst) {
        map.get(maCty).mst = mstVal
      }
      map.get(maCty).items.push(r)
    })
    baseGroups = Array.from(map.values())
  }

  // Sắp xếp thứ tự Công ty theo bộ lọc Review
  baseGroups.sort((a, b) => {
    if (f.sortBy === 'margin_desc') return getGroupNetMargin(b) - getGroupNetMargin(a)
    if (f.sortBy === 'debt_desc') return getGroupCongNo(b) - getGroupCongNo(a)
    if (f.sortBy === 'po_desc') return (b.items?.length || 0) - (a.items?.length || 0)
    return getGroupDoanhSoBan(b) - getGroupDoanhSoBan(a)
  })

  const q = (reviewMindmapModal.value.searchQuery || '').toLowerCase().trim()
  if (!q) return baseGroups

  return baseGroups
    .map(g => {
      const matchCompany =
        String(g.ten_cong_ty || '').toLowerCase().includes(q) ||
        String(g.ma_cong_ty || '').toLowerCase().includes(q) ||
        String(getGroupTenKhachHang(g) || '').toLowerCase().includes(q) ||
        String(g.mst || '').toLowerCase().includes(q)
      if (matchCompany) return g
      const matchedItems = (g.items || []).filter((r: any) =>
        String(r.So_PO || '').toLowerCase().includes(q) ||
        String(r.content_of_contract_PO || '').toLowerCase().includes(q) ||
        String(r.Ten_nha_cung_cap || '').toLowerCase().includes(q) ||
        String(r.Ten_khach_hang || '').toLowerCase().includes(q)
      )
      if (matchedItems.length > 0) {
        return { ...g, items: matchedItems }
      }
      return null
    })
    .filter(Boolean)
})

// Khi thay đổi bộ lọc trong Review -> tự động cập nhật nhánh hoặc nhảy về bước 1 của tập kết quả mới
watch(
  [mindmapFilter, () => reviewMindmapModal.value.searchQuery],
  () => {
    if (!reviewMindmapModal.value.show) return
    if (mindmapTourActive.value) {
      applyTourStepAtIndex(0)
    } else {
      const cMap: Record<string, boolean> = {}
      const pMap: Record<string, boolean> = {}
      mindmapScopeGroups.value.slice(0, 2).forEach((g: any, idx: number) => {
        cMap[getGroupCollapseKey(g)] = true
        if (idx === 0 && Array.isArray(g.items) && g.items[0]) {
          const pk = getMindmapPoKey(g.items[0])
          if (pk) pMap[pk] = true
        }
      })
      mindmapExpandedCompanies.value = cMap
      mindmapExpandedPos.value = pMap
    }
  },
  { deep: true }
)

const mindmapTopProfitGroups = computed(() => {
  return [...mindmapScopeGroups.value].sort((a, b) => getGroupNetMargin(b) - getGroupNetMargin(a))
})

const mindmapTopDebtGroups = computed(() => {
  return [...mindmapScopeGroups.value]
    .filter(g => getGroupCongNo(g) > 0)
    .sort((a, b) => getGroupCongNo(b) - getGroupCongNo(a))
})

const mindmapScopeSummary = computed(() => {
  const groups = mindmapScopeGroups.value
  const allRows: any[] = []
  groups.forEach(g => {
    if (Array.isArray(g?.items)) allRows.push(...g.items)
  })

  let dsb = 0
  let netPo = 0
  let tongSauVatVal = 0
  let giaMuaVal = 0
  let tongCpVal = 0
  let grossComVal = 0
  let thueComVal = 0
  let netComVal = 0
  let netMarginVal = 0
  let daThanhToanVal = 0
  let congNoVal = 0
  let unpaidPoCountVal = 0
  let overduePoCountVal = 0
  let dueSoonPoCountVal = 0
  let settledPoCountVal = 0

  const nccMap = new Map<string, { name: string; poCount: number; dsb: number; giaMua: number; netMargin: number; congNo: number }>()

  allRows.forEach(r => {
    const rDsb = doanhSoBan(r)
    const rNp = netPO(r)
    const rSauVat = tongSauVat(r)
    const rGm = giaMua(r)
    const rCp = tongCP(r)
    const rGc = grossCom(r)
    const rThue = thue(r)
    const rNc = netCom(r)
    const rNm = netMargin(r)
    const rPaid = daThanhToan(r)
    const rDebt = congNo(r)

    dsb += rDsb
    netPo += rNp
    tongSauVatVal += rSauVat
    giaMuaVal += rGm
    tongCpVal += rCp
    grossComVal += rGc
    thueComVal += rThue
    netComVal += rNc
    netMarginVal += rNm
    daThanhToanVal += rPaid
    congNoVal += rDebt

    if (rDebt > 0) {
      unpaidPoCountVal++
      const st = getPoDueInfo(r).dueStatus
      if (st === 'qua_han') overduePoCountVal++
      else if (st === 'sap_den_han' || st === 'den_han_hom_nay') dueSoonPoCountVal++
    } else {
      settledPoCountVal++
    }

    const nccName = String(r.Ten_nha_cung_cap || 'Chưa phân loại NCC').trim() || 'Chưa phân loại NCC'
    if (!nccMap.has(nccName)) {
      nccMap.set(nccName, { name: nccName, poCount: 0, dsb: 0, giaMua: 0, netMargin: 0, congNo: 0 })
    }
    const nccEntry = nccMap.get(nccName)!
    nccEntry.poCount++
    nccEntry.dsb += rDsb
    nccEntry.giaMua += rGm
    nccEntry.netMargin += rNm
    nccEntry.congNo += rDebt
  })

  const topNccs = Array.from(nccMap.values())
    .sort((a, b) => b.dsb - a.dsb)
    .map(item => ({
      ...item,
      sharePct: dsb > 0 ? (item.dsb / dsb) * 100 : 0
    }))

  return {
    companyCount: groups.length,
    poCount: allRows.length,
    dsb,
    netPo,
    tongSauVat: tongSauVatVal,
    giaMua: giaMuaVal,
    tongCp: tongCpVal,
    grossCom: grossComVal,
    thueCom: thueComVal,
    netCom: netComVal,
    netComPct: netPo !== 0 ? (netComVal / netPo) * 100 : 0,
    netComDsbPct: dsb !== 0 ? (netComVal / dsb) * 100 : 0,
    netMargin: netMarginVal,
    netMarginPct: netPo !== 0 ? (netMarginVal / netPo) * 100 : 0,
    netMarginDsbPct: dsb !== 0 ? (netMarginVal / dsb) * 100 : 0,
    daThanhToan: daThanhToanVal,
    congNo: congNoVal,
    paidPct: tongSauVatVal > 0 ? (daThanhToanVal / tongSauVatVal) * 100 : 0,
    unpaidPoCount: unpaidPoCountVal,
    overduePoCount: overduePoCountVal,
    dueSoonPoCount: dueSoonPoCountVal,
    settledPoCount: settledPoCountVal,
    topNccs
  }
})

function getMindmapPoKey(r: any): string {
  return String(getPoRowKey(r) || r?.So_PO || r?.id || '')
}

// Chuyển đổi số tiền & phần trăm sang câu đọc Tiếng Việt tự nhiên 100%
function fmtMoneySpeech(val: number): string {
  const n = Math.round(Number(val) || 0)
  if (n === 0) return '0 đồng'
  const abs = Math.abs(n)
  const prefix = n < 0 ? 'âm ' : ''
  const ty = Math.floor(abs / 1_000_000_000)
  const trieu = Math.floor((abs % 1_000_000_000) / 1_000_000)
  const nghin = Math.floor((abs % 1_000_000) / 1_000)
  const parts: string[] = []
  if (ty > 0) parts.push(ty + ' tỷ')
  if (trieu > 0) parts.push(trieu + ' triệu')
  if (ty === 0 && nghin > 0) parts.push(nghin + ' nghìn')
  if (parts.length === 0) return prefix + abs + ' đồng'
  return prefix + parts.join(' ') + ' đồng'
}

function fmtPctSpeech(val: number): string {
  const n = Number(val) || 0
  if (Math.abs(n) < 0.01) return '0 phần trăm'
  const rounded = Math.round(n * 10) / 10
  if (Number.isInteger(rounded)) return rounded + ' phần trăm'
  return String(rounded).replace('.', ' phẩy ') + ' phần trăm'
}

// Tách luồng riêng biệt:
// - Luồng Review Công ty (isMindmapCompanyReviewMode = true): Card Gốc Công ty -> Tỏa thẳng ra các Card PO -> 4 Khối Chi tiết PO (4 chặng trình chiếu, không bị lặp lại Card Công ty ở đầu).
// - Luồng Review Tổng Hệ thống (isMindmapCompanyReviewMode = false): Card Gốc Hệ thống -> Card Công ty All -> Card Công ty riêng -> Card PO All -> Card PO riêng -> 4 Khối Chi tiết PO (6 chặng trình chiếu).
const isMindmapCompanyReviewMode = computed(() => {
  return (
    Boolean(reviewMindmapModal.value.companyScope) ||
    (mindmapFilter.value.customer !== 'Tất cả' && mindmapScopeGroups.value.length === 1)
  )
})

const mindmapActiveCompanyGroup = computed(() => {
  if (!isMindmapCompanyReviewMode.value) return null
  return mindmapScopeGroups.value[0] || reviewMindmapModal.value.companyScope || null
})

// Danh sách các Bước Trình chiếu trên Sơ đồ Ngang / Sơ đồ Dọc (Tự động tách 2 luồng Review Công ty 4 bước vs Review Tổng 6 bước):
const mindmapTourSteps = computed(() => {
  const sum = mindmapScopeSummary.value
  const groups = mindmapScopeGroups.value
  const steps: Array<{
    id: string
    kind: 'root' | 'company-all' | 'company-single' | 'po-all' | 'po-single' | 'po-leaf'
    theme: 'blue' | 'emerald' | 'rose' | 'slate'
    stageBadge: string
    shortLabel: string
    title: string
    subtitle: string
    focusCardId: string
    narrationText: string
    narrationSegments?: Array<{ text: string; focusCardId?: string }>
    companyKey?: string
    poKey?: string
    leafIdx?: number
  }> = []

  // Helper tạo các bước PO (PO All -> PO Riêng -> 4 Phần Chi tiết PO) dùng chung cho cả 2 luồng nhưng đánh số bước theo đúng luồng
  const pushCompanyPoSteps = (g: any, isSingleCompanyFlow: boolean, gIdx = 0) => {
    const cKey = getGroupCollapseKey(g)
    const shortName = getMobileDockCompanyShortName(g)
    const poList = Array.isArray(g?.items) ? g.items : []
    if (!poList.length) return

    const firstPoKey = getMindmapPoKey(poList[0]) || (cKey + '-po-0')
    const poAllStepNum = isSingleCompanyFlow ? '2' : '4'
    const poSingleStepNum = isSingleCompanyFlow ? '3' : '5'
    const poLeafStepNum = isSingleCompanyFlow ? '4' : '6'

    const poSegments: Array<{ text: string; focusCardId?: string }> = [
      {
        text:
          (isSingleCompanyFlow ? 'Bước 2: ' : '') +
          'Thẻ Tất cả đơn hàng của công ty ' + g.ten_cong_ty + ', gồm ' + poList.length + ' đơn hàng.',
        focusCardId: 'po-' + firstPoKey
      }
    ]
    poList.slice(0, 5).forEach((r: any, idx: number) => {
      const pk = getMindmapPoKey(r) || (cKey + '-po-' + idx)
      poSegments.push({
        text: 'Đơn hàng số ' + (r.So_PO || (idx + 1)) + (r.content_of_contract_PO ? (', nội dung ' + r.content_of_contract_PO) : '') + '.',
        focusCardId: 'po-' + pk
      })
    })

    // Card PO All của Công ty
    steps.push({
      id: 'tour-po-all-' + cKey,
      kind: 'po-all',
      companyKey: cKey,
      focusCardId: 'po-' + firstPoKey,
      theme: 'blue',
      stageBadge: isSingleCompanyFlow
        ? (poAllStepNum + '. CARD PO ALL (' + poList.length + ' PO)')
        : (poAllStepNum + '. CARD PO ALL CỦA CTY #' + (gIdx + 1)),
      shortLabel: isSingleCompanyFlow
        ? ('2. Tất cả PO (' + poList.length + ')')
        : ('Tất cả PO (' + poList.length + ') - ' + shortName),
      title: 'Toàn bộ ' + poList.length + ' Đơn hàng PO của ' + g.ten_cong_ty,
      subtitle: 'Tất cả nhánh PO tỏa ra từ Công ty • Tiếp theo sẽ đi sâu vào từng PO và 4 khối chi tiết bên trong',
      narrationText: poSegments.map(s => s.text).join(' '),
      narrationSegments: poSegments
    })

    // Đi qua từng PO của Công ty
    poList.forEach((r: any, rIdx: number) => {
      const pKey = getMindmapPoKey(r) || (cKey + '-po-' + rIdx)
      const poCode = r.So_PO || String(rIdx + 1)
      const contractTitle = String(r.content_of_contract_PO || 'Đơn hàng chưa ghi nội dung hợp đồng').trim()
      const nccName = String(r.Ten_nha_cung_cap || 'chưa gắn nhà cung cấp').trim()
      const statusSpeech = congNo(r) <= 0 && tongSauVat(r) > 0
        ? 'Đã tất toán hết nợ'
        : (getPoDueInfo(r).dueBadgeText || 'Đang còn công nợ')

      // Card PO riêng
      steps.push({
        id: 'tour-po-single-' + pKey,
        kind: 'po-single',
        companyKey: cKey,
        poKey: pKey,
        focusCardId: 'po-' + pKey,
        theme: congNo(r) > 0 ? 'blue' : 'emerald',
        stageBadge: poSingleStepNum + '. CARD PO RIÊNG (' + (rIdx + 1) + '/' + poList.length + ')',
        shortLabel: 'PO #' + poCode,
        title: 'PO #' + poCode + ' — ' + contractTitle,
        subtitle: 'DSB: ' + fmt(doanhSoBan(r)) + ' đ • Sau VAT: ' + fmt(tongSauVat(r)) + ' đ • Còn nợ: ' + fmt(congNo(r)) + ' đ',
        narrationText:
          'Thẻ Đơn hàng riêng thứ ' + (rIdx + 1) + ': Đơn hàng số ' + poCode +
          (r.created_time ? (', ngày ' + fmtDate(r.created_time)) : '') +
          ', nhà cung cấp ' + nccName + ', trạng thái: ' + statusSpeech + '. ' +
          'Tên nội dung chính của đơn hàng là: ' + contractTitle + '. ' +
          'Doanh số bán đạt ' + fmtMoneySpeech(doanhSoBan(r)) + ', tổng sau thuế là ' + fmtMoneySpeech(tongSauVat(r)) + '. ' +
          'Lợi nhuận ròng đạt ' + fmtMoneySpeech(netMargin(r)) + ', tương đương ' + fmtPctSpeech(netMarginPct(r)) + '. ' +
          'Hoa hồng thực nhận là ' + fmtMoneySpeech(netCom(r)) + '. ' +
          'Đã thanh toán ' + fmtMoneySpeech(daThanhToan(r)) + ', công nợ còn lại ' + fmtMoneySpeech(congNo(r)) + '.'
      })

      // Chi tiết từng phần trong PO (Phần 1 -> 4)
      steps.push({
        id: 'tour-po-leaf-' + pKey + '-1',
        kind: 'po-leaf',
        companyKey: cKey,
        poKey: pKey,
        leafIdx: 1,
        focusCardId: 'leaf-' + pKey + '-1',
        theme: 'blue',
        stageBadge: poLeafStepNum + '.1 CHI TIẾT PO #' + poCode + ' (PHẦN 1/4)',
        shortLabel: 'PO #' + poCode + ' • 1. Doanh số',
        title: 'PO #' + poCode + ' → 1. Doanh số & Chi phí',
        subtitle: 'DSB: ' + fmt(doanhSoBan(r)) + ' đ • Sau VAT: ' + fmt(tongSauVat(r)) + ' đ • Giá mua NCC: ' + fmt(giaMua(r)) + ' đ • Tổng CP: ' + fmt(tongCP(r)) + ' đ',
        narrationText:
          'Chi tiết đơn hàng số ' + poCode + ', nội dung ' + contractTitle + ', Phần 1: Doanh số và Chi phí. ' +
          'Doanh số bán là ' + fmtMoneySpeech(doanhSoBan(r)) + '. ' +
          'Tổng tiền sau thuế là ' + fmtMoneySpeech(tongSauVat(r)) + '. ' +
          'Giá mua nhà cung cấp là ' + fmtMoneySpeech(giaMua(r)) + '. ' +
          'Tổng chi phí đơn hàng là ' + fmtMoneySpeech(tongCP(r)) + '.'
      })

      steps.push({
        id: 'tour-po-leaf-' + pKey + '-2',
        kind: 'po-leaf',
        companyKey: cKey,
        poKey: pKey,
        leafIdx: 2,
        focusCardId: 'leaf-' + pKey + '-2',
        theme: 'emerald',
        stageBadge: poLeafStepNum + '.2 CHI TIẾT PO #' + poCode + ' (PHẦN 2/4)',
        shortLabel: 'PO #' + poCode + ' • 2. Lợi nhuận & COM',
        title: 'PO #' + poCode + ' → 2. COM, Thuế & Lợi nhuận',
        subtitle: 'Net Margin: ' + fmt(netMargin(r)) + ' đ (' + pctFmt(netMarginPct(r)) + ') • Net COM: ' + fmt(netCom(r)) + ' đ • Gross COM: ' + fmt(grossCom(r)) + ' đ',
        narrationText:
          'Chi tiết đơn hàng số ' + poCode + ', Phần 2: Hoa hồng, Thuế và Lợi nhuận. ' +
