  // ═══════════════════════════════════════════════════════════════════════════
  // LUỒNG B: REVIEW TỔNG HỆ THỐNG (6 CHẶNG ĐẦY ĐỦ)
  // 1. Card Tổng quan -> 2. Card Công ty All -> 3. Card Công ty riêng -> 4. Card PO All -> 5. Card PO riêng -> 6. Chi tiết PO
  // ═══════════════════════════════════════════════════════════════════════════
  steps.push({
    id: 'tour-root',
    kind: 'root',
    theme: 'blue',
    focusCardId: 'root',
    stageBadge: '1. CARD TỔNG QUAN',
    shortLabel: '1. Tổng quan',
    title: 'Bức tranh Tổng quan Kinh doanh (' + sum.companyCount + ' Cty • ' + sum.poCount + ' PO)',
    subtitle: 'DSB: ' + fmt(sum.dsb) + ' đ • Net Margin: ' + fmt(sum.netMargin) + ' đ (' + pctFmt(sum.netMarginPct) + ') • Công nợ: ' + fmt(sum.congNo) + ' đ',
    narrationText:
      'Bước 1: Thẻ Tổng quan hệ thống. Nội dung chính: Bức tranh Kinh doanh Tổng thể, kỳ ' + mindmapTimeLabel.value + '. ' +
      'Phạm vi gồm ' + sum.companyCount + ' công ty với ' + sum.poCount + ' đơn hàng. ' +
      'Tổng doanh số bán đạt ' + fmtMoneySpeech(sum.dsb) + '. ' +
      'Doanh thu thuần đạt ' + fmtMoneySpeech(sum.netPo) + '. ' +
      'Tổng tiền sau thuế là ' + fmtMoneySpeech(sum.tongSauVat) + '. ' +
      'Giá mua nhà cung cấp là ' + fmtMoneySpeech(sum.giaMua) + ', tổng chi phí ' + fmtMoneySpeech(sum.tongCp) + '. ' +
      'Lợi nhuận ròng đạt ' + fmtMoneySpeech(sum.netMargin) + ', tương đương ' + fmtPctSpeech(sum.netMarginPct) + '. ' +
      'Hoa hồng thực nhận là ' + fmtMoneySpeech(sum.netCom) + '. ' +
      'Khách đã thanh toán ' + fmtMoneySpeech(sum.daThanhToan) + ', đạt ' + fmtPctSpeech(sum.paidPct) + '. ' +
      'Công nợ còn lại là ' + fmtMoneySpeech(sum.congNo) + ' trên ' + sum.unpaidPoCount + ' đơn hàng.'
  })

  if (groups.length > 0) {
    const companySegments: Array<{ text: string; focusCardId?: string }> = [
      {
        text: 'Bước 2: Thẻ Toàn bộ Công ty khách hàng. Toàn cảnh gồm ' + groups.length + ' công ty khách hàng trong phạm vi đang lọc.',
        focusCardId: 'company-' + getGroupCollapseKey(groups[0])
      }
    ]
    groups.slice(0, 3).forEach((g, i) => {
      companySegments.push({
