        focusCardId: 'company-' + getGroupCollapseKey(g)
      })
    })
    companySegments.push({
      text: 'Tiếp theo chúng ta sẽ đi sâu vào từng công ty riêng.',
      focusCardId: 'company-' + getGroupCollapseKey(groups[0])
    })

    // BƯỚC 2: Card Công ty All (Toàn bộ các nhánh Công ty mọc ra từ Gốc)
    steps.push({
      id: 'tour-company-all',
      kind: 'company-all',
      theme: 'blue',
      focusCardId: 'company-' + getGroupCollapseKey(groups[0]),
      stageBadge: '2. CARD CÔNG TY ALL',
      shortLabel: '2. Tất cả Cty (' + groups.length + ')',
      title: 'Toàn cảnh ' + groups.length + ' Công ty Khách hàng trong Hệ thống',
      subtitle: 'Tất cả nhánh Công ty tỏa ra từ Gốc Tổng quan • Tiếp theo sẽ đi sâu vào từng Công ty riêng',
      narrationText: companySegments.map(s => s.text).join(' '),
      narrationSegments: companySegments
    })

    // Lần lượt đi qua từng Công ty: 3. Card Cty riêng -> 4. Card PO All Cty -> 5. Card PO riêng -> 6. Chi tiết 4 phần trong PO
    groups.forEach((g, gIdx) => {
      const cKey = getGroupCollapseKey(g)
      const shortName = getMobileDockCompanyShortName(g)
      const tenKh = getGroupTenKhachHang(g)
      const poList = Array.isArray(g.items) ? g.items : []
      const compCardId = 'company-' + cKey

      // BƯỚC 3: Card Công ty riêng
      steps.push({
        id: 'tour-company-single-' + cKey,
