        stageBadge: '3. CARD CÔNG TY RIÊNG (#' + (gIdx + 1) + '/' + groups.length + ')',
        shortLabel: 'Cty #' + (gIdx + 1) + ': ' + shortName,
        title: '#' + (gIdx + 1) + ' • ' + g.ten_cong_ty,
        subtitle: 'DSB: ' + fmt(getGroupDoanhSoBan(g)) + ' đ • Net Margin: ' + fmt(getGroupNetMargin(g)) + ' đ • Công nợ: ' + fmt(getGroupCongNo(g)) + ' đ (' + poList.length + ' PO)',
        narrationText:
          'Thẻ Công ty riêng hạng ' + (gIdx + 1) + ': Tên công ty là ' + g.ten_cong_ty +
          (tenKh ? (', khách hàng đại diện là ' + tenKh) : '') +
          ', có ' + poList.length + ' đơn hàng. ' +
          'Doanh số bán đạt ' + fmtMoneySpeech(getGroupDoanhSoBan(g)) + ', tổng tiền sau thuế là ' + fmtMoneySpeech(getGroupTongSauVat(g)) + '. ' +
          'Lợi nhuận ròng đạt ' + fmtMoneySpeech(getGroupNetMargin(g)) + ', tương đương ' + fmtPctSpeech(getGroupNetMarginPct(g)) + '. ' +
          'Hoa hồng thực nhận đạt ' + fmtMoneySpeech(getGroupNetCom(g)) + '. ' +
          'Đã thanh toán ' + fmtMoneySpeech(getGroupDaThanhToan(g)) + ', công nợ còn lại là ' + fmtMoneySpeech(getGroupCongNo(g)) + '.'
      })

      pushCompanyPoSteps(g, false, gIdx)
    })
  }

  return steps
})

const currentTourStep = computed(() => {
  const list = mindmapTourSteps.value
  if (!list.length) return null
  const idx = Math.min(list.length - 1, Math.max(0, mindmapSlideIdx.value))
  return list[idx]
})

watch(() => mindmapTourSteps.value.length, (newLen) => {
  if (mindmapSlideIdx.value >= newLen) {
    mindmapSlideIdx.value = Math.max(0, newLen - 1)
  }
})

// ─── HỆ THỐNG THỜI GIAN TỰ CHẠY (CUSTOM TIMER), FOCUS CAMERA CHÍNH XÁC TỪNG CARD & GIỌNG ĐỌC TIẾNG VIỆT CHUẨN (0.9x - 2.0x) ───
function clearMindmapStepTimers() {
  mindmapAutoNextRemainingSec.value = 0
  if (mindmapCountdownInterval) {
    clearInterval(mindmapCountdownInterval)
    mindmapCountdownInterval = null
  }
  if (mindmapVoiceAutoNextTimer) {
    clearTimeout(mindmapVoiceAutoNextTimer)
    mindmapVoiceAutoNextTimer = null
  }
  if (mindmapAutoPlayTimer) {
    clearInterval(mindmapAutoPlayTimer)
    mindmapAutoPlayTimer = null
  }
}

function stopMindmapVoiceSpeech() {
  mindmapSpeechSeqId++
  mindmapVoiceSpeaking.value = false
  clearMindmapStepTimers()
  if (mindmapActiveAudioEl) {
    try {
      mindmapActiveAudioEl.onended = null
      mindmapActiveAudioEl.onerror = null
      mindmapActiveAudioEl.pause()
      mindmapActiveAudioEl.src = ''
    } catch (_) {}
    mindmapActiveAudioEl = null
  }
  if (typeof window !== 'undefined' && 'speechSynthesis' in window) {
    try {
      window.speechSynthesis.cancel()
    } catch (_) {}
  }
}

function getSafeMindmapStepDurationSec(): number {
  const raw = Number(mindmapStepDurationSec.value)
  if (!Number.isFinite(raw) || raw < 1) return 1
  if (raw > 300) return 300
  return Math.round(raw)
}

function adjustMindmapStepDuration(delta: number) {
  const nextVal = Math.min(300, Math.max(1, getSafeMindmapStepDurationSec() + delta))
  mindmapStepDurationSec.value = nextVal
  onMindmapStepDurationChange()
}

function onMindmapStepDurationChange() {
  mindmapStepDurationSec.value = getSafeMindmapStepDurationSec()
  if (mindmapTourActive.value && mindmapSlideAutoPlay.value && !mindmapVoiceSpeaking.value) {
    scheduleAutoNextMindmapStep(mindmapSpeechSeqId)
  }
}

function scheduleAutoNextMindmapStep(seqId: number) {
  clearMindmapStepTimers()
  if (!reviewMindmapModal.value.show || !mindmapTourActive.value || !mindmapSlideAutoPlay.value) return
  if (seqId !== mindmapSpeechSeqId) return

  const waitSec = getSafeMindmapStepDurationSec()
  mindmapAutoNextRemainingSec.value = waitSec

  mindmapCountdownInterval = setInterval(() => {
    if (seqId !== mindmapSpeechSeqId || !mindmapSlideAutoPlay.value || !mindmapTourActive.value) {
      clearMindmapStepTimers()
      return
    }
    if (mindmapAutoNextRemainingSec.value > 1) {
      mindmapAutoNextRemainingSec.value--
    }
  }, 1000)

  mindmapVoiceAutoNextTimer = setTimeout(() => {
    clearMindmapStepTimers()
    if (seqId !== mindmapSpeechSeqId) return
    if (reviewMindmapModal.value.show && mindmapTourActive.value && mindmapSlideAutoPlay.value) {
      nextMindmapSlide()
    }
  }, waitSec * 1000)
}

function pickVerifiedVietnameseBrowserVoice(): SpeechSynthesisVoice | null {
  if (typeof window === 'undefined' || !('speechSynthesis' in window)) return null
  const voices = window.speechSynthesis.getVoices() || []
  const viVoices = voices.filter(v => {
    const lang = String(v.lang || '').toLowerCase()
    const name = String(v.name || '').toLowerCase()
    return (
      lang.startsWith('vi') ||
      name.includes('vietnam') ||
      name.includes('tiếng việt') ||
      name.includes('hoaimy') ||
      name.includes('namminh')
    )
  })
  if (!viVoices.length) return null
  const natural = viVoices.find(v => /natural|online|hoaimy|namminh|google/i.test(v.name))
  return natural || viVoices[0]
}

function normalizeVietnameseSpeechText(raw: string): string {
  return String(raw || '')
    .replace(/\bCard\b/gi, 'Thẻ')
    .replace(/\bPO\b/g, 'đơn hàng')
    .replace(/\bP O\b/g, 'đơn hàng')
    .replace(/\bVAT\b/gi, 'thuế')
    .replace(/\bV A T\b/gi, 'thuế')
    .replace(/\bNet Margin\b/gi, 'lợi nhuận ròng')
    .replace(/\bNet COM\b/gi, 'hoa hồng thực nhận')
    .replace(/\bGross COM\b/gi, 'tổng hoa hồng')
    .replace(/\bNet PO\b/gi, 'doanh thu thuần')
    .replace(/\bNCC\b/g, 'nhà cung cấp')
    .replace(/\s+/g, ' ')
    .trim()
}

function splitVietnameseSpeechChunks(text: string, maxLen = 175): string[] {
  const clean = normalizeVietnameseSpeechText(text)
  if (!clean) return []
  const sentences = clean.split(/(?<=[.!?;])\s+/)
  const chunks: string[] = []
  let current = ''

  const pushLongPart = (part: string) => {
    const subParts = part.split(/(?<=[,:])\s+/)
    for (const sp of subParts) {
      if (!sp) continue
      if ((current ? current + ' ' + sp : sp).length <= maxLen) {
        current = current ? current + ' ' + sp : sp
      } else {
        if (current) chunks.push(current.trim())
        if (sp.length <= maxLen) {
          current = sp
        } else {
          const words = sp.split(' ')
          let wCur = ''
          for (const w of words) {
            if ((wCur ? wCur + ' ' + w : w).length <= maxLen) {
              wCur = wCur ? wCur + ' ' + w : w
            } else {
              if (wCur) chunks.push(wCur.trim())
              wCur = w
            }
          }
          current = wCur
        }
      }
    }
  }

  for (const s of sentences) {
    if (!s) continue
    if ((current ? current + ' ' + s : s).length <= maxLen) {
      current = current ? current + ' ' + s : s
    } else {
      if (current) {
        chunks.push(current.trim())
        current = ''
      }
      pushLongPart(s)
    }
  }
  if (current.trim()) chunks.push(current.trim())
  return chunks
}

function playSingleVietnameseAudioChunk(chunk: string, seqId: number): Promise<boolean> {
  return new Promise(resolve => {
    if (seqId !== mindmapSpeechSeqId || !reviewMindmapModal.value.show || !mindmapTourActive.value || !mindmapVoiceEnabled.value) {
      resolve(false)
      return
    }

    const rate = Math.min(2.5, Math.max(0.7, Number(mindmapVoiceRate.value) || 1.0))
    const localProxyUrl = '/__tts_vi?q=' + encodeURIComponent(chunk)
    const directGoogleViUrl = 'https://translate.googleapis.com/translate_tts?ie=UTF-8&tl=vi&client=tw-ob&q=' + encodeURIComponent(chunk)

    const tryPlayUrl = (url: string, isFallback: boolean) => {
      if (seqId !== mindmapSpeechSeqId) {
        resolve(false)
        return
      }
      const audio = new Audio()
      ;(audio as any).referrerPolicy = 'no-referrer'
      ;(audio as any).preservesPitch = true
      audio.preload = 'auto'
      audio.src = url
      audio.defaultPlaybackRate = rate
      audio.playbackRate = rate
      mindmapActiveAudioEl = audio

      let settled = false
      const finish = (ok: boolean) => {
        if (settled) return
        settled = true
        audio.onended = null
        audio.onerror = null
        if (mindmapActiveAudioEl === audio) {
          mindmapActiveAudioEl = null
        }
        resolve(ok)
      }

      audio.onloadedmetadata = () => {
        audio.playbackRate = Math.min(2.5, Math.max(0.7, Number(mindmapVoiceRate.value) || 1.0))
      }
      audio.onplay = () => {
        audio.playbackRate = Math.min(2.5, Math.max(0.7, Number(mindmapVoiceRate.value) || 1.0))
      }
      audio.onended = () => finish(true)
      audio.onerror = () => {
        if (!isFallback) {
          tryPlayUrl(directGoogleViUrl, true)
        } else {
          finish(false)
        }
      }

      const playPromise = audio.play()
      if (playPromise && typeof playPromise.catch === 'function') {
        playPromise.catch(() => {
          if (!isFallback) {
            tryPlayUrl(directGoogleViUrl, true)
          } else {
            finish(false)
          }
        })
      }
    }

    tryPlayUrl(localProxyUrl, false)
  })
}

async function speakCurrentTourStep() {
  stopMindmapVoiceSpeech()
  if (!reviewMindmapModal.value.show || !mindmapTourActive.value) return

  const seqId = ++mindmapSpeechSeqId
  const step = currentTourStep.value
  if (step?.focusCardId) {
    mindmapActiveReadingCardId.value = step.focusCardId
    focusCameraOnCardById(step.focusCardId)
  } else {
    focusCameraOnTourSpotlight()
  }

  // Nếu đang ở chế độ Trình chiếu không giọng đọc -> đếm ngược theo thời gian cài đặt rồi tự chuyển sang Card tiếp theo
  if (!mindmapVoiceEnabled.value) {
    if (mindmapSlideAutoPlay.value) {
      scheduleAutoNextMindmapStep(seqId)
    }
    return
  }

  if (!step || !step.narrationText) {
    if (mindmapSlideAutoPlay.value) {
      scheduleAutoNextMindmapStep(seqId)
    }
    return
  }

  // Tạo danh sách các phân đoạn đọc kèm ID Card cần Focus khi đọc tới câu đó
  const segQueue: Array<{ chunk: string; focusCardId?: string }> = []
  if (Array.isArray(step.narrationSegments) && step.narrationSegments.length > 0) {
    for (const seg of step.narrationSegments) {
      const subChunks = splitVietnameseSpeechChunks(seg.text, 175)
      for (const ch of subChunks) {
        segQueue.push({ chunk: ch, focusCardId: seg.focusCardId || step.focusCardId })
      }
    }
  } else {
    const subChunks = splitVietnameseSpeechChunks(step.narrationText, 175)
    for (const ch of subChunks) {
      segQueue.push({ chunk: ch, focusCardId: step.focusCardId })
    }
  }

  if (!segQueue.length) {
    if (mindmapSlideAutoPlay.value) {
      scheduleAutoNextMindmapStep(seqId)
    }
    return
  }

  mindmapVoiceSpeaking.value = true
  let playedViaCloudVi = true

  for (const item of segQueue) {
    if (seqId !== mindmapSpeechSeqId || !reviewMindmapModal.value.show || !mindmapTourActive.value || !mindmapVoiceEnabled.value) {
      return
    }
    // Khi đọc tới Card nào -> Focus Camera ngay vào chính Card đó!
    if (item.focusCardId) {
      mindmapActiveReadingCardId.value = item.focusCardId
      focusCameraOnCardById(item.focusCardId)
    }
    const ok = await playSingleVietnameseAudioChunk(item.chunk, seqId)
    if (!ok) {
      playedViaCloudVi = false
      break
    }
  }

  if (seqId !== mindmapSpeechSeqId) return

  if (!playedViaCloudVi) {
    const viVoice = pickVerifiedVietnameseBrowserVoice()
    if (viVoice && typeof window !== 'undefined' && 'speechSynthesis' in window) {
      await new Promise<void>(resolve => {
        const utter = new SpeechSynthesisUtterance(normalizeVietnameseSpeechText(step.narrationText))
        utter.lang = 'vi-VN'
        utter.voice = viVoice
        utter.rate = Math.min(2.5, Math.max(0.7, Number(mindmapVoiceRate.value) || 1.0))
        utter.onend = () => resolve()
        utter.onerror = () => resolve()
        window.speechSynthesis.speak(utter)
      })
    }
  }

  if (seqId !== mindmapSpeechSeqId) return
  mindmapVoiceSpeaking.value = false

  if (mindmapSlideAutoPlay.value && mindmapTourActive.value) {
    scheduleAutoNextMindmapStep(seqId)
  }
}

function replayCurrentTourStepVoice() {
  if (!mindmapVoiceEnabled.value) {
    mindmapVoiceEnabled.value = true
  }
  speakCurrentTourStep()
}

// Bắt đầu hoặc chuyển đổi giữa 2 chế độ: Trình chiếu có giọng đọc (withVoice = true) & Trình chiếu không giọng đọc (withVoice = false)
function startOrSwitchMindmapTourMode(withVoice: boolean) {
  mindmapVoiceEnabled.value = withVoice
  if (!mindmapTourActive.value) {
    startMindmapTour(0)
    return
  }
  mindmapSlideAutoPlay.value = true
  if (withVoice) {
    speakCurrentTourStep()
  } else {
    stopMindmapVoiceSpeech()
    const step = currentTourStep.value
    if (step?.focusCardId) {
      mindmapActiveReadingCardId.value = step.focusCardId
      focusCameraOnCardById(step.focusCardId)
    }
    scheduleAutoNextMindmapStep(mindmapSpeechSeqId)
  }
}

function toggleMindmapVoice() {
  startOrSwitchMindmapTourMode(!mindmapVoiceEnabled.value)
}

function onMindmapVoiceRateChange() {
  const newRate = Math.min(2.5, Math.max(0.7, Number(mindmapVoiceRate.value) || 1.0))
  if (mindmapActiveAudioEl) {
    mindmapActiveAudioEl.defaultPlaybackRate = newRate
    mindmapActiveAudioEl.playbackRate = newRate
  } else if (mindmapTourActive.value && mindmapVoiceEnabled.value) {
    speakCurrentTourStep()
  }
}

// Đồng bộ trạng thái đóng/mở nhánh theo Bước Trình chiếu
function syncBranchesForTourStep(step: any) {
  if (!step) return
  reviewMindmapModal.value.mode = 'hierarchy'
  if (step.kind === 'root' || step.kind === 'company-all' || step.kind === 'company-single') {
    mindmapExpandedCompanies.value = {}
    mindmapExpandedPos.value = {}
  } else if (step.kind === 'po-all' || step.kind === 'po-single') {
    mindmapExpandedCompanies.value = step.companyKey ? { [step.companyKey]: true } : {}
    mindmapExpandedPos.value = {}
  } else if (step.kind === 'po-leaf') {
    mindmapExpandedCompanies.value = step.companyKey ? { [step.companyKey]: true } : {}
    mindmapExpandedPos.value = step.poKey ? { [step.poKey]: true } : {}
  }
}

// Tính tọa độ chuẩn tuyệt đối (unscaled layout coordinates) của một phần tử bên trong Stage — miễn nhiễm 100% với CSS transform & transition
function getElementLayoutBoxInStage(el: HTMLElement, stageEl: HTMLElement): { left: number; top: number; width: number; height: number } {
  let left = 0
  let top = 0
  let cur: HTMLElement | null = el
  while (cur && cur !== stageEl && stageEl.contains(cur)) {
    left += cur.offsetLeft
    top += cur.offsetTop
    cur = cur.offsetParent as HTMLElement | null
  }
  return {
    left,
    top,
    width: Math.max(1, el.offsetWidth || 320),
    height: Math.max(1, el.offsetHeight || 220)
  }
}

function centerStageCameraOnElements(els: HTMLElement[], preferSingleCardZoom = true) {
  const vp = mindmapViewportRef.value
  const st = mindmapStageRef.value
  if (!vp || !st || !els.length) return

  vp.scrollLeft = 0
  vp.scrollTop = 0

  let minLeft = Infinity
  let minTop = Infinity
  let maxRight = -Infinity
  let maxBottom = -Infinity

  els.forEach(el => {
    const b = getElementLayoutBoxInStage(el, st)
    if (b.left < minLeft) minLeft = b.left
    if (b.top < minTop) minTop = b.top
    if (b.left + b.width > maxRight) maxRight = b.left + b.width
    if (b.top + b.height > maxBottom) maxBottom = b.top + b.height
  })

  if (!isFinite(minLeft) || !isFinite(minTop)) return

  const boxW = Math.max(1, maxRight - minLeft)
  const boxH = Math.max(1, maxBottom - minTop)
  const localCenterX = (minLeft + maxRight) / 2
  const localCenterY = (minTop + maxBottom) / 2

  const topPad = 88
  const bottomPad = 44
  const sidePad = 64
  const availW = Math.max(260, vp.clientWidth - sidePad * 2)
  const availH = Math.max(200, vp.clientHeight - topPad - bottomPad)

  const fitZoom = Math.min(availW / boxW, availH / boxH)
  let targetZoom = 1.0
  if (preferSingleCardZoom || els.length === 1) {
    // Khi Focus vào 1 Card đang đọc: phóng rõ ràng (0.85 -> 1.08) để Card nằm ngay chính giữa tầm mắt
    targetZoom = Math.min(1.08, Math.max(0.78, Number(Math.min(1.06, fitZoom * 0.92).toFixed(2))))
  } else {
    targetZoom = Math.min(0.98, Math.max(0.55, Number((fitZoom * 0.9).toFixed(2))))
  }

  const availCenterX = vp.clientWidth / 2
  const availCenterY = topPad + availH / 2

  const stageBaseLeft = st.offsetLeft || 48
  const stageBaseTop = st.offsetTop || 36

  const targetPanX = Math.round(availCenterX - stageBaseLeft - localCenterX * targetZoom)
  const targetPanY = Math.round(availCenterY - stageBaseTop - localCenterY * targetZoom)

  if (mindmapCameraAnimTimer) clearTimeout(mindmapCameraAnimTimer)
  mindmapCameraAnimating.value = true
  reviewMindmapModal.value.zoom = targetZoom
  reviewMindmapModal.value.panX = targetPanX
  reviewMindmapModal.value.panY = targetPanY

  mindmapCameraAnimTimer = setTimeout(() => {
    mindmapCameraAnimating.value = false
  }, 520)

  const bar = mindmapChapterBarRef.value
  if (bar) {
    const activePill = bar.querySelector('.sr-slide-chapter-pill.active') as HTMLElement | null
    if (activePill) {
      activePill.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' })
    }
  }
}

// Focus trực tiếp vào đúng 1 Card cụ thể theo data-tour-card-id khi giọng đọc đọc tới Card đó
function focusCameraOnCardById(cardId: string) {
  if (!cardId) {
    focusCameraOnTourSpotlight()
    return
  }
  const runFocus = () => {
    const st = mindmapStageRef.value
    if (!st) return
    const targetEl = st.querySelector('[data-tour-card-id="' + CSS.escape(cardId) + '"]') as HTMLElement | null
    if (targetEl) {
      centerStageCameraOnElements([targetEl], true)
    } else {
      const spotlights = Array.from(st.querySelectorAll('.is-tour-spotlight')) as HTMLElement[]
      if (spotlights.length > 0) {
        centerStageCameraOnElements([spotlights[0]], true)
      }
    }
  }
  nextTick(() => {
    requestAnimationFrame(() => {
      runFocus()
      // Chạy thêm 1 nhịp ngắn sau khi nhánh con vừa mở ra để đảm bảo tọa độ DOM chính xác 100%
      setTimeout(runFocus, 90)
    })
  })
}

function focusCameraOnTourSpotlight() {
  const step = currentTourStep.value
  if (step?.focusCardId) {
    mindmapActiveReadingCardId.value = step.focusCardId
    focusCameraOnCardById(step.focusCardId)
    return
  }
  nextTick(() => {
    requestAnimationFrame(() => {
      const st = mindmapStageRef.value
      if (!st) return
      const targets = Array.from(st.querySelectorAll('.is-tour-spotlight')) as HTMLElement[]
      if (!targets.length) return
      centerStageCameraOnElements([targets[0]], true)
    })
  })
}

function applyTourStepAtIndex(idx: number) {
  const list = mindmapTourSteps.value
  if (!list.length) return
  const clamped = Math.min(list.length - 1, Math.max(0, idx))
  mindmapSlideDirection.value = clamped >= mindmapSlideIdx.value ? 'next' : 'prev'
  mindmapSlideIdx.value = clamped
  const step = list[clamped]
  mindmapActiveReadingCardId.value = step.focusCardId || ''
  syncBranchesForTourStep(step)
  speakCurrentTourStep()
}

function startMindmapTour(startIdx = 0) {
  if (effectiveMindmapLayout.value === 'tree') {
    reviewMindmapModal.value.layout = 'canvas'
  }
  mindmapTourActive.value = true
  mindmapSlideAutoPlay.value = true
  applyTourStepAtIndex(startIdx)
}

function stopMindmapTour() {
  stopMindmapAutoPlay()
  stopMindmapVoiceSpeech()
  mindmapActiveReadingCardId.value = ''
  mindmapTourActive.value = false
  mindmapCameraAnimating.value = false
}

function toggleMindmapTour() {
  if (mindmapTourActive.value) {
    stopMindmapTour()
  } else {
    startMindmapTour(0)
  }
}

function goToMindmapSlide(targetIdx: number) {
  if (!mindmapTourActive.value) {
    startMindmapTour(targetIdx)
    return
  }
  applyTourStepAtIndex(targetIdx)
}

function nextMindmapSlide() {
  const len = mindmapTourSteps.value.length
  if (len <= 0) return
  if (!mindmapTourActive.value) {
    startMindmapTour(0)
    return
  }
  if (mindmapSlideIdx.value < len - 1) {
    applyTourStepAtIndex(mindmapSlideIdx.value + 1)
  } else if (mindmapSlideAutoPlay.value) {
    applyTourStepAtIndex(0)
  } else {
    stopMindmapVoiceSpeech()
  }
}

function prevMindmapSlide() {
  if (!mindmapTourActive.value) return
  if (mindmapSlideIdx.value > 0) {
    applyTourStepAtIndex(mindmapSlideIdx.value - 1)
  }
}

// Helper classes & visibility cho từng cấp Node khi đang ở chế độ Trình chiếu Sơ đồ (Làm nổi bật chính xác Card đang được đọc)
function getTourRootNodeClass(): string {
  if (!mindmapTourActive.value || !currentTourStep.value) return ''
  if (currentTourStep.value.kind === 'root' || mindmapActiveReadingCardId.value === 'root') {
    return 'is-tour-spotlight is-reading-focus'
  }
  return 'is-tour-context'
}

function getTourCompanyNodeClass(g: any): string {
  if (!mindmapTourActive.value || !currentTourStep.value) return ''
  const st = currentTourStep.value
  const cKey = getGroupCollapseKey(g)
  const cardId = 'company-' + cKey
  if (mindmapActiveReadingCardId.value === cardId) {
    return 'is-tour-spotlight is-reading-focus'
  }
  if (st.kind === 'company-all') return 'is-tour-spotlight'
  if (st.kind === 'company-single') {
    return st.companyKey === cKey ? 'is-tour-spotlight is-reading-focus' : 'is-tour-dimmed'
  }
  if (st.kind === 'po-all' || st.kind === 'po-single' || st.kind === 'po-leaf') {
    return st.companyKey === cKey ? 'is-tour-context' : 'is-tour-dimmed'
  }
  return 'is-tour-dimmed'
}

function getTourPoNodeClass(r: any, g: any): string {
  if (!mindmapTourActive.value || !currentTourStep.value) return ''
  const st = currentTourStep.value
  const cKey = getGroupCollapseKey(g)
  const pKey = getMindmapPoKey(r)
  const cardId = 'po-' + pKey
  if (mindmapActiveReadingCardId.value === cardId) {
    return 'is-tour-spotlight is-reading-focus'
  }
  if (st.kind === 'po-all' && st.companyKey === cKey) return 'is-tour-spotlight'
  if (st.kind === 'po-single') {
    return st.poKey === pKey ? 'is-tour-spotlight is-reading-focus' : 'is-tour-dimmed'
  }
  if (st.kind === 'po-leaf') {
    return st.poKey === pKey ? 'is-tour-context' : 'is-tour-dimmed'
  }
  return 'is-tour-dimmed'
}

function isMindmapLeafVisible(r: any, leafIdx: number): boolean {
  if (!mindmapTourActive.value || !currentTourStep.value) return true
  const st = currentTourStep.value
  const pKey = getMindmapPoKey(r)
  if (st.poKey === pKey && st.kind === 'po-leaf') {
    return (st.leafIdx || 4) >= leafIdx
  }
  return true
}

function getTourLeafNodeClass(r: any, leafIdx: number): string {
  if (!mindmapTourActive.value || !currentTourStep.value) return ''
  const st = currentTourStep.value
  const pKey = getMindmapPoKey(r)
  const cardId = 'leaf-' + pKey + '-' + leafIdx
  if (mindmapActiveReadingCardId.value === cardId) {
    return 'is-tour-spotlight is-reading-focus'
  }
  if (st.kind === 'po-leaf' && st.poKey === pKey) {
    if (st.leafIdx === leafIdx) return 'is-tour-spotlight is-reading-focus'
    if ((st.leafIdx || 0) > leafIdx) return 'is-tour-context'
  }
  return 'is-tour-dimmed'
}

function onMindmapRootCardClick() {
  if (!mindmapTourActive.value) return
  goToMindmapSlide(0)
}

function onMindmapCompanyCardClick(g: any) {
  if (!mindmapTourActive.value) {
    toggleMindmapCompany(g)
    return
  }
  const cKey = getGroupCollapseKey(g)
  const st = currentTourStep.value
  if (st?.kind === 'company-single' && st.companyKey === cKey) {
    const poAllIdx = mindmapTourSteps.value.findIndex(s => s.kind === 'po-all' && s.companyKey === cKey)
    if (poAllIdx >= 0) {
      applyTourStepAtIndex(poAllIdx)
      return
    }
  }
  const singleIdx = mindmapTourSteps.value.findIndex(s => s.kind === 'company-single' && s.companyKey === cKey)
  if (singleIdx >= 0) {
    applyTourStepAtIndex(singleIdx)
  }
}

function onMindmapPoCardClick(r: any, g: any) {
  if (!mindmapTourActive.value) {
    toggleMindmapPo(r)
    return
  }
  const pKey = getMindmapPoKey(r)
  const st = currentTourStep.value
  if (st?.kind === 'po-single' && st.poKey === pKey) {
    const leaf1Idx = mindmapTourSteps.value.findIndex(s => s.kind === 'po-leaf' && s.poKey === pKey && s.leafIdx === 1)
    if (leaf1Idx >= 0) {
      applyTourStepAtIndex(leaf1Idx)
      return
    }
  }
  const poSingleIdx = mindmapTourSteps.value.findIndex(s => s.kind === 'po-single' && s.poKey === pKey)
  if (poSingleIdx >= 0) {
    applyTourStepAtIndex(poSingleIdx)
  }
}

function onMindmapLeafCardClick(r: any, leafIdx: number) {
  if (!mindmapTourActive.value) return
  const pKey = getMindmapPoKey(r)
  const targetIdx = mindmapTourSteps.value.findIndex(s => s.kind === 'po-leaf' && s.poKey === pKey && s.leafIdx === leafIdx)
  if (targetIdx >= 0) {
    applyTourStepAtIndex(targetIdx)
  }
}

function stopMindmapAutoPlay() {
  mindmapSlideAutoPlay.value = false
  clearMindmapStepTimers()
}

function toggleMindmapAutoPlay() {
  if (mindmapSlideAutoPlay.value) {
    stopMindmapAutoPlay()
    return
  }
  mindmapSlideAutoPlay.value = true
  if (!mindmapTourActive.value) {
    startMindmapTour(0)
  } else if (mindmapVoiceEnabled.value && mindmapVoiceSpeaking.value) {
    // Đang đọc dở câu hiện tại -> khi đọc xong sẽ tự đếm ngược và chuyển bước
  } else {
    scheduleAutoNextMindmapStep(mindmapSpeechSeqId)
  }
}

function handleMindmapKeydown(e: KeyboardEvent) {
  if (!reviewMindmapModal.value.show) return
  const tgt = e.target as HTMLElement | null
  if (tgt && (tgt.tagName === 'INPUT' || tgt.tagName === 'TEXTAREA' || tgt.tagName === 'SELECT')) return
  if (mindmapTourActive.value) {
    if (e.key === 'ArrowRight' || e.key === 'PageDown' || e.key === ' ') {
      e.preventDefault()
      nextMindmapSlide()
    } else if (e.key === 'ArrowLeft' || e.key === 'PageUp') {
      e.preventDefault()
      prevMindmapSlide()
    } else if (e.key === 'Home') {
      e.preventDefault()
      goToMindmapSlide(0)
    } else if (e.key === 'End') {
      e.preventDefault()
      goToMindmapSlide(mindmapTourSteps.value.length - 1)
    } else if (e.key === 'Escape') {
      e.preventDefault()
      stopMindmapTour()
    }
  }
}

onMounted(() => {
  if (typeof window !== 'undefined') {
    window.addEventListener('keydown', handleMindmapKeydown)
    if ('speechSynthesis' in window) {
      window.speechSynthesis.getVoices()
    }
  }
})

onUnmounted(() => {
  stopMindmapAutoPlay()
  stopMindmapVoiceSpeech()
  if (mindmapCameraAnimTimer) clearTimeout(mindmapCameraAnimTimer)
  if (typeof window !== 'undefined') {
    window.removeEventListener('keydown', handleMindmapKeydown)
  }
})

watch(() => reviewMindmapModal.value.show, (isOpen) => {
  if (!isOpen) {
    stopMindmapAutoPlay()
    stopMindmapVoiceSpeech()
    mindmapActiveReadingCardId.value = ''
    mindmapTourActive.value = false
    mindmapCompareCustomRows.value = null
    mindmapMobileSheet.value = null
  }
})

function isMindmapCompanyExpanded(g: any): boolean {
  const key = getGroupCollapseKey(g)
  return Boolean(mindmapExpandedCompanies.value[key])
}

function toggleMindmapCompany(g: any) {
  const key = getGroupCollapseKey(g)
  const next = !mindmapExpandedCompanies.value[key]
  mindmapExpandedCompanies.value = {
    ...mindmapExpandedCompanies.value,
    [key]: next
  }
  if (next && Array.isArray(g?.items) && g.items.length === 1) {
    const poKey = getMindmapPoKey(g.items[0])
    if (poKey) {
      mindmapExpandedPos.value = {
        ...mindmapExpandedPos.value,
        [poKey]: true
      }
    }
  }
}

function isMindmapPoExpanded(r: any): boolean {
  const key = getMindmapPoKey(r)
  return Boolean(key && mindmapExpandedPos.value[key])
}

function toggleMindmapPo(r: any) {
  const key = getMindmapPoKey(r)
  if (!key) return
  mindmapExpandedPos.value = {
    ...mindmapExpandedPos.value,
    [key]: !mindmapExpandedPos.value[key]
  }
}

function toggleMindmapPillar(key: 'revenue' | 'profit' | 'debt' | 'ncc') {
  mindmapExpandedPillars.value = {
    ...mindmapExpandedPillars.value,
    [key]: !mindmapExpandedPillars.value[key]
  }
}

function openReviewMindmapModal(group?: any) {
  stopMindmapAutoPlay()
  stopMindmapVoiceSpeech()
  mindmapTourActive.value = false
  mindmapFilterExpanded.value = false
  mindmapMobileSheet.value = null

  // Kế thừa trạng thái bộ lọc hiện tại từ trang chính sang bộ lọc độc lập của Review
  mindmapFilter.value = {
    timeMode: (timeFilterMode.value as any) || 'all',
    dateFrom: dateFrom.value || '',
    dateTo: dateTo.value || '',
    monthFrom: monthFrom.value || '',
    monthTo: monthTo.value || '',
    yearFrom: String(yearFrom.value || ''),
    yearTo: String(yearTo.value || ''),
    customer: group && group.ten_cong_ty ? 'Tất cả' : (filterCustomer.value || 'Tất cả'),
    ncc: filterProductType.value || 'Tất cả',
    debtStatus: filterDebtStatus.value || 'Tất cả',
    sortBy: companySidebarSort.value === 'debt_desc' ? 'debt_desc' : (companySidebarSort.value === 'po_desc' ? 'po_desc' : 'dsb_desc')
  }

  reviewMindmapModal.value = {
    show: true,
    mode: 'hierarchy',
    layout: 'canvas',
    companyScope: group && group.items ? group : null,
    searchQuery: '',
    zoom: 1,
    panX: 0,
    panY: 0,
    isPanning: false,
    startX: 0,
    startY: 0
  }

  nextTick(() => {
    const cMap: Record<string, boolean> = {}
    const pMap: Record<string, boolean> = {}
    const groups = mindmapScopeGroups.value
    if (group && group.items) {
      const gKey = getGroupCollapseKey(group)
      cMap[gKey] = true
      group.items.slice(0, 3).forEach((r: any) => {
        const pk = getMindmapPoKey(r)
        if (pk) pMap[pk] = true
      })
    } else {
      groups.slice(0, 2).forEach((g: any, idx: number) => {
        cMap[getGroupCollapseKey(g)] = true
        if (idx === 0 && Array.isArray(g.items) && g.items[0]) {
          const pk = getMindmapPoKey(g.items[0])
          if (pk) pMap[pk] = true
        }
      })
    }
    mindmapSlideIdx.value = 0
    mindmapSlideDirection.value = 'next'
    mindmapExpandedCompanies.value = cMap
    mindmapExpandedPos.value = pMap
    resetMindmapViewport()
  })
}

function clearMindmapCompanyScope() {
  reviewMindmapModal.value.companyScope = null
  mindmapSlideIdx.value = 0
  if (mindmapTourActive.value) {
    applyTourStepAtIndex(0)
    return
  }
  const cMap: Record<string, boolean> = {}
  mindmapScopeGroups.value.slice(0, 2).forEach((g: any) => {
    cMap[getGroupCollapseKey(g)] = true
  })
  mindmapExpandedCompanies.value = cMap
  resetMindmapViewport()
}

function focusMindmapCompany(g: any) {
  if (!g) return
  reviewMindmapModal.value.companyScope = g
  reviewMindmapModal.value.mode = 'hierarchy'
  mindmapSlideIdx.value = 0
  if (mindmapTourActive.value) {
    applyTourStepAtIndex(0)
    return
  }
  const cMap: Record<string, boolean> = { [getGroupCollapseKey(g)]: true }
  const pMap: Record<string, boolean> = {}
  ;(g.items || []).slice(0, 3).forEach((r: any) => {
    const pk = getMindmapPoKey(r)
    if (pk) pMap[pk] = true
  })
  mindmapExpandedCompanies.value = cMap
  mindmapExpandedPos.value = pMap
  resetMindmapViewport()
}

function expandAllMindmapNodes() {
  const cMap: Record<string, boolean> = {}
  const pMap: Record<string, boolean> = {}
  mindmapScopeGroups.value.forEach(g => {
    cMap[getGroupCollapseKey(g)] = true
    ;(g.items || []).forEach((r: any) => {
      const pk = getMindmapPoKey(r)
      if (pk) pMap[pk] = true
    })
  })
  mindmapExpandedCompanies.value = cMap
  mindmapExpandedPos.value = pMap
  mindmapExpandedPillars.value = { revenue: true, profit: true, debt: true, ncc: true }
}

function collapseAllMindmapNodes() {
  mindmapExpandedCompanies.value = {}
  mindmapExpandedPos.value = {}
  mindmapExpandedPillars.value = { revenue: false, profit: false, debt: false, ncc: false }
  resetMindmapViewport()
}

function switchMindmapLayout(nextLayout: 'canvas' | 'vcanvas' | 'tree') {
  reviewMindmapModal.value.layout = nextLayout
  if (nextLayout === 'tree') {
    stopMindmapTour()
    return
  }
  if (mindmapTourActive.value) {
    focusCameraOnTourSpotlight()
  } else {
    resetMindmapViewport()
  }
}

function resetMindmapViewport() {
  reviewMindmapModal.value.zoom = 1
  reviewMindmapModal.value.panX = 0
  reviewMindmapModal.value.panY = 0
  nextTick(() => {
    const vp = mindmapViewportRef.value
    const st = mindmapStageRef.value
    if (!vp || !st) return
    if (mindmapTourActive.value) {
      focusCameraOnTourSpotlight()
      return
    }
    if (effectiveMindmapLayout.value === 'vcanvas') {
      vp.scrollTop = 0
      vp.scrollLeft = 0
      const rootNode = st.querySelector('.is-root-node') as HTMLElement | null
      if (rootNode) {
        const vpRect = vp.getBoundingClientRect()
        const stRect = st.getBoundingClientRect()
        const rRect = rootNode.getBoundingClientRect()
        const rCenterX = (rRect.left + rRect.right) / 2 - stRect.left
        reviewMindmapModal.value.panX = Math.round(vpRect.width / 2 - (stRect.left - vpRect.left) - rCenterX)
      }
    } else if (effectiveMindmapLayout.value === 'canvas') {
      vp.scrollLeft = 0
      vp.scrollTop = Math.max(0, Math.round((st.offsetHeight - vp.clientHeight) / 2))
    }
  })
}

function adjustMindmapZoom(delta: number) {
  const next = Math.min(1.6, Math.max(0.45, Number((reviewMindmapModal.value.zoom + delta).toFixed(2))))
  reviewMindmapModal.value.zoom = next
}

function onMindmapPointerDown(e: MouseEvent) {
  if (e.button !== 0) return
  const tgt = e.target as HTMLElement | null
  if (tgt && tgt.closest('button, input, a, select')) return
  mindmapCameraAnimating.value = false
  reviewMindmapModal.value.isPanning = true
  reviewMindmapModal.value.startX = e.clientX - reviewMindmapModal.value.panX
  reviewMindmapModal.value.startY = e.clientY - reviewMindmapModal.value.panY
}

function onMindmapPointerMove(e: MouseEvent) {
  if (!reviewMindmapModal.value.isPanning) return
  reviewMindmapModal.value.panX = e.clientX - reviewMindmapModal.value.startX
  reviewMindmapModal.value.panY = e.clientY - reviewMindmapModal.value.startY
}

function onMindmapPointerUp() {
  reviewMindmapModal.value.isPanning = false
}

function onMindmapTouchStart(e: TouchEvent) {
  if (e.touches.length !== 1) return
  const tgt = e.target as HTMLElement | null
  if (tgt && tgt.closest('button, input, a, select')) return
  mindmapCameraAnimating.value = false
  reviewMindmapModal.value.isPanning = true
  reviewMindmapModal.value.startX = e.touches[0].clientX - reviewMindmapModal.value.panX
  reviewMindmapModal.value.startY = e.touches[0].clientY - reviewMindmapModal.value.panY
}

function onMindmapTouchMove(e: TouchEvent) {
  if (!reviewMindmapModal.value.isPanning || e.touches.length !== 1) return
  reviewMindmapModal.value.panX = e.touches[0].clientX - reviewMindmapModal.value.startX
  reviewMindmapModal.value.panY = e.touches[0].clientY - reviewMindmapModal.value.startY
}

function onMindmapTouchEnd() {
  reviewMindmapModal.value.isPanning = false
}

function onMindmapWheel(e: WheelEvent) {
  mindmapCameraAnimating.value = false
  const delta = e.deltaY < 0 ? 0.08 : -0.08
  adjustMindmapZoom(delta)
}

function openCompanyChartFromMindmap(g: any) {
  reviewMindmapModal.value.show = false
  openCompanyChart(g, 'doanhSoBan', false, 'revenue')
}

function openChartFromMindmap() {
  const scoped = reviewMindmapModal.value.companyScope
  reviewMindmapModal.value.show = false
  if (scoped) {
    openCompanyChart(scoped, 'doanhSoBan', false, 'revenue')
  } else {
    openChart('doanhSoBan', false, 'revenue')
  }
}

const isAnySaleModalOpen = computed(() => Boolean(
  reviewMindmapModal.value.show ||
  showCraftCompareModal.value ||
  poGoodsDbSyncModal.value.show ||
  goodsDbLoadingModal.value.show ||
  showAddChoiceModal.value ||
  showFilterCustomerModal.value ||
  showFilterNccModal.value ||
  showExportModal.value ||
  showYearModal.value ||
  multiEditModal.show ||
  paymentModal.show ||
  chartModal.show ||
  editModal.show ||
  dbCustomerDetailModal.show ||
  recipientPickerModal.show ||
  industryPickerModal.show ||
  customerGroupPickerModal.value?.show ||
  srDialog.show
))
</script>

