/* TAB 2: HIGH-DENSITY GOODS TABLE */
.sr-po-goods-pane {
  display: flex;
  flex-direction: column;
  gap: 10px;
  flex: 1;
  min-height: 0;
}

.sr-po-goods-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 10px;
}

.sr-po-goods-subtitle {
  font-size: 12px;
  font-weight: 700;
  color: #94a3b8;
}

.sr-po-goods-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.sr-po-goods-sync-btn {
  padding: 6px 12px;
  border-radius: 8px;
  border: 1px solid rgba(56, 189, 248, 0.4);
  background: rgba(56, 189, 248, 0.14);
  color: #38bdf8;
  font-size: 11.5px;
  font-weight: 700;
  cursor: pointer;
}

.sr-po-goods-add-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 13px;
  background: rgba(16, 185, 129, 0.16);
  color: #34d399;
  border: 1px solid rgba(16, 185, 129, 0.42);
  border-radius: 8px;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
}

.sr-po-goods-table-wrap {
  flex: 1;
  overflow: auto;
  border: 1px solid rgba(51, 65, 85, 0.85);
  border-radius: 10px;
  background: rgba(9, 14, 26, 0.72);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.03);
}

.sr-po-goods-table {
  width: 100%;
  table-layout: fixed;
  border-collapse: collapse;
  font-size: 12px;
  color: #e2e8f0;
  min-width: 980px;
}

.sr-po-goods-table thead th {
  position: sticky;
  top: 0;
  z-index: 5;
  background: #0f172a;
  border-bottom: 1px solid rgba(52, 211, 153, 0.32);
  border-right: 1px solid rgba(51, 65, 85, 0.45);
  padding: 9px 6px;
  font-size: 10.5px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.02em;
  color: #cbd5e1;
  text-align: left;
  white-space: nowrap;
  box-sizing: border-box;
}

.sr-po-goods-table thead th:last-child {
  border-right: none;
}

.sr-po-goods-table th.text-center,
.sr-po-goods-table td.text-center {
  text-align: center !important;
}

.sr-po-goods-table th.text-right,
.sr-po-goods-table td.text-right {
  text-align: right !important;
}

.sr-po-goods-table th.text-left,
.sr-po-goods-table td.text-left {
  text-align: left !important;
}

.sr-po-goods-empty {
  padding: 32px 14px;
  text-align: center;
  color: #64748b;
  font-size: 12.5px;
}

.sr-po-goods-cat-row td {
  padding: 0;
  background: linear-gradient(90deg, rgba(2, 132, 199, 0.28), rgba(15, 23, 42, 0.92));
  border-bottom: 1px solid rgba(56, 189, 248, 0.32);
}

.sr-po-goods-cat-row input {
  width: 100%;
  box-sizing: border-box;
  padding: 8px 12px;
  background: transparent;
  color: #38bdf8;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  border: none;
  font-size: 12px;
  outline: none;
}

.sr-po-goods-row {
  border-bottom: 1px solid rgba(51, 65, 85, 0.55);
  transition: background 0.14s ease;
}

.sr-po-goods-row:hover {
  background: rgba(16, 185, 129, 0.04);
}

.sr-po-goods-row td {
  padding: 7px 6px;
  vertical-align: top;
  border-right: 1px solid rgba(51, 65, 85, 0.35);
  box-sizing: border-box;
}

.sr-po-goods-row td:last-child {
  border-right: none;
}

.sr-po-goods-row td.is-stt {
  font-weight: 800;
  color: #94a3b8;
  font-variant-numeric: tabular-nums;
  padding-top: 12px;
}

.sr-po-goods-row td.is-mono-cell {
  padding-top: 12px;
  padding-right: 10px;
}

.sr-goods-textarea {
  width: 100%;
  box-sizing: border-box;
  min-height: 46px !important;
  padding: 6px 8px !important;
  font-size: 12px !important;
  line-height: 1.4;
  resize: vertical;
}

.sr-goods-textarea.is-name {
  font-weight: 700;
}

.sr-goods-textarea.is-desc {
  color: #cbd5e1 !important;
  font-size: 12px !important;
}

.sr-goods-cell-input {
  width: 100% !important;
  box-sizing: border-box;
  height: 33px !important;
  padding: 4px 6px !important;
  font-size: 12px !important;
}

.sr-goods-price-input {
  width: 100% !important;
  box-sizing: border-box;
  height: 33px !important;
  padding: 4px 8px !important;
  color: #fbbf24 !important;
  font-family: 'JetBrains Mono', monospace;
  font-variant-numeric: tabular-nums;
  font-weight: 700;
  font-size: 12px !important;
}

.is-mono-cell {
  font-family: 'JetBrains Mono', monospace;
  font-variant-numeric: tabular-nums;
  font-weight: 700;
  font-size: 12.5px;
}

.is-emerald-cell {
  color: #34d399;
}

.sr-goods-vat-group {
  display: grid;
  grid-template-columns: 58px minmax(0, 1fr);
  gap: 4px;
  align-items: center;
  width: 100%;
}

.sr-goods-vat-pct-box {
  display: flex;
  align-items: center;
  background: rgba(15, 23, 42, 0.78);
  border: 1px solid rgba(51, 65, 85, 0.85);
  border-radius: 7px;
  height: 33px;
  padding: 0 5px 0 2px;
  box-sizing: border-box;
}

.sr-goods-vat-pct-input {
  width: 100%;
  border: none !important;
  background: transparent !important;
  color: #f8fafc;
  font-family: 'JetBrains Mono', monospace;
  font-size: 11.5px;
  font-weight: 700;
  padding: 0 2px !important;
  outline: none;
}

.sr-goods-vat-pct-unit {
  font-size: 10.5px;
  font-weight: 700;
  color: #94a3b8;
  flex-shrink: 0;
}

.sr-goods-vat-amt-input {
  width: 100% !important;
  box-sizing: border-box;
  height: 33px !important;
  padding: 4px 6px !important;
  font-family: 'JetBrains Mono', monospace;
  font-variant-numeric: tabular-nums;
  font-size: 11.5px !important;
  font-weight: 700;
}

.sr-goods-del-btn {
  width: 28px;
  height: 28px;
  margin-top: 2px;
  border-radius: 6px;
  background: rgba(239, 68, 68, 0.12);
  border: 1px solid rgba(239, 68, 68, 0.28);
  color: #ef4444;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: all 0.15s ease;
}

.sr-goods-del-btn:hover {
  background: rgba(239, 68, 68, 0.25);
  color: #ffffff;
}

.sr-po-goods-tfoot td {
  position: sticky;
  bottom: 0;
  z-index: 4;
  background: #0d261f;
  border-top: 1.5px solid rgba(52, 211, 153, 0.45);
  border-right: 1px solid rgba(52, 211, 153, 0.16);
  padding: 10px 8px;
  font-weight: 800;
  color: #34d399;
  font-family: 'JetBrains Mono', monospace;
  font-variant-numeric: tabular-nums;
  box-sizing: border-box;
}

.sr-po-goods-tfoot td:last-child {
  border-right: none;
}

.sr-po-goods-tfoot td.is-grand {
  font-size: 13px;
  color: #6ee7b7;
}

/* UPLOAD MODE CHOICE MODAL */
.sr-upload-mode-choice-modal {
  max-width: 660px !important;
}

.sr-upload-mode-file-pill {
  margin-top: 8px;
