/* 5. STICKY BOTTOM FOOTER */
.sr-po-modal-footer {
  padding: 12px 22px !important;
  border-top: 1px solid rgba(52, 211, 153, 0.24) !important;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  background: rgba(9, 18, 15, 0.98) !important;
  border-radius: 0 !important;
  flex-shrink: 0;
}

.sr-po-footer-left,
.sr-po-footer-right {
  flex: 1;
  display: flex;
  align-items: center;
  gap: 10px;
}

.sr-po-footer-right {
  justify-content: flex-end;
}

.sr-po-footer-center {
  flex: 1.2;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 10px;
}

.sr-po-btn-lbl-mob,
.sr-po-btn-cancel.is-mob-inline-close {
