  font-weight: 700;
  color: #6ee7b7;
  opacity: 0.85;
}

.sr-po-btn-delete {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  height: 38px;
  padding: 0 15px;
  border-radius: 9px;
  border: 1px solid rgba(239, 68, 68, 0.55);
  background: rgba(239, 68, 68, 0.16);
  color: #fca5a5;
  font-size: 12.5px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.18s ease;
  white-space: nowrap;
}

.sr-po-btn-delete:hover {
  background: #dc2626;
  border-color: #ef4444;
  color: #ffffff;
  box-shadow: 0 4px 12px rgba(220, 38, 38, 0.35);
}

.sr-po-btn-save {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  height: 38px;
  padding: 0 22px;
  min-width: 175px;
  border-radius: 9px;
  border: 1px solid #60a5fa;
  background: linear-gradient(135deg, #0284c7 0%, #2563eb 100%);
  color: #ffffff;
  font-size: 12.5px;
  font-weight: 800;
  letter-spacing: 0.03em;
  box-shadow: 0 6px 16px -4px rgba(37, 99, 235, 0.45);
  cursor: pointer;
  transition: all 0.18s ease;
  white-space: nowrap;
}

.sr-po-btn-save:hover:not(:disabled) {
  transform: translateY(-1px);
  filter: brightness(1.08);
  box-shadow: 0 8px 20px -4px rgba(37, 99, 235, 0.55);
}

.sr-po-btn-cancel {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 38px;
  padding: 0 20px;
  border-radius: 9px;
  border: 1px solid #475569;
  background: #1e293b;
  color: #e2e8f0;
  font-size: 12.5px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.18s ease;
  white-space: nowrap;
}

.sr-po-btn-cancel:hover {
  border-color: #94a3b8;
  color: #ffffff;
  background: #334155;
}

/* Modal Chọn Năm Import Report (.sr-year-modal) */
.sr-year-modal {
  width: 100%;
  max-width: 440px;
  background: linear-gradient(165deg, #0d1f1a 0%, #081310 100%);
  border: 1px solid rgba(52, 211, 153, 0.35);
  border-radius: 16px;
  box-shadow: 0 24px 56px rgba(0, 0, 0, 0.72);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  font-family: 'Inter', 'Plus Jakarta Sans', system-ui, sans-serif;
}

.sr-year-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 13px 18px;
  background: linear-gradient(90deg, #059669 0%, #047857 55%, #0f766e 100%);
  color: #ffffff;
}

.sr-year-modal-head-left {
  display: flex;
  align-items: center;
  gap: 10px;
}

.sr-year-modal-icon {
  width: 30px;
  height: 30px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.2);
  border: 1px solid rgba(255, 255, 255, 0.35);
  color: #ffffff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.sr-year-modal-title {
  margin: 0;
  font-size: 14px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: #ffffff;
}

.sr-year-modal-body {
  padding: 18px 20px;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.sr-year-modal-desc {
  margin: 0;
  font-size: 13px;
  line-height: 1.5;
  color: #cbd5e1;
}

.sr-year-modal-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.sr-year-modal-label {
  font-size: 11.5px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: #6ee7b7;
}

.sr-year-modal-select {
  width: 100%;
  height: 40px;
  padding: 0 12px;
  border-radius: 10px;
  border: 1px solid rgba(52, 211, 153, 0.35);
  background: rgba(15, 29, 25, 0.9);
  color: #f8fafc;
  font-size: 13.5px;
  font-weight: 700;
  outline: none;
}

.sr-year-modal-footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 10px;
  padding: 12px 20px;
  border-top: 1px solid rgba(52, 211, 153, 0.18);
  background: rgba(9, 18, 15, 0.9);
}

.sr-year-btn-confirm {
  min-width: 150px;
  height: 36px;
  padding: 0 18px;
  font-size: 12.5px;
}

/* ─── 4. Phương án A — 4 Card Phẳng (.sr-super-bento-grid) ─── */
.sr-super-bento-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
  margin-bottom: 18px;
}

.sr-sb-card {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 12px;
  padding: 16px 18px 14px;
  border-radius: 14px;
  background: linear-gradient(165deg, rgba(14, 28, 24, 0.96) 0%, rgba(9, 18, 15, 0.98) 100%);
  border: 1px solid rgba(52, 211, 153, 0.25);
  box-shadow: 0 10px 24px -8px rgba(0, 0, 0, 0.48);
  transition: transform 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease;
  overflow: hidden;
}

.sr-sb-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 3px;
  background: linear-gradient(90deg, #10b981 0%, #34d399 100%);
}

.sr-sb-card.sb-card-debt::before {
  background: linear-gradient(90deg, #ef4444 0%, #10b981 100%);
}

.sr-sb-card:hover {
  transform: translateY(-2px);
  border-color: rgba(52, 211, 153, 0.5);
  box-shadow: 0 14px 30px -8px rgba(5, 150, 105, 0.25);
}

/* Tầng 1: Header (Tên chỉ số + 3 nút gọn) */
.sr-sb-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.sr-sb-title-cluster {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.sr-sb-icon {
  width: 28px;
  height: 28px;
  border-radius: 8px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  background: rgba(16, 185, 129, 0.16);
  border: 1px solid rgba(52, 211, 153, 0.32);
  color: #34d399;
}

.sr-sb-icon.is-red {
  background: rgba(239, 68, 68, 0.16);
  border-color: rgba(248, 113, 113, 0.36);
  color: #f87171;
}

.sr-sb-title {
  margin: 0;
  font-size: 13px;
  font-weight: 700;
  color: #cbd5e1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.sr-sb-quick-acts {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
}

.sr-sb-act-pill {
  height: 22px;
  padding: 0 7px;
  border-radius: 6px;
  font-size: 10.5px;
  font-weight: 700;
  background: rgba(16, 185, 129, 0.1);
  border: 1px solid rgba(52, 211, 153, 0.25);
  color: #6ee7b7;
  cursor: pointer;
  transition: all 0.15s ease;
  white-space: nowrap;
}

.sr-sb-act-pill:hover {
  background: #059669;
  border-color: #34d399;
  color: #ffffff;
}

/* Tầng 2: 1 Con số chính duy nhất (Phẳng, không đóng hộp) */
.sr-sb-main {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  padding: 2px 0;
  cursor: pointer;
  flex-wrap: wrap;
}

.sr-sb-hero-val {
  font-family: 'JetBrains Mono', monospace;
  font-size: 22px;
  font-weight: 800;
  line-height: 1.2;
  letter-spacing: -0.02em;
}

.sr-sb-unit {
  font-size: 11px;
  font-weight: 700;
  opacity: 0.72;
  margin-left: 3px;
}

/* Bảng màu số tiền — DARK MODE (Ưu tiên Xanh lá cây) */
.money-white {
  color: #ffffff;
}

.money-green {
  color: #34d399;
}

.money-blue {
  color: #6ee7b7;
}

.money-red {
  color: #f87171;
}

.sr-sb-trend {
  display: inline-flex;
  align-items: center;
  padding: 2px 7px;
  border-radius: 999px;
  font-size: 10.5px;
  font-weight: 700;
  font-family: 'JetBrains Mono', monospace;
  background: rgba(148, 163, 184, 0.14);
  color: #cbd5e1;
}

.sr-sb-trend.up {
  background: rgba(16, 185, 129, 0.18);
  color: #6ee7b7;
}

.sr-sb-trend.down {
  background: rgba(239, 68, 68, 0.18);
  color: #fca5a5;
}

.sr-sb-po-badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 10.5px;
  font-weight: 700;
  font-family: 'JetBrains Mono', monospace;
  cursor: pointer;
  border: 1px solid transparent;
  transition: all 0.15s ease;
}

.sr-sb-po-badge.is-red {
  background: rgba(239, 68, 68, 0.18);
  border-color: rgba(248, 113, 113, 0.4);
  color: #fca5a5;
}

.sr-sb-po-badge.is-emerald {
  background: rgba(16, 185, 129, 0.18);
  border-color: rgba(52, 211, 153, 0.4);
  color: #6ee7b7;
}

/* Tầng 3: 2 dòng chữ phụ phẳng (ngăn cách bằng 1 đường kẻ mảnh) */
.sr-sb-foot {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding-top: 10px;
  border-top: 1px solid rgba(52, 211, 153, 0.16);
  margin-top: auto;
}

.sr-sb-foot-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font-size: 12px;
  padding: 2px 4px;
  margin: 0 -4px;
  border-radius: 6px;
  cursor: pointer;
  transition: background 0.15s ease;
}

.sr-sb-foot-row:hover {
  background: rgba(16, 185, 129, 0.1);
}

.sr-sb-foot-label {
  color: #94a3b8;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.sr-sb-foot-val {
  font-family: 'JetBrains Mono', monospace;
  font-size: 12.5px;
  font-weight: 800;
  white-space: nowrap;
}

.sr-sb-foot-val small {
  font-size: 10.5px;
  font-weight: 600;
  opacity: 0.78;
}

.sr-sb-sep {
  opacity: 0.45;
  margin: 0 3px;
}

.sr-sb-overdue-inline {
  color: #fbbf24;
  font-weight: 700;
  margin-left: 3px;
}

/* Thanh tiến độ mảnh 4px sát đáy Card 4 */
.sr-sb-bottom-progress {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 4px;
  background: rgba(148, 163, 184, 0.15);
  overflow: hidden;
}

.sr-sb-bottom-progress-fill {
  height: 100%;
  background: linear-gradient(90deg, #059669 0%, #34d399 100%);
  transition: width 0.35s ease;
}

/* ─── 5. Bento Customer Group Banner & Compact PO Card (Phương án A + Nút Thu Gọn) ─── */
.sr-list-control-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 14px;
  margin-bottom: 14px;
  border-radius: 12px;
  background: rgba(9, 22, 24, 0.85);
  border: 1px solid rgba(52, 211, 153, 0.24);
  flex-wrap: wrap;
}

.sr-list-ctrl-left {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.sr-list-ctrl-title {
  font-size: 13px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: #ecfdf5;
}

.sr-list-ctrl-badge {
  padding: 2px 10px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  background: rgba(16, 185, 129, 0.16);
  border: 1px solid rgba(52, 211, 153, 0.35);
  color: #6ee7b7;
}

.sr-list-ctrl-right {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.sr-list-ctrl-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 32px;
  padding: 0 12px;
  border-radius: 8px;
  border: 1px solid rgba(52, 211, 153, 0.32);
  background: rgba(15, 23, 42, 0.78);
  color: #6ee7b7;
  font-size: 11.5px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.16s ease;
}

.sr-list-ctrl-btn:hover {
  background: rgba(16, 185, 129, 0.18);
  border-color: #34d399;
  color: #ffffff;
}

.sr-list-ctrl-btn.active {
  background: linear-gradient(135deg, #059669 0%, #10b981 100%);
  border-color: #34d399;
  color: #ffffff;
}

/* Chuyển đổi chế độ xem (2 Cột Master-Detail | Danh sách dọc) */
.sr-view-mode-pills {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 3px;
  border-radius: 10px;
  background: rgba(6, 16, 18, 0.85);
  border: 1px solid rgba(52, 211, 153, 0.28);
}

.sr-view-mode-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 28px;
  padding: 0 11px;
  border-radius: 7px;
  border: 1px solid transparent;
  background: transparent;
  color: #94a3b8;
  font-size: 11.5px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.16s ease;
}

.sr-view-mode-btn:hover {
  color: #ecfdf5;
  background: rgba(16, 185, 129, 0.12);
}

.sr-view-mode-btn.active {
  background: linear-gradient(135deg, #059669 0%, #10b981 100%);
  border-color: rgba(110, 231, 183, 0.55);
  color: #ffffff;
  box-shadow: 0 3px 10px -2px rgba(16, 185, 129, 0.45);
}

/* ─── BỐ CỤC 2 CỘT TỈ LỆ 3 : 7 & HEADER NỔI BẬT ─── */
.sr-list-ctrl-plain-meta {
  font-size: 12.5px;
  font-weight: 500;
  color: #94a3b8;
}

.sr-workspace-layout.is-master-detail {
  display: grid;
  grid-template-columns: minmax(0, 3fr) minmax(0, 7fr);
  gap: 18px;
  align-items: start;
}

.sr-md-sidebar {
  position: sticky;
  top: 14px;
  height: calc(100vh - 28px);
  max-height: calc(100vh - 28px);
  min-width: 0;
  width: 100%;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  border-radius: 14px;
  background: rgba(11, 20, 28, 0.96);
  border: 1px solid rgba(52, 211, 153, 0.26);
  box-shadow: 0 12px 30px -10px rgba(0, 0, 0, 0.5);
  overflow: visible;
  z-index: 25;
}

.sr-md-sidebar.is-stacked-filter-bar {
  position: relative;
  top: 0;
  height: auto;
  max-height: none;
  margin-bottom: 16px;
}

.sr-md-sidebar-head {
  flex: 0 0 auto;
  flex-shrink: 0;
  min-width: 0;
  width: 100%;
  box-sizing: border-box;
  position: relative;
  z-index: 30;
  padding: 12px 13px 10px;
  border-radius: 13px 13px 0 0;
  border-bottom: 1px solid rgba(52, 211, 153, 0.36);
  background: linear-gradient(135deg, rgba(6, 95, 70, 0.88) 0%, rgba(15, 118, 110, 0.72) 55%, rgba(15, 23, 42, 0.96) 100%);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.sr-md-sidebar.is-stacked-filter-bar .sr-md-sidebar-head {
  border-radius: 13px;
  border-bottom: none;
}

.sr-md-sh-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  min-width: 0;
  width: 100%;
}

.sr-md-sh-title-group {
  display: flex;
  align-items: baseline;
  gap: 5px;
  min-width: 0;
  overflow: hidden;
}

.sr-md-sh-title {
  font-size: 12px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  color: #ffffff;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.sr-md-sh-plain-count {
  font-size: 11px;
  font-weight: 600;
  color: #a7f3d0;
  white-space: nowrap;
  flex-shrink: 0;
}

.sr-md-sh-actions {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
}

.sr-sb-head-btn {
  height: 25px;
  padding: 0 7px;
  border-radius: 6px;
  border: 1px solid rgba(255, 255, 255, 0.24);
  background: rgba(15, 23, 42, 0.55);
  color: #f8fafc;
  font-size: 11px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.15s ease;
}

.sr-sb-head-btn:hover:not(:disabled) {
  background: rgba(16, 185, 129, 0.32);
  border-color: #34d399;
}

.sr-sb-head-btn.is-filter-toggle.active {
  background: rgba(16, 185, 129, 0.28);
  border-color: #34d399;
  color: #ffffff;
}

.sr-sb-head-btn.is-reset {
  background: rgba(239, 68, 68, 0.24);
  border-color: rgba(248, 113, 113, 0.5);
  color: #fecaca;
}

.sr-sb-filter-count {
  padding: 0 5px;
  border-radius: 999px;
  background: #10b981;
  color: #022c22;
  font-size: 10px;
  font-weight: 800;
}

.sr-sidebar-search-shell {
  flex: 0 0 35px !important;
  width: 100% !important;
  min-width: 0 !important;
  height: 35px !important;
  min-height: 35px !important;
  padding: 0 10px !important;
  box-sizing: border-box !important;
  border-radius: 8px !important;
  background: rgba(15, 23, 42, 0.9) !important;
  border: 1px solid rgba(52, 211, 153, 0.38) !important;
}

.sr-sidebar-search-shell input {
  font-size: 12px !important;
  min-width: 0 !important;
  width: 100% !important;
}

.sr-sidebar-filter-panel {
  flex: 0 0 auto;
  width: 100%;
  min-width: 0;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 7px;
  padding: 8px 9px;
  border-radius: 9px;
  background: rgba(15, 23, 42, 0.68);
  border: 1px solid rgba(148, 163, 184, 0.22);
}

.sr-sb-time-block {
  display: flex;
  flex-direction: column;
  gap: 6px;
  width: 100%;
  min-width: 0;
}

.sr-sb-time-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 5px;
  flex-wrap: wrap;
  width: 100%;
  min-width: 0;
}

.sr-sb-seg-group {
  flex-shrink: 0;
  padding: 2px !important;
  gap: 2px !important;
}

.sr-sb-seg-group.is-full-width {
  width: 100% !important;
  display: grid !important;
  grid-template-columns: repeat(4, minmax(0, 1fr)) !important;
}

.sr-sb-seg-group.is-full-width .bg-seg-btn {
  width: 100% !important;
  min-width: 0 !important;
  justify-content: center !important;
  white-space: nowrap !important;
}

.sr-sb-seg-group .bg-seg-btn {
  height: 24px !important;
  padding: 0 7px !important;
  font-size: 11px !important;
}

.sr-sb-time-top .sr-quick-preset-group {
  gap: 4px !important;
}

.sr-sb-time-top .sr-quick-period-btn {
  height: 24px !important;
  padding: 0 6px !important;
  font-size: 10.5px !important;
}

.sr-sb-time-range-row {
  display: grid;
  grid-template-columns: 28px minmax(0, 1fr) 28px;
  align-items: center;
  gap: 5px;
  width: 100%;
  min-width: 0;
}

.sr-sb-time-range-row .bg-period-step-btn {
  width: 28px;
  height: 28px;
}

.sr-sb-date-capsule {
  width: 100%;
  min-width: 0;
  min-height: 28px !important;
  box-sizing: border-box;
  justify-content: center;
  padding: 2px 6px !important;
  gap: 4px !important;
  flex-wrap: nowrap !important;
  overflow: hidden;
}

.sr-sb-date-capsule input,
.sr-sb-date-capsule select {
  flex: 1 1 0%;
  min-width: 0 !important;
  width: 100%;
  height: 22px !important;
  padding: 0 4px !important;
  font-size: 11px !important;
}

.sr-sidebar-pickers-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 5px;
  width: 100%;
  min-width: 0;
}

.sr-sidebar-pickers-grid .pl-picker-wrap {
  width: 100%;
  min-width: 0;
}

.sr-sidebar-pickers-grid .pl-picker-wrap.is-full-span {
  grid-column: 1 / -1;
}

.sr-sidebar-pickers-grid .pl-picker-trigger {
  width: 100%;
  min-width: 0;
  box-sizing: border-box;
  height: 28px;
  padding: 0 7px;
  font-size: 11px;
  justify-content: flex-start;
}

.sr-sidebar-pickers-grid .pl-picker-val {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-align: left;
  font-size: 11px;
}

.sr-sidebar-pickers-grid > .pl-picker-wrap:nth-child(2n) .pl-popover,
.sr-sidebar-pickers-grid > .pl-picker-wrap.is-right-col .pl-popover {
  left: auto;
  right: 0;
}

.sr-md-sort-bar {
  flex: 0 0 auto;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 5px;
  width: 100%;
  min-width: 0;
}

.sr-md-sort-chip {
  height: 26px;
  padding: 0 4px;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  border-radius: 6px;
  border: 1px solid rgba(148, 163, 184, 0.26);
  background: rgba(15, 23, 42, 0.72);
  color: #cbd5e1;
  font-size: 11px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.15s ease;
  white-space: nowrap;
  text-align: center;
}

.sr-md-sort-chip:hover {
  border-color: rgba(52, 211, 153, 0.55);
  color: #ffffff;
}

.sr-md-sort-chip.active {
  background: #10b981;
  border-color: #34d399;
  color: #ffffff;
}

.sr-md-company-list {
  flex: 1 1 0%;
  min-height: 0;
  width: 100%;
  box-sizing: border-box;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.sr-md-company-list::-webkit-scrollbar {
  width: 5px;
}

.sr-md-company-list::-webkit-scrollbar-thumb {
  background: rgba(148, 163, 184, 0.28);
  border-radius: 999px;
}

.sr-md-empty-sidebar {
  padding: 28px 14px;
  text-align: center;
  font-size: 12.5px;
  color: #94a3b8;
}

.sr-md-company-card {
  flex: 0 0 auto;
  flex-shrink: 0;
  width: 100%;
  min-width: 0;
  box-sizing: border-box;
  position: relative;
  padding: 12px 13px;
  border-radius: 10px;
  background: rgba(15, 23, 42, 0.68);
  border: 1px solid rgba(148, 163, 184, 0.18);
  cursor: pointer;
  transition: all 0.15s ease;
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.sr-md-company-card:hover {
  background: rgba(30, 41, 59, 0.82);
  border-color: rgba(52, 211, 153, 0.38);
}

.sr-md-company-card.active {
  background: linear-gradient(135deg, rgba(6, 78, 59, 0.52) 0%, rgba(15, 23, 42, 0.88) 100%);
  border-color: #10b981;
  box-shadow: inset 3px 0 0 #10b981;
}

.sr-md-cc-header-line {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  min-width: 0;
  width: 100%;
}

.sr-md-cc-check {
  width: 17px;
  height: 17px;
  margin-top: 2px;
  border-radius: 4px;
  border: 1.5px solid rgba(148, 163, 184, 0.48);
  background: rgba(15, 23, 42, 0.7);
  color: #ffffff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  padding: 0;
  flex-shrink: 0;
}

.sr-md-cc-check.selected {
  background: #10b981;
  border-color: #10b981;
}

.sr-md-cc-title-block {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.sr-md-cc-name {
  font-size: 13px;
  font-weight: 700;
  color: #f8fafc;
  line-height: 1.4;
  word-break: break-word;
  overflow-wrap: anywhere;
}

.sr-md-cc-name .sr-po1-sep {
  margin: 0 5px;
}

.sr-md-cc-code-plain {
  font-weight: 800;
  color: #38bdf8;
}

.sr-md-cc-mst-inline {
  font-size: 12px;
  font-weight: 600;
  color: #94a3b8;
  font-variant-numeric: tabular-nums;
}

.sr-md-cc-metrics-4col {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px 10px;
  padding-top: 8px;
  border-top: 1px solid rgba(148, 163, 184, 0.14);
  width: 100%;
  min-width: 0;
}

.sr-md-ccm-item {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 5px;
  min-width: 0;
  overflow: hidden;
}

.sr-md-ccm-lbl {
  font-size: 11px;
  font-weight: 500;
  color: #94a3b8;
  white-space: nowrap;
  flex-shrink: 0;
}

.sr-md-ccm-val {
  font-size: 12px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: #f1f5f9;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.is-com-text {
  color: #34d399 !important;
}

.is-debt-text {
  color: #f87171 !important;
}

/* ─── CỘT PHẢI (70%): HEADER VÙNG CARD PO NỔI BẬT & LƯỚI CARD PO (1 CỘT / 2 CỘT) ─── */
.sr-md-main-area {
  min-width: 0;
}

.sr-company-top-toolbar {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  margin-bottom: 10px;
}

.sr-ctt-right {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.sr-company-folder-header {
  display: flex;
  flex-direction: column;
  margin-bottom: 16px;
}

.sr-folder-top-bar {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}

.sr-folder-ear-tab {
  position: relative;
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  max-width: 100%;
  padding: 10px 28px 9px 16px;
  border-radius: 12px 16px 0 0;
  background: linear-gradient(135deg, #059669 0%, #0d9488 58%, #0f766e 100%);
  border: 1px solid rgba(52, 211, 153, 0.55);
  border-bottom: none;
  color: #ffffff;
  clip-path: polygon(0 0, calc(100% - 16px) 0, 100% 100%, 0 100%);
  box-shadow: 0 -2px 12px rgba(16, 185, 129, 0.18);
}

.sr-folder-icon {
  color: #a7f3d0;
  flex-shrink: 0;
}

.sr-cpb-code {
  font-size: 14px;
  font-weight: 800;
  color: #ecfdf5;
}

.sr-folder-sep {
  color: rgba(255, 255, 255, 0.55);
  font-weight: 600;
}

.sr-cpb-name {
  margin: 0;
  font-size: 15px;
  font-weight: 800;
  color: #ffffff;
  letter-spacing: -0.01em;
}

.sr-folder-mst {
  font-size: 12.5px;
  font-weight: 600;
  color: #d1fae5;
  font-variant-numeric: tabular-nums;
}

.sr-folder-pocount {
  font-size: 12.5px;
  font-weight: 800;
  color: #fde047;
  font-variant-numeric: tabular-nums;
}

.sr-customer-kpi-sheet.sr-folder-body-sheet {
  padding: 12px;
  background: linear-gradient(180deg, rgba(15, 23, 42, 0.95) 0%, rgba(11, 20, 28, 0.98) 100%);
  border: 1px solid rgba(52, 211, 153, 0.38);
  border-top: 3px solid #10b981;
  border-radius: 0 12px 12px 12px;
  box-shadow: 0 10px 24px -8px rgba(0, 0, 0, 0.48);
}

.sr-super-bento-grid.is-customer-bento {
  margin-bottom: 0;
  gap: 10px;
}

.sr-super-bento-grid.is-customer-bento .sr-sb-card {
  padding: 12px 14px 11px;
  gap: 8px;
}

.sr-super-bento-grid.is-customer-bento .sr-sb-hero-val {
  font-size: 17.5px;
}

.sr-plain-text-btn {
  height: 28px;
  border: 1px solid rgba(255, 255, 255, 0.22);
  background: rgba(15, 23, 42, 0.65);
  border-radius: 6px;
  padding: 0 10px;
  font-size: 12px;
  font-weight: 700;
  color: #f8fafc;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.15s ease;
}

.sr-plain-text-btn:hover,
.sr-plain-text-btn.active {
  background: rgba(16, 185, 129, 0.32);
  border-color: #34d399;
  color: #ffffff;
}

/* Cụm nút Tác vụ, Dữ liệu & Thiết lập hiển thị ở góc phải Header nhóm (chuẩn baogiaFirebase.vue) */
.sr-hdr-action-btn {
  height: 28px;
  padding: 0 10px;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.15s ease;
}

.sr-hdr-action-btn.is-add {
  background: linear-gradient(135deg, #10b981 0%, #059669 100%);
  border: 1px solid #34d399;
  color: #ffffff;
  box-shadow: 0 2px 8px rgba(16, 185, 129, 0.28);
}

.sr-hdr-action-btn.is-add:hover {
  filter: brightness(1.08);
}

.sr-hdr-action-btn.is-export {
  background: rgba(14, 165, 233, 0.18);
  border: 1px solid rgba(56, 189, 248, 0.45);
  color: #7dd3fc;
}

.sr-hdr-action-btn.is-export:hover {
  background: #0284c7;
  border-color: #38bdf8;
  color: #ffffff;
}

.sr-hdr-export-count {
  padding: 0 5px;
  border-radius: 999px;
  background: #38bdf8;
  color: #082f49;
  font-size: 10.5px;
  font-weight: 800;
}

.sr-display-setting-wrap {
  position: relative;
  display: inline-flex;
}

.sr-hdr-action-btn.is-setting {
  background: #1e293b;
  border: 1px solid #334155;
  color: #e2e8f0;
}

.sr-hdr-action-btn.is-setting:hover,
.sr-hdr-action-btn.is-setting.active {
  border-color: #10b981;
  color: #34d399;
}

.sr-display-setting-dropdown {
  position: absolute;
  top: calc(100% + 6px);
  right: 0;
  width: 316px;
  background: #0f172a;
  border: 1px solid #334155;
  border-radius: 10px;
  box-shadow: 0 16px 36px rgba(0, 0, 0, 0.65);
  padding: 12px;
  z-index: 150;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.sr-ds-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 8px;
  border-bottom: 1px solid #1e293b;
}

.sr-ds-title {
  font-size: 12.5px;
  font-weight: 800;
  color: #f8fafc;
}

.sr-ds-close {
  background: transparent;
  border: none;
  color: #94a3b8;
  font-size: 14px;
  font-weight: 700;
  cursor: pointer;
  padding: 0 4px;
}

.sr-ds-section {
  padding-bottom: 10px;
  border-bottom: 1px solid #1e293b;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.sr-ds-section.is-last {
  padding-bottom: 0;
  border-bottom: none;
}

.sr-ds-label {
  font-size: 11px;
  font-weight: 700;
  color: #94a3b8;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.sr-ds-grid-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
}

.sr-ds-opt-btn {
  height: 30px;
  padding: 0 8px;
  border-radius: 6px;
  border: 1px solid #334155;
  background: #090d16;
  color: #94a3b8;
  font-size: 11.5px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.15s ease;
}

.sr-ds-opt-btn:hover {
  border-color: rgba(52, 211, 153, 0.5);
  color: #f8fafc;
}

.sr-ds-opt-btn.active {
  background: #1e293b;
  border-color: #10b981;
  color: #34d399;
  box-shadow: 0 0 8px rgba(16, 185, 129, 0.18);
}

.sr-ds-stack-btns {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.sr-ds-toggle-row {
  padding: 7px 10px;
  border-radius: 6px;
  border: 1px solid #334155;
  background: #090d16;
  color: #cbd5e1;
  font-size: 11.5px;
  font-weight: 600;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  cursor: pointer;
  transition: all 0.15s ease;
}

.sr-ds-toggle-row strong {
  color: #34d399;
  font-size: 11px;
  font-weight: 800;
}

.sr-ds-toggle-row:hover {
  border-color: #10b981;
}

.sr-empty-folder-sheet {
  display: flex !important;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;
  color: #94a3b8;
  font-size: 13px;
}

.sr-po1-sep {
  color: rgba(148, 163, 184, 0.65);
  user-select: none;
}

/* Lưới Card PO: 1 Cột hoặc 2 Cột */
.sr-card-list.is-cols-1 {
  display: grid !important;
  grid-template-columns: 1fr !important;
  gap: 14px !important;
  margin-bottom: 18px !important;
}

.sr-card-list.is-cols-2 {
  display: grid !important;
  grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  gap: 14px !important;
  margin-bottom: 18px !important;
}

/* ─── THIẾT KẾ CARD PO-1: HEADER CÓ MÀU NỀN NỔI BẬT + 4 KHỐI CHỈ SỐ GỐC ─── */
.sr-record-card.sr-po1-card {
  background: rgba(11, 20, 28, 0.96) !important;
  border: 2px solid rgba(56, 189, 248, 0.62) !important;
  border-radius: 12px !important;
  box-shadow: 0 8px 22px -8px rgba(0, 0, 0, 0.48) !important;
  backdrop-filter: none !important;
  transition: border-color 0.16s ease, box-shadow 0.16s ease !important;
  overflow: hidden;
}

.sr-record-card.sr-po1-card:hover {
  transform: none !important;
  filter: none !important;
  border-color: #38bdf8 !important;
  box-shadow: 0 12px 26px -8px rgba(0, 0, 0, 0.58) !important;
}

.sr-record-card.sr-po1-card.is-selected-card {
  border-color: #10b981 !important;
  box-shadow: inset 3px 0 0 #10b981 !important;
}

/* 1. Header Card PO (Có màu nền tách biệt nổi bật, sắp xếp 2 dòng rõ ràng) */
.sr-po1-header {
  padding: 12px 18px;
  border-bottom: 1.5px solid rgba(56, 189, 248, 0.48);
  background: linear-gradient(90deg, rgba(14, 116, 144, 0.42) 0%, rgba(15, 118, 110, 0.32) 52%, rgba(30, 41, 59, 0.94) 100%);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.sr-record-card.sr-po1-card.is-collapsed-card .sr-po1-header {
  border-bottom: none;
}

.sr-po1-hbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}

.sr-po1-meta-left {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  min-width: 0;
}

.sr-po1-po-num {
  font-size: 14.5px;
  font-weight: 800;
  color: #38bdf8;
}

.sr-po1-plain-meta {
  font-size: 12.5px;
  font-weight: 500;
  color: #e2e8f0;
}

.sr-po1-plain-meta strong {
  font-weight: 700;
  color: #ffffff;
}

.sr-po1-meta-right {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  font-size: 12.5px;
  color: #e2e8f0;
}

.sr-po1-plain-status {
  font-weight: 700;
  color: #f8fafc;
}

.sr-po1-plain-due {
  font-weight: 600;
  color: #fde047;
  cursor: pointer;
}

.sr-po1-plain-due:hover {
  color: #ffffff;
  text-decoration: underline;
}

.sr-po1-contract-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  padding-top: 7px;
  border-top: 1px solid rgba(148, 163, 184, 0.18);
}

.sr-po1-contract-prefix {
  font-size: 12px;
  font-weight: 600;
  color: #94a3b8;
  margin-right: 6px;
}

.sr-po1-contract-title {
  font-size: 14.5px;
  font-weight: 700;
  color: #ffffff;
  line-height: 1.4;
  flex: 1;
  min-width: 200px;
}

.sr-po1-collapsed-summary {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  font-size: 12.5px;
  color: #cbd5e1;
}

.sr-po1-collapsed-summary strong {
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: #f8fafc;
}

/* Dòng 3 (Dưới Nội dung HĐ): Danh sách Tệp Đính Kèm kèm nút View Office & Download */
.sr-po1-contract-files {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px 12px;
  padding-top: 7px;
  border-top: 1px dashed rgba(148, 163, 184, 0.22);
}

.sr-po1-file-entry {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 4px 8px;
  border-radius: 7px;
  background: rgba(15, 23, 42, 0.62);
  border: 1px solid rgba(148, 163, 184, 0.24);
  max-width: 100%;
}

.sr-po1-fe-name {
  font-size: 12px;
  font-weight: 500;
  color: #cbd5e1;
  max-width: 260px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sr-po1-fe-name strong {
  color: #f8fafc;
  font-weight: 700;
}

.sr-po1-fe-actions {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  flex-shrink: 0;
}

.sr-po1-fe-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 23px;
  padding: 0 7px;
  border-radius: 5px;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.15s ease;
  border: 1px solid transparent;
}

.sr-po1-fe-btn.is-view {
  background: rgba(56, 189, 248, 0.16);
  border-color: rgba(56, 189, 248, 0.38);
  color: #7dd3fc;
}

.sr-po1-fe-btn.is-view:hover {
  background: #0284c7;
  border-color: #38bdf8;
  color: #ffffff;
}

.sr-po1-fe-btn.is-dl {
  background: rgba(16, 185, 129, 0.16);
  border-color: rgba(16, 185, 129, 0.38);
  color: #6ee7b7;
}

.sr-po1-fe-btn.is-dl:hover {
  background: #059669;
  border-color: #34d399;
  color: #ffffff;
}

/* 2. 4 Khối Chỉ Số Theo Nhóm Gốc (Chỉ 4 cột ngang hoặc 2x2, tuyệt đối không rớt 3+1) */
.sr-po1-4blocks {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  background: transparent;
}

.sr-card-list.is-cols-2 .sr-po1-4blocks {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.sr-po1-block {
  padding: 13px 16px;
  border-right: 1px solid rgba(148, 163, 184, 0.14);
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}

.sr-po1-block:last-child {
  border-right: none;
}

.sr-card-list.is-cols-2 .sr-po1-block:nth-child(2) {
  border-right: none;
}

.sr-card-list.is-cols-2 .sr-po1-block:nth-child(1),
.sr-card-list.is-cols-2 .sr-po1-block:nth-child(2) {
  border-bottom: 1px solid rgba(148, 163, 184, 0.14);
}

.sr-po1-block-title {
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: #ffffff !important;
  padding: 6px 10px;
  margin-bottom: 4px;
  border-radius: 7px;
  border-bottom: none;
  background: linear-gradient(135deg, #0284c7 0%, #2563eb 100%);
  box-shadow: 0 2px 6px rgba(15, 23, 42, 0.14);
}

.sr-po1-block-title.is-blue-head {
  background: linear-gradient(135deg, #0284c7 0%, #2563eb 100%) !important;
  color: #ffffff !important;
}

.sr-po1-block-title.is-green-head {
  background: linear-gradient(135deg, #059669 0%, #10b981 100%) !important;
  color: #ffffff !important;
}

.sr-po1-block-title.is-red-head {
  background: linear-gradient(135deg, #dc2626 0%, #ef4444 100%) !important;
  color: #ffffff !important;
}

.sr-po1-b-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  min-height: 21px;
}

.sr-po1-b-row.is-primary .sr-po1-b-lbl {
  color: #cbd5e1;
  font-weight: 600;
}

.sr-po1-b-row.is-primary .sr-po1-b-val {
  font-size: 14px;
  font-weight: 700;
  color: #ffffff;
}

.sr-po1-b-row.is-sub-divider {
  margin-top: 4px;
  padding-top: 6px;
  border-top: 1px dashed rgba(148, 163, 184, 0.16);
}

.sr-po1-b-lbl {
  font-size: 12.5px;
  font-weight: 400;
  color: #94a3b8;
  line-height: 1.35;
}

.sr-po1-b-val {
  font-size: 13px;
  font-weight: 700;
  color: #e2e8f0;
  text-align: right;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.sr-po1-b-val.is-com-text {
  color: #34d399 !important;
}

.sr-po1-b-val.is-debt-text {
  color: #f87171 !important;
}

/* 3. Dải Tệp Đính Kèm & Ghi Chú Phẳng */
.sr-po1-files-line,
.sr-po1-note-line {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  padding: 9px 18px;
  border-top: 1px solid rgba(148, 163, 184, 0.14);
  font-size: 12.5px;
  color: #cbd5e1;
  background: rgba(15, 23, 42, 0.3);
}

.sr-po1-files-label {
  font-weight: 600;
  color: #94a3b8;
}

.sr-po1-file-link {
  color: #cbd5e1;
  text-decoration: underline;
  text-underline-offset: 3px;
  font-weight: 500;
}

.sr-po1-file-link:hover {
  color: #ffffff;
}

@media (max-width: 1480px) {
  .sr-workspace-layout.is-master-detail .sr-po1-4blocks {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .sr-workspace-layout.is-master-detail .sr-po1-block:nth-child(2) {
    border-right: none;
  }
  .sr-workspace-layout.is-master-detail .sr-po1-block:nth-child(1),
  .sr-workspace-layout.is-master-detail .sr-po1-block:nth-child(2) {
    border-bottom: 1px solid rgba(148, 163, 184, 0.14);
  }
}

@media (max-width: 1180px) {
  .sr-workspace-layout.is-master-detail {
    grid-template-columns: minmax(0, 1fr);
  }
  .sr-md-sidebar {
    position: static !important;
    top: auto !important;
    height: auto !important;
    max-height: none !important;
    overflow: visible !important;
  }
  .sr-md-company-list {
    flex: 0 0 auto !important;
    height: auto !important;
    max-height: 360px !important;
    overflow-y: auto !important;
    overflow-x: hidden !important;
    -webkit-overflow-scrolling: touch;
    overscroll-behavior-y: auto;
  }
  .sr-page.is-mobile-shell .sr-md-company-list {
    max-height: none !important;
    overflow: visible !important;
  }
  .sr-card-list.is-cols-2 {
    grid-template-columns: 1fr !important;
  }
}

@media (max-width: 768px) {
  .sr-md-cc-metrics-4col {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .sr-po1-4blocks,
  .sr-card-list.is-cols-2 .sr-po1-4blocks,
  .sr-workspace-layout.is-master-detail .sr-po1-4blocks {
    grid-template-columns: 1fr;
  }
  .sr-po1-block {
    border-right: none !important;
    border-bottom: 1px solid rgba(148, 163, 184, 0.14);
  }
  .sr-po1-block:last-child {
    border-bottom: none;
  }
}

.sr-report-group {
  margin-bottom: 20px;
}

.sr-report-group.is-group-collapsed {
  margin-bottom: 10px;
}

.sr-group-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 16px;
  margin-bottom: 10px;
  border-radius: 12px;
  background: linear-gradient(90deg, rgba(5, 150, 105, 0.92) 0%, rgba(15, 118, 110, 0.9) 55%, rgba(15, 23, 42, 0.95) 100%);
  border: 1px solid rgba(16, 185, 129, 0.45);
  box-shadow: 0 6px 20px -6px rgba(16, 185, 129, 0.3);
  flex-wrap: wrap;
}

.sr-group-banner-left {
  display: flex;
  align-items: center;
  gap: 9px;
  flex-wrap: wrap;
  min-width: 0;
}

.sr-group-code-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 10px;
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.32);
  border: 1px solid rgba(255, 255, 255, 0.25);
  color: #ecfdf5;
  font-size: 12px;
  font-weight: 800;
  font-family: 'JetBrains Mono', monospace;
}

.sr-group-company-name {
  margin: 0;
  font-size: 14px;
  font-weight: 800;
  color: #ffffff;
  max-width: 420px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.sr-group-mst-pill {
  padding: 2px 9px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  font-family: 'JetBrains Mono', monospace;
  background: rgba(15, 23, 42, 0.36);
  border: 1px solid rgba(255, 255, 255, 0.22);
  color: #d1fae5;
}

.sr-group-count-pill {
  padding: 2px 9px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
  background: rgba(255, 255, 255, 0.2);
  color: #ffffff;
}

.sr-group-banner-right {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.sr-group-fin-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 4px 12px;
  border-radius: 999px;
  background: rgba(9, 13, 22, 0.55);
  border: 1px solid rgba(255, 255, 255, 0.18);
  font-size: 11.5px;
  color: #e2e8f0;
  flex-wrap: wrap;
}

.sr-gfp-item.is-com strong {
  color: #6ee7b7;
}

.sr-gfp-item.has-debt strong {
  color: #fde047;
}

.sr-gfp-item.no-debt strong {
  color: #34d399;
}

.sr-group-collapse-btn {
  width: 28px;
  height: 28px;
  border-radius: 8px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(255, 255, 255, 0.28);
  background: rgba(15, 23, 42, 0.36);
  color: #ffffff;
  cursor: pointer;
  transition: all 0.16s ease;
}

.sr-group-collapse-btn:hover {
  background: rgba(255, 255, 255, 0.22);
}

/* PO Card Header & Inline Badges */
.sr-rc-title-line {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.sr-rc-ncc-badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 9px;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 800;
  background: rgba(16, 185, 129, 0.16);
  border: 1px solid rgba(52, 211, 153, 0.38);
  color: #6ee7b7;
}

.sr-rc-submeta-line {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: 2px;
}

.sr-record-card.is-collapsed-card .sr-rc-header {
  border-bottom: none !important;
  padding: 10px 16px !important;
}

.sr-rc-collapsed-metrics {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 4px 11px;
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.78);
  border: 1px solid rgba(52, 211, 153, 0.22);
  font-family: 'JetBrains Mono', monospace;
  font-size: 11.5px;
  flex-wrap: wrap;
}

.sr-rc-cm-item {
  display: inline-flex;
  align-items: baseline;
  gap: 4px;
  color: #f8fafc;
}

.sr-rc-cm-item small {
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-size: 10.5px;
  font-weight: 600;
  color: #94a3b8;
}

.sr-rc-cm-item.is-green strong {
  color: #34d399;
}

.sr-rc-cm-item.is-red strong {
  color: #f87171;
}

.sr-rc-collapse-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  height: 26px;
  padding: 0 9px;
  border-radius: 999px;
  border: 1px solid rgba(148, 163, 184, 0.28);
  background: rgba(15, 23, 42, 0.75);
  color: #cbd5e1;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.15s ease;
}

.sr-rc-collapse-btn:hover {
  border-color: #34d399;
  color: #ecfdf5;
  background: rgba(16, 185, 129, 0.16);
}

.sr-card-select-inline {
  padding: 3px 9px 3px 6px !important;
  font-size: 11px !important;
  height: 26px;
}

.sr-rc-badges-row {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.sr-pay-status-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 11px;
  font-weight: 800;
  padding: 3px 10px;
  border-radius: 999px;
  text-transform: uppercase;
  letter-spacing: 0.4px;
}

.sr-pay-status-badge.status-paid {
  background: rgba(16, 185, 129, 0.18);
  color: #34d399;
  border: 1px solid rgba(16, 185, 129, 0.4);
}

.sr-pay-status-badge.status-partial {
  background: rgba(245, 158, 11, 0.18);
  color: #fbbf24;
  border: 1px solid rgba(245, 158, 11, 0.4);
}

.sr-pay-status-badge.status-unpaid {
  background: rgba(244, 63, 94, 0.18);
  color: #fb7185;
  border: 1px solid rgba(244, 63, 94, 0.4);
}

.sr-due-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 11px;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 999px;
  cursor: pointer;
}

.sr-due-badge.due-overdue {
  background: rgba(239, 68, 68, 0.22);
  color: #fca5a5;
  border: 1px solid rgba(239, 68, 68, 0.55);
}

.sr-due-badge.due-soon {
  background: rgba(245, 158, 11, 0.2);
  color: #fde047;
  border: 1px solid rgba(245, 158, 11, 0.45);
}

.sr-due-badge.due-normal {
  background: rgba(16, 185, 129, 0.14);
  color: #6ee7b7;
  border: 1px solid rgba(52, 211, 153, 0.35);
}

.sr-pay-action-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 11.5px;
  font-weight: 700;
  cursor: pointer;
  background: rgba(16, 185, 129, 0.16);
  color: #34d399;
  border: 1px solid rgba(52, 211, 153, 0.4);
  transition: all 0.18s ease;
}

.sr-pay-action-btn:hover {
  background: rgba(16, 185, 129, 0.28);
  transform: translateY(-1px);
}

.sr-pay-count-pill {
  background: #10b981;
  color: #06281e;
  border-radius: 999px;
  padding: 0 6px;
  font-size: 10.5px;
  font-weight: 800;
}

/* 4 Khối Tài Chính Bento (Phương án A: Hero Number + Sub-rows) */
.sr-rc-finance-bento .sr-fin-col {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 10px;
  padding: 12px 16px !important;
}

.sr-fin-hero-box {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding-bottom: 9px;
  border-bottom: 1px dashed rgba(148, 163, 184, 0.18);
}

.sr-fin-hero-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  flex-wrap: wrap;
}

.sr-fin-hero-lbl {
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: #94a3b8;
}

.sr-fin-hero-val {
  font-family: 'JetBrains Mono', monospace;
  font-size: 17.5px;
  font-weight: 800;
  color: #ffffff;
  letter-spacing: -0.02em;
  line-height: 1.25;
}

.sr-fin-hero-val small {
  font-size: 11px;
  font-weight: 600;
  opacity: 0.72;
}

.sr-fin-Inline-pills {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.sr-fin-pct-tag {
  padding: 1px 6px;
  border-radius: 5px;
  font-family: 'JetBrains Mono', monospace;
  font-size: 10px;
  font-weight: 800;
}

.sr-fin-pct-tag.is-emerald {
  background: rgba(16, 185, 129, 0.18);
  border: 1px solid rgba(52, 211, 153, 0.35);
  color: #34d399;
}

.sr-fin-pct-tag.is-blue {
  background: rgba(56, 189, 248, 0.16);
  border: 1px solid rgba(56, 189, 248, 0.35);
  color: #38bdf8;
}

.sr-fin-sub-list {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.sr-fin-col-debt {
  background: rgba(16, 185, 129, 0.04);
}

.sr-fin-subval {
  font-size: 12px;
  color: #cbd5e1;
  font-family: 'JetBrains Mono', monospace;
}

/* Horizontal Attachment Strip */
.sr-rc-attachments-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 18px;
  border-top: 1px dashed rgba(148, 163, 184, 0.16);
  background: rgba(9, 13, 22, 0.35);
  flex-wrap: wrap;
}

.sr-rc-image-thumb a {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 3px 8px 3px 4px;
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.85);
  border: 1px solid rgba(52, 211, 153, 0.35);
  text-decoration: none;
  color: #6ee7b7;
  font-size: 11.5px;
  font-weight: 700;
}

.sr-rc-image-thumb img {
  width: 28px;
  height: 28px;
  object-fit: cover;
  border-radius: 5px;
}

.sr-file-chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 30px;
  padding: 0 10px;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 600;
  text-decoration: none;
  color: #e2e8f0;
  background: rgba(30, 41, 59, 0.75);
  border: 1px solid rgba(148, 163, 184, 0.22);
  max-width: 240px;
  transition: all 0.18s ease;
}

.sr-file-chip:hover {
  border-color: #34d399;
  background: rgba(16, 185, 129, 0.14);
  color: #ffffff;
}

.sr-chip-tag {
  font-size: 11px;
  font-weight: 800;
  color: #94a3b8;
}

.sr-chip-name {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ═══════════════════════════════════════════════════════════════════════════
   6. LIGHT BLUE THEME PARITY (.sr-page.theme-light-blue)
   Ưu tiên màu Xanh dương chủ đạo — Số tiền: Xanh lá cây, Trắng, Xanh dương, Đỏ
   ═══════════════════════════════════════════════════════════════════════════ */
.sr-page.theme-light-blue {
  --bg-accent: #0284c7;
  --bg-accent-strong: #2563eb;
  background:
    radial-gradient(1100px 460px at 12% -5%, rgba(2, 132, 199, 0.14), transparent 60%),
    radial-gradient(900px 420px at 90% 0%, rgba(37, 99, 235, 0.1), transparent 55%),
    linear-gradient(180deg, #eaf4ff 0%, #f4f8fd 48%, #edf2f9 100%) !important;
  color: #0f172a !important;
}

.sr-page.theme-light-blue .bg-brand-icon {
  background: linear-gradient(135deg, #0284c7 0%, #2563eb 100%);
  border-color: #38bdf8;
  color: #ffffff;
  box-shadow: 0 6px 18px -4px rgba(2, 132, 199, 0.4);
}

.sr-page.theme-light-blue .bg-title {
  color: #0f172a;
}

.sr-page.theme-light-blue .bg-subtitle {
  color: #475569;
}

.sr-page.theme-light-blue .bg-count-pill {
  background: #e0f2fe;
  color: #0369a1;
  border-color: #7dd3fc;
}

.sr-page.theme-light-blue .bg-filter-strip {
  background: #ffffff;
  border-color: #bae6fd;
  box-shadow: 0 10px 28px -8px rgba(2, 132, 199, 0.12);
}

.sr-page.theme-light-blue .bg-filter-head {
  background: linear-gradient(90deg, #0284c7 0%, #2563eb 55%, #1d4ed8 100%);
}

.sr-page.theme-light-blue .bg-seg-btn.active {
  background: #0284c7;
  color: #ffffff;
  box-shadow: 0 2px 8px rgba(2, 132, 199, 0.35);
}

.sr-page.theme-light-blue .bg-btn-hero-create {
  border-color: #38bdf8;
  background: linear-gradient(135deg, #0284c7 0%, #2563eb 100%);
  box-shadow: 0 6px 18px -4px rgba(2, 132, 199, 0.45);
}

.sr-page.theme-light-blue .sr-debt-chip.active {
  background: #0284c7;
  border-color: #0284c7;
  color: #ffffff;
}

.sr-page.theme-light-blue .bg-search-shell,
.sr-page.theme-light-blue .bg-seg-group,
.sr-page.theme-light-blue .bg-date-capsule,
.sr-page.theme-light-blue .pl-picker-trigger,
.sr-page.theme-light-blue .sr-debt-chip {
  background: #f8fafc;
  border-color: #cbd5e1;
  color: #1e293b;
}

.sr-page.theme-light-blue .pl-picker-val,
.sr-page.theme-light-blue .bg-search-shell input,
.sr-page.theme-light-blue .bg-date-capsule input,
.sr-page.theme-light-blue .bg-date-capsule select {
  color: #0f172a;
  background: transparent;
}

.sr-page.theme-light-blue .pl-picker-trigger.has-value {
  background: #e0f2fe;
  border-color: #38bdf8;
}

.sr-page.theme-light-blue .pl-picker-trigger.has-value .pl-picker-val,
.sr-page.theme-light-blue .pl-picker-trigger.has-value .pl-picker-lead-icon {
  color: #0369a1;
}

.sr-page.theme-light-blue .pl-popover,
.sr-page.theme-light-blue .bg-recent-dropdown,
.sr-page.theme-light-blue .sr-search-suggest-menu,
.sr-page.theme-light-blue .sr-search-suggest-empty {
  background: #ffffff;
  border-color: #93c5fd;
  box-shadow: 0 16px 36px rgba(15, 23, 42, 0.14);
}

.sr-page.theme-light-blue .pl-popover-search {
  background: #f8fafc;
  border-color: #cbd5e1;
}

.sr-page.theme-light-blue .pl-popover-search input,
.sr-page.theme-light-blue .pl-popover-item,
.sr-page.theme-light-blue .pl-cust-name,
.sr-page.theme-light-blue .sr-suggest-content {
  color: #0f172a;
}

.sr-page.theme-light-blue .pl-popover-item:hover {
  background: #f0f9ff;
}

.sr-page.theme-light-blue .pl-popover-item.active {
  background: #e0f2fe;
  color: #0369a1;
}

/* Light Blue Mode — Action Deck (.sr-action-deck) */
.sr-page.theme-light-blue .sr-action-deck {
  background: #ffffff;
  border-color: #bae6fd;
  box-shadow: 0 10px 28px -8px rgba(2, 132, 199, 0.12);
}

.sr-page.theme-light-blue .sr-action-deck-header {
  background: linear-gradient(90deg, #0284c7 0%, #2563eb 55%, #1d4ed8 100%);
}

.sr-page.theme-light-blue .sr-deck-btn-add {
  border-color: #38bdf8;
  background: linear-gradient(135deg, #0284c7 0%, #2563eb 100%);
  box-shadow: 0 8px 20px -6px rgba(37, 99, 235, 0.42);
}

.sr-page.theme-light-blue .sr-deck-btn-export {
  background: #f0f9ff;
  border-color: #7dd3fc;
  color: #0369a1;
}

.sr-page.theme-light-blue .sr-deck-btn-export:hover {
  background: #0284c7;
  border-color: #0284c7;
  color: #ffffff;
}

.sr-page.theme-light-blue .sr-export-count-pill {
  background: #2563eb;
  color: #ffffff;
}

.sr-page.theme-light-blue .sr-action-deck-utils {
  border-top-color: #e2e8f0;
}

.sr-page.theme-light-blue .sr-util-btn {
  background: #f8fafc;
  border-color: #cbd5e1;
  color: #334155;
}

.sr-page.theme-light-blue .sr-util-btn:hover {
  background: #e0f2fe;
  border-color: #38bdf8;
  color: #0284c7;
}

/* Light Blue Mode — Phương án A: 4 Card Phẳng (Blue Priority + White/Green/Blue/Red Money) */
.sr-page.theme-light-blue .sr-sb-card {
  background: #ffffff;
  border: 1px solid #bae6fd;
  box-shadow: 0 8px 22px -8px rgba(2, 132, 199, 0.14);
}

.sr-page.theme-light-blue .sr-sb-card::before {
  background: linear-gradient(90deg, #0284c7 0%, #2563eb 100%);
}

.sr-page.theme-light-blue .sr-sb-card.sb-card-debt::before {
  background: linear-gradient(90deg, #dc2626 0%, #0284c7 100%);
}

/* Card 1 (Doanh số bán) trong Light Mode: Nền Xanh Dương đậm để số tiền màu Trắng (.money-white) nổi bật */
.sr-page.theme-light-blue .sr-sb-card.sb-card-revenue {
  background: linear-gradient(135deg, #0284c7 0%, #2563eb 100%);
  border-color: #0284c7;
  box-shadow: 0 10px 26px -8px rgba(37, 99, 235, 0.38);
}

.sr-page.theme-light-blue .sr-sb-card.sb-card-revenue::before {
  background: rgba(255, 255, 255, 0.45);
}

.sr-page.theme-light-blue .sr-sb-card.sb-card-revenue .sr-sb-title {
  color: #ffffff;
}

.sr-page.theme-light-blue .sr-sb-card.sb-card-revenue .sr-sb-icon {
  background: rgba(255, 255, 255, 0.18);
  border-color: rgba(255, 255, 255, 0.35);
  color: #ffffff;
}

.sr-page.theme-light-blue .sr-sb-card.sb-card-revenue .sr-sb-act-pill {
  background: rgba(255, 255, 255, 0.16);
  border-color: rgba(255, 255, 255, 0.32);
  color: #ffffff;
}

.sr-page.theme-light-blue .sr-sb-card.sb-card-revenue .sr-sb-act-pill:hover {
  background: #ffffff;
  color: #0284c7;
}

.sr-page.theme-light-blue .sr-sb-card.sb-card-revenue .sr-sb-foot {
  border-top-color: rgba(255, 255, 255, 0.22);
}

.sr-page.theme-light-blue .sr-sb-card.sb-card-revenue .sr-sb-foot-row:hover {
  background: rgba(255, 255, 255, 0.12);
}

.sr-page.theme-light-blue .sr-sb-card.sb-card-revenue .sr-sb-foot-label {
  color: #e0f2fe;
}

.sr-page.theme-light-blue .sr-sb-card.sb-card-revenue .sr-sb-foot-val {
  color: #ffffff !important;
}

.sr-page.theme-light-blue .sr-sb-card:hover {
  border-color: #38bdf8;
  box-shadow: 0 14px 28px -8px rgba(2, 132, 199, 0.22);
}

.sr-page.theme-light-blue .sr-sb-title {
  color: #334155;
}

.sr-page.theme-light-blue .sr-sb-icon.is-emerald {
  background: #e0f2fe;
  border-color: #7dd3fc;
  color: #0284c7;
}

.sr-page.theme-light-blue .sr-sb-icon.is-red {
  background: #fef2f2;
  border-color: #fca5a5;
  color: #dc2626;
}

.sr-page.theme-light-blue .sr-sb-act-pill {
  background: #f0f9ff;
  border-color: #bae6fd;
  color: #0284c7;
}

.sr-page.theme-light-blue .sr-sb-act-pill:hover {
  background: #0284c7;
  border-color: #0284c7;
  color: #ffffff;
}

/* Bảng màu số tiền trong Light Blue Mode: Trắng, Xanh lá cây, Xanh dương, Đỏ */
.sr-page.theme-light-blue .money-white {
  color: #ffffff !important;
}

.sr-page.theme-light-blue .money-green {
  color: #059669 !important;
}

.sr-page.theme-light-blue .money-blue {
  color: #0284c7 !important;
}

.sr-page.theme-light-blue .money-red {
  color: #dc2626 !important;
}

.sr-page.theme-light-blue .sr-sb-foot {
  border-top-color: #e2e8f0;
}

.sr-page.theme-light-blue .sr-sb-foot-row:hover {
  background: #f0f9ff;
}

.sr-page.theme-light-blue .sr-sb-foot-label {
  color: #64748b;
}

.sr-page.theme-light-blue .sr-sb-overdue-inline {
  color: #dc2626;
