/* ═══════════════════════════════════════════════════════════════════════════
   6B. BENTO ANALYTICS HUB MODAL (.sr-analytics-modal) — DARK EMERALD & LIGHT BLUE
   ═══════════════════════════════════════════════════════════════════════════ */
.sr-analytics-modal {
  width: 100vw !important;
  height: 100vh !important;
  max-width: 100vw !important;
  max-height: 100vh !important;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border-radius: 0 !important;
  background: linear-gradient(180deg, rgba(6, 20, 18, 0.99) 0%, rgba(4, 13, 18, 1) 100%);
  border: none;
  box-shadow: none;
}

.sr-analytics-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 11px 20px;
  background: linear-gradient(90deg, rgba(6, 78, 59, 0.55) 0%, rgba(15, 23, 42, 0.85) 100%);
  border-bottom: 1px solid rgba(16, 185, 129, 0.24);
  flex-shrink: 0;
}

/* 2-Column Split Workspace */
.sr-analytics-split-shell {
  flex: 1;
  display: grid;
  grid-template-columns: 300px minmax(0, 1fr);
  min-height: 0;
  overflow: hidden;
}

.sr-analytics-sidebar {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 14px 14px 20px;
  background: rgba(5, 16, 20, 0.92);
  border-right: 1px solid rgba(16, 185, 129, 0.2);
  overflow-y: auto;
  min-height: 0;
}

.sr-analytics-side-section {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.sr-analytics-side-heading {
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: #34d399;
  padding: 0 2px;
}

.sr-analytics-main {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}

.sr-analytics-header-left {
  display: flex;
  align-items: center;
  gap: 13px;
  min-width: 0;
}

.sr-analytics-header-icon {
  width: 38px;
  height: 38px;
  border-radius: 11px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, rgba(16, 185, 129, 0.24) 0%, rgba(5, 150, 105, 0.12) 100%);
  border: 1px solid rgba(52, 211, 153, 0.42);
  color: #34d399;
  flex-shrink: 0;
}

.sr-analytics-title-wrap {
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
}

.sr-analytics-title-row {
  display: flex;
  align-items: center;
  gap: 9px;
  flex-wrap: wrap;
}

.sr-analytics-title {
  margin: 0;
  font-size: 16.5px;
  font-weight: 800;
  color: #ecfdf5;
  letter-spacing: -0.01em;
}

.sr-analytics-time-badge {
  padding: 2px 9px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  background: rgba(16, 185, 129, 0.16);
  border: 1px solid rgba(52, 211, 153, 0.35);
  color: #6ee7b7;
}

.sr-analytics-po-badge {
  padding: 2px 9px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  background: rgba(148, 163, 184, 0.14);
  border: 1px solid rgba(148, 163, 184, 0.28);
  color: #cbd5e1;
}

.sr-analytics-sub {
  margin: 0;
  font-size: 12px;
  color: #94a3b8;
}

/* Metric Switcher Grid inside Left Sidebar */
.sr-analytics-metric-strip {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 6px;
}

.sr-analytics-metric-chip {
  height: 32px;
  padding: 0 8px;
  border-radius: 8px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  background: rgba(15, 23, 42, 0.72);
  color: #cbd5e1;
  font-size: 11px;
  font-weight: 700;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  cursor: pointer;
  transition: all 0.16s ease;
  text-align: left;
}

.sr-analytics-metric-chip:hover {
  border-color: rgba(52, 211, 153, 0.45);
  color: #ecfdf5;
  background: rgba(16, 185, 129, 0.12);
}

.sr-analytics-metric-chip.active {
  background: linear-gradient(135deg, #059669 0%, #10b981 100%);
  border-color: #34d399;
  color: #ffffff;
  box-shadow: 0 4px 12px -2px rgba(16, 185, 129, 0.45);
}

/* 4 Mini-KPI Summary Cards stacked in Left Sidebar */
.sr-analytics-kpi-grid {
  display: flex;
  flex-direction: column;
  gap: 9px;
}

.sr-analytics-kpi-card {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding: 10px 14px;
  border-radius: 12px;
  background: rgba(15, 23, 42, 0.75);
  border: 1px solid rgba(148, 163, 184, 0.18);
  min-width: 0;
}

.sr-analytics-kpi-card.is-primary {
  border-color: rgba(16, 185, 129, 0.35);
  background: linear-gradient(135deg, rgba(6, 78, 59, 0.32) 0%, rgba(15, 23, 42, 0.82) 100%);
}

.sr-analytics-kpi-card.is-highlight {
  border-color: rgba(56, 189, 248, 0.32);
  background: linear-gradient(135deg, rgba(12, 74, 110, 0.28) 0%, rgba(15, 23, 42, 0.82) 100%);
}

.sr-analytics-kpi-card.is-warn {
  border-color: rgba(245, 158, 11, 0.32);
  background: linear-gradient(135deg, rgba(120, 53, 15, 0.24) 0%, rgba(15, 23, 42, 0.82) 100%);
}

.sr-analytics-kpi-label {
  font-size: 10.5px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: #94a3b8;
}

.sr-analytics-kpi-val {
  font-size: 16px;
  font-weight: 800;
  color: #ecfdf5;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.sr-analytics-kpi-card.is-primary .sr-analytics-kpi-val {
  color: #34d399;
}

.sr-analytics-kpi-card.is-highlight .sr-analytics-kpi-val {
  color: #38bdf8;
}

.sr-analytics-kpi-card.is-warn .sr-analytics-kpi-val {
  color: #fbbf24;
}

.sr-analytics-kpi-sub {
  font-size: 11.5px;
  font-weight: 600;
  color: #cbd5e1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Toolbar: Tabs + Controls */
.sr-analytics-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 10px 22px;
  background: rgba(9, 24, 28, 0.9);
  border-bottom: 1px solid rgba(16, 185, 129, 0.18);
  flex-wrap: wrap;
  flex-shrink: 0;
}

.sr-analytics-tabs {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.sr-analytics-tab-btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 34px;
  padding: 0 13px;
  border-radius: 9px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  background: rgba(15, 23, 42, 0.65);
  color: #cbd5e1;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.16s ease;
}

.sr-analytics-tab-btn:hover {
  border-color: rgba(52, 211, 153, 0.45);
  color: #ecfdf5;
}

.sr-analytics-tab-btn.active {
  background: rgba(16, 185, 129, 0.2);
  border-color: #10b981;
  color: #34d399;
  box-shadow: inset 0 0 0 1px rgba(52, 211, 153, 0.25);
}

.sr-analytics-controls {
  display: flex;
  align-items: center;
  gap: 14px;
  flex-wrap: wrap;
}

.sr-analytics-ctrl-group {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 3px 6px;
  border-radius: 9px;
  background: rgba(15, 23, 42, 0.78);
  border: 1px solid rgba(148, 163, 184, 0.2);
}

.sr-analytics-ctrl-label {
  font-size: 11px;
  font-weight: 700;
  color: #94a3b8;
  padding: 0 5px;
}

.sr-analytics-seg-btn {
  height: 26px;
  padding: 0 9px;
  border-radius: 6px;
  border: 1px solid transparent;
  background: transparent;
  color: #cbd5e1;
  font-size: 11.5px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.15s ease;
}

.sr-analytics-seg-btn:hover {
  color: #ffffff;
  background: rgba(148, 163, 184, 0.12);
}

.sr-analytics-seg-btn.active {
  background: #10b981;
  color: #042f2e;
  font-weight: 800;
}

.sr-analytics-limit-input {
  width: 58px;
  height: 26px;
  padding: 0 7px;
  border-radius: 6px;
  border: 1px solid rgba(16, 185, 129, 0.35);
  background: rgba(6, 20, 18, 0.9);
  color: #ecfdf5;
  font-size: 11.5px;
  font-weight: 700;
  text-align: center;
  outline: none;
}

/* Modal Body & Panels */
.sr-analytics-body {
  flex: 1;
  overflow-y: auto;
  padding: 16px 22px 22px;
}

.sr-analytics-timeline-card {
  max-width: 1080px;
  padding: 14px 18px 16px;
  border-radius: 14px;
  background: rgba(15, 23, 42, 0.65);
  border: 1px solid rgba(16, 185, 129, 0.2);
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.sr-analytics-chart-canvas-wrap {
  height: 360px;
  min-height: 320px;
  max-height: 400px;
  width: 100%;
  position: relative;
}

.sr-analytics-ranking-workspace {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.sr-analytics-charts-row {
  display: grid;
  grid-template-columns: 360px minmax(0, 1fr);
  gap: 16px;
  align-items: stretch;
}

.sr-analytics-doughnut-card,
.sr-analytics-bar-card,
.sr-analytics-table-card {
  padding: 14px 16px;
  border-radius: 14px;
  background: rgba(15, 23, 42, 0.68);
  border: 1px solid rgba(16, 185, 129, 0.2);
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-width: 0;
}

.sr-analytics-bar-card:only-child {
  grid-column: 1 / -1;
}

.sr-analytics-panel-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  flex-wrap: wrap;
}

.sr-analytics-panel-title {
  margin: 0;
  font-size: 13.5px;
  font-weight: 800;
  color: #ecfdf5;
}

.sr-analytics-panel-sub {
  font-size: 11px;
  color: #94a3b8;
}

.sr-analytics-doughnut-wrap {
  height: 360px;
  width: 100%;
  position: relative;
}

.sr-analytics-bar-scroll {
  width: 100%;
  overflow-x: auto;
  overflow-y: hidden;
  padding-bottom: 6px;
}

/* Ranking Table */
.sr-analytics-table-scroll {
  max-height: 340px;
  overflow-y: auto;
  border-radius: 10px;
  border: 1px solid rgba(148, 163, 184, 0.16);
}

.sr-analytics-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12.5px;
}

.sr-analytics-table thead th {
  position: sticky;
  top: 0;
  z-index: 2;
  background: rgba(6, 24, 24, 0.96);
  color: #94a3b8;
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  padding: 10px 12px;
  text-align: left;
  border-bottom: 1px solid rgba(16, 185, 129, 0.24);
}

.sr-analytics-table tbody tr {
  border-bottom: 1px solid rgba(148, 163, 184, 0.1);
  transition: background 0.14s ease;
}

.sr-analytics-table tbody tr:hover {
  background: rgba(16, 185, 129, 0.08);
}

.sr-analytics-table td {
  padding: 9px 12px;
  color: #e2e8f0;
  vertical-align: middle;
}

.sr-rank-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 30px;
  height: 22px;
  padding: 0 6px;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 800;
  background: rgba(148, 163, 184, 0.15);
  color: #cbd5e1;
}

.sr-rank-badge.is-top1 {
  background: rgba(16, 185, 129, 0.25);
  border: 1px solid rgba(52, 211, 153, 0.55);
  color: #34d399;
}

.sr-rank-badge.is-top2 {
  background: rgba(56, 189, 248, 0.22);
  border: 1px solid rgba(56, 189, 248, 0.5);
  color: #38bdf8;
}

.sr-rank-badge.is-top3 {
  background: rgba(245, 158, 11, 0.22);
  border: 1px solid rgba(251, 191, 36, 0.5);
  color: #fbbf24;
}

.sr-rank-name {
  font-weight: 700;
  color: #f8fafc;
  max-width: 340px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.sr-rank-po-pill {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  background: rgba(148, 163, 184, 0.14);
  color: #cbd5e1;
}

.sr-rank-val {
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}

.sr-rank-share-cell {
  display: flex;
  align-items: center;
  gap: 8px;
}

.sr-rank-share-bar {
  flex: 1;
  height: 7px;
  border-radius: 999px;
  background: rgba(148, 163, 184, 0.16);
  overflow: hidden;
}

.sr-rank-share-fill {
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, #10b981 0%, #34d399 100%);
}

.sr-rank-share-text {
  width: 44px;
  text-align: right;
  font-size: 11.5px;
  font-weight: 700;
  color: #cbd5e1;
  font-variant-numeric: tabular-nums;
}

.sr-rank-filter-btn {
  height: 26px;
  padding: 0 10px;
  border-radius: 6px;
  border: 1px solid rgba(52, 211, 153, 0.4);
  background: rgba(16, 185, 129, 0.14);
  color: #34d399;
  font-size: 11px;
  font-weight: 800;
  cursor: pointer;
  transition: all 0.15s ease;
}

.sr-rank-filter-btn:hover {
  background: #10b981;
  color: #042f2e;
}

/* ── LIGHT BLUE MODE FOR BENTO ANALYTICS HUB (.sr-analytics-modal.is-light) ── */
.sr-analytics-modal.is-light,
.sr-modal-overlay.theme-light-blue .sr-analytics-modal {
  background: #f8fafc;
  border-color: #93c5fd;
  box-shadow: 0 28px 64px rgba(15, 23, 42, 0.22);
}

.sr-analytics-modal.is-light .sr-analytics-header {
  background: linear-gradient(90deg, #0284c7 0%, #2563eb 55%, #1d4ed8 100%);
  border-bottom: 1.5px solid #38bdf8;
}

.sr-analytics-modal.is-light .sr-analytics-header-icon {
  background: rgba(255, 255, 255, 0.18);
  border-color: rgba(255, 255, 255, 0.35);
  color: #ffffff;
}

.sr-analytics-modal.is-light .sr-analytics-title {
  color: #ffffff;
}

.sr-analytics-modal.is-light .sr-analytics-time-badge,
.sr-analytics-modal.is-light .sr-analytics-po-badge {
  background: rgba(255, 255, 255, 0.2);
  border-color: rgba(255, 255, 255, 0.35);
  color: #ffffff;
}

.sr-analytics-modal.is-light .sr-analytics-sub {
  color: rgba(255, 255, 255, 0.86);
}

.sr-analytics-modal.is-light .sr-analytics-sidebar {
  background: #f0f9ff;
  border-right-color: #bae6fd;
}

.sr-analytics-modal.is-light .sr-analytics-side-heading {
  color: #0284c7;
}

.sr-analytics-modal.is-light .sr-analytics-metric-strip {
  background: transparent;
}

.sr-analytics-modal.is-light .sr-analytics-metric-chip {
  background: #ffffff;
  border-color: #cbd5e1;
  color: #334155;
}

.sr-analytics-modal.is-light .sr-analytics-metric-chip:hover {
  border-color: #38bdf8;
  color: #0284c7;
  background: #e0f2fe;
}

.sr-analytics-modal.is-light .sr-analytics-metric-chip.active {
  background: linear-gradient(135deg, #0284c7 0%, #2563eb 100%);
  border-color: #0284c7;
  color: #ffffff;
  box-shadow: 0 4px 12px -2px rgba(37, 99, 235, 0.35);
}

.sr-analytics-modal.is-light .sr-analytics-kpi-grid {
  background: transparent;
}

.sr-analytics-modal.is-light .sr-analytics-kpi-card {
  background: #ffffff;
  border-color: #cbd5e1;
}

.sr-analytics-modal.is-light .sr-analytics-kpi-card.is-primary {
  background: linear-gradient(135deg, #f0f9ff 0%, #e0f2fe 100%);
  border-color: #7dd3fc;
}

.sr-analytics-modal.is-light .sr-analytics-kpi-card.is-highlight {
  background: linear-gradient(135deg, #eff6ff 0%, #dbeafe 100%);
  border-color: #93c5fd;
}

.sr-analytics-modal.is-light .sr-analytics-kpi-card.is-warn {
  background: linear-gradient(135deg, #fffbeb 0%, #fef3c7 100%);
  border-color: #fcd34d;
}

.sr-analytics-modal.is-light .sr-analytics-kpi-label {
  color: #64748b;
}

.sr-analytics-modal.is-light .sr-analytics-kpi-val {
  color: #0f172a;
}

.sr-analytics-modal.is-light .sr-analytics-kpi-card.is-primary .sr-analytics-kpi-val {
  color: #0284c7;
}

.sr-analytics-modal.is-light .sr-analytics-kpi-card.is-highlight .sr-analytics-kpi-val {
  color: #1d4ed8;
}

.sr-analytics-modal.is-light .sr-analytics-kpi-card.is-warn .sr-analytics-kpi-val {
  color: #d97706;
}

.sr-analytics-modal.is-light .sr-analytics-kpi-sub {
  color: #475569;
}

.sr-analytics-modal.is-light .sr-analytics-toolbar {
  background: #f1f5f9;
  border-bottom-color: #cbd5e1;
}

.sr-analytics-modal.is-light .sr-analytics-tab-btn {
  background: #ffffff;
  border-color: #cbd5e1;
  color: #475569;
}

.sr-analytics-modal.is-light .sr-analytics-tab-btn:hover {
  border-color: #38bdf8;
  color: #0284c7;
}

.sr-analytics-modal.is-light .sr-analytics-tab-btn.active {
  background: #e0f2fe;
  border-color: #0284c7;
  color: #0369a1;
  box-shadow: inset 0 0 0 1px rgba(2, 132, 199, 0.2);
}

.sr-analytics-modal.is-light .sr-analytics-ctrl-group {
  background: #ffffff;
  border-color: #cbd5e1;
}

.sr-analytics-modal.is-light .sr-analytics-ctrl-label {
  color: #64748b;
}

.sr-analytics-modal.is-light .sr-analytics-seg-btn {
  color: #475569;
}

.sr-analytics-modal.is-light .sr-analytics-seg-btn:hover {
  color: #0f172a;
  background: #f1f5f9;
}

.sr-analytics-modal.is-light .sr-analytics-seg-btn.active {
  background: #0284c7;
  color: #ffffff;
}

.sr-analytics-modal.is-light .sr-analytics-limit-input {
  background: #f8fafc;
  border-color: #93c5fd;
  color: #0f172a;
}

.sr-analytics-modal.is-light .sr-analytics-timeline-card,
.sr-analytics-modal.is-light .sr-analytics-doughnut-card,
.sr-analytics-modal.is-light .sr-analytics-bar-card,
.sr-analytics-modal.is-light .sr-analytics-table-card {
  background: #ffffff;
  border-color: #cbd5e1;
  box-shadow: 0 4px 14px rgba(15, 23, 42, 0.04);
}

.sr-analytics-modal.is-light .sr-analytics-panel-title {
  color: #0f172a;
}

.sr-analytics-modal.is-light .sr-analytics-panel-sub {
  color: #64748b;
}

.sr-analytics-modal.is-light .sr-analytics-table-scroll {
  border-color: #e2e8f0;
}

.sr-analytics-modal.is-light .sr-analytics-table thead th {
  background: #f0f9ff;
  color: #0369a1;
  border-bottom-color: #bae6fd;
}

.sr-analytics-modal.is-light .sr-analytics-table tbody tr {
  border-bottom-color: #f1f5f9;
}

.sr-analytics-modal.is-light .sr-analytics-table tbody tr:hover {
  background: #f0f9ff;
}

.sr-analytics-modal.is-light .sr-analytics-table td {
  color: #1e293b;
}

.sr-analytics-modal.is-light .sr-rank-name {
  color: #0f172a;
}

.sr-analytics-modal.is-light .sr-rank-po-pill {
  background: #e2e8f0;
  color: #334155;
}

.sr-analytics-modal.is-light .sr-rank-share-bar {
  background: #e2e8f0;
}

.sr-analytics-modal.is-light .sr-rank-share-fill {
  background: linear-gradient(90deg, #0284c7 0%, #38bdf8 100%);
}

.sr-analytics-modal.is-light .sr-rank-share-text {
  color: #334155;
}

.sr-analytics-modal.is-light .sr-rank-filter-btn {
  background: #e0f2fe;
  border-color: #7dd3fc;
  color: #0284c7;
}

.sr-analytics-modal.is-light .sr-rank-filter-btn:hover {
  background: #0284c7;
  color: #ffffff;
}

/* ═══════════════════════════════════════════════════════════════════════════
   7. RESPONSIVE & MOBILE SAFE BOTTOM PADDING
   ═══════════════════════════════════════════════════════════════════════════ */
@media (max-width: 1360px) {
  .sr-super-bento-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 1280px) {
  .bg-filter-row-pickers {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 1100px) {
  :global(html:has(.sr-page)) {
    height: auto !important;
    max-height: none !important;
    overflow-x: clip !important;
    overflow-y: auto !important;
  }
  :global(body:has(.sr-page)),
  :global(#app:has(.sr-page)),
  :global(.app-layout:has(.sr-page)),
  :global(.app-layout:has(.sr-page) .main-content) {
    height: auto !important;
    max-height: none !important;
    overflow: visible !important;
    overflow-x: clip !important;
  }
  .sr-page.page {
    padding: 16px 14px calc(96px + env(safe-area-inset-bottom, 0px)) !important;
    height: auto !important;
    max-height: none !important;
    overflow: visible !important;
    overflow-x: clip !important;
  }
}

@media (max-width: 1080px) {
  .sr-top-command-grid {
    grid-template-columns: 1fr;
  }
  .sr-po-pane-layout-btns,
  .sr-po-left-rail {
    display: none !important;
  }
  .sr-po-mobile-switch {
    display: flex;
  }
  .sr-po-modal .sr-po-modal-scroll {
    padding: 0 !important;
    overflow: hidden !important;
  }
  .sr-po-workspace {
    flex-direction: column;
    padding: 10px 12px;
  }
  .sr-po-left-pane {
    display: none;
    flex: 1 1 0% !important;
    min-height: 0 !important;
    width: 100%;
    max-height: none;
  }
  .sr-po-right-pane {
    flex: 1 1 0% !important;
    min-height: 0 !important;
    overflow-y: auto !important;
    -webkit-overflow-scrolling: touch;
  }
  .sr-po-workspace.mob-show-docs .sr-po-left-pane {
    display: flex !important;
  }
  .sr-po-workspace.mob-show-docs .sr-po-right-pane {
    display: none !important;
  }
  .sr-po-modal .sr-modal-finance-grid,
  .sr-modal-finance-grid {
    grid-template-columns: 1fr;
  }
  .sr-col-2, .sr-col-3, .sr-col-4, .sr-col-5, .sr-col-6 {
    grid-column: span 6;
  }
  .sr-action-deck-body {
    flex-direction: row;
    align-items: center;
    flex-wrap: wrap;
  }
  .sr-deck-btn-add {
    flex: 1 1 240px;
  }
  .sr-deck-btn-export {
    flex: 1 1 180px;
    height: 54px;
  }
  .sr-action-deck-utils {
    width: 100%;
    padding-top: 8px;
  }
  .sr-analytics-split-shell {
    display: flex;
    flex-direction: column;
    overflow-y: auto !important;
    overflow-x: hidden !important;
    -webkit-overflow-scrolling: touch;
  }
  .sr-analytics-sidebar {
    flex: 0 0 auto;
    min-height: auto;
    border-right: none;
    border-bottom: 1px solid rgba(16, 185, 129, 0.2);
    overflow: visible !important;
  }
  .sr-analytics-main {
    flex: 0 0 auto;
    min-height: auto;
    overflow: visible !important;
  }
  .sr-analytics-body {
    flex: 0 0 auto;
    min-height: auto;
    overflow: visible !important;
  }
  .sr-analytics-charts-row {
    grid-template-columns: 1fr;
  }
  .sr-analytics-kpi-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 960px) {
  .bg-filter-row-pickers {
    grid-template-columns: repeat(2, 1fr);
  }
  .sr-rc-meta-bento {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  :global(.app-layout:has(.sr-page.page) .main-content) {
    padding-bottom: 0 !important;
  }

  .sr-page,
  .sr-page.page {
    min-height: calc(100vh - env(safe-area-inset-top, 0px)) !important;
    min-height: calc(100dvh - env(safe-area-inset-top, 0px)) !important;
    height: auto !important;
    max-height: none !important;
    overflow: visible !important;
    overflow-x: clip !important;
    padding: 12px 12px calc(110px + env(safe-area-inset-bottom, 24px)) !important;
  }

  .sr-po-modal.sr-modal-large .sr-modal-body.sr-po-modal-scroll {
    padding: 0 !important;
    overflow: hidden !important;
  }

  .sr-super-bento-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
  }

  .sr-super-bento-grid .sr-sb-card {
    padding: 10px 11px !important;
    gap: 6px !important;
    border-radius: 12px;
  }

  .sr-super-bento-grid .sr-sb-head {
    gap: 6px;
  }

  .sr-super-bento-grid .sr-sb-icon {
    width: 24px;
    height: 24px;
    border-radius: 7px;
  }

  .sr-super-bento-grid .sr-sb-title {
    font-size: 11.5px;
  }

  .sr-super-bento-grid .sr-sb-badge {
    font-size: 9.5px;
    padding: 2px 6px;
  }

  .sr-super-bento-grid .sr-sb-hero-val {
    font-size: clamp(13px, 3.7vw, 16px) !important;
    line-height: 1.2;
    word-break: break-word;
  }

  .sr-super-bento-grid .sr-sb-sub-row {
    font-size: 10.5px;
    gap: 4px;
  }

  .sr-super-bento-grid .sr-sb-sub-val {
    font-size: 11px;
  }

  .sr-add-choice-grid {
    grid-template-columns: 1fr;
    padding: 16px;
  }

  .sr-action-deck-header {
    display: none;
  }

  .sr-action-deck-body {
    flex-direction: column;
    align-items: stretch;
  }

  .sr-deck-btn-add,
  .sr-deck-btn-export {
    flex: none;
    width: 100%;
  }

  .sr-deck-btn-export {
    height: 42px;
  }

  .bg-filter-head {
    display: none;
  }

  .bg-mobile-filter-toggle-btn {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    height: 40px;
    padding: 0 12px;
    border-radius: 10px;
    border: 1px solid rgba(52, 211, 153, 0.35);
    background: rgba(16, 185, 129, 0.14);
    color: #34d399;
    font-size: 12px;
    font-weight: 800;
    cursor: pointer;
    flex-shrink: 0;
  }

  .bg-mobile-filter-badge {
    padding: 0 6px;
    border-radius: 999px;
    background: #10b981;
    color: #06281e;
    font-size: 10.5px;
    font-weight: 800;
  }

  .bg-mobile-filter-chevron.open {
    transform: rotate(180deg);
  }

  .bg-mobile-refresh-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    border-radius: 10px;
    border: 1px solid rgba(148, 163, 184, 0.25);
    background: rgba(15, 23, 42, 0.8);
    color: #cbd5e1;
    cursor: pointer;
    flex-shrink: 0;
  }

  .bg-filter-row-pickers {
    grid-template-columns: 1fr;
  }

  .sr-rc-header {
    flex-direction: column;
    gap: 10px;
  }

  .sr-rc-right {
    width: 100%;
    align-items: flex-start !important;
  }

  .sr-rc-badges-row {
    justify-content: flex-start;
  }

  .sr-rc-meta-bento {
    grid-template-columns: 1fr;
  }
}

/* ═══════════════════════════════════════════════════════════════════════════
   8. FULLSCREEN DEBT & PAYMENT MODAL (100% MATCHING BAOGIAFIREBASE)
   ═══════════════════════════════════════════════════════════════════════════ */
.sr-debt-fullscreen-overlay {
  position: fixed;
  inset: 0;
  z-index: 100050;
  display: flex;
  align-items: stretch;
  justify-content: center;
  padding: 0 !important;
  background: rgba(2, 6, 23, 0.88) !important;
  backdrop-filter: blur(8px);
}

.sr-debt-fullscreen-card.debt-payment-modal {
  width: 100vw !important;
  height: 100vh !important;
  max-width: 100vw !important;
  max-height: 100vh !important;
  margin: 0 !important;
  border-radius: 0 !important;
  background: #0b1120 !important;
  border: none !important;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  font-family: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
}

.sr-debt-head {
  padding: 12px 24px !important;
  background: linear-gradient(135deg, #075985, #0369a1) !important;
  border-bottom: 1px solid rgba(56, 189, 248, 0.35) !important;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.sr-debt-head h3 {
  margin: 0;
  font-size: 16px;
  font-weight: 800;
  color: #f8fafc;
}

.m-grab-head-stack {
  display: none;
}

.m-grab-handle {
  display: none;
}

.m-debt-body {
  display: none;
}

@media (max-width: 1280px) {
  .sr-po-modal .sr-modal-finance-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  }
  .sr-po-modal .sr-modal-fin-col:nth-child(1),
  .sr-po-modal .sr-modal-fin-col:nth-child(2) {
    border-bottom: 1px solid #1e293b !important;
  }
}

@media (max-width: 768px) {
  .sr-po-modal .sr-modal-finance-grid {
    grid-template-columns: 1fr !important;
  }
  .sr-po-modal .sr-modal-fin-col {
    border-right: none !important;
    border-bottom: 1px solid #1e293b !important;
  }
  .sr-po-modal .sr-modal-fin-col:last-child {
    border-bottom: none !important;
  }

  .debt-payment-modal .dt-only-head,
  .debt-payment-modal .dt-only-debt-view {
    display: none !important;
  }

  .debt-payment-modal .m-grab-head-stack {
    display: flex !important;
    flex-direction: column;
    align-items: flex-start;
    width: 100%;
    padding-right: 36px;
  }

  .debt-payment-modal .m-debt-body {
    display: flex !important;
    flex-direction: column;
    flex: 1;
    min-height: 0;
    overflow: hidden;
    background: #0b1323;
    position: relative;
  }

  .debt-payment-modal .m-debt-scroll-area {
    flex: 1;
    min-height: 0;
    overflow-y: auto;
    -webkit-overflow-scrolling: touch;
    padding: 14px 14px 90px 14px;
    display: flex;
    flex-direction: column;
    gap: 14px;
  }

  .debt-payment-modal .m-debt-cust-banner {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 10px 12px;
    border-radius: 12px;
    background: linear-gradient(135deg, rgba(30, 41, 59, 0.85) 0%, rgba(15, 23, 42, 0.95) 100%);
    border: 1px solid rgba(56, 189, 248, 0.22);
  }
  .debt-payment-modal .m-debt-cust-icon {
    width: 34px;
    height: 34px;
    border-radius: 9px;
    background: rgba(56, 189, 248, 0.14);
    color: #38bdf8;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
  }
  .debt-payment-modal .m-debt-cust-info {
    flex: 1;
    min-width: 0;
  }
  .debt-payment-modal .m-debt-cust-label {
    font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #94a3b8;
  }
  .debt-payment-modal .m-debt-cust-name {
    font-size: 13.5px;
    font-weight: 800;
    color: #f8fafc;
    line-height: 1.3;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }

  .debt-payment-modal .m-debt-kpi-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
  }
  .debt-payment-modal .m-debt-kpi-card {
    padding: 10px 12px;
    border-radius: 12px;
    background: #131c31;
    border: 1px solid #1e293b;
    display: flex;
    flex-direction: column;
    gap: 4px;
    min-width: 0;
  }
  .debt-payment-modal .m-debt-kpi-lbl {
    font-size: 10px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: #94a3b8;
  }
  .debt-payment-modal .m-debt-kpi-val {
    font-size: 15px;
    font-weight: 800;
    color: #f8fafc;
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }
  .debt-payment-modal .m-debt-kpi-unit {
    font-size: 11px;
    font-weight: 600;
    color: #94a3b8;
  }
  .debt-payment-modal .m-debt-kpi-card.is-blue {
    border-color: rgba(56, 189, 248, 0.25);
    background: linear-gradient(145deg, rgba(14, 116, 144, 0.14), #131c31);
  }
  .debt-payment-modal .m-debt-kpi-card.is-blue .m-debt-kpi-val {
    color: #38bdf8;
  }
  .debt-payment-modal .m-debt-kpi-card.is-green {
    border-color: rgba(16, 185, 129, 0.28);
    background: linear-gradient(145deg, rgba(6, 95, 70, 0.18), #131c31);
  }
  .debt-payment-modal .m-debt-kpi-card.is-green .m-debt-kpi-val {
    color: #34d399;
  }
  .debt-payment-modal .m-debt-kpi-card.is-danger {
    border-color: rgba(239, 68, 68, 0.35);
    background: linear-gradient(145deg, rgba(153, 27, 27, 0.22), #131c31);
  }
  .debt-payment-modal .m-debt-kpi-card.is-danger .m-debt-kpi-val {
    color: #f87171;
  }
  .debt-payment-modal .m-debt-kpi-card.is-settled {
    border-color: rgba(16, 185, 129, 0.3);
  }
  .debt-payment-modal .m-debt-kpi-card.is-settled .m-debt-kpi-val {
    color: #34d399;
  }

  .debt-payment-modal .m-debt-progress-box {
    padding: 10px 12px;
    border-radius: 12px;
    background: #131c31;
    border: 1px solid #1e293b;
  }
  .debt-payment-modal .m-debt-progress-top {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 6px;
  }
  .debt-payment-modal .m-debt-progress-lbl {
    font-size: 11px;
    font-weight: 600;
    color: #94a3b8;
  }
  .debt-payment-modal .m-debt-progress-pct {
    font-size: 12px;
    font-weight: 800;
    color: #38bdf8;
    font-variant-numeric: tabular-nums;
  }
  .debt-payment-modal .m-debt-progress-pct.is-done {
    color: #34d399;
  }
  .debt-payment-modal .m-debt-progress-track {
    width: 100%;
    height: 7px;
    border-radius: 999px;
    background: #0f172a;
    overflow: hidden;
  }
  .debt-payment-modal .m-debt-progress-fill {
    height: 100%;
    border-radius: 999px;
    background: linear-gradient(90deg, #0284c7, #10b981);
    transition: width 0.3s ease;
  }

  .debt-payment-modal .m-debt-po-switcher {
    display: flex;
    flex-direction: column;
    gap: 8px;
  }
  .debt-payment-modal .m-debt-sec-head {
    display: flex;
    justify-content: space-between;
    align-items: center;
  }
  .debt-payment-modal .m-debt-sec-title {
    font-size: 11px;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: #94a3b8;
  }
  .debt-payment-modal .m-debt-sec-hint {
    font-size: 10.5px;
    color: #64748b;
  }
  .debt-payment-modal .m-debt-po-pills {
    display: flex;
    gap: 8px;
    overflow-x: auto;
    padding-bottom: 4px;
    scrollbar-width: none;
  }
  .debt-payment-modal .m-debt-po-pills::-webkit-scrollbar {
    display: none;
  }
  .debt-payment-modal .m-debt-po-pill {
    flex: 0 0 auto;
    min-width: 155px;
    padding: 9px 11px;
    border-radius: 11px;
    background: #131c31;
    border: 1.5px solid #1e293b;
    color: #e2e8f0;
    text-align: left;
    display: flex;
    flex-direction: column;
    gap: 4px;
    cursor: pointer;
    transition: all 0.18s ease;
  }
  .debt-payment-modal .m-debt-po-pill.is-active {
    background: rgba(14, 165, 233, 0.14);
    border-color: #38bdf8;
    box-shadow: 0 4px 12px rgba(2, 132, 199, 0.2);
  }
  .debt-payment-modal .m-debt-po-pill-top {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 6px;
  }
  .debt-payment-modal .m-debt-po-num {
    font-size: 12.5px;
    font-weight: 800;
    color: #f8fafc;
  }
  .debt-payment-modal .m-debt-po-pill.is-active .m-debt-po-num {
    color: #38bdf8;
  }
  .debt-payment-modal .m-debt-po-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    flex-shrink: 0;
  }
  .debt-payment-modal .m-debt-po-dot.is-paid {
    background: #10b981;
    box-shadow: 0 0 6px rgba(16, 185, 129, 0.6);
  }
  .debt-payment-modal .m-debt-po-dot.is-unpaid {
    background: #f59e0b;
    box-shadow: 0 0 6px rgba(245, 158, 11, 0.6);
  }
  .debt-payment-modal .m-debt-po-pill-sub {
    font-size: 11px;
    font-weight: 600;
    font-variant-numeric: tabular-nums;
  }
  .debt-payment-modal .text-danger {
    color: #f87171;
  }
  .debt-payment-modal .text-success {
    color: #34d399;
  }

  .debt-payment-modal .m-debt-tabs {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 6px;
    padding: 4px;
    background: #0f172a;
    border: 1px solid #1e293b;
    border-radius: 11px;
  }
  .debt-payment-modal .m-debt-tab {
    padding: 8px 10px;
    border-radius: 8px;
    border: none;
    background: transparent;
    color: #94a3b8;
    font-size: 12px;
    font-weight: 700;
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    cursor: pointer;
    transition: all 0.18s ease;
  }
  .debt-payment-modal .m-debt-tab.active {
    background: #1e293b;
    color: #38bdf8;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.25);
  }
  .debt-payment-modal .m-debt-tab-badge {
    padding: 1px 6px;
    border-radius: 999px;
    font-size: 10.5px;
    font-weight: 800;
