    color: #38bdf8;
  }

  .debt-payment-modal .m-debt-tab-panel {
    display: flex;
    flex-direction: column;
    gap: 10px;
  }
  .debt-payment-modal .m-debt-card {
    padding: 12px;
    border-radius: 13px;
    background: #131c31;
    border: 1px solid #1e293b;
    display: flex;
    flex-direction: column;
    gap: 10px;
  }
  .debt-payment-modal .m-debt-card-head {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 8px;
  }
  .debt-payment-modal .m-debt-card-title-wrap {
    display: flex;
    flex-direction: column;
    gap: 2px;
  }
  .debt-payment-modal .m-debt-po-code {
    font-size: 14px;
    font-weight: 800;
    color: #38bdf8;
  }
  .debt-payment-modal .m-debt-po-date {
    font-size: 11px;
    color: #94a3b8;
  }
  .debt-payment-modal .m-debt-status-pill {
    padding: 4px 9px;
    border-radius: 999px;
    font-size: 11px;
    font-weight: 700;
    white-space: nowrap;
  }
  .debt-payment-modal .m-debt-status-pill.is-paid {
    background: rgba(16, 185, 129, 0.15);
    color: #34d399;
    border: 1px solid rgba(16, 185, 129, 0.35);
  }
  .debt-payment-modal .m-debt-status-pill.is-unpaid {
    background: rgba(245, 158, 11, 0.15);
    color: #fbbf24;
    border: 1px solid rgba(245, 158, 11, 0.35);
  }

  .debt-payment-modal .m-debt-card-metrics {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 6px;
    padding: 9px;
    border-radius: 10px;
    background: #0f172a;
    border: 1px solid rgba(255, 255, 255, 0.05);
  }
  .debt-payment-modal .m-debt-metric-col {
    display: flex;
    flex-direction: column;
    gap: 2px;
    min-width: 0;
  }
  .debt-payment-modal .m-debt-metric-lbl {
    font-size: 10px;
    color: #94a3b8;
    font-weight: 600;
  }
  .debt-payment-modal .m-debt-metric-val {
    font-size: 12px;
    font-weight: 800;
    color: #f8fafc;
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .debt-payment-modal .m-debt-term-editor {
    display: flex;
    flex-direction: column;
    gap: 8px;
    padding-top: 4px;
    border-top: 1px dashed #1e293b;
  }
  .debt-payment-modal .m-debt-term-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
  }
  .debt-payment-modal .m-debt-term-lbl {
    font-size: 12px;
    font-weight: 600;
    color: #cbd5e1;
  }
  .debt-payment-modal .m-debt-term-input-group {
    display: flex;
    align-items: center;
    gap: 6px;
  }
  .debt-payment-modal .m-debt-term-input {
    width: 72px;
    height: 34px;
    border-radius: 8px;
    border: 1px solid #334155;
    background: #0f172a;
    color: #f8fafc;
    font-size: 13px;
    font-weight: 700;
    text-align: center;
  }
  .debt-payment-modal .m-debt-term-unit {
    font-size: 12px;
    color: #94a3b8;
  }
  .debt-payment-modal .m-debt-due-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-size: 12px;
  }
  .debt-payment-modal .m-debt-due-lbl {
    color: #94a3b8;
  }
  .debt-payment-modal .m-debt-due-val {
    font-weight: 700;
    color: #e2e8f0;
  }
  .debt-payment-modal .m-debt-overdue-tag {
    color: #f87171;
    font-weight: 800;
  }
  .debt-payment-modal .m-debt-ontime-tag {
    color: #38bdf8;
    font-weight: 700;
  }

  .debt-payment-modal .m-debt-card-actions {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 8px;
  }
  .debt-payment-modal .m-debt-btn {
    height: 38px;
    border-radius: 9px;
    font-size: 12px;
    font-weight: 700;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    cursor: pointer;
    border: 1px solid transparent;
  }
  .debt-payment-modal .m-debt-btn-outline {
    background: #1e293b;
    border-color: #334155;
    color: #e2e8f0;
  }
  .debt-payment-modal .m-debt-btn-primary {
    background: linear-gradient(135deg, #059669, #10b981);
