  }
  .debt-payment-modal .m-debt-empty {
    padding: 28px 16px;
    border-radius: 12px;
    background: #131c31;
    border: 1px dashed #334155;
    text-align: center;
    color: #94a3b8;
    font-size: 12.5px;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
  }
  .debt-payment-modal .m-debt-history-list {
    display: flex;
    flex-direction: column;
    gap: 8px;
  }
  .debt-payment-modal .m-debt-tx-card {
    padding: 11px 12px;
