    border-top: 1px solid #1e293b;
  }
  .debt-payment-modal .m-debt-footer-btn {
    height: 42px;
    border-radius: 10px;
    font-size: 13px;
    font-weight: 800;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    cursor: pointer;
    border: 1px solid transparent;
