  .debt-payment-modal .m-debt-footer-btn.is-save {
    flex: 1;
    background: #0284c7;
    color: #ffffff;
  }
  .debt-payment-modal .m-debt-footer-btn.is-pay {
    flex: 1.25;
    background: linear-gradient(135deg, #059669, #10b981);
    color: #ffffff;
    box-shadow: 0 4px 12px rgba(16, 185, 129, 0.3);
  }
}

/* ─── 4 Ô TỆP ĐÍNH KÈM TRONG CARD PO CHÍNH (BÁO GIÁ • MUA HÀNG • DXMH • KHÁC) ─── */
.sr-po1-contract-files.is-4box-grid {
  display: grid !important;
  grid-template-columns: repeat(4, minmax(0, 1fr)) !important;
  gap: 8px !important;
  width: 100%;
  margin-top: 6px;
}

.sr-po1-file-box {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  min-width: 0;
  height: 32px;
  padding: 0 9px;
  border-radius: 7px;
  background: rgba(15, 23, 42, 0.55);
  border: 1px dashed rgba(100, 116, 139, 0.35);
  color: #64748b;
  transition: all 0.16s ease;
}

.sr-po1-file-box.has-file {
  background: rgba(15, 23, 42, 0.85);
  border: 1px solid rgba(56, 189, 248, 0.28);
  color: #e2e8f0;
  cursor: pointer;
}

.sr-po1-file-box.has-file:hover {
  border-color: rgba(56, 189, 248, 0.65);
  background: rgba(30, 41, 59, 0.92);
  transform: translateY(-1px);
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.22);
}

.sr-po1-fb-left {
  display: flex;
  align-items: center;
  gap: 5px;
  min-width: 0;
  flex: 1;
  overflow: hidden;
}

.sr-po1-fb-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: rgba(100, 116, 139, 0.45);
  flex-shrink: 0;
}

.sr-po1-file-box.has-file .sr-po1-fb-dot.is-bg {
  background: #38bdf8;
  box-shadow: 0 0 6px rgba(56, 189, 248, 0.65);
}
.sr-po1-file-box.has-file .sr-po1-fb-dot.is-mh {
  background: #a855f7;
  box-shadow: 0 0 6px rgba(168, 85, 247, 0.65);
}
.sr-po1-file-box.has-file .sr-po1-fb-dot.is-dxmh {
  background: #10b981;
  box-shadow: 0 0 6px rgba(16, 185, 129, 0.65);
}
.sr-po1-file-box.has-file .sr-po1-fb-dot.is-other {
  background: #f59e0b;
  box-shadow: 0 0 6px rgba(245, 158, 11, 0.65);
}

.sr-po1-fb-tag,
.sr-po1-file-box.has-file .sr-po1-fb-tag.is-bg,
.sr-po1-file-box.has-file .sr-po1-fb-tag.is-mh,
.sr-po1-file-box.has-file .sr-po1-fb-tag.is-dxmh,
.sr-po1-file-box.has-file .sr-po1-fb-tag.is-other {
  font-size: 9.5px;
  font-weight: 800;
  letter-spacing: 0.03em;
  padding: 2px 6px;
  border-radius: 4px;
  flex-shrink: 0;
  text-transform: uppercase;
  background: #10b981 !important;
  color: #ffffff !important;
}

.sr-po1-fb-name {
  font-size: 11px;
  font-weight: 600;
  color: #e2e8f0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  min-width: 0;
}

.sr-po1-fb-name.is-empty {
  color: #64748b;
  font-weight: 500;
  font-style: italic;
}

.sr-po1-file-box.is-other-box:hover .sr-po1-other-files-popover {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

/* Light Mode cho 4 ô tệp đính kèm */
.theme-light-blue .sr-po1-file-box,
.is-light .sr-po1-file-box {
  background: #f8fafc;
  border: 1px dashed #cbd5e1;
  color: #64748b;
}

.theme-light-blue .sr-po1-file-box.has-file,
.is-light .sr-po1-file-box.has-file {
  background: #ffffff;
  border: 1px solid #bae6fd;
  color: #0f172a;
  box-shadow: 0 1px 3px rgba(15, 23, 42, 0.04);
}

.theme-light-blue .sr-po1-file-box.has-file:hover,
.is-light .sr-po1-file-box.has-file:hover {
  border-color: #0284c7;
  background: #f0f9ff;
  box-shadow: 0 4px 10px rgba(2, 132, 199, 0.1);
}

.theme-light-blue .sr-po1-fb-name,
.is-light .sr-po1-fb-name {
  color: #1e293b;
}

.theme-light-blue .sr-po1-fb-name.is-empty,
.is-light .sr-po1-fb-name.is-empty {
  color: #94a3b8;
}

.theme-light-blue .sr-po1-fb-tag,
.is-light .sr-po1-fb-tag,
.theme-light-blue .sr-po1-file-box.has-file .sr-po1-fb-tag.is-bg,
.is-light .sr-po1-file-box.has-file .sr-po1-fb-tag.is-bg,
.theme-light-blue .sr-po1-file-box.has-file .sr-po1-fb-tag.is-mh,
.is-light .sr-po1-file-box.has-file .sr-po1-fb-tag.is-mh,
.theme-light-blue .sr-po1-file-box.has-file .sr-po1-fb-tag.is-dxmh,
.is-light .sr-po1-file-box.has-file .sr-po1-fb-tag.is-dxmh,
.theme-light-blue .sr-po1-file-box.has-file .sr-po1-fb-tag.is-other,
.is-light .sr-po1-file-box.has-file .sr-po1-fb-tag.is-other {
  background: #0284c7 !important;
  color: #ffffff !important;
}

@media (max-width: 900px) {
  .sr-po1-contract-files.is-4box-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  }
}

/* ─── SMART CUSTOMER MATCH BAR & INLINE DIFF STRIP TRONG MODAL PO ─── */
.sr-po-cust-status.is-matched {
