.sr-super-bento-grid.is-customer-bento .sr-sb-card.sb-card-debt .sr-sb-po-badge.is-emerald,
.sr-page.theme-light-blue .sr-super-bento-grid.is-customer-bento .sr-sb-card.sb-card-debt .sr-sb-po-badge.is-emerald {
  background: #ecfdf5 !important;
  border-color: #6ee7b7 !important;
  color: #059669 !important;
}

.sr-super-bento-grid.is-customer-bento .sr-sb-card.sb-card-debt .sr-sb-foot-val.money-green,
.sr-page.theme-light-blue .sr-super-bento-grid.is-customer-bento .sr-sb-card.sb-card-debt .sr-sb-foot-val.money-green {
  color: #059669 !important;
}

.sr-super-bento-grid.is-customer-bento .sr-sb-card.sb-card-debt .sr-sb-foot-val.money-blue,
.sr-page.theme-light-blue .sr-super-bento-grid.is-customer-bento .sr-sb-card.sb-card-debt .sr-sb-foot-val.money-blue {
  color: #0284c7 !important;
}

.sr-super-bento-grid.is-customer-bento .sr-sb-card.sb-card-debt .sr-sb-overdue-inline,
.sr-page.theme-light-blue .sr-super-bento-grid.is-customer-bento .sr-sb-card.sb-card-debt .sr-sb-overdue-inline {
  color: #dc2626 !important;
}

.sr-super-bento-grid.is-customer-bento .sr-sb-card.sb-card-debt .sr-sb-foot-row:hover,
.sr-page.theme-light-blue .sr-super-bento-grid.is-customer-bento .sr-sb-card.sb-card-debt .sr-sb-foot-row:hover {
  background: #fef2f2 !important;
}

.sr-super-bento-grid.is-customer-bento .sr-sb-card.sb-card-debt .sr-sb-bottom-progress,
.sr-page.theme-light-blue .sr-super-bento-grid.is-customer-bento .sr-sb-card.sb-card-debt .sr-sb-bottom-progress {
  background: #fee2e2 !important;
}

.sr-super-bento-grid.is-customer-bento .sr-sb-card.sb-card-debt .sr-sb-bottom-progress-fill,
.sr-page.theme-light-blue .sr-super-bento-grid.is-customer-bento .sr-sb-card.sb-card-debt .sr-sb-bottom-progress-fill {
  background: linear-gradient(90deg, #dc2626 0%, #059669 100%) !important;
}

/* 4. Trên Mobile (<= 768px): Nút phân tích chỉ hiển thị SVG Icon (không chữ, không emoji) để tiêu đề 4 Card KPI hiển thị đầy đủ */
@media (max-width: 768px) {
  .sr-sb-act-pill {
    width: 26px;
    height: 24px;
    padding: 0;
    border-radius: 7px;
  }

  .sr-sb-act-text {
    display: none;
  }
}

/* ─── KIỂM TRA & ĐỒNG BỘ HÀNG HÓA PO VÀO DATABASE (HANG_HOA) — CÁCH B ─── */
.sr-po-goods-title-group {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
}

.sr-po-goods-db-pills {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.sr-po-db-pill {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  line-height: 1.3;
}

.sr-po-db-pill.is-new {
  background: rgba(59, 130, 246, 0.2);
  color: #60a5fa;
  border: 1px solid rgba(59, 130, 246, 0.45);
}

.sr-po-db-pill.is-diff {
  background: rgba(245, 158, 11, 0.2);
  color: #fbbf24;
  border: 1px solid rgba(245, 158, 11, 0.45);
}

.sr-po-db-pill.is-matched {
  background: rgba(16, 185, 129, 0.2);
  color: #34d399;
  border: 1px solid rgba(16, 185, 129, 0.45);
}

.sr-po-goods-db-btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 6px 13px;
  border-radius: 8px;
  border: 1px solid #10b981;
  background: linear-gradient(135deg, #059669, #047857);
  color: #ffffff;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.18s ease;
  box-shadow: 0 2px 8px rgba(5, 150, 105, 0.35);
}

.sr-po-goods-db-btn:hover {
  background: linear-gradient(135deg, #10b981, #059669);
  color: #ffffff;
  border-color: #34d399;
  box-shadow: 0 4px 12px rgba(16, 185, 129, 0.45);
  transform: translateY(-1px);
}

.sr-po-goods-db-count {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 1px 7px;
  border-radius: 999px;
  font-size: 10.5px;
  font-weight: 800;
}

.sr-po-goods-db-count.is-warn {
  background: #ffffff;
  color: #0f172a;
}

.sr-po-goods-db-count.is-ok {
  background: rgba(255, 255, 255, 0.22);
  color: #ffffff;
  border: 1px solid rgba(255, 255, 255, 0.45);
}

.sr-goods-row-db-strip {
  margin-top: 4px;
  display: flex;
  align-items: center;
  cursor: pointer;
}

.sr-goods-db-badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: 6px;
  font-size: 10.5px;
  font-weight: 700;
  transition: all 0.15s ease;
}

.sr-goods-db-badge.is-new {
  background: rgba(59, 130, 246, 0.16);
  color: #60a5fa;
  border: 1px solid rgba(59, 130, 246, 0.36);
}

.sr-goods-db-badge.is-diff {
  background: rgba(245, 158, 11, 0.16);
  color: #fbbf24;
  border: 1px solid rgba(245, 158, 11, 0.38);
}

.sr-goods-db-badge.is-matched {
  background: rgba(16, 185, 129, 0.16);
  color: #34d399;
  border: 1px solid rgba(16, 185, 129, 0.36);
}

.sr-goods-row-db-strip:hover .sr-goods-db-badge {
  filter: brightness(1.1);
  transform: translateY(-1px);
}

/* Modal Overlay & Full-Screen Container (100% Viewport) — Main Template Font */
.sr-dbsync-overlay {
  position: fixed;
  inset: 0;
  z-index: 10200;
  background: #0b1120;
  display: flex;
  align-items: stretch;
  justify-content: stretch;
  padding: 0;
  font-family: 'Plus Jakarta Sans', 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

.sr-dbsync-overlay *,
.sr-dbsync-overlay input,
.sr-dbsync-overlay textarea,
.sr-dbsync-overlay button {
  font-family: 'Plus Jakarta Sans', 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

.sr-dbsync-modal {
  position: relative;
  width: 100vw;
  height: 100vh;
  max-width: none;
  max-height: none;
  background: #0b1120;
  border: none;
  border-radius: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  color: #f1f5f9;
}

.sr-dbsync-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 12px 24px;
  background: #0f172a;
  border-bottom: 1px solid rgba(148, 163, 184, 0.18);
  flex-shrink: 0;
}

.sr-dbsync-header-left {
  display: flex;
  align-items: center;
  gap: 14px;
}

.sr-dbsync-icon {
  width: 38px;
  height: 38px;
  border-radius: 10px;
  background: linear-gradient(135deg, #059669, #047857);
  border: 1px solid #10b981;
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.sr-dbsync-title-block {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.sr-dbsync-title-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
}

.sr-dbsync-title {
  margin: 0;
  font-size: 16px;
  font-weight: 800;
  letter-spacing: 0.01em;
  color: #f8fafc;
}

.sr-dbsync-meta-pill {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 3px 11px;
  border-radius: 999px;
  background: rgba(30, 41, 59, 0.9);
  border: 1px solid rgba(148, 163, 184, 0.25);
  font-size: 12px;
  color: #cbd5e1;
}

.sr-dbsync-meta-pill strong {
  color: #34d399;
}

.sr-dbsync-sep {
  margin: 0 6px;
  opacity: 0.45;
}

.sr-dbsync-close-btn {
  height: 36px;
  padding: 0 14px;
  border-radius: 8px;
  border: 1px solid rgba(148, 163, 184, 0.28);
  background: rgba(30, 41, 59, 0.85);
  color: #e2e8f0;
  font-size: 12.5px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  cursor: pointer;
  transition: all 0.15s ease;
}

.sr-dbsync-close-btn.is-icon-only {
  width: 32px;
  height: 32px;
  padding: 0;
}

.sr-dbsync-close-btn:hover {
  background: rgba(239, 68, 68, 0.18);
  color: #f87171;
  border-color: rgba(239, 68, 68, 0.45);
}

/* Toolbar */
.sr-dbsync-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  padding: 10px 24px;
  background: #111c33;
  border-bottom: 1px solid rgba(148, 163, 184, 0.16);
  flex-shrink: 0;
}

.sr-dbsync-tabs {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.sr-dbsync-tab {
  padding: 6px 14px;
  border-radius: 8px;
  border: 1px solid rgba(148, 163, 184, 0.24);
  background: rgba(30, 41, 59, 0.8);
  color: #cbd5e1;
  font-size: 12.5px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.15s ease;
}

.sr-dbsync-tab.active {
  background: #059669;
  border-color: #10b981;
  color: #ffffff;
}

.sr-dbsync-tab.is-new.active {
  background: #2563eb;
  border-color: #3b82f6;
}

.sr-dbsync-tab.is-diff.active {
  background: #0284c7;
  border-color: #38bdf8;
}

.sr-dbsync-tab.is-matched.active {
  background: #059669;
  border-color: #10b981;
}

.sr-dbsync-quick-btn {
  padding: 6px 13px;
  border-radius: 8px;
  border: 1px solid rgba(16, 185, 129, 0.5);
  background: rgba(16, 185, 129, 0.16);
  color: #34d399;
  font-size: 12.5px;
  font-weight: 700;
  cursor: pointer;
}

.sr-dbsync-quick-btn:hover {
  background: rgba(16, 185, 129, 0.28);
  color: #ffffff;
}

.sr-dbsync-mini-btn {
  padding: 5px 11px;
  border-radius: 6px;
  border: 1px solid rgba(148, 163, 184, 0.26);
  background: rgba(15, 23, 42, 0.85);
  color: #e2e8f0;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.15s ease;
}

.sr-dbsync-mini-btn:hover {
  border-color: #60a5fa;
  color: #ffffff;
}

/* 5-Column-Group Spacious Table */
.sr-dbsync-body {
  flex: 1;
  overflow: auto;
  padding: 0 24px 16px;
  background: #0b1120;
}

.sr-dbsync-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0 10px;
  table-layout: fixed;
  min-width: 1240px;
}

/* Table Header: Dark Mode = Solid Green, Light Mode = Solid Blue */
.sr-dbsync-table thead th {
  position: sticky;
  top: 0;
  z-index: 10;
  background: linear-gradient(135deg, #059669, #047857);
  color: #ffffff;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.03em;
  padding: 11px 12px;
  border-bottom: 2px solid #10b981;
}

.sr-dbsync-table thead th:first-child {
  border-top-left-radius: 8px;
  border-bottom-left-radius: 8px;
}

.sr-dbsync-table thead th:last-child {
  border-top-right-radius: 8px;
  border-bottom-right-radius: 8px;
}

.sr-dbsync-row td {
  padding: 12px;
  vertical-align: top;
  background: #131c31;
  border-top: 1px solid rgba(148, 163, 184, 0.18);
  border-bottom: 1px solid rgba(148, 163, 184, 0.18);
}

.sr-dbsync-row td:first-child {
  border-left: 1px solid rgba(148, 163, 184, 0.18);
  border-top-left-radius: 12px;
  border-bottom-left-radius: 12px;
}

.sr-dbsync-row td:last-child {
  border-right: 1px solid rgba(148, 163, 184, 0.18);
  border-top-right-radius: 12px;
  border-bottom-right-radius: 12px;
}

.sr-dbsync-row.is-selected td {
  background: #16233f;
  border-top-color: rgba(16, 185, 129, 0.45);
  border-bottom-color: rgba(16, 185, 129, 0.45);
}

.sr-dbsync-row.is-selected td:first-child {
  border-left: 3px solid #10b981;
}

.sr-dbsync-row.is-selected td:last-child {
  border-right-color: rgba(16, 185, 129, 0.45);
}

.sr-dbsync-idx-wrap {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding-top: 4px;
}

.sr-dbsync-checkbox {
  width: 18px;
  height: 18px;
  cursor: pointer;
  accent-color: #059669;
}

.sr-dbsync-stt-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 2px 7px;
  border-radius: 6px;
  background: rgba(30, 41, 59, 0.95);
  color: #cbd5e1;
  font-size: 11.5px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}

/* Section Banner inside each column (Định danh, Các chỉ số, Chế độ, Kết quả):
   Dark Mode = Solid Green (#059669), Light Mode = Solid Blue (#2563eb) */
.sr-dbsync-col-wrap {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.sr-dbsync-sec-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 5px 10px;
  border-radius: 7px;
  background: linear-gradient(135deg, #059669, #047857);
  color: #ffffff;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.03em;
}

/* Column 2: Product Identity & DB Match Card */
.sr-dbsync-identity-card {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.sr-dbsync-status-strip {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 6px;
}

.sr-dbsync-status-left {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
}

.sr-dbsync-status-badge {
  display: inline-flex;
  align-items: center;
  padding: 3px 9px;
  border-radius: 6px;
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: 0.02em;
}

.sr-dbsync-status-badge.is-new {
  background: rgba(37, 99, 235, 0.22);
  color: #60a5fa;
  border: 1px solid rgba(59, 130, 246, 0.45);
}

.sr-dbsync-status-badge.is-diff {
  background: rgba(14, 165, 233, 0.22);
  color: #38bdf8;
  border: 1px solid rgba(56, 189, 248, 0.45);
}

.sr-dbsync-status-badge.is-matched {
  background: rgba(16, 185, 129, 0.22);
  color: #34d399;
  border: 1px solid rgba(16, 185, 129, 0.45);
}

.sr-dbsync-db-compare-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border-radius: 6px;
  background: rgba(15, 23, 42, 0.85);
  border: 1px solid rgba(148, 163, 184, 0.24);
  font-size: 11.5px;
  color: #cbd5e1;
}

.sr-dbsync-db-compare-pill strong {
  color: #ffffff;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.sr-dbsync-link-actions {
  display: flex;
  align-items: center;
  gap: 5px;
}

.sr-dbsync-link-btn {
  padding: 2px 8px;
  border-radius: 5px;
  border: 1px solid rgba(255, 255, 255, 0.38);
  background: rgba(255, 255, 255, 0.16);
  color: #ffffff;
  font-size: 10.5px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.15s ease;
}

.sr-dbsync-link-btn:hover {
  background: #ffffff;
  color: #047857;
  border-color: #ffffff;
}

.sr-dbsync-link-btn.is-unlink {
  background: rgba(239, 68, 68, 0.85);
  color: #ffffff;
  border-color: rgba(254, 202, 202, 0.6);
}

.sr-dbsync-link-btn.is-unlink:hover {
  background: #dc2626;
  color: #ffffff;
}

.sr-dbsync-name-textarea {
  width: 100%;
  padding: 7px 10px;
  border-radius: 8px;
  border: 1px solid rgba(148, 163, 184, 0.28);
  background: rgba(15, 23, 42, 0.92);
  color: #f8fafc;
  font-size: 13.5px;
  font-weight: 600;
  line-height: 1.4;
  resize: vertical;
  outline: none;
  box-sizing: border-box;
}

.sr-dbsync-meta-inputs {
  display: grid;
  grid-template-columns: 1.2fr 1.15fr 112px;
  gap: 8px;
}

.sr-dbsync-labeled-field {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.sr-dbsync-labeled-field label {
  font-size: 10.5px;
  font-weight: 700;
  color: #94a3b8;
}

.sr-dbsync-input-with-btn {
  display: flex;
  align-items: center;
  gap: 4px;
}

.sr-dbsync-input-with-btn .sr-dbsync-input {
  flex: 1;
  min-width: 0;
}

.sr-dbsync-pick-inline-btn {
  height: 32px;
  padding: 0 9px;
  border-radius: 7px;
  border: 1px solid #10b981;
  background: #059669;
  color: #ffffff;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  flex-shrink: 0;
  white-space: nowrap;
  transition: all 0.15s ease;
}

.sr-dbsync-pick-inline-btn:hover {
  background: #047857;
  border-color: #34d399;
}

.sr-dbsync-input {
  width: 100%;
  height: 32px;
  padding: 4px 9px;
  border-radius: 7px;
  border: 1px solid rgba(148, 163, 184, 0.28);
  background: rgba(15, 23, 42, 0.92);
  color: #f8fafc;
  font-size: 13px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  outline: none;
  box-sizing: border-box;
}

.sr-dbsync-input:focus,
.sr-dbsync-name-textarea:focus {
  border-color: #3b82f6;
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.22);
}

.sr-dbsync-input.is-code {
  color: #60a5fa;
  font-weight: 700;
  font-size: 12px;
}

.sr-dbsync-input.is-cat {
  color: #34d399;
  font-weight: 700;
  font-size: 12px;
  text-transform: uppercase;
}

/* Column 3: 2x2 Calculation Inputs Grid */
.sr-dbsync-calc-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
  padding: 8px 10px;
  border-radius: 10px;
  background: rgba(15, 23, 42, 0.72);
  border: 1px solid rgba(148, 163, 184, 0.2);
}

.sr-dbsync-calc-field {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.sr-dbsync-calc-field label {
  font-size: 11px;
  font-weight: 700;
  color: #cbd5e1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.sr-dbsync-off-label-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 4px;
}

.sr-dbsync-off-mode-switch {
  display: inline-flex;
  border-radius: 5px;
  overflow: hidden;
  border: 1px solid rgba(148, 163, 184, 0.35);
  background: rgba(15, 23, 42, 0.95);
}

.sr-dbsync-off-mode-switch button {
  padding: 1px 7px;
  border: none;
  background: transparent;
  color: #94a3b8;
  font-size: 10px;
  font-weight: 800;
  cursor: pointer;
}

.sr-dbsync-off-mode-switch button.active {
  background: #059669;
  color: #ffffff;
}

.sr-dbsync-input.is-file-price {
  color: #38bdf8;
  font-weight: 700;
}

.sr-dbsync-input.is-cost-price {
  color: #34d399;
  font-weight: 700;
}

.sr-dbsync-pct-input-wrap {
  position: relative;
  display: flex;
  align-items: center;
}

.sr-dbsync-pct-input-wrap .sr-dbsync-input {
  padding-right: 24px;
}

.sr-dbsync-pct-unit {
  position: absolute;
  right: 8px;
  font-size: 11.5px;
  font-weight: 800;
  color: #94a3b8;
  pointer-events: none;
}

/* Column 4: Price Mode Radio Cards & Currency Bar (Only Blue & Green, NO Yellow) */
.sr-dbsync-choice-stack {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.sr-dbsync-radio-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.sr-dbsync-radio-card {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 8px 11px;
  border-radius: 8px;
  border: 1px solid rgba(148, 163, 184, 0.24);
  background: rgba(15, 23, 42, 0.85);
  color: #cbd5e1;
  cursor: pointer;
  transition: all 0.15s ease;
  text-align: left;
}

.sr-dbsync-radio-dot {
  width: 14px;
  height: 14px;
  border-radius: 999px;
  border: 2px solid #64748b;
  flex-shrink: 0;
  position: relative;
}

.sr-dbsync-radio-card.active .sr-dbsync-radio-dot {
  border-color: #60a5fa;
}

.sr-dbsync-radio-card.active .sr-dbsync-radio-dot::after {
  content: '';
  position: absolute;
  inset: 2px;
  border-radius: 999px;
  background: #60a5fa;
}

.sr-dbsync-radio-card.is-calc.active .sr-dbsync-radio-dot {
  border-color: #34d399;
}

.sr-dbsync-radio-card.is-calc.active .sr-dbsync-radio-dot::after {
  background: #34d399;
}

.sr-dbsync-radio-text {
  font-size: 12px;
  font-weight: 700;
  flex: 1;
}

.sr-dbsync-radio-val {
  font-size: 13px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  color: #f8fafc;
}

.sr-dbsync-radio-card.active {
  background: rgba(37, 99, 235, 0.22);
  border-color: #3b82f6;
  color: #93c5fd;
}

.sr-dbsync-radio-card.is-calc.active {
  background: rgba(16, 185, 129, 0.2);
  border-color: #10b981;
  color: #6ee7b7;
}

.sr-dbsync-currency-row {
  display: flex;
  flex-direction: column;
  gap: 8px;
  padding: 8px 10px;
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.78);
  border: 1px solid rgba(148, 163, 184, 0.22);
}

.sr-dbsync-currency-row.is-usd {
  border-color: rgba(37, 99, 235, 0.65);
  background: rgba(37, 99, 235, 0.16);
}

.sr-dbsync-cur-left {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 7px;
}

.sr-dbsync-cur-lbl {
  font-size: 11.5px;
  font-weight: 700;
  color: #cbd5e1;
}

.sr-dbsync-cur-switch {
  display: inline-grid;
  grid-template-columns: 1fr 1fr;
  border-radius: 6px;
  overflow: hidden;
  border: 1px solid rgba(148, 163, 184, 0.35);
  background: rgba(15, 23, 42, 0.95);
}

.sr-dbsync-cur-switch button {
  padding: 4px 11px;
  border: none;
  background: transparent;
  color: #94a3b8;
  font-size: 11.5px;
  font-weight: 800;
  cursor: pointer;
}

.sr-dbsync-cur-switch button.active {
  background: #059669;
  color: #ffffff;
}

.sr-dbsync-rate-inline {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  padding-top: 4px;
  border-top: 1px dashed rgba(59, 130, 246, 0.35);
}

.sr-dbsync-rate-inline label {
  font-size: 11.5px;
  font-weight: 800;
  color: #60a5fa;
  white-space: nowrap;
}

.sr-dbsync-input-with-btn.is-rate-wrap {
  flex: 1;
  justify-content: flex-end;
}

.sr-dbsync-input.is-rate {
  width: 105px;
  height: 30px;
  border: 1.5px solid #3b82f6;
  background: #0f172a;
  color: #60a5fa;
  font-weight: 800;
}

/* Column 5: Result Summary Card (Green for VND, Blue for USD) */
.sr-dbsync-result-card {
  padding: 10px 12px;
  border-radius: 10px;
  background: rgba(6, 78, 59, 0.25);
  border: 1px solid rgba(16, 185, 129, 0.45);
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.sr-dbsync-result-card.is-usd {
  background: rgba(30, 58, 138, 0.28);
  border-color: rgba(59, 130, 246, 0.55);
}

.sr-dbsync-result-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 4px;
  border-bottom: 1px dashed rgba(148, 163, 184, 0.25);
}

.sr-dbsync-result-action {
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: 0.02em;
  color: #cbd5e1;
}

.sr-dbsync-result-cur-tag {
  padding: 2px 8px;
  border-radius: 4px;
  background: #059669;
  color: #ffffff;
  font-size: 10.5px;
  font-weight: 800;
}

.sr-dbsync-result-card.is-usd .sr-dbsync-result-cur-tag {
  background: #2563eb;
  color: #ffffff;
}

.sr-dbsync-result-metric {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 6px;
}

.sr-dbsync-result-lbl {
  font-size: 11.5px;
  font-weight: 600;
  color: #cbd5e1;
}

.sr-dbsync-result-val {
  font-size: 14px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}

.sr-dbsync-result-val.is-vnd {
  color: #34d399;
}

.sr-dbsync-result-val.is-usd {
  color: #60a5fa;
}

.sr-dbsync-result-sub {
  font-size: 13px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.sr-dbsync-result-sub.is-vnd {
  color: #a7f3d0;
}

.sr-dbsync-result-sub.is-usd {
  color: #93c5fd;
}

.sr-dbsync-result-footnote {
  margin-top: 2px;
  font-size: 11px;
  font-weight: 600;
  color: #60a5fa;
  line-height: 1.35;
}

/* Picker Sub-modals (SP DB & Danh mục / ĐVT / Tỉ giá) */
.sr-dbsync-picker-backdrop {
  position: absolute;
  inset: 0;
  z-index: 30;
  background: rgba(2, 6, 23, 0.78);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}

.sr-dbsync-picker-card {
  width: min(740px, 95%);
  max-height: 78vh;
  background: #1e293b;
  border: 1px solid rgba(148, 163, 184, 0.35);
  border-radius: 12px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.65);
}

.sr-dbsync-picker-card.is-attr-picker {
  width: min(620px, 94%);
}

.sr-dbsync-picker-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  background: linear-gradient(135deg, #059669, #047857);
  color: #ffffff;
}

.sr-dbsync-picker-head h4 {
  margin: 0;
  font-size: 14px;
  font-weight: 800;
  color: #ffffff;
}

.sr-dbsync-picker-search {
  display: flex;
  gap: 8px;
  padding: 10px 16px;
  border-bottom: 1px solid rgba(148, 163, 184, 0.18);
}

.sr-dbsync-picker-list {
  flex: 1;
  overflow-y: auto;
  padding: 8px 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.sr-dbsync-attr-grid {
  flex: 1;
  overflow-y: auto;
  padding: 12px 16px;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(165px, 1fr));
  gap: 8px;
}

.sr-dbsync-attr-chip {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 9px 12px;
  border-radius: 8px;
  border: 1px solid rgba(148, 163, 184, 0.25);
  background: rgba(15, 23, 42, 0.85);
  color: #f8fafc;
  cursor: pointer;
  transition: all 0.15s ease;
  text-align: left;
}

.sr-dbsync-attr-chip:hover {
  border-color: #10b981;
  background: rgba(5, 150, 105, 0.22);
}

.sr-dbsync-attr-val {
  font-size: 12.5px;
  font-weight: 700;
  color: #f8fafc;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sr-dbsync-attr-cnt {
  padding: 2px 6px;
  border-radius: 999px;
  background: rgba(16, 185, 129, 0.2);
  color: #34d399;
  font-size: 10.5px;
  font-weight: 700;
  flex-shrink: 0;
}

.sr-dbsync-picker-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 9px 12px;
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.78);
  border: 1px solid rgba(148, 163, 184, 0.16);
  cursor: pointer;
  transition: all 0.15s ease;
}

.sr-dbsync-picker-item:hover {
  border-color: #3b82f6;
  background: rgba(37, 99, 235, 0.16);
}

.sr-dbsync-picker-item-left {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.sr-dbsync-picker-code {
  padding: 2px 6px;
  border-radius: 4px;
  background: rgba(59, 130, 246, 0.18);
  color: #93c5fd;
  font-size: 11.5px;
  font-weight: 700;
}

.sr-dbsync-picker-name {
  font-size: 12.5px;
  color: #f8fafc;
}

.sr-dbsync-picker-cat {
  padding: 1px 6px;
  border-radius: 4px;
  background: rgba(16, 185, 129, 0.18);
  color: #34d399;
  font-size: 10.5px;
  font-weight: 700;
}

.sr-dbsync-picker-item-right {
  font-size: 12px;
  color: #cbd5e1;
  white-space: nowrap;
}

/* Footer */
.sr-dbsync-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  padding: 12px 24px;
  background: #0f172a;
  border-top: 1px solid rgba(148, 163, 184, 0.2);
  flex-shrink: 0;
}

.sr-dbsync-footer-info {
  font-size: 13px;
  color: #94a3b8;
}

.sr-dbsync-footer-info strong {
  color: #f8fafc;
}

.sr-dbsync-footer-info .text-sky {
  color: #38bdf8;
}

.sr-dbsync-footer-info .text-amber {
  color: #34d399;
}

.sr-dbsync-footer-actions {
  display: flex;
  align-items: center;
  gap: 10px;
}

.sr-dbsync-cancel-btn {
  padding: 9px 18px;
  border-radius: 8px;
  border: 1px solid rgba(148, 163, 184, 0.28);
  background: rgba(30, 41, 59, 0.85);
  color: #cbd5e1;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
}

.sr-dbsync-save-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 9px 22px;
  border-radius: 8px;
  border: none;
  background: linear-gradient(135deg, #059669, #047857);
  color: #ffffff;
  font-size: 13.5px;
  font-weight: 800;
  cursor: pointer;
  box-shadow: 0 4px 14px rgba(5, 150, 105, 0.35);
}

.sr-dbsync-save-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  box-shadow: none;
}

.sr-dbsync-empty {
  padding: 32px;
  text-align: center;
  color: #94a3b8;
  font-size: 13.5px;
}

/* ─── LIGHT MODE OVERRIDES (Modal PO is Teleported to body with .sr-po-modal.is-light / .theme-light-blue) ─── */
.sr-po-modal.is-light .sr-po-goods-db-btn,
.theme-light-blue .sr-po-goods-db-btn,
.sr-page.theme-light-blue .sr-po-goods-db-btn {
  background: linear-gradient(135deg, #2563eb, #1d4ed8);
  border: 1px solid #1e40af;
  color: #ffffff;
  box-shadow: 0 3px 10px rgba(37, 99, 235, 0.32);
}

.sr-po-modal.is-light .sr-po-goods-db-btn:hover,
.theme-light-blue .sr-po-goods-db-btn:hover,
.sr-page.theme-light-blue .sr-po-goods-db-btn:hover {
  background: linear-gradient(135deg, #1d4ed8, #1e3a8a);
  color: #ffffff;
  border-color: #1e3a8a;
  box-shadow: 0 5px 14px rgba(29, 78, 216, 0.42);
}

.sr-po-modal.is-light .sr-po-db-pill.is-new,
.theme-light-blue .sr-po-db-pill.is-new {
  background: #dbeafe;
  color: #1d4ed8;
  border-color: #93c5fd;
}

.sr-po-modal.is-light .sr-po-db-pill.is-diff,
.theme-light-blue .sr-po-db-pill.is-diff {
  background: #e0f2fe;
  color: #0369a1;
  border-color: #7dd3fc;
}

.sr-po-modal.is-light .sr-po-db-pill.is-matched,
.theme-light-blue .sr-po-db-pill.is-matched {
  background: #d1fae5;
  color: #047857;
  border-color: #6ee7b7;
}

.sr-po-modal.is-light .sr-goods-db-badge.is-new,
.theme-light-blue .sr-goods-db-badge.is-new,
.sr-page.theme-light-blue .sr-goods-db-badge.is-new {
  background: #dbeafe;
  color: #1d4ed8;
  border-color: #93c5fd;
}

.sr-po-modal.is-light .sr-goods-db-badge.is-diff,
.theme-light-blue .sr-goods-db-badge.is-diff,
.sr-page.theme-light-blue .sr-goods-db-badge.is-diff {
  background: #e0f2fe;
  color: #0369a1;
  border-color: #7dd3fc;
}

.sr-po-modal.is-light .sr-goods-db-badge.is-matched,
.theme-light-blue .sr-goods-db-badge.is-matched,
.sr-page.theme-light-blue .sr-goods-db-badge.is-matched {
  background: #d1fae5;
  color: #047857;
  border-color: #6ee7b7;
}

/* Light Mode for Full-Screen Sync Modal (.sr-dbsync-overlay.is-light) */
.sr-dbsync-overlay.is-light,
.sr-dbsync-overlay.is-light .sr-dbsync-modal,
.sr-dbsync-overlay.is-light .sr-dbsync-body {
  background: #f1f5f9;
  color: #0f172a;
}

.sr-dbsync-overlay.is-light .sr-dbsync-header,
.sr-dbsync-overlay.is-light .sr-dbsync-toolbar,
.sr-dbsync-overlay.is-light .sr-dbsync-footer {
  background: #ffffff;
  border-color: #cbd5e1;
}

.sr-dbsync-overlay.is-light .sr-dbsync-icon {
  background: linear-gradient(135deg, #2563eb, #1d4ed8);
  border-color: #1d4ed8;
  color: #ffffff;
}

.sr-dbsync-overlay.is-light .sr-dbsync-title,
.sr-dbsync-overlay.is-light .sr-dbsync-footer-info strong {
  color: #0f172a;
}

.sr-dbsync-overlay.is-light .sr-dbsync-meta-pill {
  background: #eff6ff;
  border-color: #bfdbfe;
  color: #1e3a8a;
}

.sr-dbsync-overlay.is-light .sr-dbsync-meta-pill strong {
  color: #1d4ed8;
}

/* Light Mode Headers (Table Header & Column Section Banners) = Solid Blue (#2563eb) with White text */
.sr-dbsync-overlay.is-light .sr-dbsync-table thead th {
  background: linear-gradient(135deg, #2563eb, #1d4ed8);
  color: #ffffff;
  border-bottom: 2px solid #1e40af;
}

.sr-dbsync-overlay.is-light .sr-dbsync-sec-banner,
.sr-dbsync-overlay.is-light .sr-dbsync-picker-head {
  background: linear-gradient(135deg, #2563eb, #1d4ed8);
  color: #ffffff;
}

.sr-dbsync-overlay.is-light .sr-dbsync-link-btn:hover {
  background: #ffffff;
  color: #1d4ed8;
}

.sr-dbsync-overlay.is-light .sr-dbsync-checkbox {
  accent-color: #2563eb;
}

.sr-dbsync-overlay.is-light .sr-dbsync-stt-pill {
  background: #e2e8f0;
  color: #1e293b;
}

.sr-dbsync-overlay.is-light .sr-dbsync-row td {
  background: #ffffff;
  border-color: #cbd5e1;
}

.sr-dbsync-overlay.is-light .sr-dbsync-row.is-selected td {
