}

.sr-dbsync-overlay.is-light .sr-dbsync-status-badge.is-new {
  background: #dbeafe;
  color: #1d4ed8;
  border-color: #93c5fd;
}

.sr-dbsync-overlay.is-light .sr-dbsync-status-badge.is-diff {
  background: #e0f2fe;
  color: #0369a1;
  border-color: #7dd3fc;
}

.sr-dbsync-overlay.is-light .sr-dbsync-status-badge.is-matched {
  background: #d1fae5;
  color: #047857;
  border-color: #6ee7b7;
}

.sr-dbsync-overlay.is-light .sr-dbsync-calc-grid,
.sr-dbsync-overlay.is-light .sr-dbsync-currency-row:not(.is-usd),
.sr-dbsync-overlay.is-light .sr-dbsync-db-compare-pill {
