  border-color: #cbd5e1;
  color: #334155;
}

.sr-dbsync-overlay.is-light .sr-dbsync-calc-field label,
.sr-dbsync-overlay.is-light .sr-dbsync-labeled-field label,
.sr-dbsync-overlay.is-light .sr-dbsync-cur-lbl {
  color: #334155;
}

.sr-dbsync-overlay.is-light .sr-dbsync-db-compare-pill strong,
.sr-dbsync-overlay.is-light .sr-dbsync-radio-val {
