}

.sr-dbsync-overlay.is-light .sr-dbsync-input,
.sr-dbsync-overlay.is-light .sr-dbsync-name-textarea,
.sr-dbsync-overlay.is-light .sr-dbsync-radio-card:not(.active),
.sr-dbsync-overlay.is-light .sr-dbsync-tab:not(.active),
.sr-dbsync-overlay.is-light .sr-dbsync-mini-btn,
.sr-dbsync-overlay.is-light .sr-dbsync-close-btn,
.sr-dbsync-overlay.is-light .sr-dbsync-cancel-btn {
