}

.sr-dbsync-overlay.is-light .sr-dbsync-tab.active {
  background: #2563eb;
  border-color: #1d4ed8;
  color: #ffffff;
}

.sr-dbsync-overlay.is-light .sr-dbsync-quick-btn {
  background: #eff6ff;
  border-color: #60a5fa;
  color: #1d4ed8;
}

.sr-dbsync-overlay.is-light .sr-dbsync-quick-btn:hover {
  background: #2563eb;
  color: #ffffff;
}

.sr-dbsync-overlay.is-light .sr-dbsync-pick-inline-btn {
  background: #2563eb;
  border-color: #1d4ed8;
  color: #ffffff;
}

.sr-dbsync-overlay.is-light .sr-dbsync-pick-inline-btn:hover {
  background: #1d4ed8;
}

.sr-dbsync-overlay.is-light .sr-dbsync-input.is-code {
  color: #1d4ed8;
}

.sr-dbsync-overlay.is-light .sr-dbsync-input.is-cat {
  color: #047857;
}

.sr-dbsync-overlay.is-light .sr-dbsync-input.is-file-price {
  color: #1d4ed8;
}

.sr-dbsync-overlay.is-light .sr-dbsync-input.is-cost-price {
  color: #047857;
}

.sr-dbsync-overlay.is-light .sr-dbsync-off-mode-switch,
.sr-dbsync-overlay.is-light .sr-dbsync-cur-switch {
  background: #f1f5f9;
  border-color: #cbd5e1;
}

.sr-dbsync-overlay.is-light .sr-dbsync-off-mode-switch button,
.sr-dbsync-overlay.is-light .sr-dbsync-cur-switch button {
  color: #475569;
}

.sr-dbsync-overlay.is-light .sr-dbsync-off-mode-switch button.active,
.sr-dbsync-overlay.is-light .sr-dbsync-cur-switch button.active {
  background: #2563eb;
  color: #ffffff;
}

/* Light Mode Tỉ giá (Ti_gia) — Crisp Blue & Green, Easy to Read */
.sr-dbsync-overlay.is-light .sr-dbsync-currency-row.is-usd {
  background: #eff6ff;
  border-color: #60a5fa;
}

.sr-dbsync-overlay.is-light .sr-dbsync-rate-inline {
  border-top-color: #bfdbfe;
}

.sr-dbsync-overlay.is-light .sr-dbsync-rate-inline label {
  color: #1d4ed8;
}

.sr-dbsync-overlay.is-light .sr-dbsync-input.is-rate {
  background: #ffffff;
  border: 1.5px solid #2563eb;
  color: #1d4ed8;
  font-weight: 800;
}

.sr-dbsync-overlay.is-light .sr-dbsync-radio-card.active {
  background: #eff6ff;
  border-color: #2563eb;
  color: #1d4ed8;
}

.sr-dbsync-overlay.is-light .sr-dbsync-radio-card.is-calc.active {
  background: #ecfdf5;
  border-color: #059669;
  color: #047857;
}

.sr-dbsync-overlay.is-light .sr-dbsync-result-card {
  background: #ecfdf5;
  border-color: #34d399;
}

.sr-dbsync-overlay.is-light .sr-dbsync-result-card.is-usd {
  background: #eff6ff;
  border-color: #60a5fa;
}

.sr-dbsync-overlay.is-light .sr-dbsync-result-action {
  color: #1e293b;
}

.sr-dbsync-overlay.is-light .sr-dbsync-result-lbl {
  color: #334155;
}

.sr-dbsync-overlay.is-light .sr-dbsync-result-val.is-vnd {
  color: #047857;
}

.sr-dbsync-overlay.is-light .sr-dbsync-result-val.is-usd {
  color: #1d4ed8;
}

.sr-dbsync-overlay.is-light .sr-dbsync-result-sub.is-vnd {
  color: #065f46;
}

.sr-dbsync-overlay.is-light .sr-dbsync-result-sub.is-usd {
  color: #1e40af;
}

.sr-dbsync-overlay.is-light .sr-dbsync-result-footnote {
  color: #1d4ed8;
}

.sr-dbsync-overlay.is-light .sr-dbsync-picker-card {
  background: #ffffff;
  border-color: #cbd5e1;
  color: #0f172a;
}

.sr-dbsync-overlay.is-light .sr-dbsync-picker-item,
.sr-dbsync-overlay.is-light .sr-dbsync-attr-chip {
  background: #f8fafc;
  border-color: #cbd5e1;
  color: #0f172a;
}

.sr-dbsync-overlay.is-light .sr-dbsync-picker-item:hover,
.sr-dbsync-overlay.is-light .sr-dbsync-attr-chip:hover {
  background: #eff6ff;
  border-color: #2563eb;
}

.sr-dbsync-overlay.is-light .sr-dbsync-picker-name,
.sr-dbsync-overlay.is-light .sr-dbsync-attr-val {
  color: #0f172a;
}

.sr-dbsync-overlay.is-light .sr-dbsync-picker-code {
  background: #dbeafe;
  color: #1d4ed8;
}

.sr-dbsync-overlay.is-light .sr-dbsync-picker-cat,
.sr-dbsync-overlay.is-light .sr-dbsync-attr-cnt {
  background: #d1fae5;
  color: #047857;
}

.sr-dbsync-overlay.is-light .sr-dbsync-picker-item-right {
  color: #334155;
}

.sr-dbsync-overlay.is-light .sr-dbsync-save-btn {
  background: linear-gradient(135deg, #2563eb, #1d4ed8);
  box-shadow: 0 4px 14px rgba(37, 99, 235, 0.35);
}

/* ==========================================================================
   UNIFIED TEMPLATE DIALOG MODAL (ALERT & CONFIRM — DARK & LIGHT PARITY)
   ========================================================================== */
.sr-dialog-overlay {
  display: flex !important;
  align-items: center !important;
  justify-content: center !important;
  padding: 16px !important;
  background: rgba(3, 8, 18, 0.74) !important;
  backdrop-filter: blur(5px) !important;
  -webkit-backdrop-filter: blur(5px) !important;
  font-family: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif !important;
}

.sr-dialog-overlay.is-light {
  background: rgba(15, 23, 42, 0.45) !important;
}

.sr-dialog-card {
  width: 476px !important;
  max-width: 94vw !important;
  height: auto !important;
  max-height: 88dvh !important;
  padding: 0 !important;
  border-radius: 14px !important;
  display: flex !important;
  flex-direction: column !important;
  overflow: hidden !important;
  background: linear-gradient(180deg, #111c30 0%, #0b1322 100%) !important;
  border: 1px solid rgba(56, 189, 248, 0.28) !important;
  box-shadow:
    0 24px 56px -12px rgba(0, 0, 0, 0.76),
    0 0 0 1px rgba(255, 255, 255, 0.04) inset !important;
  color: #f8fafc;
}

.sr-dialog-card.is-variant-success {
  border-color: rgba(16, 185, 129, 0.38) !important;
}

.sr-dialog-card.is-variant-danger,
.sr-dialog-card.is-variant-error {
  border-color: rgba(248, 113, 113, 0.35) !important;
}

.sr-dialog-card.is-light {
  background: #ffffff !important;
  border: 1px solid #cbd5e1 !important;
  box-shadow:
    0 22px 48px -12px rgba(15, 23, 42, 0.24),
    0 4px 14px rgba(2, 132, 199, 0.08) !important;
  color: #0f172a;
}

.sr-dialog-head {
  position: relative;
  padding: 13px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-shrink: 0;
  background: linear-gradient(135deg, #0369a1 0%, #1d4ed8 100%);
  border-bottom: 1px solid rgba(255, 255, 255, 0.12);
}

.sr-dialog-card.is-variant-success .sr-dialog-head {
  background: linear-gradient(135deg, #059669 0%, #047857 100%);
}

.sr-dialog-card.is-variant-danger .sr-dialog-head,
.sr-dialog-card.is-variant-error .sr-dialog-head {
  background: linear-gradient(135deg, #dc2626 0%, #b91c1c 100%);
}

.sr-dialog-dt-head {
  display: flex;
  align-items: center;
  gap: 9px;
  color: #ffffff;
  text-transform: uppercase;
  font-weight: 800;
  font-size: 14px;
  letter-spacing: 0.35px;
  padding-right: 34px;
}

.sr-dialog-head-ico {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #ffffff;
  flex-shrink: 0;
}

.sr-dialog-m-head {
  display: none;
  flex-direction: column;
  gap: 2px;
  padding-right: 34px;
}

.sr-dialog-m-eyebrow {
  font-size: 10.5px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: rgba(255, 255, 255, 0.82);
}

.sr-dialog-m-title {
  font-size: 14.5px;
  font-weight: 800;
  color: #ffffff;
}

.sr-dialog-close-x {
  color: #ffffff;
  position: absolute;
  right: 14px;
  top: 50%;
  transform: translateY(-50%);
  background: rgba(0, 0, 0, 0.2);
  border-radius: 50%;
  width: 28px;
  height: 28px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid rgba(255, 255, 255, 0.18);
  cursor: pointer;
  transition: background 0.18s ease, transform 0.18s ease;
}

.sr-dialog-close-x:hover {
  background: rgba(255, 255, 255, 0.22);
}

.sr-dialog-body {
  padding: 18px 20px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  overflow-y: auto;
}

/* Target Entity Card */
.sr-dialog-target-card {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 11px 13px;
  border-radius: 10px;
  background: rgba(30, 41, 59, 0.72);
  border: 1px solid rgba(148, 163, 184, 0.24);
}

.sr-dialog-card.is-light .sr-dialog-target-card {
  background: #f8fafc;
  border-color: #cbd5e1;
}

.sr-dialog-target-icon {
  width: 38px;
  height: 38px;
  border-radius: 10px;
  background: rgba(14, 165, 233, 0.16);
  border: 1px solid rgba(56, 189, 248, 0.35);
  color: #38bdf8;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.sr-dialog-card.is-variant-success .sr-dialog-target-icon {
  background: rgba(16, 185, 129, 0.16);
  border-color: rgba(52, 211, 153, 0.35);
  color: #34d399;
}

.sr-dialog-card.is-variant-danger .sr-dialog-target-icon,
.sr-dialog-card.is-variant-error .sr-dialog-target-icon {
  background: rgba(239, 68, 68, 0.16);
  border-color: rgba(248, 113, 113, 0.35);
  color: #f87171;
}

.sr-dialog-card.is-light .sr-dialog-target-icon {
  background: #e0f2fe;
  border-color: #7dd3fc;
  color: #0284c7;
}

.sr-dialog-card.is-light.is-variant-success .sr-dialog-target-icon {
  background: #d1fae5;
  border-color: #6ee7b7;
  color: #059669;
}

.sr-dialog-card.is-light.is-variant-danger .sr-dialog-target-icon,
.sr-dialog-card.is-light.is-variant-error .sr-dialog-target-icon {
  background: #fee2e2;
  border-color: #fecaca;
  color: #dc2626;
}

.sr-dialog-target-info {
  min-width: 0;
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.sr-dialog-target-tag {
  font-size: 11px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.35px;
  color: #94a3b8;
}

.sr-dialog-card.is-light .sr-dialog-target-tag {
  color: #64748b;
}

.sr-dialog-target-val {
  font-size: 13.5px;
  font-weight: 700;
  color: #f8fafc;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sr-dialog-card.is-light .sr-dialog-target-val {
  color: #0f172a;
}

/* Semantic Message Box (Blue / Emerald / Rose — no hard-to-read yellow in Light Mode) */
.sr-dialog-msg-box {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 12px 14px;
  border-radius: 10px;
  font-size: 13.5px;
  line-height: 1.55;
  background: rgba(14, 165, 233, 0.11);
  border: 1px solid rgba(56, 189, 248, 0.32);
  color: #e0f2fe;
}

.sr-dialog-card.is-variant-success .sr-dialog-msg-box {
  background: rgba(16, 185, 129, 0.12);
  border-color: rgba(52, 211, 153, 0.35);
  color: #d1fae5;
}

.sr-dialog-card.is-variant-danger .sr-dialog-msg-box,
.sr-dialog-card.is-variant-error .sr-dialog-msg-box {
  background: rgba(239, 68, 68, 0.12);
  border-color: rgba(248, 113, 113, 0.35);
  color: #fee2e2;
}

.sr-dialog-card.is-light .sr-dialog-msg-box {
  background: #eff6ff;
  border-color: #93c5fd;
  color: #1e3a8a;
}

.sr-dialog-card.is-light.is-variant-success .sr-dialog-msg-box {
  background: #ecfdf5;
  border-color: #6ee7b7;
  color: #065f46;
}

.sr-dialog-card.is-light.is-variant-danger .sr-dialog-msg-box,
.sr-dialog-card.is-light.is-variant-error .sr-dialog-msg-box {
  background: #fef2f2;
  border-color: #fecaca;
  color: #991b1b;
}

.sr-dialog-msg-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-top: 2px;
  flex-shrink: 0;
  color: #38bdf8;
}

.sr-dialog-card.is-variant-success .sr-dialog-msg-icon {
  color: #34d399;
}

.sr-dialog-card.is-variant-danger .sr-dialog-msg-icon,
.sr-dialog-card.is-variant-error .sr-dialog-msg-icon {
  color: #f87171;
}

.sr-dialog-card.is-light .sr-dialog-msg-icon {
  color: #0284c7;
}

.sr-dialog-card.is-light.is-variant-success .sr-dialog-msg-icon {
  color: #059669;
}

.sr-dialog-card.is-light.is-variant-danger .sr-dialog-msg-icon,
.sr-dialog-card.is-light.is-variant-error .sr-dialog-msg-icon {
  color: #dc2626;
}

.sr-dialog-msg-text {
  flex: 1;
  min-width: 0;
  white-space: pre-line;
  font-weight: 500;
}

/* Subnote */
.sr-dialog-subnote {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 9px 12px;
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.58);
  border: 1px solid rgba(148, 163, 184, 0.18);
  color: #94a3b8;
  font-size: 12.5px;
  line-height: 1.48;
}

.sr-dialog-card.is-light .sr-dialog-subnote {
  background: #f8fafc;
  border-color: #e2e8f0;
  color: #475569;
}

.sr-dialog-subnote-ico {
  margin-top: 1px;
  color: #64748b;
  flex-shrink: 0;
}

/* Footer */
.sr-dialog-foot {
  padding: 12px 20px !important;
  display: flex !important;
  align-items: center !important;
  justify-content: flex-end !important;
  gap: 10px !important;
  background: rgba(9, 15, 28, 0.78) !important;
  border-top: 1px solid rgba(148, 163, 184, 0.16) !important;
}

.sr-dialog-card.is-light .sr-dialog-foot {
  background: #f8fafc !important;
  border-top: 1px solid #e2e8f0 !important;
}

.sr-dialog-foot button.sr-dlg-btn {
  width: auto !important;
  margin: 0 !important;
  height: 38px !important;
  min-height: 38px !important;
  padding: 0 16px !important;
  border-radius: 8px !important;
  font-size: 13px !important;
  font-weight: 700 !important;
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  gap: 6px !important;
  white-space: nowrap !important;
  cursor: pointer !important;
  transition: transform 0.15s ease, box-shadow 0.18s ease, background 0.18s ease !important;
}

.sr-dialog-foot button.sr-dlg-btn:focus-visible {
  outline: 2px solid #38bdf8 !important;
  outline-offset: 2px !important;
}

.sr-dialog-foot button.sr-dlg-cancel {
  background: rgba(30, 41, 59, 0.9) !important;
  border: 1px solid rgba(148, 163, 184, 0.32) !important;
  color: #e2e8f0 !important;
}

.sr-dialog-foot button.sr-dlg-cancel:hover {
  background: rgba(51, 65, 85, 0.95) !important;
  color: #ffffff !important;
}

.sr-dialog-card.is-light .sr-dialog-foot button.sr-dlg-cancel {
  background: #ffffff !important;
  border: 1px solid #cbd5e1 !important;
  color: #334155 !important;
}

.sr-dialog-card.is-light .sr-dialog-foot button.sr-dlg-cancel:hover {
  background: #f1f5f9 !important;
  color: #0f172a !important;
}

.sr-dialog-foot button.sr-dlg-discard {
  background: rgba(239, 68, 68, 0.14) !important;
  border: 1px solid rgba(239, 68, 68, 0.48) !important;
  color: #fca5a5 !important;
}

.sr-dialog-foot button.sr-dlg-discard:hover {
  background: rgba(220, 38, 38, 0.9) !important;
  border-color: #ef4444 !important;
  color: #ffffff !important;
}

.sr-dialog-card.is-light .sr-dialog-foot button.sr-dlg-discard {
  background: #fef2f2 !important;
  border: 1px solid #fecaca !important;
  color: #dc2626 !important;
}

.sr-dialog-card.is-light .sr-dialog-foot button.sr-dlg-discard:hover {
  background: #dc2626 !important;
  border-color: #dc2626 !important;
  color: #ffffff !important;
}

.sr-dialog-foot button.sr-dlg-confirm {
  border: none !important;
  color: #ffffff !important;
  font-weight: 800 !important;
  background: linear-gradient(135deg, #0284c7 0%, #2563eb 100%) !important;
  box-shadow: 0 4px 12px rgba(2, 132, 199, 0.28) !important;
}

.sr-dialog-foot button.sr-dlg-confirm:hover {
  background: linear-gradient(135deg, #0ea5e9 0%, #0284c7 100%) !important;
  transform: translateY(-1px) !important;
}

.sr-dialog-foot button.sr-dlg-confirm.is-btn-success {
  background: linear-gradient(135deg, #10b981 0%, #059669 100%) !important;
  box-shadow: 0 4px 12px rgba(16, 185, 129, 0.3) !important;
}

.sr-dialog-foot button.sr-dlg-confirm.is-btn-success:hover {
  background: linear-gradient(135deg, #34d399 0%, #10b981 100%) !important;
}

.sr-dialog-foot button.sr-dlg-confirm.is-btn-danger,
.sr-dialog-foot button.sr-dlg-confirm.is-btn-error {
  background: linear-gradient(135deg, #ef4444 0%, #dc2626 100%) !important;
  box-shadow: 0 4px 14px rgba(239, 68, 68, 0.32) !important;
}

.sr-dialog-foot button.sr-dlg-confirm.is-btn-danger:hover,
.sr-dialog-foot button.sr-dlg-confirm.is-btn-error:hover {
  background: linear-gradient(135deg, #f87171 0%, #ef4444 100%) !important;
}

@media (max-width: 1100px) {
  .sr-dialog-overlay {
    padding: 16px !important;
    align-items: center !important;
    justify-content: center !important;
  }

  .sr-dialog-card {
    width: min(440px, 92vw) !important;
    height: auto !important;
    max-height: 86dvh !important;
    border-radius: 16px !important;
  }

  .sr-dialog-dt-head {
    display: none !important;
  }

  .sr-dialog-m-head {
    display: flex !important;
  }

  .sr-dialog-body {
    padding: 14px 16px 16px 16px !important;
  }

  .sr-dialog-foot {
    padding: 12px 16px !important;
  }

  .sr-dialog-foot:not(.is-single-action) {
    display: grid !important;
    grid-template-columns: 1fr 1fr !important;
  }

  .sr-dialog-foot button.sr-dlg-btn {
    width: 100% !important;
    height: 40px !important;
    min-height: 40px !important;
  }

  .sr-dialog-foot.is-single-action button.sr-dlg-confirm {
    width: 100% !important;
  }

  .sr-dialog-foot.is-three-actions button.sr-dlg-confirm.is-btn-save-close {
    grid-column: 1 / -1 !important;
    width: 100% !important;
  }
}

/* ============================================================
   MODAL CHỌN KHÁCH HÀNG (KH) / NHÀ CUNG CẤP (NCC)
   ============================================================ */
.sr-filter-picker-modal {
  width: 94vw;
  max-width: 820px;
  max-height: 86vh;
  display: flex;
  flex-direction: column;
  border-radius: 16px;
  overflow: hidden;
  background: #0f172a;
  border: 1px solid rgba(56, 189, 248, 0.28);
  box-shadow: 0 24px 64px rgba(2, 6, 23, 0.65);
  color: #f8fafc;
}

.sr-filter-picker-modal.is-ncc-modal {
  max-width: 760px;
  border-color: rgba(16, 185, 129, 0.3);
}

.sr-fpm-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 14px 20px;
  background: linear-gradient(135deg, #0284c7 0%, #2563eb 100%);
  border-bottom: 1px solid rgba(255, 255, 255, 0.14);
  flex-shrink: 0;
}

.sr-filter-picker-modal.is-ncc-modal .sr-fpm-header {
  background: linear-gradient(135deg, #059669 0%, #10b981 100%);
}

.sr-fpm-header-left {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}

.sr-fpm-icon {
  width: 38px;
  height: 38px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.18);
  border: 1px solid rgba(255, 255, 255, 0.28);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: #ffffff;
  flex-shrink: 0;
}

.sr-fpm-title-wrap {
  min-width: 0;
}

.sr-fpm-title-row {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.sr-fpm-title {
  margin: 0;
  font-size: 15px;
  font-weight: 800;
  color: #ffffff;
  letter-spacing: 0.01em;
}

.sr-fpm-badge {
  display: inline-flex;
  align-items: center;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: 0.03em;
  background: rgba(255, 255, 255, 0.2);
  color: #ffffff;
  border: 1px solid rgba(255, 255, 255, 0.3);
}

.sr-fpm-sub {
  margin: 3px 0 0;
  font-size: 12px;
  color: rgba(255, 255, 255, 0.88);
}

.sr-fpm-toolbar {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  padding: 12px 20px;
  background: rgba(15, 23, 42, 0.95);
  border-bottom: 1px solid rgba(148, 163, 184, 0.16);
  flex-shrink: 0;
}

.sr-fpm-search-box {
  position: relative;
  flex: 1 1 260px;
  min-width: 0;
  display: flex;
  align-items: center;
}

.sr-fpm-search-icon {
  position: absolute;
  left: 12px;
  color: #38bdf8;
  pointer-events: none;
}

.sr-filter-picker-modal.is-ncc-modal .sr-fpm-search-icon {
  color: #10b981;
}

.sr-fpm-search-input {
  width: 100%;
  height: 36px;
  padding: 0 32px 0 36px;
  border-radius: 9px;
  border: 1px solid rgba(148, 163, 184, 0.28);
  background: rgba(30, 41, 59, 0.85);
  color: #f8fafc;
  font-size: 12.5px;
  outline: none;
  transition: border-color 0.16s ease, box-shadow 0.16s ease;
}

.sr-fpm-search-input:focus {
  border-color: #38bdf8;
  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.18);
}

.sr-filter-picker-modal.is-ncc-modal .sr-fpm-search-input:focus {
  border-color: #10b981;
  box-shadow: 0 0 0 3px rgba(16, 185, 129, 0.18);
}

.sr-fpm-search-clear {
  position: absolute;
  right: 8px;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: none;
  background: rgba(148, 163, 184, 0.22);
  color: #cbd5e1;
  font-size: 14px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.sr-fpm-search-clear:hover {
  background: rgba(239, 68, 68, 0.25);
  color: #fca5a5;
}

.sr-fpm-all-btn {
  height: 36px;
  padding: 0 13px;
  border-radius: 9px;
  border: 1px solid rgba(56, 189, 248, 0.35);
  background: rgba(56, 189, 248, 0.1);
  color: #38bdf8;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  transition: all 0.15s ease;
  white-space: nowrap;
}

.sr-fpm-all-btn:hover {
  background: rgba(56, 189, 248, 0.2);
}

.sr-fpm-all-btn.active {
  background: linear-gradient(135deg, #0284c7 0%, #2563eb 100%);
  border-color: #0284c7;
  color: #ffffff;
}

.sr-filter-picker-modal.is-ncc-modal .sr-fpm-all-btn {
  border-color: rgba(16, 185, 129, 0.35);
  background: rgba(16, 185, 129, 0.1);
  color: #34d399;
}

.sr-filter-picker-modal.is-ncc-modal .sr-fpm-all-btn.active {
  background: linear-gradient(135deg, #059669 0%, #10b981 100%);
  border-color: #059669;
  color: #ffffff;
}

.sr-fpm-count-tag {
  font-size: 11.5px;
  font-weight: 700;
  color: #94a3b8;
  padding: 4px 10px;
  border-radius: 999px;
  background: rgba(30, 41, 59, 0.8);
  border: 1px solid rgba(148, 163, 184, 0.18);
  white-space: nowrap;
}

.sr-fpm-body {
  flex: 1 1 auto;
  min-height: 0;
  overflow-y: auto;
  padding: 14px 20px;
  background: #0b1120;
}

.sr-fpm-empty {
  padding: 36px 16px;
  text-align: center;
  color: #94a3b8;
  font-size: 13px;
}

.sr-fpm-list {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.sr-fpm-item {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 11px 14px;
  border-radius: 12px;
  border: 1px solid rgba(148, 163, 184, 0.16);
  background: rgba(30, 41, 59, 0.65);
  color: #f8fafc;
  text-align: left;
  cursor: pointer;
  transition: all 0.16s ease;
}

.sr-fpm-item:hover {
  border-color: rgba(56, 189, 248, 0.5);
  background: rgba(30, 41, 59, 0.95);
  transform: translateY(-1px);
}

.sr-fpm-item.active {
  border-color: #38bdf8;
  background: linear-gradient(135deg, rgba(2, 132, 199, 0.24), rgba(37, 99, 235, 0.18));
  box-shadow: 0 4px 14px rgba(2, 132, 199, 0.18);
}

.sr-fpm-item-main {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.sr-fpm-item-title-row {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.sr-fpm-item-name {
  font-size: 13px;
  font-weight: 800;
  color: #f8fafc;
  line-height: 1.35;
  word-break: break-word;
}

.sr-fpm-selected-pill {
  flex-shrink: 0;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  background: rgba(16, 185, 129, 0.2);
  color: #34d399;
  border: 1px solid rgba(16, 185, 129, 0.4);
}

.sr-fpm-item-meta {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.sr-fpm-meta-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 2px 8px;
  border-radius: 6px;
  font-size: 11px;
  color: #94a3b8;
  background: rgba(15, 23, 42, 0.75);
  border: 1px solid rgba(148, 163, 184, 0.14);
}

.sr-fpm-meta-chip strong {
  color: #e2e8f0;
  font-weight: 700;
}

.sr-fpm-meta-chip.is-code strong {
  color: #38bdf8;
}

.sr-fpm-meta-chip.is-mono strong {
  font-variant-numeric: tabular-nums;
}

.sr-fpm-item-right {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 10px;
}

.sr-fpm-metrics {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.sr-fpm-metric-pill {
  display: inline-flex;
  align-items: center;
  padding: 3px 8px;
  border-radius: 7px;
  font-size: 11px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.sr-fpm-metric-pill.is-po {
  background: rgba(56, 189, 248, 0.14);
  color: #38bdf8;
  border: 1px solid rgba(56, 189, 248, 0.28);
}

.sr-fpm-metric-pill.is-dsb {
  background: rgba(16, 185, 129, 0.14);
  color: #34d399;
  border: 1px solid rgba(16, 185, 129, 0.28);
}

.sr-fpm-metric-pill.is-debt {
  background: rgba(239, 68, 68, 0.14);
  color: #f87171;
  border: 1px solid rgba(239, 68, 68, 0.3);
}

.sr-fpm-metric-pill.is-settled {
  background: rgba(148, 163, 184, 0.14);
  color: #94a3b8;
  border: 1px solid rgba(148, 163, 184, 0.22);
}

.sr-fpm-choose-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 28px;
  padding: 0 11px;
  border-radius: 7px;
  font-size: 11.5px;
  font-weight: 800;
  background: rgba(56, 189, 248, 0.14);
  color: #38bdf8;
  border: 1px solid rgba(56, 189, 248, 0.32);
  white-space: nowrap;
  transition: all 0.15s ease;
}

.sr-fpm-item:hover .sr-fpm-choose-btn,
.sr-fpm-choose-btn.active {
  background: linear-gradient(135deg, #0284c7 0%, #2563eb 100%);
  color: #ffffff;
  border-color: #0284c7;
}

/* Grid cho NCC / Product Type */
.sr-fpm-ncc-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 10px;
}

.sr-fpm-ncc-card {
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 10px;
  padding: 12px 14px;
  border-radius: 12px;
  border: 1px solid rgba(148, 163, 184, 0.18);
  background: rgba(30, 41, 59, 0.65);
  color: #f8fafc;
  text-align: left;
  cursor: pointer;
  transition: all 0.16s ease;
}

.sr-fpm-ncc-card:hover {
  border-color: rgba(16, 185, 129, 0.5);
  background: rgba(30, 41, 59, 0.95);
  transform: translateY(-1px);
}

.sr-fpm-ncc-card.active {
  border-color: #10b981;
  background: linear-gradient(135deg, rgba(5, 150, 105, 0.24), rgba(16, 185, 129, 0.16));
  box-shadow: 0 4px 14px rgba(16, 185, 129, 0.18);
}

.sr-fpm-ncc-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
}

.sr-fpm-ncc-name {
  font-size: 13px;
  font-weight: 800;
  color: #f8fafc;
  line-height: 1.35;
  word-break: break-word;
}

.sr-fpm-ncc-card .sr-fpm-choose-btn {
  background: rgba(16, 185, 129, 0.14);
  color: #34d399;
  border-color: rgba(16, 185, 129, 0.32);
}

.sr-fpm-ncc-card:hover .sr-fpm-choose-btn,
.sr-fpm-ncc-card .sr-fpm-choose-btn.active {
  background: linear-gradient(135deg, #059669 0%, #10b981 100%);
  color: #ffffff;
  border-color: #059669;
}

.sr-fpm-ncc-foot {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.sr-fpm-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  padding: 12px 20px;
  background: rgba(15, 23, 42, 0.96);
  border-top: 1px solid rgba(148, 163, 184, 0.16);
  flex-shrink: 0;
}

.sr-fpm-footer-info {
  font-size: 12px;
  color: #94a3b8;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sr-fpm-footer-info strong {
  color: #38bdf8;
  font-weight: 800;
}

.sr-filter-picker-modal.is-ncc-modal .sr-fpm-footer-info strong {
  color: #34d399;
}

.sr-fpm-footer-actions {
  display: flex;
  align-items: center;
  gap: 8px;
}

.sr-fpm-reset-btn {
  height: 34px;
  padding: 0 12px;
  border-radius: 8px;
  border: 1px solid rgba(245, 158, 11, 0.4);
  background: rgba(245, 158, 11, 0.12);
  color: #fbbf24;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.15s ease;
}

.sr-fpm-reset-btn:hover {
  background: rgba(245, 158, 11, 0.22);
}

/* Light Mode cho Modal KH & NCC */
.sr-filter-picker-modal.is-light {
  background: #ffffff;
  border-color: #bae6fd;
  color: #0f172a;
  box-shadow: 0 24px 60px rgba(15, 23, 42, 0.2);
}

.sr-filter-picker-modal.is-ncc-modal.is-light {
  border-color: #a7f3d0;
}

.sr-filter-picker-modal.is-light .sr-fpm-toolbar {
  background: #f8fafc;
  border-bottom-color: #cbd5e1;
}

.sr-filter-picker-modal.is-light .sr-fpm-search-input {
  background: #ffffff;
  border-color: #cbd5e1;
  color: #0f172a;
}

.sr-filter-picker-modal.is-light .sr-fpm-search-clear {
  background: #e2e8f0;
  color: #475569;
}

.sr-filter-picker-modal.is-light .sr-fpm-all-btn:not(.active) {
  background: #f0f9ff;
  border-color: #7dd3fc;
  color: #0284c7;
}

.sr-filter-picker-modal.is-ncc-modal.is-light .sr-fpm-all-btn:not(.active) {
  background: #ecfdf5;
  border-color: #6ee7b7;
  color: #059669;
}

.sr-filter-picker-modal.is-light .sr-fpm-count-tag {
  background: #f1f5f9;
  border-color: #cbd5e1;
  color: #475569;
}

.sr-filter-picker-modal.is-light .sr-fpm-body {
  background: #f8fafc;
}

.sr-filter-picker-modal.is-light .sr-fpm-item,
.sr-filter-picker-modal.is-light .sr-fpm-ncc-card {
  background: #ffffff;
  border-color: #e2e8f0;
  color: #0f172a;
  box-shadow: 0 1px 3px rgba(15, 23, 42, 0.04);
}

.sr-filter-picker-modal.is-light .sr-fpm-item:hover {
  border-color: #38bdf8;
  background: #f0f9ff;
}

.sr-filter-picker-modal.is-light .sr-fpm-ncc-card:hover {
  border-color: #10b981;
  background: #ecfdf5;
}

.sr-filter-picker-modal.is-light .sr-fpm-item.active {
  background: #e0f2fe;
  border-color: #0284c7;
}

.sr-filter-picker-modal.is-light .sr-fpm-ncc-card.active {
  background: #d1fae5;
  border-color: #059669;
}

.sr-filter-picker-modal.is-light .sr-fpm-item-name,
.sr-filter-picker-modal.is-light .sr-fpm-ncc-name {
  color: #0f172a;
}

.sr-filter-picker-modal.is-light .sr-fpm-meta-chip {
  background: #f1f5f9;
  border-color: #e2e8f0;
  color: #475569;
}

.sr-filter-picker-modal.is-light .sr-fpm-meta-chip strong {
  color: #0f172a;
}

.sr-filter-picker-modal.is-light .sr-fpm-meta-chip.is-code strong {
  color: #0284c7;
}

.sr-filter-picker-modal.is-light .sr-fpm-metric-pill.is-po {
  background: #e0f2fe;
  color: #0369a1;
  border-color: #bae6fd;
}

.sr-filter-picker-modal.is-light .sr-fpm-metric-pill.is-dsb {
  background: #dcfce7;
  color: #047857;
  border-color: #a7f3d0;
}

.sr-filter-picker-modal.is-light .sr-fpm-metric-pill.is-debt {
  background: #fee2e2;
  color: #b91c1c;
  border-color: #fecaca;
}

.sr-filter-picker-modal.is-light .sr-fpm-metric-pill.is-settled {
  background: #f1f5f9;
  color: #64748b;
  border-color: #cbd5e1;
}

.sr-filter-picker-modal.is-light .sr-fpm-footer {
  background: #f8fafc;
  border-top-color: #e2e8f0;
}

.sr-filter-picker-modal.is-light .sr-fpm-footer-info {
  color: #475569;
}

.sr-filter-picker-modal.is-light .sr-fpm-footer-info strong {
  color: #0284c7;
}

.sr-filter-picker-modal.is-ncc-modal.is-light .sr-fpm-footer-info strong {
  color: #059669;
}

.sr-filter-picker-modal.is-light .sr-fpm-reset-btn {
  background: #fef3c7;
  border-color: #fcd34d;
  color: #b45309;
}

@media (max-width: 680px) {
  .sr-fpm-item {
    flex-direction: column;
    align-items: stretch;
  }

  .sr-fpm-item-right {
    justify-content: space-between;
  }
}

/* ═══════════════════════════════════════════════════════════════════════════
   MOBILE NATIVE APP SHELL & FLOATING GLASS BOTTOM DOCK (baogiaFirebase PARITY)
   ═══════════════════════════════════════════════════════════════════════════ */
.sr-page.is-mobile-shell .sr-company-top-toolbar {
  justify-content: space-between;
  gap: 8px;
  flex-wrap: wrap;
}

.sr-mob-toolbar-left {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  min-width: 0;
}

.sr-mob-ctx-btn {
  height: 28px;
  padding: 0 10px;
  border-radius: 7px;
  border: 1px solid rgba(52, 211, 153, 0.35);
  background: rgba(16, 185, 129, 0.14);
  color: #6ee7b7;
  font-size: 11.5px;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
  gap: 5px;
  cursor: pointer;
  white-space: nowrap;
  transition: all 0.15s ease;
}

.sr-mob-ctx-btn:hover,
.sr-mob-ctx-btn:active {
  background: rgba(16, 185, 129, 0.25);
  border-color: #34d399;
  color: #ffffff;
}

.sr-mob-ctx-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  background: #10b981;
  color: #052e16;
}

.sr-mob-ctx-badge.is-amber {
  background: #f59e0b;
  color: #0f172a;
}

.sr-mob-ctx-stat {
  font-size: 11.5px;
  font-weight: 700;
  color: #94a3b8;
  font-variant-numeric: tabular-nums;
}

.sr-mob-company-stepper {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  height: 28px;
  padding: 0 3px;
  border-radius: 7px;
  background: rgba(15, 23, 42, 0.78);
  border: 1px solid rgba(148, 163, 184, 0.28);
}

.sr-mob-step-btn {
  width: 22px;
  height: 22px;
  border-radius: 5px;
  border: none;
  background: transparent;
  color: #cbd5e1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  padding: 0;
}

.sr-mob-step-btn:hover,
.sr-mob-step-btn:active {
  background: rgba(16, 185, 129, 0.22);
  color: #34d399;
}

.sr-mob-step-pos {
  font-size: 11px;
  font-weight: 700;
  color: #e2e8f0;
  padding: 0 4px;
  font-variant-numeric: tabular-nums;
}

/* Ở Tab 1 (Tổng quan), ẩn 4 KPI từng công ty nên làm gọn tai Folder Header */
.sr-page.is-mobile-shell.m-tab-overview .sr-company-folder-header {
  margin-bottom: 10px;
}

.sr-page.is-mobile-shell.m-tab-overview .sr-folder-top-bar {
  align-items: center;
  padding: 8px 12px;
  border-radius: 10px;
  background: linear-gradient(135deg, rgba(5, 150, 105, 0.88) 0%, rgba(15, 118, 110, 0.88) 60%, rgba(15, 23, 42, 0.94) 100%);
  border: 1px solid rgba(52, 211, 153, 0.48);
  box-shadow: 0 4px 14px -4px rgba(0, 0, 0, 0.35);
}

.sr-page.is-mobile-shell.m-tab-overview .sr-folder-ear-tab {
  padding: 0;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  clip-path: none !important;
  border-radius: 0;
  flex: 1 1 200px;
}

.sr-plain-text-btn.is-mob-company-jump {
  background: rgba(16, 185, 129, 0.25);
  border-color: rgba(52, 211, 153, 0.55);
  color: #ecfdf5;
}

/* ─── Floating Glass Bottom Dock (3 Nút: Tổng quan | Thêm mới | Tên công ty — Nằm phía trên Bottom Bar) ─── */
.sr-page.is-mobile-shell {
  padding-bottom: calc(104px + env(safe-area-inset-bottom, 0px));
}

.sr-mobile-dock {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  position: fixed;
  bottom: calc(12px + env(safe-area-inset-bottom, 0px));
  left: 50%;
  transform: translateX(-50%);
  width: min(460px, calc(100vw - 20px));
  z-index: 955;
  background: rgba(8, 22, 18, 0.94);
  backdrop-filter: blur(20px) saturate(180%);
  -webkit-backdrop-filter: blur(20px) saturate(180%);
  border: 1px solid rgba(52, 211, 153, 0.32);
  border-radius: 20px;
  padding: 6px 8px;
  box-shadow:
    0 18px 40px -8px rgba(0, 0, 0, 0.72),
    0 0 0 1px rgba(16, 185, 129, 0.16);
  align-items: center;
  gap: 6px;
  transition:
    bottom 0.34s cubic-bezier(0.22, 1, 0.36, 1),
    opacity 0.2s cubic-bezier(0.22, 1, 0.36, 1),
    transform 0.2s cubic-bezier(0.22, 1, 0.36, 1);
}

.sr-mobile-dock.is-modal-hidden {
  opacity: 0 !important;
  visibility: hidden !important;
  pointer-events: none !important;
  transform: translate(-50%, 24px) scale(0.96) !important;
}

.sr-dock-btn {
  flex: 1 1 0;
  min-width: 0;
  min-height: 48px;
  border: 1px solid transparent;
  background: transparent;
  color: #94a3b8;
  border-radius: 14px;
  padding: 5px 4px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  font-size: 10.5px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.18s ease;
  position: relative;
}

.sr-dock-btn > span {
  max-width: 100%;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  line-height: 1.15;
}

.sr-dock-icon-wrap {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 20px;
}

.sr-dock-btn:hover,
.sr-dock-btn:active {
  color: #ecfdf5;
  background: rgba(16, 185, 129, 0.12);
}

.sr-dock-btn.active {
  color: #34d399;
  background: rgba(16, 185, 129, 0.18);
  border-color: rgba(52, 211, 153, 0.36);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.sr-dock-btn.is-primary.is-center-cta {
  background: linear-gradient(135deg, #10b981 0%, #059669 100%);
  color: #042f2e;
  font-weight: 800;
  border-color: rgba(110, 231, 183, 0.45);
  box-shadow: 0 6px 18px -4px rgba(16, 185, 129, 0.55);
}

.sr-dock-btn.is-primary.is-center-cta:hover,
.sr-dock-btn.is-primary.is-center-cta:active {
  filter: brightness(1.06);
  color: #022c22;
}

.sr-dock-btn.is-disabled {
  opacity: 0.6;
}

.sr-dock-badge {
  position: absolute;
  top: -5px;
  right: -13px;
  min-width: 16px;
  height: 15px;
  padding: 0 4px;
  border-radius: 999px;
  background: #0ea5e9;
  color: #ffffff;
  font-size: 9.5px;
  font-weight: 800;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1.5px solid #081612;
  font-variant-numeric: tabular-nums;
}

.sr-dock-badge.is-amber {
  background: #f59e0b;
  color: #0f172a;
}

.sr-dock-badge.is-emerald {
  background: #10b981;
  color: #052e16;
}

.sr-dock-company-name {
  max-width: 100%;
  padding: 0 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* ─── Light Blue Theme Parity cho Mobile Shell & Floating Dock ─── */
.sr-page.theme-light-blue .sr-mob-ctx-btn {
  background: #e0f2fe;
  border-color: #7dd3fc;
  color: #0369a1;
}

.sr-page.theme-light-blue .sr-mob-ctx-btn:hover,
.sr-page.theme-light-blue .sr-mob-ctx-btn:active {
  background: #0284c7;
  border-color: #0284c7;
  color: #ffffff;
}

.sr-page.theme-light-blue .sr-mob-ctx-stat {
  color: #475569;
}

.sr-page.theme-light-blue .sr-mob-company-stepper {
  background: #ffffff;
  border-color: #bae6fd;
}

.sr-page.theme-light-blue .sr-mob-step-btn {
  color: #0369a1;
}

.sr-page.theme-light-blue .sr-mob-step-pos {
  color: #0f172a;
}

.sr-page.theme-light-blue.is-mobile-shell.m-tab-overview .sr-folder-top-bar {
  background: linear-gradient(135deg, #0284c7 0%, #0369a1 65%, #075985 100%);
  border-color: #38bdf8;
  box-shadow: 0 4px 12px rgba(2, 132, 199, 0.18);
}

.sr-page.theme-light-blue .sr-mobile-dock {
  background: rgba(255, 255, 255, 0.95);
  border-color: #bae6fd;
  box-shadow:
    0 16px 36px -8px rgba(2, 132, 199, 0.24),
    0 0 0 1px rgba(14, 165, 233, 0.14);
}

.sr-page.theme-light-blue .sr-dock-btn {
  color: #475569;
}

.sr-page.theme-light-blue .sr-dock-btn:hover,
.sr-page.theme-light-blue .sr-dock-btn:active {
  color: #0284c7;
  background: #f0f9ff;
}

.sr-page.theme-light-blue .sr-dock-btn.active {
  color: #0284c7;
  background: #e0f2fe;
  border-color: #7dd3fc;
}

.sr-page.theme-light-blue .sr-dock-btn.is-primary.is-center-cta {
  background: linear-gradient(135deg, #0284c7 0%, #0369a1 100%);
  color: #ffffff;
  border-color: #38bdf8;
  box-shadow: 0 6px 18px -4px rgba(2, 132, 199, 0.42);
}

.sr-show-mob-inline {
  display: none;
}

.sr-page.theme-light-blue .sr-dock-badge {
  border-color: #ffffff;
}

@media (max-width: 768px) {
  .sr-page.is-mobile-shell {
    padding: 14px 12px calc(158px + env(safe-area-inset-bottom, 0px)) !important;
  }

  /* Đặt thanh Dock nằm ngay phía trên Pill Bottom Bar (.sidebar cao 56px ở bottom 10px) */
  .sr-mobile-dock {
    left: 10px;
    right: 10px;
    bottom: calc(74px + env(safe-area-inset-bottom, 0px));
    width: auto;
    max-width: 460px;
    margin: 0 auto;
    transform: translate3d(0, 0, 0);
    will-change: bottom, transform;
    transition:
      bottom 0.38s cubic-bezier(0.22, 1, 0.36, 1),
      transform 0.38s cubic-bezier(0.22, 1, 0.36, 1),
      opacity 0.24s cubic-bezier(0.22, 1, 0.36, 1),
      box-shadow 0.3s ease !important;
  }

  /* Khi cuộn xuống làm Bottom Bar của App tự ẩn (.mobile-nav-hidden), thanh Dock trượt mượt xuống đúng vị trí thanh Bottom Bar */
  :global(.app-layout.mobile-nav-hidden .sr-mobile-dock) {
    bottom: calc(10px + env(safe-area-inset-bottom, 0px)) !important;
  }

  .sr-mobile-dock.is-modal-hidden,
  :global(.app-layout.has-open-modal .sr-mobile-dock) {
    transform: translateY(calc(100% + 96px + env(safe-area-inset-bottom, 0px))) scale(0.96) !important;
    opacity: 0 !important;
    visibility: hidden !important;
    pointer-events: none !important;
  }

  /* Ẩn nút Thêm mới trên thanh công cụ phụ vì đã có nút Thêm mới nổi bật ở chính giữa Dock */
  .sr-hide-mob {
    display: none !important;
  }

  .sr-show-mob-inline {
    display: inline-flex !important;
  }

  /* ─── 1. THU GỌN CARD CÔNG TY (COMPANY FOLDER HEADER) TRÊN MOBILE (2 DÒNG GỌN GÀNG) ─── */
  .sr-page.is-mobile-shell.m-tab-overview .sr-company-folder-header {
    margin-bottom: 8px;
    padding: 8px 10px;
    border-radius: 10px;
    background: linear-gradient(135deg, rgba(5, 150, 105, 0.9) 0%, rgba(15, 118, 110, 0.9) 60%, rgba(15, 23, 42, 0.95) 100%);
    border: 1px solid rgba(52, 211, 153, 0.5);
    box-shadow: 0 4px 12px -4px rgba(0, 0, 0, 0.35);
    gap: 6px;
  }

  .sr-page.theme-light-blue.is-mobile-shell.m-tab-overview .sr-company-folder-header {
    background: linear-gradient(135deg, #0284c7 0%, #0369a1 65%, #075985 100%);
    border-color: #38bdf8;
    box-shadow: 0 4px 12px rgba(2, 132, 199, 0.2);
  }

  .sr-page.is-mobile-shell.m-tab-overview .sr-folder-top-bar,
  .sr-page.theme-light-blue.is-mobile-shell.m-tab-overview .sr-folder-top-bar {
    padding: 0 !important;
    border: none !important;
    border-radius: 0 !important;
    background: transparent !important;
    box-shadow: none !important;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    flex-wrap: nowrap;
  }

  .sr-page.is-mobile-shell.m-tab-overview .sr-folder-ear-tab {
    flex: 1 1 0%;
    min-width: 0;
    display: flex;
    align-items: center;
    gap: 6px;
    flex-wrap: nowrap;
  }

  .sr-page.is-mobile-shell.m-tab-overview .sr-folder-ear-tab .sr-folder-icon {
    width: 15px;
    height: 15px;
    flex-shrink: 0;
  }

  .sr-page.is-mobile-shell.m-tab-overview .sr-folder-ear-tab .sr-cpb-name {
    font-size: 13px;
    font-weight: 800;
    line-height: 1.28;
    flex: 1 1 auto;
    min-width: 0;
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }

  .sr-page.is-mobile-shell.m-tab-overview .sr-folder-ear-tab .sr-cpb-code,
  .sr-page.is-mobile-shell.m-tab-overview .sr-folder-ear-tab .sr-folder-mst,
  .sr-page.is-mobile-shell.m-tab-overview .sr-folder-ear-tab .sr-folder-sep {
    display: none !important;
  }

  .sr-page.is-mobile-shell.m-tab-overview .sr-folder-ear-tab .sr-folder-pocount {
    flex-shrink: 0;
    font-size: 10.5px;
    font-weight: 800;
    padding: 2px 6px;
    border-radius: 999px;
    background: rgba(15, 23, 42, 0.38);
    border: 1px solid rgba(255, 255, 255, 0.2);
    color: #fde047;
  }

  .sr-page.is-mobile-shell.m-tab-overview .sr-cpb-right {
    flex-shrink: 0;
    display: inline-flex;
    align-items: center;
    gap: 5px;
  }

  .sr-page.is-mobile-shell.m-tab-overview .sr-cpb-right .sr-plain-text-btn {
    height: 24px;
    padding: 0 7px;
    font-size: 11px;
    border-radius: 6px;
  }

  .sr-page.is-mobile-shell.m-tab-overview .sr-cpb-right .sr-plain-text-btn:last-child {
    width: 24px;
    padding: 0;
    justify-content: center;
  }

  .sr-mob-folder-chevron {
    transition: transform 0.2s ease;
  }

  .sr-mob-folder-chevron.is-collapsed {
    transform: rotate(180deg);
  }

  .sr-mob-folder-subbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    padding-top: 5px;
    border-top: 1px solid rgba(255, 255, 255, 0.18);
    font-size: 11px;
    color: rgba(255, 255, 255, 0.88);
    flex-wrap: wrap;
  }

  .sr-mob-fs-left,
  .sr-mob-fs-right {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    min-width: 0;
  }

  .sr-mob-fs-code {
    font-weight: 800;
    color: #ffffff;
  }

  .sr-mob-fs-mst {
    color: rgba(255, 255, 255, 0.82);
    font-variant-numeric: tabular-nums;
  }

  .sr-mob-fs-sep {
    opacity: 0.55;
  }

  .sr-mob-fs-metric {
    font-variant-numeric: tabular-nums;
  }

  .sr-mob-fs-metric strong {
    font-weight: 800;
    color: #ffffff;
  }

  .sr-mob-fs-metric.is-debt strong {
    color: #fde047;
  }

  .sr-mob-fs-metric.is-settled strong {
    color: #a7f3d0;
  }

  /* ─── 2. THU GỌN CARD PO TRÊN MOBILE (PHƯƠNG ÁN PO-1: HEADER GỌN + 4 CHIP FILE 1 DÒNG + LƯỚI 2x2 CHỈ SỐ) ─── */
  .sr-card-list.is-cols-1,
  .sr-card-list.is-cols-2 {
    gap: 10px !important;
    margin-bottom: 12px !important;
  }

  .sr-po1-header {
    padding: 8px 10px !important;
    gap: 5px !important;
  }

  .sr-po1-hbar {
    gap: 5px 8px !important;
  }

  .sr-po1-meta-left {
    gap: 5px !important;
  }

  .sr-po1-po-num {
    font-size: 12.5px !important;
  }

  .sr-po1-plain-meta {
    font-size: 11px !important;
  }

  .sr-po1-meta-right {
    gap: 5px !important;
    font-size: 11px !important;
  }

  .sr-po-pay-extend-btn {
    height: 24px !important;
    padding: 0 8px !important;
    font-size: 10.5px !important;
    border-radius: 6px !important;
  }

  .sr-po-collapse-arrow-btn {
    width: 24px !important;
    height: 24px !important;
    border-radius: 6px !important;
  }

  .sr-po1-contract-row {
    padding-top: 5px !important;
    gap: 6px !important;
  }

  .sr-po1-contract-prefix {
    font-size: 11px !important;
    margin-right: 4px !important;
  }

  .sr-po1-contract-title {
    font-size: 12px !important;
    line-height: 1.32 !important;
    min-width: 0 !important;
  }

  .sr-po1-collapsed-summary {
    font-size: 11px !important;
    gap: 5px !important;
  }

  /* 4 Ô Tệp đính kèm: Gói gọn trên 1 hàng ngang 4 Chip (BÁO GIÁ • MUA HÀNG • DXMH • KHÁC) */
  .sr-po1-contract-files.is-4box-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr)) !important;
    gap: 4px !important;
    padding-top: 5px !important;
    margin-top: 2px !important;
  }

  .sr-po1-file-box {
    height: 24px !important;
    padding: 0 4px !important;
    border-radius: 6px !important;
    justify-content: center !important;
  }

  .sr-po1-fb-left {
    justify-content: center !important;
    gap: 3px !important;
  }

  .sr-po1-file-box .sr-doc-tick-circle {
    width: 12px !important;
    height: 12px !important;
    flex-shrink: 0;
  }

  .sr-po1-fb-name,
  .sr-po1-fe-actions {
    display: none !important;
  }

  .sr-po1-fb-tag {
    font-size: 8.5px !important;
    padding: 1px 4px !important;
    letter-spacing: 0.01em !important;
  }

  .sr-po1-file-box:not(.has-file) .sr-po1-fb-tag,
  .theme-light-blue .sr-po1-file-box:not(.has-file) .sr-po1-fb-tag {
    background: transparent !important;
    color: #64748b !important;
    padding: 0 !important;
  }

  /* 4 Khối chỉ số tài chính trên Mobile (Phương án PO-1): Lưới 2x2 giảm 50% chiều cao */
  .sr-po1-4blocks,
  .sr-card-list.is-cols-2 .sr-po1-4blocks,
  .sr-workspace-layout.is-master-detail .sr-po1-4blocks {
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
  }

  .sr-po1-block {
    padding: 8px 9px !important;
    gap: 4px !important;
  }

  .sr-po1-block:nth-child(odd) {
    border-right: 1px solid rgba(148, 163, 184, 0.16) !important;
  }

  .sr-po1-block:nth-child(even) {
    border-right: none !important;
  }

  .sr-po1-block:nth-child(1),
  .sr-po1-block:nth-child(2) {
    border-bottom: 1px solid rgba(148, 163, 184, 0.16) !important;
  }

  .sr-po1-block:nth-child(3),
  .sr-po1-block:nth-child(4) {
    border-bottom: none !important;
  }

  .sr-page.theme-light-blue .sr-po1-block:nth-child(odd) {
    border-right-color: #cbd5e1 !important;
  }

  .sr-page.theme-light-blue .sr-po1-block:nth-child(1),
  .sr-page.theme-light-blue .sr-po1-block:nth-child(2) {
    border-bottom-color: #cbd5e1 !important;
  }

  .sr-po1-block-title {
    font-size: 9.5px !important;
    padding: 4px 6px !important;
    margin-bottom: 2px !important;
    border-radius: 5px !important;
    letter-spacing: 0.02em !important;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .sr-po1-b-row {
    min-height: 17px !important;
    gap: 4px !important;
  }

  .sr-po1-b-row.is-sub-divider {
    margin-top: 2px !important;
    padding-top: 4px !important;
  }

  .sr-po1-b-lbl {
    font-size: 10.5px !important;
    line-height: 1.25 !important;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  .sr-po1-b-val {
    font-size: 11px !important;
  }

  .sr-po1-b-row.is-primary .sr-po1-b-val {
    font-size: 11.5px !important;
  }

  .sr-po1-note-line {
    padding: 6px 10px !important;
    font-size: 11px !important;
    gap: 6px !important;
  }

  /* Ẩn 3 nút Thêm mới / Xuất Excel / Thiết lập hiển thị trên thanh công cụ phụ vì đã đưa xuống thanh Dock 5 nút */
  .sr-page.is-mobile-shell .sr-company-top-toolbar .sr-hdr-action-btn {
    display: none !important;
  }

  /* Hiển thị Popover Thiết lập hiển thị nổi ngay phía trên thanh Dock khi bấm nút Hiển thị dưới Dock */
  .sr-page.is-mobile-shell .sr-display-setting-dropdown {
    position: fixed !important;
    top: auto !important;
    bottom: calc(138px + env(safe-area-inset-bottom, 0px)) !important;
    left: 12px !important;
    right: 12px !important;
    width: auto !important;
    max-width: 380px !important;
    margin: 0 auto !important;
    z-index: 980 !important;
    border-radius: 14px !important;
    box-shadow: 0 20px 48px rgba(0, 0, 0, 0.72) !important;
    transition: bottom 0.38s cubic-bezier(0.22, 1, 0.36, 1) !important;
  }

  :global(.app-layout.mobile-nav-hidden .sr-page.is-mobile-shell .sr-display-setting-dropdown) {
    bottom: calc(74px + env(safe-area-inset-bottom, 0px)) !important;
  }

  /* Tinh chỉnh 5 nút trên thanh Dock cân đối trên màn hình điện thoại */
  .sr-mobile-dock {
    padding: 5px 6px !important;
    gap: 4px !important;
  }

  .sr-dock-btn {
    min-height: 46px !important;
    padding: 4px 2px !important;
    font-size: 9.5px !important;
    border-radius: 12px !important;
  }

  /* Hiển thị 4 Card KPI Công ty ngay trong Tổng quan bên dưới Header mỗi công ty */
  .sr-page.is-mobile-shell.m-tab-overview .sr-customer-kpi-sheet.sr-folder-body-sheet {
    margin-top: 4px;
    padding: 8px;
    border-radius: 10px;
  }

  /* Ở Tổng quan, nút mũi tên trên Card PO rút gọn xoay ngang (›) báo hiệu chuyển sang Tab 3 xem chi tiết PO */
  .sr-po-collapse-arrow-btn.is-mob-detail-jump svg {
    transform: rotate(90deg) !important;
  }

  /* Nút Sửa PO trên thanh điều hướng của Tab 3 (PO đang chọn) */
  .sr-mob-ctx-btn.is-edit-po {
    background: linear-gradient(135deg, #0284c7 0%, #2563eb 100%) !important;
    border-color: #38bdf8 !important;
    color: #ffffff !important;
  }

  /* Ở Tab 3 (PO đang chọn): Hiển thị đầy đủ 4 Ô File đính kèm dạng lưới 2x2 kèm tên file & nút Xem / Tải xuống */
  .sr-page.is-mobile-shell.m-tab-company_detail .sr-po1-contract-files.is-4box-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
    gap: 6px !important;
  }

  .sr-page.is-mobile-shell.m-tab-company_detail .sr-po1-file-box {
    height: 30px !important;
    padding: 0 7px !important;
    justify-content: space-between !important;
  }

  .sr-page.is-mobile-shell.m-tab-company_detail .sr-po1-fb-left {
    justify-content: flex-start !important;
    gap: 4px !important;
  }

  .sr-page.is-mobile-shell.m-tab-company_detail .sr-po1-fb-name {
    display: inline-block !important;
    font-size: 10px !important;
  }

  .sr-page.is-mobile-shell.m-tab-company_detail .sr-po1-fe-actions {
    display: inline-flex !important;
    gap: 3px !important;
  }

  .sr-page.is-mobile-shell.m-tab-company_detail .sr-po1-fe-btn {
    height: 20px !important;
    padding: 0 5px !important;
    font-size: 9.5px !important;
  }

  .sr-page.is-mobile-shell.m-tab-company_detail .sr-po1-fe-btn.is-view span {
    display: none !important;
  }

  /* Tách khung nền Header Công ty khỏi 4 Card KPI Công ty bên dưới để 4 Card KPI nền trắng không bị bọc trong nền xanh */
  .sr-page.is-mobile-shell .sr-company-folder-header,
  .sr-page.is-mobile-shell.m-tab-overview .sr-company-folder-header,
  .sr-page.theme-light-blue.is-mobile-shell.m-tab-overview .sr-company-folder-header {
    background: transparent !important;
    border: none !important;
    padding: 0 !important;
    box-shadow: none !important;
    gap: 0 !important;
    margin-bottom: 8px !important;
  }

  .sr-page.is-mobile-shell .sr-folder-top-bar,
  .sr-page.is-mobile-shell.m-tab-overview .sr-folder-top-bar {
    padding: 8px 10px 6px !important;
    border-radius: 10px 10px 0 0 !important;
    background: linear-gradient(135deg, rgba(5, 150, 105, 0.92) 0%, rgba(15, 118, 110, 0.92) 60%, rgba(15, 23, 42, 0.96) 100%) !important;
    border: 1px solid rgba(52, 211, 153, 0.5) !important;
    border-bottom: none !important;
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
    gap: 8px !important;
    flex-wrap: nowrap !important;
  }

  .sr-page.theme-light-blue.is-mobile-shell .sr-folder-top-bar,
  .sr-page.theme-light-blue.is-mobile-shell.m-tab-overview .sr-folder-top-bar {
    background: linear-gradient(135deg, #0284c7 0%, #0369a1 65%, #075985 100%) !important;
    border-color: #38bdf8 !important;
  }

  .sr-page.is-mobile-shell .sr-folder-ear-tab {
    padding: 0 !important;
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    clip-path: none !important;
    border-radius: 0 !important;
    flex: 1 1 0% !important;
    min-width: 0 !important;
    display: flex !important;
    align-items: center !important;
    gap: 6px !important;
    flex-wrap: nowrap !important;
  }

  .sr-page.is-mobile-shell .sr-folder-ear-tab .sr-cpb-code,
  .sr-page.is-mobile-shell .sr-folder-ear-tab .sr-folder-mst,
  .sr-page.is-mobile-shell .sr-folder-ear-tab .sr-folder-sep {
    display: none !important;
  }

  .sr-page.is-mobile-shell .sr-folder-ear-tab .sr-cpb-name {
    font-size: 13px !important;
    line-height: 1.28 !important;
    flex: 1 1 auto !important;
    min-width: 0 !important;
  }

  .sr-page.is-mobile-shell .sr-folder-ear-tab .sr-folder-pocount {
    flex-shrink: 0 !important;
    font-size: 10.5px !important;
    font-weight: 800 !important;
    padding: 2px 6px !important;
    border-radius: 999px !important;
    background: rgba(15, 23, 42, 0.38) !important;
    border: 1px solid rgba(255, 255, 255, 0.2) !important;
    color: #fde047 !important;
  }

  .sr-page.is-mobile-shell .sr-mob-folder-subbar {
    padding: 5px 10px 7px !important;
    border-radius: 0 0 10px 10px !important;
    background: linear-gradient(135deg, rgba(5, 150, 105, 0.92) 0%, rgba(15, 118, 110, 0.92) 60%, rgba(15, 23, 42, 0.96) 100%) !important;
    border: 1px solid rgba(52, 211, 153, 0.5) !important;
    border-top: 1px solid rgba(255, 255, 255, 0.18) !important;
    box-shadow: 0 4px 12px -4px rgba(0, 0, 0, 0.32) !important;
  }

  .sr-page.theme-light-blue.is-mobile-shell .sr-mob-folder-subbar {
    background: linear-gradient(135deg, #0284c7 0%, #0369a1 65%, #075985 100%) !important;
    border-color: #38bdf8 !important;
    border-top-color: rgba(255, 255, 255, 0.22) !important;
    box-shadow: 0 4px 12px rgba(2, 132, 199, 0.18) !important;
  }

  .sr-page.is-mobile-shell.m-tab-overview .sr-customer-kpi-sheet.sr-folder-body-sheet {
    margin-top: 8px !important;
    padding: 0 !important;
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
  }

  .sr-page.is-mobile-shell .sr-company-top-toolbar .sr-hdr-action-btn.is-add {
    display: none;
  }
}

/* ─── TỐI GIẢN HEADER CỦA CÁC MODAL (BỎ BADGE & PHỤ ĐỀ RƯỜM RÀ) ─── */
.sr-po-mode-badge,
.sr-po-header-sub,
.sr-fpm-badge,
.sr-fpm-sub,
.debt-payment-modal .m-grab-eyebrow {
  display: none !important;
}

/* ─── ĐƯA NÚT THÊM MỚI VÀO CHÍNH GIỮA (VỊ TRÍ 3/5) TRÊN THANH FLOATING DOCK ─── */
.sr-mobile-dock > .sr-dock-btn:nth-child(1) {
  order: 1;
}
.sr-mobile-dock > .sr-dock-btn:nth-child(4) {
  order: 2;
}
.sr-mobile-dock > .sr-dock-btn.is-center-cta {
  order: 3;
}
.sr-mobile-dock > .sr-dock-btn:nth-child(5) {
  order: 4;
}
.sr-mobile-dock > .sr-dock-btn.is-company-slot {
  order: 5;
}

/* ─── ĐƯA NÚT TOGGLE THU GỌN TRONG CARD PO LÊN GÓC TRÊN BÊN PHẢI CARD ─── */
.sr-po1-header {
  position: relative !important;
}

.sr-po1-hbar {
  padding-right: 34px !important;
}

.sr-po-collapse-arrow-btn {
  position: absolute !important;
  top: 10px !important;
  right: 12px !important;
  z-index: 3;
}

/* ─── SỬA DỨT ĐIỂM LAYOUT CARD CÔNG TY (.sr-company-folder-header) TRÊN MOBILE SHELL ─── */
.sr-page.is-mobile-shell .sr-company-folder-header,
.sr-page.is-mobile-shell.m-tab-overview .sr-company-folder-header,
.sr-page.theme-light-blue.is-mobile-shell .sr-company-folder-header,
