@media (max-width: 1080px) {
  .sr-po-overview-grid {
    gap: 8px 10px !important;
  }

  /* Phần 1: Thông tin tổng quan PO (3 hàng cân đối, không bị tràn nhãn hay lẻ ô) */
  .sr-po-overview-grid > :nth-child(1) {
    order: 1 !important;
    grid-column: span 6 !important;
  }
  .sr-po-overview-grid > :nth-child(2) {
    order: 2 !important;
    grid-column: span 6 !important;
  }
  .sr-po-overview-grid > :nth-child(3) {
    order: 3 !important;
    grid-column: 1 / -1 !important;
  }
  .sr-po-overview-grid > :nth-child(4) {
    order: 4 !important;
    grid-column: span 6 !important;
  }
  .sr-po-overview-grid > :nth-child(5) {
    order: 5 !important;
    grid-column: span 6 !important;
  }

  /* Phần 2: Thanh tiêu đề & trạng thái Thông tin khách hàng gọn gàng */
  .sr-po-overview-grid > :nth-child(6) {
    order: 6 !important;
    grid-column: 1 / -1 !important;
    margin-top: 4px !important;
    padding-top: 10px !important;
  }

  .sr-po-cust-bar {
    flex-direction: column !important;
    align-items: stretch !important;
    gap: 7px !important;
  }

  .sr-po-cust-bar-left {
    width: 100% !important;
    justify-content: space-between !important;
    flex-wrap: nowrap !important;
    gap: 6px !important;
  }

  .sr-po-cust-status.is-linked .sr-po-cust-status-sep,
  .sr-po-cust-status.is-linked .sr-po-cust-status-name,
  .sr-po-cust-status.is-linked .sr-po-cust-status-mst {
    display: none !important;
  }

  .sr-po-cust-status {
    white-space: nowrap !important;
    flex-shrink: 0 !important;
    padding: 3px 9px !important;
    border-radius: 999px !important;
  }

  .sr-po-cust-bar-right {
    width: 100% !important;
    display: flex !important;
    align-items: center !important;
    gap: 6px !important;
    flex-wrap: nowrap !important;
  }

  .sr-po-cust-bar-right .sr-po-cust-quick-btn,
  .sr-po-cust-bar-right .sr-po-cust-picker-btn {
    flex: 1 1 0% !important;
    justify-content: center !important;
    white-space: nowrap !important;
    padding: 5px 8px !important;
    font-size: 11.5px !important;
  }

  /* 5 trường Khách hàng: Tên công ty Full-width lên đầu + 2 hàng đôi (MST | Người nhận) & (Ngành hàng | Nhóm KH) */
  .sr-po-overview-grid > :nth-child(8) {
    order: 7 !important;
    grid-column: 1 / -1 !important;
  }
  .sr-po-overview-grid > :nth-child(7) {
    order: 8 !important;
    grid-column: span 6 !important;
  }
  .sr-po-overview-grid > :nth-child(9) {
    order: 9 !important;
    grid-column: span 6 !important;
  }
  .sr-po-overview-grid > :nth-child(10) {
    order: 10 !important;
    grid-column: span 6 !important;
  }
  .sr-po-overview-grid > :nth-child(11) {
    order: 11 !important;
    grid-column: span 6 !important;
  }
}

