  .sr-analytics-modal.is-light .sr-analytics-table tbody tr {
    background: #ffffff !important;
    border: 2px solid #0284c7 !important;
    box-shadow: 0 4px 12px rgba(2, 132, 199, 0.1) !important;
  }

  .sr-analytics-table tbody td {
    display: block !important;
    padding: 0 !important;
    border: none !important;
    width: auto !important;
    min-width: 0 !important;
  }

  /* Hạng (#1, #2, #3...) */
  .sr-analytics-table tbody td:nth-child(1) {
    order: 1 !important;
    flex: 0 0 auto !important;
  }

  /* Tên Đối tượng (Khách hàng / Ngành / Nhóm KH / NCC / PO) */
  .sr-analytics-table tbody td.sr-rank-name {
    order: 2 !important;
    flex: 1 1 calc(100% - 120px) !important;
    min-width: 0 !important;
    font-size: 13.5px !important;
    font-weight: 700 !important;
    line-height: 1.35 !important;
    white-space: normal !important;
    word-break: break-word !important;
  }

  /* Số PO pill bên góc phải trên */
  .sr-analytics-table tbody td:nth-child(3) {
    order: 3 !important;
    flex: 0 0 auto !important;
  }

  .sr-analytics-table .sr-rank-po-pill {
    display: inline-flex !important;
    align-items: center !important;
    white-space: nowrap !important;
    padding: 3px 9px !important;
    border-radius: 999px !important;
    font-size: 11px !important;
    font-weight: 800 !important;
  }

  /* Ô Giá trị chỉ số chính đóng khung Bento nổi bật ở giữa Card */
  .sr-analytics-table tbody td.sr-rank-val {
    order: 4 !important;
    flex: 1 1 100% !important;
    text-align: left !important;
    font-size: 15.5px !important;
    font-weight: 800 !important;
    white-space: nowrap !important;
    padding: 7px 11px !important;
    border-radius: 9px !important;
    background: rgba(16, 185, 129, 0.12) !important;
    border: 1px solid rgba(52, 211, 153, 0.28) !important;
  }

  .sr-analytics-modal.is-light .sr-analytics-table tbody td.sr-rank-val {
    background: #f0f9ff !important;
    border: 1px solid #bae6fd !important;
    color: #0369a1 !important;
  }

  /* Thanh tỷ trọng % bên dưới trái */
  .sr-analytics-table tbody td:has(.sr-rank-share-cell) {
    order: 5 !important;
    flex: 1 1 auto !important;
    min-width: 140px !important;
  }

  /* Nút Lọc PO bên dưới phải */
  .sr-analytics-table tbody td:last-child {
    order: 6 !important;
    flex: 0 0 auto !important;
    margin-left: auto !important;
  }

  .sr-analytics-table .sr-rank-filter-btn {
    padding: 6px 12px !important;
    border-radius: 8px !important;
    font-size: 11.5px !important;
    font-weight: 700 !important;
  }

  /* ═══════════════════════════════════════════════════════════════════════════
     FLOATING PILL BOTTOM DOCK 3 NÚT ĐỒNG BỘ 100% VỚI .sr-mobile-dock TRANG CHÍNH
     ═══════════════════════════════════════════════════════════════════════════ */
  .sr-analytics-mobile-dock {
    position: fixed !important;
    left: 10px !important;
    right: 10px !important;
    bottom: calc(10px + env(safe-area-inset-bottom, 0px)) !important;
    z-index: 100020 !important;
    display: grid !important;
    grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
    gap: 6px !important;
    padding: 6px 8px !important;
    border-radius: 20px !important;
    background: rgba(8, 22, 18, 0.95) !important;
    border: 1px solid rgba(52, 211, 153, 0.36) !important;
    backdrop-filter: blur(20px) saturate(180%) !important;
    -webkit-backdrop-filter: blur(20px) saturate(180%) !important;
    box-shadow:
      0 18px 40px -8px rgba(0, 0, 0, 0.72),
      0 0 0 1px rgba(16, 185, 129, 0.16) !important;
  }

  .sr-analytics-modal.is-light .sr-analytics-mobile-dock {
    background: rgba(255, 255, 255, 0.96) !important;
    border: 1.5px solid #bae6fd !important;
    box-shadow:
      0 16px 36px -8px rgba(2, 132, 199, 0.24),
      0 0 0 1px rgba(14, 165, 233, 0.14) !important;
  }

  .sr-analytics-dock-btn {
    display: flex !important;
    flex-direction: column !important;
    align-items: center !important;
    justify-content: center !important;
    gap: 3px !important;
    min-height: 48px !important;
    padding: 5px 6px !important;
    border-radius: 14px !important;
    border: 1px solid transparent !important;
    background: transparent !important;
    color: #94a3b8 !important;
    font-size: 11px !important;
    font-weight: 700 !important;
    cursor: pointer !important;
    transition: all 0.18s ease !important;
  }

  .sr-analytics-dock-btn.active {
    background: rgba(16, 185, 129, 0.18) !important;
    border-color: rgba(52, 211, 153, 0.42) !important;
    color: #34d399 !important;
    box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08) !important;
  }

  .sr-analytics-modal.is-light .sr-analytics-dock-btn {
    color: #475569 !important;
  }

  .sr-analytics-modal.is-light .sr-analytics-dock-btn.active {
    background: linear-gradient(135deg, #0284c7 0%, #0369a1 100%) !important;
    border-color: #38bdf8 !important;
    color: #ffffff !important;
    box-shadow: 0 6px 16px -4px rgba(2, 132, 199, 0.4) !important;
  }
}

/* ─── 8. ICON TRÒN CHO CỘT HẠNG (.sr-rank-badge): VÀNG (1) • BẠC (2) • ĐỒNG (3) • XANH DƯƠNG (4+) • CHỮ TRẮNG ─── */
.sr-rank-badge,
.sr-analytics-modal.is-light .sr-rank-badge {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  width: 26px !important;
  height: 26px !important;
  min-width: 26px !important;
  padding: 0 !important;
  border-radius: 50% !important;
  border: none !important;
  font-size: 11.5px !important;
  font-weight: 800 !important;
  line-height: 1 !important;
  color: #ffffff !important;
  background: linear-gradient(135deg, #0284c7 0%, #2563eb 100%) !important;
  box-shadow: 0 2px 6px rgba(2, 132, 199, 0.3) !important;
}

.sr-rank-badge.is-top1,
.sr-analytics-modal.is-light .sr-rank-badge.is-top1 {
  background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%) !important;
  color: #ffffff !important;
  box-shadow: 0 2px 7px rgba(245, 158, 11, 0.42) !important;
}

.sr-rank-badge.is-top2,
.sr-analytics-modal.is-light .sr-rank-badge.is-top2 {
  background: linear-gradient(135deg, #94a3b8 0%, #64748b 100%) !important;
  color: #ffffff !important;
  box-shadow: 0 2px 7px rgba(100, 116, 139, 0.38) !important;
}

.sr-rank-badge.is-top3,
.sr-analytics-modal.is-light .sr-rank-badge.is-top3 {
  background: linear-gradient(135deg, #d97706 0%, #92400e 100%) !important;
  color: #ffffff !important;
  box-shadow: 0 2px 7px rgba(180, 83, 9, 0.38) !important;
}

/* ─── 9. CARD CÔNG TY Ở PC KHI ĐƯỢC CHỌN (.sr-md-company-card.active) — NỀN XANH DƯƠNG ĐẬM NHẸ RÕ RÀNG ─── */
