.sr-debt-fullscreen-overlay.is-light .m-debt-inst-metrics {
  background: #f0f9ff !important;
  border: 1px solid #bae6fd !important;
}

.sr-debt-fullscreen-overlay.is-light .m-debt-metric-lbl,
.sr-debt-fullscreen-overlay.is-light .m-debt-inst-due,
.sr-debt-fullscreen-overlay.is-light .m-debt-hist-time,
.sr-debt-fullscreen-overlay.is-light .m-debt-hist-cust-info,
.sr-debt-fullscreen-overlay.is-light .m-debt-hist-rem,
.sr-debt-fullscreen-overlay.is-light .m-debt-empty-sub {
  color: #475569 !important;
}

.sr-debt-fullscreen-overlay.is-light .m-debt-hist-note {
  background: #f8fafc !important;
  border-color: #cbd5e1 !important;
  color: #334155 !important;
}

/* ─── 2 SUB-MODALS (THIẾT LẬP KẾ HOẠCH HẠN & GHI NHẬN ĐỢT THANH TOÁN) TRONG LIGHT MODE ─── */
.sr-modal-overlay.is-light .debt-schedule-submodal,
.sr-modal-overlay.is-light .debt-record-submodal {
  background: #ffffff !important;
  border: 2px solid #0284c7 !important;
  color: #0f172a !important;
  box-shadow: 0 20px 50px rgba(15, 23, 42, 0.22) !important;
}

.sr-modal-overlay.is-light .debt-sub-body {
  background: #f8fafc !important;
  color: #0f172a !important;
}

.sr-modal-overlay.is-light .debt-sub-body label,
.sr-modal-overlay.is-light .debt-sub-body span {
  color: #334155 !important;
}

.sr-modal-overlay.is-light .debt-sub-seg button span,
.sr-modal-overlay.is-light .debt-sub-save span {
  color: inherit !important;
}

.sr-modal-overlay.is-light .debt-sub-body .sr-modal-input {
  background: #ffffff !important;
  border: 1.5px solid #cbd5e1 !important;
  color: #0f172a !important;
}

.sr-modal-overlay.is-light .debt-sub-table-wrap {
  background: #ffffff !important;
  border: 1.5px solid #bae6fd !important;
}

.sr-modal-overlay.is-light .debt-sub-table-wrap thead tr {
  background: #f0f9ff !important;
  border-bottom: 1.5px solid #bae6fd !important;
  color: #0369a1 !important;
}

.sr-modal-overlay.is-light .debt-sub-table-wrap tbody tr {
  border-bottom: 1px dashed #cbd5e1 !important;
}

.sr-modal-overlay.is-light .debt-sub-footer {
  background: #ffffff !important;
  border-top: 1.5px solid #e2e8f0 !important;
}

.sr-modal-overlay.is-light .debt-sub-cancel {
  background: #f1f5f9 !important;
  border: 1.5px solid #cbd5e1 !important;
  color: #0f172a !important;
}

/* Nút mũi tên quay lại ở Header Modal Phân tích */
.sr-analytics-back-btn {
  width: 38px;
  height: 38px;
  border-radius: 11px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: rgba(16, 185, 129, 0.16);
  border: 1px solid rgba(52, 211, 153, 0.42);
  color: #34d399;
  cursor: pointer;
  flex-shrink: 0;
  transition: all 0.18s ease;
}

.sr-analytics-back-btn:hover {
  background: rgba(16, 185, 129, 0.28);
  transform: translateX(-1px);
}

.sr-analytics-modal.is-light .sr-analytics-back-btn {
  background: rgba(255, 255, 255, 0.2);
  border: 1px solid rgba(255, 255, 255, 0.4);
  color: #ffffff;
}

.sr-analytics-modal.is-light .sr-analytics-back-btn:hover {
  background: rgba(255, 255, 255, 0.32);
}

/* Biểu đồ Thanh Ngang (Horizontal Bar) & Chuẩn hóa Safe-Area Header tất cả Modal trên Mobile */
@media (max-width: 1080px) {
  .sr-analytics-bar-scroll {
    overflow-x: hidden !important;
  }

  .sr-analytics-bar-scroll .chart-wrapper-mobile {
    width: 100% !important;
    min-width: 100% !important;
    max-width: 100% !important;
    height: var(--mob-bar-h, 340px) !important;
    overflow-x: hidden !important;
  }

  /* ─── 1. SỬA LỖI CARD PILL ĐƠN HÀNG PO TRONG MODAL TIẾN ĐỘ & LỊCH SỬ THANH TOÁN MOBILE ─── */
  .debt-payment-modal button.m-debt-po-pill {
    display: inline-flex !important;
    flex-direction: column !important;
    align-items: flex-start !important;
    justify-content: center !important;
    height: auto !important;
    min-height: 48px !important;
    padding: 7px 12px !important;
    gap: 3px !important;
    white-space: nowrap !important;
  }

  .debt-payment-modal .m-debt-po-sep {
    display: none !important;
  }

  .debt-payment-modal .m-debt-po-code {
    font-size: 12px !important;
    font-weight: 800 !important;
    line-height: 1.25 !important;
  }

  .debt-payment-modal .m-debt-po-state {
    font-size: 11.5px !important;
    font-weight: 700 !important;
    line-height: 1.25 !important;
    color: #fb7185 !important;
  }

  .sr-debt-fullscreen-overlay.is-light .debt-payment-modal .m-debt-po-state {
    color: #dc2626 !important;
  }

  .debt-payment-modal button.m-debt-po-pill.is-paid .m-debt-po-state {
    color: #34d399 !important;
  }

  .sr-debt-fullscreen-overlay.is-light .debt-payment-modal button.m-debt-po-pill.is-paid .m-debt-po-state {
    color: #059669 !important;
  }

  /* ─── 2. PHƯƠNG ÁN A: CHUẨN HÓA HEADER TẤT CẢ MODAL MOBILE NÉ THANH PIN / ĐỒNG HỒ (52px) ─── */
  /* Các Modal Fullscreen trên Mobile */
  .sr-po-modal,
  .sr-analytics-modal,
  .sr-mindmap-modal,
  .debt-payment-modal.sr-debt-fullscreen-card,
  .sr-filter-picker-modal,
  .sr-dbsync-modal,
  .sr-modal.sr-modal-large {
    width: 100% !important;
    max-width: 100% !important;
    height: 100dvh !important;
    max-height: 100dvh !important;
    margin: 0 !important;
    border-radius: 0 !important;
  }

  .sr-modal-overlay:has(> .sr-po-modal),
  .sr-modal-overlay:has(> .sr-analytics-modal),
  .sr-modal-overlay:has(> .sr-mindmap-modal),
  .sr-modal-overlay:has(> .sr-filter-picker-modal),
  .sr-modal-overlay:has(> .sr-modal-large),
  .sr-debt-fullscreen-overlay,
  .sr-dbsync-overlay {
    padding: 0 !important;
  }

  /* Đẩy nội dung Header của các Modal Fullscreen xuống dưới vùng Pin / Tai thỏ / Dynamic Island */
  .sr-po-modal > .sr-po-modal-header,
  .sr-analytics-modal > .sr-analytics-header,
  .sr-mindmap-modal > .sr-mindmap-header,
  .debt-payment-modal > .sr-debt-head,
  .sr-filter-picker-modal > .sr-fpm-header,
  .sr-dbsync-modal > .sr-dbsync-header,
  .sr-modal.sr-modal-large > .sr-modal-header {
    padding-top: max(calc(env(safe-area-inset-top, 0px) + 6px), 52px) !important;
    padding-bottom: 12px !important;
    padding-left: 14px !important;
    padding-right: 14px !important;
    border-radius: 0 !important;
  }

  /* Nút đóng (X) trong Header Modal Tiến độ thanh toán căn ngang hàng với tiêu đề bên dưới vùng Pin */
  .debt-payment-modal > .sr-debt-head {
    display: flex !important;
    align-items: center !important;
    justify-content: space-between !important;
  }

  .debt-payment-modal > .sr-debt-head .m-grab-head-stack {
    padding-right: 8px !important;
  }

  .debt-payment-modal > .sr-debt-head > button.x {
    position: static !important;
    top: auto !important;
    right: auto !important;
    transform: none !important;
    width: 34px !important;
    height: 34px !important;
    min-width: 34px !important;
    flex-shrink: 0 !important;
    margin: 0 !important;
  }

  .sr-modal.sr-modal-large > .sr-modal-header .sr-btn-close {
    top: max(calc(env(safe-area-inset-top, 0px) + 8px), 52px) !important;
  }

  /* Các Modal nhỏ / Sub-modal / Dialog giữa màn hình: luôn cách vùng Pin tối thiểu 56px */
  .sr-modal-overlay:not(:has(> .sr-po-modal)):not(:has(> .sr-analytics-modal)):not(:has(> .sr-filter-picker-modal)):not(:has(> .sr-modal-large)),
  .sr-dialog-overlay {
    padding-top: max(calc(env(safe-area-inset-top, 0px) + 12px), 56px) !important;
    padding-bottom: max(calc(env(safe-area-inset-bottom, 0px) + 12px), 24px) !important;
    padding-left: 12px !important;
    padding-right: 12px !important;
    box-sizing: border-box !important;
  }

  .sr-modal:not(.sr-modal-large):not(.sr-po-modal):not(.sr-analytics-modal),
  .sr-add-choice-modal,
  .sr-year-modal,
  .sr-dialog-card,
  .debt-schedule-submodal,
  .debt-record-submodal {
    max-height: calc(100dvh - max(calc(env(safe-area-inset-top, 0px) + 24px), 80px)) !important;
  }
}

@media (max-width: 380px) {
  .sr-super-bento-grid {
    grid-template-columns: 1fr;
  }
}

/* ═══════════════════════════════════════════════════════════════════════════
   REVIEW KINH DOANH — INTERACTIVE BUSINESS MINDMAP MODAL (PC & MOBILE, DARK & LIGHT)
   ═══════════════════════════════════════════════════════════════════════════ */
.bg-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.bg-topbar-right {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.sr-topbar-review-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 14px;
  border-radius: 999px;
  background: linear-gradient(135deg, #0284c7, #0369a1);
  color: #ffffff !important;
  border: 1px solid rgba(56, 189, 248, 0.45);
  font-size: 12.5px;
  font-weight: 800;
  cursor: pointer;
  box-shadow: 0 4px 12px rgba(2, 132, 199, 0.28);
  transition: all 0.18s ease;
}

.sr-topbar-review-btn:hover {
  background: linear-gradient(135deg, #0369a1, #075985);
  transform: translateY(-1px);
  box-shadow: 0 6px 16px rgba(2, 132, 199, 0.38);
}

.sr-hdr-action-btn.is-review-mindmap {
  background: linear-gradient(135deg, #0284c7, #0369a1) !important;
  color: #ffffff !important;
  border: 1px solid rgba(56, 189, 248, 0.45) !important;
  box-shadow: 0 3px 10px rgba(2, 132, 199, 0.24);
}

.sr-hdr-action-btn.is-review-mindmap:hover {
  background: linear-gradient(135deg, #0369a1, #075985) !important;
  transform: translateY(-1px);
}

.sr-plain-text-btn.is-folder-review-btn {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 10px;
  border-radius: 999px;
  background: rgba(2, 132, 199, 0.16);
  border: 1px solid rgba(56, 189, 248, 0.35);
  color: #38bdf8;
  font-size: 11.5px;
  font-weight: 800;
  margin-right: 6px;
}

.theme-light-blue .sr-plain-text-btn.is-folder-review-btn {
  background: #e0f2fe;
  border-color: #7dd3fc;
  color: #0369a1;
}

.sr-plain-text-btn.is-folder-review-btn:hover {
  background: #0284c7;
  color: #ffffff;
  border-color: #0284c7;
}

/* Modal Container */
.sr-mindmap-modal {
  width: 100vw !important;
  max-width: 100vw !important;
  height: 100dvh !important;
  max-height: 100dvh !important;
  margin: 0 !important;
  border-radius: 0 !important;
  display: flex;
  flex-direction: column;
  background: #090d16;
  color: #f8fafc;
  overflow: hidden;
}

.sr-mindmap-modal.is-light {
  background: #f1f5f9;
  color: #0f172a;
}

/* Header */
.sr-mindmap-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 20px;
  background: linear-gradient(135deg, #0f172a 0%, #1e293b 100%);
  border-bottom: 1px solid rgba(56, 189, 248, 0.22);
  flex-shrink: 0;
}

.sr-mindmap-modal.is-light .sr-mindmap-header {
  background: linear-gradient(135deg, #0284c7 0%, #0369a1 100%);
  border-bottom: 1px solid rgba(2, 132, 199, 0.3);
}

.sr-mindmap-header-left {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.sr-mindmap-header-icon {
  width: 34px;
  height: 34px;
  border-radius: 10px;
  background: rgba(56, 189, 248, 0.16);
  border: 1px solid rgba(56, 189, 248, 0.38);
  color: #38bdf8;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.sr-mindmap-modal.is-light .sr-mindmap-header-icon {
  background: rgba(255, 255, 255, 0.2);
  border-color: rgba(255, 255, 255, 0.38);
  color: #ffffff;
}

.sr-mindmap-title-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

.sr-mindmap-title {
  margin: 0;
  font-size: 16px;
  font-weight: 800;
  color: #ffffff;
  letter-spacing: -0.01em;
}

.sr-mindmap-scope-pill {
  padding: 3px 10px;
  border-radius: 999px;
  background: rgba(56, 189, 248, 0.16);
  border: 1px solid rgba(56, 189, 248, 0.35);
  color: #7dd3fc;
  font-size: 11.5px;
  font-weight: 700;
}

.sr-mindmap-modal.is-light .sr-mindmap-scope-pill {
  background: rgba(255, 255, 255, 0.2);
  border-color: rgba(255, 255, 255, 0.38);
  color: #ffffff;
}

.sr-mindmap-scope-reset-btn {
  padding: 3px 10px;
  border-radius: 999px;
  background: #10b981;
  color: #ffffff;
  border: none;
  font-size: 11px;
  font-weight: 800;
  cursor: pointer;
}

.sr-mindmap-header-right {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.sr-mindmap-jump-analytics-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  border-radius: 8px;
  background: rgba(255, 255, 255, 0.12);
  border: 1px solid rgba(255, 255, 255, 0.24);
  color: #ffffff;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
}

.sr-mindmap-jump-analytics-btn:hover {
  background: rgba(255, 255, 255, 0.22);
}

/* Subheader Toolbar */
.sr-mindmap-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 10px;
  padding: 10px 20px;
  background: #0f172a;
  border-bottom: 1px solid #1e293b;
  flex-shrink: 0;
}

.sr-mindmap-modal.is-light .sr-mindmap-toolbar {
  background: #ffffff;
  border-bottom: 1px solid #cbd5e1;
}

.sr-mindmap-seg-group,
.sr-mindmap-layout-switch {
  display: inline-flex;
  align-items: center;
  background: #1e293b;
  padding: 3px;
  border-radius: 9px;
  border: 1px solid #334155;
  gap: 3px;
}

.sr-mindmap-modal.is-light .sr-mindmap-seg-group,
.sr-mindmap-modal.is-light .sr-mindmap-layout-switch {
  background: #f1f5f9;
  border-color: #cbd5e1;
}

.sr-mindmap-seg-btn,
.sr-mindmap-layout-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  border-radius: 7px;
  border: none;
  background: transparent;
  color: #94a3b8;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.15s;
}

.sr-mindmap-modal.is-light .sr-mindmap-seg-btn,
.sr-mindmap-modal.is-light .sr-mindmap-layout-btn {
  color: #475569;
}

.sr-mindmap-seg-btn.active,
.sr-mindmap-layout-btn.active {
  background: #0284c7;
  color: #ffffff !important;
  box-shadow: 0 2px 8px rgba(2, 132, 199, 0.3);
}

.sr-mindmap-search-box {
  display: flex;
  align-items: center;
  gap: 7px;
  background: #1e293b;
  border: 1px solid #334155;
  border-radius: 8px;
  padding: 5px 11px;
  flex: 1;
  min-width: 210px;
  max-width: 360px;
  color: #94a3b8;
}

.sr-mindmap-modal.is-light .sr-mindmap-search-box {
  background: #f8fafc;
  border-color: #cbd5e1;
  color: #64748b;
}

.sr-mindmap-search-input {
  border: none;
  background: transparent;
  color: #f8fafc;
  font-size: 12.5px;
  width: 100%;
  outline: none;
}

.sr-mindmap-modal.is-light .sr-mindmap-search-input {
  color: #0f172a;
}

.sr-mindmap-search-clear {
  border: none;
  background: transparent;
  color: #94a3b8;
  cursor: pointer;
  font-size: 12px;
  padding: 0 2px;
}

.sr-mindmap-actions-right {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.sr-mindmap-tool-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 6px 11px;
  border-radius: 8px;
  background: rgba(56, 189, 248, 0.12);
  border: 1px solid rgba(56, 189, 248, 0.3);
  color: #38bdf8;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
}

.sr-mindmap-modal.is-light .sr-mindmap-tool-btn {
  background: #e0f2fe;
  border-color: #7dd3fc;
  color: #0369a1;
}

.sr-mindmap-tool-btn:hover {
  background: #0284c7;
  color: #ffffff;
  border-color: #0284c7;
}

/* Body & Canvas Viewport */
.sr-mindmap-body {
  flex: 1;
  min-height: 0;
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.sr-mindmap-canvas-viewport {
  flex: 1;
  width: 100%;
  height: 100%;
  overflow: auto;
  position: relative;
  cursor: grab;
  user-select: none;
  background-color: #090d16;
  background-image: radial-gradient(rgba(56, 189, 248, 0.14) 1px, transparent 1px);
  background-size: 22px 22px;
  padding: 36px 48px;
}

.sr-mindmap-modal.is-light .sr-mindmap-canvas-viewport {
  background-color: #f1f5f9;
  background-image: radial-gradient(rgba(2, 132, 199, 0.16) 1px, transparent 1px);
}

.sr-mindmap-canvas-viewport.is-panning {
  cursor: grabbing;
}

.sr-mindmap-canvas-stage {
  position: relative;
  transform-origin: 0 0;
  will-change: transform;
  display: inline-block;
  min-width: max-content;
  padding-bottom: 80px;
  padding-right: 80px;
}

.sr-mindmap-canvas-stage.is-vertical-stage {
  transform-origin: 0 0;
  min-width: 100%;
  width: max-content;
  padding-left: 48px;
  padding-right: 48px;
  padding-bottom: 100px;
}

.sr-mindmap-canvas-stage.is-camera-animating {
  transition: transform 0.52s cubic-bezier(0.22, 1, 0.36, 1);
}

.sr-mm-root-col.is-root-only::after {
  display: none !important;
}

/* Horizontal Mindmap Tree & Connectors */
.sr-mm-tree {
  display: flex;
  align-items: center;
}

.sr-mm-root-col {
  display: flex;
  align-items: center;
  position: relative;
  padding-right: 32px;
}

.sr-mm-root-col::after {
  content: '';
  position: absolute;
  right: 0;
  top: 50%;
  width: 32px;
  height: 2.5px;
  background: #0284c7;
}

.sr-mm-children-col {
  display: flex;
  flex-direction: column;
  justify-content: center;
  position: relative;
}

.sr-mm-branch-row {
  display: flex;
  align-items: center;
  position: relative;
  padding: 10px 0 10px 32px;
}

/* Horizontal connector into each child node */
.sr-mm-branch-row::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  width: 32px;
  height: 2px;
  background: rgba(56, 189, 248, 0.55);
}

.sr-mindmap-modal.is-light .sr-mm-branch-row::before {
  background: rgba(2, 132, 199, 0.55);
}

/* Vertical spine connecting sibling branches */
.sr-mm-branch-row::after {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 2px;
  background: rgba(56, 189, 248, 0.55);
}

.sr-mindmap-modal.is-light .sr-mm-branch-row::after {
  background: rgba(2, 132, 199, 0.55);
}

.sr-mm-branch-row:first-child::after {
  top: 50%;
}

.sr-mm-branch-row:last-child::after {
  bottom: 50%;
}

.sr-mm-branch-row:only-child::after {
  display: none;
}

/* Outgoing connector when a node has expanded children */
.sr-mm-node-wrap {
  position: relative;
  display: flex;
  align-items: center;
}

.sr-mm-branch-row:has(> .sr-mm-children-col) > .sr-mm-node-wrap {
  padding-right: 28px;
}

.sr-mm-branch-row:has(> .sr-mm-children-col) > .sr-mm-node-wrap::after {
  content: '';
  position: absolute;
  right: 0;
  top: 50%;
  width: 28px;
  height: 2px;
  background: rgba(56, 189, 248, 0.55);
}

.sr-mindmap-modal.is-light .sr-mm-branch-row:has(> .sr-mm-children-col) > .sr-mm-node-wrap::after {
  background: rgba(2, 132, 199, 0.55);
}

/* Vertical Mindmap Tree & Connectors (Top -> Bottom) */
.sr-mm-tree.is-vertical {
  flex-direction: column;
  align-items: center;
}

.sr-mm-tree.is-vertical .sr-mm-root-col {
  padding-right: 0;
  padding-bottom: 32px;
  justify-content: center;
}

.sr-mm-tree.is-vertical .sr-mm-root-col::after {
  right: auto;
  top: auto;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 2.5px;
  height: 32px;
}

.sr-mm-tree.is-vertical .sr-mm-children-col {
  flex-direction: row;
  align-items: flex-start;
  justify-content: center;
}

.sr-mm-tree.is-vertical .sr-mm-branch-row {
  flex-direction: column;
  align-items: center;
  justify-content: flex-start;
  padding: 32px 12px 0 12px;
}

/* Vertical connector dropping down into each child node */
.sr-mm-tree.is-vertical .sr-mm-branch-row::before {
  left: 50%;
  top: 0;
  transform: translateX(-50%);
  width: 2px;
  height: 32px;
}

/* Horizontal spine connecting sibling branches at top */
.sr-mm-tree.is-vertical .sr-mm-branch-row::after {
  top: 0;
  bottom: auto;
  left: 0;
  right: 0;
  width: auto;
  height: 2px;
}

.sr-mm-tree.is-vertical .sr-mm-branch-row:first-child::after {
  top: 0;
  left: 50%;
}

.sr-mm-tree.is-vertical .sr-mm-branch-row:last-child::after {
  top: 0;
  bottom: auto;
  right: 50%;
}

.sr-mm-tree.is-vertical .sr-mm-branch-row:only-child::after {
  display: none;
}

.sr-mm-tree.is-vertical .sr-mm-node-wrap {
  flex-direction: column;
  align-items: center;
}

.sr-mm-tree.is-vertical .sr-mm-branch-row:has(> .sr-mm-children-col) > .sr-mm-node-wrap {
  padding-right: 0;
  padding-bottom: 28px;
}

.sr-mm-tree.is-vertical .sr-mm-branch-row:has(> .sr-mm-children-col) > .sr-mm-node-wrap::after {
  right: auto;
  top: auto;
  bottom: 0;
  left: 50%;
  transform: translateX(-50%);
  width: 2px;
  height: 28px;
}

/* Mindmap Node Cards */
.sr-mm-node {
  background: #0f172a;
  border: 1px solid #1e293b;
  border-radius: 14px;
  padding: 14px 16px;
  box-shadow: 0 10px 26px rgba(0, 0, 0, 0.42);
  transition: border-color 0.18s ease, box-shadow 0.18s ease, transform 0.18s ease;
  color: #f8fafc;
}

.sr-mindmap-modal.is-light .sr-mm-node {
  background: #ffffff;
  border-color: #cbd5e1;
  box-shadow: 0 6px 20px rgba(15, 23, 42, 0.07);
  color: #0f172a;
}

.sr-mm-node.is-root-node {
  width: 350px;
  border: 2px solid #0284c7;
  background: linear-gradient(160deg, #0f172a 0%, #111c33 100%);
}

.sr-mindmap-modal.is-light .sr-mm-node.is-root-node {
  background: linear-gradient(160deg, #ffffff 0%, #f0f9ff 100%);
  border: 2px solid #0284c7;
}

.sr-mm-node.is-company-node,
.sr-mm-node.is-pillar-node {
  width: 340px;
  cursor: pointer;
}

.sr-mm-node.is-company-node.is-expanded,
.sr-mm-node.is-po-node.is-expanded {
  border-color: #0284c7;
  box-shadow: 0 0 0 1px rgba(2, 132, 199, 0.35), 0 10px 24px rgba(2, 132, 199, 0.15);
}

.sr-mindmap-modal.is-light .sr-mm-node.is-company-node.is-expanded,
.sr-mindmap-modal.is-light .sr-mm-node.is-po-node.is-expanded {
  background: #f0f9ff;
  border-color: #0284c7;
}

.sr-mm-node.is-po-node {
  width: 325px;
  cursor: pointer;
}

.sr-mm-node.is-leaf-node {
  width: 295px;
  padding: 11px 14px;
}

.sr-mm-node.is-leaf-blue { border-left: 4px solid #0284c7; }
.sr-mm-node.is-leaf-emerald { border-left: 4px solid #10b981; }
.sr-mm-node.is-leaf-rose { border-left: 4px solid #ef4444; }
.sr-mm-node.is-leaf-slate { border-left: 4px solid #64748b; }

/* Node Internals */
.sr-mm-node-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 8px;
}

.sr-mm-head-left {
