  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  min-width: 0;
}

.sr-mm-badge {
  display: inline-flex;
  align-items: center;
  padding: 2.5px 8px;
  border-radius: 6px;
  font-size: 10.5px;
