}

.sr-mm-badge.is-blue { background: rgba(2, 132, 199, 0.2); color: #38bdf8; }
.sr-mm-badge.is-emerald { background: rgba(16, 185, 129, 0.2); color: #34d399; }
.sr-mm-badge.is-rose { background: rgba(239, 68, 68, 0.2); color: #f87171; }
.sr-mm-badge.is-slate { background: rgba(148, 163, 184, 0.2); color: #cbd5e1; }

.sr-mindmap-modal.is-light .sr-mm-badge.is-blue { background: #e0f2fe; color: #0369a1; }
.sr-mindmap-modal.is-light .sr-mm-badge.is-emerald { background: #d1fae5; color: #047857; }
.sr-mindmap-modal.is-light .sr-mm-badge.is-rose { background: #fee2e2; color: #b91c1c; }
.sr-mindmap-modal.is-light .sr-mm-badge.is-slate { background: #e2e8f0; color: #334155; }

.sr-mm-sub-count,
.sr-mm-po-count-badge {
  font-size: 11px;
  font-weight: 800;
  padding: 2px 8px;
  border-radius: 999px;
  background: rgba(56, 189, 248, 0.14);
  color: #38bdf8;
  white-space: nowrap;
}

.sr-mindmap-modal.is-light .sr-mm-sub-count,
.sr-mindmap-modal.is-light .sr-mm-po-count-badge {
  background: #e0f2fe;
  color: #0284c7;
}

.sr-mm-rank-circle {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 11px;
  font-weight: 800;
  color: #ffffff;
  flex-shrink: 0;
}

.sr-mm-rank-circle.is-r1 { background: #eab308; }
.sr-mm-rank-circle.is-r2 { background: #94a3b8; }
.sr-mm-rank-circle.is-r3 { background: #d97706; }
.sr-mm-rank-circle.is-rn { background: #0284c7; }

.sr-mm-kh-pill,
.sr-mm-mst-pill,
.sr-mm-ncc-tag {
  font-size: 10.5px;
  font-weight: 700;
  padding: 1.5px 6px;
