  background: rgba(148, 163, 184, 0.14);
  color: #cbd5e1;
}

.sr-mindmap-modal.is-light .sr-mm-kh-pill,
.sr-mindmap-modal.is-light .sr-mm-mst-pill,
.sr-mindmap-modal.is-light .sr-mm-ncc-tag {
  background: #e2e8f0;
  color: #334155;
}

.sr-mm-root-title,
.sr-mm-company-name {
  font-size: 13.5px;
  font-weight: 800;
  line-height: 1.35;
  margin-bottom: 9px;
  color: #f8fafc;
}

.sr-mindmap-modal.is-light .sr-mm-root-title,
.sr-mindmap-modal.is-light .sr-mm-company-name {
  color: #0f172a;
}

.sr-mm-po-code {
  font-size: 12.5px;
  font-weight: 800;
  color: #38bdf8;
}

.sr-mindmap-modal.is-light .sr-mm-po-code {
