}

.sr-mm-po-date {
  font-size: 11px;
  color: #94a3b8;
}

.sr-mindmap-modal.is-light .sr-mm-po-date {
  color: #64748b;
}

.sr-mm-status-tag {
  font-size: 10.5px;
  font-weight: 800;
  padding: 2px 7px;
  border-radius: 999px;
  white-space: nowrap;
}

.sr-mm-status-tag.is-settled { background: rgba(16, 185, 129, 0.16); color: #34d399; }
.sr-mm-status-tag.is-debt { background: rgba(245, 158, 11, 0.16); color: #fbbf24; }
