.sr-mindmap-modal.is-light .sr-mm-status-tag.is-settled { background: #d1fae5; color: #059669; }
.sr-mindmap-modal.is-light .sr-mm-status-tag.is-debt { background: #fef3c7; color: #d97706; }
.sr-mindmap-modal.is-light .sr-mm-status-tag.is-overdue { background: #fee2e2; color: #dc2626; }

.sr-mm-po-contract {
