}

/* Semantic Value Colors */
.is-blue-val { color: #38bdf8 !important; }
.is-emerald-val { color: #10b981 !important; }
.is-rose-val { color: #f87171 !important; }

.sr-mindmap-modal.is-light .is-blue-val { color: #0284c7 !important; }
.sr-mindmap-modal.is-light .is-emerald-val { color: #059669 !important; }
.sr-mindmap-modal.is-light .is-rose-val { color: #dc2626 !important; }

.sr-mm-progress-bar {
  margin-top: 9px;
  height: 5px;
  border-radius: 999px;
  background: rgba(148, 163, 184, 0.2);
  overflow: hidden;
}

.sr-mm-progress-fill {
  height: 100%;
  background: linear-gradient(90deg, #0284c7, #10b981);
  border-radius: 999px;
}

/* Node Footer & Action Buttons */
.sr-mm-node-foot {
