  align-items: center;
  gap: 5px;
}

.sr-mm-mini-btn {
  padding: 4px 9px;
  border-radius: 6px;
  border: 1px solid rgba(56, 189, 248, 0.35);
  background: rgba(2, 132, 199, 0.14);
  color: #38bdf8;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
}

.sr-mindmap-modal.is-light .sr-mm-mini-btn {
  background: #e0f2fe;
  border-color: #7dd3fc;
  color: #0369a1;
}

.sr-mm-mini-btn.is-red {
  background: #dc2626;
