  margin-bottom: 7px;
  padding-bottom: 5px;
  border-bottom: 1px solid rgba(148, 163, 184, 0.18);
}

.sr-mm-leaf-title.is-blue { color: #38bdf8; }
.sr-mm-leaf-title.is-emerald { color: #10b981; }
.sr-mm-leaf-title.is-rose { color: #f87171; }
.sr-mm-leaf-title.is-slate { color: #cbd5e1; }

.sr-mindmap-modal.is-light .sr-mm-leaf-title.is-blue { color: #0284c7; }
.sr-mindmap-modal.is-light .sr-mm-leaf-title.is-emerald { color: #059669; }
.sr-mindmap-modal.is-light .sr-mm-leaf-title.is-rose { color: #dc2626; }
.sr-mindmap-modal.is-light .sr-mm-leaf-title.is-slate { color: #334155; }

.sr-mm-leaf-rows {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.sr-mm-leaf-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  font-size: 11.5px;
}

.sr-mm-leaf-row span {
  color: #94a3b8;
  font-weight: 600;
}

.sr-mindmap-modal.is-light .sr-mm-leaf-row span {
