  color: #ffffff !important;
}

.sr-mm-leaf-cta.is-red { background: linear-gradient(135deg, #ef4444, #dc2626); }
.sr-mm-leaf-cta.is-blue { background: linear-gradient(135deg, #0284c7, #0369a1); }

/* Floating Zoom HUD */
.sr-mindmap-hud {
  position: fixed;
  right: 22px;
  bottom: 22px;
  z-index: 20;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  border-radius: 999px;
  background: rgba(15, 23, 42, 0.92);
  border: 1px solid rgba(56, 189, 248, 0.35);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.45);
}

.sr-mindmap-modal.is-light .sr-mindmap-hud {
  background: rgba(255, 255, 255, 0.95);
  border-color: #cbd5e1;
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.12);
}

