}

.sr-mm-hud-btn {
  min-width: 30px;
  height: 28px;
  border-radius: 999px;
  border: 1px solid rgba(148, 163, 184, 0.3);
  background: rgba(30, 41, 59, 0.8);
  color: #f8fafc;
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
  padding: 0 8px;
}

.sr-mindmap-modal.is-light .sr-mm-hud-btn {
  background: #f1f5f9;
  color: #0f172a;
  border-color: #cbd5e1;
}

.sr-mm-hud-btn:hover {
  background: #0284c7;
  color: #ffffff;
  border-color: #0284c7;
}

/* Vertical Indented Tree View (Mobile & Quick-Read Mode) */
.sr-mindmap-vtree-scroll {
  flex: 1;
  overflow-y: auto;
  padding: 16px 20px 40px;
}

.sr-vtree-container {
  max-width: 1180px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.sr-vtree-root-card {
  background: linear-gradient(145deg, #0f172a, #162238);
  border: 2px solid #0284c7;
  border-radius: 14px;
  padding: 16px;
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.35);
}

.sr-mindmap-modal.is-light .sr-vtree-root-card {
  background: linear-gradient(145deg, #ffffff, #f0f9ff);
  box-shadow: 0 6px 20px rgba(2, 132, 199, 0.08);
}

.sr-vtree-root-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 6px;
}

.sr-vtree-root-title {
  font-size: 15px;
  font-weight: 800;
  margin-bottom: 12px;
}

.sr-vtree-root-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
}

.sr-vtree-stat-box {
  padding: 10px 12px;
  border-radius: 10px;
  background: rgba(15, 23, 42, 0.65);
  border: 1px solid rgba(148, 163, 184, 0.22);
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.sr-mindmap-modal.is-light .sr-vtree-stat-box {
  background: #ffffff;
  border-color: #cbd5e1;
}

.sr-vtree-stat-box.is-blue { border-left: 4px solid #0284c7; }
.sr-vtree-stat-box.is-emerald { border-left: 4px solid #10b981; }
.sr-vtree-stat-box.is-rose { border-left: 4px solid #ef4444; }

.sr-vtree-stat-lbl {
  font-size: 11px;
  font-weight: 700;
  color: #94a3b8;
}

.sr-mindmap-modal.is-light .sr-vtree-stat-lbl {
  color: #64748b;
}

.sr-vtree-stat-val {
  font-size: 15px;
  font-weight: 800;
}

.sr-vtree-stat-box.is-blue .sr-vtree-stat-val { color: #38bdf8; }
.sr-vtree-stat-box.is-emerald .sr-vtree-stat-val { color: #10b981; }
.sr-vtree-stat-box.is-rose .sr-vtree-stat-val { color: #f87171; }

.sr-mindmap-modal.is-light .sr-vtree-stat-box.is-blue .sr-vtree-stat-val { color: #0284c7; }
.sr-mindmap-modal.is-light .sr-vtree-stat-box.is-emerald .sr-vtree-stat-val { color: #059669; }
.sr-mindmap-modal.is-light .sr-vtree-stat-box.is-rose .sr-vtree-stat-val { color: #dc2626; }

.sr-vtree-stat-box small {
  font-size: 10.5px;
  color: #94a3b8;
}

.sr-mindmap-modal.is-light .sr-vtree-stat-box small {
  color: #64748b;
}

/* Vertical Indented Branches */
.sr-vtree-branches {
  position: relative;
  padding-left: 18px;
  border-left: 2.5px solid rgba(2, 132, 199, 0.45);
  margin-left: 12px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.sr-vtree-company-item {
  position: relative;
}

.sr-vtree-company-item::before {
  content: '';
  position: absolute;
  left: -18px;
  top: 24px;
  width: 18px;
  height: 2.5px;
  background: rgba(2, 132, 199, 0.45);
}

.sr-vtree-company-card,
.sr-vtree-po-card {
  background: #0f172a;
  border: 1px solid #1e293b;
  border-radius: 12px;
  padding: 13px 15px;
  cursor: pointer;
  transition: all 0.16s ease;
}

.sr-mindmap-modal.is-light .sr-vtree-company-card,
.sr-mindmap-modal.is-light .sr-vtree-po-card {
  background: #ffffff;
  border-color: #cbd5e1;
}

.sr-vtree-company-card.is-open,
.sr-vtree-po-card.is-open {
  border-color: #0284c7;
}

.sr-mindmap-modal.is-light .sr-vtree-company-card.is-open,
.sr-mindmap-modal.is-light .sr-vtree-po-card.is-open {
  background: #f0f9ff;
  border-color: #0284c7;
}

.sr-vtree-c-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 4px;
}

.sr-vtree-c-title-row {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}

.sr-vtree-c-name {
  font-size: 13.5px;
  font-weight: 800;
}

.sr-vtree-c-sub {
  font-size: 11.5px;
  color: #94a3b8;
  margin-bottom: 8px;
}

.sr-mindmap-modal.is-light .sr-vtree-c-sub {
  color: #475569;
}

.sr-vtree-po-list {
  margin-top: 10px;
  margin-left: 14px;
  padding-left: 16px;
  border-left: 2px dashed rgba(16, 185, 129, 0.5);
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.sr-vtree-po-item {
  position: relative;
}

.sr-vtree-po-item::before {
  content: '';
  position: absolute;
  left: -16px;
  top: 22px;
  width: 16px;
  height: 2px;
  background: rgba(16, 185, 129, 0.5);
}

.sr-vtree-leaf-grid {
  margin-top: 8px;
  margin-left: 12px;
  padding-left: 14px;
  border-left: 2px dotted rgba(56, 189, 248, 0.45);
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
}

.sr-vtree-leaf-grid .sr-mm-node.is-leaf-node {
  width: 100%;
}

@media (max-width: 1080px) {
  .sr-mindmap-header {
    padding: 9px 12px;
  }

  .sr-mindmap-toolbar {
    padding: 6px 10px;
    gap: 6px;
    flex-wrap: nowrap;
    overflow-x: auto;
  }

  .sr-mindmap-layout-switch {
    width: auto;
    flex-shrink: 0;
    flex-wrap: nowrap;
  }

  .sr-mindmap-layout-btn {
    white-space: nowrap;
    padding: 5px 8px;
    font-size: 11.5px;
    justify-content: center;
  }

  .sr-mindmap-search-cluster {
    flex: 0 0 auto;
    min-width: 0;
  }

  .sr-mindmap-actions-right {
    width: auto;
    flex-shrink: 0;
    flex-wrap: nowrap;
    gap: 6px;
  }

  .sr-vtree-root-grid {
    grid-template-columns: 1fr 1fr;
  }

  .sr-vtree-leaf-grid {
    grid-template-columns: 1fr;
    margin-left: 6px;
    padding-left: 10px;
  }

  .sr-mindmap-vtree-scroll {
    padding: 12px 10px 60px;
  }

  .sr-vtree-branches {
    margin-left: 6px;
    padding-left: 12px;
  }

  .sr-vtree-company-item::before {
    left: -12px;
    width: 12px;
  }

  .sr-vtree-po-list {
    margin-left: 8px;
    padding-left: 12px;
  }

  .sr-vtree-po-item::before {
    left: -12px;
    width: 12px;
  }
}

@media (max-width: 560px) {
  .sr-vtree-root-grid {
    grid-template-columns: 1fr;
  }
}

/* ═══════════════════════════════════════════════════════════════════════════
   SLIDE PRESENTATION DECK (TRÌNH CHIẾU SLIDE REVIEW KINH DOANH PC & MOBILE)
   ═══════════════════════════════════════════════════════════════════════════ */
.sr-mindmap-tool-btn.is-playing {
  background: #10b981 !important;
  border-color: #10b981 !important;
  color: #ffffff !important;
}

.sr-slide-chapter-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 20px;
  background: #0b1120;
  border-bottom: 1px solid #1e293b;
  overflow-x: auto;
  flex-shrink: 0;
}

.sr-mindmap-modal.is-light .sr-slide-chapter-bar {
  background: #f8fafc;
  border-bottom: 1px solid #e2e8f0;
}

.sr-slide-chapter-pill {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 11px;
  border-radius: 999px;
  border: 1px solid #1e293b;
  background: #111827;
  color: #94a3b8;
  font-size: 11.5px;
  font-weight: 700;
  white-space: nowrap;
  cursor: pointer;
  transition: all 0.16s ease;
  flex-shrink: 0;
}

.sr-mindmap-modal.is-light .sr-slide-chapter-pill {
  background: #ffffff;
  border-color: #cbd5e1;
  color: #475569;
}

.sr-slide-chapter-pill .sr-sc-num {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: rgba(148, 163, 184, 0.18);
  color: #cbd5e1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  font-weight: 800;
}

.sr-mindmap-modal.is-light .sr-slide-chapter-pill .sr-sc-num {
  background: #e2e8f0;
  color: #334155;
}

.sr-slide-chapter-pill.active {
  background: #0284c7;
  border-color: #38bdf8;
  color: #ffffff !important;
  box-shadow: 0 3px 10px rgba(2, 132, 199, 0.35);
}

.sr-slide-chapter-pill.active .sr-sc-num {
  background: rgba(255, 255, 255, 0.24);
  color: #ffffff;
}

/* Slide Viewport & Edge Arrows */
.sr-slide-deck-viewport {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  position: relative;
  background-color: #090d16;
  background-image: radial-gradient(rgba(56, 189, 248, 0.12) 1px, transparent 1px);
  background-size: 24px 24px;
}

.sr-mindmap-modal.is-light .sr-slide-deck-viewport {
  background-color: #f1f5f9;
  background-image: radial-gradient(rgba(2, 132, 199, 0.14) 1px, transparent 1px);
}

.sr-slide-edge-nav {
  position: absolute;
  top: 46%;
  transform: translateY(-50%);
  z-index: 15;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1px solid rgba(56, 189, 248, 0.35);
  background: rgba(15, 23, 42, 0.85);
  color: #38bdf8;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.45);
  transition: all 0.18s ease;
}

.sr-mindmap-modal.is-light .sr-slide-edge-nav {
  background: rgba(255, 255, 255, 0.94);
  border-color: #7dd3fc;
  color: #0284c7;
  box-shadow: 0 6px 20px rgba(15, 23, 42, 0.12);
}

.sr-slide-edge-nav:hover:not(:disabled) {
  background: #0284c7;
  color: #ffffff;
  border-color: #0284c7;
  transform: translateY(-50%) scale(1.06);
}

.sr-slide-edge-nav:disabled {
  opacity: 0.28;
  cursor: not-allowed;
}

.sr-slide-edge-nav.is-prev { left: 16px; }
.sr-slide-edge-nav.is-next { right: 16px; }

.sr-slide-stage-scroll {
  flex: 1;
  overflow-y: auto;
  padding: 20px 68px 24px;
  display: flex;
  align-items: stretch;
  justify-content: center;
}

/* Main Slide Card */
.sr-slide-card {
  width: 100%;
  max-width: 1360px;
  margin: auto;
  background: rgba(15, 23, 42, 0.92);
  border: 1px solid rgba(56, 189, 248, 0.28);
  border-radius: 18px;
  padding: 22px 26px;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.55);
  display: flex;
  flex-direction: column;
  gap: 18px;
}

.sr-mindmap-modal.is-light .sr-slide-card {
  background: #ffffff;
  border-color: #bae6fd;
  box-shadow: 0 14px 36px rgba(15, 23, 42, 0.08);
}

.sr-slide-card-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding-bottom: 14px;
  border-bottom: 1px solid rgba(148, 163, 184, 0.18);
  flex-wrap: wrap;
}

.sr-slide-head-left {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
  flex: 1;
}

.sr-slide-step-badge {
  display: inline-flex;
  align-self: flex-start;
  padding: 2.5px 9px;
  border-radius: 999px;
  background: #0284c7;
  color: #ffffff;
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: 0.05em;
}

.sr-slide-eyebrow {
  font-size: 11px;
  font-weight: 800;
  color: #38bdf8;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.sr-mindmap-modal.is-light .sr-slide-eyebrow {
  color: #0284c7;
}

.sr-slide-main-title {
  margin: 0;
  font-size: 20px;
  font-weight: 800;
  line-height: 1.3;
  color: #f8fafc;
}

.sr-mindmap-modal.is-light .sr-slide-main-title {
  color: #0f172a;
}

.sr-slide-subtitle {
  margin: 0;
  font-size: 12.5px;
  color: #94a3b8;
}

.sr-mindmap-modal.is-light .sr-slide-subtitle {
  color: #475569;
}

.sr-slide-hero-kpi {
  padding: 10px 16px;
  border-radius: 12px;
  background: rgba(2, 132, 199, 0.12);
  border: 1px solid rgba(56, 189, 248, 0.3);
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
}

.sr-mindmap-modal.is-light .sr-slide-hero-kpi {
  background: #f0f9ff;
  border-color: #bae6fd;
}

.sr-slide-hk-lbl {
  font-size: 11px;
  font-weight: 700;
  color: #94a3b8;
  text-transform: uppercase;
}

.sr-mindmap-modal.is-light .sr-slide-hk-lbl {
  color: #0369a1;
}

.sr-slide-hk-val {
  font-size: 21px;
  font-weight: 800;
}

/* Mindmap Grid inside Slide (Left Root Hub -> Connected Right Branches) */
.sr-slide-mindmap-grid {
  display: grid;
  grid-template-columns: 360px 1fr;
  gap: 28px;
  align-items: center;
  position: relative;
}

.sr-slide-hub-col {
  position: relative;
  display: flex;
  align-items: center;
}

.sr-slide-hub-col::after {
  content: '';
  position: absolute;
  right: -28px;
  top: 50%;
  width: 28px;
  height: 2.5px;
  background: #0284c7;
}

.sr-mm-node.is-slide-root {
  width: 100% !important;
}

.sr-slide-branches-col {
  position: relative;
  padding-left: 20px;
  border-left: 2.5px solid rgba(2, 132, 199, 0.55);
}

.sr-slide-branches-col.is-2x2-branches {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}

.sr-slide-branches-col.is-list-branches {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.sr-slide-branch-card {
  background: #0f172a;
  border: 1px solid #1e293b;
  border-radius: 14px;
  padding: 15px 16px;
  cursor: pointer;
  transition: all 0.18s ease;
}

.sr-mindmap-modal.is-light .sr-slide-branch-card {
  background: #f8fafc;
  border-color: #cbd5e1;
}

.sr-slide-branch-card:hover {
  transform: translateY(-2px);
  border-color: #0284c7;
  box-shadow: 0 8px 20px rgba(2, 132, 199, 0.16);
}

.sr-slide-branch-card.is-blue { border-left: 4px solid #0284c7; }
.sr-slide-branch-card.is-emerald { border-left: 4px solid #10b981; }
.sr-slide-branch-card.is-rose { border-left: 4px solid #ef4444; }
.sr-slide-branch-card.is-slate { border-left: 4px solid #64748b; }

.sr-sb-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 8px;
}

.sr-sb-jump-hint {
  font-size: 11px;
  font-weight: 800;
  color: #38bdf8;
}

.sr-mindmap-modal.is-light .sr-sb-jump-hint {
  color: #0284c7;
}

.sr-sb-big-val {
  font-size: 18px;
  font-weight: 800;
  margin-bottom: 10px;
}

.sr-sb-big-val small {
  font-size: 12px;
  font-weight: 700;
  opacity: 0.85;
}

/* Rank Branch Items on Pillar Slides */
.sr-slide-rank-branch {
  background: #0f172a;
  border: 1px solid #1e293b;
  border-radius: 12px;
  padding: 11px 14px;
  cursor: pointer;
  transition: all 0.16s ease;
}

.sr-mindmap-modal.is-light .sr-slide-rank-branch {
  background: #f8fafc;
  border-color: #cbd5e1;
}

.sr-slide-rank-branch:hover {
  border-color: #0284c7;
  transform: translateY(-1px);
}

.sr-srb-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.sr-srb-title-group {
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
}

.sr-srb-name {
  font-size: 12.5px;
  font-weight: 800;
  display: block;
}

.sr-srb-sub {
  font-size: 11px;
  color: #94a3b8;
  margin-top: 2px;
}

.sr-mindmap-modal.is-light .sr-srb-sub {
  color: #475569;
}

.sr-srb-right {
  text-align: right;
  flex-shrink: 0;
}

.sr-srb-primary {
  display: block;
  font-size: 13.5px;
  font-weight: 800;
}

.sr-srb-secondary {
  font-size: 10.5px;
  color: #94a3b8;
}

.sr-mindmap-modal.is-light .sr-srb-secondary {
  color: #64748b;
}

/* Company PO Inspector inside Company Slide */
.sr-slide-branches-col.is-company-po-inspector {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.sr-slide-po-tabs {
  display: flex;
  align-items: center;
  gap: 8px;
  overflow-x: auto;
  padding-bottom: 4px;
}

.sr-slide-po-tab {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 7px 13px;
  border-radius: 10px;
  border: 1px solid #1e293b;
  background: #0f172a;
  color: #cbd5e1;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
}

.sr-mindmap-modal.is-light .sr-slide-po-tab {
  background: #f8fafc;
  border-color: #cbd5e1;
  color: #334155;
}

.sr-slide-po-tab.active {
  background: rgba(2, 132, 199, 0.18);
  border-color: #0284c7;
  color: #ffffff;
}

.sr-mindmap-modal.is-light .sr-slide-po-tab.active {
  background: #e0f2fe;
  border-color: #0284c7;
  color: #0369a1;
}

.sr-slide-active-po-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 11px 14px;
  border-radius: 12px;
  background: rgba(2, 132, 199, 0.1);
  border: 1px solid rgba(56, 189, 248, 0.28);
  flex-wrap: wrap;
}

.sr-mindmap-modal.is-light .sr-slide-active-po-banner {
  background: #f0f9ff;
  border-color: #bae6fd;
}

.sr-sapb-left {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
  min-width: 0;
  flex: 1;
}

.sr-sapb-contract {
  width: 100%;
  font-size: 13px;
  font-weight: 800;
  margin-top: 2px;
}

.sr-sapb-actions {
  display: flex;
  align-items: center;
  gap: 6px;
}

.sr-slide-po-4cards {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
}

.sr-slide-po-4cards .sr-mm-node.is-leaf-node,
.sr-slide-branches-col.is-2x2-branches .sr-mm-node.is-leaf-node {
  width: 100% !important;
}

/* Bottom Slide Player Bar */
.sr-slide-player-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 10px 22px;
  background: #0f172a;
  border-top: 1px solid #1e293b;
  flex-shrink: 0;
}

.sr-mindmap-modal.is-light .sr-slide-player-bar {
  background: #ffffff;
  border-top: 1px solid #cbd5e1;
}

.sr-spb-left,
.sr-spb-right {
  display: flex;
  align-items: center;
  gap: 8px;
}

.sr-spb-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 7px 14px;
  border-radius: 9px;
  border: 1px solid #334155;
  background: #1e293b;
  color: #f8fafc;
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
  transition: all 0.15s;
}

.sr-mindmap-modal.is-light .sr-spb-btn {
  background: #f1f5f9;
  border-color: #cbd5e1;
  color: #0f172a;
}

.sr-spb-btn:hover:not(:disabled) {
  background: #0284c7;
  border-color: #0284c7;
  color: #ffffff;
}

.sr-spb-btn:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.sr-spb-btn.is-next-primary {
  background: linear-gradient(135deg, #0284c7, #0369a1);
  border-color: #38bdf8;
  color: #ffffff !important;
}

.sr-spb-btn.is-autoplay.active {
  background: #10b981;
  border-color: #10b981;
  color: #ffffff !important;
}

.sr-spb-center {
  flex: 1;
  max-width: 420px;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.sr-spb-progress-info {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  font-size: 12px;
  color: #cbd5e1;
}

.sr-mindmap-modal.is-light .sr-spb-progress-info {
  color: #334155;
}

.sr-spb-progress-track {
  height: 6px;
  border-radius: 999px;
  background: rgba(148, 163, 184, 0.22);
  overflow: hidden;
}

.sr-spb-progress-fill {
  height: 100%;
  background: linear-gradient(90deg, #0284c7, #10b981);
  border-radius: 999px;
  transition: width 0.25s ease;
}

/* Slide Transitions */
.sr-slide-next-enter-active,
.sr-slide-next-leave-active,
.sr-slide-prev-enter-active,
.sr-slide-prev-leave-active {
  transition: all 0.22s cubic-bezier(0.22, 1, 0.36, 1);
}

.sr-slide-next-enter-from {
  opacity: 0;
  transform: translateX(28px);
}

.sr-slide-next-leave-to {
  opacity: 0;
  transform: translateX(-28px);
}

.sr-slide-prev-enter-from {
  opacity: 0;
  transform: translateX(-28px);
}

.sr-slide-prev-leave-to {
  opacity: 0;
  transform: translateX(28px);
}

@media (max-width: 1080px) {
  .sr-slide-stage-scroll {
    padding: 12px 10px 20px;
  }

  .sr-slide-card {
    padding: 14px 12px;
    border-radius: 14px;
    gap: 14px;
  }

  .sr-slide-main-title {
    font-size: 16px;
  }

  .sr-slide-hero-kpi {
    width: 100%;
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
  }

  .sr-slide-hk-val {
    font-size: 17px;
  }

  .sr-slide-mindmap-grid {
    grid-template-columns: 1fr;
    gap: 14px;
  }

  .sr-slide-hub-col::after {
    display: none;
  }

  .sr-slide-branches-col {
    padding-left: 10px;
    border-left-width: 2px;
  }

  .sr-slide-branches-col.is-2x2-branches,
  .sr-slide-branches-col.is-list-branches,
  .sr-slide-po-4cards {
    grid-template-columns: 1fr;
  }

  .sr-slide-player-bar {
    padding: 8px 10px;
    gap: 8px;
  }

  .sr-spb-btn {
    padding: 7px 10px;
    font-size: 11.5px;
  }
}

/* ─── GUIDED MINDMAP PRESENTATION (TRÌNH CHIẾU SƠ ĐỒ NGANG / DỌC KIỂU SLIDE TUTORIAL) ─── */
.sr-mindmap-present-btn {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 6.5px 14px;
  border-radius: 9px;
  border: 1px solid #38bdf8;
  background: linear-gradient(135deg, #0284c7 0%, #0369a1 100%);
  color: #ffffff;
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
  box-shadow: 0 4px 14px rgba(2, 132, 199, 0.32);
  transition: all 0.18s ease;
}

.sr-mindmap-present-btn:hover {
  transform: translateY(-1px);
  box-shadow: 0 6px 18px rgba(2, 132, 199, 0.45);
  filter: brightness(1.06);
}

.sr-mindmap-present-btn.is-active {
  background: linear-gradient(135deg, #e11d48 0%, #be123c 100%);
  border-color: #fb7185;
  box-shadow: 0 4px 14px rgba(225, 29, 72, 0.35);
}

.sr-mindmap-canvas-viewport.is-tour-mode {
  overflow: hidden;
}

/* Floating Step Tutorial Banner at Top of Canvas */
.sr-tour-step-banner {
  position: absolute;
  top: 12px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 25;
  width: min(860px, calc(100% - 120px));
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 10px 16px;
  border-radius: 14px;
  background: rgba(15, 23, 42, 0.92);
  backdrop-filter: blur(12px);
  border: 1.5px solid rgba(56, 189, 248, 0.5);
  box-shadow: 0 14px 34px rgba(0, 0, 0, 0.52);
  color: #f8fafc;
}

.sr-mindmap-modal.is-light .sr-tour-step-banner {
  background: rgba(255, 255, 255, 0.95);
  border-color: #0284c7;
  color: #0f172a;
  box-shadow: 0 10px 28px rgba(15, 23, 42, 0.14);
}

.sr-tour-step-banner.is-theme-emerald {
  border-color: rgba(16, 185, 129, 0.6);
}

.sr-tour-step-banner.is-theme-rose {
  border-color: rgba(244, 63, 94, 0.6);
}

.sr-tour-step-banner.is-theme-slate {
  border-color: rgba(148, 163, 184, 0.55);
}

.sr-tsb-left {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  flex: 1;
}

.sr-tsb-step-pill {
  padding: 4px 10px;
  border-radius: 999px;
  background: linear-gradient(135deg, #0284c7, #0369a1);
  color: #ffffff;
  font-size: 11px;
  font-weight: 800;
  white-space: nowrap;
  flex-shrink: 0;
}

.sr-tsb-stage-tag {
  padding: 3.5px 9px;
  border-radius: 7px;
  background: rgba(56, 189, 248, 0.16);
  border: 1px solid rgba(56, 189, 248, 0.35);
  color: #38bdf8;
  font-size: 10.5px;
  font-weight: 800;
  white-space: nowrap;
  flex-shrink: 0;
}

.sr-mindmap-modal.is-light .sr-tsb-stage-tag {
  background: #e0f2fe;
  border-color: #7dd3fc;
  color: #0369a1;
}

.sr-tsb-texts {
  min-width: 0;
  flex: 1;
}

.sr-tsb-title {
  font-size: 13.5px;
  font-weight: 800;
  line-height: 1.25;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.sr-tsb-sub {
  font-size: 11.5px;
  color: #94a3b8;
  margin-top: 2px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

