  color: #475569;
}

.sr-tsb-right {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.sr-tsb-focus-btn {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  padding: 6px 11px;
  border-radius: 8px;
  border: 1px solid rgba(56, 189, 248, 0.38);
  background: rgba(2, 132, 199, 0.16);
  color: #38bdf8;
  font-size: 11.5px;
  font-weight: 800;
  cursor: pointer;
  transition: all 0.15s;
}

.sr-mindmap-modal.is-light .sr-tsb-focus-btn {
  background: #f0f9ff;
  border-color: #7dd3fc;
  color: #0284c7;
}

.sr-tsb-focus-btn:hover {
  background: #0284c7;
  border-color: #0284c7;
  color: #ffffff;
}

/* Spotlight, Context & Dimmed States on Mindmap Nodes during Tour */
.sr-mm-tree.is-tour-active .sr-mm-node {
  transition: opacity 0.32s ease, filter 0.32s ease, transform 0.32s ease, box-shadow 0.32s ease, border-color 0.32s ease;
}

.sr-mm-tree.is-tour-active .sr-mm-node.is-tour-spotlight {
  opacity: 1 !important;
  filter: none !important;
  border-color: #38bdf8 !important;
  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.45), 0 18px 42px rgba(2, 132, 199, 0.42) !important;
  z-index: 5;
}

.sr-mindmap-modal.is-light .sr-mm-tree.is-tour-active .sr-mm-node.is-tour-spotlight {
  border-color: #0284c7 !important;
  box-shadow: 0 0 0 3px rgba(2, 132, 199, 0.32), 0 16px 36px rgba(2, 132, 199, 0.22) !important;
}

.sr-mm-tree.is-tour-active .sr-mm-node.is-tour-context {
  opacity: 0.72;
  filter: saturate(0.85);
}

.sr-mm-tree.is-tour-active .sr-mm-node.is-tour-dimmed {
  opacity: 0.24;
  filter: grayscale(0.45) brightness(0.82);
}

.sr-mindmap-modal.is-light .sr-mm-tree.is-tour-active .sr-mm-node.is-tour-dimmed {
  opacity: 0.32;
  filter: grayscale(0.45);
}

.sr-spb-btn.is-exit-tour {
  border-color: rgba(244, 63, 94, 0.45);
  color: #fda4af;
}

.sr-mindmap-modal.is-light .sr-spb-btn.is-exit-tour {
  border-color: #fecdd3;
  background: #fff1f2;
  color: #e11d48;
}

.sr-spb-btn.is-exit-tour:hover {
  background: #e11d48 !important;
  border-color: #e11d48 !important;
  color: #ffffff !important;
}

@media (max-width: 1080px) {
  .sr-tour-step-banner {
    width: calc(100% - 20px);
    padding: 8px 11px;
  }
  .sr-tsb-stage-tag {
    display: none;
  }
}


