@media (max-width: 768px) {
  .sr-mm-lbl-pc {
    display: none !important;
  }

  .sr-mm-lbl-mob {
    display: inline !important;
  }

  .sr-mindmap-search-cluster {
    flex: 0 0 auto;
  }

  .sr-mindmap-filter-toggle-btn {
    padding: 5px 9px;
    font-size: 11.5px;
  }

  .sr-mindmap-mode-pill {
    padding: 5px 8px;
    font-size: 11px;
  }

  .sr-mindmap-filter-bar {
    flex-direction: column;
    align-items: stretch;
    gap: 6px;
    padding: 8px 10px;
  }

  .sr-mmf-mob-search-row {
    display: flex;
    align-items: center;
    gap: 6px;
    width: 100%;
  }

  .sr-mindmap-search-box.is-mob-filter-search {
    flex: 1;
    min-width: 0;
    max-width: none;
    padding: 4px 9px;
  }

  .sr-mmf-time-row {
    width: 100%;
    justify-content: space-between;
  }

  .sr-mmf-seg {
    flex: 1;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
  }

  .sr-mmf-seg-btn {
    text-align: center;
    padding: 4px 4px;
  }

  .sr-mmf-period-ctrl {
    width: 100%;
    justify-content: space-between;
  }

  .sr-mmf-period-ctrl .sr-mmf-input,
  .sr-mmf-period-ctrl .sr-mmf-select {
    flex: 1;
    min-width: 0;
  }

  .sr-mmf-compact-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 6px;
    width: 100%;
  }

  .sr-mmf-pill {
    max-width: none;
    width: 100%;
  }

  .sr-mmf-mob-tools {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 6px;
    width: 100%;
  }

  .sr-mmf-mob-tools .sr-mindmap-seg-group {
    width: auto;
    display: inline-flex;
    flex: 1;
  }

  .sr-mmf-mob-tools .sr-mindmap-seg-btn {
    flex: 1;
    padding: 4px 6px;
    font-size: 11px;
    justify-content: center;
  }

  .sr-mmf-mob-branch-btns {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    flex-shrink: 0;
  }

  .sr-mmf-mob-branch-btns .sr-mindmap-tool-btn {
    padding: 4px 8px;
    font-size: 11px;
  }
}

