  width: min(1180px, calc(100vw - 32px));
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 10px 16px;
  border-radius: 14px;
  background: rgba(15, 23, 42, 0.96);
