  gap: 6px;
  padding: 7px 12px;
  border-radius: 9px;
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
  border: 1px solid transparent;
  white-space: nowrap;
}
.sr-ccd-btn.is-clone {
  background: rgba(2, 132, 199, 0.18);
  color: #38bdf8;
  border-color: rgba(56, 189, 248, 0.45);
}
.sr-ccd-btn.is-mindmap {
  background: rgba(16, 185, 129, 0.18);
  color: #34d399;
  border-color: rgba(52, 211, 153, 0.45);
}
.sr-ccd-btn.is-primary {
  background: linear-gradient(135deg, #d97706 0%, #b45309 100%);
  color: #ffffff;
  border-color: #fbbf24;
}
.sr-ccd-btn.is-clear {
  background: rgba(239, 68, 68, 0.14);
  color: #f87171;
  border-color: rgba(239, 68, 68, 0.35);
}

/* Multi-Draft Comparison Matrix Modal */
.sr-craft-compare-modal {
  width: min(1460px, 96vw);
  height: min(90vh, 920px);
  display: flex;
  flex-direction: column;
  border-radius: 16px;
  background: #0f172a;
  border: 1px solid rgba(148, 163, 184, 0.28);
  box-shadow: 0 26px 70px rgba(0, 0, 0, 0.65);
  overflow: hidden;
  color: #f8fafc;
}
.sr-craft-compare-modal.is-light {
  background: #ffffff;
  border-color: #cbd5e1;
  color: #0f172a;
}
.sr-ccm-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 14px 20px;
  background: rgba(15, 23, 42, 0.95);
  border-bottom: 1px solid rgba(148, 163, 184, 0.2);
  flex-wrap: wrap;
}
.sr-craft-compare-modal.is-light .sr-ccm-header {
  background: #f8fafc;
  border-bottom-color: #e2e8f0;
}
.sr-ccm-header-left {
  display: flex;
  align-items: center;
  gap: 12px;
}
.sr-ccm-icon {
  width: 38px;
  height: 38px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(245, 158, 11, 0.18);
  color: #fbbf24;
  border: 1px solid rgba(245, 158, 11, 0.4);
}
.sr-ccm-title-row {
  display: flex;
  align-items: center;
  gap: 10px;
}
.sr-ccm-title {
  margin: 0;
  font-size: 16px;
  font-weight: 800;
}
.sr-ccm-count-pill {
  padding: 2px 9px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
  background: rgba(245, 158, 11, 0.2);
  color: #fbbf24;
  border: 1px solid rgba(245, 158, 11, 0.45);
}
.sr-ccm-sub {
  margin: 3px 0 0;
  font-size: 12px;
  color: #94a3b8;
}
.sr-ccm-header-right {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}
.sr-ccm-seg {
  display: inline-flex;
  padding: 2px;
  border-radius: 8px;
  background: rgba(30, 41, 59, 0.9);
  border: 1px solid rgba(148, 163, 184, 0.24);
}
.sr-craft-compare-modal.is-light .sr-ccm-seg {
  background: #e2e8f0;
  border-color: #cbd5e1;
}
.sr-ccm-seg-btn {
  padding: 5px 10px;
  border-radius: 6px;
  border: none;
  background: transparent;
  color: #94a3b8;
  font-size: 11.5px;
  font-weight: 700;
  cursor: pointer;
}
.sr-craft-compare-modal.is-light .sr-ccm-seg-btn {
  color: #475569;
}
.sr-ccm-seg-btn.active {
  background: #0284c7;
  color: #ffffff;
}
.sr-ccm-tool-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 11px;
  border-radius: 8px;
  border: 1px solid rgba(148, 163, 184, 0.3);
  background: rgba(30, 41, 59, 0.8);
  color: #e2e8f0;
  font-size: 11.5px;
  font-weight: 700;
  cursor: pointer;
}
.sr-craft-compare-modal.is-light .sr-ccm-tool-btn {
  background: #ffffff;
  color: #334155;
  border-color: #cbd5e1;
}
.sr-ccm-tool-btn.active {
  background: #d97706;
  border-color: #fbbf24;
  color: #ffffff;
}
.sr-ccm-tool-btn.is-clone {
  background: rgba(2, 132, 199, 0.2);
  border-color: rgba(56, 189, 248, 0.45);
  color: #38bdf8;
}
.sr-ccm-tool-btn.is-mindmap {
  background: linear-gradient(135deg, #059669 0%, #047857 100%);
  border-color: #34d399;
  color: #ffffff;
}
.sr-ccm-close {
  width: 34px;
  height: 34px;
  border-radius: 8px;
  border: 1px solid rgba(148, 163, 184, 0.25);
  background: transparent;
  color: inherit;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.sr-ccm-highlights {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
  padding: 12px 20px;
  background: rgba(30, 41, 59, 0.45);
  border-bottom: 1px solid rgba(148, 163, 184, 0.16);
}
.sr-craft-compare-modal.is-light .sr-ccm-highlights {
  background: #f8fafc;
  border-bottom-color: #e2e8f0;
}
.sr-ccm-hl-card {
  padding: 10px 14px;
  border-radius: 10px;
  border: 1px solid rgba(148, 163, 184, 0.22);
  background: rgba(15, 23, 42, 0.65);
}
.sr-craft-compare-modal.is-light .sr-ccm-hl-card {
  background: #ffffff;
  border-color: #cbd5e1;
}
.sr-ccm-hl-card.is-emerald {
  border-color: rgba(16, 185, 129, 0.45);
}
.sr-ccm-hl-card.is-blue {
  border-color: rgba(56, 189, 248, 0.45);
}
.sr-ccm-hl-card.is-amber {
  border-color: rgba(245, 158, 11, 0.45);
}
.sr-ccm-hl-badge {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.04em;
  color: #94a3b8;
  margin-bottom: 4px;
}
.sr-ccm-hl-main {
  display: flex;
  align-items: baseline;
  gap: 8px;
  flex-wrap: wrap;
  font-size: 13px;
}
.sr-ccm-hl-val.is-emerald {
  color: #34d399;
  font-weight: 800;
  font-size: 15px;
}
.sr-ccm-hl-val.is-blue {
  color: #38bdf8;
  font-weight: 800;
  font-size: 15px;
}
.sr-ccm-hl-val.is-amber {
  color: #fbbf24;
  font-weight: 800;
  font-size: 15px;
}
.sr-ccm-hl-pct {
  font-size: 11.5px;
  color: #94a3b8;
}
.sr-ccm-hl-sub {
  margin-top: 3px;
  font-size: 11px;
  color: #94a3b8;
}

.sr-ccm-side-clear-btn {
  padding: 2px 7px;
  border-radius: 5px;
  border: 1px solid rgba(239, 68, 68, 0.35);
  background: rgba(239, 68, 68, 0.12);
  color: #f87171;
  font-size: 10.5px;
  font-weight: 700;
  cursor: pointer;
  transition: all 0.15s ease;
}
.sr-ccm-side-clear-btn:hover {
  background: rgba(239, 68, 68, 0.22);
}

.sr-ccm-po-picker-list {
  display: flex;
  flex-direction: column;
  gap: 5px;
  max-height: 230px;
  overflow-y: auto;
  padding-right: 2px;
}
.sr-ccm-po-pick-item {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 7px 9px;
  border-radius: 8px;
  border: 1px solid rgba(148, 163, 184, 0.18);
  background: rgba(15, 23, 42, 0.45);
  color: inherit;
  text-align: left;
  cursor: pointer;
  transition: all 0.15s ease;
}
.sr-analytics-modal.is-light .sr-ccm-po-pick-item {
  background: #ffffff;
  border-color: #cbd5e1;
}
.sr-ccm-po-pick-item:hover {
  border-color: rgba(56, 189, 248, 0.45);
}
.sr-ccm-po-pick-item.active {
  border-color: rgba(56, 189, 248, 0.7);
  background: rgba(2, 132, 199, 0.14);
}
.sr-analytics-modal.is-light .sr-ccm-po-pick-item.active {
  background: #f0f9ff;
  border-color: #0284c7;
}
.sr-ccm-po-pick-check {
  width: 15px;
  height: 15px;
  border-radius: 4px;
  border: 1.5px solid rgba(148, 163, 184, 0.5);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  margin-top: 1px;
  color: #ffffff;
}
.sr-ccm-po-pick-item.active .sr-ccm-po-pick-check {
  background: #0284c7;
  border-color: #38bdf8;
}
.sr-ccm-po-pick-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  flex: 1;
}
.sr-ccm-po-pick-title {
  font-size: 11.5px;
  font-weight: 700;
  line-height: 1.25;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.sr-ccm-po-pick-sub {
  font-size: 10px;
  color: #94a3b8;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.sr-ccm-po-picker-empty {
  font-size: 11px;
  color: #94a3b8;
  padding: 8px 4px;
}

.sr-ccm-empty-pick-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 8px;
  width: 100%;
  max-width: 720px;
  margin-top: 12px;
  text-align: left;
}

.sr-ccm-chart-workspace {
  padding: 14px 20px 18px;
  border-bottom: 1px solid rgba(148, 163, 184, 0.22);
  background: rgba(15, 23, 42, 0.55);
}
.sr-craft-compare-modal.is-light .sr-ccm-chart-workspace {
  background: #f8fafc;
  border-bottom-color: #e2e8f0;
}
.sr-ccm-chart-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 12px;
}
.sr-ccm-chart-metrics {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}
.sr-ccm-metric-chip {
  padding: 5px 11px;
  border-radius: 8px;
  font-size: 11.5px;
  font-weight: 700;
  cursor: pointer;
}
.sr-ccm-metric-chip.is-triple {
  border: 1px solid rgba(245, 158, 11, 0.45);
  background: rgba(245, 158, 11, 0.14);
  color: #fbbf24;
}
.sr-ccm-metric-chip.is-triple.active {
  background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%);
  border-color: #fcd34d;
  color: #ffffff;
}
.sr-craft-compare-modal.is-light .sr-ccm-metric-chip.is-triple {
  background: #fffbeb;
  border-color: #f59e0b;
  color: #b45309;
}
.sr-craft-compare-modal.is-light .sr-ccm-metric-chip.is-triple.active {
  background: linear-gradient(135deg, #f59e0b 0%, #d97706 100%);
  color: #ffffff;
}
.sr-ccm-chart-sort {
  display: flex;
  align-items: center;
  gap: 6px;
}
.sr-ccm-charts-row {
  margin-bottom: 0;
}
.sr-analytics-table-card.is-matrix-full-card {
  padding: 10px 12px;
  gap: 6px;
}
.sr-analytics-table-scroll.is-matrix-full-scroll {
  max-height: none !important;
  height: auto !important;
  overflow-y: visible !important;
  overflow-x: auto;
}
.sr-ccm-table {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  font-size: 12.5px;
  color: #f1f5f9;
  background: #0f172a;
}
.sr-analytics-modal.is-light .sr-ccm-table {
  color: #0f172a;
  background: #ffffff;
}
.sr-ccm-table th,
.sr-ccm-table td {
  padding: 7px 14px;
  border-bottom: 1px solid rgba(148, 163, 184, 0.22);
  border-right: 1px solid rgba(148, 163, 184, 0.18);
  vertical-align: middle;
  background: #0f172a;
  transition: background-color 0.14s ease;
}
.sr-analytics-modal.is-light .sr-ccm-table th,
.sr-analytics-modal.is-light .sr-ccm-table td {
  border-bottom-color: #e2e8f0;
  border-right-color: #e2e8f0;
  background: #ffffff;
}
.sr-ccm-table tbody tr:hover td {
  background: #172338;
}
.sr-analytics-modal.is-light .sr-ccm-table tbody tr:hover td {
  background: #f8fafc;
}
.sr-ccm-table thead th {
  position: sticky;
  top: 0;
  z-index: 5;
  background: #1e293b;
  border-bottom: 2px solid rgba(148, 163, 184, 0.35);
}
.sr-analytics-modal.is-light .sr-ccm-table thead th {
  background: #f1f5f9;
  border-bottom: 2px solid #cbd5e1;
}
.sr-ccm-sticky-col {
  position: sticky;
  left: 0;
  z-index: 4;
  background: #0f172a;
  min-width: 245px;
  max-width: 275px;
  border-right: 2px solid rgba(148, 163, 184, 0.32) !important;
}
.sr-analytics-modal.is-light .sr-ccm-sticky-col {
  background: #ffffff;
  border-right: 2px solid #cbd5e1 !important;
}
.sr-ccm-table thead th.sr-ccm-sticky-col {
  z-index: 6;
  background: #1e293b;
}
.sr-analytics-modal.is-light .sr-ccm-table thead th.sr-ccm-sticky-col {
  background: #f1f5f9;
}

.sr-ccm-corner-head {
  display: flex;
  flex-direction: column;
  gap: 3px;
  text-align: left;
}
.sr-ccm-corner-head span {
  font-size: 11.5px;
  font-weight: 800;
  letter-spacing: 0.04em;
  color: #f8fafc;
}
.sr-analytics-modal.is-light .sr-ccm-corner-head span {
  color: #0f172a;
}
.sr-ccm-corner-head small {
  font-size: 10.5px;
  font-weight: 600;
  color: #94a3b8;
}
.sr-analytics-modal.is-light .sr-ccm-corner-head small {
  color: #475569;
}

.sr-ccm-option-th {
  min-width: 255px;
  text-align: left;
}
.sr-ccm-option-th.is-best-overall {
  background: #112d28 !important;
  border-bottom-color: #10b981 !important;
}
.sr-analytics-modal.is-light .sr-ccm-option-th.is-best-overall {
  background: #ecfdf5 !important;
  border-bottom-color: #10b981 !important;
}
.sr-ccm-opt-head {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.sr-ccm-opt-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
}
.sr-ccm-opt-num {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.03em;
  padding: 2px 7px;
  border-radius: 5px;
  background: rgba(245, 158, 11, 0.22);
  border: 1px solid rgba(245, 158, 11, 0.45);
  color: #fcd34d;
}
.sr-analytics-modal.is-light .sr-ccm-opt-num {
  background: #fef3c7;
  border-color: #f59e0b;
  color: #b45309;
}
.sr-ccm-opt-crown {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.03em;
  padding: 2px 7px;
  border-radius: 5px;
  background: rgba(16, 185, 129, 0.24);
  border: 1px solid rgba(16, 185, 129, 0.5);
  color: #34d399;
}
.sr-analytics-modal.is-light .sr-ccm-opt-crown {
  background: #d1fae5;
  border-color: #10b981;
  color: #047857;
}
.sr-ccm-opt-rm {
  width: 20px;
  height: 20px;
  border-radius: 5px;
  border: 1px solid transparent;
  background: transparent;
  color: #94a3b8;
  font-size: 15px;
  line-height: 1;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.sr-ccm-opt-rm:hover {
  background: rgba(239, 68, 68, 0.16);
  color: #ef4444;
}
.sr-ccm-opt-po {
  font-size: 13px;
  font-weight: 800;
  line-height: 1.35;
  color: #f8fafc;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  word-break: break-word;
}
.sr-analytics-modal.is-light .sr-ccm-opt-po {
  color: #0f172a;
}
.sr-ccm-opt-cust {
  font-size: 11px;
  font-weight: 500;
  color: #94a3b8;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.sr-analytics-modal.is-light .sr-ccm-opt-cust {
  color: #475569;
}

.sr-ccm-opt-actions {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 4px;
  flex-wrap: wrap;
}
.sr-ccm-act-btn {
  padding: 5px 10px;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  border: 1px solid rgba(148, 163, 184, 0.35);
  background: #1e293b;
  color: #f1f5f9;
  transition: all 0.15s ease;
}
.sr-ccm-act-btn:hover {
  border-color: #38bdf8;
  color: #38bdf8;
}
.sr-analytics-modal.is-light .sr-ccm-act-btn {
  background: #ffffff;
  color: #1e293b;
  border-color: #cbd5e1;
}
.sr-analytics-modal.is-light .sr-ccm-act-btn:hover {
  background: #f0f9ff;
  border-color: #0284c7;
  color: #0284c7;
}
.sr-ccm-act-btn.is-chot {
  background: linear-gradient(135deg, #059669 0%, #047857 100%) !important;
  border-color: #10b981 !important;
  color: #ffffff !important;
}
.sr-ccm-act-btn.is-chot:hover {
  filter: brightness(1.08);
}

.sr-ccm-section-banner .sr-ccm-section-td {
  padding: 5px 14px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  background: #162235 !important;
  color: #e2e8f0;
  border-top: 1px solid rgba(148, 163, 184, 0.3);
  border-bottom: 1px solid rgba(148, 163, 184, 0.3);
}
.sr-ccm-section-banner.is-sec-rev .sr-ccm-section-td {
  background: #0c243d !important;
  color: #38bdf8;
}
.sr-ccm-section-banner.is-sec-com .sr-ccm-section-td {
  background: #291f0c !important;
  color: #fbbf24;
}
.sr-ccm-section-banner.is-sec-profit .sr-ccm-section-td {
  background: #0b2922 !important;
  color: #34d399;
}
.sr-analytics-modal.is-light .sr-ccm-section-banner .sr-ccm-section-td {
  background: #f1f5f9 !important;
  color: #1e293b;
  border-top-color: #cbd5e1;
  border-bottom-color: #cbd5e1;
}
.sr-analytics-modal.is-light .sr-ccm-section-banner.is-sec-rev .sr-ccm-section-td {
  background: #e0f2fe !important;
  color: #0369a1;
}
.sr-analytics-modal.is-light .sr-ccm-section-banner.is-sec-com .sr-ccm-section-td {
  background: #fef3c7 !important;
  color: #b45309;
}
.sr-analytics-modal.is-light .sr-ccm-section-banner.is-sec-profit .sr-ccm-section-td {
  background: #d1fae5 !important;
  color: #047857;
}
.sr-ccm-sec-dot {
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  margin-right: 7px;
  vertical-align: middle;
  background: #64748b;
}
.sr-ccm-sec-dot.is-rev { background: #0284c7; }
.sr-ccm-sec-dot.is-com { background: #f59e0b; }
.sr-ccm-sec-dot.is-profit { background: #10b981; }

.sr-ccm-m-label {
  display: flex;
  align-items: center;
  gap: 8px;
}
.sr-ccm-m-label strong {
  color: #f1f5f9;
  font-weight: 700;
  font-size: 12.5px;
}
.sr-analytics-modal.is-light .sr-ccm-m-label strong {
  color: #1e293b;
}
.sr-ccm-m-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #64748b;
  flex-shrink: 0;
}
.sr-ccm-m-dot.is-rev { background: #0284c7; }
.sr-ccm-m-dot.is-cost { background: #f59e0b; }
.sr-ccm-m-dot.is-com { background: #f59e0b; }
.sr-ccm-m-dot.is-profit { background: #10b981; }
.sr-ccm-m-dot.is-ratio { background: #0284c7; }

.sr-ccm-table tr.is-highlight-row td {
  background: #132036;
}
.sr-ccm-table tr.is-highlight-row .sr-ccm-m-label strong {
  font-weight: 800;
  color: #ffffff;
}
.sr-analytics-modal.is-light .sr-ccm-table tr.is-highlight-row td {
  background: #f8fafc;
}
.sr-analytics-modal.is-light .sr-ccm-table tr.is-highlight-row .sr-ccm-m-label strong {
  font-weight: 800;
  color: #0f172a;
}

.sr-ccm-table tr.is-active-chart-metric td {
  background: #122b47 !important;
}
.sr-analytics-modal.is-light .sr-ccm-table tr.is-active-chart-metric td {
  background: #e0f2fe !important;
}

.sr-ccm-val-td.is-best-cell {
  background: rgba(16, 185, 129, 0.14) !important;
}
.sr-analytics-modal.is-light .sr-ccm-val-td.is-best-cell {
  background: #ecfdf5 !important;
}

.sr-ccm-cell-main {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}
.sr-ccm-cell-main.is-right-aligned {
  justify-content: flex-end;
}
.sr-ccm-cell-val {
  font-weight: 700;
  font-size: 13.5px;
  font-variant-numeric: tabular-nums;
  color: #f8fafc;
}
.sr-analytics-modal.is-light .sr-ccm-cell-val {
  color: #0f172a;
}
.sr-ccm-cell-val.is-best-val {
  font-weight: 800;
  color: #34d399;
}
.sr-analytics-modal.is-light .sr-ccm-cell-val.is-best-val {
  color: #047857;
}
.sr-ccm-cell-val.is-neg-val {
  color: #f87171;
}
.sr-analytics-modal.is-light .sr-ccm-cell-val.is-neg-val {
  color: #dc2626;
}
.sr-ccm-cell-pct {
  font-size: 11px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: #38bdf8;
  white-space: nowrap;
}
.sr-analytics-modal.is-light .sr-ccm-cell-pct {
  color: #0284c7;
}

.sr-ccm-delta-row {
  margin-top: 2px;
}
.sr-ccm-delta-row.is-right-aligned {
  text-align: right;
}
.sr-ccm-delta-text {
  font-size: 11px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.sr-ccm-delta-text.is-good {
  color: #34d399;
}
.sr-analytics-modal.is-light .sr-ccm-delta-text.is-good {
  color: #047857;
}
.sr-ccm-delta-text.is-bad {
  color: #f87171;
}
.sr-analytics-modal.is-light .sr-ccm-delta-text.is-bad {
  color: #dc2626;
}
.sr-ccm-delta-text.is-flat,
.sr-ccm-delta-text.is-neutral {
  color: #94a3b8;
}
.sr-analytics-modal.is-light .sr-ccm-delta-text.is-flat,
.sr-analytics-modal.is-light .sr-ccm-delta-text.is-neutral {
  color: #64748b;
}
.sr-ccm-opt-actions.is-right-aligned {
  justify-content: flex-end;
  margin-top: 0;
}
.sr-ccm-footer-actions-row td {
  background: #162235 !important;
  border-top: 2px solid rgba(148, 163, 184, 0.32);
  padding: 8px 14px;
}
.sr-analytics-modal.is-light .sr-ccm-footer-actions-row td {
  background: #f1f5f9 !important;
  border-top: 2px solid #cbd5e1;
}

@keyframes sr-promoted-outline-blink {
  0%, 100% {
    outline-color: #10b981;
    outline-offset: 2px;
  }
  50% {
    outline-color: #f59e0b;
    outline-offset: 5px;
  }
}

@keyframes sr-promoted-overlay-flash {
  0%, 100% {
    opacity: 0.92;
    border-color: #10b981;
    background: rgba(16, 185, 129, 0.22);
    box-shadow:
      inset 0 0 32px rgba(16, 185, 129, 0.48),
      0 0 28px rgba(16, 185, 129, 0.55);
  }
  50% {
    opacity: 0.18;
    border-color: #f59e0b;
    background: rgba(245, 158, 11, 0.08);
    box-shadow:
      inset 0 0 10px rgba(245, 158, 11, 0.2),
      0 0 12px rgba(245, 158, 11, 0.25);
  }
}

.sr-record-card.sr-po1-card.is-promoted-highlight-card,
.sr-page.theme-light-blue .sr-record-card.sr-po1-card.is-promoted-highlight-card {
  position: relative !important;
  z-index: 12 !important;
  outline: 3.5px solid #10b981 !important;
  outline-offset: 2px;
  animation: sr-promoted-outline-blink 0.75s ease-in-out infinite !important;
}

.sr-record-card.sr-po1-card.is-promoted-highlight-card::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: 12px;
  border: 3px solid #10b981;
  pointer-events: none;
  z-index: 25;
  animation: sr-promoted-overlay-flash 0.75s ease-in-out infinite;
}

.sr-md-company-card.is-promoted-company-card {
  outline: 2.5px solid #10b981 !important;
  outline-offset: 1px;
  animation: sr-promoted-outline-blink 0.75s ease-in-out infinite !important;
}

/* ─── MODAL LOADING PROGRESS KHI TẢI & ĐỒNG BỘ CACHE HÀNG HÓA (HANG_HOA) ─── */
.sr-goods-db-loading-overlay {
  position: fixed;
  inset: 0;
  z-index: 100080;
  background: rgba(2, 6, 23, 0.74);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.sr-goods-db-loading-overlay.is-light {
  background: rgba(15, 23, 42, 0.48);
}

.sr-goods-db-loading-card {
  width: min(520px, calc(100vw - 28px));
  background: linear-gradient(180deg, #0f172a 0%, #09111e 100%);
  border: 1.5px solid rgba(52, 211, 153, 0.42);
  border-radius: 18px;
  padding: 20px 22px;
  box-shadow:
    0 24px 60px -12px rgba(0, 0, 0, 0.75),
    0 0 0 1px rgba(16, 185, 129, 0.16);
  color: #f8fafc;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.sr-goods-db-loading-overlay.is-light .sr-goods-db-loading-card {
  background: #ffffff;
  border-color: #38bdf8;
  color: #0f172a;
  box-shadow: 0 22px 54px -12px rgba(2, 132, 199, 0.28);
}

.sr-gdl-head {
  display: flex;
  align-items: center;
  gap: 12px;
}

.sr-gdl-icon-ring {
  width: 44px;
  height: 44px;
  border-radius: 12px;
  background: rgba(16, 185, 129, 0.16);
  border: 1px solid rgba(52, 211, 153, 0.42);
  color: #34d399;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.sr-goods-db-loading-overlay.is-light .sr-gdl-icon-ring {
  background: #e0f2fe;
  border-color: #7dd3fc;
  color: #0284c7;
}

.sr-gdl-spin {
  animation: srGdlPulse 1.4s ease-in-out infinite;
}

@keyframes srGdlPulse {
  0%, 100% {
    transform: translateY(0) scale(1);
    opacity: 0.92;
  }
  50% {
    transform: translateY(-2px) scale(1.08);
    opacity: 1;
  }
}

.sr-gdl-title-wrap {
  flex: 1;
  min-width: 0;
}

.sr-gdl-eyebrow {
  display: block;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.06em;
  color: #34d399;
  margin-bottom: 2px;
}

.sr-goods-db-loading-overlay.is-light .sr-gdl-eyebrow {
  color: #0284c7;
}

.sr-gdl-title {
  margin: 0;
  font-size: 14.5px;
  font-weight: 800;
  line-height: 1.3;
  color: inherit;
}

.sr-gdl-pct-badge {
  padding: 5px 10px;
  border-radius: 999px;
  background: rgba(16, 185, 129, 0.2);
  border: 1px solid rgba(52, 211, 153, 0.45);
  color: #34d399;
  font-size: 13px;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  flex-shrink: 0;
}

.sr-goods-db-loading-overlay.is-light .sr-gdl-pct-badge {
  background: #e0f2fe;
  border-color: #38bdf8;
  color: #0369a1;
}

.sr-gdl-progress-track {
  width: 100%;
  height: 10px;
  border-radius: 999px;
  background: rgba(30, 41, 59, 0.9);
  border: 1px solid rgba(148, 163, 184, 0.22);
  overflow: hidden;
}

.sr-goods-db-loading-overlay.is-light .sr-gdl-progress-track {
  background: #e2e8f0;
  border-color: #cbd5e1;
}

.sr-gdl-progress-fill {
  height: 100%;
  border-radius: 999px;
  background: linear-gradient(90deg, #10b981 0%, #34d399 50%, #38bdf8 100%);
  transition: width 0.18s cubic-bezier(0.22, 1, 0.36, 1);
}

.sr-goods-db-loading-overlay.is-light .sr-gdl-progress-fill {
  background: linear-gradient(90deg, #0284c7 0%, #0ea5e9 55%, #10b981 100%);
}

.sr-gdl-meta-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  font-size: 12px;
  color: #94a3b8;
}

.sr-goods-db-loading-overlay.is-light .sr-gdl-meta-row {
  color: #475569;
}

.sr-gdl-detail {
  flex: 1;
  min-width: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.sr-gdl-counter {
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}

.sr-gdl-counter strong {
  color: #34d399;
}

.sr-goods-db-loading-overlay.is-light .sr-gdl-counter strong {
  color: #0284c7;
}

.sr-gdl-cache-note {
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 8px 11px;
  border-radius: 10px;
  background: rgba(16, 185, 129, 0.1);
  border: 1px solid rgba(52, 211, 153, 0.24);
  color: #a7f3d0;
  font-size: 11.5px;
  font-weight: 600;
}

.sr-goods-db-loading-overlay.is-light .sr-gdl-cache-note {
  background: #f0f9ff;
  border-color: #bae6fd;
  color: #0369a1;
}

/* Đồng bộ chuyển động mượt của Thanh Compare Dock & Bảng So Sánh Bản Tạm trên Mobile */
@media (max-width: 768px) {
  .sr-page.is-mobile-shell .sr-company-top-toolbar .sr-hdr-action-btn.is-compare-craft {
    display: inline-flex !important;
  }

  .sr-craft-compare-overlay {
    padding: 0 !important;
  }

  .sr-craft-compare-modal {
    width: 100vw !important;
    max-width: 100vw !important;
    height: 100dvh !important;
    max-height: 100dvh !important;
    border-radius: 0 !important;
  }

  .sr-ccm-header {
    padding: max(calc(env(safe-area-inset-top, 0px) + 8px), 48px) 12px 10px !important;
    gap: 8px !important;
  }

  .sr-ccm-sub {
    display: none;
  }

  .sr-ccm-highlights {
    display: flex;
    overflow-x: auto;
    gap: 8px;
    padding: 8px 12px;
  }

  .sr-ccm-hl-card {
    min-width: 220px;
    flex-shrink: 0;
  }

  .sr-ccm-sticky-col {
    min-width: 145px;
    max-width: 165px;
  }

  .sr-craft-compare-dock {
    left: 10px;
    right: 10px;
    width: auto;
    bottom: calc(136px + env(safe-area-inset-bottom, 0px));
    transform: none;
    padding: 8px 10px;
    gap: 8px;
    flex-direction: column;
    align-items: stretch;
    transition:
      bottom 0.38s cubic-bezier(0.22, 1, 0.36, 1),
      transform 0.38s cubic-bezier(0.22, 1, 0.36, 1),
      opacity 0.24s ease;
  }

  :global(body:has(.app-layout.mobile-nav-hidden) .sr-craft-compare-dock) {
    bottom: calc(72px + env(safe-area-inset-bottom, 0px)) !important;
  }
}

/* =========================================================================
   NHÃN THỜI GIAN CHUYỂN TRANG SAU KHI ĐỌC XONG + MOBILE DOCK & BOTTOM SHEET
   + FIX MODAL PO MOBILE (CHỐNG AUTO-ZOOM & KÉO NGANG)
   ========================================================================= */
.sr-mindmap-timer-lbl,
.sr-spb-timer-lbl {
  font-size: 11px;
  font-weight: 600;
  color: #cbd5e1;
  white-space: nowrap;
  padding-left: 4px;
  padding-right: 2px;
}

.sr-mindmap-modal.is-light .sr-mindmap-timer-lbl,
.sr-mindmap-modal.is-light .sr-spb-timer-lbl {
  color: #475569;
}

/* Mặc định trên PC ẩn Mobile Dock & Mobile Bottom Sheet */
.sr-mindmap-mobile-dock,
.sr-mm-sheet-backdrop {
  display: none;
}

@media (max-width: 768px) {
  /* -----------------------------------------------------------------------
     1. FIX MODAL PO (.sr-po-modal) TRÊN MOBILE:
        - Chống tự động Zoom In / Zoom Out khi chạm vào ô nhập liệu (font-size >= 16px)
        - Khoá hoàn toàn kéo qua kéo lại phương ngang (overflow-x: hidden, touch-action: pan-y)
     ----------------------------------------------------------------------- */
  .sr-modal-overlay:has(.sr-po-modal) {
    padding: 0 !important;
    overflow-x: hidden !important;
    max-width: 100vw !important;
    touch-action: pan-y;
  }

  .sr-po-modal {
    width: 100vw !important;
    max-width: 100vw !important;
    height: 100dvh !important;
    max-height: 100dvh !important;
    margin: 0 !important;
    border-radius: 0 !important;
    overflow-x: hidden !important;
    overscroll-behavior-x: none !important;
    touch-action: pan-y;
  }

  .sr-po-modal,
  .sr-po-modal .sr-po-modal-header,
  .sr-po-modal .sr-po-body-split,
  .sr-po-modal .sr-po-left-sidebar,
  .sr-po-modal .sr-po-right-pane,
  .sr-po-modal .sr-po-section-block,
  .sr-po-modal .sr-po-overview-grid,
  .sr-po-modal .sr-po-overview-card,
  .sr-po-modal .sr-po-goods-toolbar,
  .sr-po-modal .sr-po-modal-footer {
    max-width: 100% !important;
    min-width: 0 !important;
    box-sizing: border-box !important;
    overflow-x: hidden !important;
  }

  /* Ngăn iOS Safari / Chrome Mobile tự động phóng to (auto-zoom) khi focus vào input/select/textarea */
  .sr-po-modal input:not([type="checkbox"]):not([type="radio"]),
  .sr-po-modal select,
  .sr-po-modal textarea,
  .sr-mindmap-modal input:not([type="checkbox"]):not([type="radio"]),
  .sr-mindmap-modal select,
  .sr-mindmap-modal textarea {
    font-size: 16px !important;
  }

  /* Thanh công cụ bảng hàng hoá và chân trang Modal PO tự xuống dòng gọn gàng, không tràn ngang */
  .sr-po-modal .sr-po-goods-toolbar,
  .sr-po-modal .sr-po-goods-toolbar-left,
  .sr-po-modal .sr-po-goods-toolbar-right {
    flex-wrap: wrap !important;
    width: 100% !important;
    min-width: 0 !important;
    gap: 6px !important;
  }

  .sr-po-modal .sr-po-modal-footer {
    flex-direction: column !important;
    align-items: stretch !important;
    gap: 6px !important;
    padding: 8px 10px calc(8px + env(safe-area-inset-bottom, 0px)) !important;
  }

  .sr-po-modal .sr-po-footer-right {
    display: none !important;
  }

  .sr-po-modal .sr-po-btn-lbl-dt {
    display: none !important;
  }

  .sr-po-modal .sr-po-btn-lbl-mob {
    display: inline !important;
  }

  .sr-po-modal .sr-po-btn-cancel.is-mob-inline-close {
    display: inline-flex !important;
  }

  .sr-po-modal .sr-po-footer-left,
  .sr-po-modal .sr-po-footer-center {
    display: flex !important;
    flex-wrap: nowrap !important;
    width: 100% !important;
    min-width: 0 !important;
    justify-content: stretch !important;
    gap: 6px !important;
  }

  .sr-po-modal .sr-po-footer-left > *,
  .sr-po-modal .sr-po-footer-center > * {
    flex: 1 1 0% !important;
    min-width: 0 !important;
    justify-content: center !important;
    text-align: center !important;
    padding: 0 8px !important;
    font-size: 11.5px !important;
    height: 35px !important;
    white-space: nowrap !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
  }

  .sr-po-modal .sr-po-footer-center > * {
    height: 38px !important;
    font-size: 12px !important;
    font-weight: 800 !important;
  }

  /* Chỉ riêng bảng chi tiết mặt hàng cho phép cuộn ngang nội bộ trong khung bảng */
  .sr-po-modal .sr-po-table-wrap,
  .sr-po-modal .sr-po-items-table-wrap {
    max-width: 100% !important;
    overflow-x: auto !important;
    -webkit-overflow-scrolling: touch;
  }

  /* -----------------------------------------------------------------------
     2. MODAL REVIEW KINH DOANH (.sr-mindmap-modal) TRÊN MOBILE:
        - Ẩn thanh công cụ trên, thanh mục lục bước, và bỏ bottom player modal cũ
        - Thay bằng Thanh Dock 4 nút dưới đáy (Chế độ, Bộ lọc, Đọc, Slide) + Bottom Sheet
     ----------------------------------------------------------------------- */
  .sr-mindmap-modal .sr-mindmap-toolbar,
  .sr-mindmap-modal .sr-mindmap-filter-bar,
  .sr-mindmap-modal .sr-slide-chapter-bar,
  .sr-mindmap-modal .sr-slide-player-bar,
  .sr-mindmap-modal .sr-tour-step-banner {
    display: none !important;
  }

  .sr-mindmap-modal .sr-mindmap-body {
    padding-bottom: calc(64px + env(safe-area-inset-bottom, 0px)) !important;
  }

  .sr-mindmap-modal .sr-mindmap-hud {
    bottom: 14px !important;
    right: 12px !important;
  }

  /* Thanh Bottom Dock cố định ở đáy Modal Review Kinh Doanh trên Mobile */
  .sr-mindmap-mobile-dock {
    position: absolute;
    left: 0;
    right: 0;
    bottom: 0;
    z-index: 60;
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 6px;
    padding: 7px 10px calc(7px + env(safe-area-inset-bottom, 0px));
    background: rgba(15, 23, 42, 0.96);
    border-top: 1px solid rgba(148, 163, 184, 0.22);
    backdrop-filter: blur(14px);
    box-shadow: 0 -8px 24px rgba(2, 6, 23, 0.45);
  }

  .sr-mindmap-modal.is-light .sr-mindmap-mobile-dock {
    background: rgba(255, 255, 255, 0.97);
    border-top-color: #cbd5e1;
    box-shadow: 0 -6px 20px rgba(15, 23, 42, 0.08);
  }

  .sr-mm-dock-btn {
    position: relative;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 2px;
    min-height: 50px;
    padding: 5px 4px;
    border-radius: 11px;
    border: 1px solid transparent;
    background: transparent;
    color: #94a3b8;
    cursor: pointer;
    transition: all 0.18s ease;
  }

  .sr-mindmap-modal.is-light .sr-mm-dock-btn {
    color: #475569;
  }

  .sr-mm-dock-btn.active {
    background: rgba(59, 130, 246, 0.18);
    border-color: rgba(96, 165, 250, 0.45);
    color: #60a5fa;
  }

  .sr-mindmap-modal.is-light .sr-mm-dock-btn.active {
    background: #eff6ff;
    border-color: #93c5fd;
    color: #1d4ed8;
  }

  .sr-mm-dock-btn.is-running {
    background: rgba(16, 185, 129, 0.16);
    border-color: rgba(52, 211, 153, 0.45);
    color: #34d399;
  }

  .sr-mindmap-modal.is-light .sr-mm-dock-btn.is-running {
    background: #ecfdf5;
    border-color: #6ee7b7;
    color: #047857;
  }

  .sr-mm-dock-icon-wrap {
    position: relative;
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }

  .sr-mm-dock-badge {
    position: absolute;
    top: -5px;
    right: -10px;
    min-width: 15px;
    height: 15px;
    padding: 0 4px;
    border-radius: 999px;
    background: #3b82f6;
    color: #ffffff;
    font-size: 9.5px;
    font-weight: 800;
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }

  .sr-mm-dock-lbl {
    font-size: 11.5px;
    font-weight: 700;
    line-height: 1.15;
    color: inherit;
  }

  .sr-mm-dock-sub {
    font-size: 9.5px;
    font-weight: 600;
    opacity: 0.78;
    line-height: 1.1;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    max-width: 100%;
  }

  /* Bottom Sheet Overlay & Sheet Container */
  .sr-mm-sheet-backdrop {
    position: absolute;
    inset: 0;
    bottom: calc(64px + env(safe-area-inset-bottom, 0px));
    z-index: 55;
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    background: rgba(2, 6, 23, 0.52);
    backdrop-filter: blur(3px);
    animation: srMmFadeIn 0.18s ease-out;
  }

  .sr-mm-bottom-sheet {
    width: 100%;
    max-height: 78%;
    display: flex;
    flex-direction: column;
    background: #0f172a;
    border-top: 1px solid rgba(148, 163, 184, 0.28);
    border-radius: 18px 18px 0 0;
    box-shadow: 0 -14px 36px rgba(2, 6, 23, 0.65);
    overflow: hidden;
    animation: srMmSheetUp 0.22s cubic-bezier(0.22, 1, 0.36, 1);
  }

  .sr-mindmap-modal.is-light .sr-mm-bottom-sheet {
    background: #ffffff;
    border-top-color: #cbd5e1;
    box-shadow: 0 -12px 32px rgba(15, 23, 42, 0.16);
  }

  .sr-mm-sheet-handle-bar {
    display: flex;
    justify-content: center;
    padding: 8px 0 4px;
    cursor: pointer;
  }

  .sr-mm-sheet-grabber {
    width: 38px;
    height: 4px;
    border-radius: 999px;
    background: rgba(148, 163, 184, 0.45);
  }

  .sr-mm-sheet-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    padding: 6px 14px 10px;
    border-bottom: 1px solid rgba(148, 163, 184, 0.16);
  }

  .sr-mindmap-modal.is-light .sr-mm-sheet-header {
    border-bottom-color: #e2e8f0;
  }

  .sr-mm-sheet-title-wrap {
    display: flex;
    align-items: center;
    gap: 7px;
    color: #f8fafc;
  }

  .sr-mindmap-modal.is-light .sr-mm-sheet-title-wrap {
    color: #0f172a;
  }

  .sr-mm-sheet-title-wrap h4 {
    margin: 0;
    font-size: 14px;
    font-weight: 800;
  }

  .sr-mm-sheet-header-actions {
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .sr-mm-sheet-reset-btn {
    height: 28px;
    padding: 0 10px;
    border-radius: 7px;
    border: 1px solid rgba(248, 113, 113, 0.4);
    background: rgba(239, 68, 68, 0.14);
    color: #fca5a5;
    font-size: 11.5px;
    font-weight: 700;
  }

  .sr-mindmap-modal.is-light .sr-mm-sheet-reset-btn {
    background: #fef2f2;
    border-color: #fecaca;
    color: #dc2626;
  }

  .sr-mm-sheet-close {
    width: 28px;
    height: 28px;
    border-radius: 8px;
    border: 1px solid rgba(148, 163, 184, 0.25);
    background: rgba(30, 41, 59, 0.7);
    color: #cbd5e1;
    font-size: 13px;
    font-weight: 700;
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }

  .sr-mindmap-modal.is-light .sr-mm-sheet-close {
    background: #f1f5f9;
    border-color: #cbd5e1;
    color: #334155;
  }

  .sr-mm-sheet-body {
    padding: 12px 14px 16px;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    gap: 12px;
  }

  .sr-mm-sheet-section {
    display: flex;
    flex-direction: column;
    gap: 6px;
  }

  .sr-mm-sheet-label {
    font-size: 11px;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: #94a3b8;
  }

  .sr-mindmap-modal.is-light .sr-mm-sheet-label {
    color: #64748b;
  }

  .sr-mm-sheet-grid-3 {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 8px;
  }

  .sr-mm-sheet-grid-2 {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
  }

  .sr-mm-sheet-choice {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 6px;
    padding: 10px 8px;
    border-radius: 10px;
    border: 1px solid rgba(148, 163, 184, 0.24);
    background: rgba(30, 41, 59, 0.72);
    color: #e2e8f0;
    font-size: 12px;
    font-weight: 700;
    text-align: center;
  }

  .sr-mindmap-modal.is-light .sr-mm-sheet-choice {
    background: #f8fafc;
    border-color: #cbd5e1;
    color: #1e293b;
  }

  .sr-mm-sheet-choice.active {
    background: rgba(37, 99, 235, 0.22);
    border-color: #3b82f6;
    color: #60a5fa;
  }

  .sr-mindmap-modal.is-light .sr-mm-sheet-choice.active {
    background: #eff6ff;
    border-color: #2563eb;
    color: #1d4ed8;
  }

  .sr-mm-sheet-action-row {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
  }

  .sr-mm-sheet-action-btn {
    flex: 1 1 calc(50% - 4px);
    min-height: 36px;
    padding: 6px 10px;
    border-radius: 9px;
    border: 1px solid rgba(148, 163, 184, 0.24);
    background: rgba(30, 41, 59, 0.65);
    color: #e2e8f0;
    font-size: 12px;
    font-weight: 600;
  }

  .sr-mindmap-modal.is-light .sr-mm-sheet-action-btn {
    background: #f8fafc;
    border-color: #cbd5e1;
    color: #1e293b;
  }

  .sr-mm-sheet-action-btn.is-accent {
    border-color: rgba(59, 130, 246, 0.5);
    color: #60a5fa;
  }

  .sr-mindmap-search-box.is-sheet-search {
    width: 100%;
    height: 38px;
  }

  .sr-mmf-compact-grid.is-sheet-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 8px;
  }

  .sr-mm-sheet-primary-btn {
    width: 100%;
    min-height: 40px;
    padding: 8px 14px;
    border-radius: 10px;
    border: 1px solid #2563eb;
    background: linear-gradient(135deg, #2563eb, #1d4ed8);
    color: #ffffff;
    font-size: 13px;
    font-weight: 700;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
  }

  .sr-mm-sheet-primary-btn.is-voice {
    border-color: #059669;
    background: linear-gradient(135deg, #10b981, #059669);
  }

  .sr-mm-sheet-active-controls {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
  }

  .sr-mm-sheet-ctrl-btn {
    flex: 1 1 auto;
    min-height: 36px;
    padding: 6px 10px;
    border-radius: 9px;
    border: 1px solid rgba(148, 163, 184, 0.28);
    background: rgba(30, 41, 59, 0.8);
    color: #f8fafc;
    font-size: 12px;
    font-weight: 700;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
  }

  .sr-mindmap-modal.is-light .sr-mm-sheet-ctrl-btn {
    background: #f1f5f9;
    border-color: #cbd5e1;
    color: #0f172a;
  }

  .sr-mm-sheet-ctrl-btn.is-play.is-playing {
    background: rgba(16, 185, 129, 0.2);
    border-color: #10b981;
    color: #34d399;
  }

  .sr-mindmap-modal.is-light .sr-mm-sheet-ctrl-btn.is-play.is-playing {
    background: #ecfdf5;
    border-color: #10b981;
    color: #047857;
  }

  .sr-mm-sheet-ctrl-btn.is-danger {
    background: rgba(239, 68, 68, 0.16);
    border-color: rgba(248, 113, 113, 0.45);
    color: #fca5a5;
  }

  .sr-mindmap-modal.is-light .sr-mm-sheet-ctrl-btn.is-danger {
    background: #fef2f2;
    border-color: #fca5a5;
    color: #dc2626;
  }

  .sr-mm-sheet-setting-card {
    display: flex;
    flex-direction: column;
    gap: 10px;
    padding: 10px 12px;
    border-radius: 11px;
    border: 1px solid rgba(148, 163, 184, 0.2);
    background: rgba(30, 41, 59, 0.55);
  }

  .sr-mindmap-modal.is-light .sr-mm-sheet-setting-card {
    background: #f8fafc;
    border-color: #e2e8f0;
  }

  .sr-mm-sheet-setting-row {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
  }

  .sr-mm-sheet-setting-lbl {
    font-size: 12.5px;
    font-weight: 700;
    color: #e2e8f0;
    line-height: 1.3;
  }

  .sr-mindmap-modal.is-light .sr-mm-sheet-setting-lbl {
    color: #1e293b;
  }

  .sr-mindmap-voice-rate.is-sheet-rate {
    height: 32px;
    padding: 0 8px;
    border-radius: 8px;
  }

  .sr-mm-sheet-step-box {
    padding: 10px 12px;
    border-radius: 11px;
    border: 1px solid rgba(59, 130, 246, 0.32);
    background: rgba(30, 58, 138, 0.22);
    display: flex;
    flex-direction: column;
    gap: 5px;
  }

  .sr-mindmap-modal.is-light .sr-mm-sheet-step-box {
    background: #eff6ff;
    border-color: #bfdbfe;
  }

  .sr-mm-sheet-step-top {
    display: flex;
    align-items: center;
    gap: 6px;
  }

  .sr-mm-sheet-step-badge {
    font-size: 10px;
    font-weight: 800;
    padding: 2px 7px;
    border-radius: 999px;
    background: #2563eb;
    color: #ffffff;
  }

  .sr-mm-sheet-step-stage {
    font-size: 11px;
    font-weight: 700;
    color: #93c5fd;
  }

  .sr-mindmap-modal.is-light .sr-mm-sheet-step-stage {
    color: #1d4ed8;
  }

  .sr-mm-sheet-step-title {
    font-size: 13px;
    font-weight: 800;
    color: #f8fafc;
  }

  .sr-mindmap-modal.is-light .sr-mm-sheet-step-title {
    color: #0f172a;
  }

  .sr-mm-sheet-step-sub {
    font-size: 11.5px;
    color: #cbd5e1;
    line-height: 1.35;
  }

  .sr-mindmap-modal.is-light .sr-mm-sheet-step-sub {
    color: #475569;
  }

  .sr-mm-sheet-step-nav {
    display: flex;
    gap: 8px;
    margin-top: 4px;
  }

  .sr-mm-sheet-nav-btn {
    flex: 1;
    height: 32px;
    border-radius: 8px;
    border: 1px solid rgba(148, 163, 184, 0.28);
    background: rgba(15, 23, 42, 0.7);
    color: #e2e8f0;
    font-size: 12px;
    font-weight: 700;
  }

  .sr-mindmap-modal.is-light .sr-mm-sheet-nav-btn {
    background: #ffffff;
    border-color: #cbd5e1;
    color: #1e293b;
  }

  .sr-mm-sheet-nav-btn.is-primary {
    background: #2563eb;
    border-color: #2563eb;
    color: #ffffff;
  }

  .sr-mm-sheet-nav-btn:disabled {
    opacity: 0.45;
  }

  .sr-mm-sheet-steps-list {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 6px;
    max-height: 165px;
    overflow-y: auto;
  }

  .sr-mm-sheet-step-item {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 7px 8px;
    border-radius: 8px;
    border: 1px solid rgba(148, 163, 184, 0.22);
    background: rgba(30, 41, 59, 0.6);
    color: #cbd5e1;
    font-size: 11.5px;
    font-weight: 600;
    text-align: left;
  }

  .sr-mindmap-modal.is-light .sr-mm-sheet-step-item {
    background: #f8fafc;
    border-color: #e2e8f0;
    color: #334155;
  }

  .sr-mm-sheet-step-item.active {
    border-color: #3b82f6;
    background: rgba(37, 99, 235, 0.22);
    color: #60a5fa;
  }

  .sr-mindmap-modal.is-light .sr-mm-sheet-step-item.active {
    border-color: #2563eb;
    background: #eff6ff;
    color: #1d4ed8;
  }

  .sr-mm-sheet-step-num {
    width: 18px;
    height: 18px;
    border-radius: 999px;
    background: rgba(148, 163, 184, 0.22);
    font-size: 10px;
    font-weight: 800;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
  }

  .sr-mm-sheet-step-name {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  @keyframes srMmSheetUp {
    from {
      transform: translateY(100%);
    }
    to {
      transform: translateY(0);
    }
  }

  @keyframes srMmFadeIn {
    from {
      opacity: 0;
    }
    to {
      opacity: 1;
    }
  }
}

/* ═══════════════════════════════════════════════════════════════════════════
   ĐỒNG BỘ PHÂN TÁCH MÀU THEO CHẾ ĐỘ (BẢN CHÍNH THỨC ↔ BẢN TẠM) & GIAO DIỆN (LIGHT ↔ DARK)
   - Light Mode: Bản Chính Thức = Xanh Dương (Ocean Blue) | Bản Tạm = Xanh Lá Cây (Emerald Green)
   - Dark Mode : Bản Chính Thức = Xanh Lá Cây (Dark Emerald) | Bản Tạm = Xanh Dương (Dark Ocean Blue)
   ═══════════════════════════════════════════════════════════════════════════ */

/* 1A. LIGHT MODE — BẢN CHÍNH THỨC (XANH DƯƠNG) */
.sr-page.theme-light-blue .sr-mode-switch-btn.is-official.active,
.sr-page.theme-light-blue .sr-ctt-mode-btn.is-official.active {
  background: linear-gradient(135deg, #0284c7 0%, #2563eb 100%) !important;
  border-color: #38bdf8 !important;
  color: #ffffff !important;
  box-shadow: 0 2px 8px rgba(2, 132, 199, 0.28) !important;
}

.sr-page.theme-light-blue .sr-mode-switch-btn.is-official .sr-mode-dot.is-emerald,
.sr-page.theme-light-blue .sr-ctt-mode-btn.is-official .sr-mode-dot.is-emerald {
  background: #38bdf8 !important;
}

.sr-page.theme-light-blue .sr-mode-switch-btn.is-official.active .sr-mode-dot.is-emerald,
.sr-page.theme-light-blue .sr-ctt-mode-btn.is-official.active .sr-mode-dot.is-emerald {
  background: #bae6fd !important;
}

/* 1B. LIGHT MODE — BẢN TẠM / PHƯƠNG ÁN (XANH LÁ CÂY - EMERALD GREEN) */
.sr-page.theme-light-blue .sr-mode-switch-btn.is-craft .sr-mode-dot.is-amber,
.sr-page.theme-light-blue .sr-ctt-mode-btn.is-craft .sr-mode-dot.is-amber {
  background: #10b981 !important;
}

.sr-page.theme-light-blue .sr-mode-switch-btn.is-craft.active .sr-mode-dot.is-amber,
.sr-page.theme-light-blue .sr-ctt-mode-btn.is-craft.active .sr-mode-dot.is-amber {
  background: #a7f3d0 !important;
}

.sr-page.theme-light-blue .sr-mode-switch-btn.is-craft.active,
.sr-page.theme-light-blue .sr-ctt-mode-btn.is-craft.active {
  background: linear-gradient(135deg, #059669 0%, #10b981 100%) !important;
  border-color: #34d399 !important;
  color: #ffffff !important;
  box-shadow: 0 2px 8px rgba(5, 150, 105, 0.28) !important;
}

.sr-page.theme-light-blue.mode-craft .bg-count-pill.is-craft-pill {
  background: #d1fae5 !important;
  color: #065f46 !important;
  border-color: #10b981 !important;
}

/* Card Công ty cột trái & Khung Danh sách công ty ở Light Mode - Bản Tạm */
.sr-page.theme-light-blue.mode-craft .sr-md-sidebar {
  background: #ffffff !important;
  border-color: #6ee7b7 !important;
  box-shadow: 0 10px 28px -8px rgba(5, 150, 105, 0.14) !important;
}

.sr-page.theme-light-blue.mode-craft .sr-md-sidebar-head {
  background: linear-gradient(135deg, #059669 0%, #10b981 58%, #047857 100%) !important;
  border-bottom-color: #34d399 !important;
}

.sr-page.theme-light-blue.mode-craft .sr-md-sh-plain-count {
  color: #d1fae5 !important;
}

.sr-page.theme-light-blue.mode-craft .sr-sb-head-btn:hover:not(:disabled),
.sr-page.theme-light-blue.mode-craft .sr-sb-head-btn.is-filter-toggle.active {
  background: #ffffff !important;
  border-color: #ffffff !important;
  color: #059669 !important;
}

.sr-page.theme-light-blue.mode-craft .sr-sidebar-search-shell {
  border-color: #6ee7b7 !important;
}

.sr-page.theme-light-blue.mode-craft .sr-sidebar-filter-panel {
  background: #f0fdf4 !important;
  border-color: #6ee7b7 !important;
}

.sr-page.theme-light-blue.mode-craft .sr-md-company-card {
  border-color: #a7f3d0 !important;
}

.sr-page.theme-light-blue.mode-craft .sr-md-company-card:hover {
  background: #ecfdf5 !important;
  border-color: #10b981 !important;
}

.sr-page.theme-light-blue.mode-craft .sr-md-company-card.active {
  background: linear-gradient(135deg, #a7f3d0 0%, #d1fae5 100%) !important;
  border: 2px solid #059669 !important;
  box-shadow: inset 4px 0 0 #059669, 0 6px 16px -4px rgba(5, 150, 105, 0.24) !important;
}

.sr-page.theme-light-blue.mode-craft .sr-md-company-card .sr-md-cc-code-plain,
.sr-page.theme-light-blue.mode-craft .sr-md-company-card.active .sr-md-cc-code-plain {
  color: #047857 !important;
}

.sr-page.theme-light-blue.mode-craft .sr-md-company-card.active .sr-md-cc-metrics-4col {
  border-top-color: #6ee7b7 !important;
}

.sr-page.theme-light-blue.mode-craft .sr-md-cc-check.selected {
  background: #059669 !important;
  border-color: #059669 !important;
}

/* Thư mục Công ty (Folder Header & Body Sheet) ở Light Mode - Bản Tạm */
.sr-page.theme-light-blue.mode-craft .sr-folder-top-bar {
  border-bottom: 3px solid #059669 !important;
}

.sr-page.theme-light-blue.mode-craft .sr-folder-ear-tab,
.sr-page.theme-light-blue.mode-craft.is-mobile-shell .sr-folder-ear-tab,
.sr-page.theme-light-blue.mode-craft.is-mobile-shell.m-tab-overview .sr-folder-ear-tab {
  background: linear-gradient(135deg, #059669 0%, #10b981 58%, #047857 100%) !important;
  border-color: #34d399 !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.35), 0 -4px 14px -4px rgba(5, 150, 105, 0.25) !important;
}

.sr-page.theme-light-blue.mode-craft .sr-folder-icon {
  color: #d1fae5 !important;
}

.sr-page.theme-light-blue.mode-craft .sr-customer-kpi-sheet.sr-folder-body-sheet,
.sr-page.theme-light-blue.mode-craft.is-mobile-shell .sr-customer-kpi-sheet.sr-folder-body-sheet,
.sr-page.theme-light-blue.mode-craft.is-mobile-shell.m-tab-overview .sr-customer-kpi-sheet.sr-folder-body-sheet {
  background: #f0fdf4 !important;
  border-color: #6ee7b7 !important;
  border-top: 3px solid #059669 !important;
  box-shadow: 0 8px 20px -6px rgba(5, 150, 105, 0.14) !important;
}

.sr-page.theme-light-blue.mode-craft .sr-plain-text-btn {
  background: rgba(255, 255, 255, 0.94) !important;
  border-color: #6ee7b7 !important;
  color: #047857 !important;
}

.sr-page.theme-light-blue.mode-craft .sr-plain-text-btn:hover:not(:disabled) {
  background: #059669 !important;
  border-color: #047857 !important;
  color: #ffffff !important;
}

/* Card PO (.sr-po1-card) ở Light Mode - Bản Tạm */
.sr-page.theme-light-blue.mode-craft .sr-record-card.sr-po1-card {
  background: #ffffff !important;
  border: 2px solid #059669 !important;
  box-shadow: 0 8px 22px -6px rgba(5, 150, 105, 0.2) !important;
}

.sr-page.theme-light-blue.mode-craft .sr-record-card.sr-po1-card:hover {
  border-color: #047857 !important;
  box-shadow: 0 12px 26px -6px rgba(5, 150, 105, 0.28) !important;
}

.sr-page.theme-light-blue.mode-craft .sr-record-card.sr-po1-card.is-selected-card {
  border-color: #059669 !important;
  box-shadow: inset 4px 0 0 #059669 !important;
}

.sr-page.theme-light-blue.mode-craft .sr-po1-header {
  background: linear-gradient(90deg, #bbf7d0 0%, #d1fae5 55%, #ecfdf5 100%) !important;
  border-bottom: 1.5px solid #34d399 !important;
}

.sr-page.theme-light-blue.mode-craft .sr-po1-po-num {
  color: #047857 !important;
}

.sr-page.theme-light-blue.mode-craft .sr-po1-contract-row {
  border-top-color: #a7f3d0 !important;
}

.sr-page.theme-light-blue.mode-craft .sr-po1-contract-files {
  border-top-color: #6ee7b7 !important;
}

.sr-page.theme-light-blue.mode-craft .sr-craft-option-pill {
  background: #059669 !important;
  color: #ffffff !important;
  border-color: #047857 !important;
}


/* 2A. DARK MODE — BẢN CHÍNH THỨC (XANH LÁ CÂY - DARK EMERALD) */
.sr-page:not(.theme-light-blue):not(.mode-craft) .sr-md-company-card.active {
  background: linear-gradient(135deg, rgba(5, 150, 105, 0.36) 0%, rgba(6, 78, 59, 0.62) 100%) !important;
  border: 1.5px solid #10b981 !important;
  box-shadow: inset 4px 0 0 #10b981, 0 6px 16px -4px rgba(16, 185, 129, 0.32) !important;
}

.sr-page:not(.theme-light-blue):not(.mode-craft) .sr-md-company-card .sr-md-cc-code-plain {
  color: #34d399 !important;
}

.sr-page:not(.theme-light-blue):not(.mode-craft) .sr-record-card.sr-po1-card {
  background: rgba(8, 22, 18, 0.96) !important;
  border: 2px solid rgba(16, 185, 129, 0.62) !important;
  box-shadow: 0 8px 22px -8px rgba(0, 0, 0, 0.52) !important;
}

.sr-page:not(.theme-light-blue):not(.mode-craft) .sr-record-card.sr-po1-card:hover {
  border-color: #34d399 !important;
}

.sr-page:not(.theme-light-blue):not(.mode-craft) .sr-po1-header {
  background: linear-gradient(90deg, rgba(5, 150, 105, 0.44) 0%, rgba(13, 148, 136, 0.32) 52%, rgba(15, 23, 42, 0.94) 100%) !important;
  border-bottom: 1.5px solid rgba(52, 211, 153, 0.48) !important;
}

.sr-page:not(.theme-light-blue):not(.mode-craft) .sr-po1-po-num {
  color: #34d399 !important;
}


/* 2B. DARK MODE — BẢN TẠM / PHƯƠNG ÁN (XANH DƯƠNG - DARK OCEAN BLUE) */
.sr-page:not(.theme-light-blue) .sr-mode-switch-btn.is-craft .sr-mode-dot.is-amber,
.sr-page:not(.theme-light-blue) .sr-ctt-mode-btn.is-craft .sr-mode-dot.is-amber {
  background: #38bdf8 !important;
}

