/* 3. BỐ CỤC 3 KHỐI CHỈ SỐ Ở BẢN TẠM (KHI ĐÃ BỎ CỘT CÔNG NỢ) */
.sr-po1-4blocks.is-craft-3blocks {
  grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
}

.sr-card-list.is-cols-2 .sr-po1-4blocks.is-craft-3blocks {
  grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
}

